-- 自动生成：仅含中文译文与匹配指纹。来源见 SOURCES.md。
local D = LegionChineseDB
D.Strings[16842]="阿卡玛！你听到消息了吗？我被瓦丝琪的人跟踪了。我们的秘密就要暴露了！"
D.Strings[16843]="伊利丹必定会抓住我，那时候，他肯定会得知灰舌部队的秘密。这对他来说根本没有什么难度！不，我们只有一个办法。是我的愚蠢和疏忽导致了今天的局面，那么就让我进入灵魂的世界，结束这次危机。"
D.Strings[16844]="我已经下定了决心，不要再劝说我了。我把自己的生命都献给了我们的计划，如果现在前功尽弃，我们怎么能对得起那些为此牺牲的伙伴？"
D.Strings[16845]="谢谢你，阿卡玛。你让我感到了无上的荣耀，我感到自己的兄弟们就在身边。再会，朋友。好好指引我们的同胞。"
D.Strings[16846]="伊利丹正在搜捕我。我在这里非常危险，我们大家都非常危险。"
D.Strings[16847]="你感觉到了吗？"
D.Strings[16848]="过来，我们去看看！"
D.Strings[16849]="就在前面！"
D.Strings[16850]="哦，哇噻，他们正在从那个纳鲁身上抽取能量吗？好有趣啊……"
D.Strings[16851]="逛完了这座奇异的城市之后，也许你会有兴趣和我们一起来庆祝。春节庆典正在月光林地进行着，其它城市也都有前往庆典的传送点。过来和我们一起狂欢吧！"
D.Strings[16852]="哇喔，跑得真快！"
D.Strings[16853]="萨兰蒂亚似乎很迷惑，缓缓地走到了这个给她带来奇妙感觉的东西前。"
D.Strings[16854]="多尔南站在巨大的黑暗之门前，满怀敬畏地张大了嘴。"
D.Strings[16855]="你在这里干什么，$r？"
D.Strings[16856]="%s跪了下来，用月亮井的水装满了整个水瓶。"
D.Strings[16857]="药水已经完成了。我只希望克林塔尔能够原谅我们打断了他在翡翠梦境的逗留。"
D.Strings[16858]="萨兰蒂亚在看到扎拉多姆时，下巴几乎都要碰到地上了。"
D.Strings[16859]="哈哈，我喜欢！唔……发生了什么事？救救我！"
D.Strings[16860]="在这个世界上没有几个人有能力使用唤醒戒卫了，$n。我们很幸运，因为我就是其中之一。"
D.Strings[16861]="%s把药草和月亮井水混合在一起以制造唤醒戒卫。"
D.Strings[16862]="埃兰被打败了？啊……我能感觉到他的控制已经被解开了——虽然感觉很微弱。但是这足够让我继续履行看门人的工作了！你愿意被传送到守护者的图书馆吗，$n？"
D.Strings[16863]="请把我传送到守护者的图书馆去吧。"
D.Strings[16864]="这个女孩什么都没有做，而且她不应该为她在将来可能做的、或者没能做到的任何事情负任何责任。"
D.Strings[16865]="没事了，孩子。"
D.Strings[16866]="%s突然跪下，但他的心思似乎游离在别处。"
D.Strings[16867]="你在伊瑟拉的领域里干什么，入侵者？走开！你们在这里不受欢迎！"
D.Strings[16868]="%s站稳了脚跟，开始辨识周围的环境。"
D.Strings[16869]="%s和它的主人联系着，正试图建立灵魂的联接。"
D.Strings[16870]="多尔南在看到扎拉多姆时，下巴几乎都要碰到地上了。"
D.Strings[16871]="哇，他真是个大家伙啊！嗯……怎么回事？救救我！"
D.Strings[16872]="很高兴再次见到你，$c$n。多尔南一直在问起你。"
D.Strings[16873]="很高兴再次见到你，$c$n。萨兰蒂亚一直在问起你。"
D.Strings[16874]="外域的战争比起我所经历过的任何战争都惨烈。大部分悲惨的受害人都是那些留在后方的孩子。$B$B现在，斯克提斯的鸦人对沙塔斯城的威胁进一步加剧，那里也会有更多的孤儿需要照顾。这些孩子看不到光明的未来。$B$B但是你却有能力为他们做些什么。儿童周来了，$c，我恳求你给这些孩子的生活带来些乐趣和奇迹吧。"
D.Strings[16875]="他们还在追我，$r！快点，在我们被发现前告诉我，你来这里干什么！要是被他们抓住了，我们两个人都得死！"
D.Strings[16876]="%s渐渐变得昏昏欲睡。"
D.Strings[16877]="我必须回去休息了……他们肯定不会在这里找到我的……翡翠梦境……"
D.Strings[16878]="<这位德鲁伊似乎陷入了沉睡，全然忘却了他周围的环境。>"
D.Strings[16879]="试着叫醒克林塔尔。"
D.Strings[16880]="我求你了，$r，快一点。他们是不会放弃追踪的！就算是在这里，我也无法从他们手中逃脱！"
D.Strings[16881]="你……你不是他们的同党！快，在他们找到我们之前，得躲进某个隐密的地方！快点！"
D.Strings[16882]="退后点，$n。这可能是一个复仇军的陷阱。"
D.Strings[16883]="%s在复仇军牢房上使用复仇军监牢钥匙。"
D.Strings[16884]="你可以从暴风城维勒武器店的人类武器大师吴平、埃索达贸易阶梯的德莱尼武器大师韩迪尔或是铁炉堡密林武器店内的侏儒武器大师比克斯那里学会使用弩。"
D.Strings[16885]="指挥官……我在这个世界中的时间不多了……监狱……成百……上千……从其它世界来的生物……被……被复仇军关押在那里。他们大部分是我们的朋友。必须……必须拯救他们……现在……现在还来得及……"
D.Strings[16886]="你就是那个在我梦里出现过的人。"
D.Strings[16887]="那些笨蛋！他们都干了些什么！他们都监禁了一些什么恐怖的东西？又是什么目的？我仍然需要你的帮助，英雄。帮助我们。帮助你的人民。"
D.Strings[16888]="是的，我就是，孩子。还有你记得你在梦里展示给我的一切吗？"
D.Strings[16889]="居住在达纳苏斯战士区的暗夜精灵武器大师伊琳尼雅·月火可以教你使用弓。"
D.Strings[16890]="你的意思是，我也能在这里做吗？"
D.Strings[16891]="试试。"
D.Strings[16892]="太令人吃惊了，多尔南。真的太令人吃惊了！"
D.Strings[16893]="我成功了，我成功了！！！"
D.Strings[16894]="这家店里的比克斯可以教你使用匕首。如果你还想认识其他人的话，暴风城的吴平、埃索达的韩迪尔和达纳苏斯的伊琳尼雅·月火也都能教你。至于我，我一直不喜欢用匕首战斗。"
D.Strings[16895]="达纳苏斯战士区的武器大师伊琳尼雅·月火，或是铁炉堡密林武器店的矮人武器大师布里维夫，都能教你如何使用拳套。"
D.Strings[16896]="全神贯注片刻之后，多尔南召唤出了元素之力。"
D.Strings[16897]="能教你使用枪的是布里维夫，去铁炉堡的密林武器店找他吧。"
D.Strings[16898]="布里维夫会很高兴把他所知道的一切关于枪的知识都教给你的！"
D.Strings[16899]="我是按照节点亲王哈拉迈德的吩咐来这里的。奇怪的事情似乎正在风暴尖塔中酝酿着。"
D.Strings[16900]="我会想你的，$n！答应我你会经常回来看我。"
D.Strings[16901]="请重置棋盘，我们想再玩一次。"
D.Strings[16902]="一个阴暗而险恶的幽魂正在侵袭翡翠梦境。它的力量正迅速向我们的世界中蔓延，$n。我们必须对抗它，这也是我不能亲自陪伴你们作战的原因。"
D.Strings[16903]="我会带领你去圣物的位置，但你必须保护好我的灵魂。只有身为圣物守护者的我，才能破除净化之匣的封印。"
D.Strings[16904]="一个%s从翡翠梦境中侵入了现实世界！"
D.Strings[16905]="这是第一件圣物，不过还有两个。跟着我，$n。"
D.Strings[16906]="我已经拿到了第二件圣物。休息一会，然后我们继续去最后一个净化之匣那里。"
D.Strings[16907]="愚蠢的德鲁伊！精神与肉体的分离使你变得虚弱不堪，我的主人即将支配整个翡翠梦境，你的灵魂和你的身体将会在这里湮灭！"
D.Strings[16908]="%s把艾维娜圣物交给了梦境卫士鲁罗萨。"
D.Strings[16909]="翡翠梦境永远都不会属于你！"
D.Strings[16910]="矮人武器大师布里维夫能教你怎么使用单手斧和双手斧。你可以在铁炉堡的密林武器店找到他。"
D.Strings[16911]="据我所知没有比这里的布里维夫更出色的斧子专家了！单手斧，双手斧……他都是大师。"
D.Strings[16912]="我的朋友布里维夫能指示你怎么使用拳套……或者，如果你喜欢女性教师的话，达纳苏斯战士区的暗夜精灵武器大师伊琳尼雅·月火同样能教会你！"
D.Strings[16913]="那个勇敢的比克斯就能教你怎么使用弩。不过如果你在找其他训练师的话，可以去找达纳苏斯战士区的伊琳尼雅·月火，或者是埃索达内贸易阶梯的德莱尼人武器大韩迪尔。"
D.Strings[16914]="居住在达纳苏斯战士区的暗夜精灵武器大师伊琳尼雅·月火能指导你怎么使用弓。"
D.Strings[16915]="韩迪尔和布里维夫都能指导你怎么挥舞锤子，无论大小。你可以在铁炉堡的密林武器店内找到布里维夫，而韩迪尔则整天待在埃索达的贸易阶梯训练着德莱尼人。"
D.Strings[16916]="锤子是布里维夫的最拿手的武器！他就在这家店附近。如果你不喜欢他的训练方法，我听说埃索达的德莱尼的武器大师韩迪尔同样也知道怎么摆弄锤子！他就在贸易阶梯那里。"
D.Strings[16917]="吴平是长柄武器的大师。他一般在暴风城的维勒武器店训练学生。"
D.Strings[16918]="暴风城维勒武器店的武器大师吴平和达纳苏斯战士区的伊琳尼雅·月火都能教会你怎么使用法杖。"
D.Strings[16919]="联盟有两名使剑的大师：韩迪尔和吴平。你可以在埃索达的贸易阶梯找到前者，而后者可以在暴风城的维勒武器店找到。"
D.Strings[16920]="达纳苏斯战士区的伊琳尼雅·月火和铁炉堡密林武器店的比克斯都能指导你怎么适当地使用投掷武器。"
D.Strings[16921]="斧"
D.Strings[16922]="弓"
D.Strings[16923]="弩"
D.Strings[16924]="匕首"
D.Strings[16925]="拳套"
D.Strings[16926]="枪"
D.Strings[16927]="锤"
D.Strings[16928]="长柄武器"
D.Strings[16929]="法杖"
D.Strings[16930]="剑"
D.Strings[16931]="投掷武器"
D.Strings[16932]="这里的比克斯能教你怎么使用投掷武器。要是你去达纳苏斯更方便的话，也可以去找那里战士区的伊琳尼雅·月火学习。"
D.Strings[16933]="你会帮我吗，$n？"
D.Strings[16934]="如果你需要武器训练，我可以向你提供。"
D.Strings[16935]="啊，你希望去其他地方训练？我会指引你的。告诉我你对什么武器有兴趣。"
D.Strings[16936]="我们已经得到了全部三件圣物，不过我的能量正在迅速消失。我们必须立刻回到梦境卫士鲁罗萨那里去！他会告诉你接下来该怎么做。"
D.Strings[16937]="太可爱了！！！"
D.Strings[16938]="啊……你好啊，小宝贝！"
D.Strings[16939]="他们实在太小了。"
D.Strings[16940]="啊……"
D.Strings[16941]="鲁罗萨，我把艾维娜圣物委托给$n转交莫希斯·轻翼了。现在我必须彻底地回到翡翠梦境去了。不要让$n失败！"
D.Strings[16942]="唔……这东西闻起来很有趣。"
D.Strings[16943]="你的眼睛真大啊！"
D.Strings[16944]="我不记得曾经有这么小过。"
D.Strings[16945]="多可爱啊！"
D.Strings[16946]="哈纳什和塞尤克可以教会你如何使用单手斧和双手斧。你可以在奥格瑞玛的荣誉谷找到他们。"
D.Strings[16947]="奥格瑞玛荣誉谷内的武器大师塞尤克和哈纳什可以教你如何射箭，银月城远行者广场的武器大师伊蕾达同样也是这方面的专家。"
D.Strings[16948]="阿基巴德是用弩的大师。他是幽暗城的武器大师，就居住在军事区。"
D.Strings[16949]="你可以从三个武器大师那里寻求匕首的使用指导：幽暗城军事区的阿基巴德，奥格瑞玛荣誉谷内的塞尤克，和银月城远行者广场的伊蕾达。"
D.Strings[16950]="那个丑陋的兽人塞尤克可以教你如何使用匕首。要是你想在其他地方学的话，也可以去银月城远行者广场找伊蕾达或是去幽暗城军事区找阿基巴德，如何？"
D.Strings[16951]="你可以在奥格瑞玛的兽人武器大师塞尤克那里学会使用拳套。他每天都在荣誉谷。"
D.Strings[16952]="你想学习拳套的使用方法吗？和这里的塞尤克谈谈，他会教你的。"
D.Strings[16953]="我们的射击教师是安塞瓦，居住在雷霆崖中部高地底层的牛头人武器大师。"
D.Strings[16954]="安塞瓦会教你怎么使用锤子，你可以在雷霆崖的中部高地底层找到他。"
D.Strings[16955]="遗忘者的武器大师阿基巴德知道如何使用长柄武器，他就在幽暗城的军事区训练其他人。银月城远行者广场的血精灵武器大师伊蕾达也能教你相同的技能。"
D.Strings[16956]="奥格瑞玛荣誉谷的巨魔武器大师哈纳什和雷霆崖中部高地底层的牛头人武器大师安塞瓦可以教你如何使用法杖。"
D.Strings[16957]="这里的哈纳什知道怎么使用法杖。如果你想找一个更强健的教师，就去雷霆崖，安塞瓦会在中部高地底层教你。"
D.Strings[16958]="银月城远行者广场的血精灵伊蕾达会教你学习使用单手剑和双手剑。幽暗城的武器大师阿基巴德同样也能教你，他就在军事区。"
D.Strings[16959]="奥格瑞玛的武器大师塞尤克和哈纳什是真正的投掷武器专家。他们在荣誉谷训练所有对此有兴趣的学生；如果想看更加优雅的投掷姿势，那么没人比得上银月城远行者广场的伊蕾达。"
D.Strings[16960]="阿基巴德是弩类武器的教师。他是幽暗城的武器大师，就在军事区。"
D.Strings[16961]="我们的射击老师是雷霆崖中部高地底层的牛头人武器大师安塞瓦。"
D.Strings[16962]="他们都是从在雷霆崖中部高地底层的安塞瓦那里学会使用锤子的。"
D.Strings[16963]="遗忘者的武器大师阿基巴德知道如何耍长柄武器，他就在幽暗城的军事区训练着其他人。银月城远行者广场的血精灵武器大师伊蕾达也能教你相同的技能，朋友。"
D.Strings[16964]="我不知道为什么你想学些其他技能……但我想我能为你找到合适的训练师。你具体想要什么训练？"
D.Strings[16965]="既然你不是过来接受训练的，就站后面点，不要妨碍我工作。"
D.Strings[16966]="你让我失望了，阿卡玛。我本想要亲自审讯这条狡猾的虫子！现在我有些怀疑你们这些破碎者的忠诚了。"
D.Strings[16967]="看来你没有撒谎，阿卡玛。凯尔萨斯的背叛并没有让我感到多么吃惊，我并没有某些家伙所想的那样健忘。你的同族与他有重大的牵连，这让我不得不质疑你的忠诚。"
D.Strings[16968]="将你的灰舌部队派进风暴要塞，去杀掉他最得意的部下，那只名叫奥的凤凰。以此来向我证明你不是他的同党。不要妄图背叛我，破碎者。我们都知道你的灵魂在谁的掌握中！"
D.Strings[16969]="提防那些包围我们的复仇军。"
D.Strings[16970]="我把紫罗兰徽记给弄丢了，请再给我一个。"
D.Strings[16971]="我……我自由了！复仇军打算折磨我，直到我交出他们所要的东西。若不是你及时赶到，我肯定会屈服于他们的折磨。"
D.Strings[16972]="知道吗，$c，在这座陵墓尽头的沙法尔的房间内，有一个具备强大力量的生物正在休眠。它目前被静止间的力量控制着。如果你想消灭它，就必须先回到阿米尔那里去！"
D.Strings[16973]="过来，我会教如何骑乘这些坐骑。不过，你……带了足够的钱来付这笔费用吧？"
D.Strings[16974]="欢迎来到常青林，$c。坦莫和我一直在研究刀锋山一带的鸦人，最近，我们发现他们和那些泰罗卡森林的鸦人之间有着一些令人担忧的差别。"
D.Strings[16975]="<鸦人的幽灵逐渐接近你，仿佛是在辨认你。但你觉得它似乎总是看不清楚。>$B$B罗卡拉姆，是你吗？"
D.Strings[16976]="是的……是的，是我……"
D.Strings[16977]="请原谅我质问你，孩子。我的视力已经不如从前了，但是乌鸦之神赐我长生。$B$B不久之后，你就会接替我的位置。我将我所知道的知识都传授给了你。唯一的遗憾就是我没能夺回氏族神圣的乌鸦之书。"
D.Strings[16978]="是的，长者。告诉我关于乌鸦之书的故事吧。"
D.Strings[16979]="自从斯克提斯的鸦人同胞背信弃义，从我们手中偷走乌鸦之书，打破石板并将碎裂的石板碎片掩埋在他们那肮脏的城市中之后，鸦神真正的信徒便永远地生活在耻辱之中。$B$B祈祷乌鸦之神能挑中你，让你成为夺回神圣书典的英雄吧。孩子，要时刻保持信仰，并永远铭记这条预言：“与乌鸦之神为敌的人们，鸦神会从你们的睡梦中进入这个世界。”"
D.Strings[16980]="葛罗克需要帮助。小$r，快去刀锋山帮助血槌氏族吧！"
D.Strings[16981]="你去找莫戈多格吗？"
D.Strings[16982]="我正在寻找一名技艺超群的英雄。$G他:她;将召集其他人拯救血槌氏族，并从戈隆的残暴统治下解放生活在刀锋山的所有食人魔氏族。$B$B当你了解到更多的知识之后再来找我吧。但是，$c，在此之前请你保持低调，以免被戈隆察觉到我们的动机。"
D.Strings[16983]="如果我们想摆脱身上的枷锁，再次享受自由的滋味，就必须杀死所有的格鲁尔之子！$B$B但是，我们必须隐秘行动，只有通过秘密的抵抗行动，我们才有机会获得成功。"
D.Strings[16984]="要想拯救尤勒斯上校，恐怕只能利用那种危险性很高的仪式——是的，驱魔仪式。"
D.Strings[16985]="告诉我，$n，我们还要准备些什么……"
D.Strings[16986]="葛罗克需要帮助！为什么没人帮忙啊？"
D.Strings[16987]="%s环顾四周，却发现没有人愿意帮助自己，只得叹了口气。"
D.Strings[16988]="我们不能辜负背叛者。"
D.Strings[16989]="很快，我们的时代就要来了！"
D.Strings[16990]="堡垒那边有消息吗？"
D.Strings[16991]="这些变异兽人的味道让我感到恶心。"
D.Strings[16992]="食人魔，请离开这里。你正在打扰我们的客户！"
D.Strings[16993]="不要再这样了，葛罗克。我跟你说过的，离远点！"
D.Strings[16994]="葛罗克，出去。"
D.Strings[16995]="还没有人帮你吗，食人魔？"
D.Strings[16996]="食人魔，快走开！"
D.Strings[16997]="葛罗克，跟你说过多少次了，出去！"
D.Strings[16998]="卫兵，如果这个食人魔还不离开的话，就把他“护送”出去。"
D.Strings[16999]="有人愿意帮帮这个食人魔吗？那样他就不会再回来了。"
D.Strings[17000]="闪开，葛罗克，你不能去上面。"
D.Strings[17001]="啊，甜心，你知道我不能让你去上面。命令始终是命令。"
D.Strings[17002]="回答仍然是不，葛罗克。你不能去上面。"
D.Strings[17003]="我记得我告诉过你，不要到这附近来。走开！"
D.Strings[17004]="要是你们这些小家伙不去刀锋山和莫戈多格谈话，葛罗克会生气的！"
D.Strings[17005]="敌人就在我们眼前！守住你们的阵地！"
D.Strings[17006]="圣光的敌人必须被消灭！"
D.Strings[17007]="为了克希利！为了沙塔尔！"
D.Strings[17008]="你们的末日到来了，伊利达雷！"
D.Strings[17009]="把伊利丹的走狗们全部消灭！"
D.Strings[17010]="来吧，恶魔！死亡正等待着你！"
D.Strings[17011]="可怜虫……你主人的计划破产了！"
D.Strings[17012]="我有个消息要带给你们的主人，渣滓！"
D.Strings[17013]="我眼花了吗？我们很久没有见过面了，罗卡拉姆兄弟，真的是你吗？$B$B你在找塞克卡尔？他就在漩涡峰西部的水晶田中。他说自己可以在那里感受到某种原始的、未开化的超自然力量，并为此神魂颠倒；但是在旁人看来，那片水晶田并没有什么异常现象。"
D.Strings[17014]="%s开始分裂了！"
D.Strings[17015]="%s一路沿地面探测，寻找着被埋在土下的乌鸦石。"
D.Strings[17016]="%s找到了一块被埋起来的乌鸦石。"
D.Strings[17017]="我觉得我需要洗个澡。*嗅* 我想你也要洗个澡！"
D.Strings[17018]="一个牛头人圣骑士会是一头圣牛吗？"
D.Strings[17019]="我穿这条裙子是不是看起来比较胖？"
D.Strings[17020]="我敢打赌伊利丹其实是个好人，他只是需要母爱。"
D.Strings[17021]="我敢打赌要是冰淇淋打过孔的话味道肯定会更好！"
D.Strings[17022]="男孩有虱子女孩有美貌！"
D.Strings[17023]="如果我摒住呼吸，我会变成什么颜色？"
D.Strings[17024]="如果连马都能得到马蹄铁，我能得到德莱尼靴子吗？"
D.Strings[17025]="如果燃烧军团是这么大的麻烦，为什么就不能给他们浇些水呢？那么他们就只好停止燃烧了。"
D.Strings[17026]="你为什么吃这么多也不会胖？"
D.Strings[17027]="纳鲁睡觉的时候是不是要把圣光关掉的？"
D.Strings[17028]="%s默默注视了你片刻，然后示意你跟着。"
D.Strings[17029]="呵呵，我靠得有些近。不用担心，我很好。"
D.Strings[17030]="沃洛斯说他想和你谈话。"
D.Strings[17031]="%s感觉到了危险，迅速逃跑了。"
D.Strings[17032]="%s开始引导圣光的力量。"
D.Strings[17033]="我弄丢了哈拉迈德之眼，能再给我一个吗，阿米尔？"
D.Strings[17034]="%s开始吟唱一个非常圣洁的法术。"
D.Strings[17035]="前进，占星者！让伊利丹的侍从们见识一下我们的厉害！"
D.Strings[17036]="你也许了解一点点驾驭走兽的技巧，但是你有乘坐飞禽自由飞翔的经历吗？蛮锤矮人懂得如何驯养最好的飞行坐骑。如果你有胆的话，只需付一笔小钱，我就教给你这项技能。"
D.Strings[17037]="提到蛮锤部族时你会想到什么呢？当然是狮鹫骑士啦！影月谷虽说不是鹰巢山，但我们的狮鹫数量依然很充足，嗯，非常充足。瞧瞧那些美丽的小宝贝儿，你看上哪一只了呀？"
D.Strings[17038]="让我看看你的狮鹫，拉瑟尔。"
D.Strings[17039]="猛烈的地震警告了附近的鱼人们！"
D.Strings[17040]="%s把他的敌人送入了水下的坟墓！"
D.Strings[17041]="%s看到了一只小虫！"
D.Strings[17042]="%s召唤了水泡！"
D.Strings[17043]="稍息，士兵们！"
D.Strings[17044]="%s拿走了南国之怒月亮石，并逃进了河里。跟着她！"
D.Strings[17045]="%s阴险地举起战锤……"
D.Strings[17046]="武器准备！"
D.Strings[17047]="杀！"
D.Strings[17048]="你！快交出月亮石，我保证任何人都不会受到伤害！"
D.Strings[17049]="啊哈！"
D.Strings[17050]="可怜的家伙，你们胆敢进攻伊利丹大人的神殿？好吧，我会让这里变成你们的墓地！"
D.Strings[17051]="好吧，你赢了！我投降！不要伤害我！"
D.Strings[17052]="看到吗？我得到了南国之怒月亮石，而你无能为力。再见！"
D.Strings[17053]="不要伤害我！"
D.Strings[17054]="交出南国之怒月亮石，我就让你走。"
D.Strings[17055]="施放冰霜陷阱。"
D.Strings[17056]="一个吻就可以了。"
D.Strings[17057]="啊！我要撕碎你的灵魂！"
D.Strings[17058]="太弱了，小虫子！你的灵魂还不够塞牙缝呢……"
D.Strings[17059]="尽情享受庆典吧！"
D.Strings[17060]="小桶里的酒太棒了。干杯，$c！"
D.Strings[17061]="太棒了，宴会时间到了！"
D.Strings[17062]="%s一言不发，心中权衡着要做出怎样的抉择。站在他旁边的沙塔尔军队鸦雀无声，空气中弥漫着紧张的气氛……"
D.Strings[17063]="靠近点，年轻人。完全不用害怕我和$n。"
D.Strings[17064]="%s谨慎地走近观察者艾莱亚。"
D.Strings[17065]="为了帮助$n完成一个非常重要的任务，我要训练你一下。然后，我保证会让你重获自由。"
D.Strings[17066]="就凭你这副可怜虫的模样还敢高谈阔论什么守护圣光？蠢货！克希利，我要消灭你！"
D.Strings[17067]="时机到了，玛维！释放你的怒火吧！"
D.Strings[17068]="这一天我已经等待许多年了！伊利丹和他的走狗都将彻底被毁灭！"
D.Strings[17069]="把所有看到我们的人都杀掉……一定不能让伊利丹得知我们的到来！"
D.Strings[17070]="你的死期就要到了，阿卡玛。主人马上就会得知你的背叛！"
D.Strings[17071]="阿卡玛没有主人了。再也没有了。"
D.Strings[17072]="趁阿卡玛专注地听着瓦加斯的遗言时，%s偷偷躲到了隐蔽之处。"
D.Strings[17073]="我们的计划早已危在旦夕。好像玛维决定以她自己的方式来做事。"
D.Strings[17074]="%s的注意力转移到了神殿南墙的一道裂缝上。"
D.Strings[17075]="无论玛维是不是和我们在一起，我们都必须继续。进去！快点！"
D.Strings[17076]="当我们需要你时就会发出号令。飞去东方，到斯克提斯去，在那里等待着$n的信号。"
D.Strings[17077]="年轻的麻鹰，如果没有你，我们恐怕要花上几年的时间才能找到乌鸦之书。带着我们的感激返回纳格兰吧。"
D.Strings[17078]="这就是了！这就是真正的……乌鸦之书！"
D.Strings[17079]="堕落与腐化的盛宴已经不复存在了！玛瑟里顿在$n和$g他:她;的伙伴们面前倒下了！它的灭亡见证了联盟力量的伟大！一个深渊领主被消灭了！"
D.Strings[17080]="兄弟们，姐妹们！敌人的末日降临了！我们必须打击剩余的邪兽人！把他们像虫子那样消灭掉！在洛萨之子的庇护下继续战斗吧！"
D.Strings[17081]="一切都真相大白了……乌鸦之神的追随者将敌人的灵魂永久地禁锢在石像中，以此俘获和制服他们。石板甚至提到了乌鸦之神的名字——安苏。我一直以为他的名字早已湮没在历史的长河中！"
D.Strings[17082]="石板上还记载着别的信息。在一段血腥战斗和乌鸦之神落败的描述之后，有一个预言：安苏将在敌人的梦境中出现，扭曲他们的意志，以重返这个世界……"
D.Strings[17083]="石板应证了我先前的猜想。我们必须利用这条信息，在安苏对翡翠梦境造成更大的破坏之前，将他召唤到这个世界中，然后击败他！"
D.Strings[17084]="%s向帮忙确定乌鸦石位置的麻鹰致谢。"
D.Strings[17085]="前进，守备官！把这些恶魔从我们圣洁的神殿里赶出来！"
D.Strings[17086]="你似乎懂得如何驾驭野兽在地面行走，但是如果你想要在天空翱翔的话，就需要经过刻苦的训练，当然还需要金币。你身上有金币的，对吧？"
D.Strings[17087]="瞧这些漂亮的野兽。我们在这里饲养双足飞龙，并训练这些既可靠又勇敢的野兽适应德拉诺世界严酷的天气环境。"
D.Strings[17088]="让我看看你的双足飞龙，达玛。"
D.Strings[17089]="地狱火堡垒是我们的了！伊利丹的邪兽人军团已经不复存在了！玛瑟里顿在$n和$g他:她;的朋友们面前倒下了！"
D.Strings[17090]="决战的时刻到了！让我们拿起武器，消灭残余的邪兽人势力吧！为了你们的酋长而战！为了部落而战！"
D.Strings[17091]="蠢货！山鹰精华永远不会落入你的手中！"
D.Strings[17092]="乌鸦之神的时代即将来临，而你的末日就在眼前！"
D.Strings[17093]="你胆敢打扰乌鸦之神的忠实追随者？"
D.Strings[17094]="你会为你的傲慢而付出代价，$c！"
D.Strings[17095]="猎鹰被击败了，它注定再也不会出现了！你的任务失败了！"
D.Strings[17096]="乌鸦之神会像预言所说的那样重返这个世界，而你根本没有能力阻止他！"
D.Strings[17097]="你胆敢召唤我？"
D.Strings[17098]="%s深深吸了一口气！"
D.Strings[17099]="%s开始施放炎爆术！"
D.Strings[17100]="沉默突然笼罩着整个沙塔斯城。"
D.Strings[17101]="%s的思想似乎侵入了你的心灵。"
D.Strings[17102]="凯尔萨斯·逐日者被$n和$g他:她;的伙伴们打败了。"
D.Strings[17103]="现在，攻击风暴要塞内的残余血精灵的时刻已经来临了。拿起武器！让阿达尔的战歌激励你们吧！"
D.Strings[17104]="我不关心你是谁，或是你在天空卫队以外做些什么。不过只要你在这里，你就要听从我的命令。"
D.Strings[17105]="我饿了。水果应该很好吃。"
D.Strings[17106]="枯瘦的莫戈多格告诉葛罗克，要去城市里为血槌氏族寻求帮助。葛罗克就来了。"
D.Strings[17107]="要是没人帮忙，葛罗克就打人！"
D.Strings[17108]="刀塔氏族没有公平地战斗。他们有戈隆帮忙。你去刀锋山，和枯瘦的莫戈多格谈谈。去消灭戈隆吧。"
D.Strings[17109]="嘿，巨魔！为什么这个符咒没有用？！"
D.Strings[17110]="等我长大以后，我要成为一个制革工人！"
D.Strings[17111]="葛罗克没有吃掉所有苹果。看，那里还有一篮。"
D.Strings[17112]="就是那个愤怒的兽人。他弄碎了它们！想让葛罗克去打他吗？"
D.Strings[17113]="大家为$n，食人魔新的$G国王:女王;欢呼吧！"
D.Strings[17114]="你手下那群猴子可耻地失败了，纳鲁。虽然我已经落败，但是我还活着……当我们控制纳鲁飞船的时候，绝对没有犯下这样的错误。"
D.Strings[17115]="这一切都是为了什么？几样无关紧要的小玩意？太迟了。迎接主人归来的准备工作早就开始了。很快，他就会重返这个世界。"
D.Strings[17116]="你，或是伊利丹那个蠢货，都根本不能阻止我！你们一直扮演着我的仆从的角色，只是你们对此一无所知罢了。"
D.Strings[17117]="他的双眼中折射出欲望的光芒，谁能从他的凝视下拯救艾泽拉斯世界？你？就凭你？还有这些帮你打杂的猴子？"
D.Strings[17118]="放下武器，向基尔加丹的力量屈服吧！"
D.Strings[17119]="不！这怎么可能？"
D.Strings[17120]="很久之前，那些下等的灵魂就被囚禁起来了，再也没有回来！我亲自挑选了守护者！而你都做了些什么？"
D.Strings[17121]="你会为你的傲慢付出痛苦的代价！你休想阻止我夺走翡翠梦境！"
D.Strings[17122]="享受聚会吧，$c！"
D.Strings[17123]="保护我的宝贝！"
D.Strings[17124]="为了黑鳞！"
D.Strings[17125]="开饭了！"
D.Strings[17126]="侦察整片区域，汇报你发现的任何动向！"
D.Strings[17127]="以圣光的名义！那是什么东西？"
D.Strings[17128]="燃烧军团的诡计真是个巨大的威胁！"
D.Strings[17129]="快点消灭这台邪恶的机器！"
D.Strings[17130]="我们可没法就靠这么点人搞定那台机器，趁我们还没被发现，快跑！"
D.Strings[17131]="燃烧军团造出来的东西真是一天比一天邪恶了。"
D.Strings[17132]="让我们看看当这个机器恶棍敲你的大门时，你会作何感想，伊利丹！"
D.Strings[17133]="进去，快点！可以用燃烧军团的进攻作为掩护！"
D.Strings[17134]="龙骑士，准备起飞！"
D.Strings[17135]="你这垃圾，回到巡逻队中去！对我来说，那护盾比一百个你都要有价值……"
D.Strings[17136]="这是赤裸裸的侮辱！你胆敢违抗我的命令，我要惩罚你！"
D.Strings[17137]="请求低飞掠过哨塔的允许！"
D.Strings[17138]="对于那些在这场战役中献出生命的勇士，没有什么词语能够表达我们敬意。但是我想说，很荣幸能与你们并肩作战。现在，尽情地庆祝吧，胜利属于我们！！"
D.Strings[17139]="我出生至今就没听说过什么提克巴朗。事实上，占星者们说他们在图书馆中也没有找到任何提及提克巴朗的资料……"
D.Strings[17140]="要知道，他们可不是为了写这个而活的，你说是吧？"
D.Strings[17141]="%s皱起眉毛，露出怀疑的神色。"
D.Strings[17142]="你是在侮辱我们的市民吗？"
D.Strings[17143]="这就是事实，朋友。你体会不到吗？"
D.Strings[17144]="不用再害怕了，$n！"
D.Strings[17145]="从你的睡眠中醒来吧，$n！"
D.Strings[17146]="记住你应该向谁效忠，$n！"
D.Strings[17147]="回到这个位面来，$n！"
D.Strings[17148]="回归你原本的形态，$n！"
D.Strings[17149]="不要这么轻易地被吸引，$n！这是个骗局！"
D.Strings[17150]="恢复自由，$n，追击！"
D.Strings[17151]="$n，冲破束缚，重获自由吧！"
D.Strings[17152]="%s缩进了龟壳里。"
D.Strings[17153]="%s嗅了嗅空气中的味道，皱起眉头。他往肩膀上瞟了一眼。"
D.Strings[17154]="我认为，那……气味是从托比亚斯那里来的。"
D.Strings[17155]="%s失落的神情消失了，换上一副狡猾的模样。"
D.Strings[17156]="……你觉得他会买绳子上的肥皂吗？"
D.Strings[17157]="辛多雷是不可战胜的！"
D.Strings[17158]="还没完！"
D.Strings[17159]="太阳的光芒……在等待着我。"
D.Strings[17160]="你的灵魂将归于深渊！"
D.Strings[17161]="以上层精灵之血的名义！"
D.Strings[17162]="为了太阳之井！"
D.Strings[17163]="你们势单力薄！"
D.Strings[17164]="我要让你们自以为是的错觉荡然无存！"
D.Strings[17165]="准备出发！"
D.Strings[17166]="不！我……不会……"
D.Strings[17167]="血债血还！"
D.Strings[17168]="更大的危机……在等着你们。"
D.Strings[17169]="你是不是在暗示你出售的设备可以控制他人的心灵？那可是非常危险的……"
D.Strings[17170]="%s脸上带着愤怒的表情转向亚达尔。"
D.Strings[17171]="说实在的，朋友，你在嘲笑我的品位。"
D.Strings[17172]="倘若你的“品位”不包括诈骗城里的居民，那么你就不会觉得我的话很“讽刺”。"
D.Strings[17173]="嗯，嗯。"
D.Strings[17174]="阿卡玛。你的两面三刀并没有让我感到意外。我早就应该把你和你那些畸形的同胞全部杀掉。"
D.Strings[17175]="说得好。但是这毫无意义。"
D.Strings[17176]="你不会是想说你卖的这堆破烂能改变人们的生活吧？"
D.Strings[17177]="%s愤怒地大声咆哮着。"
D.Strings[17178]="你想查明吗？！"
D.Strings[17179]="%s冷冷地盯着格里伏塔。"
D.Strings[17180]="……你在威胁我？！"
D.Strings[17181]="啊……啊……不。"
D.Strings[17182]="%s在格里伏塔的身后皱着眉头，但仍然保持着沉默。"
D.Strings[17183]="真的？“保证”？我们要坐下来仔细地谈谈关于你的这个“保证”。"
D.Strings[17184]="%s耷拉着肩膀，轻声祈求着什么。"
D.Strings[17185]="你不如在这里就展示一下你出售的这个护身符的治疗效果……？"
D.Strings[17186]="啊……不，朋友。别把货物搞乱了，行吗？"
D.Strings[17187]="%s紧张地笑了笑。"
D.Strings[17188]="好吧。咱们待会儿再谈，不过我很想看看你所宣称的证据。"
D.Strings[17189]="嗨！嗨！朋友，待会儿。咱们待会儿再谈。"
D.Strings[17190]="到处都是对这个……这个家伙的抱怨声。据说他是个可疑的人物。我是来调查他的生意是否合法的……如果他胆敢做违法的勾当，我就会立即采取行动。"
D.Strings[17191]="你们这是自寻死路！"
D.Strings[17192]="如果你集齐一套报复卡片的话，你将获得一张暗月卡片：复仇。当你拿着这张卡片时，任何攻击你的人都有一定几率遭到神圣的复仇。"
D.Strings[17193]="如果你集齐一套风暴卡片的话，你将获得暗月卡片：怒火。当你拿着这张卡片时，你的法术或物理攻击的爆击几率会不断提高，直到你打出一次爆击。"
D.Strings[17194]="如果你集齐一套祝福卡片的话，你将获得暗月卡片：远征。当你拿着这张卡片时，你只需持续战斗，你的法术和物理攻击的伤害就会不断提高。"
D.Strings[17195]="如果你集齐一套愚人卡片的话，你将获得暗月卡片：疯狂。当你拿着这张卡片时，每当你杀死一个敌人，你就会充满疯狂的力量。"
D.Strings[17196]="告诉我更多关于报复套牌的信息。"
D.Strings[17197]="告诉我更多关于愚人套牌的信息。"
D.Strings[17198]="告诉我更多关于祝福套牌的信息。"
D.Strings[17199]="告诉我更多关于风暴套牌的信息。"
D.Strings[17200]="我们要终结你的统治，伊利丹！我的人民，以及整个外域，都将重获自由！"
D.Strings[17201]="时机来临了，终于等到这一刻了！"
D.Strings[17202]="我们食人魔曾经迷失了自我……"
D.Strings[17203]="虽然我们很强大，但却只知道暴力……"
D.Strings[17204]="我们经历了艰苦卓绝的漫长斗争，每一次都证明了我们食人魔是一股不可忽视的力量。"
D.Strings[17205]="不久以后，我们内部开始互相争斗，兄弟之间凭借血腥的战斗来决出谁是最强者。"
D.Strings[17206]="很明显，从那以后，我们的种族已经在毁灭的道路上走出了很远。我们成了自己最大的敌人，成了毁灭自身的原因。"
D.Strings[17207]="但是如今，在这些水晶之间，我们找到了一条新的道路，一条和平之路。"
D.Strings[17208]="莫希斯！感谢艾露恩！我还以为我再也看不到你了。"
D.Strings[17209]="当心点，朋友们。背叛者就在那边的大厅中冥想。"
D.Strings[17210]="我们已经作好面对伊利丹的准备了。"
D.Strings[17211]="原谅我，王子殿下！我……失败了。"
D.Strings[17212]="警报！消灭入侵者。"
D.Strings[17213]="系统……关闭……"
D.Strings[17214]="目标已终结。"
D.Strings[17215]="入侵生命体已经停止运转。"
D.Strings[17216]="威胁已排除。"
D.Strings[17217]="备用方案启动……"
D.Strings[17218]="计算力量参数……"
D.Strings[17219]="这样看来仅凭我的血还不足够来偿还这一切，是吗？好吧，那么再让我恢复你的奥术精华。在这之后，我和巴塔斯就两清了。"
D.Strings[17220]="%s在仪式堆上放下一座小雕像。"
D.Strings[17221]="整个过程将会非常艰巨。我们必须首先召唤出元素侍僧。而你则必须打败这些侍僧，这样一来我的随从就能开始做准备了。"
D.Strings[17222]="干得好！让我们继续。"
D.Strings[17223]="准备好！水之侍僧很快就要来了……"
D.Strings[17224]="出来吧，地之侍僧！"
D.Strings[17225]="火之侍僧，现身吧！"
D.Strings[17226]="现在，我们将召唤奥术侍僧。"
D.Strings[17227]="你在考验我的耐心，蠢货！"
D.Strings[17228]="够了！尝尝高阶督军纳因图斯的真正怒火吧！"
D.Strings[17229]="嘘！小声点。孩子们正在睡觉。"
D.Strings[17230]="%s看到他的$g国王:女王;大发雷霆之后退缩了。"
D.Strings[17231]="%s看到$n之后，一不小心放了个典型的食人魔的屁。"
D.Strings[17232]="我也喜欢放屁！"
D.Strings[17233]="啊，我不觉得我们两个合适。"
D.Strings[17234]="我做错了什么，我的$g国王:女王;陛下？"
D.Strings[17235]="深渊中的洪水会淹没你们！"
D.Strings[17236]="沼泽花爆炸了，猛烈地喷射着花粉。"
D.Strings[17237]="以潮汐的名义！"
D.Strings[17238]="我的仆从，干掉他们！"
D.Strings[17239]="你们无处可逃！"
D.Strings[17240]="很快就都结束了。"
D.Strings[17241]="挣扎只会让你更痛苦。"
D.Strings[17242]="只有强者才能生存。"
D.Strings[17243]="埃格恩的……巨浪……"
D.Strings[17244]="停止前进。否则你们将被消灭。"
D.Strings[17245]="地面破坏程序启动。"
D.Strings[17246]="范围确认。释放。"
D.Strings[17247]="轨道锁定。"
D.Strings[17248]="提升至最高速度。"
D.Strings[17249]="威胁等级归零。"
D.Strings[17250]="指令完成。"
D.Strings[17251]="目标已歼灭。"
D.Strings[17252]="系统崩溃倒计时，五，四……"
D.Strings[17253]="嗯，$g国王:女王;陛下？"
D.Strings[17254]="你杀死了戈隆！现在你又得和那些天上来的家伙作战吗？"
D.Strings[17255]="为$n而战！"
D.Strings[17256]="这酒真好喝！"
D.Strings[17257]="要是$G国王:女王;陛下跳舞的话，我也跟着跳！"
D.Strings[17258]="$G国王:女王;陛下不生我的气吗？"
D.Strings[17259]="你为什么这么看着我？你不会是想吻我吧，是不是！？"
D.Strings[17260]="现在所有的格鲁尔之子都死了！现在新的$G国王:女王;陛下将领导所有的食人魔去奥格瑞拉！"
D.Strings[17261]="水晶人"
D.Strings[17262]="$g国王:女王;陛下！"
D.Strings[17263]="$n$G国王:女王;陛下！"
D.Strings[17264]="跪下，败狗！"
D.Strings[17265]="$G他:她;真是个漂亮的统治者。"
D.Strings[17266]="仁慈！"
D.Strings[17267]="嘘……安静，是新的$g国王:女王;陛下。"
D.Strings[17268]="$G他:她;太小了！$g他:她;能行吗？"
D.Strings[17269]="愿为您效劳。"
D.Strings[17270]="你最好快点醒来，新人。这里不是斯克提斯外的某个舒适的后院，这里是刀锋山！一不小心就会导致灾难性的后果！"
D.Strings[17271]="准备好以后再到我这里来。"
D.Strings[17272]="我遗失了灌注精华的月亮石。你能再给我一个吗？"
D.Strings[17273]="我需要你的生命精华，只有这样我才能在这个位面继续生存下去。"
D.Strings[17274]="主人，这是你的！"
D.Strings[17275]="好吧，现在，你立刻前往大锻炉那里找先知亚瓦德，就在东边略微往北一点。"
D.Strings[17276]="身为萨尔酋长大人的顾问，派雷亚诺一直待在智慧谷的格罗玛什要塞里。"
D.Strings[17277]="真可怕呀！"
D.Strings[17278]="我和银月大使帕拉·晨歌代表逐日王庭来到奥格瑞玛。$B$B大使负责处理各种民事问题，而我则对萨尔提出军事建议，以及宣扬与血骑士合作的……呃，独一无二的优势。"
D.Strings[17279]="继续指导我如何使用纳鲁的力量吧。"
D.Strings[17280]="%s回到了石化状态。"
D.Strings[17281]="神圣符印？有了。蜡烛？有了。魔粉，嗯……魔粉？啊，该死的！我再也不要帮别人带施法材料了。这附近有商人吗？"
D.Strings[17282]="这附近有法师吗？我应该带些水和食物的……"
D.Strings[17283]="谁再问我要药水，我就揍他。我再也不当炼金师了！"
D.Strings[17284]="亲娘哎，要是可以骑狮鹫就好了……"
D.Strings[17285]="我可以教你珠宝加工。有兴趣吗？"
D.Strings[17286]="为什么这堵墙还没建起来？我一直在敲打，但是毫无效果！"
D.Strings[17287]="谢谢你召唤我，小家伙。我的队伍把我丢在这里，就直接跑进地下城了！"
D.Strings[17288]="为什么这堵墙还没有倒下？你在干什么？"
D.Strings[17289]="嘿，蠢货！为什么你要敲这堵墙？我们是要建造墙而不是弄倒它！愚蠢的兽人！建造！我说的是建造！"
D.Strings[17290]="太棒了！"
D.Strings[17291]="醒来吧，我的孩子，来帮助你们的主人！"
D.Strings[17292]="你想要什么？作为一名邪兽人，你闻上去有点古怪……"
D.Strings[17293]="你不是想把这里当做自己家吧。也许你想吃点什么？"
D.Strings[17294]="我想让古格修护甲。也许我还会买点什么。"
D.Strings[17295]="有时候，那些该死的血精灵会顺路从我这里购买一些特殊的材料或是毒药。我必须随时保持这类货源，以免谣言传到伊利丹大人耳朵里，说龙喉氏族不与血精灵合作……$B$B<鲁姆普斯艰难地咽了口气。>$B$B我们可不希望发生那种事……"
D.Strings[17296]="你有什么特别的货物吗，鲁姆普斯？"
D.Strings[17297]="哦耶！你想尝尝这些枪支的威力吗，渣滓？走近点！"
D.Strings[17298]="你怎么和这些巨蟒扭打的？哦哦哦，呀呀呀，兄弟！"
D.Strings[17299]="听见了吗？你听见颂歌了吗，兄弟？他们正在为鲁克斯特欢呼！"
D.Strings[17300]="如果疯狂的鲁克斯特对你大发雷霆，你准备怎么做，兄弟？！"
D.Strings[17301]="<克希利浑身散发着红色的光芒。纳鲁在欢迎你这位盟友。>"
D.Strings[17302]="我愿意与你的军队并肩作战，克希利。"
D.Strings[17303]="检查那里的水晶簇！"
D.Strings[17304]="什么都没找到？好吧。去另一簇看看。"
D.Strings[17305]="那簇水晶似乎有异样。"
D.Strings[17306]="如果你能帮我找到我梦寐以求的东西，我会好好奖励你的。"
D.Strings[17307]="我有些怀疑你是个没用的家伙了。不要再让我失望！"
D.Strings[17308]="嗯，这些不错。"
D.Strings[17309]="你与灵翼龙族结下了深厚的情谊，我们都愿意在背后支持你！朋友，现在就给予我们的敌人致命一击吧！我们必须夺回失去的一切。"
D.Strings[17310]="你帮了灵翼龙族许多忙，$n。但是在你掌握更高级的骑术之前，是无法有什么进展的。只有最坚定的骑士才能帮助灵翼龙族。"
D.Strings[17311]="是的……施放你珍贵的小法术吧，呱——啊——呱！"
D.Strings[17312]="我想要输入神秘兑换码来换取我的金猪宠物。"
D.Strings[17313]="你好，$r。你最近有幸参加了特别的活动吧？$B$B那样的话，你可能已经得到了一组神秘兑换码。将神秘兑换码告诉我，我就送你一份特殊的奖励。"
D.Strings[17314]="你的魔法将导致你的毁灭……呱——啊——呱……"
D.Strings[17315]="你的力量……呱——呱……将转而对付你……"
D.Strings[17316]="你的法术……呱——呱……脆弱的魔法……轻而易举地就能转而对付你……"
D.Strings[17317]="地面崩裂了！"
D.Strings[17318]="苏普雷姆斯愤怒地击打着地面！"
D.Strings[17319]="入侵者！让龙喉的标记引导你的怒火！杀死$n！"
D.Strings[17320]="你要帮忙吗？"
D.Strings[17321]="你能骗得了谁，$r？在碎天者敏锐的目光中，即便是灵翼氏族的魔法也不能遮盖你的真面目！"
D.Strings[17322]="小心龙喉碎天者和升腾者，他们能识破我们的魔法！和那些家伙保持距离，切记！"
D.Strings[17323]="食人魔氏族是不会被征服的。我们绝不臣服于戈隆的统治，也不会向你这样的$r低头！"
D.Strings[17324]="莫戈多格这个蠢货，居然认为那个小个子是我们的救世主。"
D.Strings[17325]="这些山脉是食人魔的地盘。不是戈隆的，也不是人类和兽人的！"
D.Strings[17326]="不要向莫戈多格的傀儡低头！他不过是想以此取代戈隆大王的统治。为什么我们要不停地更换主人呢？"
D.Strings[17327]="时机已经成熟。那些挡在氏族前进道路上的家伙们，让他们统统去死！"
D.Strings[17328]="不要听信莫戈多格的谎言！奥格瑞拉是个神仙般的圣地！我们铲除了那些企图分化奴役我们的敌对势力，在这里建立起自己的天堂。"
D.Strings[17329]="你一定很好奇为什么食人魔说话也能这么流利。这是生长在奥格瑞拉周围的水晶簇的副作用。那里的食人魔将这根法杖送给了我，镶嵌在法杖上的水晶赐予了我无穷的智慧。$B$B只要你继续在奥格瑞拉行善，那么总有一天，所有的食人魔同胞都能享受到这种福泽。谢谢你，我的$g国王:女王;。感谢你为我们所做的一切。"
D.Strings[17330]="我们是兄弟。我们要团结起来，抵抗那些反对和平的家伙。"
D.Strings[17331]="啊……我……死了。"
D.Strings[17332]="我要去……奥格瑞拉了。"
D.Strings[17333]="伟大的$g国王:女王;陛下，杀了我吧……我很荣幸。"
D.Strings[17334]="$g国王:女王;$n陛下，我现在死了。"
D.Strings[17335]="你对燃烧军团来说已经不陌生了。当然，你也会知道，这意味着怎样的痛苦在等待着你……"
D.Strings[17336]="我们就在奥格瑞拉。"
D.Strings[17337]="我们就在天堂。"
D.Strings[17338]="从前的道路血渍斑斑，如今我们却走在被水晶照耀的道路上。"
D.Strings[17339]="即使是战争的喧嚣，也无法阻止我们聆听水晶中传出的美妙歌声。"
D.Strings[17340]="即使敌人兵临城下，水晶散发出的光芒依然鼓舞着我们。"
D.Strings[17341]="在奥格瑞拉，我们达到了一种更高的生活境界。而且我们会继续保持这种状态。"
D.Strings[17342]="你听见了吗，兄弟？"
D.Strings[17343]="在水晶的歌唱声中，你可曾听见战争迫近的号角？"
D.Strings[17344]="你看到我们的敌人了吗？"
D.Strings[17345]="他们就潜伏在附近，随时准备发起进攻。"
D.Strings[17346]="我们准备好了吗？"
D.Strings[17347]="水晶启迪了我们。但是我们仍然需要保持警惕。"
D.Strings[17348]="$G国王:女王;陛下，你觉得……世上真的有个……奥格瑞拉吗？"
D.Strings[17349]="弱小的$r……你是一个……可怕的$g国王:女王;。"
D.Strings[17350]="尽其一生，为荣誉，为宽恕，为血魔而战。"
D.Strings[17351]="又一个，嗯？你永远都不会成功……"
D.Strings[17352]="记住，你每天只能做一次收集工作。但是，我们也一直需要更多的水晶。任何废柴苦工都能把那些东西带回营地。"
D.Strings[17353]="我的猎犬将把你的尸体当作一顿美餐！"
D.Strings[17354]="容你肆意挑衅的日子就要结束了！"
D.Strings[17355]="你的灵魂注定会被毁灭！我们的护盾防御就快准备就绪了……"
D.Strings[17356]="护盾防御正在启动，30秒后执行"
D.Strings[17357]="护盾防御正在启动，20秒后执行"
D.Strings[17358]="护盾防御正在启动，10秒后执行"
D.Strings[17359]="对叛徒来说，这是再好不过的结局了……"
D.Strings[17360]="我没有新任务交给你了，孩子。你已经不适合做体力活啦……"
D.Strings[17361]="召唤中"
D.Strings[17362]="为了孩子们！为了部落！"
D.Strings[17363]="为了孩子们的将来！为了联盟的将来！必须阻止燃烧军团！"
D.Strings[17364]="%s似乎运气不佳，附近连一颗乌鸦石也没有。"
D.Strings[17365]="感受我体内的恶魔之力吧！"
D.Strings[17366]="%s变成了一个灵体生物……"
D.Strings[17367]="你们就这点本事吗？这就是你们全部的能耐？"
D.Strings[17368]="玛维……怎么可能……？"
D.Strings[17369]="他们的愤怒和我的相比简直不值一提，伊利丹。我们之间终于要决一胜负了。"
D.Strings[17370]="我长久以来的追猎终于要结束了！今天，正义将得到伸张！"
D.Strings[17371]="你好，$c。我相信你一定给我带来了一些关于全球精英邀请赛的好消息？如果确实如此，那么你肯定有一个神秘兑换码想要告诉我，作为神秘兑换码的回报，我会送你一只小金猪作为礼物。$B$B准备好以后，就把神秘兑换码悄悄告诉我吧。"
D.Strings[17372]="我愿意告诉你我的神秘兑换码，换取一只金猪宠物。"
D.Strings[17373]="%s的肉体在剧烈的怒火中烧得粉碎！"
D.Strings[17374]="我的孩子们，消灭$n！"
D.Strings[17375]="%s把注意力集中在$n身上。"
D.Strings[17376]="伊利丹对我的氏族的控制非常严密，$n。但是无论如何，一切很快就会结束了。$B$B$n，你准备好了吗？氏族的未来就靠你了。"
D.Strings[17377]="我与你同在，阿卡玛。"
D.Strings[17378]="天空卫队斥候！！！"
D.Strings[17379]="%s把饮料撒了出来。"
D.Strings[17380]="%s一边咒骂着超速驾驶的天空卫士，一边清理着弄脏的地方。"
D.Strings[17381]="把药剂……给我，瑟维里！"
D.Strings[17382]="我看到他们了……从斯克提斯来的刺客！"
D.Strings[17383]="以瓦丝琪女王的名义，去死吧！"
D.Strings[17384]="鸦人会派出他们所有的刺客……不过那些刺客的命运会和这些先行者一样！"
D.Strings[17385]="留在这里……"
D.Strings[17386]="我等会儿再对付你。"
D.Strings[17387]="你的成功转瞬即逝！"
D.Strings[17388]="你该去死了。"
D.Strings[17389]="伊利丹大人……会干掉你们的！"
D.Strings[17390]="这是……我吐的血？即使我没被刺杀，这旧伤旧疾也会要了我的命。"
D.Strings[17391]="我的耐心用尽了！死吧！去死吧！"
D.Strings[17392]="你知道，我是第一个。对我来说，死亡之轮已经旋转了许多次。时间已经流逝了许多……有太多事情要做了。"
D.Strings[17393]="你可以派上一些用场……"
D.Strings[17394]="事情更糟糕了。"
D.Strings[17395]="死亡真的并非那么糟糕。"
D.Strings[17396]="你在害怕什么？"
D.Strings[17397]="我有些东西给你。"
D.Strings[17398]="你要表现出足够的尊敬！"
D.Strings[17399]="死亡之轮……又开始旋转了。"
D.Strings[17400]="%s感到恶心！"
D.Strings[17401]="这是什么诡计！？是谁煽动我的部下反对我？"
D.Strings[17402]="去水晶那边工作！"
D.Strings[17403]="这水晶不错。把它们弄下来！"
D.Strings[17404]="快一点！水晶可不会自己走回营地去！"
D.Strings[17405]="你把这一批全都给毁了！为什么我要和你这个渣一样的甘尔葛一起工作。"
D.Strings[17406]="至少你还没有弄坏这一批。"
D.Strings[17407]="难以置信，你竟然真的做对了一次。"
D.Strings[17408]="开饭时间到了！？"
D.Strings[17409]="嗯！食物！"
D.Strings[17410]="我太饿了！太好吃了！"
D.Strings[17411]="它一口吞下了一只羊！"
D.Strings[17412]="嗨……我感觉不是太好。"
D.Strings[17413]="你是个坏兽人……坏……啊！"
D.Strings[17414]="我是个征服者。"
D.Strings[17415]="我是个审判者。"
D.Strings[17416]="你的能力还不够，我教你的东西你肯定理解不了。我强烈建议你找葛洛莉丝谈一谈，先向她学习一点小花样，磨练磨练你的技术吧。"
D.Strings[17417]="让我们开始做事吧，$n。我会让你了解我所掌握的知识，不过，先继续。"
D.Strings[17418]="你不可能抵挡得住我的军团！"
D.Strings[17419]="要是你有胆的话，就凝视着迁跃门内部吧。我已经为你准备了一些特别的东西……"
D.Strings[17420]="阿达利斯！"
D.Strings[17421]="休息一会儿，朋友。你需要恢复力量。"
D.Strings[17422]="你摆脱不了你的命运，叛徒！"
D.Strings[17423]="你休想逃走！"
D.Strings[17424]="叛徒！你在攻击护盾！你死定了……"
D.Strings[17425]="莫戈多格，我知道那些你一直想知道的东西。"
D.Strings[17426]="我回来了，老大。让我告诉你我知道的事情。"
D.Strings[17427]="戈隆什么都不知道，莫戈多格。我确信他们不知道计划。"
D.Strings[17428]="我听说许多事情都在进行。我们马上要去杀戈隆了？"
D.Strings[17429]="莫戈多格，我不会把对付戈隆的秘密计划告诉任何人。"
D.Strings[17430]="我和其他食人魔已经协商好了。他们也准备好了。"
D.Strings[17431]="好的，我现在出发了。"
D.Strings[17432]="这些毫无价值的努力，除了痛苦以外，什么都不能带给你。"
D.Strings[17433]="你干得不错。你提供的信息对我们的成功十分重要。"
D.Strings[17434]="谢谢你，朋友。很快，我们就能从戈隆的奴役中解脱出来。"
D.Strings[17435]="太好了。你现在所从事的事业，终有一天会让我们加入奥格瑞拉的同伴们。"
D.Strings[17436]="奥格瑞拉得知你给我们带来的信息之后肯定会十分高兴的。"
D.Strings[17437]="这是个好消息，我们反抗戈隆的秘密行动仍旧按计划顺利进行着。而且，现在我们还得到了来自外部的支持与帮助。"
D.Strings[17438]="我们坚定不移地继续反抗戈隆的秘密行动！回去收集更多的信息吧。"
D.Strings[17439]="好。要是一切都能按计划顺利进行，我们很快就会从戈隆的魔掌中逃脱出来，获得真正的自由。刀锋山的所有食人魔都将从奥格瑞拉这里享受到食人魔文明的祝福。"
D.Strings[17440]="不久之后，我的朋友，你就会像我一样得到一块奥格瑞拉水晶。那样的话，你就能更深刻地了解周围的世界。"
D.Strings[17441]="是。除非这事跟我有关系。"
D.Strings[17442]="在明天到十年后这个阶段期间的某一天就会发生。我肯定。"
D.Strings[17443]="真的！"
D.Strings[17444]="对你来说不错……对我则相反。"
D.Strings[17445]="我跟其他的小鬼开会讨论了一下，答案是“是”。不过有一个小鬼投了反对票。"
D.Strings[17446]="前景不错，但我比较悲观。"
D.Strings[17447]="要我说出这样的话真是有些难过，不过答案是“是”。"
D.Strings[17448]="如果矮人会飞，答案就是“是”。他们真的会飞？那就是咯！"
D.Strings[17449]="当然，但是你不会喜欢的。"
D.Strings[17450]="你在这里听到和看到的一切都要保密，$r。"
D.Strings[17451]="$g国王:女王;陛下！卓尔特愿为您效劳。"
D.Strings[17452]="葛罗克听说你是所有食人魔的新$g国王:女王;。恭……恭喜你，小$r。"
D.Strings[17453]="很不幸……是的。"
D.Strings[17454]="我看不到否定的理由，不过话说回来，有很多东西我都看不到。"
D.Strings[17455]="我可以用你的灵魂打赌。"
D.Strings[17456]="是的。但是如果别人问起来……别说是我告诉你的。"
D.Strings[17457]="你是不是已经问过一次了？是啊！"
D.Strings[17458]="告……告诉我……基尔加丹是红色的吗？"
D.Strings[17459]="啊，当然。你做梦去吧。"
D.Strings[17460]="大概吧。"
D.Strings[17461]="显然。"
D.Strings[17462]="跳三次，然后扭摆十分钟，就行了！"
D.Strings[17463]="绝对是啊。"
D.Strings[17464]="是的，但并非你所想的那样。"
D.Strings[17465]="没错没错！我说了一千次了！"
D.Strings[17466]="是啦是啦，别烦我啦！"
D.Strings[17467]="如果你让我出去，我就回答“是”。"
D.Strings[17468]="就像我背上的瘤那样千真万确。"
D.Strings[17469]="我这里的答案是肯定的，到你那里就不知道了。"
D.Strings[17470]="一个字，“当然！”"
D.Strings[17471]="是的。但是我宁愿不用回答这个问题。"
D.Strings[17472]="过会再问我，我忙着抓鼻子呢，精神很难集中。"
D.Strings[17473]="为啥我一定要回答你的问题？你会在别人摇晃你的时候占卜吗？"
D.Strings[17474]="是的，今天会下雨。什么？你没有问这个问题？太遗憾了。"
D.Strings[17475]="抱歉，我只会讲恶魔语。"
D.Strings[17476]="是！我是说，不是！嗯……哪个答案可以让你同意把我放出来？"
D.Strings[17477]="可能也许大概是。"
D.Strings[17478]="区别不大，反正你明天就要挂了。"
D.Strings[17479]="你应该问“我背后那个盗贼是不是要杀了我？”"
D.Strings[17480]="我真希望自己的冷却时间更长一点。"
D.Strings[17481]="%s耸了耸肩。天知道！"
D.Strings[17482]="我每天都这样问自己……"
D.Strings[17483]="谢谢你，朋友。"
D.Strings[17484]="你让我们感到很荣幸，朋友。"
D.Strings[17485]="你为灵翼做的一切都不会被忽视的。"
D.Strings[17486]="你是我们永远的朋友！"
D.Strings[17487]="就像我妈妈常说的一样：[恶魔语] “Razxx khaj jhashxx xashjx。”"
D.Strings[17488]="%s无视你。"
D.Strings[17489]="为什么是我？为什么不是一个地精或者侏儒……"
D.Strings[17490]="扭曲虚空中发生的事，就在扭曲虚空了结吧。"
D.Strings[17491]="不要进行无意义的赌博。你的幸运数字是2，2.5和根号2。"
D.Strings[17492]="你不想知道吗？"
D.Strings[17493]="哦哦哦！我可以清晰地感觉到……呃，没了。"
D.Strings[17494]="我的契约上可没有这个！"
D.Strings[17495]="你在拿我寻开心么？"
D.Strings[17496]="你觉得我是哪种小鬼？"
D.Strings[17497]="说“请”。"
D.Strings[17498]="想交换一下地盘吗？"
D.Strings[17499]="是不是无论什么东西困在球里，你都会这样向它发问？"
D.Strings[17500]="嘿！你倒是试试在有混蛋摇你的房子时来摆放家具看看啊！"
D.Strings[17501]="一切皆有可能。你只需要在这里签个字……"
D.Strings[17502]="答案有些模糊且潮湿。请清理一下思维后再重试。"
D.Strings[17503]="集中注意力（把我从这个牢笼里放出来）然后再试试看。"
D.Strings[17504]="请投入25银币，然后再试一次。"
D.Strings[17505]="你是我的朋友吗，丹尼？"
D.Strings[17506]="你还记得上次自己做的傻事吗？"
D.Strings[17507]="行啦，别白费力气了！"
D.Strings[17508]="两个字：不可能！"
D.Strings[17509]="你需要去搞个奥术智慧效果了，难道答案还不明显吗？不！"
D.Strings[17510]="就算我不是个可以预知未来的小鬼，答案也是很明白的：不！"
D.Strings[17511]="成功的几率是百分之32.33（无限循环）。"
D.Strings[17512]="当黑石山冻成冰块的时候！"
D.Strings[17513]="哈哈哈哈，你在开玩笑对吧？"
D.Strings[17514]="我的线人说“不”。不过那是在动刑之前……"
D.Strings[17515]="这个可能性等同于我逃出这只球的可能性。"
D.Strings[17516]="你在错误的时间摇晃了我，伙计！准备失望吧。"
D.Strings[17517]="除非你是超人什么的。而且你也知道，你分明不是。"
D.Strings[17518]="这个可能性等同于我跟一位魅魔约会的可能性。"
D.Strings[17519]="我预知未来的能力趋于无穷大，不过你成功的机会趋于零。"
D.Strings[17520]="不可能——你继续摇我也不会改变这个答案。"
D.Strings[17521]="答案是肯定的……"
D.Strings[17522]="……不！"
D.Strings[17523]="答案很简单，看我口型：没门。"
D.Strings[17524]="前景不妙！哈哈哈哈！接受现实吧！"
D.Strings[17525]="调查结果表明：哼哼！"
D.Strings[17526]="非常好，入侵者。你吸引到了我的注意……"
D.Strings[17527]="看！为了这个时刻，我特地留下了我最喜欢的宠物。"
D.Strings[17528]="我来对付这些渣滓！进攻吧，朋友们！向伊利丹发起进攻！"
D.Strings[17529]="来吧，我的手下。让这个叛徒付出代价！"
D.Strings[17530]="你们这些乌合之众休想碰到我！"
D.Strings[17531]="我投降，我投降！！这次你赢了……"
D.Strings[17532]="打得好！"
D.Strings[17533]="你看那最后一击！真漂亮！"
D.Strings[17534]="这群肮脏的野兽！"
D.Strings[17535]="%s发出了一声刺耳的尖叫，呼叫周围的卡利鸟来帮忙。"
D.Strings[17536]="%s好像在和某个看不见的东西说话。"
D.Strings[17537]="扔手榴弹！"
D.Strings[17538]="猩猩宝宝"
D.Strings[17539]="现在我会变得更大，我会压碎你！"
D.Strings[17540]="球中的小鬼"
D.Strings[17541]="午餐篮"
D.Strings[17542]="我们要等多久？"
D.Strings[17543]="总有一天，我们会统治这座黑暗的神殿。"
D.Strings[17544]="哦，现在轮到$n了！"
D.Strings[17545]="手榴弹竟然在这种时候逆火，这蠢东西还真会挑时间啊！我受够了这些所谓的高品质地精工程学制品！"
D.Strings[17546]="幸运与我们同在！飞向天空吧！"
D.Strings[17547]="我有个建议，$r。请认真考虑你的选择——一旦做出抉择，就很难反悔了。$B$B你已经通过了忠诚的考验，现在是时候让你正式加入我们的组织了。我必须了解你希望以什么样的方式来为我们效力，以便我们为你提供适当的奖励。"
D.Strings[17548]="愚蠢的阿卡玛，你的生命已经到了尽头……"
D.Strings[17549]="让埃辛诺斯的烈焰吞噬你们！"
D.Strings[17550]="我们的研究完成了！干得好！总部会花大量精力来研究我们获得的测量数据。而且幸运的是，我们还揭开了巴什伊尔的阴谋。现在，启航！"
D.Strings[17551]="我雇佣贾兰娜对学徒进行基础训练，去和她谈谈吧。我想要将这家店铺的生意运转得越来越有效率，这样所有人——包括赞助者，都会对它表示尊敬。"
D.Strings[17552]="欢迎来到基伦的裁缝店，你可以在这里找到你需要的商品。如果你愿意向我讨教裁缝技能的话，和我说一声就成，我会很乐意教给你的。"
D.Strings[17553]="这里散发着污秽的恶臭，看来鸦人最近又堆积了新的战利品。"
D.Strings[17554]="<召唤猎手吉萨拉克。>"
D.Strings[17555]="如果你是在寻找零件、齿轮这种小玩意的话，那么你来对地方了！"
D.Strings[17556]="让我看看你都有些什么……呃，东西……"
D.Strings[17557]="熔炉需要额外的调整。去看看，奴隶！"
D.Strings[17558]="<召唤风怒者瓦克奇斯。>"
D.Strings[17559]="<召唤卡尔洛格。>"
D.Strings[17560]="<召唤黑暗尖啸者阿克卡莱。>"
D.Strings[17561]="你看上去很眼熟……"
D.Strings[17562]="你的骨头会变成我家爱狗最理想的玩具。"
D.Strings[17563]="我的预言梦境中充满了世界各地正在发生着和可能发生的事件的景象。它们大部分都非常可怕，不过，这未必是不可改变的。"
D.Strings[17564]="需要施法材料的话，你可来对了地方。即使找遍整个沙塔斯城，你也找不到更好的选择了。"
D.Strings[17565]="喝水中"
D.Strings[17566]="我来帮你了，老大！"
D.Strings[17567]="我来了，老大！"
D.Strings[17568]="看上去就很疼！"
D.Strings[17569]="修理模块已经激活！"
D.Strings[17570]="你……你是谁？？你想要什么？"
D.Strings[17571]="在我把你做成我护甲上的又一个装饰前，给我滚到一边去。你的领袖和我有事要商量……"
D.Strings[17572]="好……好……我们马上走开……请不要伤害我们……"
D.Strings[17573]="我还以为你认同我的观点……"
D.Strings[17574]="莫格霍尔大王，我想……能够和你攀上交情真是荣幸。"
D.Strings[17575]="我是女伯爵希奈丝特拉。"
D.Strings[17576]="我不想说太多废话，女伯爵希奈丝特拉。就直接告诉我你想从龙喉氏族这里得到什么吧。"
D.Strings[17577]="我相信你肯定已经听说了奈法利安在艾泽拉斯的失败……虽然他失败了，但实验仍然继续着。我的主人……他继续进行着他的儿子没能完成的研究。"
D.Strings[17578]="主……主人？他还活着？"
D.Strings[17579]="你曾是一位重要的军官，莫格霍尔。我们不会轻易忘记你在格瑞姆巴托所做的一切。"
D.Strings[17580]="现在……我们要你找回龙卵。灵翼龙卵。他们毕竟是主人的东西。无论你出多高的价钱，我们都会和你交换的。"
D.Strings[17581]="%s显得非常紧张，话都说不利索了。"
D.Strings[17582]="是……是，是的……当然，我们只需要这个地方的水晶和矿石。也就是说……我们需要坐骑。"
D.Strings[17583]="主人听到这个消息一定会很高兴的。黑龙军团会满足你的一切要求，必要的情况下，你可以骑我们的幼龙。"
D.Strings[17584]="感谢你的慷慨，莫格霍尔。但我现在必须走了。"
D.Strings[17585]="%s倒在了地上。"
D.Strings[17586]="我和你没完！"
D.Strings[17587]="你永远都别想活着离开这里！"
D.Strings[17588]="冷静！"
D.Strings[17589]="<玛德拉普正在擦着他的靴子。>"
D.Strings[17590]="$c，你的技艺进展得不错嘛，我认为时机已经成熟了。如果你想要进一步提升技能的话，就去幽暗城拜访乔瑟夫·格里高利吧。"
D.Strings[17591]="你在工程学上的造诣已经完全超越了我，我没有什么可以教你的了。我听说臭气熏天的奥格瑞玛里面有一位名叫罗克希克的工程师，他技艺精湛，应该能做你的老师。"
D.Strings[17592]="我不干活了！"
D.Strings[17593]="工作真没劲！我不做了！"
D.Strings[17594]="我有力气！但没人告诉我干什么！"
D.Strings[17595]="让我看看你有什么本事，$n！"
D.Strings[17596]="%s看见手中的盾牌破碎之后，更加恼怒了。"
D.Strings[17597]="哈哈！你放出了我的宠物！那么你的灵魂就是它的下一顿饭了。"
D.Strings[17598]="立正，步兵！"
D.Strings[17599]="哇！好吧，好吧。我回去工作！"
D.Strings[17600]="嘿！不要再用训诫靴踢我啦！对不起！我马上就干活！"
D.Strings[17601]="啊！训诫靴踢得我好疼！我觉得在训诫靴下会工作得更好！"
D.Strings[17602]="为什么用训诫靴踢我？？为什么？？"
D.Strings[17603]="啊！！训诫靴！！"
D.Strings[17604]="啊呀！总有一天我也要拿到训诫靴……"
D.Strings[17605]="不管你是谁，入侵者。我要惩罚你，作为一个警告！"
D.Strings[17606]="不自量力！"
D.Strings[17607]="你！就是你！我必须和你谈谈！"
D.Strings[17608]="无尽的诅咒等待着你，$r！这座监狱再也关不住我了！"
D.Strings[17609]="你无处可逃了，懦夫！"
D.Strings[17610]="灰舌破碎者们，你们的首领有话要说！"
D.Strings[17611]="背叛者不再掌控着我们的命运了，他施加在灰舌氏族灵魂上的邪恶魔咒已经消散了！"
D.Strings[17612]="从阴影中解脱吧！我将领导你们对抗真正的敌人。脱下你们的镣铐，拿起武器，去对抗你们的伊利达雷主人吧！！"
D.Strings[17613]="我把我的训诫靴弄丢了，玛德拉普。我想它可能卡在一个没用的苦工背上了。"
D.Strings[17614]="滚开，否则我就用训诫靴踢你。"
D.Strings[17615]="阿卡玛万岁！"
D.Strings[17616]="继续保持下去，步兵。"
D.Strings[17617]="为我们的首领欢呼！阿卡玛万岁！"
D.Strings[17618]="接收我的生命精华吧，主人！"
D.Strings[17619]="%s看到他的朋友们在战斗中倒下，变得愈加愤怒了！"
D.Strings[17620]="不要偷懒，像一个真正的邪兽人那样战斗！"
D.Strings[17621]="女侏儒都比你打得更狠！"
D.Strings[17622]="你把那个叫做进攻？连陆行鸟都比你更具有攻击性！"
D.Strings[17623]="要是你还不使出全力的话，就要被派去清扫一年的幼龙粪便！"
D.Strings[17624]="不要浪费我的感情了！"
D.Strings[17625]="哦，你喜欢我的眼罩呀？嗯，不过你还是别戴它的好。"
D.Strings[17626]="嗯？什么？我这里有点忙，朋友！$B$B当然，要是你是来帮忙的，我有着整个世界的时间。"
D.Strings[17627]="纠错信息：超出射程"
D.Strings[17628]="%s慢慢靠近，并安静地等待着。"
D.Strings[17629]="我也许老了，但是我仍然可以轻易超越像你这样傲慢的年轻人，$n。不要落在后面……"
D.Strings[17630]="好吧，我想你赢了……"
D.Strings[17631]="%s呼喊同伴来帮助自己！"
D.Strings[17632]="%s冲过去攻击$n！"
D.Strings[17633]="%s似乎已经做好被捕捉的准备了。"
D.Strings[17634]="水晶监牢开始破碎了！"
D.Strings[17635]="天空卫队来了！天空卫队来了！"
D.Strings[17636]="哦嚯！前进，天空卫队！"
D.Strings[17637]="哇哦！感谢你一路把我带回这里。你原本不需要这样做的。"
D.Strings[17638]="你真是个讨人喜欢的家伙。我保证会好好照顾这只以太鳐的。"
D.Strings[17639]="非常感谢你把它带回来。你会成为我最好的放牧者！"
D.Strings[17640]="噢，她是不是很漂亮啊？我等不及要好好训练她，与她一起在天空翱翔了！"
D.Strings[17641]="他是不是很可爱？！感谢你把他带回我这里！！！"
D.Strings[17642]="天空卫队需要长期补充以太鳐的储量。在你的帮助下，我们才能在天空翱翔。"
D.Strings[17643]="干得好！她各方面条件都挺不错的。谢谢你！"
D.Strings[17644]="哇！更多需要训练的虚空鳐！"
D.Strings[17645]="你竟敢召唤我，$n？"
D.Strings[17646]="棱柱中燃烧的眼睛让你感到恐怖……"
D.Strings[17647]="将35块埃匹希斯碎片放入棱柱中。"
D.Strings[17648]="邪能水晶熔炉可以将埃匹希斯碎片转化成不稳定的野兽合剂。这种合剂能让饮用者变得更加敏捷、强壮，并且更具活力。$B$B来吧，做出你的选择。"
D.Strings[17649]="用10块埃匹希斯碎片购买1瓶不稳定的野兽合剂"
D.Strings[17650]="<当你将埃匹希斯碎片放入邪能水晶熔炉并拉下控制杆后，从熔炉中传来了物体被碾碎的声音。很快一瓶合剂就从熔炉口落了出来。>"
D.Strings[17651]="利用邪能水晶熔炉制造另一瓶合剂。"
D.Strings[17652]="用50块埃匹希斯碎片购买5瓶不稳定的野兽合剂"
D.Strings[17653]="巴什伊尔水晶熔炉可以将埃匹希斯碎片转化成不稳定的巫术合剂。这种合剂能让饮用者变得更加聪明、更具活力，还可以增加法术伤害和治疗效果。$B$B来吧，做出你的选择。"
D.Strings[17654]="用10块埃匹希斯碎片购买1瓶不稳定的巫术合剂"
D.Strings[17655]="利用巴什伊尔水晶熔炉制造另一瓶合剂。"
D.Strings[17656]="<当你将埃匹希斯碎片放入巴什伊尔水晶熔炉并拉下控制杆后，从熔炉中传来了物体被碾碎的声音。很快一瓶合剂就落在了你的脚旁。>"
D.Strings[17657]="用50块埃匹希斯碎片购买5瓶不稳定的巫术合剂"
D.Strings[17658]="希望你能帮我们解决这件麻烦事。试想一下，如果你有10个儿子，他们都想尝试去做那些自己力所不能及的事，你该怎么办？$B$B尽管如此，我们却必须尽到做父亲的职责。"
D.Strings[17659]="你有孩子吗，$c？$B$B听我说，来到奥格瑞拉之后，我们都觉得没有以前快乐了。那些水晶让孩子们变得聪明了许多。从前，我们只需要敲打他们的小脑瓜就能让他们闭嘴。而现在，他们却整天吵着问我们各种各样关于天空卫队的事情。$B$B无知真是幸福！"
D.Strings[17660]="这孩子还是有些愚钝——看来他还需要接受水晶的启迪，不过，谢谢你为他制造了那些合剂。$B$B嗨！还有九个孩子需要你帮忙呢。$B$B<托尔库斯的两个脑袋都叹了口气。>$B$B想从我这里领走一个小孩吗？我愿意便宜卖给你。"
D.Strings[17661]="你刚来奥格瑞拉不久，这些水晶簇的好处你还没有完全体会到呢。何况，你只有一个脑袋。$B$B而我们就不同了。我们在这里住了很长一段时间了。因此，你可以想象我们聪明的头脑精通多少事情。$B$B最近，我们对铸魔营地的恶魔挺感兴趣的。具体来说，我们设计出了一个彻底摆脱他们的好办法。$B$B至少，理论上是那样。"
D.Strings[17662]="我们希望每天都能制造出一个以上的黑暗符印，但那样做太浪费时间了。从自然法则上来讲也办不到，而且我们的能力有限，这样的出产频率恐怕很难实现。$B$B只要有聪明的家伙愿意帮忙，我们就会将他们征召过来，以此获得更多的黑暗符印。"
D.Strings[17663]="巴什伊尔水晶熔炉可以将埃匹希斯碎片转化成不稳定的巫术合剂。这种合剂能让饮用者变得更加聪明，更具活力，还能增加法术伤害和治疗效果。$B$B但是10块埃匹希斯碎片才能购买1瓶合剂，你身上的碎片数量不够。"
D.Strings[17664]="邪能水晶熔炉可以将埃匹希斯碎片转化成不稳定的野兽合剂。这种合剂能让饮用者变得更加敏捷、强壮和更具活力。$B$B但是10块埃匹希斯碎片才能购买1瓶合剂，你身上的碎片数量不够。"
D.Strings[17665]="正在打开"
D.Strings[17666]="甘克和$r一样都是刚来奥格瑞拉的。这里就和下面那些食人魔所说的一样，真是天堂一般的地方。那些水晶簇让甘克变聪明了，但是也让甘克的脑袋很痛。$B$B<甘克的两个脑袋互相点着头。>$B$B我们正在学习制造晶铸黑暗符印。学会的话，就能粉碎恶魔的迁跃门了！"
D.Strings[17667]="甘克现在很聪明！我们知道如何将黑暗符印制成晶铸黑暗符印！"
D.Strings[17668]="$n破坏了迁跃门，做得好！但是恶魔又修复了被毁坏的迁跃门。$B$B$n，只要你给甘克另一枚黑暗符印，甘克就为你制作晶铸黑暗符印！"
D.Strings[17669]="欢迎来到奥格瑞拉，$c。$B$B食人魔通过奥格瑞拉周围的水晶簇散发出的魔力获得了敏锐的才智。尽管我们不完全明白这是怎么回事，但我们喜欢这个新家，只想在这里过安宁的生活。$B$B可是恶魔、虚灵，还有黑龙却偏偏要来滋扰生事。"
D.Strings[17670]="我代表奥格瑞拉对你的所做的一切表示感谢，$n。$B$B<库洛尔的左边脑袋点着头，右边脑袋则对着你微笑。>$B$B不要忘了，帮助奥格瑞拉就是帮助我们在刀锋山的食人魔同胞。为了表达对你的敬意，他们已经将你奉为$g国王:女王;。"
D.Strings[17671]="我们什么时候再去弄些不可思议的合剂？"
D.Strings[17672]="那些合剂的数量足够我们加入天空卫队吗？"
D.Strings[17673]="天空卫队需要我们的帮助！我们需要更多不可思议的合剂。"
D.Strings[17674]="我们等不及想加入天空卫队了。我们只是需要更多不可思议的合剂而已，对吗？"
D.Strings[17675]="凭你的能力，还不够资格参加晋级赛。不过你可以找竞技场管理员谈一谈，参加一些练习赛。训练永远都不会嫌太晚的。"
D.Strings[17676]="看，是天空卫队！"
D.Strings[17677]="你要伤害我吗？我可不想和战争扯上关系，$r。$B$B我只是个体弱多病的学者，请你别来打扰我！"
D.Strings[17678]="这枚龙卵看上去和正常的黑龙卵一样富有弹性。如果你在它附近放上一些埃匹希斯碎片，它们的震动或许能让龙卵裂开？"
D.Strings[17679]="这枚龙卵看上去和正常的黑龙卵一样富有弹性。如果你在它附近放上一些埃匹希斯碎片，它们的震动或许能让龙卵裂开？$B$B可惜这样做需要35块埃匹希斯碎片，你身上没有足够的水晶。"
D.Strings[17680]="将35块埃匹希斯碎片放在龙蛋附近使其碎裂。"
D.Strings[17681]="<当你将埃匹希斯碎片放在龙蛋附近后，它们发出嗡嗡的蜂鸣声。片刻之后，龙蛋粗糙的外壳出现了一道裂缝，一只黑龙幼崽破壳而出，尖叫着呼喊它的母亲。>"
D.Strings[17682]="<安吉拉在地狱猎犬耳边低语着什么，直到她留意到你。>$B$B和其它地狱猎犬相比，基尔西的体型显得娇小许多，但是这并未影响到它。我相信外域会改变这一切的，基尔西，对吧？$B$B妈妈的小天使一定会成长为一头巨大凶猛的地狱猎犬！一定！"
D.Strings[17683]="特罗普会让你见识到龙喉兽人飞翔的英姿……而你就让特罗普看看没用的渣滓是怎么死的吧。"
D.Strings[17684]="你干得不错。让特罗普吃了一惊……向亚恩报告吧。"
D.Strings[17685]="%s尖叫着呼唤它的母亲。"
D.Strings[17686]="让我们搞定这里的事情吧……"
D.Strings[17687]="菜鸟，你打得真烂。真是烂到渣了……"
D.Strings[17688]="这让我回忆起了过去的时光。我扮演联盟，你则防守霜狼村。投弹完毕！"
D.Strings[17689]="感谢你……这可真令我感到羞耻。"
D.Strings[17690]="这趟飞行之旅可能不太安全，$n。希望你已经安排好了后事。"
D.Strings[17691]="你是我见过的最棒的飞行员。真不敢相信我竟然说出这样的话，但是你很可能和汤告鲁士·碎空不相上下哦。还有，要是刚才的进展不是特别顺利的话，你就是我的飞行员了……"
D.Strings[17692]="%s尖叫着呼唤它的父亲。"
D.Strings[17693]="<当你将埃匹希斯碎片放在龙蛋附近后，它们发出嗡嗡的蜂鸣声。片刻之后，龙蛋粗糙的外壳出现了一道裂缝，一只黑龙幼崽破壳而出，尖叫着呼喊它的父亲。>"
D.Strings[17694]="穆维里克！！！"
D.Strings[17695]="准备好葬礼的火堆！$n向汤告鲁士·碎空发起挑战了！"
D.Strings[17696]="我……我败了……$n才是最优秀的兽人！"
D.Strings[17697]="我为你悲叹，$n。你根本不明白自己陷入了怎样的窘境……"
D.Strings[17698]="要不是塞纳里奥远征队，我肯定早就葬身矿洞了……是他们救了我的命！因此，我为塞纳里奥远征队的盟友们提供修理装备以及出售施法材料的服务。"
D.Strings[17699]="我是塞纳里奥远征队的盟友，莫尔托格。让我看看你出售的货物。"
D.Strings[17700]="我很久没有遇到过旗鼓相当的对手了……"
D.Strings[17701]="他们成功了！敌人已被击溃！返回基地！"
D.Strings[17702]="放弃任务！我们的地面部队已经落败。"
D.Strings[17703]="发现敌人！改变阵型，准备轰炸！"
D.Strings[17704]="你在这里可以找到很多事情做，$n。"
D.Strings[17705]="战斗姿态！准备发动冲锋！"
D.Strings[17706]="嗨，你最近挺忙的是吧？！你不仅帮助我们轰炸恶魔，还替我们捕捉虚空鳐，我都不知道该怎么感谢你。$B$B你让我们的工作轻松了许多。继续保持下去吧！"
D.Strings[17707]="狂暴姿态！无情地攻击他们！"
D.Strings[17708]="防御姿态！用盾牌挡住攻击，然后迅速反击！"
D.Strings[17709]="合剂都准备妥当了，我们要让天空卫队看看我们的决心。"
D.Strings[17710]="天空卫士，当心！托尔库斯二世来了！"
D.Strings[17711]="指挥官阁下！托尔库斯二世向你报告！"
D.Strings[17712]="听我说。我钦佩你做出的贡献，但我不知道该怎么说……你，你是个食人魔，孩子。"
D.Strings[17713]="是，长官。我是食人魔，但是请您给我们一个机会吧！自从我们第一次看见天空卫队在奥格瑞拉上空飞翔，就憧憬着这一刻的到来！"
D.Strings[17714]="%s做了个解散的手势，然后走向发射台。"
D.Strings[17715]="当%s意识到食人魔在想什么时，它畏缩了。"
D.Strings[17716]="我们必须在矿洞附近重建我们的要塞！"
D.Strings[17717]="<暗血监工咕哝着。>"
D.Strings[17718]="他们派你来杀我的吧，嗯？我早就猜到了……被恐怖支配的生物都一样。$B$B不过你……你和他们不一样……"
D.Strings[17719]="我是为你而来的，监工。"
D.Strings[17720]="你竟敢质问一个龙喉督工！"
D.Strings[17721]="督工？$B$B你不是龙喉督工，正如我不是暴风城的国王一样。对……你就是他们提起的那个家伙。"
D.Strings[17722]="灵翼龙族。他们说愿意保护破碎者氏族，让我们享受未曾体验过安宁与和平。我们决定接受龙族的恩惠，帮助托兰纳古唤醒了那些居住在矿洞中的生物，并为此付出了巨大的代价。在这场骚乱中，很多兄弟不幸遇难。我们计划让矿洞变成不适合居住的废墟，以此迫使龙喉兽人离开这座岛屿。"
D.Strings[17723]="谁提到了我？你在说什么，破碎者？"
D.Strings[17724]="龙喉氏族已经堕落了。他们在岛上疯狂地开采天然资源，并利用这些资源支援伊利丹派驻在黑暗神殿外的军队。当然，他们将大部分资源据为己有，而且把私藏的资源出售给出价最高的人。"
D.Strings[17725]="这些出价者是谁？"
D.Strings[17726]="我们不知道。但我们相信黑龙一族以独立的第三方身份参与了此事。这就是你来这里的目标，$r。你要抽丝剥茧般地揭开这个秘密，让灵翼龙族重获自由。$B$B那么……我想矿洞女王要求你带回我的手吧。"
D.Strings[17727]="呃……是的。"
D.Strings[17728]="如果它能换来龙喉氏族的衰落，我很乐意做出这样的牺牲。"
D.Strings[17729]="啊！如果我必须死，我会与你同归于尽！"
D.Strings[17730]="嗨，伙计！别挑布隆库！他还没有被驯服！你骑上去的话很可能会没命的！"
D.Strings[17731]="布隆库猛然一跃，将%s摔了下来，然后逃进了荒野中！"
D.Strings[17732]="恐惧之喉！你会付出昂贵的代价，入侵者……"
D.Strings[17733]="我必须马上离开这个地方！"
D.Strings[17734]="布隆库？听上去不错！"
D.Strings[17735]="我觉得你没把我的话听进去。虚空鳐并不是最理想的——"
D.Strings[17736]="埃匹希斯圣物闪着微光，似乎里面隐藏着什么东西。"
D.Strings[17737]="插入1块埃匹希斯碎片，然后开始！"
D.Strings[17738]="回来吧，布隆库先生！让我们一起加入天空卫队！"
D.Strings[17739]="你隐约看见了前方的埃匹希斯纪念碑。"
D.Strings[17740]="插入35块埃匹希斯碎片，然后开始！"
D.Strings[17741]="感谢你为我们提供了合剂。"
D.Strings[17742]="别打扰我！绝对不能出现任何偏差！"
D.Strings[17743]="谢谢你。我们离开这里吧！"
D.Strings[17744]="%s朝托尔库斯二世发出嘶嘶的叫声。"
D.Strings[17745]="立正，队长！"
D.Strings[17746]="继续前进。我不喜欢这个地方。"
D.Strings[17747]="再次谢谢你。如果杜尔因上尉得知本周能少替换一名斥候的话，他肯定会很高兴的。"
D.Strings[17748]="棱柱中燃烧的眼睛让你感到恐怖……召唤它需要35块埃匹希斯碎片，而你身上没有足够的水晶。"
D.Strings[17749]="我准备好面对挑战者了！叫他出来吧！"
D.Strings[17750]="胡说！"
D.Strings[17751]="这一下是为了娜萨！"
D.Strings[17752]="你无处可逃了，天空卫队的渣滓！"
D.Strings[17753]="没有人可以逃出斯克提斯！"
D.Strings[17754]="通往欢愉之园的大门打开了。"
D.Strings[17755]="你这个小家伙，害我看走了眼。$B$B我猜你是来购买我出售的特殊货物的吧？"
D.Strings[17756]="直视背叛者的双眼吧！"
D.Strings[17757]="太轻松了！"
D.Strings[17758]="谁想成为下一个？"
D.Strings[17759]="你们对力量一无所知！"
D.Strings[17760]="控制器可以激活关联的质子加速器。激活操作将召唤出一名巴什伊尔先驱者，或许就是巴什伊尔本人。$B$B当然，前提是你有加速器模组来激活这台设备。"
D.Strings[17761]="控制器可以激活关联的质子加速器。激活操作将召唤出一名巴什伊尔先驱者，或许就是巴什伊尔本人。$B$B可惜，你没有加速器模组来激活这台设备。"
D.Strings[17762]="利用加速器模组为质子加速器充能，然后召唤巴什伊尔或者一名巴什伊尔先驱者。"
D.Strings[17763]="<你将加速器模组放入控制器上的凹槽中，然后拉下控制杆。模组顿时散发出光芒，它的能量随着机械的蜂鸣声转化为了动力。>"
D.Strings[17764]="你赢了……玛维。但是……一个没有目标的猎手……什么都不是。你……离开了我……什么都不是。"
D.Strings[17765]="结束了。你被打败了。"
D.Strings[17766]="他说得对。我觉得很失落……我……什么都不是。"
D.Strings[17767]="再会，勇士们。"
D.Strings[17768]="下次给我放尊重点，至少先准备好再来向我挑战！"
D.Strings[17769]="可怜虫！我要让你尝尝粉身碎骨的痛苦！我要毁灭你的灵魂！"
D.Strings[17770]="你还真以为我的主人会落入你设计的小圈套，$n？"
D.Strings[17771]="蠢货！"
D.Strings[17772]="圣光会再次照耀这阴暗的大厅……我发誓。"
D.Strings[17773]="别理会维克斯顿的话。你想要好东西？那就和克里希谈一谈。如果你的声望够高的话，我正好有你需要的货物。孩子，你要明白，竞技场上的懦夫是没有资格拥有这些东西的。"
D.Strings[17774]="我想加入斗兽场队列，鲁克斯特。"
D.Strings[17775]="<Flaskataur拍打着他巨大的双翼。>"
D.Strings[17776]="那些玷污这座神殿的家伙已经全部被打败了。除了一个人之外！"
D.Strings[17777]="伟大的Flaskataur，让我购买你出售的货物吧。"
D.Strings[17778]="让我们结束这一切吧。当你恢复了全部的力量之后，我会带你去伊利丹的居所。"
D.Strings[17779]="是面对伊利丹的时候了，$n。你准备好了吗？"
D.Strings[17780]="我准备好了，阿卡玛。"
D.Strings[17781]="%s变得越来越愤怒了！"
D.Strings[17782]="我准备好进入黑暗神殿了，约翰尼。"
D.Strings[17783]="欢迎你，朋友！你想看什么？"
D.Strings[17784]="你好，朋友。我们能帮你什么忙吗？"
D.Strings[17785]="我们能帮你什么忙吗？"
D.Strings[17786]="勇士！我们能帮你什么忙吗？"
D.Strings[17787]="你来到这里真是我们的荣幸，朋友。我们能帮你什么忙吗？"
D.Strings[17788]="勇士！希望你喜欢我们的食物。"
D.Strings[17789]="我们的食物能令最强大的勇士赞不绝口。"
D.Strings[17790]="还是很饿吗，朋友？我们能帮你什么忙吗？"
D.Strings[17791]="朋友，我们为你准备了一顿美餐。"
D.Strings[17792]="我们能为你提供什么美味吗？"
D.Strings[17793]="%s阵亡了。"
D.Strings[17794]="%s再次站起来投入战斗！"
D.Strings[17795]="你不是孤身一人，阿卡玛！"
D.Strings[17796]="你的人民永远和你在一起！"
D.Strings[17797]="嘿，朋友。如果你和天空卫队搞好关系的话，我就为你开通前往鸦羽山黑风码头的直达航线。$B$B你喜欢这只漂亮的虚空鳐吗？它真可爱。"
D.Strings[17798]="我一个人无法获胜……"
D.Strings[17799]="你好，$n。要赶去我们位于鸦羽山的基地黑风码头吗？我为你准备了一只漂亮的小虚空鳐。$B$B现在就出发吗？和我说一声就成！"
D.Strings[17800]="是，我愿意乘坐虚空鳐飞往黑风码头。"
D.Strings[17801]="你好！如果你想要飞往刀锋山的天空卫队哨站的话，我可以为你准备一只虚空鳐。$B$B和我说一声就成。"
D.Strings[17802]="你好。如果你在沙塔尔天空卫队的声望再提升一点，我就为你开通前往刀锋山天空卫队哨站的直达航线。"
D.Strings[17803]="当然！送我回天空卫队哨站吧。"
D.Strings[17804]="我感谢你们的帮助，兄弟们。我们的人民会报答你们的！"
D.Strings[17805]="你这渣滓，你希望怎么解决此事？"
D.Strings[17806]="碾碎你就象捏死一只虫子那样简单！"
D.Strings[17807]="你让我很生气，凡人！"
D.Strings[17808]="我会把你劈成两半的！收敛点，蠢货！"
D.Strings[17809]="现在就逃吧，趁你还活着的时候逃走吧！"
D.Strings[17810]="理智点！想要阻止燃烧军团？别做白日梦了！让我们用文明的方式来探讨这个问题。我能赐予你连做梦都不敢想的强大的力量！"
D.Strings[17811]="在我们和伊利丹之间就只剩下这扇门了。站开点，朋友们。"
D.Strings[17812]="遗忘魔焰裁缝专精并不是件轻松的事。如果你选择放弃，那么你就会忘记所有与魔焰裁缝专精相关的图样！"
D.Strings[17813]="我们会为你奉上秘制饮品：鸡尾酒和梦想。至少我们能帮你实现其中一项。"
D.Strings[17814]="我想遗忘魔焰裁缝专精。"
D.Strings[17815]="所有人都要喝酒。我们能为你做些什么呢？"
D.Strings[17816]="遗忘你已经学会的知识需要一大笔钱，而且这并不是件容易的事。你真的希望付这笔费用吗？"
D.Strings[17817]="你好，朋友。我们能为你做些什么吗？"
D.Strings[17818]="我们的美酒能滋润最干涸的喉咙。"
D.Strings[17819]="除了和我闲聊，你就没有别的事可做了吗？$B$B拿出你的勇气来！"
D.Strings[17820]="这样就对啦！我们为你所做的一切感到光荣！$B$B如果你想要前往我们在鸦羽山的另一处基地，就和天空卫队训练师伊雷娜谈一谈吧。她会很乐意为你安排的。"
D.Strings[17821]="你受到了大家的尊敬，朋友！要不是我明白事理的话，肯定会以为你想抢我的饭碗！！！$B$B只要你像之前那样继续帮助我们，你就值得受到这样的尊重！"
D.Strings[17822]="要么饮酒，要么滚开！"
D.Strings[17823]="我还能说什么，$n？你是最棒的沙塔尔天空卫士！$B$B别被溢美之词冲昏了头脑。我还有别的东西可以教给你！$B$B<天空指挥官凯勒对你咧嘴一笑，眨了眨眼睛。>"
D.Strings[17824]="我知道你耗费了不少精力来帮助我们，$c。$B$B新手，继续努力吧，歼灭所有的恶魔！"
D.Strings[17825]="哨站的每个人都在提起你的名字。别因此沾沾自喜，我知道你能做得更好！$B$B我会继续关注你的，新手。"
D.Strings[17826]="尊敬的勇士，我们能帮你什么忙吗？"
D.Strings[17827]="好吧，我承认。$n，你已经证明了自己的实力。$B$B如果说我之前对你太过严厉的话，那也是因为我发现你具备一名优秀的天空卫士的潜质。我敢说你就是我们的王牌飞行员！$B$B任何时候你想来帮忙都成，我会为你准备好一组炸弹的。"
D.Strings[17828]="我们很高兴为你提供补给。"
D.Strings[17829]="嗨，$c！$B$B<卡提害羞地看着你。>$B$B如果你愿意为我们捕捉更多的以太鳐，可以随时过来找我！"
D.Strings[17830]="朋友！好久不见！我们能为你做些什么吗？"
D.Strings[17831]="你知道吗，$n，很荣幸能和你一起共事！$B$B当你闲下来的时候，或许我们可以共进晚餐？$B$B哦，我们为你开通了前往鸦羽山基地的直达航线，我有没有告诉你这件事啊？如果你想去那里的话，就与天空卫队训练师伊雷娜谈一谈。"
D.Strings[17832]="这么说，你常来这附近，可惜闲暇时我们总是没机会聚聚。$B$B我说得对吗？$B$B<卡提故意流露出振奋的神情。>$B$B不管怎样，我都想告诉你，我……我们真的非常感谢你为天空卫队所做的一切！"
D.Strings[17833]="希望你没把我当做马屁精之类的家伙，$n。$B$B我的意思是，我知道你在天空卫队享有很高的声誉，嗯……我想你大概不会愿意和我这样地位卑微的工人呆在一起。$B$B不过，如果你想出去逛逛，或是一起捕捉以太鳐什么的，随时来找我！我等着你。$B$B我真想你……"
D.Strings[17834]="这些圣物伟大而神秘。如果能系统地研究它们，或许就能揭示它们蕴藏的真正力量。"
D.Strings[17835]="<库洛尔的左脑袋在说话。>$B$B你如此热情地帮助我们，真是令人感动呀……$B$B<他的右脑袋作着结论。>$B$B……因此我们想让你知道，我们非常感谢你所做的一切！"
D.Strings[17836]="尊贵的英雄，钢铁远没有血肉之躯来得强壮。唯有持有者才能令钢铸武器的效力发挥到极致。嗯，不说这些了……我们能帮你什么忙吗？"
D.Strings[17837]="人们已经开始对你表示崇敬了。$B$B<库洛尔的左眼凝视着你，折射出冷漠的目光。>$B$B继续加油，$n！"
D.Strings[17838]="首先你成为了刀锋山食人魔的$g国王:女王;，接着又赢得了奥格瑞拉食人魔的尊敬。$B$B从来没有哪个$r能取得这样的成就，你简直是活生生的例证。$n，谢谢你，我们欠你的永远都无法偿还！"
D.Strings[17839]="一生当中能信任的东西可不多。钢铁就是其中之一。"
D.Strings[17840]="我们食人魔能得到你这样一位$r的帮助，我感到十分荣幸。你让我们重新拥有了一个光明的未来。$B$B现在，我们只需要处理掉这些剩下来的头疼事务就好了。不过，你确认不想要领养一个我们的孩子吗？"
D.Strings[17841]="和钢铁比起来，铸钢者的双手是不是更厉害呢？"
D.Strings[17842]="你给予了我们这么多帮助，真是令我们感到惊讶。要是没有你，我们肯定早就被恶魔或是黑龙给撵出了家园！$B$B顺便说一句，我们提过想要将一个孩子便宜卖给你，对吧？不要？你不感兴趣吗？"
D.Strings[17843]="在奥格瑞拉这里，我们有足够的时间来沉思有关钢铁的秘密。不过这都是另一个话题了……有什么我可以为你效劳的吗？"
D.Strings[17844]="需要我为你铸造钢铁武器吗？"
D.Strings[17845]="$n，你慷慨地帮助我们，使我们一家子过得其乐融融，我们真不知道要怎么感谢你才好。 $B$B嗯，我们之前开玩笑说要把其中一个小孩卖给你，你没有当真吧？我们真的是在开玩笑呃……虽然这群小子不断地制造麻烦。$B$B嘿，你们就不能安静点吗？！"
D.Strings[17846]="我们有点开始喜欢小$n了！你好厉害！连恶魔也能打赢！"
D.Strings[17847]="甘克喜欢小$r$n。你杀死了大恶魔，让所有小恶魔们感到害怕！$B$B<甘克的两个脑袋都在对着你笑。>"
D.Strings[17848]="我们永远欢迎你来这里！$B$B库洛尔说$r是我们的英雄！$B$B$n现在就像是我们食人魔的一员了。但是，甘克搞糊涂了，因为他觉得$n需要再长大点。"
D.Strings[17849]="我们能为你做些什么吗，尊贵的$G兄弟:姐妹;？"
D.Strings[17850]="你会为此后悔的，凡人！雷萨赫尔顿会回来的……我要复仇！"
D.Strings[17851]="麻鹰被证明在搜索乌鸦石方面是非常有天分的，因此观察者艾莱亚训练了另一只麻鹰远程传递我的声音。当你研究显现在石板上鸟的灵魂时，它可以帮助我们进行联络！"
D.Strings[17852]="尊敬的$G兄弟:姐妹;，我们能帮你什么忙吗？"
D.Strings[17853]="你好，朋友！我们能帮你什么忙吗？"
D.Strings[17854]="我们是来帮忙的。"
D.Strings[17855]="你在这里的知名度已经相当高了，$r。这是件好事。$B$B我相信你不会被溢美之词冲昏了头脑，你会继续帮助我们放逐恶魔的，对吗？"
D.Strings[17856]="你的无私让我们感到无地自容，$n。先前，我们确实有点自以为是，但是你让我们彻底改变了态度。$B$B谢谢你，希望你会继续帮助我们对抗铸魔营地。"
D.Strings[17857]="到这里来重新调整水晶熔炉。"
D.Strings[17858]="你总算露面了！那座熔炉已经坏掉快一小时了！"
D.Strings[17859]="蠢货，你们都干了些什么？"
D.Strings[17860]="白痴！为什么我们必须忍受你们的愚蠢？"
D.Strings[17861]="你可耻地败了！我要延长你一年的奴役期限！"
D.Strings[17862]="你在奥格瑞拉过得很愉快吧？$B$B我们有许多手工打造的好东西。我们挑选出最好的货物，准备出售给你这样酷毙了的客人！$B$B嗯，在你外出执行任务、确保奥格瑞拉安全的同时，有空的时候可以顺路过来看看我们出售的货物。$B$B朋友，祝你好运。"
D.Strings[17863]="游侠们，听好了！让那些野蛮的巴什伊尔恶魔尝点苦头。我们的任务很简单，尽可能地坚守这片区域，获取他们的新技术的准确读数。"
D.Strings[17864]="别低估我们的敌人。我们是主动挑衅的入侵者，他们已经被逼得无路可走了。这帮家伙必定会奋起反抗的。"
D.Strings[17865]="我们是天空卫士！这就是我们受训的目的。绝不退缩，绝不投降。哪怕明知是去送死，我们也会毫不犹豫地执行使命！宁愿战死沙场，也不会透露那份情报。"
D.Strings[17866]="还有谁对此有疑问吗？"
D.Strings[17867]="你很快就能查明真相！"
D.Strings[17868]="天空卫队游侠，准备起飞！！"
D.Strings[17869]="朋友，我只想知道一件事，他们在哪里。"
D.Strings[17870]="你想要什么？"
D.Strings[17871]="我是巴塔斯的特使。他派我来收集一份完美的奥术精华。"
D.Strings[17872]="霍纳斯，让我看看你出售的货物。"
D.Strings[17873]="天空指挥官凯勒，我不喜欢这件死亡之翼血脉披风。"
D.Strings[17874]="你不喜欢这件披风？但是你费了这么大力气才搞到手呢！嗯，好吧，如果你愿意的话，我就以适当的价格收购它。$B$B用一块埃匹希斯水晶做为交换怎么样？"
D.Strings[17875]="<莫格霍尔大王向你敬礼。>"
D.Strings[17876]="防御部队，让这帮渣滓尝尝占星者的愤怒！"
D.Strings[17877]="士兵们，奋勇作战吧！不要对敌人手下留情！"
D.Strings[17878]="<召唤泰罗克。>"
D.Strings[17879]="听起来不错嘛。"
D.Strings[17880]="你确定吗，朋友？成交之后一概不予退换哦。"
D.Strings[17881]="是的，我确定。我想用这件死亡之翼血脉披风换取一块埃匹希斯水晶。"
D.Strings[17882]="很好，我相信别的天空卫士一定能用得着这件披风的。$B$B给，这是你的埃匹希斯水晶。希望它能令你满意。"
D.Strings[17883]="是谁把我召唤到了这个世界？星阵尚未排列成线……我的力量还没有完全恢复！你会为此付出代价的！"
D.Strings[17884]="安静点，孩子，还轮不到你呢。你就呆在这里，见证即将发生的事吧。"
D.Strings[17885]="嘿，$n，只要你继续努力的话，我们出售的货物就任你挑选。这有点像是因果报应的说法吧。$B$B那么，请尽力帮助我们以及北边的天空卫队吧。$B$B嗯……谢谢你！"
D.Strings[17886]="库洛尔在我面前为你说了一堆好话，$n。怎么样，我们还出售一些特别的食人魔美酒哩。$B$B它们都是非常美味的！"
D.Strings[17887]="你在这里很受尊敬，朋友。好像每个人都在说起你。真酷。$B$B请随便看看吧，说不定有你感兴趣的东西呢。我们有很多上等货。"
D.Strings[17888]="还有什么好说的呢，$n？伙计，你可以随意选购店里的商品！$B$B对极了！"
D.Strings[17889]="那是个危险的想法。要是真的出了差错，索莉多米肯定会第一个察觉的。"
D.Strings[17890]="你觉得关于永恒龙族的传言是真的吗？我觉得听上去……挺耳熟的。"
D.Strings[17891]="我喜欢看他们那样做。"
D.Strings[17892]="哦，你想来点这个，是吗？"
D.Strings[17893]="哈哈，来吧！"
D.Strings[17894]="把这里夷为平地！"
D.Strings[17895]="%s吃着刚被杀死的迁跃追迹者。"
D.Strings[17896]="我想遗忘暗纹裁缝专精。"
D.Strings[17897]="我想遗忘月布裁缝专精。"
D.Strings[17898]="遗忘魔焰裁缝专精并不是件轻松的事。如果你选择放弃，就会遗忘所有与魔焰裁缝专精相关的图样！$B$B你真的确定吗？"
D.Strings[17899]="遗忘暗纹裁缝专精并不是件轻松的事。如果你选择放弃，就会遗忘所有与暗纹裁缝专精相关的图样！$B$B你真的确定吗？"
D.Strings[17900]="遗忘月布裁缝专精并不是件轻松的事。如果你选择放弃，就会遗忘所有与月布裁缝专精相关的图样！$B$B你真的确定吗？"
D.Strings[17901]="占星者胜利了！龙喉氏族被打败了！"
D.Strings[17902]="我们……失……败……了。"
D.Strings[17903]="接受圣光的制裁吧！"
D.Strings[17904]="面对圣光的愤怒吧！"
D.Strings[17905]="制裁之锤将审判你的罪行！"
D.Strings[17906]="滚开！你别想从我这里得到任何东西。"
D.Strings[17907]="我可以帮你纠正你的错误。"
D.Strings[17908]="你在等我的先驱者吗？"
D.Strings[17909]="或许我可以剥下你的皮，然后拿到市场上叫卖。不过还是算了吧，你这身臭皮囊看上去就不值几个钱。"
D.Strings[17910]="你是在什么地方找到激活控制器的模块的？不过无所谓，反正你没有机会再来捣乱了。"
D.Strings[17911]="主人很忙，我倒是有空陪你玩玩！"
D.Strings[17912]="巴什伊尔对他不能与你交手表示遗憾，不过他派我来舒缓你失望的情绪。"
D.Strings[17913]="你知道你正在干什么吗，$n？过来，让我好好教育一下你和你的朋友们。"
D.Strings[17914]="我还要为主人打点别的事务。我们来个速战速决怎么样，这样我就能做自己的事情了。"
D.Strings[17915]="你靠这个东拼西凑而成的破玩意启动了加速器？"
D.Strings[17916]="$n，让我给你点建议：夹起尾巴滚回山谷中的安全地带吧。"
D.Strings[17917]="你觉得自己本事够大，能从我手里抢走东西吗？"
D.Strings[17918]="蠢货太多，时间太少！"
D.Strings[17919]="哟，一位$c和$g他:她;的朋友……真是有趣。这应该不会花太长时间的。"
D.Strings[17920]="你连最简单的附魔技能都没有学会呢。请你先去向多洛索斯请教吧。"
D.Strings[17921]="别哭啊，$n。很快就会结束了。我保证不往你的尸体上吐口水。"
D.Strings[17922]="我已经没有什么新知识可以教给你了，如果你想要进一步提升自己的技能，就需要学会分解这些精美衣物的方法。赫加斯是位精通附魔学的大师，他就隐居在石爪山脉烈日石居背后的山上，去向赫加斯讨教吧。"
D.Strings[17923]="必须阻止龙喉氏族……"
D.Strings[17924]="今天你想从我这里学到什么新知识呢？"
D.Strings[17925]="可笑的家伙，你最好向那边的塔尔玛讨教几招，在你学会如何正确地加工皮革之后再回来找我吧。还有，你制作出来的皮革真难闻。"
D.Strings[17926]="我比你想象的要年长得多，给我放尊重点！"
D.Strings[17927]="我要吞噬你的肉体！同样，燃烧军团也将毁灭你的族人！"
D.Strings[17928]="说起制革，有谁能比得上整天披着一身好皮的牛头人呢？要知道，哪怕他们遭遇不测，也能从自己身上剥下优质的皮货来。如果你能忍受恶臭的话，就去雷霆崖找犹纳吧，她可以教你更多关于制造皮革的知识。"
D.Strings[17929]="过来，过来。要是你已经准备好了上好的皮革，我会让你看看怎么制作有用的物品。"
D.Strings[17930]="我会让你死个痛快的，$n。"
D.Strings[17931]="你为什么不先去米尔温多那里磨炼下自己的技术呢？他会很乐意为你传授基础知识的。"
D.Strings[17932]="让你信奉的神灵来怜悯你吧，因为我是不会对你有哪怕一丝怜悯的。"
D.Strings[17933]="我听说，海对面有个名叫萨鲁·钢怒的铁匠大师。如果你想要继续提升你的技能，就去奥格瑞玛的铁匠铺找他吧，$c。祝你好运。"
D.Strings[17934]="离我远点！！！"
D.Strings[17935]="想死是吧？"
D.Strings[17936]="你想考验我？"
D.Strings[17937]="勇敢的尝试。"
D.Strings[17938]="拜托。如果你一定要这么做的话，还是让拉斯亚来看看你做出的劣等药剂吧。等你能制作……更有效力的药剂之后，再回来找我。"
D.Strings[17939]="华丽的击杀！"
D.Strings[17940]="你们的死期即将到来，$n。尽情享受生命的最后一刻吧。"
D.Strings[17941]="算……算你走运。"
D.Strings[17942]="你们完全不够格。"
D.Strings[17943]="我闻到了你浑身散发着的臭气，渺小的$n。在这里，在我的地盘中，你将永远长眠。"
D.Strings[17944]="你们想要杀了我？你们先死吧！"
D.Strings[17945]="被遗忘者配制出的药剂非常强劲，你不觉得吗？我相信，他们以自身为实验品，经历无数次失败才取得了如此伟大的成就。当然你很幸运，赫伯特·哈尔希医生已经完成了所有必要的研究，你只需去拜访他就行了。"
D.Strings[17946]="我对这些无意义的干扰感到厌烦了。你的死期到了，$n！"
D.Strings[17947]="逃吧，否则就来受死！"
D.Strings[17948]="我的使命完成了。"
D.Strings[17949]="天空卫队会为你的鲁莽付出代价的，$n！"
D.Strings[17950]="命运……在等待。"
D.Strings[17951]="没有第二次机会了！"
D.Strings[17952]="为了奎尔萨拉斯！为了太阳之井！"
D.Strings[17953]="我觉得今晚我能享用一顿用$r和食人魔烹制的美餐。"
D.Strings[17954]="我有很多惊喜要给你们！"
D.Strings[17955]="渺小的$r，现在就让你尝尝我的怒火！"
D.Strings[17956]="你竟敢召唤我？傲慢的家伙，你会受到惩罚的。"
D.Strings[17957]="嗨，$r。今天你对什么感兴趣呀？"
D.Strings[17958]="奥尔多会获胜的！"
D.Strings[17959]="通用语……多么粗俗的语言。Bandal！"
D.Strings[17960]="你胆敢侵犯我的巢穴，让烈焰净化你的罪行吧！"
D.Strings[17961]="奥尔多获胜了！龙喉氏族被打败了！"
D.Strings[17962]="谁啊？！$n和$g他:她的;朋友们来玩了？"
D.Strings[17963]="我还有更重要的事情要做……"
D.Strings[17964]="伊利丹大人，我……"
D.Strings[17965]="享受你们最后的时光吧。"
D.Strings[17966]="部落会……毁灭你们。"
D.Strings[17967]="午餐时间。"
D.Strings[17968]="喝你的血。吃你的肉。"
D.Strings[17969]="我饿了。"
D.Strings[17970]="当心吧，我复活了！"
D.Strings[17971]="太愚蠢了……"
D.Strings[17972]="够了！不要继续了！"
D.Strings[17973]="我不要……被忽视！"
D.Strings[17974]="当心点，懦夫！"
D.Strings[17975]="你可以获得任何你想要的东西……只要付得起代价。"
D.Strings[17976]="我很满足。"
D.Strings[17977]="没错，你要和我们在一起了……"
D.Strings[17978]="当心你所期望的东西……"
D.Strings[17979]="你们走得太远了。"
D.Strings[17980]="我不会离开太远的！"
D.Strings[17981]="等待你们的只有痛苦与折磨！"
D.Strings[17982]="不要留下我一个人！"
D.Strings[17983]="看看你们强迫我做了些什么！"
D.Strings[17984]="我不愿意这样！"
D.Strings[17985]="痛苦才刚刚开始……"
D.Strings[17986]="我不想回去！"
D.Strings[17987]="现在，我该做些什么？"
D.Strings[17988]="既然来了，就要付出代价。"
D.Strings[17989]="我根本没什么感觉。"
D.Strings[17990]="你们觉得很有趣吗？"
D.Strings[17991]="是办正事还是找乐子呢？"
D.Strings[17992]="你看起来有点紧张……"
D.Strings[17993]="不要害羞。"
D.Strings[17994]="我是你的了。"
D.Strings[17995]="来得快，去得也快。"
D.Strings[17996]="不用理睬他们的攻击，$n！他们伤害不了你！"
D.Strings[17997]="多么快乐的结局啊。"
D.Strings[17998]="我……还不能死。"
D.Strings[17999]="他们的魔法对你不起作用，$n！"
D.Strings[18000]="伊利丹会付出代价的。"
D.Strings[18001]="更近了一步。"
D.Strings[18002]="不速之客！"
D.Strings[18003]="来了更多敌人！"
D.Strings[18004]="我支撑不了多久了。"
D.Strings[18005]="不！我不能死！"
D.Strings[18006]="继续战斗，朋友们！杀了他，让我的人民摆脱诅咒！"
D.Strings[18007]="当心他的视线！不要直视他的眼睛！"
D.Strings[18008]="新发现！我需要帮助才能完成测量……我要给同伴们发出信号！"
D.Strings[18009]="瓦解炮塔使得水晶熔炉充能过度，由此揭示了更多的秘密！给我守住！在我们收集新数据时守住！"
D.Strings[18010]="终于！我们寻找多时的信息！天空卫队，迅速集合。我们必须立即返回总部，通报这一消息！"
D.Strings[18011]="这座熔炉可以制造出不稳定的合剂……要研究合剂的话，我需要一些埃匹希斯碎片！"
D.Strings[18012]="我在这片水域培植这些令人惊异的水晶。我需要更多的埃匹希斯碎片做为催化剂！"
D.Strings[18013]="它的特性真是令人惊讶！给我点埃匹希斯水晶，我可以用它们制成武器和护甲。"
D.Strings[18014]="过来，$n。伊利丹大人在等你。"
D.Strings[18015]="龙喉氏族的勇士们，都聚集过来吧！就在你们中间，一位佼佼者已经晋升为领主了！向$n领主致敬！表达你们的敬意和忠诚吧！"
D.Strings[18016]="伊利丹大人很快就来到这里。"
D.Strings[18017]="这里散发着污秽的恶臭，看来鸦人最近又堆积了新的战利品。\n\n你需要10张迷时卷轴来召唤泰罗卡仇敌的后裔。"
D.Strings[18018]="伊利丹大人万岁！"
D.Strings[18019]="伊利丹大人，这位就是我和其他人向您提到过的龙喉氏族的英雄。他会引领我们走向胜利！"
D.Strings[18020]="这是什么意思，莫格霍尔？"
D.Strings[18021]="但是……大人，我不明白。$n……这个兽人曾经为我们……"
D.Strings[18022]="骨堆中弥漫出一股恐怖的黑暗能量。"
D.Strings[18023]="你给我闭嘴，白痴。你真是个不可理喻的蠢材……"
D.Strings[18024]="这就是你所谓的英雄？"
D.Strings[18025]="你们被欺骗了，白痴。"
D.Strings[18026]="整个……计划……都被破坏了！"
D.Strings[18027]="我希望立即在神殿内看到这个渣滓的尸块。否则你们就将遭受比死亡更痛苦的命运！"
D.Strings[18028]="我好像弄丢了我的指环。"
D.Strings[18029]="需要战场补给吗？"
D.Strings[18030]="长官，我能为你提供什么装备吗？"
D.Strings[18031]="需要补给吗？"
D.Strings[18032]="你胆敢欺骗莫格霍尔！在将你送到伊利丹大人的神殿之前，我要让你尝尝你想都不敢想的痛苦！我要折磨你，享受复仇的乐趣。"
D.Strings[18033]="你休想伤害这个孩子，莫格霍尔！$n，快点，爬到我的背上来！"
D.Strings[18034]="我好像弄丢了我的钥匙。"
D.Strings[18035]="你永远都无法做好万全的准备。"
D.Strings[18036]="你来了！"
D.Strings[18037]="你好，旅行者。"
D.Strings[18038]="我把缰绳给弄丢了。你能再给我一根吗？"
D.Strings[18039]="太空卫队以太技师和他的护卫队正在前往巴什伊尔码头的途中。去那里和他们碰面，帮助他们完成任务吧！"
D.Strings[18040]="太空卫队以太技师和她的护卫队正在研究巴什伊尔水晶熔炉，她需要帮助！前往巴什伊尔码头，找到以太技师并确保她的安全！"
D.Strings[18041]="我下定决心了。让我遗忘我的裁缝专精吧！"
D.Strings[18042]="嘿，看呀，是$n！"
D.Strings[18043]="$n，你今天杀了几条龙？"
D.Strings[18044]="$n，你能来这里，真是我们的荣幸。"
D.Strings[18045]="听说$n单枪匹马地捣毁了一处铸魔营地！"
D.Strings[18046]="有$n在，我们再也不用担心燃烧军团了。"
D.Strings[18047]="$n，你就是食人魔的$g国王:女王;！"
D.Strings[18048]="谢谢你帮助我们，$n。"
D.Strings[18049]="$n是我们的英雄！"
D.Strings[18050]="$n，今天过得怎么样？"
D.Strings[18051]="为$n欢呼三声！"
D.Strings[18052]="$n，你好吗？"
D.Strings[18053]="我们希望你能多待一会儿，$n。经常过来看看，让我们一起怀念过去的时光。"
D.Strings[18054]="要不是$n，我们现在会在哪里呢？"
D.Strings[18055]="$n，你放逐了多少个恶魔？我猜有成百上千吧！"
D.Strings[18056]="听说$n知道如何使用埃匹希斯圣物和纪念碑！"
D.Strings[18057]="你们能从$n身上学到很多东西！"
D.Strings[18058]="奥格瑞拉需要和谐！"
D.Strings[18059]="让战争远离奥格瑞拉！"
D.Strings[18060]="别在这里闹事！"
D.Strings[18061]="你想在奥格瑞拉胡作非为？"
D.Strings[18062]="看，是$n！"
D.Strings[18063]="$n，去杀龙吗？"
D.Strings[18064]="$n，很高兴你在这里。"
D.Strings[18065]="$n单枪匹马地捣毁了所有铸魔营地！！"
D.Strings[18066]="有$n在……我们再也不用担心燃烧军团了。"
D.Strings[18067]="$n是甘克心目中的英雄！"
D.Strings[18068]="甘克喜欢$n！"
D.Strings[18069]="$n，甘克的朋友。"
D.Strings[18070]="甘克希望$n能多待一会儿。$n以后要再来看甘克。"
D.Strings[18071]="$n消灭了恶魔，拯救了奥格瑞拉！"
D.Strings[18072]="$n消灭了所有的恶魔。"
D.Strings[18073]="甘克听说$n知道如何使用埃匹希斯的圣物！"
D.Strings[18074]="你们都得听$n的！"
D.Strings[18075]="遗忘药水专精并不是件轻松的事。\n\n你真的确定吗？"
D.Strings[18076]="遗忘药剂专精并不是件轻松的事。\n\n你真的确定吗？"
D.Strings[18077]="遗忘转化专精并不是件轻松的事。\n\n你真的确定吗？"
D.Strings[18078]="我下定决心了。让我遗忘炼金专精吧！"
D.Strings[18079]="我希望遗忘药水专精。"
D.Strings[18080]="我希望遗忘药剂专精。"
D.Strings[18081]="我希望遗忘转化专精。"
D.Strings[18082]="伊利丹的将领已经全部被打败了，$n。如果你准备就绪，就勇敢地前进吧。"
D.Strings[18083]="%s大发雷霆！"
D.Strings[18084]="我准备好了。带我去命令大厅吧。"
D.Strings[18085]="伊利丹的侍从依然守护着神殿大厅，$n。如果你打败了他们，我就能带你进入神殿的深处。"
D.Strings[18086]="他们把我从卡雷什叫过来就是为了对付这群渣滓？真是难以置信！等着收尸吧！"
D.Strings[18087]="$n骑士，很高兴见到你。"
D.Strings[18088]="嗨，那是我们的王牌飞行员，$n！"
D.Strings[18089]="听说$n想要成为天空卫队的队长。"
D.Strings[18090]="瞧，是$n，我们的王牌飞行员。"
D.Strings[18091]="$n，你有在玩极品飞车的感觉吗？"
D.Strings[18092]="够了！让我亲自来解决这帮蠢货！"
D.Strings[18093]="你干得不错，$n！"
D.Strings[18094]="最近你去过巴什伊尔码头帮忙吗，$n？"
D.Strings[18095]="$n，见到你真是个意外的惊喜。"
D.Strings[18096]="立正，$n军官来了！"
D.Strings[18097]="有$n在，我们没有什么好担心的。"
D.Strings[18098]="$n，天空的统帅，你在干什么？"
D.Strings[18099]="他们说$n从来没有被击落过。"
D.Strings[18100]="呵呵，有$n在天空飞翔，我们的敌人就要小心了！"
D.Strings[18101]="好吧，有件事是肯定的。$n再也不是移动荣誉了！"
D.Strings[18102]="$n，你的坐骑还撑得住吧？最近情况很艰难吗？"
D.Strings[18103]="嗯，这不是我们的常驻飞行员$n吗……最近怎么样啊，王牌飞行员？"
D.Strings[18104]="你已经清除了前路的障碍，离我的同胞又近了一步。我与他们之间，与这座神殿之间仍然有着强烈的羁绊。你愿意继续深入神殿吗？"
D.Strings[18105]="不久前，我的同胞还在这里，但是现在我和他们之间的感应却越来越微弱。一个拥有强大力量的生物守护着庭院，阻止了通往神殿深处的道路。"
D.Strings[18106]="带我去找其他死誓者，奥鲁姆。"
D.Strings[18107]="%s呲着牙发出嘶嘶声，以示威胁。"
D.Strings[18108]="你抓住了卡尔洛格！卡尔洛格抽你！"
D.Strings[18109]="听！地底传来的声音！他们要啜饮你的鲜血！"
D.Strings[18110]="瓦克奇斯携着狂风朝你恶狠狠地扑过来。"
D.Strings[18111]="你是我们当中最勇敢的骑士，$n。天空卫队感谢你。"
D.Strings[18112]="别……别将泰罗克召唤到我们的世界，$n……那样做……很愚蠢……"
D.Strings[18113]="我好像把黑色骨灰弄丢了。"
D.Strings[18114]="麦迪文的回音作弊了！"
D.Strings[18115]="试着对$n施法。"
D.Strings[18116]="只有最擅长追捕伊利丹仆从的猎手才能在我这里选购货物。$B$B当你在沙塔尔、塞纳里奥远征队以及奥尔多的声望达到崇拜时，我才会出售货物给你。"
D.Strings[18117]="只有最擅长追捕伊利丹仆从的猎手才能在我这里选购货物。$B$B当你在沙塔尔、塞纳里奥远征队以及占星者的声望达到崇拜时，我才会出售货物给你。"
D.Strings[18118]="欢迎你，$n。伊利丹将特殊的徽记赐给了他麾下最强大的仆从，替我取回这些徽记，我就让你选购这些炼金商品。"
D.Strings[18119]="我要兑换徽记。"
D.Strings[18120]="我好像弄丢了灰舌兜帽。"
D.Strings[18121]="到处……隐藏着鸦人！"
D.Strings[18122]="休息一会儿，阿达利斯。你需要恢复体力。"
D.Strings[18123]="一！"
D.Strings[18124]="二！"
D.Strings[18125]="三！"
D.Strings[18126]="四！"
D.Strings[18127]="五！"
D.Strings[18128]="酒桶打开了！现在，我来献上祝酒辞。啊，放心，我尽量简短一些。"
D.Strings[18129]="戈隆……燃烧军团……什么都难不倒你吗，$n？"
D.Strings[18130]="$n在附近的话，连水晶簇都会发出美妙的歌声。"
D.Strings[18131]="听说只要提起$n的名字，就算是龙也会因为恐惧而战栗。"
D.Strings[18132]="水晶启迪了$n。"
D.Strings[18133]="$n！水晶在赞美你！"
D.Strings[18134]="我们感谢你，$n。"
D.Strings[18135]="戈隆……燃烧军团……统统不是$n的对手！"
D.Strings[18136]="水晶让$n变得更聪明。"
D.Strings[18137]="$n！水晶在为你歌唱！"
D.Strings[18138]="甘克很感谢$n。"
D.Strings[18139]="$n，我们应该找个时间来赛跑。"
D.Strings[18140]="听说你不带降落伞披风就外出执行飞行任务，$n。"
D.Strings[18141]="在天空卫队的队员名单上，$n最为出众，因此名字也排在首位。"
D.Strings[18142]="$n是一位文雅的军官。"
D.Strings[18143]="王牌飞行员$n，12点位置！"
D.Strings[18144]="也许有一天$n会将$g他:她;的绝招教给我们？"
D.Strings[18145]="很荣幸能与你一起飞行，$n。"
D.Strings[18146]="$n，你是天空卫队最优秀的飞行员！你是我们的骄傲！"
D.Strings[18147]="在$n的帮助下，奥格瑞拉才能享有这份安宁。"
D.Strings[18148]="$n，强大的$c，所有食人魔的朋友！"
D.Strings[18149]="在$n的帮助下，奥格瑞拉才能享有这份安宁！"
D.Strings[18150]="$n，强大的$c，我的朋友！"
D.Strings[18151]="我弄丢了你给我的麻鹰哨。能再给我一个吗？"
D.Strings[18152]="肉眼见不见的鸦人们……他们就在我们身边……注视着我们……他们在等待！"
D.Strings[18153]="我是做幼龙生意的，$n。我得到授权，向最高阶的军官们出售虚空幼龙。"
D.Strings[18154]="我想要购买一只新的幼龙。"
D.Strings[18155]="我弄丢了我的勋章，克希利。"
D.Strings[18156]="你需要什么，$c？"
D.Strings[18157]="我需要一个新的魔化伊利达雷徽章。"
D.Strings[18158]="你们都聚在这里庆祝这个伟大的节日，真是令人高兴。我很久没见过这么大规模的庆典了。"
D.Strings[18159]="开始倒计时！"
D.Strings[18160]="苏普雷姆斯锁定了一个新目标！"
D.Strings[18161]="第一关：完成！"
D.Strings[18162]="游戏结束"
D.Strings[18163]="第二关：完成！"
D.Strings[18164]="最终关：完成！"
D.Strings[18165]="化成灰烬吧！"
D.Strings[18166]="美酒节就要开始啦！"
D.Strings[18167]="美酒节马上就要开始啦！到时候千万要记得过来看看哦。"
D.Strings[18168]="真是等不及看到这些准备工作完工了。我们马上就可以开始享受这个节日啦！"
D.Strings[18169]="美酒节是一场永不停止的盛宴！不过，准备这场盛宴也是个永无止境的工作……"
D.Strings[18170]="科隆克，能给我解释一下充能的聚焦水晶有什么用吗？"
D.Strings[18171]="聚焦水晶？当然，我会解释清楚的，毕竟，看上去你只具备完全理解这个概念所必需的一半脑力。$B$B首先，通过一个简单的反应，一块耗尽能量的聚焦水晶可以与十块埃匹希斯碎片产生连接，并在反应结束之后转化为一块充能的聚焦水晶。这些充能的聚焦水晶具备某种医疗能力，但更重要的是，它可以与某只被占据的恶魔产生共效，并应用在特殊的地方。$B$B比如说，每块充能的聚焦水晶的都可以使某只被占据的恶魔展现出特殊的力量。不久之后，甘克就会派你去完成一个类似的任务。"
D.Strings[18172]="嘿！听着！我有……我有些非常非常重要的事情要说！里看……等等，我要说虾米来着？船和飘在水面上的……对对！不要飘在船上……谢谢里……"
D.Strings[18173]="嘿，伙计们！最近怎么样？"
D.Strings[18174]="这儿怎么搞的啊？"
D.Strings[18175]="嘿！有谁看到附近有没有漂亮的金发矮人妹？我……我发誓，刚才还寨周围看见咧……"
D.Strings[18176]="%s快速掠过，在$n身上留下了一道很深的伤口！"
D.Strings[18177]="当麦格尼国王陛下过来找我谈有关节日的事情时，我简直要兴奋得疯过去了。我对他说，有了我这侏儒的一些微小帮助，我们就能制造出一场令所有人都会难以忘怀的盛宴。不过，国王陛下喜欢比较朴素和传统的风格，他更看中缅怀过去之类的事情。"
D.Strings[18178]="我对此可以理解，但国王陛下能允许我这个侏儒去开酒桶，已经是个改变了。所以呢，现在我正在研究另一个难题，那就是：如何最有效率地打开酒桶，并把里面的酒平均地分给大家喝，注意平均和最有效率这两个词。"
D.Strings[18179]="现在，我手下最精锐的技师们正在研制一台伟大的机器来完成这个使命！我们可以计算出……"
D.Strings[18180]="好吧……那么……我猜开罐器74205得再等一等……此外，我觉着开罐器75633的设计很有意思……"
D.Strings[18181]="好吧，好吧……现在我们就开始十秒倒计时，大家准备好了吗？10！"
D.Strings[18182]="快点快点，补锅的！"
D.Strings[18183]="我们要酒啊啊啊啊！"
D.Strings[18184]="呀，呀！喝呀喝呀！"
D.Strings[18185]="无聊死啦！！！"
D.Strings[18186]="喝呀，一口干！喝呀，一口干！喝呀，一口干！"
D.Strings[18187]="打开酒桶！"
D.Strings[18188]="%s开始全力聚焦！"
D.Strings[18189]="喝吧，喝了以后一切都会变美好的！"
D.Strings[18190]="要搭独木舟前往龙骨荒野吗？"
D.Strings[18191]="吉米，我想搭乘你的独木舟。"
D.Strings[18192]="当心北极鲨！"
D.Strings[18193]="感谢大家……今天我们要……要……是啦！其实……我们要叫萨……萨尔老大……和吉……吉……反……反正……他会明白我们是热爱部落的。部……部落万岁！"
D.Strings[18194]="嘿！你挺不挺部落？<嗝儿>我挺！"
D.Strings[18195]="嘿！有人看见漂亮地精妹了吗？我发誓刚才这里肯定有个……"
D.Strings[18196]="今天，让我们深刻铭记那些为我们带来温饱的人。"
D.Strings[18197]="让他们彼此争斗，才能显示出我们对他们的敬意。"
D.Strings[18198]="我们马上就能知道谁是最棒的酿酒师啦。酿酒师们都非常期待这场比赛，否则我们也不会邀请他们了。"
D.Strings[18199]="伟大的战士兄弟们，让我们举杯欢庆吧！"
D.Strings[18200]="从五开始倒数。倒数结束打开这只酒桶，我们将评出谁才是最优秀的酿酒大师。"
D.Strings[18201]="从五开始倒数。倒数结束后，老沃金就会打开这只酒桶，我们将评出谁才是最优秀的酿酒大师。"
D.Strings[18202]="酒桶已经被打开了！比赛开始！让我们一起举杯，为战士们干杯吧……"
D.Strings[18203]="为了部落，酿！为了部落，喝！"
D.Strings[18204]="战栗吧，丧钟已为你鸣响！颤抖吧，挽歌已为你宣唱！末日审判已潸然降临，所有生者都要付出代价！"
D.Strings[18205]="美酒万岁！"
D.Strings[18206]="今天最适合喝酒啦！其实每一天都很适合喝酒！"
D.Strings[18207]="为了部落，干杯！"
D.Strings[18208]="烈焰吞噬一切！你们精疲力竭，毫无获胜的希望。我要伸张正义！"
D.Strings[18209]="我的地狱烈焰竟已不再煌煌。你的生命火烛必也要暗褐无光！"
D.Strings[18210]="无头骑士——攻击，转移。"
D.Strings[18211]="我把破碎大厅的钥匙弄丢了。"
D.Strings[18212]="开火示警！"
D.Strings[18213]="让他们吃点苦头……"
D.Strings[18214]="天空一片黑暗，火焰仍在肆虐。你的挣扎毫无意义，命运之轮已经开始旋转。"
D.Strings[18215]="小镇仍在燃烧，看这净化的火焰！啊，时间过得真快，我要撤退了！"
D.Strings[18216]="你浪费了太多的时间，凡人。长眠吧！"
D.Strings[18217]="毫不迟疑，伸张正义！"
D.Strings[18218]="神秘的蹄印，烧焦的盾牌，四散的徽章……这些东西有什么联系吗？"
D.Strings[18219]="这种罪行不容姑息。旅店的地理位置和它的离奇被毁让事态变得非常棘手。朋友，用谨慎的态度去树荫旅店展开调查吧。"
D.Strings[18220]="你在这里干什么？你还想要继续玷污这个被屠杀的家族所遗留的灰烬吗？离开这个地方。这里不欢迎你。"
D.Strings[18221]="你能再撒一次反光粉吗？"
D.Strings[18222]="唔……我觉得……"
D.Strings[18223]="愚蠢的法师们……总是将材料用得一干二净，还不知道及时补充。"
D.Strings[18224]="他又在为材料的事发牢骚了？呸，他怎么不提上次将召唤书忘在这里的糗事？"
D.Strings[18225]="那么，它在哪儿？"
D.Strings[18226]="“朋友”，如果你认为自己能阻止我们的话，那你就大错特错了。"
D.Strings[18227]="我们一定要把吉安娜的懦弱行径曝光！"
D.Strings[18228]="这些家伙总有一天会明白，普罗德摩尔将军是一位真正的英雄！"
D.Strings[18229]="就是像你这样的家伙削弱了联盟的力量，邀请部落来夺走我们为之奋斗的一切！"
D.Strings[18230]="朋友，感谢你成功地保卫了塞拉摩。"
D.Strings[18231]="等你下班以后，我请你去旅店喝上几杯，一起回忆过去的美好时光。"
D.Strings[18232]="难道你不怀念往昔的岁月吗？我的朋友知道如何重返荣耀……"
D.Strings[18233]="朋友，你看上去是位通情达理的$c。你可曾记得塞拉摩昔日的光辉岁月？那是吉安娜禁止我们与部落交战之前的事情了。兽人仍在频频挑衅，而我们却被告知不得挑起战乱，你是否对此感到厌倦？"
D.Strings[18234]="你的言论根本影响不了我。去别的地方散布那些叛逆的理论吧，叛徒！"
D.Strings[18235]="看！水果摊边上有个三层楼高的食人魔。那个水果贩看来想和我们大战一场了……"
D.Strings[18236]="那个食人魔就是他要发动战争的迹象。水果贩已经坏了道上的规矩！"
D.Strings[18237]="哪个水果贩有这个胆子？他竟然买通食人魔当打手。"
D.Strings[18238]="哈！水果贩这下一定很害怕了。他竟然叫来了援军。好吧，这下有的玩了。"
D.Strings[18239]="难道那水果贩以为我瞎了吗？我怎么可能看不到他的食人雇佣兵？"
D.Strings[18240]="我感觉到了真正的战争气息。水果贩已经得到了食人魔的援助，我也必须叫来我的援兵。"
D.Strings[18241]="无头骑士的灵魂已经变得疯狂了！在万圣节期间，他随时可能袭击这座村庄！"
D.Strings[18242]="无头骑士要攻击村子了！谁能救救孩子们，谁能阻止它！"
D.Strings[18243]="现在，无头骑士对我们的威胁已经解除了。我们又可以呼吸到自由的空气了，但如果不能在有头的情况下击败它，它随时还会回来的。"
D.Strings[18244]="如果你要战争，那么我们就成全你，给你战争，水果贩！"
D.Strings[18245]="你的食人魔佣兵吓不倒我，水果贩！我的援军就要到了！"
D.Strings[18246]="你的日子到头了！你的食人魔军团不堪一击！"
D.Strings[18247]="$n，我真的希望有人能找到我的狗！"
D.Strings[18248]="%s看到午餐之后高兴地叫了起来！"
D.Strings[18249]="%s开心地吃着午餐。"
D.Strings[18250]="%s跳了一支特殊的舞蹈，对你表示感谢。"
D.Strings[18251]="飞艇应该是刚刚到达格罗姆高……"
D.Strings[18252]="凭什么我的外甥每天都能享受荆棘谷的阳光和海滩呢？舅舅真是不好当。"
D.Strings[18253]="飞艇应该是刚刚离开格罗姆高……"
D.Strings[18254]="飞往格罗姆高的飞艇随时会靠港。"
D.Strings[18255]="飞往格罗姆高的飞艇已经靠港了！要去荆棘谷的就赶快啦！"
D.Strings[18256]="嘿！我到底给飞艇的油箱里加油了没有？有人能告诉我吗？好吧，随它去吧！"
D.Strings[18257]="飞艇应该是刚刚到达奥格瑞玛。再等一小会儿吧……"
D.Strings[18258]="真希望我的兄弟在杜隆塔尔没搞出什么乱子。那边臭烘烘的兽人太多了……不过，这里也不怎么轻松啊……"
D.Strings[18259]="前往奥格瑞玛的飞艇已经出发啦。希望这次它不会爆炸。"
D.Strings[18260]="老实说，我也搞不清楚飞艇目前到底在哪儿……"
D.Strings[18261]="飞艇应该是刚刚到达奥格瑞玛……"
D.Strings[18262]="飞艇应该是刚刚从奥格瑞玛起航……"
D.Strings[18263]="飞艇应该是刚刚从格罗姆高起航……"
D.Strings[18264]="飞艇目前在哪里？"
D.Strings[18265]="飞艇应该是刚刚到达幽暗城。"
D.Strings[18266]="飞艇应该是刚刚到达奥格瑞玛。"
D.Strings[18267]="飞艇应该是刚刚从奥格瑞玛起航。"
D.Strings[18268]="飞艇应该是刚刚从幽暗城起航。"
D.Strings[18269]="无头骑士发动了攻击！火焰可能会吞噬整个村落！我们该怎么办？"
D.Strings[18270]="飞艇应该是刚刚到达格罗姆高。"
D.Strings[18271]="飞艇应该是刚刚从格罗姆高起航。"
D.Strings[18272]="我还没去过格罗姆高呢。这不公平！温暖的沙滩……向着夕阳奔跑的鳄鱼与迅猛龙……啊……等等……或许还是不要去了吧。"
D.Strings[18273]="快，下一班去荆棘谷的飞艇马上就要出发了！"
D.Strings[18274]="飞往提瑞斯法林的飞艇已经靠港了！一定要穿上被遗忘者最流行的服饰去冒险呀！"
D.Strings[18275]="若是白白浪费掉这些传单就太可惜啦，不是吗？"
D.Strings[18276]="我整天都在收集飞艇零件。就这样，弗雷萨还不肯给我加点薪水。至于你，你肯定不是来跟我抢工作的，对吧？我猜你想知道飞艇现在的位置在哪。总之，你运气不错，我这里就有个飞艇追踪装置了！"
D.Strings[18277]="只要加入一点创造性的改变，它们会变得更有用……"
D.Strings[18278]="去往幽暗城的飞艇目前在哪里？"
D.Strings[18279]="去往格罗姆高的飞艇目前在哪里？"
D.Strings[18280]="请考虑一下我们的提议吧！"
D.Strings[18281]="请收下这份传单，考虑一下我们的提议吧！"
D.Strings[18282]="嗨，谢谢。"
D.Strings[18283]="%s读着传单。"
D.Strings[18284]="这……这只是个玩笑吧？"
D.Strings[18285]="我很久没读到过这么好笑的东西啦。你是来逗我开心的吧？"
D.Strings[18286]="一群疯子！你们真的相信这东西吗？"
D.Strings[18287]="我永远都不会参与这样的组织。不过最好留着这个。这东西迟早有用……"
D.Strings[18288]="嗨……嗨……嗨！就是你！我也许看上去很萎靡，但我肯定会东山再起的！过来看看我有些什么。最最珍贵和最最不可思议的护身符就在这里！我甚至还弄到了些新玩意！过来，过来，你知道你想要看看的。"
D.Strings[18289]="看看这个，$r！你知道你的爱人需要些什么吗？一朵这样的花，一朵只生长在神秘的泰罗卡森林的丁香花。稀有！如此稀有！你在别处可找不到这样的花？名花配美人，不是吗？难·道·不·是·吗？"
D.Strings[18290]="神奇的护身符！惊人的古玩！格里伏塔……最新……进货的，由经过时间考验的神奇材质做成的新奇珠宝制品！用这些不可思议的法宝来让你自己变得更强大吧，破盘价出售啦！"
D.Strings[18291]="好吧，好吧，我知道你在想什么。这是根棍子，但它绝不是一根普通的棍子，绝不是！$c，你在这里看到的是一根非常非常稀有，非常非常珍贵，以这个世界特别的力量精炼而成的棍子！你想拥有这被华丽的力量触及过的德拉诺神器吗？我知道你想。千万不要错过了，如果你错过了，那么恭喜你！你买不到了。"
D.Strings[18292]="嗨，$c！等等！最近你去市场逛过吗？我的摊位还好吧？"
D.Strings[18293]="我不敢相信他们竟然把我赶出了沙塔斯城。那里难道不是贫民窟吗？我，格里伏塔也是难民啊！不是我的错，我只是个有事业心的难民……"
D.Strings[18294]="现在，我知道你在想什么了。格里伏塔有些麻烦，但这不算什么。我身边仍然有着很多库存。过来看看我有些什么吧。"
D.Strings[18295]="商人格里伏塔因多次诈骗顾客，被判驱逐出沙塔斯城。我们要仔细检查他出售的这些小玩意儿。请配合我们的工作，离开他的摊位。"
D.Strings[18296]="没什么好看的。走开。"
D.Strings[18297]="这个摊位正在接受官方的调查。请离这里远点。"
D.Strings[18298]="你不用担心——那个在这里叫卖“货物”的骗子已经被赶出我们美丽的城市了。"
D.Strings[18299]="请离开这个摊位。这里正在接受调查。"
D.Strings[18300]="我们绝不能落下不听从民众意见的口实。这个“骗子”制造了很多虚假的宣传，现在我们要把事情都纠正过来。"
D.Strings[18301]="小心点，$r，有个令人讨厌的家伙在那里。"
D.Strings[18302]="如果你要出城冒险的话，$c，小心那个衣着光鲜的巨魔，他可能会尝试接近你。不要理他，让他在那里享受他应得的放逐吧。"
D.Strings[18303]="麦酒，艾泽拉斯最好的酒！"
D.Strings[18304]="过来试试我们的黑麦酒吧！"
D.Strings[18305]="麦酒引领了酿酒工艺的革新。来试试我们最新的产品，纯正的麦酒！"
D.Strings[18306]="雷霆啤酒，全世界最好的啤酒。"
D.Strings[18307]="你似乎需要一杯冰镇啤酒，雷霆啤酒是你最好的选择！"
D.Strings[18308]="我们有世界上最棒的酿酒厂，雷霆啤酒酿造商们一直引以为傲。"
D.Strings[18309]="哇！你真的想要从我们手中购买吗？"
D.Strings[18310]="上前去，卫兵！杀戮时间开始了！"
D.Strings[18311]="哈哈哈！"
D.Strings[18312]="卫兵，快上！你们更怕谁！他们……还是我？"
D.Strings[18313]="嗯？啊……呃……"
D.Strings[18314]="兽人，快醒醒！我口渴得很！卖点喝的给我……"
D.Strings[18315]="你没看到我有好多事情要忙吗？走开点，农夫！"
D.Strings[18316]="等等！我想喝点咖啡！"
D.Strings[18317]="冲锋！冲过去，把他们的脑袋给我带来！"
D.Strings[18318]="我想你知道我是谁吧。但是，你还是不停地烦我？$b$b你是不是想引起我的注意？"
D.Strings[18319]="呃，你是谁？"
D.Strings[18320]="拜托，别讲那种荒谬的话了！我就是巴德·奈德雷克，如假包换！$b$b我游历过这片大陆的每个角落，从海加尔山颠到沉没的神庙都留下了我的足印。事实上，沉没的神庙还是我命名的呢！$b$b是啦，就是我。你还怀疑什么呢。"
D.Strings[18321]="我要失去耐心了！继续上，让他们感觉生不如死！"
D.Strings[18322]="不，我想我不认识你吧。"
D.Strings[18323]="真的吗？听起来真能打……"
D.Strings[18324]="好吧，$c，听我说。我的实际年龄比外表所显示出来的更大，我还拥有超越年龄的智慧。你最好别怀疑我所说的。\n\n当然，若是你不相信我的话呢，就去看看城镇中招贴的公告牌吧。每张上面都写着我的名字！$b$b不过嘛，标有“通缉”字样的公告牌请直接无视吧。我向你保证，那只是误会。"
D.Strings[18325]="嗯……古老的钱币……难看的珠宝……"
D.Strings[18326]="又是难看的珠宝……还有家书……我快要放弃希望了！"
D.Strings[18327]="嗨……这是什么？一副镣铐，还不是一般的镣铐呢。上面附有魔法。还有这箱货物，啊，里面有人！"
D.Strings[18328]="没人料到黑铁矮人会来吧！！"
D.Strings[18329]="$c，你好。我正在向巴德拉克讨教驾驭狮鹫的窍门。真希望有一天我能拥有自己的狮鹫棚。"
D.Strings[18330]="警报！警报！发现有人未经许可就想取出贵重物品。启动安全系统。"
D.Strings[18331]="狗在哪里？"
D.Strings[18332]="你能帮我找到我的狗吗？"
D.Strings[18333]="我好想它啊！"
D.Strings[18334]="人们总是希望在旅店或是这样的节日聚会上找到艳遇，我非常理解这种想法。但是酒精会让人的感官变得迟钝，让你忘却生计的艰辛。$B$B不过，我找到了解决方法！通过很多次的试验和磨难，我设计出一种特别的装置！只要戴上这些护目镜，所有人都会变得魅力十足！$B$B嗯……包括你，美人！怎么样，我还可以给你打折！"
D.Strings[18335]="呀哈！来呀，甜心！"
D.Strings[18336]="嗨，甜心！你对伶牙俐齿魅力四射的女人感兴趣吗？"
D.Strings[18337]="多么迷人的容貌啊！"
D.Strings[18338]="吉安娜女士让我来和你谈谈关于乘坐狮鹫调查奥卡兹岛的事。"
D.Strings[18339]="事情会变成什么样呢……"
D.Strings[18340]="我想要喝一杯。"
D.Strings[18341]="我听说你的厨艺很不错。"
D.Strings[18342]="啊，我的厨艺吗？应该是吧。作为女招待，当然总得在厨房里跑来跑去的。我确实学到了一些新的菜谱，虽然不是很特殊，但至少可以填饱葛罗克那无底洞一样的胃。"
D.Strings[18343]="我还想学习更多。"
D.Strings[18344]="很抱歉，$n，但是我已经没有什么可以教你的了。当然，说不定哪天我灵光一闪，就发明出新菜谱啦，所以不要忘了经常回来看看！"
D.Strings[18345]="我的兄弟克里克斯觉得他在奥格瑞玛的工作很糟糕。但和这个地方的恶臭比较起来，那算得了什么？不过至少老板还付给我额外的危险津贴！\n\n什么？你想知道飞艇在哪里？你很幸运，我正好带着我的飞艇追踪器！"
D.Strings[18346]="去往奥格瑞玛的飞艇目前在哪里？"
D.Strings[18347]="这个巨魔肯定是心术不正的坏蛋。"
D.Strings[18348]="究竟是谁认为这些垃圾玩意儿会拥有什么力量？根本没有任何值得去吸取的能量。"
D.Strings[18349]="我告诉过阿达尔收容大量浑身长满虱子的难民只会给自己带来更多的麻烦，但是他会听吗？不，不，这样的事要是被占星者知道该怎么办？啊。"
D.Strings[18350]="到家之后，我要好好地洗个热水澡。嗯，或许洗两次。呃，不如洗上五次。"
D.Strings[18351]="要是他们觉得我要去巨魔的衣柜翻东西的话，那他们完全错了。"
D.Strings[18352]="为什么整个世界就我要做这样的工作？"
D.Strings[18353]="啊。别告诉我那是只蟑螂……"
D.Strings[18354]="艾泽拉斯和外域的人们……你们准备好了吗！"
D.Strings[18355]="我想把这称为……"
D.Strings[18356]="部落的力量！"
D.Strings[18357]="谢谢大家！晚安！"
D.Strings[18358]="好吧……我放弃……"
D.Strings[18359]="保持警惕。尘泥沼泽中强敌四伏，我们担负着构筑塞拉摩岛第一道防线的重任。"
D.Strings[18360]="这酒可真够劲儿的！再……再来一杯！*嗝儿*"
D.Strings[18361]="你……你刚才说想让……让我……在……在吧台上……跳舞？*嗝儿*"
D.Strings[18362]="老板！来点音乐听听！"
D.Strings[18363]="目前逃亡者占领了废弃哨塔，所以北点哨塔成为距离塞拉摩岛最远的岗哨。"
D.Strings[18364]="哎呀，小美人你好……"
D.Strings[18365]="好吧，你这个矫情的家伙……待会等你心情好些了，我再来找你吧。"
D.Strings[18366]="嗯，你不介意我这样做吧！"
D.Strings[18367]="马克，别来烦我。我没心情和你这个醉鬼说话。离我远点！"
D.Strings[18368]="这一次，你不会有机会再进监狱了！"
D.Strings[18369]="小公主，你说什么就是什么啦。不过拖延是没有意义的，有些事情是无可避免的……"
D.Strings[18370]="你为什么要让可怜的马克伤心啊？等我回来后，希望你会改变想法……"
D.Strings[18371]="我的公主，你讨厌我了。我感觉得到！"
D.Strings[18372]="滚远点！否则我就让巴德把你做成狗粮……"
D.Strings[18373]="马克，这里没有酒。滚吧！"
D.Strings[18374]="去去去！老远就闻到一股酒臭味，我就知道是你……"
D.Strings[18375]="那么，这个可爱的小家伙是谁呀？"
D.Strings[18376]="啊，亲爱的埃门纳！咱们又见面了，我真是开心。"
D.Strings[18377]="哼。我本来就没有喜欢过她……"
D.Strings[18378]="嗯，没有什么不能用润滑剂搞定的！"
D.Strings[18379]="妈妈常说5点钟之前不许喝酒。可是，世界上一定有某个地方已经到5点了吧！"
D.Strings[18380]="<咳嗽>啊……"
D.Strings[18381]="哇！就像爸爸常说的，腾出肚子来喝酒！哈哈。"
D.Strings[18382]="哦。我的肚子有点不舒服……"
D.Strings[18383]="嗯，瞧我这身老骨头，看来该休息一会儿啦。"
D.Strings[18384]="你是说巴德手下的探险队？$b$b他对任何人都一视同仁的。只要你会用铁铲，他就会雇佣你。$b$b呃……除非你是亡灵。巴德讨厌他们。不过我认为他是害怕亡灵。"
D.Strings[18385]="这家伙是巴德手下的一名探险队员吧，他是什么人？"
D.Strings[18386]="嗯，我很有本事呢。你要我帮你什么啊？"
D.Strings[18387]="$c，要我帮忙吗？"
D.Strings[18388]="你是来掠夺战利品的么？去排队候着吧！$b$b我的那份还没有到手呢……"
D.Strings[18389]="孩子，你可难倒了我。我跟探险队的成员不熟。$b$b这些巨魔烈酒我已经喝腻了，就盼着巴德许诺的财宝呢……"
D.Strings[18390]="这帮家伙真有意思……"
D.Strings[18391]="你是说巴德手下的探险队？啊，他对任何人都一视同仁的。只要你会用铁铲，他就会雇佣你。$b$b除非你是亡灵。巴德讨厌他们。或许是害怕吧。"
D.Strings[18392]="是啊，你永远不会知道下一个入伙的家伙是谁，也不会知道下一个因此事而丧命的家伙是谁。$b$b我的建议么，就是不要和任何人扯上关系。"
D.Strings[18393]="说得没错。巴德纠集了形形色色的酒鬼。$b$b似乎只要能喝到免费的美酒，这帮家伙就会抛开彼此的差异与分歧，聚到一起来。"
D.Strings[18394]="哎呀！那是什么味道？"
D.Strings[18395]="<闻了闻身上的气味，然后退了一步>$b$b$c，这就是冒险的味道！"
D.Strings[18396]="<嗝儿>听好了，$r。不如你也去和那些野蛮的巨魔扭打一番，然后闻闻自己身上的味儿！"
D.Strings[18397]="瞧，这营地附近只有兽人烈酒而已。$b$b我可不喜欢喝这种酒，你懂我的意思吧……"
D.Strings[18398]="哈。就按你说的办。"
D.Strings[18399]="白痴。"
D.Strings[18400]="你能闭嘴吗？！"
D.Strings[18401]="给我个理由，为什么我就不能离开呢？"
D.Strings[18402]="你是我所遇到过的最无能的军官！"
D.Strings[18403]="恕我直言，长官，忍耐！"
D.Strings[18404]="詹姆斯？詹姆斯……不，你不是詹姆斯，但我知道你是谁……"
D.Strings[18405]="你就是追踪那帮野蛮的渣滓，替我们报仇的英雄。"
D.Strings[18406]="我千方百计地想要告诉吉姆……想要告诉所有人……谁才是幕后黑手，可惜始终没有机会……"
D.Strings[18407]="谢谢你为吉姆和我们所做的一切。如果你遇见吉姆，请告诉他我和小吉米始终爱着他，我们一直在等他回家。"
D.Strings[18408]="妈妈，我们什么时候能再见到爸爸？"
D.Strings[18409]="吉米，我也不知道我们何时才能与你爸爸重逢。但你要知道，他爱你，无时无刻都在思念你。"
D.Strings[18410]="哦……见鬼，让我换个绷……带！"
D.Strings[18411]="这样或许可以延缓感染的速度。"
D.Strings[18412]="图高尔！懒惰的家伙，快过来帮我卸货！"
D.Strings[18413]="蠢货！你给我等着，总有一天我会在你的酒里加点料，让你长眠不起……"
D.Strings[18414]="我说，布伦德，你的目光为何从来不在我的身上停留？"
D.Strings[18415]="噢，玛尔格。事实上，我有话对你说……"
D.Strings[18416]="我试过很多种方法，但只有在我喝醉时才觉得你是个美人！"
D.Strings[18417]="欢迎来到警戒哨岗，$c。"
D.Strings[18418]="啊啊啊！你竟然说出这样的话！"
D.Strings[18419]="希望你吸取教训……"
D.Strings[18420]="哈哈哈哈哈哈哈！"
D.Strings[18421]="湮远而艰辛的探索到此为止，真正的正义者将由命运择示。"
D.Strings[18422]="对不起……啊呀……"
D.Strings[18423]="好吧……你嬴了……"
D.Strings[18424]="求你，别打啦……我全身都疼……"
D.Strings[18425]="我说，布伦德，说些我爱听的甜言蜜语好吗？"
D.Strings[18426]="但是，布伦德，你不是一直在喝么？"
D.Strings[18427]="肮脏的兽人！"
D.Strings[18428]="玛尔格，我记得我警告过你，别在我喝酒的时候烦我……"
D.Strings[18429]="嗨，莫格罗姆！玛尔格似乎需要关爱，不如你陪陪她？"
D.Strings[18430]="我的躯体健壮而纯洁！现在，让我来治愈你们这帮阴暗的灵魂吧。"
D.Strings[18431]="我需要一些空间！"
D.Strings[18432]="我需要更多的空间！"
D.Strings[18433]="$c，我需要帮助。$b$b过来帮帮我怎么样？"
D.Strings[18434]="能告诉我一些关于巴德的事情吗？"
D.Strings[18435]="他是个坏人！$b$b我已经看穿他的真面目了。这家伙以财富为诱饵，将那群笨蛋灌得烂醉如泥，然后利用他们做些肮脏的勾当——他们通常会因此而丧命。"
D.Strings[18436]="那么，你还待在这儿做什么？"
D.Strings[18437]="问得好。你不妨找我的兄弟图高尔谈谈。$b$b那个懒惰的坏家伙或许会告诉你答案……别让我打开话匣子。"
D.Strings[18438]="啊……我们的酒都没了……黑铁矮人……啊……会回来……啊……"
D.Strings[18439]="你好啊。在这些龙宝宝的主人持兑换码来认领它们之前，我会一直负责照料它们。"
D.Strings[18440]="输入认证码以获得虚空龙宝宝宠物。"
D.Strings[18441]="可悲的凡人，奥妮克希亚不会任凭你摆布的！"
D.Strings[18442]="就凭你也敢来挑衅。死之前让我好好享受一下玩弄你的乐趣吧。"
D.Strings[18443]="朋友，快！我就要没命了！$b$b我知道他们是如何对待囚犯的！我还这么年轻，我可不想死！$b$b你倒是做点什么啊，快啊！"
D.Strings[18444]="你能告诉我这里的情况吗？"
D.Strings[18445]="听着，朋友！$b$b我会把我知道的一切都告诉你，但你得先把我从这个恐怖的地方救出去！$b$b怎么样？"
D.Strings[18446]="布洛格很感激收留他的泥链镇地精，不过有时他觉得地精们在嘲笑自己。"
D.Strings[18447]="我想要输入神秘兑换码以获得我的鱼人服装。"
D.Strings[18448]="啊哈！坦扎尔自由啦！$b$b我真走运！竟然毫发未伤。$b$b朋友，我是被命运之神眷顾的幸运儿。是啦。肯定是这样。"
D.Strings[18449]="不客气……告诉我们这儿发生了什么事！"
D.Strings[18450]="能告诉我们关于巴德的事情吗？"
D.Strings[18451]="我从未到过这么冷的地方，$r。就算是没有冰雪覆盖，在诺森德的冰荒废土上行走还是异常艰难。"
D.Strings[18452]="我想要购买一些材料，亚米娜。"
D.Strings[18453]="你……好似有点面熟。我以前在哪儿见过你吗？"
D.Strings[18454]="我认识你吗？"
D.Strings[18455]="让我给你一个忠告吧：永远不要信任侏儒。"
D.Strings[18456]="给我再来点酒，笨蛋。"
D.Strings[18457]="好吧，朋友，我告诉你……$b$b那晚我们潜入祖阿曼，想要一探究竟。$b$b夜色寂静，突然传来一阵微风掠过树叶般的飒飒声。没等我们回过神来，就被这帮野蛮的巨魔和他们的宠物包围了！等我醒来的时候已经是次日，我发现自己被囚禁在牢笼中。$b$b日复一日，囚犯们接二连三地惨遭毒手。每杀死一名囚犯，那名熊巨魔的力量就增加一些。$b$b朋友，我对祖阿曼的了解仅限于此。我也不想知道更多了！"
D.Strings[18458]="等我长大以后，我要当一个马夫！"
D.Strings[18459]="别罗嗦了，孩子，我要寄存我的宠物。"
D.Strings[18460]="这旅馆可是在北边那些野蛮人觉醒之前就建起来了。至少，感谢圣光！$B$B你在这里会呆很久吗？"
D.Strings[18461]="我想看看你卖的货物，哈吉尔。"
D.Strings[18462]="那家伙就是个蠢货！$B$B名望，财富？啊呸！朋友，这儿就像个死亡陷阱！$B$B我见过各种巨魔，可他们与其他巨魔截然不同——卑鄙、强壮、狡猾。$b$b他们似乎知道我们潜入了祖阿曼一样……"
D.Strings[18463]="*嗝儿*酒精……和毒药……*嗝儿*都是很……危险的……"
D.Strings[18464]="我需要一些材料，苏雷。"
D.Strings[18465]="<巴德见你走近，眼珠子一转。>$b$b哟，这不是即将成名的$n么！$b$b您大驾光临真是我的荣幸啊！"
D.Strings[18466]="你派去祖阿曼的探险队惨遭屠杀！你倒是做点什么啊！"
D.Strings[18467]="好啦，$n，放轻松点，做个深呼吸吧。你要相信我。$b$b你缺乏处理这类情况的经验，才会搞得惊惶失措。心理上的恐惧感往往会夸大事实。所以啦，根本不存在什么危机。$b$b我说，你不要这么消极嘛。这会影响到整个探险队的士气……"
D.Strings[18468]="你要是真有自己吹嘘的那么能干，为什么不亲自去调查祖阿曼呢？"
D.Strings[18469]="愚蠢的问题！$n，看来我高估了你。$b$b你应该清楚，必须有人主持大局。我是唯一合格的人选，这副重担只能由我来挑。$b$b$c，说实话，我很羡慕你。我多想亲自深入祖阿曼，铲除那些野蛮的巨魔。你应该感到幸运才是……"
D.Strings[18470]="烧死你们，异形，烧死你们！"
D.Strings[18471]="孩子们，喝光它！"
D.Strings[18472]="不速之客闯入了聚会！"
D.Strings[18473]="刚才谁说有“免费的啤酒”？"
D.Strings[18474]="你可以在塔贝萨的房中找到学徒加里奥。至少，他没法偷走那儿的所有材料。"
D.Strings[18475]="要是有牧师或是德鲁伊在就好了。在康复之前，我没法继续研究工作了。"
D.Strings[18476]="等等，莫非……你是$n，对吧？$b$b我能为你做些什么吗？"
D.Strings[18477]="你之前的那些“伙伴”呢？"
D.Strings[18478]="哦，那要看你所说的“伙伴”是谁。这些年来来往往的人可多啦，唯有巴德·奈德雷克还保持着追寻历史传说的热诚！$b$b大部分人在收获财富之后都隐退了。不过我不会选择这样的道路。我始终觉得，我的使命就是揭开世间神秘事物的面纱。哎，我不去做的话，还有谁肯担起这个差事呢？"
D.Strings[18479]="那么，新近的这支探险队呢？他们的情况如何？"
D.Strings[18480]="啊，他们呀——悲惨的结局。$b$b探险队进入祖阿曼已有数日，至今音信全无。$b$b类似的情形我也见得多了，这帮被名誉和财富冲昏了头脑的蠢货。我警告过他们，没有做好充分的准备就别贸然涉险，可惜他们压根儿没听进去……"
D.Strings[18481]="我说，巴德，有谁能证明你所说的话吗？"
D.Strings[18482]="听着，$n，聪明的话就别放弃唾手可得的财富。这种好事不是每天都能碰上的！$b$b那么，$c，你愿意加入探险队吗？$b$b<巴德没等你答话便继续开口。>$b$b你显然是愿意啦！还有很多工作要做呢，你这家伙废话不少，却没有一点实质行动嘛。你最好做出点成绩给我看，不然我就找人顶替你的位置。$b$b我敢打赌，这样的机遇不知道有多少人垂涎呢！"
D.Strings[18483]="喂喂！我们被那群该死的海盗给堵在海湾里了！$B$B能帮我们出去吗？"
D.Strings[18484]="喂喂！我们被那群该死的海盗给堵在海湾里了！$B$B朝他们丢炸弹，看能不能帮我们出去？$B$B我们偷来的飞艇就在那边，趁它起航之前跳上去！"
D.Strings[18485]="喂喂！我们被那群该死的海盗给堵在海湾里了！$B$B朝他们丢炸弹，看能不能帮我们出去？$B$B我们偷来的飞艇就在那里……我都听见它的声音了！趁它起航之前跳上去！"
D.Strings[18486]="我是个囚犯！$B$B这帮混蛋把我美丽的飞艇从天上打了下来。你知道这是为什么吗？就因为我帮部落运输了一些士兵和补给物资！这算什么新鲜事嘛！真是的！$B$B现在他们逼我开着飞艇在海湾上巡逻，帮他们轰炸海盗。现在飞艇的零件短缺得厉害，她随时都有坠毁的危险！我几乎靠口水和绳子才能保证她不散架！$B$B我跟你说，这是违法的！"
D.Strings[18487]="我是个囚犯！$B$B这帮混蛋把我美丽的飞艇从天上打了下来。你知道这是为什么吗？就因为我帮部落运输了一些士兵和补给物资！这算什么新鲜事嘛！真是的！$B$B现在他们逼我开着飞艇在海湾上巡逻，帮他们轰炸海盗。现在飞艇的零件短缺得厉害，她随时都有坠毁的危险！我几乎靠口水和绳子才能保证她不散架！$B$B你要是出了什么事，我可不负责，不过你最好趁她起航前跳上去。$B$B我跟你说，这是违法的！"
D.Strings[18488]="我是个囚犯！$B$B这帮混蛋把我美丽的飞艇从天上打了下来。你知道这是为什么吗？就因为我帮部落运输了一些士兵和补给物资！这算什么新鲜事嘛！真是的！$B$B现在他们逼我开着飞艇在海湾上巡逻，帮他们轰炸海盗。现在飞艇的零件短缺得厉害，她随时都有坠毁的危险！我几乎靠口水和绳子才能保证她不散架！$B$B如果你愿意帮忙的话，就去那边候着吧。她在1分钟之内就会入港。$B$B我跟你说，这是违法的！"
D.Strings[18489]="我的飞艇刚刚入港。虽然我被扣押起来充当人质，而且飞艇本身的状态也不太好，但是2分钟后，她就要再度起航了。"
D.Strings[18490]="1分钟后，飞艇就要出发绕海湾一圈了！有没有谁想搭救我啊，我就在码头上。"
D.Strings[18491]="熊熊燃烧的火焰熄灭了。"
D.Strings[18492]="打断"
D.Strings[18493]="撤退！！！！"
D.Strings[18494]="那么，祖阿曼的挖掘工作何时开始呀？"
D.Strings[18495]="$n，要有耐心。若是我像你这般草率行事，也就不会成名了。$b$b做好最后的准备工作，祖阿曼的财富和秘密很快就属于我啦！$b$b<巴德看了看你，轻声地笑了。>$b$b……哎呀，我是说属于我们俩啦。"
D.Strings[18496]="监护员！那个坏人是来吃我们的吗？"
D.Strings[18497]="要是我爸爸活着的话，他会把火灭掉的！"
D.Strings[18498]="要是我妈妈活着的话，她会把火灭掉的！"
D.Strings[18499]="加尔，这是送你的礼物，祝贺你乔迁新居。"
D.Strings[18500]="来吧，打开它。我想你会喜欢的。"
D.Strings[18501]="加尔？"
D.Strings[18502]="除非是吃的东西，否则我不想要。"
D.Strings[18503]="加尔，我总觉得你不太对劲。出了什么事？"
D.Strings[18504]="没什么。有兴趣帮我炖青蛙腿吗？"
D.Strings[18505]="加尔，我专程来拜访你！你却躲在这个偏僻的小屋里炖青蛙腿？真是无可救药！"
D.Strings[18506]="%s在井旁哼唱了一支小曲。"
D.Strings[18507]="%s笑了笑，继续从井中打水。"
D.Strings[18508]="莉丝安向井中扔下一枚硬币，然后环顾四周观察着是否有人注意到她。"
D.Strings[18509]="管你是谁，给我滚远点！女巫岭属于我……属于我！"
D.Strings[18510]="太……太可怕了……恶魔……"
D.Strings[18511]="庄园……下一个牺牲者……很快就会被吞噬……"
D.Strings[18512]="黑暗……堕落……悄无声息地侵蚀了大地……"
D.Strings[18513]="陌生人，你来这儿做什么？你会堕入痛苦的深渊！落得和我们一样的下场……"
D.Strings[18514]="黑暗将吞噬一切……生命……"
D.Strings[18515]="太晚了。趁你们还活着……赶紧带着你的朋友离开这里吧。"
D.Strings[18516]="对加尔来说太晚了……它的控制力太强大了……"
D.Strings[18517]="我的工作就是日夜不停地制造弹药或是给弓换弦。$B$B你需要帮助吗？"
D.Strings[18518]="芬雷，让我看看你出售的货物。"
D.Strings[18519]="听着，$c，我知道你和你的朋友非常熟悉艾泽拉斯世界。你们一定遇见过好些渴求名望和财富的家伙。$b$b如果有谁对祖阿曼感兴趣的话，记得介绍给我认识哟，我会酬谢你的。"
D.Strings[18520]="在你们这些可怜的种族踏足这里之前，这片土地就属于我了！"
D.Strings[18521]="所有胆敢冒险进入这里的家伙都会成为我的财产，你也一样！"
D.Strings[18522]="他逃走了？万岁！"
D.Strings[18523]="万圣节是个可怕的节日，但我喜欢！"
D.Strings[18524]="在远古魔法的作用下，这场森林大火绵延燃烧了数年都不曾熄灭。这里本是始祖龙女王及其配偶的栖息地。$B$B然而，某个早已被遗忘的邪恶种族已经觉醒，并企图再次奴役始祖龙女王的后裔，让它们为自己服务。$B$B这些维库人最近在灰烬龙巢附近频频滋事，严重威胁到你们的安危。"
D.Strings[18525]="这简直是对我们的侮辱！赤裸裸的侮辱！他们拒绝我们参与矮人历史悠久的传统节日！"
D.Strings[18526]="他们企图利用蛮力达到复仇的目的！散开！"
D.Strings[18527]="这块公告板被热砂集团派驻泥链镇的代表用来张贴悬赏和工作通知。"
D.Strings[18528]="我觉得德拉兹特根本找不到有能力杀死那头迅猛龙的人。我的意思是说，他已经两次提升赏金了……"
D.Strings[18529]="继续射击！阻挡他们的援军！"
D.Strings[18530]="掩护射击！"
D.Strings[18531]="将他们从主力部队中孤立出来！"
D.Strings[18532]="探险队使用的伪装都准备好了吗？"
D.Strings[18533]="事实上！他们向我提出了所有我能做到的改进建议。我简直不能想像什么地方会有问题。$b$b好吧，$c，拿上这个。我做了一些的修改——一些很小很小的修改。现在没有任何失败的借口了！"
D.Strings[18534]="你是在暗示我给祖尔金送去活人祭品吗？"
D.Strings[18535]="说什么呢！$b$b我只是想铲除邪恶势力啊，你应该知道，这种事情肯定要付出代价的嘛。$b$b$n，换个角度来想吧。我这是为普通人谋福利，让他们有机会成为世人瞩目的英雄！多么难得的机遇呀！$b$b你只需让他们来这儿找我，剩下的事就交给我来应付好了……"
D.Strings[18536]="难道我们就这样躲藏在深山里，任由那帮嗜酒的狂徒在拒绝邀请我们的情况下举办庆典？！"
D.Strings[18537]="对极了！我们得让这帮家伙明白，和黑铁矮人作对没什么好下场！"
D.Strings[18538]="所有人都想毁灭阿曼尼帝国。但现在，我们有盟友了。我们和赞达拉一同战斗，我们更加强大了！你们无法阻止我们！整个世界都将溺毙在鲜血中！"
D.Strings[18539]="打碎他们的酒桶！倒掉这些美酒！"
D.Strings[18540]="你最好站远点。剖鱼是件肮脏的活。"
D.Strings[18541]="说得太好了！"
D.Strings[18542]="艾泽拉斯世界的凡人们，接受我的赐福吧！邪恶的祖尔金已经死啦！"
D.Strings[18543]="这些是幽暗城送来的最后10份药剂样本……可它们毫无价值！"
D.Strings[18544]="这样叫我怎么研究！我需要一份能在这种气候下存活的药剂样本！"
D.Strings[18545]="他们送来的药剂样本连只老鼠都杀不死！"
D.Strings[18546]="幽暗城的药剂样本原本已经取得了一些进展。但是不知道怎么回事，突然又不行了！"
D.Strings[18547]="皇家药剂师协会欢迎你来到诺森德，$c。你愿意为我们伟大的希尔瓦娜斯女王陛下做些什么呢？"
D.Strings[18548]="%s吸收了野熊之魂的精华！"
D.Strings[18549]="快！快跑！"
D.Strings[18550]="你别想抓到我！"
D.Strings[18551]="去，去啊！"
D.Strings[18552]="白痴，到这边来！"
D.Strings[18553]="龙族的帮手，去死吧！"
D.Strings[18554]="滚出石槌食人魔的领地！"
D.Strings[18555]="为什么要惊扰沉睡的鬼魂？别的石槌食人魔呢？！"
D.Strings[18556]="%s显得非常虚弱，可以捕捉了！"
D.Strings[18557]="休息时间。"
D.Strings[18558]="留神点。"
D.Strings[18559]="工作的时候动点脑子。上尉要求周末前必须完成这项工事！"
D.Strings[18560]="休息时间结束了。"
D.Strings[18561]="你知道你在干什么吗？"
D.Strings[18562]="动作快点！"
D.Strings[18563]="不！向左一点点……好，就这样。"
D.Strings[18564]="当心撞上横梁！"
D.Strings[18565]="照目前的速度，我们肯定完不成任务。"
D.Strings[18566]="$c，我没有什么能教你的了。如果你想要了解更多关于珠宝加工的知识，就和我的同事卡琳达谈谈吧。"
D.Strings[18567]="我所掌握的附魔技能都传授给你了。去找瑟丹娜吧，她能教给你更多东西。"
D.Strings[18568]="如果你想要进一步提升自己的裁缝技能，就去和我的雇主基伦谈谈吧。他所掌握的裁缝知识远远超越我。"
D.Strings[18569]="%s吸收了雄鹰之魂的精华！"
D.Strings[18570]="%s吸收了山猫之魂的精华！"
D.Strings[18571]="%s吸收了龙鹰之魂的精华！"
D.Strings[18572]="这里的情况比我想象的糟得多！飞艇并不比一堆扭曲的金属和燃烧的燃料好多少！"
D.Strings[18573]="你惊动了一头海狮，它立即向同伴发出了警报。"
D.Strings[18574]="谢谢你！真不知道那些野蛮人会怎么对付我。"
D.Strings[18575]="%s发现了一顿美餐！"
D.Strings[18576]="欢迎来到塞拉摩，$c。"
D.Strings[18577]="我们来自黑石山，\n我们来喝你的酒！\n黑铁矮人说到做到，\n你对此清楚得很！"
D.Strings[18578]="你未曾体会过我们的痛楚，\n你未曾品尝过我们的麦酒！\n美酒节上缺了我们的参与？\n试试看吧，你只会落得惨败的结果！"
D.Strings[18579]="举杯向科林祝酒，\n还有霍尔雷·黑须！\n酒味淡雅不上头，\n好在它还算是杯酒！"
D.Strings[18580]="我们畅饮辛辣的烈酒，\n喝光所有的酒桶！\n饮酒、猜拳，猜拳、饮酒，\n直到双腿失去知觉！"
D.Strings[18581]="饮下所有的美酒\n我们跳到暗影熔炉上\n向拉格纳罗斯举杯……\n……但是一滴酒都不给他尝！"
D.Strings[18582]="射手，列队准备！"
D.Strings[18583]="听我的命令！准备，瞄准……"
D.Strings[18584]="是信号弹。左侧炮台，准备！"
D.Strings[18585]="校准射程。"
D.Strings[18586]="中央炮台，准备。"
D.Strings[18587]="右侧炮台，准备。"
D.Strings[18588]="伊莱先生！"
D.Strings[18589]="那些捡回的炮弹呢？"
D.Strings[18590]="很好。伊莱，继续。"
D.Strings[18591]="炮兵们正在执行轰炸任务呢，长官！"
D.Strings[18592]="所有炮台，准备。"
D.Strings[18593]="这些炮弹每天都会被打到斯克恩或是地平线那边的某些地方去，但你知道为什么晚上又会回到这里吗？$B$B炮弹回收任务！$B$B但这工作跟我的合约完全不对口，你知道吗？"
D.Strings[18594]="休息会吧，小甜甜，要不要来点吃的，放松放松？$B$B这里就你最需要休息啦。"
D.Strings[18595]="有什么吃的，塞蕾丝？"
D.Strings[18596]="上，恶魔！"
D.Strings[18597]="对！咬持剑的手！"
D.Strings[18598]="放松，孩子！别把这靶子给打散架了。"
D.Strings[18599]="我投降！把刀拿开！"
D.Strings[18600]="我跟你回去。请放过我的手下吧。他们还很年轻，犯点小错误也是难免的……"
D.Strings[18601]="这是什么？不，这中间肯定有误会。我可以解……解释……"
D.Strings[18602]="嗯，这就是巴德？"
D.Strings[18603]="你就是那个被俘虏们终日咒骂的家伙？我还以为你有多大能耐呢！"
D.Strings[18604]="只要你们能将祭品塞满这些笼子，我就不会要你们的命。"
D.Strings[18605]="你给我听着——如果篝火堆旺不起来，无论你躲在何处，我都会把你揪出来，用你当燃料！"
D.Strings[18606]="从此以后，你的灵魂将永远是我的玩物……"
D.Strings[18607]="巴德，我们总会碰面的。我相信这一天很快就要来了。"
D.Strings[18608]="除非有紧急事务，否则我没有太多时间与你闲聊，公民。我肩负着保卫塞拉摩的重要使命。"
D.Strings[18609]="艾登中尉总是自愿地承担起驻守城门的重任。我对此没什么意见。$b$b我喜欢呆在岗哨，既能看到手下的侍卫，还能欣赏商人的女儿。"
D.Strings[18610]="你是来换班的吗？时间刚刚好呢。如果你愿意换班的话，我就能喝上两杯啦。"
D.Strings[18611]="感谢圣光，迪菲亚的那帮家伙对潜水一窍不通。"
D.Strings[18612]="我的潜水设备弄丢了，你还有备用的吗？"
D.Strings[18613]="我能提供的工程学结构图非常有限，你得向丹文讨教讨教。他会让你见识到工程学的精妙之处！"
D.Strings[18614]="你就不能挑个更好的时候来吗！我们赶紧离开这里。"
D.Strings[18615]="好了，我们走吧……但别忘记给联盟留下点终身难忘的东西！"
D.Strings[18616]="这座营地的补给物资有限。真要出什么差错的话，他们就完蛋了。"
D.Strings[18617]="亚当斯上尉派我来调查哈尔格林德到底发生了什么事。我以这座被废弃的维库人哨塔为掩护，费了好大的工夫，最多只能靠到这么近了。$B$B被遗忘者一定在秘密策划着什么。我感觉得到！"
D.Strings[18618]="啊，对……看着它烧个精光！"
D.Strings[18619]="我们离成功很近了！"
D.Strings[18620]="你们这帮联盟的渣滓，尝尝药剂师的厉害吧！"
D.Strings[18621]="我们赶紧逃离这里吧！"
D.Strings[18622]="别动手！是药剂师！"
D.Strings[18623]="我们欠你的情，朋友。与复仇港的雷杉德尔谈谈吧，他会给你一份适当的酬劳。"
D.Strings[18624]="啊哈哈哈哈！我要挖掘出真相！"
D.Strings[18625]="我什么都不想知道了。让我都忘了吧！"
D.Strings[18626]="人们只要专注于研究和挖掘，他们就能发现真相。"
D.Strings[18627]="我们安全了，它不会追到这里的！"
D.Strings[18628]="末日即将降临！那位不可名状之存在就要重获自由了！"
D.Strings[18629]="它来了！快躲起来！"
D.Strings[18630]="如果时间再充裕一点就好了！"
D.Strings[18631]="原谅我吧，伟大的主！我不是故意要挖掘真相的。"
D.Strings[18632]="这真相将给予你自由。很快，你就会成为我们的一员！"
D.Strings[18633]="既然你已经知道了真相，我就更不能让你离开了！"
D.Strings[18634]="一切即将结束。接受那位不可名状之存在的拥抱吧！"
D.Strings[18635]="入侵者！你是来杀我们的吧！"
D.Strings[18636]="你不能走……不能让它找到我们！"
D.Strings[18637]="你在这里，那么它肯定就在后面不远处！"
D.Strings[18638]="在你了解到这恐怖的真相之前，我要结束你的生命！"
D.Strings[18639]="现在你必须加入我们了……永远地！"
D.Strings[18640]="欢迎来到塞拉摩。"
D.Strings[18641]="$c，今天你想学习哪些附魔公式？"
D.Strings[18642]="今天我是不是可以为你展示一两张新图样？"
D.Strings[18643]="你的锻造技能已经超越了我所掌握的范围，不过那边的波玛尔能教给你更多知识。"
D.Strings[18644]="我所掌握的知识非常有限，卡博隆在炼金术方面的造诣比我厉害得多。如果你想要继续提升自己的技能，就和他谈谈吧。"
D.Strings[18645]="如果消息来源不可靠的话，吉安娜女士也不会急着派信使来暴风城。"
D.Strings[18646]="迪菲亚兄弟会寻得了新的庇护，他们在暴风城国王失踪事件中显然扮演了不光彩的角色，我们必须重新制定进攻迪菲亚兄弟会的计划。"
D.Strings[18647]="代我向吉安娜女士致谢。请转告她，在国王安全归来之前，我们不会停止对迪菲亚兄弟会及其支持组织的攻击。"
D.Strings[18648]="$c，莱纳里斯更适合担当你的导师。想要学习更多关于制皮的知识，就和她谈谈吧。"
D.Strings[18649]="伯瓦尔，别犯傻了！"
D.Strings[18650]="迪菲亚兄弟会不过是群乌合之众。我们要对付的应该是真正有威胁的对手，而不是在这里捕风捉影。"
D.Strings[18651]="我已经做好前往暴风城的准备了。"
D.Strings[18652]="很高兴见到你，$c。"
D.Strings[18653]="能替我捎个信吗？乌瑞恩国王有一封紧急信件要交给塞拉摩岛的吉安娜女士。"
D.Strings[18654]="奥格瑞拉必将恢复和平！"
D.Strings[18655]="$n，想要提升你的炼金术技能，就去找鲁克谈谈吧。"
D.Strings[18656]="暗月卡片共有八套：野兽、祝福、元素、报复、愚人、入口、风暴和督军，每套卡片各有八张。如果你能集齐一套八张卡片，就能用一副暗月套牌在萨杜斯·帕雷教授处兑换到强大的饰品。"
D.Strings[18657]="无头骑士正在村子里到处放火！我们必须要保护孩子们！"
D.Strings[18658]="无头骑士来了！快一点，帮助你们的部落同胞保卫村庄！"
D.Strings[18659]="无头骑士暂时被击退了。我们可以稍微松口气，但是仍然不能掉以轻心。"
D.Strings[18660]="监护员！无头骑士会吃掉我们吗？"
D.Strings[18661]="要是妈妈还活着的话，她会赶来灭火的！"
D.Strings[18662]="他逃走了吗？万岁！"
D.Strings[18663]="欢迎再次光临外域最精彩的盛会，朋友！很高兴再次见到你。$B$B来，尽情体验我们精心准备的节目吧。记得四下看看哟，我们会不断在暗月马戏团中引进新奇刺激的玩意儿！瞧瞧这些熟悉或是新鲜的事物！我们会尽力为孩子们带来欢乐！"
D.Strings[18664]="朋友，你好。欢迎光临外域最精彩的盛会！$B$B来，尽情体验我们精心准备的节目吧。瞧瞧这些新奇玩意儿，它们是暗月马戏团从这个广袤而神秘的世界中收集来的！我们会尽力为孩子们带来欢乐！"
D.Strings[18665]="大家玩得还开心吗？很好！欢迎来到外域最精彩的盛会——暗月马戏团！记得与亚布·尼比盖尔和他的朋友谈谈。"
D.Strings[18666]="欢迎大家来到世上最隆重的庆典——暗月马戏团！我们拥有各色各样美味的食品、甘甜的佳酿、奇异的器物、神秘的塔罗牌、精美的礼品，还有难以自抑的激动氛围！别忘记在吉瓦斯·格里加特处兑换暗月马戏团奖券！五张奖券就能兑换到哦，还有更多令人称奇的奖品在等着你呢。所有人都有份！"
D.Strings[18667]="我会照顾好你的宠物的，不要担心！"
D.Strings[18668]="暗月马戏团是整个外域最隆重的庆典！"
D.Strings[18669]="谁来品尝一下，绝赞的美酒噢！！"
D.Strings[18670]="欢迎来到塞拉摩，$c。你在找什么？"
D.Strings[18671]="你看起来是个非常明智的人。为什么不来读一读这份传单并谈谈你的想法呢？"
D.Strings[18672]="不是我！我发誓，其实是$n干的！"
D.Strings[18673]="啊啊啊！这都是$n的主意！森林巨魔是我最好的朋友……"
D.Strings[18674]="真不该把主力部队留在瓦加德。都是凯勒中将那个自大狂的错！$B$B现在手头就这么点人，我们怎么执行任务？这里的要塞需要驻军，维德瓦堡垒也需要部队！$B$B不过你既然来了，或许我们需要担心的就能少一些啦。"
D.Strings[18675]="我按照上尉的意思，提供了针对部分决策的参考意见，但是我觉得他更想听听你的看法。"
D.Strings[18676]="这么多张嘴要喂，谁来喂？我！$B$B做饭、洗碗，还有买菜什么的全都是我在做！"
D.Strings[18677]="……逃亡者内衣对折出售？这是什么玩意儿？"
D.Strings[18678]="……逃亡者能尽情享受游泳与喂狗的乐趣？可笑！"
D.Strings[18679]="这些年来，我从来没想过还能看见这样的新疆界。$B$B只是，这里已经被邪恶玷污，亘古流传的知识也被掩埋了。"
D.Strings[18680]="我也算得上是经历丰富吧，可这次探险者协会在低语峡谷的遭遇还是超出了我的想象。$B$B能从那里逃生，我真是万幸！"
D.Strings[18681]="……逃亡者要建立一个新的塞拉摩岛，所有的城民都能为所欲为？这是什么狗屁？"
D.Strings[18682]="我没有什么能教给你的了。去找我的导师法里谈谈吧，她会传授给你更多关于珠宝加工的新知识的。"
D.Strings[18683]="……把小鸡绘在塞拉摩岛的旗帜上？！这些家伙是不是疯了！"
D.Strings[18684]="……建立一笔基金来购买发胶？算了吧，我喜欢我现在的发型！"
D.Strings[18685]="朋友，接下来由米阿尔做你的导师吧。我已经没有什么可教给你的了。"
D.Strings[18686]="朋友，你在我这里的受训课程就快结束了。阿克汉姆会继续向你传授新知识的。"
D.Strings[18687]="现在是你向别的导师讨教新知识的时候了。奥克基尔在工程学方面的造诣非同寻常，他会继续指引你的。"
D.Strings[18688]="过奖了，你应该找我的同事雷菲克谈谈的。"
D.Strings[18689]="$c，我所掌握的附魔技能已经不能满足你求知的欲望了。请和纳霍加谈谈吧。"
D.Strings[18690]="学习讲究循序渐进，不能操之过急。和费卢尔谈谈吧，好好向他讨教。"
D.Strings[18691]="现在是你继续提升技能的时候了。前往达纳苏斯的工匠区找泰龙尼斯谈谈吧，接下来由他来训练你。"
D.Strings[18692]="如果你想要了解炼金术的基础知识，就和迪里兹谈谈吧。"
D.Strings[18693]="$n，你想目睹泰达希尔巨大的树枝吗？你真该去那儿，有位暗夜精灵能教给你更多关于炼金术的知识。去达纳苏斯的工匠区找安尼希尔谈谈吧。"
D.Strings[18694]="现在还不是时候呢，你先和埃德雷姆谈谈吧。他会教给你关于锻造的基础知识的。"
D.Strings[18695]="你很可能会问，“接下来该找谁呢？”我知道答案。要学习更多关于锻造的知识，你就得跨越无尽之海，前往庄严的铁炉堡。铁炉堡中的那尊熔炉是世上最大的！大熔炉处的本古斯·深炉就是你要找的训练师。"
D.Strings[18696]="牛头人酋长每小时都会登台表演一次。提起精神来吧，让吟游诗人激发他们的灵感，将这盛会吟唱成令人难忘的诗篇！"
D.Strings[18697]="$c，我正忙着呢。你最好和库德里恩谈谈训练的事儿。"
D.Strings[18698]="牛头人酋长音乐会将在30分钟后开演！快来泰罗卡森林欢庆暗月马戏团开张吧，就在沙塔斯城以南！"
D.Strings[18699]="牛头人酋长音乐会将在15分钟后开演！快来泰罗卡森林欢庆暗月马戏团开张吧，就在沙塔斯城以南！"
D.Strings[18700]="牛头人酋长音乐会将在5分钟后开演！快来泰罗卡森林欢庆暗月马戏团开张吧，就在沙塔斯城以南！"
D.Strings[18701]="$n，我所掌握的附魔技能相当有限。你应该前往艾尔文森林的阿祖拉之塔，基塔·费温德就居住在塔中，她是你的下一任导师。"
D.Strings[18702]="外域的居民们，你们准备好了吗？牛头人酋长音乐会现在正式开演！"
D.Strings[18703]="就你目前的水平来说，向基尔玛斯讨教些简单的设计图就成啦。"
D.Strings[18704]="侏儒！侏儒是神奇的种族。他们别提有多棒了！侏儒在工程学上的造诣真是登峰造极啊！前往铁炉堡的侏儒区，和宾斯匹德谈谈吧。"
D.Strings[18705]="啧啧。尊重你的长者。卡亚特才是你的导师。"
D.Strings[18706]="我所掌握的裁缝技能非常有限，已经没有什么可以教你的了。在无尽之海的另一边，暴风城的法师区中有一位伟大的裁缝。他名叫乔吉奥·波利罗，我想由他来做你的导师比较合适。去那儿和他谈谈吧。"
D.Strings[18707]="$n，你的进展真是令我吃惊！现在你该前往外域学习更多关于珠宝加工的新知识了。你可以去地狱火半岛的荣耀堡找塔蒂亚娜谈谈。如果你更喜欢奥尔多的话，就去沙塔斯城的奥尔多高地找哈曼纳尔。"
D.Strings[18708]="$c，你的进展真是神速啊！现在你该前往外域学习更多关于珠宝加工的新知识了。你可以去地狱火半岛的萨尔玛找卡莱恩谈谈。如果你更喜欢奥尔多的话，就去沙塔斯城的奥尔多高地找哈曼纳尔。他是个相当假正经的家伙，我可不建议你去找他。"
D.Strings[18709]="布洛格，我记得我们谈过这个问题。你不能待在房间里。当然啦，你是可以塞进去，不过其他人就没空间了！"
D.Strings[18710]="你说过布洛格可以待在这里的！你许诺过会帮助布洛格夺回石槌氏族的土地！"
D.Strings[18711]="是，我们是说过你可以待在这儿，但是这间房子是我们的总部！所有的手册和蓝图都存放在里面！"
D.Strings[18712]="但这是唯一适合布洛格的房子，地精的房子都太小太小啦！"
D.Strings[18713]="我想说，食人魔的体型也太大了吧！好吧，我打消说服你挪动地方的念头，不过这只是暂时的！"
D.Strings[18714]="地面……已经完全结冰了。我们只能傻傻地坐在这里，这些绞肉车哪里都不能去。"
D.Strings[18715]="高级执行官安希尔姆要求你立刻报告情况。"
D.Strings[18716]="这也太可怕了吧？这地面简直冻得跟岩石一样硬！$B$B你瞧，这些轮子之前还是陷在烂泥里，现在和泥土冻成一块了！恐怕得叫个憎恶用铁链将它们拖出来。"
D.Strings[18717]="我绝不会把蕨墙村当作自己的家。那么做就等于放弃了收复失地的希望。"
D.Strings[18718]="嗨，$c。我叫阿什莉，巴德派我和一群令人讨厌的巨魔和臭气熏天的兽人和愚蠢的人类还有一个喝醉的矮人来这儿结果我们被一群超级超级坏的巨魔抓住了然后我们就被关进了笼子更可怕的是这里还有一头非常非常残忍的巨魔豹它专吃牢笼中的囚犯所以我想它很快就会来吃我了但是凭我自己的力量是不可能逃出这里的所以……$B$B<阿什莉深深地吸了口气。>$b$b你能杀死那头猛兽吗？"
D.Strings[18719]="地精杂烩煲"
D.Strings[18720]="钓鱼椅"
D.Strings[18721]="幽灵虎坐骑"
D.Strings[18722]="诅咒这片冻土！我们的绞肉车还怎么上前线！"
D.Strings[18723]="见鬼！还不如把这些东西拆成零件好了！它们根本毫无用处。"
D.Strings[18724]="快把轮子挖出来，我们没时间了！"
D.Strings[18725]="陌生人，听着。我很乐意坐下来聊聊，不过我头痛得厉害。$b$b不如你先让这帮一无是处的巨魔安静点，然后我们再谈，怎么样？"
D.Strings[18726]="好吧，$r，算我欠你情啦。$b$b在你出现之前，我还以为这是我最后一口酒呢。"
D.Strings[18727]="那么，一个像你这样的矮人到底是怎样沦落到这里的呢？"
D.Strings[18728]="那是个伤心的故事——还有几分尴尬。$b$b矮人嗜酒如命可是众所周知的事。我自然也不例外，而且我对美酒的喜爱程度完全超越了我的想象。$b$b就这样，我遇见了巴德。他说只要我愿意加入探险队，就能尽情享受所有的美酒。我经受不了诱惑，做出了令我后悔至今的决定。$b$b那天晚上，我喝下足以放倒一头科多兽的烈酒之后，跟随巴德的杂牌探险队进入了祖阿曼。$b$b待我清醒时，发现自己已经沦为囚犯了。"
D.Strings[18729]="噢，谢谢你帮我逃离了牢笼我被囚禁了好久那里闻起来就像被太阳曝晒了一周的碎羊肉但是呢我很讨厌羊肉因为我在很小很小的时候被变成了一头羊而且长达一分钟因此我很清楚做羊的滋味所以我自然不希望被吃掉尤其是被打扮得像猫的大巨魔吃掉……$b$b<阿什莉深深地吸了一口气。>$b$b我的发型没乱吧？"
D.Strings[18730]="像你这样自信的小侏儒怎么会陷入如此窘境呢？"
D.Strings[18731]="我本想利用家门口的小兔子练习我的魔法技能这样我就能消灭盘踞在诺莫瑞根的坏人让所有侏儒回到自己的家园但是妈妈说我还太年轻不适合出来冒险再后来我遇到了巴德先生他说我其实很成熟啦完全可以和他的朋友们一起来这里他还说我可以在这里进行全面的练习呢接下来我们就被抓住了然后被关进了笼子……$b$b<阿什莉深深地吸了一口气。>$b$b你真的是$r吗？"
D.Strings[18732]="进退两难的联盟水手想必已经明白他们难逃一死，却选择了负隅顽抗。$B$B真是可悲可叹啊。"
D.Strings[18733]="击败荒弃海岸的联盟只是时间问题。他们已经被包围了，而且我们还占有数量优势。"
D.Strings[18734]="希尔瓦娜斯的意志在上，我们的敌人终将失败。"
D.Strings[18735]="高级执行官安希尔姆要求你立刻报到。"
D.Strings[18736]="就是城墙上的那两尊大炮延缓了我们的攻城速度。要是没有它们的保护，城墙上的守军早就会被我们杀得丢下要塞仓皇逃命去了。$B$B现在我们有两个选择，摧毁那些大炮，或者等他们弹药消耗完。就看安希尔姆怎么决定吧。"
D.Strings[18737]="无头骑士本是白银之手的成员，可惜这位昔日的英雄被诅咒了。他盘踞在血色修道院中，失去理智的无头骑士竟然认为自己还活着，我们才是没有生命的亡者。$B$B他再也不是圣光忠诚的仆从了。随着万圣节的来临，他在艾泽拉斯世界各地的村落中散播着阴暗的种子，还有那仇恨的火焰。"
D.Strings[18738]="无头骑士是谁？"
D.Strings[18739]="别管我，$r。$b$b克拉斯活着跟死了也没什么两样。趁那些巨魔还没发现你，快逃命吧。"
D.Strings[18740]="把你们的灵魂给我，帮助我消灭敌人！"
D.Strings[18741]="把他们打成肉酱！把他们的脸打扁！"
D.Strings[18742]="守住防线！把维库人赶回去！"
D.Strings[18743]="杀光维库杂种！希尔瓦娜斯万岁！"
D.Strings[18744]="别让维库人冲过去！杀光他们！"
D.Strings[18745]="看来有的事还是得戈斯亲自动手！"
D.Strings[18746]="你不是戈斯的对手！"
D.Strings[18747]="戈斯不在乎会不会搭上性命！戈斯要把他们都打扁！"
D.Strings[18748]="自由啦！克拉斯的痛苦结束了。$b$b谢谢你，$c。"
D.Strings[18749]="兽人，你怎么啦？"
D.Strings[18750]="克拉斯就不该来这个鬼地方……不该相信人类。我真是个大傻瓜，$c，你莫非也是听信了巴德的鬼话来进来的？$b$b我的儿子已经失踪两个月了，据说有人最后一次看见他是和巴德在一起。巴德说我或许可以在祖阿曼中找到他的下落……$b$b我跟着探险队来到这里，然后沦为俘虏。要不是你帮忙，我肯定没命了。$b$b陌生人，谢谢你。"
D.Strings[18751]="成功了！我们打败了泰瑟尔！"
D.Strings[18752]="我们打败了海怪！"
D.Strings[18753]="过来暖和暖和，让你那一身疲倦的骨头歇歇。我们很好客的。"
D.Strings[18754]="你已经无法阻止我了！我们的王，马上就要苏醒了！"
D.Strings[18755]="求你了，带我离开这里！"
D.Strings[18756]="钥匙……你得先找到钥匙！"
D.Strings[18757]="我好像在那些维库人身上见过钥匙。"
D.Strings[18758]="我不要被他们拖进下面的墓穴！"
D.Strings[18759]="我不要成为祭品！"
D.Strings[18760]="他们正在下面的墓穴中举行邪恶的仪式，我马上就要变成他们的祭品了！"
D.Strings[18761]="有没有英雄来救我啊？"
D.Strings[18762]="这就是一切的结束。"
D.Strings[18763]="噢，谢谢你，谢谢你！"
D.Strings[18764]="谢谢你，我永远不会忘记你的恩情！"
D.Strings[18765]="为那些沦为祭品的朋友复仇！"
D.Strings[18766]="你必须阻止这疯狂的一切，否则就来不及了！"
D.Strings[18767]="谢谢你，英雄！"
D.Strings[18768]="必须消灭那些邪恶的维库人！"
D.Strings[18769]="你们这群蠢货，不能让风行者号落入敌人手中！给我顶住！"
D.Strings[18770]="我要军法处置负责侦查这片海域的斥候！我们钻进了一个大圈套！"
D.Strings[18771]="把这些联盟狗赶下船！"
D.Strings[18772]="不惜一切代价，保住我们的大炮！"
D.Strings[18773]="遵循圣光为你照亮的道路吧，孩子。"
D.Strings[18774]="火，赐予我洞察……"
D.Strings[18775]="弓箭手准备！瞄准！"
D.Strings[18776]="哪个蠢货竟敢不经觐见就擅自闯入陛下的领域？"
D.Strings[18777]="水，赐予我宁静……"
D.Strings[18778]="但是，你闯入了主上的领域。就凭僭越入侵这一点，他就有权处决你！阿尔萨斯大人对那些逃跑的奴隶没有任何的怜悯与仁慈！"
D.Strings[18779]="%s吸入了从火炉中腾起的轻烟。"
D.Strings[18780]="%s突然陷入了精神恍惚的状态。"
D.Strings[18781]="但是……他已经得知了你们战胜暴风城北方舰队的消息，并且相信你们有足够的潜力，能够明察事理并抛弃希尔瓦娜斯幼稚的复仇理论。"
D.Strings[18782]="谢谢你们，万物之灵。"
D.Strings[18783]="阿尔萨斯准备赐予你力量，超乎你想象的力量。比起以后你将领导的天灾军团来说，眼下你手中的军队简直脆弱得可笑。"
D.Strings[18784]="黑铁矮人！！！"
D.Strings[18785]="他们是来抢夺啤酒的！"
D.Strings[18786]="来人抢救啤酒啊！"
D.Strings[18787]="如果你还珍惜自己的啤酒，就快跑吧！"
D.Strings[18788]="快跑！是黑铁矮人！"
D.Strings[18789]="我们对真相有了一定程度的了解。接下来要彻底揭露真相了！"
D.Strings[18790]="谁敢干涉我们，就得死！"
D.Strings[18791]="他们的到来宣告着世界的末日！"
D.Strings[18792]="你，就是你，别偷懒！"
D.Strings[18793]="我们在这里很安全，兄弟姐妹都很安全，但这世界都要毁灭了。"
D.Strings[18794]="有时候，我甚至希望我什么也不知道。但很快我就意识到现在这样也挺好的。"
D.Strings[18795]="安静，你有没有听见啊？！"
D.Strings[18796]="$n，我的孩子，过来，我有些话要问你。"
D.Strings[18797]="这就是你要说的？"
D.Strings[18798]="把这些渣滓都赶下地狱！开火！"
D.Strings[18799]="它冲我们来了！"
D.Strings[18800]="瞄准它们的眉心！那里是怪兽的弱点！"
D.Strings[18801]="入侵者来啦！"
D.Strings[18802]="别让这些怪物冲进城门！士兵们，坚守防线！"
D.Strings[18803]="$g先生:女士;！我负责保护你的安全。$B$B请下令吧！"
D.Strings[18804]="这些年来，我一直处于迷失的混沌中。现在，我终于看到自己的灵魂变得有多么黑暗……"
D.Strings[18805]="无头骑士来了……"
D.Strings[18806]="你的末日到了……"
D.Strings[18807]="为了伊米隆国王！"
D.Strings[18808]="求饶吧……"
D.Strings[18809]="你的末日来临啦！"
D.Strings[18810]="受死吧，蝼蚁！"
D.Strings[18811]="这些家伙是谁？！"
D.Strings[18812]="他们是从哪儿来的？！"
D.Strings[18813]="他们想要干什么？"
D.Strings[18814]="我不知道，我只知道他们体型魁梧，性情狂暴！"
D.Strings[18815]="总之他们绝对不是侏儒。"
D.Strings[18816]="先停止战斗，让我来问问他们……好吧……管他的！杀啊！"
D.Strings[18817]="这重要吗？"
D.Strings[18818]="我觉得他们是从那座邪恶的大城堡里冒出来的。好吧，我只是瞎猜而已，或许猜错了。"
D.Strings[18819]="白痴……"
D.Strings[18820]="我们会死吗？我不知道……猜测而已。"
D.Strings[18821]="你问的是奖金高达64,000金的竞猜问题？"
D.Strings[18822]="他们只想让你闭嘴！别废话了，战斗吧！"
D.Strings[18823]="让我想起了第二次流沙之战时我驻守塞纳里奥要塞的日子……还记得那个兽人吗？是叫萨鲁法尔？他是我见过的最厉害的家伙。"
D.Strings[18824]="我对兽人没有好感，但是如果现在他在这里就好了。他能将这些家伙大卸八块！"
D.Strings[18825]="听说他待在萨尔身边。没事就在城墙上挂龙头解闷。"
D.Strings[18826]="听说他亲自将不可一世的拉格纳罗斯送回了元素位面……"
D.Strings[18827]="你感受到了死亡的恐惧……"
D.Strings[18828]="尝尝死亡的滋味吧！"
D.Strings[18829]="千万小心那些维库人！这是一个嗜血而凶残的种族，每日所想不过是征伐与杀戮。更何况，他们已经向巫妖王宣誓效忠！维库人在附近建立了多处定居点，他们的人数几乎是你们的5倍。"
D.Strings[18830]="做出选择吧，安希尔姆。回到巫妖王的军队，与天灾军团并肩作战或者对你所谓的女王保持忠诚，直到天灾军团将你驱出他们的家园！"
D.Strings[18831]="这里这里，小猫咪……"
D.Strings[18832]="你在哪儿呢？你这只鬼鬼祟祟的小坏猫！"
D.Strings[18833]="耶！你在这里！"
D.Strings[18834]="瞧你！你这一整天都在找它们啊！"
D.Strings[18835]="那儿有一只！"
D.Strings[18836]="Aranal ledel! 他们的命运归你们处置！"
D.Strings[18837]="$c，我们的狮鹫还在学着适应这里复杂的地貌，因此我只能为你提供峡湾内的短途飞行服务。你想去哪儿啊？"
D.Strings[18838]="我要前往瓦加德港。"
D.Strings[18839]="我要前往西部卫戍要塞。"
D.Strings[18840]="我要前往维德瓦堡垒。"
D.Strings[18841]="别这么快。"
D.Strings[18842]="每一次我望向这个基地时，唯一能看到……就是恐惧……等到天灾军团占领了铁炉堡或是暴风城以后，你们还会感到恐惧吗？不！不会了！知道为什么吗？因为那时候你们早已没命了。"
D.Strings[18843]="如果你感觉脊椎下传来阵阵凉意，甚至有尿裤子的冲动，倒是应该感到欣慰。让这种感觉刺激你的情绪吧。恐惧是唯一能让你保持呼吸的情感。"
D.Strings[18844]="我说得够清楚了吧？你们听明白没？我可不想再送更多的棺材或者阵亡通知单回去了。"
D.Strings[18845]="南瓜头冒出了邪恶的烟雾……"
D.Strings[18846]="%s在你拔下鱼叉时痛苦地大叫起来。"
D.Strings[18847]="召唤无头骑士。"
D.Strings[18848]="不……不……龙颅村……还有……幸存者……"
D.Strings[18849]="我的伤势太重了。没法活着回去了……村民们……被关在笼子里……仪式……"
D.Strings[18850]="我……不行了……失血过多……别管我了，告诉凯勒……还有人在里面……"
D.Strings[18851]="务必转告我的家人……我……永远……爱他们……"
D.Strings[18852]="他们把我们钉在这里，就是为了给其他人一个警告……还有些人活着……囚禁……"
D.Strings[18853]="为我复仇，陌生人……让他们……下地狱……"
D.Strings[18854]="谢谢你，英雄。如果你不介意的话，我想呆在你的身边，向那些家伙复仇！"
D.Strings[18855]="你最好祈祷这笼子能永远关着我，渣滓。"
D.Strings[18856]="帮帮我……只要我能从这个该死的笼子里出来，这帮家伙就有苦头吃了。"
D.Strings[18857]="还能有机会略略报复一下真好。我这就动身返回瓦加德，朋友。"
D.Strings[18858]="你们竟如此渴望将我灭亡。可却不知，首级还在，我便可避过一切灾殃！"
D.Strings[18859]="瞧你这丧气的模样。"
D.Strings[18860]="快点，$c！$b$b这场危机快要失控了。"
D.Strings[18861]="非常感谢！我也去杀那些野蛮人，就当算是感谢你，帮你的忙了。"
D.Strings[18862]="谢谢你，朋友。你的队伍还需要人吗？"
D.Strings[18863]="在我返回瓦加德之前我会尽量帮助你。这是我唯一能做的事了。"
D.Strings[18864]="我听说他们在仪式广场上将囚犯当作祭品供奉给天神。我想，那地方应该是叫亚勒伯龙……"
D.Strings[18865]="这绝不是你最后一次看见我。等乌特加德的大军将你践踏至渣后，我还会回来朝你的尸体吐口水！"
D.Strings[18866]="我要吸取你们的灵魂，我要听你们临死前的哀号！"
D.Strings[18867]="你需要长途旅行么，$n？我的蝙蝠会很快把你送到目的地的。"
D.Strings[18868]="我需要飞往风行者号。紧急军务！"
D.Strings[18869]="%s将能量引导向死者的遗体。"
D.Strings[18870]="卑劣……"
D.Strings[18871]="没有价值的祭品……"
D.Strings[18872]="令人不快的裁决……"
D.Strings[18873]="你失败了……"
D.Strings[18874]="中士，把你的望远镜借给我。"
D.Strings[18875]="%s在囚犯面前得意地摇晃着钥匙。"
D.Strings[18876]="脚下小心，$r。$b$b你绝不会是第一个死在这里的人。"
D.Strings[18877]="你想要吗，猴子？要不要啊？"
D.Strings[18878]="你身上的臭味熏死我了。要不是为了安格博达女王，我早就杀了你。"
D.Strings[18879]="清算之日即将来临。你这样的异端将被彻底消灭……"
D.Strings[18880]="你觉着你的镇子还能撑多久？马上就完蛋啦……瞧着吧，小东西。"
D.Strings[18881]="我倒要看看你们如何抑止内心的恐惧而奋起反抗，小家伙！"
D.Strings[18882]="我心中的黑暗面正逐渐膨胀……我就要接受审判了……为了瓦格里！为了巫妖王！"
D.Strings[18883]="一只潜伏在阴影中的生物显身了！"
D.Strings[18884]="空中传来炮弹划过的声音，远处的火光忽隐忽现。"
D.Strings[18885]="这些联盟蛤蟆真是太讨厌了！居然还敢登上满员的被遗忘者驱逐舰……这真是我听过的最愚蠢的自杀方式。"
D.Strings[18886]="哈哈！就凭你也想阻止我完成升华仪式？没人有这个本事！"
D.Strings[18887]="你以为我不知道你想干什么吗？你以为我没有在观察着你的一举一动吗？"
D.Strings[18888]="你不可能阻止我完成升华仪式，卑微的$r。去死吧！"
D.Strings[18889]="不可能！你不可能击败我！"
D.Strings[18890]="我和姐妹们都欢迎您造访，$R。"
D.Strings[18891]="太不走运了，哈尔弗丹。"
D.Strings[18892]="哈尔弗丹，你没有资格获得升华。你的灵魂将坠入湮灭的深渊！"
D.Strings[18893]="对敌军舰队的测试报告出来了，长官！"
D.Strings[18894]="呃……好消息是增援部队撤退了。"
D.Strings[18895]="这种药剂效力不是非常……强。但是，目前已知的有害效果包括晕眩、平衡感丧失和剧烈的胃痛。"
D.Strings[18896]="很好。那么结果如何呢？"
D.Strings[18897]="直说吧！坏消息是什么？"
D.Strings[18898]="保持警惕，$n。$b$b我们还没有走出这片森林呢……"
D.Strings[18899]="我们是皇家药剂师协会的成员！药剂引起胃痛不在我们的工作范围之内！"
D.Strings[18900]="你们都是业余的吗？明天早上，我要见到一份完整的分析报告！拉维恩，给我做事去！"
D.Strings[18901]="你好，陌生人。如果你是在找一处用武之地，那么恭喜你，你找到了。$B$B那些亡者从坟墓中爬出来，在大地上游荡，并乘着船飘洋过海来到这里。峡湾的局势越来越严峻了，再这样下去，我们就不得不往北逃亡了。"
D.Strings[18902]="我是来此协助与保护你的。$B$B接下来我们要如何打击敌军呢？"
D.Strings[18903]="望远镜借我用一下。"
D.Strings[18904]="过来点，年轻人，我的耳朵已经不那么好用了，说话声音也不如以前洪亮了。"
D.Strings[18905]="我在这儿呢，你这蠢货！"
D.Strings[18906]="上尉，我弄丢了指挥官徽记。"
D.Strings[18907]="好吧，再给你一枚。这次千万别再弄丢了！"
D.Strings[18908]="灰烬图腾酋长，我弄丢了你给我的徽章。"
D.Strings[18909]="好吧，再给你一枚。千万别再弄丢了。"
D.Strings[18910]="你这家伙真令我作呕！"
D.Strings[18911]="该死，普罗伊！你把密码表放到哪去了！"
D.Strings[18912]="就像这探险者协会一样把我一个人丢在这里，甚至连一口麦酒都没得喝！"
D.Strings[18913]="你怎么会让整个探险队都丢了性命？"
D.Strings[18914]="看看这是谁来了。"
D.Strings[18915]="这些天，凯勒的士兵都没带回什么消息……不过，没有消息就是最好的消息。"
D.Strings[18916]="你的生命到此结束！"
D.Strings[18917]="你的种族就是世界的污点！"
D.Strings[18918]="天啊！凯勒！遗址那里的情况怎么样了？还是没消息吗？"
D.Strings[18919]="我已经跟你说过很多次了，米科索夫。我已经派出至少三支救援队进入遗址了，而且一支都没有回来。我还要保证港口的正常运转呢！你马上从我面前消失！"
D.Strings[18920]="只能祈祷治疗方案能生效了。"
D.Strings[18921]="我根本没有能治疗你们的药品和器械。"
D.Strings[18922]="别担心，士兵。亚米娜会照顾好你的。"
D.Strings[18923]="我需要搭乘巨型蝙蝠去拦截联盟援军。"
D.Strings[18924]="饮酒！划拳！饮酒！划拳！"
D.Strings[18925]="这是怎么了！"
D.Strings[18926]="谁把那只蝙蝠给我打下来！"
D.Strings[18927]="这液体……真是难闻！"
D.Strings[18928]="现在，让我来告诉你们什么叫……数量优势。"
D.Strings[18929]="当暗月马戏团开始展览的时候，他们会出现在泰罗卡森林。我们会在沙塔斯城南边搭建帐篷！"
D.Strings[18930]="暗月马戏团正在外域的泰罗卡森林开张，就在沙塔斯城的南边。走过路过不要错过！"
D.Strings[18931]="能与你一起战斗是我的荣幸。"
D.Strings[18932]="与你并肩战斗对我来说是莫大的荣誉。"
D.Strings[18933]="猎犬似乎闻到了北边有什么东西，正全速冲向气味的发源地。"
D.Strings[18934]="冲到目的地后，猎犬却变得躁动不安，似乎想要逃窜。看来是被那股气味给唬到了。"
D.Strings[18935]="药剂的用途如此广泛，我们得加紧研究！"
D.Strings[18936]="你是不是已经完全恢复了？我们再试一次……"
D.Strings[18937]="嗯，要略微降低压力才行……"
D.Strings[18938]="实验体仍在呼吸。再来一份剂量……"
D.Strings[18939]="能在这么短的时间内取得这样的进展已经很了不起了。我们再试一次……"
D.Strings[18940]="告诉我你感觉怎么样。"
D.Strings[18941]="实验体的生命力还真是顽强啊。加大剂量……"
D.Strings[18942]="%s拧动阀门，专注地盯着笼子，手中握着一支羽毛笔。"
D.Strings[18943]="恐惧之王已经向我们致意了！祈祷吧！我们今天或许将战死沙场！祈祷吧！最终的审判已经来临！"
D.Strings[18944]="这些都非常不错。非要从中选一个的话，真有点难以做决定。"
D.Strings[18945]="很好，我找到合适的号角啦。现在我要开始雕刻了，这恐怕会很难。我根本没听过雌雪人的叫声！"
D.Strings[18946]="我已经把大部分基础图案雕刻好了，在完成雕刻之前需要测试一下。你愿意帮我测试吗，$n？"
D.Strings[18947]="恐惧之王万岁！"
D.Strings[18948]="牺牲生命也在所不辞！领主阁下！"
D.Strings[18949]="我们马上就会消灭这些入侵者，主上。"
D.Strings[18950]="今天，我们中的一员将得到升华。"
D.Strings[18951]="瓦格里就在我们身边，兄弟们，姐妹们！那些为巫妖王牺牲的人将得到荣光！"
D.Strings[18952]="贡纳·索瓦德森在此！拿命来！"
D.Strings[18953]="因格瓦尔已经派出龙骑兵去消灭那些蝼蚁了！很快他们就将面临觉醒的维库军团的毁灭性打击！"
D.Strings[18954]="努力战斗，兄弟们！用战斗的回响让同胞们觉醒吧！"
D.Strings[18955]="献祭仪式启动——倒计时开始……"
D.Strings[18956]="蔑冬的敌人，你们很快就会被撕成碎片！"
D.Strings[18957]="把这些蝼蚁赶出维库人的家园！"
D.Strings[18958]="啊！不要再喷了！"
D.Strings[18959]="那是什……啊！"
D.Strings[18960]="以布莱恩胡子的名字，停！"
D.Strings[18961]="关在笼里的矮人一面咳嗽，一面打喷嚏，全身都在颤抖。"
D.Strings[18962]="笼中的矮人发出低沉而绝望的呻吟。"
D.Strings[18963]="%s无力地摇晃着笼子的栏杆。"
D.Strings[18964]="%s沮丧地靠在笼子的栏杆上。"
D.Strings[18965]="你就是那个打扰我吃晚餐的家伙吗？是你吗？"
D.Strings[18966]="你也算是雌雪人吗？又丑又不丰满！你快让我抓狂了……"
D.Strings[18967]="真高兴见到你！$B$B要做的工作还有很多，我们的时间偏偏不多了。"
D.Strings[18968]="我要兑换酒桶保卫者的戳记……"
D.Strings[18969]="你想让我做什么？"
D.Strings[18970]="让我出来，懦夫！老子要让你知掉矮人的厉害！"
D.Strings[18971]="你想对村民们做什么！？"
D.Strings[18972]="戈斯从来不怕战死。被遗忘者只要把我重新拼起来就行了。"
D.Strings[18973]="戈斯有时候也很迷茫。戈斯是个好杀手，所以升到了中士。但戈斯很不习惯没有东西杀的日子！"
D.Strings[18974]="维库人身材高大，也比我们强壮。但！我们比他们长得帅！"
D.Strings[18975]="雷管5000型超级大炮是一种代表世界最尖端技术水平的单人发射装置，它能以龙的速度将人发射出去。发明该设施的地精家族是家喻户晓的航空领域先驱，这种超级大炮已经成为了家族的荣耀！$B$B如果你想象鸟儿一样在空中翱翔，就去沙塔斯城的圣光广场找玛克希玛·雷管吧。她会把你发射到城外的小池塘去！"
D.Strings[18976]="如何才能得到帮助呢？"
D.Strings[18977]="你知道矿洞里有只巨型雪人，对不对？"
D.Strings[18978]="那是雪·人！雪人啊！你到底知不知道啊，就是那种又大又臭还长着角的大怪兽！"
D.Strings[18979]="它让我们的矿工完全没法开采矿石。联盟急需那种矿石！"
D.Strings[18980]="你聋了吗？你这是在拖延联盟的军事行动，如果亚当斯上尉为此责罚你的话，我也脱不了干系！"
D.Strings[18981]="鲜美的脑！"
D.Strings[18982]="好……饿……呀……"
D.Strings[18983]="饿死我了……"
D.Strings[18984]="肉！吃了你！"
D.Strings[18985]="过来……再过来点……"
D.Strings[18986]="你听见什么没有，琼斯？我好像……听到了什么东西……在那边……"
D.Strings[18987]="啊！火焰般的光芒！！！"
D.Strings[18988]="啊呀呀呀……"
D.Strings[18989]="圣光……明亮的圣光……"
D.Strings[18990]="该死的光……好痛……"
D.Strings[18991]="走开……滚……"
D.Strings[18992]="没有。什么声音也没听见……"
D.Strings[18993]="$C，你做好动身的准备了？稍等。"
D.Strings[18994]="好，我们出发吧。"
D.Strings[18995]="她依然那么美丽！$n，拜托你转告我的话！"
D.Strings[18996]="我爱你，亲爱的伊雷娜。"
D.Strings[18997]="伊雷娜低声呜咽着。"
D.Strings[18998]="时间到了！你失败了……剩下的囚犯很快就会化为灰烬。"
D.Strings[18999]="或许我们选择靠近裂木森林和亚勒伯龙的道路是个错误。"
D.Strings[19000]="四名囚犯都得救啦！你很强大！"
D.Strings[19001]="来吧，英雄。圣光将指引我们前进并一路保护我们。"
D.Strings[19002]="来面对圣光的审判吧，恶魔！"
D.Strings[19003]="我要把你重新打回地狱里去！"
D.Strings[19004]="%s将神圣的古器放在伊鲁伦·图布雷勋爵身旁。"
D.Strings[19005]="伊鲁伦，我的任务完成了，接下来一切都交给你了。再见，愿圣光指引你前进的道路。"
D.Strings[19006]="%s闻到了肉味，猛然惊醒过来并发出了愤怒的嚎叫！"
D.Strings[19007]="我们的魔法……对这种疾病完全没有作用！"
D.Strings[19008]="末日临近了，兄弟们！我们会被彻底吞噬！"
D.Strings[19009]="安全起见，我只能为你安排峡湾区域的短途飞行。那么，你想去哪呢？"
D.Strings[19010]="将我送往复仇港吧。"
D.Strings[19011]="将我送往新阿加曼德吧。"
D.Strings[19012]="将我送往冬蹄营地吧。"
D.Strings[19013]="瞧你这花拳秀腿的！"
D.Strings[19014]="你训练的时候怎么跟睡着了一样。"
D.Strings[19015]="要是那帮小东西敢杀进来，我可不会像跟你对练的时候那样克制。"
D.Strings[19016]="老太太，要不要休息一下啊？"
D.Strings[19017]="你的拳头缺乏力道！"
D.Strings[19018]="不管你是练还是不练，都得满地找牙！"
D.Strings[19019]="来呀，你倒是给我一拳啊！"
D.Strings[19020]="一只%s突然窜了出来，想要护食。"
D.Strings[19021]="我一生戎马，经历过无数战争的洗礼。我曾在不同的旗帜下作战，不过那都是别人的战争。$B$B这次却截然不同了。这些被遗忘者士兵来这里的理由都只有一个。阿尔萨斯必须死。"
D.Strings[19022]="嗨，基尔，再考虑考虑我的提议？你瞧，我有大量兽皮和腌肉，想和你交换厚重的雪人毛皮或是你们正在加工的羽毛。"
D.Strings[19023]="我很想跟你做生意，杰森，但这些东西都是联盟远征军的财产。"
D.Strings[19024]="或许等战事消停之后，我可以考虑用余货给你做交易。不过你干嘛不和远征军做生意啊，他们要进军灰熊丘陵了，急需大量物资。"
D.Strings[19025]="嗯，我很期待能和远征军做生意。这样的话，我就要好好地保存这些肉啦。优秀的军需官是不会拒绝可靠的补给品入库的。"
D.Strings[19026]="麦酒，艾泽拉斯最好的酒！来美酒节尝尝吧！"
D.Strings[19027]="雷酒，全世界最好的酒。来美酒节尝尝吧！"
D.Strings[19028]="饿了吗？你还可以在这里睡觉哦。"
D.Strings[19029]="保持警惕，$r，我们已经被亡灵包围了。"
D.Strings[19030]="我必须回去，祝你狩猎愉快。"
D.Strings[19031]="愿天地间的精魂永远保佑你。"
D.Strings[19032]="你救了我的命。我欠你一份情。"
D.Strings[19033]="我们不应该穿越裂木森林的。是个人都该明白这点！"
D.Strings[19034]="这里到处都是幽魂。小心！"
D.Strings[19035]="他们将我们分别关押起来。我敢肯定还有其他的幸存者。"
D.Strings[19036]="我欠你一条命，陌生人。"
D.Strings[19037]="来吧！死就死！"
D.Strings[19038]="以他们的痛苦为乐趣吧！"
D.Strings[19039]="站起来，接受审判吧！"
D.Strings[19040]="以巫妖王的名义，死吧！"
D.Strings[19041]="为伊米隆国王的荣耀而战！我们不惜为巫妖王陛下而死！"
D.Strings[19042]="等一等……"
D.Strings[19043]="这只是……"
D.Strings[19044]="啤酒！只是啤酒而已！"
D.Strings[19045]="这酒真是稀松平常，毫无新意。"
D.Strings[19046]="你！不许告诉葛瑞克！听到没有？"
D.Strings[19047]="狂野的灵魂与我同在……"
D.Strings[19048]="灵魂，到我这里来！"
D.Strings[19049]="已经很安全了。你自由啦！"
D.Strings[19050]="喂！这里，来牢笼这里。过来让我看看你。"
D.Strings[19051]="喂……你就准备坐在那里沾沾自喜吗？你到底是不是来救人的啊？"
D.Strings[19052]="我说……别在那儿闲逛，过来帮我一把好吗？"
D.Strings[19053]="喂！这里……被困的矮人这里。来啦，我有话对你讲。"
D.Strings[19054]="别半途而废啊。告诉我，我能安全逃离此地了吧？"
D.Strings[19055]="埃基尔松，入侵者靠近了！"
D.Strings[19056]="擅自闯入竞技场的家伙将付出血的代价！沃鲁夫来了！"
D.Strings[19057]="放出所有俘虏！芬尔乌斯要把他们全碾成渣！"
D.Strings[19058]="芬尔乌斯算什么！让巫妖王手下真正的士兵来试试你的战力吧。"
D.Strings[19059]="很好……肉……更多的肉……"
D.Strings[19060]="我经不起派特洛夫的说辞，居然同意跟着一帮无能的矮人到了这里。"
D.Strings[19061]="他还许诺说会派增援力量过来，可人呢？"
D.Strings[19062]="总得有人去收集粪便啊！"
D.Strings[19063]="我说什么都不会踏进裂木森林一步，那地方闹鬼了！"
D.Strings[19064]="等我们回去，我一定要杀了派特洛夫！"
D.Strings[19065]="我不会再向北挪一步了！那些蜘蛛好大！"
D.Strings[19066]="派特洛夫许诺说马上就派援兵过来。怎么这么久都没动静？！"
D.Strings[19067]="我本该留在那里鼓捣飞行器的，却被派到这里来收集蝙蝠粪便！"
D.Strings[19068]="这里应该很安全！总比被一群饥饿的座狼给包围了要好，大工匠恐怕也会认可这一点！"
D.Strings[19069]="菲纳特，嘘！"
D.Strings[19070]="一切都会好起来的，菲纳特。别担心。"
D.Strings[19071]="菲纳特，别这样。我很担心亚伦的安危，你就别给我添乱了。"
D.Strings[19072]="对，我们都希望你能在要塞里安静地呆着。"
D.Strings[19073]="菲纳特！够了！"
D.Strings[19074]="不如你试着独立完成那些工作，这样说不定你还能快点返回要塞呢。"
D.Strings[19075]="菲纳特，你给我安静一会儿。吵得我头痛。"
D.Strings[19076]="菲纳特，拜托！派特洛夫很快就会派帮手来了！"
D.Strings[19077]="他们的防线被攻破了！进攻！"
D.Strings[19078]="啊，自由了！"
D.Strings[19079]="你救了我的命，我自然会报答你。不过那帮野蛮人把我的背包藏哪儿了？"
D.Strings[19080]="别不好意思。随意挑吧。要不是你帮忙，我早就完了。"
D.Strings[19081]="够了，伊鲁伦。"
D.Strings[19082]="弗丁大人，您不能露面！"
D.Strings[19083]="%s脱掉伪装。"
D.Strings[19084]="他的死，事实上……在净化灰烬使者的过程中，所有骑士的死本来都是可以避免的。"
D.Strings[19085]="他们的逝去让我倍感沉痛。"
D.Strings[19086]="自由之路总是铺垫着悲剧，大人。但我们不能让您做出牺牲。北伐军无法承受如此沉重的打击。"
D.Strings[19087]="%s流露出痛苦的神情。"
D.Strings[19088]="这把剑本来应该由我带来诺森德的。从此以后，它所背负的一切就让我来承担吧。"
D.Strings[19089]="伊鲁伦，你说得对。自由的代价是沉重的，毫无疑问还会有上千名骑士为此牺牲。"
D.Strings[19090]="%s拿起灰烬使者。"
D.Strings[19091]="阿尔萨斯，你听见了吗？银色北伐军来了！你的王国将被正义的审判彻底毁灭！我以圣光之名起誓！"
D.Strings[19092]="[维库人土语] Bjorns mottar haelgond sygar！"
D.Strings[19093]="你竟敢辱骂我的妈妈！"
D.Strings[19094]="嗨！你是不是忘记坦扎尔还在这里了？"
D.Strings[19095]="朋友，你除掉巨魔熊了吗？坦扎尔现在安全了？"
D.Strings[19096]="嗨，有人吗？"
D.Strings[19097]="朋友，我就是闭着眼睛也能打开这把锁。你只需告诉我什么时候能安全逃走就行啦。"
D.Strings[19098]="救命！谁来救救可怜的坦扎尔！"
D.Strings[19099]="纳洛拉克已经死了，你自由了。"
D.Strings[19100]="古代密码表落到了地上。"
D.Strings[19101]="相比起来，药剂师更强调实践吧。毕竟我们在负责后勤工作的。$B$B这并不代表我们的理论基础知识不够扎实。我们只是……做实事而已。"
D.Strings[19102]="芬尔乌斯无所畏惧！让那些斗士上前来吧！"
D.Strings[19103]="巫妖王又能收割更多的灵魂啦！来呀，小子们，来呀！"
D.Strings[19104]="你见过无头骑士吗？要是他到这里来的话，我会和他战斗，然后偷走他的南瓜！"
D.Strings[19105]="我喜欢在大水桶里划水，但是他们说那不是给孩子们玩的。"
D.Strings[19106]="他们说这些水桶是灭火用的。你是个消防队员吗？"
D.Strings[19107]="无头骑士与其他令人毛骨悚然的鬼魂和人类一起住在血色修道院。"
D.Strings[19108]="他们正在旅店里分发糖果！守护者格雷沃基说要是他们不给我们糖果……我们就去和他们捣乱！"
D.Strings[19109]="你见过无头骑士吗？守护者格雷沃基说，如果他出现了的话，千万不要看他，否则他会把我变成南瓜！"
D.Strings[19110]="你可以在大水桶里打满一桶水。泼水真有趣！"
D.Strings[19111]="呜哈！坦扎尔自由了！"
D.Strings[19112]="我看到暴风城来的士兵们在灭火。他们是英雄！"
D.Strings[19113]="无头骑士居住在血色修道院。有时候他会出来吓唬小孩子，但我不怕！"
D.Strings[19114]="我从旅店那里得到了一些糖果！不过我还想要更多！"
D.Strings[19115]="太幸运了！这不是坦扎尔的东西吗……"
D.Strings[19116]="好啦。这是给你的礼物，庆祝坦扎尔的顺利逃脱！"
D.Strings[19117]="再往左一点——不，不，往右……"
D.Strings[19118]="唔……左转、右转、扭一扭、按下去……"
D.Strings[19119]="再深一点——快好啦……"
D.Strings[19120]="进入那座洞穴吧，它就是痛苦之源……"
D.Strings[19121]="让我看看，按下去、扭一扭、我转、我再转……"
D.Strings[19122]="啧啧，新鲜的灵魂！"
D.Strings[19123]="下面那些卑贱的奴隶有肉吃啦……"
D.Strings[19124]="太弱了……只配喂给下面那些卑贱的亡灵。扔下去！"
D.Strings[19125]="%s显得非常虚弱！"
D.Strings[19126]="谢谢你。我还以为我再也见不到我的姐妹啦！"
D.Strings[19127]="我在哪里？发生了什么事？是你……救了我？"
D.Strings[19128]="我就知道鲁莉尔蕾会派人来救我的！谢谢你，朋友，也帮我谢谢鲁莉尔蕾！"
D.Strings[19129]="$c，谢谢你。$b$b要是有什么事我能帮上忙的，尽管开口。"
D.Strings[19130]="安全了吗？是谁杀死了巨魔？"
D.Strings[19131]="克拉斯捡回了一条命！"
D.Strings[19132]="到克拉斯这里来吧，接受我的感谢。"
D.Strings[19133]="克拉斯肯定是遇到了伟大的巨魔克星！"
D.Strings[19134]="我的英雄！过来和克拉斯谈谈。"
D.Strings[19135]="探险者协会允许我跟他们一起来真是太好了。但是裂木森林和周边区域实在是太危险，我没带帮手就闯了进来，真是蠢到家了。"
D.Strings[19136]="我想去帮他们打败无头骑士，但是老格雷沃基不让我去！"
D.Strings[19137]="无头骑士下次再过来的话，我们同样会再次打败他！"
D.Strings[19138]="我的朋友很害怕，但我不怕！"
D.Strings[19139]="你是个英雄！"
D.Strings[19140]="无头骑士很可怕，但我一点都不害怕！一点也不害怕！"
D.Strings[19141]="无头骑士落荒而逃了！"
D.Strings[19142]="要是他回来了，你会再去和他战斗吗？"
D.Strings[19143]="我希望我能有个像你一样的$g爸爸:妈妈;！"
D.Strings[19144]="蔑冬部族必胜！"
D.Strings[19145]="将入侵者驱逐出去！为安格博达女王而战！"
D.Strings[19146]="勇敢地战斗吧，瓦格里会奖赏你的！"
D.Strings[19147]="别打哑谜了！"
D.Strings[19148]="把这些东西拼起来可真够难的！"
D.Strings[19149]="足骨……连接到髋骨！髋骨再……再连接到这里好了！嗯嗯……"
D.Strings[19150]="得把这些腐烂的部分切掉，我做东西只用最好的材料！"
D.Strings[19151]="我弄丢了座狼伪装服。"
D.Strings[19152]="好吧，别再弄丢了。"
D.Strings[19153]="怎么会弄丢呢？好吧好吧，别再弄丢了。"
D.Strings[19154]="调配失败的混合物溅到了地板上，呈现出了奇特的生命迹象！"
D.Strings[19155]="我会很想念冬蹄营地的，但是我能理解灰烬图腾酋长做出的决定。我们没有能力永远维持家园这个温暖的港湾。"
D.Strings[19156]="<地上躺着一具新阿加曼德药剂师残缺不全的尸体。>"
D.Strings[19157]="拿起药剂师的包裹。"
D.Strings[19158]="我本应该呆在乌特加德城堡，与因格瓦尔并肩作战的！现在却被派来对付你这样的废物。"
D.Strings[19159]="为什么不直接杀掉你呢，真是奇怪。"
D.Strings[19160]="因格瓦尔早就计划好怎么对付你了，小家伙。"
D.Strings[19161]="你马上就要进入审判竞技场了，蝼蚁。"
D.Strings[19162]="%s摇晃着笼子，发出嘎嘎声。"
D.Strings[19163]="%s完全丧失了自控能力，开始无差别地攻击朋友和敌人！"
D.Strings[19164]="以黑暗领主之名，这名人类将成为您的祭品！"
D.Strings[19165]="瓦格里，来吧！我愿意接受审判！"
D.Strings[19166]="死就死吧！"
D.Strings[19167]="嘿，你没看见我正要喝酒吗？"
D.Strings[19168]="很好，这个就行。我觉着……嗝儿。"
D.Strings[19169]="掠龙维库囚犯感到不适。"
D.Strings[19170]="陌生人，这里散发着死亡的气息。$b$b快走吧，否则你就会像克拉斯一样被关进牢笼。"
D.Strings[19171]="小心我的钢锯，它会让你看到很多内在的东西，不是吗？"
D.Strings[19172]="我们杀死了俘虏你的家伙。你现在自由了。"
D.Strings[19173]="哎哟，真恶心！"
D.Strings[19174]="怎么会这样！"
D.Strings[19175]="我很不舒服。"
D.Strings[19176]="嘿，放松点！"
D.Strings[19177]="你哪里不舒服？"
D.Strings[19178]="他们竟然能做出那样的事。"
D.Strings[19179]="真……特别。"
D.Strings[19180]="那是被遗忘者最新研制的药剂？！"
D.Strings[19181]="拿稳了，笨蛋！你将那些稀有的材料都弄洒了！"
D.Strings[19182]="药剂！它动了！"
D.Strings[19183]="嗯……？"
D.Strings[19184]="呀。"
D.Strings[19185]="他没事吧？"
D.Strings[19186]="这可不太好。"
D.Strings[19187]="哇。"
D.Strings[19188]="入侵者！警报！"
D.Strings[19189]="站开点……"
D.Strings[19190]="拜托你，朋友，收下这个吧，带着我克拉斯的感激一并收下吧。"
D.Strings[19191]="格雷尔，我需要一匹狮鹫和一些炸弹来轰炸新阿加曼德！"
D.Strings[19192]="拿去吧。好好利用这些武器！"
D.Strings[19193]="现在，来看看……，他们把克拉斯的东西放哪去啦？"
D.Strings[19194]="我们也被诅咒了吗？"
D.Strings[19195]="%s指着那个婴儿。"
D.Strings[19196]="神灵抛弃了我们！我们必须在伊米隆国王发现之前处理掉它！"
D.Strings[19197]="不！你不能这样！求你了！这是我们的孩子啊！"
D.Strings[19198]="那要怎么办？一旦他们发现了这个畸形的胎儿，我们就会被处死。"
D.Strings[19199]="我……我会把它藏起来，直到我为它找到一个家，一个远离这里的家……"
D.Strings[19200]="尊贵的伊米隆国王，万岁！"
D.Strings[19201]="听他说！肃静！"
D.Strings[19202]="绝不能对畸形儿心存怜悯！"
D.Strings[19203]="向斯克恩开火！"
D.Strings[19204]="一定要保持维库人纯正的血统！"
D.Strings[19205]="我的国王，手下留情！那是我们的骨肉啊！"
D.Strings[19206]="它们是祸害！维库人的力量会因它们的存在而削弱！杀掉它们！"
D.Strings[19207]="%s要求大家安静下来。"
D.Strings[19208]="嘘！"
D.Strings[19209]="国王有话要说！"
D.Strings[19210]="维库人，国王恳请你们安静下来！"
D.Strings[19211]="人群在惊惶中骚动起来。"
D.Strings[19212]="在最黑暗的时刻，他们依然不忘嘲笑我们！"
D.Strings[19213]="在我们最需要泰坦指引的时候，他们又在哪儿呢？氏族诞生了畸形的胎儿，它们面貌丑陋，甚至无法站立！又丑又弱……一无是处……"
D.Strings[19214]="伊米隆身心疲惫。自从我坐上王位，就一直在思考为什么维库人的生活如此艰难。答案只有一个……只有一个……"
D.Strings[19215]="除了泰坦，还有谁能对我们下这样的诅咒？谁能拥有那样的力量？"
D.Strings[19216]="没有……是泰坦诅咒了我们！"
D.Strings[19217]="人群喧闹起来。"
D.Strings[19218]="今天，所有的维库人都将抛弃过去的信仰！废除我们曾经信奉的神灵！维库人将效忠伊米隆国王！伊米隆会保护我们的！"
D.Strings[19219]="人群欢呼起来。"
D.Strings[19220]="现在，我颁布第一道法令！所有维库人畸形婴儿一出生就要立即被处死！我们必须保证血统的纯正！违抗伊米隆国王的法令的维库人将被带往亚勒伯龙处决！"
D.Strings[19221]="%s咧嘴一笑。"
D.Strings[19222]="萨满的精魂将你带来了这里……我能感应到空气中涌动着那种力量。*巫妖王大笑起来* 我也曾是个萨满祭司。"
D.Strings[19223]="不，我的仆从。这一个还没有准备好。"
D.Strings[19224]="你感觉到了吗，凡人？死亡之力从我的每一寸皮肤上渗透出来，覆盖了所有我碰触过的事物。只要我的手指轻轻一触，你的灵魂就将在诅咒中永远地凋零消逝。"
D.Strings[19225]="但……现在还不是让你为巫妖王效力的时候。是的，更伟大的命运还在等待着你。力量……在你为我效劳之前，你必须获得更多的力量。"
D.Strings[19226]="看仔细了，瓦格里。看我如何施压。你瞧，它还没有成熟呢。接着它就会爆裂，毫无生气地陨落。"
D.Strings[19227]="需要为您准备好一切吗？"
D.Strings[19228]="哇噢——你杀死了巨魔坏蛋不仅挽救了我的性命使我幼小而纯洁的灵魂免遭奴役还粉碎了他们企图利用我的力量来帮助他们统治艾泽拉斯世界的邪恶计划你冒着生命危险将我从死亡的边缘拉了回来因此不管你是谁也不管你从哪儿来我都要好好地报答你的救命之恩你相信我啦我会竭尽所能地报答你的……$b$b<阿什莉深深地吸了口气。>$b$b我希望你会喜欢糖果……"
D.Strings[19229]="安全了，小侏儒。你现在可以出来了。"
D.Strings[19230]="当然。我是在附近一具矮人的尸体上找到的。"
D.Strings[19231]="哇！你是怎么把那个大个子的巨魔坏蛋撂翻在地的呀可惜我连这个笼子的把手都够不着不然我肯定会跳到他身上狠狠地揍他一顿我要为那些惨死在他手中的俘虏报仇这个坏蛋可把我吓得够呛你帮了我这么大的忙我其实挺不好意思的不过能麻烦你过来打开牢笼吗？"
D.Strings[19232]="当然。"
D.Strings[19233]="哎咳……我觉得吧，在和那个恐怖的怪物艰难地打斗了这么久之后你花上点时间休息兼庆祝一番我绝对没有任何意见啊不过呢你最好别忘记我还在这里呢虽然我看上去个子玲珑不过我还是有能力报答你的恩情的……"
D.Strings[19234]="我说……虽然我讨厌那种刚从死亡边缘捡回一条命就开始喋喋不休抱怨起来的家伙不过呢我也要提醒你我还被关在这个肮脏的笼子里呢如果你能放我出去的话我就可以和你一起分享打败那头恐怖的巨魔豹的喜悦啦……"
D.Strings[19235]="我知道你们都在赶时间可能还需要去打败更大更危险的怪物不过如果你们肯费费神把我从这个笼子里放出去的话我一定会异常兴奋的所以要是你们愿意花上这么一点时间的话我就会很耐心……很耐心……很耐心地在这里等着哟……"
D.Strings[19236]="诺森德的旅程就要拉开序幕。你准备好了就告诉我，我会将你传送到起始地区。"
D.Strings[19237]="去吧！遵照主人的命令行事！"
D.Strings[19238]="朋友，你想去祖阿曼？我带你去吧。"
D.Strings[19239]="带我去祖阿曼！"
D.Strings[19240]="你马上就要死了！"
D.Strings[19241]="让我带给你们痛苦！"
D.Strings[19242]="你们召唤野兽？你马上就要大大的后悔了！"
D.Strings[19243]="纳洛拉克，变形，出发！"
D.Strings[19244]="你们曾有过机会的，但现在太迟了！"
D.Strings[19245]="现在你们有什么好说的啊？"
D.Strings[19246]="阿曼尼帝国万岁！"
D.Strings[19247]="我会在另一个世界里等你们的！"
D.Strings[19248]="赞达拉给了我们力量。没人能和阿曼尼作对啦！"
D.Strings[19249]="看好了，我有许多新招，比如变个熊……"
D.Strings[19250]="没人能逃过猎鹰的眼睛！"
D.Strings[19251]="现在来见识一下我的尖牙和利爪吧！"
D.Strings[19252]="遮天的龙鹰降临了！"
D.Strings[19253]="烈火会烧光你们！"
D.Strings[19254]="这就是为什么他们叫我“战神”！"
D.Strings[19255]="更多的人会像你们一样倒下。"
D.Strings[19256]="就算我倒下了……阿曼尼帝国……绝不会消亡……"
D.Strings[19257]="唔，或许是这个吧——顺便提一句，我有没有告诉过你“双响喇叭”法迪利克的事？有一次这家伙趁我搓火球时在我背后吓我。我们之所以叫他“双响喇叭”是因为，啊……当我没说吧。那次事件搞得妈妈非常生气，瞧，我的眉毛到现在也没长出来……"
D.Strings[19258]="嘿，酒保，再来一杯！"
D.Strings[19259]="你洗过那个杯子吗……嗝儿？"
D.Strings[19260]="贾森，我能搅出更多的泡沫来。"
D.Strings[19261]="嗯……你应该把这玩意儿送给派特洛夫制作炸弹！"
D.Strings[19262]="塞蕾丝，你这身衣服真漂亮。你太美啦。我爱你们……嗝儿！"
D.Strings[19263]="再喝下去，你就要醉了。"
D.Strings[19264]="谁在讲话？我几乎看不见你的脑袋。你到了法定的饮酒年纪了吗？"
D.Strings[19265]="贝比，我敢打赌矮人都喝不过你。"
D.Strings[19266]="我爱你！"
D.Strings[19267]="我也爱你！"
D.Strings[19268]="酒保一边工作一边哼着小曲儿。"
D.Strings[19269]="莉丝安！莉丝安·怀特！她在哪儿？"
D.Strings[19270]="别指望有谁会帮你！"
D.Strings[19271]="莉丝安！我敢打赌她又跑到井边做白日梦了！"
D.Strings[19272]="<嘟囔>这身衣服真的很漂亮呢！<嘟囔>"
D.Strings[19273]="我需要更多的铲齿鹿！"
D.Strings[19274]="这些码头工人又闹罢工了？！我需要那些补给物资！"
D.Strings[19275]="%s想要今天还有不少工作要做，不由地叹了口气。"
D.Strings[19276]="谢谢你，甜心。我们也爱你。"
D.Strings[19277]="啊，那里也没有——好吧，它一定在这附近啦。我有没有跟你说过离开那个臭烘烘的牢笼是件多么美妙的事情？笼子空间狭小不过我凭借灵巧的身段能在奔跑哟只是有时候我跑得太快了就跟飞檐走壁似的所以呢我决定在里面转圈子玩……"
D.Strings[19278]="我的包裹！终于找到啦这是我送你的礼物我真心希望你会喜欢它因为我要你们记住这刻美好时光一辈子都不要忘记啊我还希望你每次看到它的时候都能笑一笑要知道我是永远不会忘记你们的我迫不及待地想要回家告诉妈妈这次的冒险之旅啦……你觉得我这副耳环好看吗？"
D.Strings[19279]="你救了我的命，朋友！我还以为他们会把我淹死呢。"
D.Strings[19280]="朋友，需要帮忙的话尽管开口。"
D.Strings[19281]="联盟的增援快要耗尽了！"
D.Strings[19282]="部落的增援快要耗尽了！"
D.Strings[19283]="要是没有这些高大的巨魔，这里倒是一处舒适的好地方。"
D.Strings[19284]="我想我再也回不到从前了吧。呵呵，来一品脱酒应该就成。"
D.Strings[19285]="这才是真正的冒险。那些足不出户的孩子肯定难以想象这样的经历……"
D.Strings[19286]="我应该趁自己被囚禁在祖阿曼时四处逛逛，搞点财宝什么的——毕竟，对我这样的矮人来说，再多吃点苦头也没什么关系吧？"
D.Strings[19287]="你真像一场及时雨。瞧瞧那帮野蛮人是如何对待囚犯的……"
D.Strings[19288]="我一定会把这个故事讲给我的孙子听……只要我能活到抱孙子的那一天。"
D.Strings[19289]="像你这样的陌生人也能慷慨伸出援手，真是感动得令我落泪……嗨，只有喝上几杯才能表达我的感谢。"
D.Strings[19290]="也许我应该写本书……“哈考尔的祖阿曼指南”。不错，我喜欢这个书名。"
D.Strings[19291]="相信我，真的没什么可担心的！"
D.Strings[19292]="联盟这帮蠢货！他们没有意识到所有努力都是白费的吗！"
D.Strings[19293]="好啊，让大家像无头苍蝇一样东奔西跑吧。"
D.Strings[19294]="连那些蛤蟆都……？难以置信！"
D.Strings[19295]="那群笨蛋！我就知道他们会这么做，但是他们没有料到我事先做了防火处理。哈哈哈哈哈哈！"
D.Strings[19296]="别管那么多……我们还有很多工作要做！"
D.Strings[19297]="蠢货！高温很可能是完善药剂样本的重要条件。"
D.Strings[19298]="噢，只是一点点小火嘛。大家都恐慌了！"
D.Strings[19299]="药剂师的研究被中断，他叹了口气。"
D.Strings[19300]="%s环顾四周，皱了皱眉头，觉得同事们的反应明显过激了。"
D.Strings[19301]="%s摇了摇头，继续开始研究工作。"
D.Strings[19302]="%s若有所思地注视着附近着火的药剂罐头。"
D.Strings[19303]="你们……永远无法消灭……我的灵魂！"
D.Strings[19304]="别吵啦！"
D.Strings[19305]="你们什么也得不到！"
D.Strings[19306]="我是猎鹰，而你们，就是猎物！"
D.Strings[19307]="你们所做的一切不过是浪费我的时间！"
D.Strings[19308]="这样应该就没问题了。这扇大门的机关已经被解除了。"
D.Strings[19309]="感谢关心，不过我们有意要探索祖阿曼。"
D.Strings[19310]="让我猜猜，你是巴德派来的另一队乌合之众吧？$b$b$r，趁你还没受伤——甚至送命之前离开这里吧。"
D.Strings[19311]="我很清楚这里有多危险。我再说一遍，别挡路。"
D.Strings[19312]="我详细地研究了这个地方，我不会允许任何像你们这样的窃贼进入这地方，并偷走属于博物馆的财宝。"
D.Strings[19313]="事实上，你最好留在这里。你只会坏我的事……"
D.Strings[19314]="无论如何都别来烦我，就算你惹上麻烦也不要叫我……"
D.Strings[19315]="嗨！我是最优秀的赛羊手，这并不代表我就乐意帮助那些酿酒商。你高兴的话，你去帮他们好了。$B$B等等，我还没说完呢！$B$B你要是能帮到酿酒商，就有机会骑上世界上最好的赛羊！"
D.Strings[19316]="你还需要找人从卡拉诺斯运回酒桶吗？"
D.Strings[19317]="接下来，我会帮你雕刻符文，它拥有支配巨人的力量。"
D.Strings[19318]="我省掉了代表“北面”和“西面”的符文，因为我还不确定它们会对巨人产生怎样的影响。而且，我还添加了限制控制时间的符文。"
D.Strings[19319]="瞧，命令符文……希望能起作用。它并不没有铁矮人那股邪恶的气息，却同样具备操纵巨人的能力。"
D.Strings[19320]="%s凝视着东北方！"
D.Strings[19321]="%s盯着集合石，叹了口气。"
D.Strings[19322]="啊哈哈哈，瞧见了吗？格里伏塔回来了！我带着一堆古董回到了熟悉的货摊前，而且我已经准备好和你做买卖了！$b$b想要变得更健壮更强大更矫健吗？我出售的护身符都具备这些功能哟。来吧，掏钱买个绝世珍宝吧！破盘价啦！"
D.Strings[19323]="又有入侵者，敲响警钟！"
D.Strings[19324]="今天，所有的灵魂将饕餮不已！开始仪式吧，献祭所有的囚徒……为我们的新客人腾出空间！"
D.Strings[19325]="黑暗的岁月可以促成奇怪的友谊。如果能去旧洛丹伦，观看被遗忘者们烧毁稻草人的话也挺不错的。"
D.Strings[19326]="这个节日原本是部落发明的，不是联盟。真不明白我们为什么也要庆祝。"
D.Strings[19327]="我们这是在庆祝谁摆脱了谁的束缚？呸，管他呢？！我要更多的糖果！"
D.Strings[19328]="为什么每个人都不停地说侏儒只想要更多的糖果？！"
D.Strings[19329]="我说，免费的糖果真是个赔钱的买卖。呃……或许它们只是招揽顾客的减价货呢……糖果诱使你进入旅店，接下来你就要花钱吃肉啦。太棒了！"
D.Strings[19330]="万圣节结束后我们就要打碎所有的南瓜。那将会是我最开心的日子！"
D.Strings[19331]="退一步说，庆祝另一位死敌的诞辰真是件诡异的事。不过，我们还是会参加盟友们的节日。"
D.Strings[19332]="被遗忘者有权庆祝自己重获自由。还有什么比这更重要的吗？"
D.Strings[19333]="被遗忘者每晚都会焚毁一个巨大的稻草人，真不明白这样做的意义何在，不过我们的仪式在他们眼中应该也很奇怪。"
D.Strings[19334]="万圣节期间，被遗忘者每晚都会焚毁一个稻草人。真不明白他们为什么不烧真人，不过这大概是他们的节日传统吧。"
D.Strings[19335]="我们在万圣节上狂欢，纪念女妖之王将我们从巫妖王和天灾军团的魔掌中解救出来。每晚在幽暗城外都会举办稻草人晚会，记得参加哦。"
D.Strings[19336]="你居然把证据给弄丢了？！"
D.Strings[19337]="我以为很安全嘛！要是你们这帮卫兵能惩治惩治沙塔斯城中的小偷，就不会发生这样的事件！"
D.Strings[19338]="你想把这事推到卫兵头上来掩饰自己的疏忽吗？这么个简单的任务你都办不好。那巨魔显然是个骗子！"
D.Strings[19339]="看，随机挑选开始！五秒内就有结果！"
D.Strings[19340]="巨魔木乃伊……看上去处理得很草率。"
D.Strings[19341]="嗯。我还是不明白这只鸟的含义。"
D.Strings[19342]="数年来，这些篝火堆都不曾熄灭。它们对巨魔来说有着非同寻常的意义。"
D.Strings[19343]="奇怪。很明显，他们利用献祭仪式获取强大的力量。但他们的目的是什么呢？"
D.Strings[19344]="瞧这雕刻手法。丰富的色彩、粗壮的线条、深奥的符号……令人叹为观止。"
D.Strings[19345]="这尊雕像和其它巨魔雕像截然不同。"
D.Strings[19346]="是啦，我确信这代表着多个实体的融合。太神奇啦。"
D.Strings[19347]="哟。纠结的毛发、脱落的羽毛、碎裂的骨头、被烧焦的不明物——或许是衣物？"
D.Strings[19348]="装满垃圾的袋子被整齐地堆在一旁，和血腥的现场形成强烈的……视觉冲击。"
D.Strings[19349]="研究垃圾也能了解到这个文明的不少信息。"
D.Strings[19350]="这是什么？一颗牙齿么？好象是某只大型猫科动物嘴里掉出来的。真奇怪……"
D.Strings[19351]="灰烬与枯骨，就这么散落着。我必须取一份样品。"
D.Strings[19352]="奇怪啊……，这上面的镶嵌着的图案跟任何已知的巨魔传统风格都完全没有任何接近之处。"
D.Strings[19353]="这些是祖阿曼特有的桶吧。桶身很短、很圆……"
D.Strings[19354]="万圣节快乐！"
D.Strings[19355]="你知道……我们为什么要庆祝这个节日吗？"
D.Strings[19356]="我们的被遗忘者同盟在每年的这个时候都要举办重要的庆典。"
D.Strings[19357]="艾泽拉斯世界有很多奇怪的传统。我就喜欢万圣节这个传统节日。"
D.Strings[19358]="怎么就没有啤酒味的糖果呢？！"
D.Strings[19359]="再来捣乱啊，我说，再来啊。这里可有“真正”的糖哦！"
D.Strings[19360]="我们一定得参加下次的稻草人焚烧祭典。"
D.Strings[19361]="还有其它的旅店可以捣乱的吗？"
D.Strings[19362]="让这个变态的夜晚去见鬼吧。不过，糖倒是真不错。"
D.Strings[19363]="被遗忘者一定要庆祝他们重获自由！"
D.Strings[19364]="就算感觉陌生与奇怪，我们也有义务尊重盟友们的神圣节日。"
D.Strings[19365]="真该发明个侏儒夹心软糖啥的……"
D.Strings[19366]="现在是被遗忘者的时代！"
D.Strings[19367]="肯·定·有什么办法能趁这节日的时候发上一笔！"
D.Strings[19368]="旅店老板们居然免费发糖，真是疯了。"
D.Strings[19369]="欢迎来到暴雪嘉年华！这座临时租借来的码头能带你前往诺森德。船只很快就会靠岸了。祝你旅途愉快！"
D.Strings[19370]="你的责任就是保障城市的安全！如果大街上到处都是行为卑鄙的家伙，我怎么执行那个“简单的任务”？瞧，在沙塔斯城随便吐口唾沫就能砸到一个肮脏的小偷。"
D.Strings[19371]="……当然，我不会真的吐口水啦。"
D.Strings[19372]="哎咳，凯雷先生，我正在努力穿越这个房间……请帮帮我吧！"
D.Strings[19373]="还有什么能比永久侍奉熊之圣魂更好呢？来呀，将你们的灵魂交给我！"
D.Strings[19374]="闻到你们的气味了，陌生人。别再逃避命运了。过来吧，我很快会把你们献祭给灵魂。"
D.Strings[19375]="我的猎鹰将把你们的灵魂带到我这里。你们的牺牲也并非毫无意义……"
D.Strings[19376]="陌生人，你们很快就将步入死亡。你们根本不该来到这里……"
D.Strings[19377]="来呀，蠢蛋们，来把我的笼子塞满吧……"
D.Strings[19378]="我已经等待很久了，陌生人。你的死亡将使我更强大！"
D.Strings[19379]="兄弟们，复活吧！"
D.Strings[19380]="铁领主交给我们一项任务！"
D.Strings[19381]="过来，朋友们。你们的尸体将是孩子们最好的食物，而你们的灵魂则将壮大我的力量！"
D.Strings[19382]="过来，陌生人。龙鹰之圣魂已经饥渴太久了。"
D.Strings[19383]="跟着我进入山岭，执行主人的计划！"
D.Strings[19384]="自由选择吧，入侵者们！我手下任何一位祭司都愿意陪陪你们。"
D.Strings[19385]="别害怕。你们之前有千百人尝试过，你们并不孤独。"
D.Strings[19386]="你们就要失败了，陌生人。很多人也曾尝试过，但他们只是使我们更强大！"
D.Strings[19387]="我知道你有多讨厌那些卑鄙的家伙，我这不正在设法将他们永久驱逐出沙塔斯城吗！下次，我一定要求配备一名有能力的调查员！"
D.Strings[19388]="你什么时候才会停止瞎扯淡？"
D.Strings[19389]="%s板着脸，把头扭向一边。"
D.Strings[19390]="我凭什么要忍受这个自吹自擂的家伙……"
D.Strings[19391]="%s对调查员艾斯瑞克皱了皱眉头。"
D.Strings[19392]="没什么。我只是在自言自语罢了。"
D.Strings[19393]="你们的努力全都白费了，献祭完成了，你们很快也将被囚禁。"
D.Strings[19394]="很快，笼子就会变空，献祭就将完成，而你们，则会代替他们的位置。"
D.Strings[19395]="时间不多了，陌生人。很快你们的灵魂也将落得跟前人一样的下场。"
D.Strings[19396]="动作快点，祭司们！仪式绝不能被中断！"
D.Strings[19397]="这些珍贵的器物都是我的客户指名预订的呢。$b$b$c，只要你能帮我找回来，我是绝对不会亏待你的，我懂你的心思啦。$B$B我们来谈谈今天的订单如何？"
D.Strings[19398]="玛哈杜恩听见虚空风中传来的低语声。$B$B有人来到玛哈杜恩面前，谈论起今天的猎物。"
D.Strings[19399]="你们的努力值得赞赏……但现在，你们就将加入死者的行列了。"
D.Strings[19400]="注意！所有的祭品都将增强我们与灵魂世界的联系。很快，我们就将无坚不摧！"
D.Strings[19401]="你们干得还不坏……你们的努力竟然略略延缓了那不可避免的命运。来我这里吧，你们已经证明自己将是很好的祭品。"
D.Strings[19402]="%s喷溅着水花。"
D.Strings[19403]="看，起作用了。"
D.Strings[19404]="孩子，看来你相当自信哦？如果你能在竞技场中占一席之地，我倒是可以送你点什么。是相当不错的东西呢，比克里希的那些破玩意儿好多啦。$b$b祝你好运。"
D.Strings[19405]="我们是来练习灭火技术的。荣耀归于部落！"
D.Strings[19406]="不错不错！看来我们已经准备好面对真正的火灾了。"
D.Strings[19407]="快点，$c！剃刀岭失火了！快上！快去灭火！"
D.Strings[19408]="$n，闪金镇着火了！快去帮忙灭火！"
D.Strings[19409]="好吧，或许竞技场并不适合你？维克斯顿还有些第一季的存货，我们正想处理掉呢。不过天下没有免费的大餐，你懂我的意思吧？"
D.Strings[19410]="善良的陌生人，我向你的无私致敬。"
D.Strings[19411]="这群野蛮人将我洗劫一空，不过我从他们身上偷来的咒符倒是可以送给你。"
D.Strings[19412]="我的钱呢？我的酒呢？我的脚呢？"
D.Strings[19413]="哇哇！我还不想死啊！我要永生啊！这完全就不公平啊！"
D.Strings[19414]="噗嗤！我是一个小侏儒！而且……，我没有主……呃，算了……"
D.Strings[19415]="绝望吧！看着我的章鱼脸，绝望吧！可笑的艾泽拉斯人！"
D.Strings[19416]="大脑……大脑脑脑！"
D.Strings[19417]="老子有了疯狂巫毒啦，哥们！"
D.Strings[19418]="我是一朵秀丽而脆弱的小花花！"
D.Strings[19419]="嗨！你吃掉了最后一只鸡？我原本打算将它留到特殊的时刻再吃的！"
D.Strings[19420]="为了联盟！等等……为了部落！等等，我是哪边的来着……"
D.Strings[19421]="为了部落！不……联盟！嗯……我戴着哪个面具？"
D.Strings[19422]="你现在当然这么说啦，等待会吃饭的时候你肯定就不会这么想了！"
D.Strings[19423]="就算只能啃石头充饥，我也不会吃你剩下的东西！"
D.Strings[19424]="跟着我，小姑娘。"
D.Strings[19425]="$n，希望你能用得着它。"
D.Strings[19426]="哎唷！扔东西的时候小心点！"
D.Strings[19427]="太神奇了！这些余烬没有丝毫的热度。"
D.Strings[19428]="我从来没有闻过这样诡异的烟味。他们在烧什么呢？"
D.Strings[19429]="陌生人，谢谢你。"
D.Strings[19430]="除了这只古老的箱子，我也没别的东西可给你的了。收下吧。"
D.Strings[19431]="希望你能……用得着。"
D.Strings[19432]="再见……"
D.Strings[19433]="美酒节上总是需要大量的酒桶！$B$B我会让你从我们这里借一头山羊和一根缰绳。$B$B你每给我带来一个酒桶，我就给你一些奖币，作为你给我带来酒桶的感谢，我甚至会让你更久地使用我的山羊！\n\n但是，只要你开始了，在明天以前你就不能再做了。\n\n你确定已经准备好了吗？"
D.Strings[19434]="我今天准备为你工作！给我点好酒！"
D.Strings[19435]="哦！差不多该有人来救我了……"
D.Strings[19436]="我想我应该感激你。请收下这个。我不希望留着任何会让我想起这个地方的东西。"
D.Strings[19437]="在我被抓住时，我从一名巨魔身上偷来了这枚咒符。或许你能利用它来对付这帮家伙。"
D.Strings[19438]="我受够这个地方了。再见。"
D.Strings[19439]="啊，终于！"
D.Strings[19440]="在他们抓到我之前，我找到了这枚咒符。或许你能用得着……"
D.Strings[19441]="我希望你能用得着它。必须阻止这群卑鄙的禽兽！"
D.Strings[19442]="祝你好运！"
D.Strings[19443]="瞧，形势转好呀。"
D.Strings[19444]="你救的是我，而不是那些醉鬼，你应该感到庆幸。"
D.Strings[19445]="请收下这点微不足道的报酬，接受我的谢意吧。"
D.Strings[19446]="耶！我得救了！谢谢你，$n。"
D.Strings[19447]="我的天哪，那是什么气味——噢，哎呦！我的嗅觉恐怕要好一会儿才能恢复了。"
D.Strings[19448]="抱歉，朋友。收下吧，这应该能弥补你在营救我的过程中遭受的损失。"
D.Strings[19449]="你把那些材料都切好并扔下锅了吗？你在磨蹭什么呢？！"
D.Strings[19450]="今天还有好几道菜要做！赶紧！"
D.Strings[19451]="放点牛油进去！可能还需要加点普通油脂。玛格汉兽人可喜欢裂蹄牛油啦！"
D.Strings[19452]="好啦！闭上你的嘴，让我们做好这道菜！"
D.Strings[19453]="天哪，你就不能快点把水煮沸吗！"
D.Strings[19454]="该煮好的时候自然会煮好的！"
D.Strings[19455]="啊，这是真的吗？我……我摆脱了那个可怕的诅咒？"
D.Strings[19456]="$n，任何语言都不足以表达我的感激之情。"
D.Strings[19457]="你也看到啦，被这帮野蛮人洗劫后我身上也没多少值钱货了。但是我愿意与你分享我仅有的一切。来瞧瞧吧。"
D.Strings[19458]="我得走啦，省得又被抓住。如果你有任何需要，都可以来找我。"
D.Strings[19459]="嗯……苍蝇！好在现在我能尝尝它们的味道啦。"
D.Strings[19460]="能变回从前的样子真好，谢谢你。"
D.Strings[19461]="或许我这里有你感兴趣的东西？过来，看看有喜欢的吗？"
D.Strings[19462]="我得走了，$n。再见。"
D.Strings[19463]="开始检查投掷点！"
D.Strings[19464]="石像鬼发动了攻击！兄弟们，握紧你们的步枪！"
D.Strings[19465]="耶！我又变成女孩啦！"
D.Strings[19466]="谢谢你救了我。我讨厌变成青蛙！"
D.Strings[19467]="我不喜欢和陌生人讲话，不过你看上去挺友善的。给，这是我被绑架前找到的小玩意儿。"
D.Strings[19468]="我得走了。小心！"
D.Strings[19469]="警告！电源供给失效——启动紧急措施。"
D.Strings[19470]="啊，蠢货！你毁了一切！"
D.Strings[19471]="你觉得它能跳多远？"
D.Strings[19472]="我开始想念我的朋友了——他们肯定不会相信我的经历！哦，给你——这是我在玩捉迷藏游戏的时候找到的。"
D.Strings[19473]="让我看看我还能不能发出那种声音……"
D.Strings[19474]="嗯。谢谢你的好意，不过我不需要帮助。"
D.Strings[19475]="我试图念诵咒语来摆脱困境，我其实就快成功啦<呱>……我的天哪！"
D.Strings[19476]="好吧，我应该报答你的——给，收下吧。这玩意儿我多得是。"
D.Strings[19477]="你或许想离开这儿。我倒觉得在这种鬼地方被变成青蛙算是幸运的了。"
D.Strings[19478]="哦！我恢复先前的美貌啦？太好了！我还以为要当一辈子青蛙呢。"
D.Strings[19479]="太可怕了。我的皮肤变得黏糊糊的，我的舌头还一直在舔着自己的眼珠！"
D.Strings[19480]="谢谢你救了我。请收下这只巨魔货箱，就当作我们之间的回忆吧。"
D.Strings[19481]="我再也不想看见这个肮脏的池塘了。谢谢你，$n。我永远都不会忘记你！"
D.Strings[19482]="我肯定是疯了，让一个占星者来帮忙处理这么一个棘手的工作……"
D.Strings[19483]="我做了我该做的一切。不过保护城市的安宁并不是我的职责，不然要你这个卫兵干什么？"
D.Strings[19484]="如果是我们全权负责调查的话，我向你保证，证据仍然会很安全。可惜，我们使用了你的狗屁方法……"
D.Strings[19485]="当然，我的方法可能有待商榷。那就是我行事的方式，不过我要说明的是，是我的方法首先揭示了格里夫塔这个骗子的真面目。你所要做的只是保证城市的安宁，但你并没有完成这个简单的任务！"
D.Strings[19486]="你这个无能的家伙，只会说大话的败家子。"
D.Strings[19487]="你这个自负的家伙，保守的空谈家。"
D.Strings[19488]="%s和调查员艾斯瑞克怒目而视。"
D.Strings[19489]="嗨！有什么我可以帮忙的吗？"
D.Strings[19490]="这么看来你想知道我在寻找什么吗？我正在找一个既勇敢又强壮的家伙。聪明是一方面啦，不过你也得有一定的肌肉才行。$B$B当那些讨厌的黑铁矮人进攻时，你要以投掷杯子的方式来攻击他们——就是扔杯子击倒他们就这么简单。$B$B你每打倒一个矮人，你就会被标记一次。和我交谈，我就会根据你得到的印记数量发给你奖券。"
D.Strings[19491]="瞧，她多漂亮呀！想带她出去兜兜风吗？"
D.Strings[19492]="你的疯狂眼镜有什么用？"
D.Strings[19493]="小声点，$c。别被他们发现了。"
D.Strings[19494]="嗨！你有兴趣知道更多关于赛羊和赛羊会的事吗？"
D.Strings[19495]="我能免费得到一匹坐骑？"
D.Strings[19496]="我要怎么样才能让山羊跑得更快些？"
D.Strings[19497]="速度有什么区别？"
D.Strings[19498]="我的山羊会筋疲力尽吗？"
D.Strings[19499]="听上去很复杂……"
D.Strings[19500]="在你接受了任务之后，我们会借给你一头山羊。只是借你而已，所以你不能永远拥有它。山羊可能看上去有点慢，不过只要甩几下缰绳，它就会加快速度。$B$B我们的山羊爱吃苹果。我们已经在一路上放了很多苹果，记得顺路吃几个。吃苹果会让你的山羊忘记疲惫。"
D.Strings[19501]="给你山羊的同时，你也同样会得到一根缰绳。这可不是什么祖传的宝贝，你得真的去使用它！$B$B甩甩缰绳就可以让它加快些速度。你的缰绳放得越松，山羊就会跑得越快。$B$B不过它跑得越快，就越容易疲劳。所以你得注意点。"
D.Strings[19502]="你只要一开始甩甩缰绳，就可以看到山羊速度的改变。它起初是步行，甩几下缰绳以后就会开始疾走，在它疾走的时候再来几下，就会开始慢跑了。在它慢跑得时候再加把劲，就可以让它飞奔起来。"
D.Strings[19503]="让你的山羊慢跑或者飞奔太久的话，它会精疲力尽。如果你想让山羊恢复，让它步行或疾走一会儿就行了。如果附近有苹果就更好了，带它去吃一点，可以更快地恢复。"
D.Strings[19504]="赛羊其实比看上去更简单，不过要掌握的话还是需要技术的。如果你能避免让你的山羊精疲力尽，你只需要用用缰绳，吃吃苹果就可以了。"
D.Strings[19505]="$c，真是奇怪。我以为你已经发现了与天灾水晶关联的东西。$B$B我们必须设法关闭水晶的护盾，然后彻底摧毁它们。在你有所发现之前不如再回去多杀些天灾军团的成员？"
D.Strings[19506]="我曾经经历过这样的结局。这次会有新意吗？"
D.Strings[19507]="嗯？这是什么？$B$B别浪费时间！"
D.Strings[19508]="我特意为你留着这个呢！"
D.Strings[19509]="奇怪，我还以为你从那些天灾军团成员身上找到了关闭瘟疫水晶的方法呢。$B$B$c，我建议你有所发现之前，返回海滩继续屠杀他们。"
D.Strings[19510]="一切正在按照计划进行着，法库雷斯特公爵。我向你保证，这只是时间问题。"
D.Strings[19511]="我想你应该是带来了什么好消息吧？"
D.Strings[19512]="有办法可以买到山羊吗？"
D.Strings[19513]="如果你有足够多的美酒节奖券，美酒节营地的奖券兑换员就可以给你一个“荣誉酿酒商”的戳印。$b$b有了那个戳印，我就可以卖给你一头美酒节赛羊。不过我要提醒你，它们可并不便宜！"
D.Strings[19514]="我想买一头美酒节赛羊。"
D.Strings[19515]="来3-B展位看看！美酒节的麦酒！"
D.Strings[19516]="麦酒是不会让你感到腹胀，也不会上头……的美酒。雷酒可不敢这么说。"
D.Strings[19517]="麦酒是你的最佳选择！去美酒节尝尝麦酒吧！"
D.Strings[19518]="美酒节上就要喝真正的酒，雷酒！"
D.Strings[19519]="你想尽情享受欢乐吗？雷酒就是你最好的选择！去美酒节试试吧！"
D.Strings[19520]="你能感觉到这魔力吗？雷酒酿造师所释放的魔力！去美酒节看看吧！"
D.Strings[19521]="入侵者，你的生命结束了！"
D.Strings[19522]="让我送你的灵魂去极乐世界吧！"
D.Strings[19523]="让我们瞧瞧你是不是个值得尊敬的对手！"
D.Strings[19524]="$c，杀死你对我来说真是莫大的乐趣！"
D.Strings[19525]="你的灵魂将永无宁日！"
D.Strings[19526]="阴冷的黑暗等待着你的灵魂！"
D.Strings[19527]="我会终结你的生命，让你陷入堕落的深渊！"
D.Strings[19528]="我以为你不会这么主动的！"
D.Strings[19529]="这就是我说的“青蛙风格”！"
D.Strings[19530]="不会太久吧？"
D.Strings[19531]="我保证不会让你得疣……"
D.Strings[19532]="周围跑来跑去的魔汁还不够多……"
D.Strings[19533]="喂，$n，我知道有块沼泽离这里不远……"
D.Strings[19534]="是你的莲花叶子还是我的？"
D.Strings[19535]="感觉有点像小青蛙，是吗？"
D.Strings[19536]="魔汁跳进了$n的口袋。"
D.Strings[19537]="我没什么可以教你的了，孩子。去找荣耀堡的莱布斯基——就在地狱火半岛。他能教你更多东西！"
D.Strings[19538]="我没什么可以教你的了，孩子。去找萨尔玛的塞比格——就在地狱火半岛。他能教你更多东西！"
D.Strings[19539]="这里是我们辛辛苦苦用双手建设起来的！朋友，它凝聚着我们的血和泪。$B$B相信我，我们绝对不会放弃瓦加德。"
D.Strings[19540]="嘿，朋友，我拿来的这个东西可以说是一个伟大的成就，一件你从未看到过的东西！不过现在你可以买到它，可以非常便宜地买到它！$B$B你知道，我已经厌倦了花钱在酒馆里找寻完美的人。所以我做了这个东西……这副眼镜可以让每个人看上去都是那么完美无缺。你可别错过这种好东西！$B$B那么，你想试试吗？让我的口袋里多一点钱？既然你看上去那么完美，我会给你打折的！"
D.Strings[19541]="我在寻找各种各样的东西！不过你所说的那些印记，酒桶保护者的印记？那些东西可以证明你知道如何应付战斗。$B$B每当你打倒一个黑铁矮人，你就会得到一个印记。我会用一张奖券来交换你所得到的印记。$B$B给出这些奖券让我感到很痛苦，但它同样意味着我能再次看到你，不过还得看到你再次离开……"
D.Strings[19542]="我看到你在街对面闲逛，就满心希望你可以到这边来。那么，甜心，有什么需要我为你效劳的？"
D.Strings[19543]="嗨，美女！帅哥！"
D.Strings[19544]="嗨！美女，过来！"
D.Strings[19545]="哟！大家伙！你觉得你能对付得了我吗？"
D.Strings[19546]="嗨，强壮的家伙！嗨，$c！你喜欢钱吗？我很有钱！到这来看看我的金币怎么样？"
D.Strings[19547]="嗨，嗨！亲爱的，你的身材真不错！"
D.Strings[19548]="哇！美女！"
D.Strings[19549]="工头不是说他要带些卫兵过来吗？他们在哪儿呢？"
D.Strings[19550]="你打算向裂角挑战？我说，你可真勇敢。"
D.Strings[19551]="替我们好好地教训他！"
D.Strings[19552]="你瞧，我们眼下还不算太忙。不如帮你做个棺材……"
D.Strings[19553]="正常的狗根本不敢靠近我。当我发现这点时深受打击……我其实是很喜欢动物的。$B$B天灾犬是不错的替代品。当然，它们的模样……并不好看。但你知道吗，我的相貌也好看不到哪儿去！"
D.Strings[19554]="情况不妙啊。"
D.Strings[19555]="嗨，朋友，你想试试全世界最好的酒吗？"
D.Strings[19556]="嗨，就是你。那个高个子……想来点刺激的吗?  德罗恩的酿酒厂可以帮助你！"
D.Strings[19557]="德罗恩的美酒简直是个传说！过来尝尝传说中的美酒吧！"
D.Strings[19558]="德罗恩的酿酒厂里有着你能用钱买到的最好的酒！他们曾被《地精美酒月刊》评为“世上最好的佳酿”！"
D.Strings[19559]="我们为部落干杯！你也是为部落干杯吗？来德罗恩的酿酒厂让我们看看！"
D.Strings[19560]="嗨！塔卡里的巫毒酒不会让你喝了就死的！但他们也有一种酒可以让你喝了就死……"
D.Strings[19561]="如果你想充分享受生活，你就必须尝尝塔卡里的巫毒酒！"
D.Strings[19562]="塔卡里的巫毒酒是你所能找到的最好的酒！他们曾被《地精美酒周报》评为“世上最好的佳酿”！"
D.Strings[19563]="德罗恩的酿酒厂可以让你尽享欢乐！来美酒节尝尝吧！"
D.Strings[19564]="同知道什么是真正美酒的兽人一起庆祝美酒节吧！来美酒节尝尝德罗恩的佳酿！"
D.Strings[19565]="如果你以为兽人给你脑袋上来一下就已经够狠了，就去体验一下更狠的吧！去德罗恩的酿酒厂试试看，只有美酒节才有哦！"
D.Strings[19566]="去德罗恩的酿酒厂加入你的兄弟姐妹们，一起为部落干杯！"
D.Strings[19567]="你真的想喝兽人或食人魔酿的酒吗？你最好去美酒节尝尝塔卡里的巫毒酒！"
D.Strings[19568]="如果你想喝些异国风味的酒，美酒节上有塔卡里的巫毒酒！"
D.Strings[19569]="需要放松吗？去美酒节的塔卡里巫毒酒馆看看，那里的酒会让你感到舒畅！"
D.Strings[19570]="塔卡里的巫毒酒可以让狂欢一直继续下去！去美酒节看看吧！"
D.Strings[19571]="孵化者呢？快去孵蛋！"
D.Strings[19572]="这里是练习灭火技术的地方，为了被遗忘者！"
D.Strings[19573]="我败了！弟兄们，别害怕！没有谁能将你们赶出岩石熔炉！"
D.Strings[19574]="好痛！好痛啊！！！"
D.Strings[19575]="克雷顿太帅了！！"
D.Strings[19576]="克雷顿太帅了！"
D.Strings[19577]="克雷顿不帅了！"
D.Strings[19578]="%s在临死前扭动着身躯，发出痛苦的呼喊声。"
D.Strings[19579]="我最喜欢尖叫声了。"
D.Strings[19580]="要令这些意志脆弱的外来者屈服真是太容易了。"
D.Strings[19581]="我倒要看看这帮入侵者能承受怎样的折磨。"
D.Strings[19582]="很好！你还活着。我又有乐子咯！"
D.Strings[19583]="这帮家伙体型不大，意志倒是强硬得多嘛。"
D.Strings[19584]="$n的混合剂被毁坏了！必须重做一瓶。"
D.Strings[19585]="放弃求生的欲望吧。我可以整日整夜地折磨你。"
D.Strings[19586]="<乌尔芬低声嚎叫，嗅了嗅你身上的气味；接着你就明白了他的语言。>$B$B北方那头名叫迦瓦尔的白色座狼带走了我的狼群。我要割断他的喉咙，重新成为群族的首领。"
D.Strings[19587]="%s对着雏鸟咕咕地叫。"
D.Strings[19588]="在剃刀岭和这里之间发生的坠毁事故把酿造流程搞的一塌糊涂！但那也不能改变黑铁矮人几乎每小时一次的进攻！$B$B如果你想帮忙的话，那么这样，我会让你从我们这里借一头山羊和一根缰绳。$B$B你每给我带来一个酒桶，我就给你些奖币，作为你给我带来酒桶的感谢，我甚至会让你更久地使用我的山羊！\n\n但是，只要你开始了，在明天以前你就不能再做了。\n\n你确定已经准备好了吗？"
D.Strings[19589]="我准备为你工作了！给我一头山羊！"
D.Strings[19590]="你仍然需要帮忙从剃刀岭附近的坠毁点那里搬运酒桶吗？"
D.Strings[19591]="我看到你在欣赏我们合法拥有的赛羊……我能感觉到，你想要参加赛羊会……不过在你参与之前，你必须得做些事。$B$B嗯，对于这些山羊来说，工作和玩其实是一样的。"
D.Strings[19592]="杰森，你给我听着。既然钢羽还有一窝嗷嗷待哺的雏鸟，你就别想动她。"
D.Strings[19593]="为什么啊？如果我们能将她和雏鸟做成标本，陈列在一起也挺不错的呀——"
D.Strings[19594]="杰森！"
D.Strings[19595]="干嘛啊？我们在灰熊丘陵的时候可不就是这么做的嘛。"
D.Strings[19596]="他们将工具放在这样的箱子里。去营帐附近找找看。"
D.Strings[19597]="我之前看到过铁炉堡的士兵灭火。他们是英雄！"
D.Strings[19598]="$n，不要傻站在那里！卡拉诺斯正在燃烧！快去帮忙！啊，所有的酒……"
D.Strings[19599]="如果你想接受灭火训练，那么你来对了地方。虽然在这附近到处都是雪，但你永远都不知道贝尔丁·钢架还是那些侏儒什么时候会引起一场爆炸，对吧？"
D.Strings[19600]="$n，碧蓝岗哨的村庄正在燃烧！快去帮忙灭火！"
D.Strings[19601]="喂，你！干嘛呢，勤快点！$B$B没看到这里人人都忙着么，你这个饭桶！"
D.Strings[19602]="朋友，瞧你那副得意忘形的模样！你是不是从哪个富商那儿抢到什么好东西了？财富是要大家分享的……朋友，别小气嘛！"
D.Strings[19603]="瞧那边！那蠢货把农夫给惹火了。这下麻烦了吧，我看他的小命难保啦。"
D.Strings[19604]="为骡子钉上马蹄铁要花多少钱啊？"
D.Strings[19605]="我们不负责给骡子钉马蹄铁。准确地说，那是远征队的事儿。"
D.Strings[19606]="你完全不了解状况！如果我不赶紧出发的话，好的建筑用地都会被别人抢先霸占啦！"
D.Strings[19607]="这又不是我的问题！如果你这么着急建房子的话，就在要塞里建好了，省得你整天抱怨！"
D.Strings[19608]="朋友，我说的是实话！北海海盗是世界上最强硬的海盗。$B$B你最好不要惹事。算啦！反正所有的白痴海盗都会被处死！"
D.Strings[19609]="你能不能从我的熔炉旁滚开……"
D.Strings[19610]="那，那是头骡子！"
D.Strings[19611]="嗯……那是什么？"
D.Strings[19612]="朋友，你这样就很无耻了。你是想惹我发火是吧？滚，你这个懦弱的海盗。明天再见！"
D.Strings[19613]="欢迎来到维德瓦堡垒！瞧，那片土地等着你去占领呢！"
D.Strings[19614]="是啊，诺森德的环境极其恶劣，但是我们拥有强壮的体魄和勇敢的精神，能面对一切挑战！"
D.Strings[19615]="我们要用刀剑夺得这片土地的所有权，然后用犁来开垦荒地！而你们，将作为拓荒的先驱者，被后世传颂。"
D.Strings[19616]="你们并不孤单。我们特意准备了一群骡子，运送你们所需的补给物资。"
D.Strings[19617]="斧头、锄头、种子、钉子、食物、毯子、水……任凭你们挑选。价格非常合理哟。"
D.Strings[19618]="我的物资供应非常充足。如果你们还需要其它的货物，欢迎随时来找我！"
D.Strings[19619]="我忠诚的顾客，呃……朋友们，来吧，征服这片土地！"
D.Strings[19620]="你是新来的吧，瞧你那副自以为是的模样。$B$B<索雷克朝地上吐了口唾沫。>$B$B肯定是……"
D.Strings[19621]="我不太懂艺术……但是我知道自己喜欢什么！"
D.Strings[19622]="嘿，兄弟！给我们来点啤酒吧。你瞧，酒杯都空了。"
D.Strings[19623]="伙计，瞧好啦。我来让你见识一下什么是真正的舞蹈。"
D.Strings[19624]="朋友，你瞧，谁敢欺负我的朋友，我就让他没好果子吃！"
D.Strings[19625]="<老冰鳞在沙地上画画，希望你能从粗糙的图案上看出他是在企求你的帮助。>"
D.Strings[19626]="我们在这里练习灭火技术。"
D.Strings[19627]="快点，$c！鹰翼广场到处都是火焰！走！去扑灭那些火焰！"
D.Strings[19628]="一切都结束啦，伙计！"
D.Strings[19629]="祖尔金……会给你们惊喜的……"
D.Strings[19630]="你们没有时间啦！"
D.Strings[19631]="烧死你们！"
D.Strings[19632]="风之圣魂将是你的梦魇！"
D.Strings[19633]="阴影将会降临在你们头上……"
D.Strings[19634]="既然之前杀不掉我……你们不会再有第二次机会啦！"
D.Strings[19635]="你们不会从这个梦魇里醒来的！"
D.Strings[19636]="你的意志现在属于我！"
D.Strings[19637]="黑暗已经来临……"
D.Strings[19638]="你的灵魂在流血！"
D.Strings[19639]="这没什么。"
D.Strings[19640]="你的死相会比它更凄惨。"
D.Strings[19641]="我不在乎！"
D.Strings[19642]="这……不是我的结局！"
D.Strings[19643]="你疯了！你会带给所有人死亡！"
D.Strings[19644]="一道电能风暴出现了！"
D.Strings[19645]="%s闪烁着微光逐渐消失了……"
D.Strings[19646]="亲爱的，我们得找到一块带温泉的好地方。"
D.Strings[19647]="当然啦，亲爱的。"
D.Strings[19648]="我可不希望在咱们的土地上遇见恐怖的狼、巨人或是丑陋的山羊。"
D.Strings[19649]="你说得对，亲爱的。不过在庄稼成熟之前，咱们还不得靠羊肉维持生计……"
D.Strings[19650]="我宁可屠宰那些骡子！我说，你为什么不带些牲畜来呢？"
D.Strings[19651]="亲爱的，我宁可听骡子叫也不愿意听你讲话。"
D.Strings[19652]="在利爪与尖牙面前，下跪吧，祈祷吧，颤栗吧！"
D.Strings[19653]="你没可能胜过这伟大的战力！"
D.Strings[19654]="你们注定要失败！"
D.Strings[19655]="我要把你撕碎！"
D.Strings[19656]="你将死无全尸！"
D.Strings[19657]="你竟敢向蔑冬部族宣战？！我要用那面旗帜刺穿你的身体！"
D.Strings[19658]="啧啧，祭品自己送上门来了？你脑子坏掉了吧？"
D.Strings[19659]="我要拿你的尸体去喂匕鞘湾的鲨鱼！"
D.Strings[19660]="丢酒杯！"
D.Strings[19661]="<老冰鳞警惕地盯着你，他漫不经心地晃动着脑袋，眨巴着死鱼眼。>"
D.Strings[19662]="长屋被摧毁了！警报声响彻云霄。"
D.Strings[19663]="士兵，学会自我保护！用长枪将他们从空中打下来！以牙还牙！"
D.Strings[19664]="直接命中码头！掠龙防御者已经被惊动了！"
D.Strings[19665]="不要给他们任何机会！将他们从空中击落！"
D.Strings[19666]="为部落干杯！"
D.Strings[19667]="美酒节来啦！"
D.Strings[19668]="为联盟干杯！"
D.Strings[19669]="为我们口袋里的金币干杯！"
D.Strings[19670]="没有什么节日比得上美酒节的美食和美酒！"
D.Strings[19671]="$R，占用你一点时间好吗？"
D.Strings[19672]="陌生人，我说你还是回去吧。$b$b这里不是供你游历的风景地。它会摧毁你的躯体，嚼碎你的骨头。"
D.Strings[19673]="维库人的仓库燃起了熊熊烈焰！掠龙防御者已经被惊动了！"
D.Strings[19674]="把他们从天上打下来！士兵，别让他们靠近你！"
D.Strings[19675]="取回"
D.Strings[19676]="上面那些亚勒伯龙维库人身上就有钥匙。"
D.Strings[19677]="这只巨大的南瓜灯矗立在村子的中央。"
D.Strings[19678]="打碎南瓜！"
D.Strings[19679]="南瓜被打碎了，不过没有更多的财宝了。"
D.Strings[19680]="打碎南瓜就能得到隐藏的财宝！这真是太棒了！"
D.Strings[19681]="不要告诉我，你没有多余的缰绳了……"
D.Strings[19682]="看什么看？哈哈……开个玩笑嘛！"
D.Strings[19683]="和好朋友坐在一起分享美酒，还有什么能比得上这样的惬意呢……嗝儿！"
D.Strings[19684]="“耶……酒精真令人发狂呀！”等等……酒劲来没上来呢……"
D.Strings[19685]="朋友，坐下来喝一杯吧！也给我来一杯！"
D.Strings[19686]="……那个卑鄙的海盗安着两条木腿，左手是个铁钩，他还有两颗玻璃假眼和木头鼻子！"
D.Strings[19687]="啧啧，送上门来的祭品。"
D.Strings[19688]="你是来送死的吧？"
D.Strings[19689]="你也会成为巫妖王的仆从。"
D.Strings[19690]="我们的仪式能添上新的祭品啦。"
D.Strings[19691]="……因此他说“我只有一颗眼珠！当然不会重影！”"
D.Strings[19692]="嗨，咱们来玩玩吧？"
D.Strings[19693]="你是为巫妖王而活的！"
D.Strings[19694]="我会让你大吃一惊的。"
D.Strings[19695]="停尸间还留着你的空位呢。"
D.Strings[19696]="亲吻炮手的女儿？为什么我总是碰不到心仪的少女……"
D.Strings[19697]="听说泰里镶个画框就能赚1000金币。或许我也该考虑做工艺品生意！"
D.Strings[19698]="啊哈哈哈！"
D.Strings[19699]="格雷兹克斯，这是你朋友？$g他:她;不太像……海盗。"
D.Strings[19700]="那些酒可棒啦。你不介意的话，我想回去喝几杯。你要一起来吗，$n？"
D.Strings[19701]="啊哈哈哈哈哈！"
D.Strings[19702]="渺小的灵魂，滚吧。"
D.Strings[19703]="新鲜的尸体。"
D.Strings[19704]="真令我失望啊，竟然不做反抗。"
D.Strings[19705]="你的牺牲会让我们获得更多力量。"
D.Strings[19706]="无赖港就在前面。如果你不介意的话，我要去躺会儿。我头痛得厉害。"
D.Strings[19707]="别喋喋不休。"
D.Strings[19708]="你还指望谁来救你是吧？可是都没有人露面呢。"
D.Strings[19709]="喂，嗯……“伙计！”这就是我向你提过的家伙！$g他:她;可是真正的“海洋的霸主”！"
D.Strings[19710]="嗯？你想飞？不……这是不可能的！"
D.Strings[19711]="米克高维尔，我负责处理探险者协会的官方事宜。带我去探险者协会哨站！"
D.Strings[19712]="$n，快！快穿上伪装！"
D.Strings[19713]="呀！"
D.Strings[19714]="呸！是，我也是南海海盗的一员了——如果你想打什么鬼主意，就趁早死了这条心。信不信我现在就砍翻你！"
D.Strings[19715]="嗨，欢迎来到美酒节！"
D.Strings[19716]="你好，朋友！欢迎来到美酒节！"
D.Strings[19717]="欢迎，$c！欢迎参加铁炉堡一年一度的美酒节庆典！"
D.Strings[19718]="傻瓜，你阻止不了我！受死吧！"
D.Strings[19719]="你真的认为能击败我，救出你的朋友吗？"
D.Strings[19720]="谁会做出这样的事情？！"
D.Strings[19721]="嗨，欢迎参加美酒节。过来喝上几杯吧！"
D.Strings[19722]="我的脑子一片混沌！"
D.Strings[19723]="怎么了，朋友？欢迎来到美酒节！现在就去买些酒喝喝吧！"
D.Strings[19724]="嗨，$c！欢迎来到美酒节庆典……现在尽情享受这里的美酒美食吧！"
D.Strings[19725]="你是故意来毁坏矮人的地毯的吧！你怎么能这样！"
D.Strings[19726]="他们竟然如此对待那条地毯，可耻！"
D.Strings[19727]="呀啊啊啊！别想得到我的望远镜，你这只配滚去舱底喝污水的蠢货！"
D.Strings[19728]="霍泽，宝贝！爸爸来啦！"
D.Strings[19729]="尼德梅尔，你觉得是谁干的呢？"
D.Strings[19730]="还用想吗？我知道是谁，也只有他们能做出这样的龌龊事！"
D.Strings[19731]="来，谷迪，我们去探险吧。"
D.Strings[19732]="肯定是那些混蛋铁矮人表亲！肯定是！"
D.Strings[19733]="不可能吧。"
D.Strings[19734]="威廉，山脊上长着一丛新鲜的草药。叫贝卡娜来采一下吧。"
D.Strings[19735]="你不信！？兄弟，我打赌一定是他们！你为什么不相信我？"
D.Strings[19736]="因为他们是铁制的啊，你这个大笨蛋！看来你一点都没有继承爸爸的聪明才智！"
D.Strings[19737]="够了！别说了！兄弟，我受够你了！干嘛提到爸爸！起来！我要跟你决斗！别坐在那儿挨打，不然待会又要听你抱怨了！"
D.Strings[19738]="你冷静点！无缘无故地发什么脾气呀！还记得上次你乱撒气的后果吗？坐下啦！"
D.Strings[19739]="拜托，叫她来呀。"
D.Strings[19740]="什么？为什么要我去？"
D.Strings[19741]="好吧，我去叫她。"
D.Strings[19742]="奇怪，她通常都待在这儿的……"
D.Strings[19743]="嗨，贝卡娜，我……嗯，艾蕾娜发现了一丛草药！你能去采一下吗？"
D.Strings[19744]="谢谢！如果你……嗯，需要帮助的话就来采我……啊，我是说，就来找我，我很乐意帮忙的！"
D.Strings[19745]="%s红着脸走开了。"
D.Strings[19746]="啊，这些苹果实在太可口了！"
D.Strings[19747]="我的弟弟肯定想尝尝的。"
D.Strings[19748]="谢谢你，但我现在并不是很饿。"
D.Strings[19749]="嗨，威廉，什么事？"
D.Strings[19750]="啊，谢谢你！我一会就去。"
D.Strings[19751]="不用，我自己能搞定。谢谢你。"
D.Strings[19752]="我最好在采集草药之前问清楚状况。我可不想再次被狼袭击。"
D.Strings[19753]="威廉真有趣。他常常脸红。"
D.Strings[19754]="我相信，高贵的联盟士兵心里肯定惦念着其它更重要的事情。噢！艾蕾娜发现了一些草药，我去帮她采一下。"
D.Strings[19755]="%s将草药种植在附近。"
D.Strings[19756]="嗯……好吧，小心点，他可能爱上你了。我也不太相信他那个姐姐……"
D.Strings[19757]="好吧，贝卡，把它们放在树丛旁的花园里就行了。要小心狼！"
D.Strings[19758]="……我告诉过你那时候我深入黑石山的中心地带探险的事吗？"
D.Strings[19759]="那时，我就这么用力一砍杀死了那兽人，然后拿走了这副肩甲。"
D.Strings[19760]="我在那里发现了一把锋利的斧子，一把刚从烈火中铸造出来的利斧。"
D.Strings[19761]="我亲手在熔炉旁辛勤地铸造了几个小时，终于铸成了这件胸甲。"
D.Strings[19762]="我在一个巨魔的口袋里找到了一颗漂亮的宝石，虽说不是什么八心八箭，但是我把它卖了个不错的价钱！"
D.Strings[19763]="……我就这么用力一拳，打倒了那个鱼人，从它那又冰凉又粘稠的手中拿到了这颗宝珠！"
D.Strings[19764]="……我不会忘记去祖阿曼森林深处冒险的那段时光。"
D.Strings[19765]="……当我们在希利苏斯与一波波的异种虫作战时，燃烧的砂粒灼烧着我的脸。"
D.Strings[19766]="……整座城市都被烧毁了，只留下了一片烧焦的废墟。人们倒下，当他们重新站起来的时候，就变成了亡灵的军团。"
D.Strings[19767]="……我有没有跟你说过我到厄运之槌深处探险的事？"
D.Strings[19768]="%s默默地点了点头……"
D.Strings[19769]="%s不耐烦地听着……"
D.Strings[19770]="维萨鲁斯放射出纯净的能量！"
D.Strings[19771]="%s开始吸取附近邪能水晶的能量。快摧毁它！"
D.Strings[19772]="欢迎来到美酒节，朋友！在赞美那些相互对抗的酿酒厂之间的友好竞争精神时，我们可以得到很多乐趣。如果你有任何疑问，找我就是了！"
D.Strings[19773]="餐饮供应商"
D.Strings[19774]="奖币和纪念品"
D.Strings[19775]="赛羊"
D.Strings[19776]="你好，$r。我是希达尔格，擅长狩猎，算得上是一流的驯鹰大师。停在我肩膀上的就是杀人机器木丝了。$B$B你可能会想，“驯鹰师是干什么的呢？”我来告诉你——我们是优秀的猎手！训鹰术是一门利用经过特殊训练的猛禽来狩猎的艺术。你对此感兴趣吗？希达尔格可以教你！"
D.Strings[19777]="美酒节就是个享受这个世界中最好的食物和美酒的盛典，一点都不夸张。过来看看这么多清爽的手工啤酒、节日香肠、椒盐卷饼和奶酪。还有什么比这更好的呢？而且你只需要花那么一丁点钱。"
D.Strings[19778]="除了啤酒和香肠，美酒节最受欢迎的就是纪念品了！不管是传统节日的服装，还是美酒的袖珍酒桶，一切应有尽有，你可以在贝尔比这里买到各种美酒节的主题物品。记得你手上要有足够多的美酒节奖币，因为你只能用它们来购买纪念品。你可以通过在美酒节的场地附近帮忙来获取奖币。"
D.Strings[19779]="让火焰净化一切吧！嗨，怎么了？"
D.Strings[19780]="赛羊会是美酒节的一个重要传统节目。如果你想知道更多的信息，就去和羊圈旁的波尔·冻石谈谈。而且那也是获取美酒节奖币的好方法！"
D.Strings[19781]="嗨，欢迎来到美酒节！在这里你可以享受各种乐趣，如果你有任何问题的话，随时可以过来问我。不然，就去买些啤酒和椒盐卷饼吧！"
D.Strings[19782]="美酒节的意义就在于美食和美酒，而且我们所提供的就是最好的！你觉得我在撒谎？看看我们的那些美酒、香肠、椒盐卷饼和奶酪吧。你会发现，你周围都是最棒的美食，而且你找不到比这更便宜的了！"
D.Strings[19783]="每个人都喜欢那些疯狂的美酒节赛羊。想要了解更多信息吗？去和羊圈旁的德利兹·塔波奎克谈谈吧。享受一点乐趣，并获取一些美酒节奖币！"
D.Strings[19784]="嗨，记得给你自己弄些美酒节的纪念品！不管是传统节日的服装还是美酒的袖珍酒桶，应有尽有。只要去找布利克斯·菲克维特就行了，但是首先请确保你手上有着足够的美酒节奖券……因为你只能用它们来购买纪念品。你可以通过在美酒节的场地附近帮忙以获取奖券。"
D.Strings[19785]="你好，愿艾露恩之光与你同在。"
D.Strings[19786]="你能再为我读一次奥利卡的诗吗？"
D.Strings[19787]="我非常乐意！\n\n不要在我的墓碑前哭泣，\n我不在那里，我没有长眠。\n\n我是凛冽的寒风，\n掠过诺森德的雪原。\n\n我是温柔的春雨，\n滋润着西部荒野的麦田。\n\n我是清幽的黎明，\n弥漫在荆棘谷的林间。\n\n我是雄浑的鼓声，\n飞越纳格兰的云端。\n\n我是温暖的群星，\n点缀达纳苏斯的夜晚。\n\n我是高歌的飞鸟，\n留存于美好的人间。\n\n不要在我的墓碑前哭泣，\n我不在那里，我从未长眠。"
D.Strings[19788]="想搭一程顺风船么？"
D.Strings[19789]="没错！"
D.Strings[19790]="维萨鲁斯过载了！"
D.Strings[19791]="我跟你说啊，猎艳的最佳方法就是保持良好的风度，还要戴上这种护目镜！"
D.Strings[19792]="*呀呀！*嘿！看我的海盗伪装！耶！*呀呀！*"
D.Strings[19793]="*呱*讲话得像个海盗才行啊！耶！*呀呀！*"
D.Strings[19794]="*呀呀！*你这蠢货，给我闭嘴！我们会被你害死的！*呱！*"
D.Strings[19795]="叫什么叫，你简直是个白痴！那些海盗会把你剁了，然后拔下你的羽毛插在帽子上！"
D.Strings[19796]="<岩石猎鹰啄着你的手。>"
D.Strings[19797]="<猎鹰发出饥饿的叫声，想要吃幼虫。>"
D.Strings[19798]="<喂食岩石猎鹰。>"
D.Strings[19799]="兄弟，我们已经失去了一切。幸运的是，卡玛古为我们提供了容身之所。"
D.Strings[19800]="你在我们最需要的时候伸出了援手。愿海洋赐予你财富。"
D.Strings[19801]="谢谢你，阿加鲁克。我们在伊斯卡尔就听说了你的事迹。"
D.Strings[19802]="愿塔尤卡保佑你和你的村落。"
D.Strings[19803]="“朋友”，你最好埋下头！希望你懂我的意思！$B$B耶！"
D.Strings[19804]="亲爱的，快啦。你很快就会苏醒过来，艾泽拉斯世界将在恐惧中颤抖！"
D.Strings[19805]="苏醒吧，伊米隆国王。时机已经成熟，你很快就能重掌统治权。"
D.Strings[19806]="从沉睡中醒来吧，我的爱。有了巫妖王的支持，世界将因你而颤抖。"
D.Strings[19807]="仪式怎么要进行这么久？你的主子向我保证过，说有了你的帮助，仪式会快很多的！"
D.Strings[19808]="加倍努力！伊米隆国王很快就要苏醒了，接着他将登上王座！"
D.Strings[19809]="该死的泰坦诅咒了我们！伊米隆，我的国王，张开双眼吧！"
D.Strings[19810]="是时候了，我的丈夫，我们的国王很快就能重新回到我们身边啦。我要和他一起铲除世间的蝼蚁！"
D.Strings[19811]="仪式进行得太慢啦。需要更多的祭品！"
D.Strings[19812]="不要着急，伊米隆。我对你另有安排。你先回到乌特加德之巅去，在那里更好地为我效劳。如果真有这些蝼蚁再次找上你的那一天，到时你就可以亲自为妻子复仇了。"
D.Strings[19813]="谁才是猎物啊？"
D.Strings[19814]="真容易对付……"
D.Strings[19815]="今晚我们要吃你的肉，喝你的血！"
D.Strings[19816]="我负责主持格斗比赛。你想不想赌一把啊？怎么样，有信心吗？但是——谁敢搞贿赂选手的猫腻，我就让他走跳板。$B$B我会亲自维持比赛的公平！"
D.Strings[19817]="与其他种族不同，血精灵的财富不仅仅局限于金币、丝绸或是宝石之类的原材料。辛多雷精妙的工艺本身就是无价的财富。"
D.Strings[19818]="塔鲁克派我来收欠款。"
D.Strings[19819]="别惹我，败狗！老子是接受过血骑士正统训练的强者！"
D.Strings[19820]="我认输！我认输！以奎尔萨拉斯的名义！不要杀我！"
D.Strings[19821]="我还钱！我还钱！呀～！不要伤害我！"
D.Strings[19822]="还钱，哈瑞！"
D.Strings[19823]="“疯狗”约纳·斯特林要我整日整夜地打扫甲板。$B$B打扫甲板？！$B$B我是个法师，凭什么让我做这种杂事！就算要打扫，也该玩点新花样吧。"
D.Strings[19824]="喝光啊，你真不够意思！"
D.Strings[19825]="吃！喝！快乐起来！下一轮酒该你请啦！"
D.Strings[19826]="小子，喝光你的朗姆酒！要知道，闪金镇还有着口渴的孤儿呢！"
D.Strings[19827]="安静点好吗？要是被人发现，我们就死定了。"
D.Strings[19828]="好吧，伙计！谁点了风味朗姆酒啊？小杰克，是你吗？"
D.Strings[19829]="没事，甜心。这杯是免费的。"
D.Strings[19830]="免费的朗姆酒？啊……这可是我的最爱！"
D.Strings[19831]="太棒了！喝得……有点……多了！"
D.Strings[19832]="<这个海盗显然是喝多了，看上去有点不省人事。>"
D.Strings[19833]="<谨慎地翻开海盗的口袋，寻找塔鲁克的欠款。>"
D.Strings[19834]="看什么看？再给我来一杯！"
D.Strings[19835]="来点什么呢？朗姆酒？还是麦酒？$B$B或者你想尝尝别的？"
D.Strings[19836]="我想请杰克喝一杯。最好是……那种后劲儿特足的饮料。"
D.Strings[19837]="你想公然和杰克叫板是吗？$B$B嘿，我得说着这绝对是个……愚蠢的决定。这会让你损失惨重的。我可不想冒着丢掉小命的危险去干这种一分钱都挣不来的破事。嗯，你最好等我跑远了再动手。"
D.Strings[19838]="给，你可以用这枚金币买给自己想要的东西。"
D.Strings[19839]="当然啦，亲爱的。把它算到哈里的账上好不好呀？他欠我一杯酒呢！"
D.Strings[19840]="好啦，$n！这肯定管用！让我们好好打扫一下吧！"
D.Strings[19841]="瞧！一尘不染！"
D.Strings[19842]="呀啊啊啊！想要夺得我的财宝……你要费一番功夫了！"
D.Strings[19843]="什么……嗝？！"
D.Strings[19844]="够了……我喝不下了！"
D.Strings[19845]="你戴过合成酿酒护目镜吗？超级难受的！"
D.Strings[19846]="黑铁矮人进攻"
D.Strings[19847]="那些黑铁矮人简直是失心疯了，他们几乎每个小时都要来一次，打碎酒桶之后就跑掉了！$B$B也许你要问，“我为什么要关心这个呢？”$B$B那么我告诉你，他们破坏掉的都是提供免费啤酒的酒桶！没错，免费的！$B$B如果你正好遇到黑铁矮人破坏酒桶，别忘了帮我们保护这些免费的美酒！"
D.Strings[19848]="美酒节是个完美的节日！不过万事无绝对，黑铁矮人就是这个节日中的一个小麻烦。他们几乎每个小时都要来一次！$B$B他们的目标是提供免费啤酒的酒桶，而且那些啤酒还都是最棒的上等啤酒！$B$B你看，如果你正好遇到黑铁矮人破坏酒桶，别忘了帮我们保护这些免费的美酒！"
D.Strings[19849]="能量！多点，多点，再多点！"
D.Strings[19850]="它沸腾燃烧了……"
D.Strings[19851]="我不会停下的。永远不会……"
D.Strings[19852]="你死定了，旱鸭子！"
D.Strings[19853]="看来我的伙计们需要帮手啊！"
D.Strings[19854]="这是我的！"
D.Strings[19855]="你想偷能量！受死吧！"
D.Strings[19856]="从我的水晶周围滚开！"
D.Strings[19857]="呀啊啊啊……又死了！"
D.Strings[19858]="呀啊啊啊，朋友！"
D.Strings[19859]="你就是这样报答主子的吗？你这烂熊！啊啊啊啊啊！"
D.Strings[19860]="约纳·斯特林这个蠢货迟早要害死我们。如果他多花点时间观察局势的话，就会明白在战争期间攻击职业海军是件多么愚蠢的事。"
D.Strings[19861]="你最好快滚，$n。我不想和约纳的死扯上关系。$B$B他们还不知道我杀了以前的船长取而代之，我才能勉强坐稳头领的位置。"
D.Strings[19862]="%s吞食着主人的尸体。"
D.Strings[19863]="沧海桑田，你，还有他们……世事变幻。$B$B卡玛古因此受到威胁。你能为我们做些什么呢？"
D.Strings[19864]="我是个外行，嗯？沃尔特讲话不经过大脑吗？我独自一人就教训了那些铁矮人，还在这里搭建起营地观察挖掘场的动静。"
D.Strings[19865]="瞧，那家伙正在为地毯的事烦恼呢。"
D.Strings[19866]="晚上好。"
D.Strings[19867]="暗礁母海狮和公海狮找到了真爱。"
D.Strings[19868]="启动。"
D.Strings[19869]="士兵们，起来战斗吧！为死去的骑士带来胜利的荣耀！"
D.Strings[19870]="沃尔特派我来要一些黑铁条。"
D.Strings[19871]="呃……这么说……你打算启程返回前哨站，是吧？"
D.Strings[19872]="沃尔特的工作台可以使用了。"
D.Strings[19873]="<跳上工作台，让沃尔特将你塞进魔像中。>"
D.Strings[19874]="瞧，完美的作品！"
D.Strings[19875]="每天两次，分别是在早上6点15分和下午6点15分，大工匠梅卡托克会亲自来到美酒节的现场，主持开酒罐仪式。千万别错过！"
D.Strings[19876]="哇欧，哇欧，哇欧！伙计们，稳住！"
D.Strings[19877]="矮人们突然都大笑起来。"
D.Strings[19878]="开酒罐仪式"
D.Strings[19879]="噢，尊贵的岩石与钢铁领主，您……您打算如何处理呢 ？"
D.Strings[19880]="每天两次，分别是在早上6点15分和下午6点15分，萨鲁法尔大王会亲自来到美酒节的现场，主持开酒罐仪式。千万别错过！"
D.Strings[19881]="朋友，这行不通的。铁矮人才不会喜欢那个大家伙！"
D.Strings[19882]="再过10分钟，萨鲁法尔大王就要来主持开酒罐仪式啦！"
D.Strings[19883]="再过20分钟，萨鲁法尔大王就要来主持开酒罐仪式啦！"
D.Strings[19884]="雷波斯基，不懂就别折腾了！完全没有必要！那些铁矮人不会知道真相的！你不如回去调查到底是谁在你的地毯上捣鬼，这里的工作就交给真正的科学家吧！"
D.Strings[19885]="萨鲁法尔大王来了！开酒罐仪式马上就要开始啦！"
D.Strings[19886]="我非常伤心！就别开玩笑了！"
D.Strings[19887]="再过20分钟，大工匠梅卡托克就要来主持开酒罐仪式啦！"
D.Strings[19888]="再过10分钟，大工匠梅卡托克就要来主持开酒罐仪式啦！"
D.Strings[19889]="大工匠梅卡托克来了！开酒罐仪式马上就要开始啦！"
D.Strings[19890]="要是爸爸能活着看到这一天该多好啊！"
D.Strings[19891]="我说，你知道自己在干什么吗？你竟然拖着那个金属玩意儿踩过雷波斯基的地毯，看我怎么收拾你。"
D.Strings[19892]="很好。这桶螺钉或许能起作用……"
D.Strings[19893]="铁符文构造体U-9207无法识别你的声音。雷波斯基，现在开始摧毁你的地毯。"
D.Strings[19894]="想活命的话*噼啪*就跟着我。"
D.Strings[19895]="加文·雷酒负责看管酒窖。只要他呆在地下室，这些酒桶就十分安全。"
D.Strings[19896]="警报！警报！构造体检测到敌人已经越过了我们的防线。加速。"
D.Strings[19897]="构造体载体汇报。主要功能：监视。"
D.Strings[19898]="未发现异常。继续执行指派的任务。"
D.Strings[19899]="向我们的创造者欢呼。"
D.Strings[19900]="胡乱调用构造体的功能将导致程序终结。前进。"
D.Strings[19901]="构造体不解答铁矮人提出的任何问题。启动摧毁程序。"
D.Strings[19902]="构造体不得与低等生物交谈。低等生物必须努力工作。"
D.Strings[19903]="你丢了钱包？构造体找到了装满金币的钱包。"
D.Strings[19904]="站住！立即出示身份证明！"
D.Strings[19905]="这里禁止入内！"
D.Strings[19906]="我没见过你这样的家伙。"
D.Strings[19907]="喂！站住！"
D.Strings[19908]="站住！！站住！！废铁现在会自己移动了？"
D.Strings[19909]="回答错误！"
D.Strings[19910]="很好，$n。非常好……"
D.Strings[19911]="好吧……是我的错。我这是在哪儿？"
D.Strings[19912]="为伟大的创造者欢呼吧！"
D.Strings[19913]="你当然是对的。继续。"
D.Strings[19914]="原谅我的傲慢！"
D.Strings[19915]="你是替创造者传话的吗？"
D.Strings[19916]="我们会加倍努力的！"
D.Strings[19917]="继续工作。努力工作。"
D.Strings[19918]="什么都瞒不过布隆特斯。"
D.Strings[19919]="不要到处闲逛。"
D.Strings[19920]="继续摧毁。"
D.Strings[19921]="援军正在途中。确保功能正常。"
D.Strings[19922]="消灭土灵入侵者。"
D.Strings[19923]="侍从们，过来吧！主人在召唤你们！"
D.Strings[19924]="你在风暴峭壁的同胞的工作日趋白热化。很快，我们的创造者就能重获自由了。"
D.Strings[19925]="你在北方的同胞已经征服了那些石头怪物，指挥他们朝奥杜尔前进。很快，万神殿剩余的防御力量就会被消灭。"
D.Strings[19926]="我们必须设法封锁凡人在这片区域开启的三条裂隙。大地能知晓我们的所作所为。如果不能关闭地表的裂缝，它就会继续妨碍我们的宏伟计划。"
D.Strings[19927]="把这里埋了！这是主人的命令！"
D.Strings[19928]="雷鸣声响彻整个山洞。"
D.Strings[19929]="雷鸣声逐渐减弱了。"
D.Strings[19930]="我准备好了，沃尔特。"
D.Strings[19931]="系统故障。3……2……"
D.Strings[19932]="尽情享用吧，兄弟们！"
D.Strings[19933]="系统故障*滴答*"
D.Strings[19934]="即将坠毁*咣*"
D.Strings[19935]="构造体即将关闭*哔*"
D.Strings[19936]="*滴答*飞行系统故障*哐*"
D.Strings[19937]="等等，凡人，我有话和你说。"
D.Strings[19938]="当你凝视宝珠时，你感到一股熟悉的力量正在影响你的思绪。"
D.Strings[19939]="让宝珠引导你的思绪……"
D.Strings[19940]="你还不能和占卜宝珠产生共鸣。"
D.Strings[19941]="你凝视着面前的宝珠，思绪渐渐飘散……"
D.Strings[19942]="是陆地，科瓦斯基先生！港口就在前方，长官！"
D.Strings[19943]="谢谢你，亨德尔先生。"
D.Strings[19944]="梅拉先生，请你驶向港口。"
D.Strings[19945]="托格雷船长！我们即将抵达目的地，长官！"
D.Strings[19946]="谢谢你，科瓦斯基先生！你可以回去继续监督进港情况了！"
D.Strings[19947]="干得好。请把我们安全带到下一个港口吧。"
D.Strings[19948]="托格雷船长是最棒的！"
D.Strings[19949]="我在拖洗甲板！"
D.Strings[19950]="梅蕾女士号永远是最棒的船！"
D.Strings[19951]="拖洗甲板治好了我的驼背！"
D.Strings[19952]="是，是，科瓦斯基先生。"
D.Strings[19953]="形势正在发生变化，$n。战争开始了。$B$B是让我们的人民抓住机遇去帮助盟友们……还是在一旁静观局势发展呢？"
D.Strings[19954]="对不起，我没时间闲聊。"
D.Strings[19955]="没看见我正忙着吗？离我远点，别让科瓦斯基撞见了。"
D.Strings[19956]="真是个启航的好日子，对吧？"
D.Strings[19957]="在托格雷手下做事非常辛苦，不过他是位好船长。"
D.Strings[19958]="我们剩下的人不多了，$n。宿敌的回归让我们忧虑万分。"
D.Strings[19959]="我得密切注意船只和船员的情况。请原谅我不能和你闲聊。"
D.Strings[19960]="梅蕾女士号长期停靠塞拉摩岛，我们奉命保护船只上的乘客。"
D.Strings[19961]="欢迎乘坐梅蕾女士号。我是船长托格雷。$b$b我负责解答所有关于这艘船的疑问，并祝愿大家旅途愉快。就像我喜欢的座右铭那样：对我来说，船只的意义在于带你游历全世界。没有它，你就无法享受这样美妙的体验。"
D.Strings[19962]="梅蕾女士号"
D.Strings[19963]="物品和装备"
D.Strings[19964]="“鼠胆船长”？"
D.Strings[19965]="是呀，梅蕾女士号，她是一艘很漂亮的船。$b$b你知道，呆在船上能学到很多知识的。有首诗说得好：苍茫黑夜中两只落寞行船，擦身而过时互相道安，风笛长鸣，堪堪见到模糊的形，片刻后却只余远去的影；人生亦如这广阔的洋，你我的船不期中徜徉而遇，彼此仅是浅烙下容与音，即又遁入黑暗与寂静。"
D.Strings[19966]="肚子饿的话，可以找厨师长格莱斯。"
D.Strings[19967]="考布斯先生是随船的工程师和军需官，他出售各种你可能需要的物资。若是你想要修理装备的话，也可以找他哦，他技术不错的。"
D.Strings[19968]="啊，是啊……这个名字。嗯……人们常说，好名字就像美好的愿望，你需要用心经营，却很可能因一次失误前功尽弃。至于我的名字的由来嘛，不用说也知道为什么别人这么称呼我吧……"
D.Strings[19969]="亡者已经复苏，任何敢于穿越亡者领地的人都会遭到疯狂的报复。回去吧！"
D.Strings[19970]="大地开裂，神器失窃。古神之盾已经遗失。混乱将会笼罩世界。"
D.Strings[19971]="风暴愤怒法杖被盗。这片大陆遭到了诅咒！风暴永远不会停息！"
D.Strings[19972]="除非伊斯多弗的冰冷之心归位，否则它迟早会吞噬这片大陆。但凡拥有它的人，无一例外地被冰冷鲜血诅咒所困扰，为他们的痛楚默哀吧……"
D.Strings[19973]="那些试图穿上克瓦迪尔的上古甲胄的蠢货将会尝到无尽的痛苦。凡人，当心这片迷雾，你很可能丢掉性命。"
D.Strings[19974]="我真幸运。没几个牛头人能成为护卫舰的船员的！格雷兹克斯甚至让我操纵这些不可思议的战斗快艇。"
D.Strings[19975]="我没功夫和你闲聊，洛伊。带我去无赖港。"
D.Strings[19976]="维库人的怒火将吞噬你！"
D.Strings[19977]="它的能量在我体内流淌！我是神！！！"
D.Strings[19978]="阿卜杜尔像牛一样强壮！！"
D.Strings[19979]="你想挑战我？我拥有十倍于常人的力量！！！！"
D.Strings[19980]="你这不怕死的蠢货！阿卜杜尔要让你知道厉害的！"
D.Strings[19981]="我……需要你们的……帮助！我……快支持不住了！"
D.Strings[19982]="啊！我要疯了，快帮帮我！"
D.Strings[19983]="快！我的心志快要完全丧失了！"
D.Strings[19984]="无与伦比的能量……我……想要……更多！"
D.Strings[19985]="邪能……流遍我全身吧……"
D.Strings[19986]="你的生命会让我变得更强壮，恶魔……基尔加丹给我们的礼物！"
D.Strings[19987]="很快我就会比其他精灵更强壮了！我会效忠基尔加丹！"
D.Strings[19988]="多点……多点……再多点！！！"
D.Strings[19989]="这道传送门与其它连接艾泽拉斯世界的传送门不同。为了让它持续工作，我们需要有更多的法力晶格。$b$b否则我们就有可能失去通向奎尔丹纳斯岛和太阳之井的捷径。"
D.Strings[19990]="从我的眼前滚开！"
D.Strings[19991]="%s释放了一道幽魂冲击波！"
D.Strings[19992]="你干了些什么？！"
D.Strings[19993]="我的力量……消失了！"
D.Strings[19994]="不……不……不！！！！！"
D.Strings[19995]="开火！开火啊，你们这群胆小的海盗！"
D.Strings[19996]="索罗夫要消灭更多的海盗！"
D.Strings[19997]="那些小家伙呢！？怎么只有一面破旗帜！"
D.Strings[19998]="索罗夫被耍了！啊啊啊啊……"
D.Strings[19999]="由于注满了能量，%s变得不稳定起来！"
D.Strings[20000]="%s释放了能量，它的周围变成了一片火海！"
D.Strings[20001]="裂隙的能量是我们的！"
D.Strings[20002]="滚开，这是我们的地盘！"
D.Strings[20003]="我的！你们休想夺走这块地方！"
D.Strings[20004]="这不是给你的！滚出这里！"
D.Strings[20005]="复活吧，为你永恒的主人效劳！"
D.Strings[20006]="核心超出负荷。检测到系统故障……"
D.Strings[20007]="水晶发出微弱的光芒。它的保护能量变得很弱，但并没有完全消失。"
D.Strings[20008]="<高贵的弗拉斯卡萨赞许地对你点了点头。>"
D.Strings[20009]="我们现在正在测试祖阿曼，一个位于幽魂之地的10人团队副本。你需要达到68级才能进入。"
D.Strings[20010]="尊特拉华达，我已经做好去祖阿曼的准备了。传送我吧！"
D.Strings[20011]="目标确定。启动安全程序。"
D.Strings[20012]="开启本地防御。"
D.Strings[20013]="命令接受成功。入侵者将被消灭。"
D.Strings[20014]="%s周身充满了奥术能量。"
D.Strings[20015]="你好，$r。$b$b我的商店终于开张了。希望你能找到你想要的东西！"
D.Strings[20016]="呱！你杀不了我，我是无敌的！"
D.Strings[20017]="快！利用火焰来支援地面部队。它的远古魔力应该可以清除泰罗克的护盾。"
D.Strings[20018]="凯尔萨斯的军队就是从这里撤退到太阳之井的。他的一些走狗仍然残留在这里，燃烧军团以最不平常的方式奖赏着他们……"
D.Strings[20019]="我们成功地拿下了圣殿。我们可以继续转变这些魔像守卫，用它们来保护其它的战略要地。"
D.Strings[20020]="喂！伙计，你想要预订慈悲修女号的座位？你找对地方啦……"
D.Strings[20021]="我们必须确保不会再有谁葬身大海。"
D.Strings[20022]="瞄准，往死里打！"
D.Strings[20023]="开火！亲爱的，为了财宝，开火吧！"
D.Strings[20024]="有人或许能风光一辈子，但是总不可能在死后也为所欲为吧！开火！"
D.Strings[20025]="$c，请原谅，我必须专心工作。"
D.Strings[20026]="很多人葬身大海。我和小精灵负责在海面上搜寻灵魂。"
D.Strings[20027]="索罗夫的财宝掉在了地上。"
D.Strings[20028]="我和小精灵守护着那些迷失的灵魂。"
D.Strings[20029]="海洋是个危险的地方，$c。我们必须保持警惕。"
D.Strings[20030]="我现在恐怕不能和你谈话。"
D.Strings[20031]="能量……是我的！"
D.Strings[20032]="你阻止不了我！"
D.Strings[20033]="水晶结界……我需要能量！"
D.Strings[20034]="这么……多……能量。"
D.Strings[20035]="能量……我能感觉到！"
D.Strings[20036]="我们会重新夺回这些结界的！"
D.Strings[20037]="你不能夺走我们的结界！"
D.Strings[20038]="啊哈哈哈，来一瓶侏儒烈酒庆祝一下！"
D.Strings[20039]="一炮轰成渣啊！"
D.Strings[20040]="尽情享受美酒和女人！"
D.Strings[20041]="受死吧，旱鸭子！"
D.Strings[20042]="财宝属于我们！"
D.Strings[20043]="……你见过凯尔萨斯现在的样子了吗？"
D.Strings[20044]="嗯。自从风暴要塞被攻击以来，他就变得有些不一样了。"
D.Strings[20045]="他被打倒在地，人人都以为他已经死了。要不是女祭司德莉希亚及时赶到，谁知道会发生什么！"
D.Strings[20046]="他现在的眼神……让我感到害怕。"
D.Strings[20047]="是的，不过我们还将始终追随着他。我们的职责就是在他进行准备的时候守护这里。"
D.Strings[20048]="准备？准备什么？"
D.Strings[20049]="他的……回归。"
D.Strings[20050]="纳鲁祝福你，我的朋友。"
D.Strings[20051]="我这边的行动倒不是很频繁。在战区中如此靠近前线，真是紧张刺激。"
D.Strings[20052]="说到行动，我接到命令，要去发动一次空袭。"
D.Strings[20053]="我完全忍受不了这些恶魔了！"
D.Strings[20054]="是啊！你上次看到末日守卫洗澡是什么时候？"
D.Strings[20055]="……更不用说花园里到处都是那些讨厌的深渊巡逻队了。"
D.Strings[20056]="但是我们为什么需要他们？"
D.Strings[20057]="凯尔萨斯大人坚持要这么做。"
D.Strings[20058]="好吧，我希望等他们的事情搞定之后，凯尔萨斯会把他们送回传送门的另一端去……"
D.Strings[20059]="努力训练！我们是凯尔萨斯身边仅存的忠诚卫士。"
D.Strings[20060]="认真一点！必要的时候，我们必须以生命来保卫太阳之井！"
D.Strings[20061]="凯尔萨斯不能容忍再次失败！"
D.Strings[20062]="再来一次！"
D.Strings[20063]="晨锋部队会为所有的辛多雷守卫这片土地。我们没有任何退路！"
D.Strings[20064]="这里不是度假胜地——我们的生命，我们的灵魂，能够摆脱魔瘾的最后希望，都让我们和奎尔丹纳斯紧紧联系在一起。"
D.Strings[20065]="你想得到失心者那样的下场吗？不想吧？！那么现在就给我努力一点！"
D.Strings[20066]="基尔加丹快要失去耐心了！把那些纳鲁的仆从们消灭干净！"
D.Strings[20067]="库斯卡钥匙"
D.Strings[20068]="你畏惧死亡？如果你失败的话，会有远比死亡更加痛苦的下场等着你！去消灭那些凡人！"
D.Strings[20069]="回到你的岗位上去！战斗还没有结束！"
D.Strings[20070]="阳湾军械库是我们的了！我们已经把那些恶魔逼退到黎明广场去了！"
D.Strings[20071]="我们已经占领了阳湾圣殿！通知沙塔斯城，我们现在要开始行动了！"
D.Strings[20072]="我们已经夺取了军械库的控制权，但我们在岛上的工作还没有完成。"
D.Strings[20073]="我们已经夺下了军械库，$n。尽管如此，我们仍然不能沾沾自喜，满足现状。燃烧军团不会就此停下他们的脚步。"
D.Strings[20074]="我们的努力得到了回报。我们已经占领了阳湾圣殿，$n。去那里看看有什么可以帮忙的吧。"
D.Strings[20075]="$n，很高兴再次看到你！"
D.Strings[20076]="大家看，是$n！"
D.Strings[20077]="晨锋部队、恶魔和纳迦们要小心了，因为$n回来收拾他们了！"
D.Strings[20078]="$n$G大人:女士;，您能与我们并肩作战，我们感到很荣幸。"
D.Strings[20079]="……黑暗神殿正在被围攻？"
D.Strings[20080]="在阿卡玛和他卑鄙的同党们干掉奥之后不久，奥尔多和占星者的军队就对黑暗神殿发动了攻击。还好我们及时离开了伊利丹。"
D.Strings[20081]="我听说有二十来人闯进风暴要塞，把他给干掉了。"
D.Strings[20082]="才二十个？不可能吧，少于四十个人根本不可能。"
D.Strings[20083]="好吧，也许是有一百人左右吧……"
D.Strings[20084]="阿卡玛那条狗，他背叛那个背叛者也只是时间问题而已……"
D.Strings[20085]="勇者号上的水手将竭诚为你提供温馨舒适的服务。"
D.Strings[20086]="不好意思，我们还是另找时间谈吧。再见。"
D.Strings[20087]="破碎残阳很幸运能有$n与我们并肩作战。"
D.Strings[20088]="要不是$n，我们可能早就死光了。"
D.Strings[20089]="$n，再次感谢你能帮助我们。如果没有你，我们根本不可能有这样的成就。"
D.Strings[20090]="欢迎乘坐勇者号。不好意思，失陪……"
D.Strings[20091]="$n，能为您效劳，我感到很荣幸。"
D.Strings[20092]="$n化解了无数次恶魔的攻势。"
D.Strings[20093]="我有点嫉妒维瓦·水歌了。为什么？他比我更优秀！"
D.Strings[20094]="如果我是那些晨锋血精灵的话，我一看到$n来了就会立即跳水游走。"
D.Strings[20095]="你觉得$n终结了多少失心者的痛苦？"
D.Strings[20096]="快看，我们最棒的勇士$n，在这里！"
D.Strings[20097]="对水手来说，这是个不幸的名字，是吗？"
D.Strings[20098]="我们的英雄来了！最近过得怎么样，$n？"
D.Strings[20099]="我承认，如果不是$n，整场战役都会一败涂地。"
D.Strings[20100]="无论怎样，我们都将永远赞扬你所作出的努力，$n！"
D.Strings[20101]="他大概是年纪最大、最有经验的水手了吧，他的体格最强壮！嗯？嗯？和食人魔一样粗壮的手臂！"
D.Strings[20102]="最近在死亡之痕蹂躏那些恶魔吗，$n？"
D.Strings[20103]="$n，哪天我请你喝杯酒吧。"
D.Strings[20104]="我简直不敢想象，如果$n决定不再回来的话，这里将会变成什么样子。"
D.Strings[20105]="我们发誓要全力保卫勇者号乘客。必须确保鲁瑟兰村至暴风城港口航道的安全。"
D.Strings[20106]="$n，你不知道看到你给我们带来了多大的安慰。"
D.Strings[20107]="太巧了……我们刚提到你，$n！"
D.Strings[20108]="有$n在这里，谁还需要魔像守卫？"
D.Strings[20109]="嗨，$n，也给我们留点事做吧，让我们也能得到些赞扬好不好啊？"
D.Strings[20110]="晨锋部队被赶出了阳湾港口！我们胜利了！"
D.Strings[20111]="检查"
D.Strings[20112]="嗨，孩子。欢迎乘坐少女之爱号。我是维克诺兹船长，能与黑水海盗一起航行是你的荣幸。血帆海盗根本不敢靠近，因为我们有最精锐的水手，货舱里还堆放着大量火药。你知道，所谓安全保障嘛。$b$b如果你有有疑问，尽管来问我好了。"
D.Strings[20113]="少女之爱号"
D.Strings[20114]="这就是少女之爱号。她很漂亮，是吧？不久前，公爵委派我担任这艘船的船长。她本不属于我，因此“少女之爱”这个名字不是我取的。我猜为她取名的水手大概是在海上航行太久了，没能好好享受港口的美妙时光。你懂我的意思吗？"
D.Strings[20115]="如果你的肚子饿得咕咕叫，就去找厨师长拜雷·钢胃谈谈，可别说是我告诉你的这家伙的名字可是有来历的……"
D.Strings[20116]="热砂港的船只怎可能没有工程师呢？托克斯宾德出售所有你需要的物品。如果你想要修理物品的话，他的技术也不错哟。"
D.Strings[20117]="欢迎乘坐羽月渡船号。我们往返于羽月要塞和被遗忘的海岸，搜寻不幸的落水者。大海暗藏危机，你必须做好充分的准备。$b$b你可以和食物供给商谈谈，购买足够的干粮。他们会很乐意帮忙的。"
D.Strings[20118]="我代表月海之浪号的全体船员欢迎你,\127$c。希望在起航之前，我们的食物供应商能帮你准备好一切。"
D.Strings[20119]="搭乘艾露恩的祝福号时请保持警惕，$r。虽然艾露恩保佑我们找到了新的盟友，但是深不可测的海洋依然危机四伏。$B$B但是，在月神的感召下，我们承担起搜寻失落灵魂的重任。"
D.Strings[20120]="在航海之旅中，艾露恩一直庇护着我们。但是我们仍然要保持警惕，$c。"
D.Strings[20121]="不好意思，$r，我必须专心工作。"
D.Strings[20122]="对不起，除了与小精灵交流并向船长汇报我的发现之外，我没时间和其他人闲聊。请原谅。"
D.Strings[20123]="欢迎乘坐少女之爱号。她将载你安全驶往港口。"
D.Strings[20124]="如果你狠狠地捏一个侏儒，是可以学到很多东西的：比如说逃脱的小伎俩，制作美味的曲奇饼干，甚至可以学到如何制造飞行器。"
D.Strings[20125]="飞行器？"
D.Strings[20126]="你经常捏侏儒吗？"
D.Strings[20127]="我一有空就会这么做。感觉非常不错，同时也能让我把握他们的心思——照我的经验来说，通常没什么好事。"
D.Strings[20128]="那实在是……太棒了。你说的飞行器是什么？"
D.Strings[20129]="谢谢提醒！我现在就去试试。"
D.Strings[20130]="风筝"
D.Strings[20131]="火箭鸡"
D.Strings[20132]="纸飞机"
D.Strings[20133]="嗯……如果那个讨厌的船长向你推销他的特价品，你就直接把那些烂货扔进海里去。说不定有些龙虾人会因此丧命，不过好在你能捡回一条命呀。"
D.Strings[20134]="你好，$n。$b$b我已经造好了铁砧，可以开始装备我们的军队了。这一步对我们来说非常重要，不过仍然有许多事需要去做。$B$B对你来说更重要的是：我可以制造新的武器装备了！也许你会对此感兴趣。"
D.Strings[20135]="我们已经拿下了港口，这艘船真的算是个不错的奖励。只不过她还不适合航海。$B$B对了，我得到命令去监视绿鳃海岸一带的纳迦。$B$B你觉得你能帮帮我吗？"
D.Strings[20136]="我必须阻止晨锋部队的增援。"
D.Strings[20137]="欢迎登上唤雷号！$b$b不用理会那群整天抱怨爆炸或者类似东西的家伙。真的，每个人都会犯错误，我们应该开除掉一些懒惰的家伙。$b$b你看，我知道如果有一个船长的船坠毁了22还是23次是有点……但任何少于那个次数的事故就根本算不得什么了。"
D.Strings[20138]="<抱怨> 那些山都不知道从哪里钻出来的……五次都是突然出现！"
D.Strings[20139]="<抱怨> 你可能会觉得让一艘飞艇撞进海里挺困难的，但是前后发生了四次就更不可思议了！"
D.Strings[20140]="<抱怨> 我真希望我们能设法避免坠入湖中。我真希望我们只坠入湖中一次……但实际上，我们先后坠入四面湖中，其中还包括洛丹米尔湖！"
D.Strings[20141]="很幸运，那些松树枝看上去并没有怎么伤到飞艇。$b$b不过那也不是我们三次坠毁在森林里的借口。"
D.Strings[20142]="我从未想过我能看见泰达希尔……我也的确没想到我们会坠入泰达希尔。"
D.Strings[20143]="现在我们已经成功地穿越雷霆崖两次了！"
D.Strings[20144]="<抱怨> 我真不知道为什么我们能毫发无损地穿过千针石林的那一大堆石柱，最后却坠毁在闪光平原上！"
D.Strings[20145]="如果你喜欢刺激，那可是我们船长最擅长的事了！我爱这份工作！"
D.Strings[20146]="不要多问……"
D.Strings[20147]="你不能把我们的坏运气都怪在我的头上吧……我甚至都不知道我要去哪！$b$b尽管也许那意思是说你能责怪我……$b$b不！等等！我能把这艘船完好的停进港口的……但那肯定是船长发出的命令！也许他喜欢挑战我们的极限来测试我们的生存能力还有修理技术。"
D.Strings[20148]="干得好，$n。"
D.Strings[20149]="你有多少净化过的金属，我就要多少。"
D.Strings[20150]="照这样下去，我们的人很快就会有最好的装备了。"
D.Strings[20151]="谢谢你，$n！"
D.Strings[20152]="你干得太棒了。你是不是以前当过铁匠？"
D.Strings[20153]="有了纳迦的矿石和你提供的纯净金属，就可以铸造出一种几乎无懈可击的合金了。"
D.Strings[20154]="你在这里所做的工作对我们有着不可估量的作用。"
D.Strings[20155]="谢谢你帮我净化这些金属，$n。事情实在太多了，我根本没时间去做。"
D.Strings[20156]="我的名字曾经是埃欧罗，这是我的故事：有一天，村子里进行了一场秘密的投票，最终那次投票导致我改变了自己的名字。他们让我选择是改名字还是像考尔奇一样。要是你的话，你也会这么做的吧。你觉得我的新名字怎么样？有很大的改进，对吧？$b$b对了，如果你在找活干的话，去布告栏那里看看吧。"
D.Strings[20157]="西边出现龙鹰！把那个$c打下来！"
D.Strings[20158]="不要让那龙鹰通过这里！开火！"
D.Strings[20159]="破碎残阳的垃圾！随意开火！"
D.Strings[20160]="我们掩护你，$n！"
D.Strings[20161]="爬升！从上方进攻！让我们想办法给$n提供一些掩护。"
D.Strings[20162]="表演时间到了！炸得再狠点，再快点！"
D.Strings[20163]="有什么我能帮你的吗？也许你在找一头宠物猪吧？"
D.Strings[20164]="金猪"
D.Strings[20165]="银猪"
D.Strings[20166]="战斗阵形！死亡之痕就在前面！"
D.Strings[20167]="加快填弹速度。有些恶魔已经是风一吹就要倒了。"
D.Strings[20168]="盯着恶魔。我们今天不是来消灭那些亡灵天灾的。"
D.Strings[20169]="碾碎这些讨厌的垃圾！"
D.Strings[20170]="粉碎他们！把他们的骨头碾进泥土里！"
D.Strings[20171]="用力点，蝼蚁！我们必须在主人回归前保证太阳之井的安全！"
D.Strings[20172]="烧死他们！把他们碎尸万段！"
D.Strings[20173]="这里没有什么能比我更让你感到恐怖的了！"
D.Strings[20174]="要么胜利要么死亡！这就是军团的行事风格！"
D.Strings[20175]="我听说深渊领主是蛆虫变成的，布鲁塔卢斯！"
D.Strings[20176]="小蓝鸟又在说大话了！你不如下来看看能不能把我这条虫子从泥土里啄出来！"
D.Strings[20177]="新兵们，你们好。我是教官巴尔杜姆。在接下来的几天内，你们会接受我的训练。"
D.Strings[20178]="凯尔萨斯·逐日者王子的军队占领了奎尔丹纳斯岛。先前的情报表明他已经死了，但情报错了。"
D.Strings[20179]="他和他的恶魔同伴们正在高地上设法重新点燃太阳井，打开一道裂缝，把他们的首领基尔加丹重新召唤回这个世界。"
D.Strings[20180]="我们的任务是在支援上头派来的特种部队的同时，尽可能多的消灭凯尔萨斯的手下。"
D.Strings[20181]="不用说也知道，我们中的很多人将一去不复返。但你们只需要牢记训练的内容，时刻保持警惕，就可以大大提高生还的机率。"
D.Strings[20182]="我要说的就这些了。认真点，孩子们。"
D.Strings[20183]="有种就下来啊！我会撕下你的翅膀，把你的尸首埋在泥土里。咱们看看谁会变成土里的蛆虫，你这条没用的龙！"
D.Strings[20184]="我喜欢冷一点的食物！"
D.Strings[20185]="啊哈哈哈哈！你想把我冻起来吗？下来啊，我会给你的生命添加一些真正的热量。"
D.Strings[20186]="这是什么可怜的魔法？你不如带上二十四个最棒的伙伴再回来试一次，怎么样？"
D.Strings[20187]="长官，我们已经从南面进入了。有何指示？"
D.Strings[20188]="非常好，让你的小队列好阵型。还有工作要做。"
D.Strings[20189]="好吧，安静。我们有很多事需要做，但时间只有那么一点。"
D.Strings[20190]="我曾经和一些德莱尼人在斯克提斯并肩作战，也曾经和另一些德莱尼人在影月谷对抗伊利丹。然而现在，我们是在艾泽拉斯，这里的情况看上去很艰险。"
D.Strings[20191]="首先，我要告诉你们这些辛多雷，我的要求很严格……这和占星者们的行事方式并不一样。要么给我打起精神，要么就给我滚回去！"
D.Strings[20192]="既然没人有异议，欢迎来到奎尔丹纳斯岛。太阳之井就在南边的高地上，而凯尔萨斯王子则躲藏在东面的魔导师平台里。"
D.Strings[20193]="我们是来这里支援那些高级军官召集来的所谓“冒险者”的。我们会帮助他们守卫岛上的关键位置，让他们远离战火，这样他们就能安心去做他们的事情了。"
D.Strings[20194]="你们可以从小队指挥官那里得到更进一步的分配和指示。如果没有什么其他问题，就这样，好运！"
D.Strings[20195]="欢迎来到太阳之井。尽管这里气候宜人，景色秀丽，但女士们先生们，你们不是来这里度假的！"
D.Strings[20196]="现在的情况是这样：在那些更有经验、并且装备精良的伙计们对付凯尔萨斯王子时，我们正在努力保护我们所能保护的一切。"
D.Strings[20197]="我知道，我们也以为他已经死了，不过事实并非如此。他正设法用太阳之井将燃烧军团的主子——基尔加丹带到这个世界来。"
D.Strings[20198]="我跟你们打保票，如果他成功了，这个世界将会遭受比外域更严重的灾难！所以，我们必须保证这一切不会发生。"
D.Strings[20199]="在猎人们被指派狙击敌方飞行员的同时，战士们也将被分配前往关键地区进行防御。"
D.Strings[20200]="我正在等待着给你们指派特殊任务的命令。在此期间，请待在这里随时准备出发！"
D.Strings[20201]="占领阳湾军械库的战斗有什么新消息吗？"
D.Strings[20202]="我们还要多久才能完成阳湾军械库的铁砧和熔炉？"
D.Strings[20203]="我还有其他事想问你。"
D.Strings[20204]="主教，我们有没有拿下阳湾港口？"
D.Strings[20205]="纳苏恩，你觉得我们还要多久才能在阳湾港口布置一个炼金台？"
D.Strings[20206]="摧毁太阳之井高地中的魔法屏障的进展如何了？"
D.Strings[20207]="我们仍然在尝试摧毁第一道屏障阿加麦斯。拜托你了，$c，请立即前往奎尔丹纳斯岛，尽一切可能帮助我们！"
D.Strings[20208]="第一道屏障阿加麦斯已经被摧毁了，基尔加丹的两个副官——萨洛拉丝女王和高阶术士奥蕾塞丝——必须接受正义的制裁。$B$B召集你的伙伴吧，$c，攻入太阳之井！第二道屏障洛希多尔是我们的下一个目标。"
D.Strings[20209]="第二道屏障洛希多尔已经被摧毁了，但是埃库尼苏——太阳之井高地最后的那道魔法屏障挡住了我们，$n。$B$B继续尽一切可能帮助我们吧。"
D.Strings[20210]="成功了！我们毫发无损地完成了这次航行！不过现在还不是偷懒的时候！加大马力，准备靠港！"
D.Strings[20211]="准备靠港！"
D.Strings[20212]="考伯伯特先生，全速前进！"
D.Strings[20213]="赶快出发吧，考伯培特先生。"
D.Strings[20214]="考伯波特先生，可以出发了。"
D.Strings[20215]="考伯托特先生……快点！"
D.Strings[20216]="先生，我的名字是……啊，算了……"
D.Strings[20217]="菲尔维兹先生，请你稍微慢点！"
D.Strings[20218]="顺便说一声，我的名字是考伯纳特！"
D.Strings[20219]="先生，你差点就把我的名字叫对了……"
D.Strings[20220]="先生，你几乎快要把我的名字说对了。"
D.Strings[20221]="先生，你至少得认清我的性别吧……"
D.Strings[20222]="如果基尔加丹通过太阳之井进入这个世界，我们就将陷入一场一万年以来最残酷的战争。"
D.Strings[20223]="埃库尼苏已经不复存在，但是，我们……太迟了……$B$B基尔加丹被释放了！我们唯一的希望只剩下这个世界的英雄们了！"
D.Strings[20224]="奎菲克斯！！我们遇到麻烦了！"
D.Strings[20225]="又一次成功的航行！伙计们，准备停靠在飞艇塔上！"
D.Strings[20226]="真不敢相信，那次旅行实在是太幸运了！我是全世界最好的天空船长！"
D.Strings[20227]="我们安全了！但我们飞得还不够快！我想要的是那种风抚过脸庞的感觉！"
D.Strings[20228]="铁鹰号是客船，并不是战舰！好吧，对我来说这仅仅是一份工作。只要王子肯付工钱，我就顺从那个喜欢自吹自擂的船长。$b$b不管怎样，欢迎上船。"
D.Strings[20229]="你有东西需要修理吗？请使用售货机器人。"
D.Strings[20230]="我们保护着这艘由奥格瑞玛飞往荆棘谷格罗姆高营地的飞艇。"
D.Strings[20231]="现在没空，朋友……我有事要做，再见。"
D.Strings[20232]="我管理着艾泽拉斯最坚固的飞船。她曾经靠两门轻型火炮就炸平了一座城市，真的……她投射下的阴影就足以让敌人魂飞魄散。$b$b什么？这当然是真的！"
D.Strings[20233]="%s变形成为了一头熊！"
D.Strings[20234]="成功了，$n。掌控了阳湾港之后，我们离全面胜利只有一步之遥了。"
D.Strings[20235]="这座纪念碑不漂亮吗？对我们来说，铭记这些为胜利而牺牲的伙伴们非常有意义。我们永远都不能忘记战争的代价——即便是那些我们最终获胜的战争。"
D.Strings[20236]="我去打个瞌睡。你觉得自己能在飞船停泊期间控制好她吗？"
D.Strings[20237]="好吧，等我一会儿，我去拿轴承……"
D.Strings[20238]="该出发了！"
D.Strings[20239]="精彩的旅途即将展开！"
D.Strings[20240]="看我的！"
D.Strings[20241]="前进，我能搞定。"
D.Strings[20242]="喂！我们要出发了！"
D.Strings[20243]="醒醒！！我们要启航了！"
D.Strings[20244]="别睡了！！我们要出发了！"
D.Strings[20245]="如果你真的想打开那些门，就至少需要3个人的力量！跟我来！"
D.Strings[20246]="%s大声地清了清喉咙。"
D.Strings[20247]="飞艇已经靠港。站好了！"
D.Strings[20248]="你的工作很辛苦吗？累得连我们靠港的时候你都没有力气站好？我是看着你的家族的面子上，才给了你这份差事。别让我后悔自己的决定。"
D.Strings[20249]="欢迎上船，$c。放下行李，享受你的旅程吧。在紫色公主号上，我们希望您心情愉快。如果你在船上有什么需要的话，船舱里有售货机可以为您服务。"
D.Strings[20250]="娱乐是让船员保持工作效率的重要手段。心情轻松了，他们的表现才会更好。"
D.Strings[20251]="船长真是太明理啦！我们在靠港后可以去放松一下！那是我最向往的时刻。"
D.Strings[20252]="请让我休息一小会。"
D.Strings[20253]="让我再睡会吧，就五分钟，朋友……"
D.Strings[20254]="我现在很忙。"
D.Strings[20255]="我现在没时间和你闲聊。"
D.Strings[20256]="尽管从格罗姆高营地到幽暗城的航线平淡无奇，但是一路上的风景秀色宜人。可是这并不能成为工作时候睡着的理由。"
D.Strings[20257]="如果我的计算正确的话，敲打这面锣就可以打开那扇门。我知道，这实在太疯狂了，不过说真的，我想这可能是个节约时间的好主意。"
D.Strings[20258]="进来休息一会儿吧，远离灰尘和泥沼吧。"
D.Strings[20259]="准备好。如果我们想进去的话，至少得有3个人帮我。跟着我……"
D.Strings[20260]="根据我的计算，如果我们有足够多的人同时敲锣的话，那么这些门上的封印就会被揭开，这样我们就能进去了。"
D.Strings[20261]="我承认我害怕了。也许这样更好——只有死亡在那里等待着像你们这样的人。"
D.Strings[20262]="牛头人酋长乐队在下一场巡回演出期间会停留在银月城。他们经常在没有练习任务的时候在我上方的阳台上懒洋洋地晒太阳。请随意和他们打招呼吧……他们喜欢被关注的感觉。\n\n我们暂时不需要新的人手，不过你可以时常来看看。谁知道会发生什么？"
D.Strings[20263]="牛头人酋长乐队一定是整个艾泽拉斯最著名的乐队了！"
D.Strings[20264]="我想知道他们会在银月城待多久，真希望他们能在这里表演！"
D.Strings[20265]="如果可以的话，我愿付出一切来找寻一个上台和他们谈话的机会……"
D.Strings[20266]="不要在还未准备好的时候就去战斗，$n。倘若你已经向我们证明了自己的能力……我就可以给你提供一些非常强大的装备。"
D.Strings[20267]="阳湾港是我们的了。凯尔萨斯的走狗们落荒而逃……是时候让他们脱离苦海了！"
D.Strings[20268]="我是牛头人酋长乐队的后勤人员主管。\n\n你知道啦，就是打包、转运、卸货、搭建拆卸舞台、调试灯光效果，所有这类事情。"
D.Strings[20269]="舒维瑟尔是我的一个老朋友了……很有价值。我的意思是指我们的友谊。我以为我已经遗忘了那种感觉，直到我们再次在沙塔斯城相遇。\n\n他最近并不常在提瑞斯法林地，所以我想通过传送宝珠过去，向他问个好。"
D.Strings[20270]="<呀噜咕噜发现自己竟然能听懂你说的话，感到分外震惊。>"
D.Strings[20271]="别紧张。$n是来这里帮忙的，$g他:她;不是恶魔一伙的。"
D.Strings[20272]="只要同心协力，我们一定能逃离这里。你准备好了吗？"
D.Strings[20273]="出发吧！"
D.Strings[20274]="我们已经脱离了危险。我可以自己回去的。"
D.Strings[20275]="感谢你救了我，$r。请转告国王我回来了。"
D.Strings[20276]="嗨，陌生人，过来！"
D.Strings[20277]="这附近要是有人能帮我逃走就好了。"
D.Strings[20278]="为什么要将我强行关押起来啊！你脑子坏了吗！"
D.Strings[20279]="呆在沉闷的洞穴里，还要追随那个疯狂的龙虾人，我实在是受不了了！放我出去！"
D.Strings[20280]="你在干什么，闲逛吗？"
D.Strings[20281]="最好的防守就是进攻，这是尽人皆知的。"
D.Strings[20282]="如果你没法保证自己能活下来，那么再强的武器对你来说也毫无意义，$c。"
D.Strings[20283]="$r，你已经掌握了与我们交流的诀窍，不过这算不了什么。$B$B水塘那边还有大群的冬鳞背叛者等着你去收拾呢。"
D.Strings[20284]="不错，我们需要你这样的人手。向平民联络官报到吧，他会为你分配工作。"
D.Strings[20285]="我倒是能提供适合你的工作机会。向平民联络官报到吧。"
D.Strings[20286]="我还以为人手已经够了，不过好像还有一些空缺。向平民联络官报到吧。"
D.Strings[20287]="很好，你在这块领域算得上是熟练工。立即向平民联络官报到吧，我们需要你这样的人手！"
D.Strings[20288]="我又不是瞎子。我能看到真实的情况！"
D.Strings[20289]="又是来应征士兵的！喏，这是你的剑。去兵营报到吧！"
D.Strings[20290]="别害怕，朋友。这是你的剑和盾。去兵营报到吧。"
D.Strings[20291]="啧啧，瞧你这强壮的胳膊？朋友，前线正需要你这样的勇士。去兵营报到吧。"
D.Strings[20292]="你让我很伤心呢——我得招满分配的名额，你知道吗？你能拿剑吗？去兵营报到好了。"
D.Strings[20293]="似乎我们还需要一名……啊，不对。是七名士兵。希望你擅长使剑——去兵营报到吧。"
D.Strings[20294]="下一位，下一位。"
D.Strings[20295]="下一位！"
D.Strings[20296]="木匠，长官。"
D.Strings[20297]="木匠。"
D.Strings[20298]="造船工，长官。"
D.Strings[20299]="造船工。"
D.Strings[20300]="雇农，大人。"
D.Strings[20301]="雇农，长官。"
D.Strings[20302]="裁缝。"
D.Strings[20303]="裁缝，大人。"
D.Strings[20304]="铁匠。"
D.Strings[20305]="泥瓦匠，长官。"
D.Strings[20306]="矿工。"
D.Strings[20307]="矿工，长官。"
D.Strings[20308]="厨师。"
D.Strings[20309]="厨师，长官。"
D.Strings[20310]="不久前，我来这里观察冬鳞鱼人。我伪装成他们的模样，保持着一定的距离，记录鱼人的日常生活情况。$B$B没过多久，一切都改变了。$B$B考达拉的一场地震引发山崩，附近的洞穴都露了出来。居住在洞穴中的龙虾人开始偷窃冬鳞蝌蚪。鱼人们试图拯救他们的后代，但是一旦他们进入洞穴，就像被转换了心智似的，沦为了龙虾人的走狗。$B$B那些尚未堕落的鱼人撤退到这里，我勉为其难地成为了他们的首领。"
D.Strings[20311]="姆嘎姆嘎国王，我弄丢了你的备用鱼人服。对不起。"
D.Strings[20312]="别担心，$n。我们帮你找到了那件意外丢失的鱼人服。$B$B喏，拿好了，千万要小心哦。再搞丢的话，你还得消灭更多的冬鳞鱼人才能杀回克拉西姆斯的巢穴。我可不愿意让你再费这么大劲。"
D.Strings[20313]="报上你的职业。"
D.Strings[20314]="很好。你的职业是？"
D.Strings[20315]="你的职业？"
D.Strings[20316]="应征者，你以前是做什么工作的？"
D.Strings[20317]="来诺森德之前，你是做什么的？"
D.Strings[20318]="我的兄弟姐妹都发疯了！你能帮我逃离这里吗？"
D.Strings[20319]="没时间闲聊——我有工作要做！"
D.Strings[20320]="你能听懂我说的话？我能听懂你说的！"
D.Strings[20321]="$R，我为什么要和你说话？这堆烂摊子很可能就是拜你们所赐！"
D.Strings[20322]="我们要忙着收集贝壳和消灭逆戟鲸呢。你要么来帮忙，要么就别挡路！"
D.Strings[20323]="Blurglgr murbrgl……开个玩笑，我能听懂你的话。"
D.Strings[20324]="你查明村落里的鱼人发狂的原因了吗？"
D.Strings[20325]="我就知道我们不应该进入洞穴。那里的状况太异常了！"
D.Strings[20326]="总觉得新国王姆嘎姆嘎有什么地方不对劲，但是又说不上来是哪儿有问题"
D.Strings[20327]="我听说你的兄弟加入了占星者？"
D.Strings[20328]="是啊。"
D.Strings[20329]="啧啧，他们给他什么报酬？"
D.Strings[20330]="报酬？哦，他们并不给他任何报酬。"
D.Strings[20331]="什么？那他为什么做这种傻事？"
D.Strings[20332]="我不知道，也许是为了种族的生存，未来的愿景，英勇的事迹之类的东西吧。"
D.Strings[20333]="对我来说这些东西就好似一堆腐烂的陆行鸟蛋一样。"
D.Strings[20334]="是啊，我是永远都不会做这种傻事的。这里的报酬真不错。"
D.Strings[20335]="是啊，我希望下个月就能退休。我在艾泽拉斯海岸边买下了一块地皮，希望能去那里安度晚年。"
D.Strings[20336]="太棒了。这才是生活……"
D.Strings[20337]="凯尔萨斯大人重新激活太阳井还要多久？"
D.Strings[20338]="很快。我听说他聚集了外域所有最强大的法师来帮他召唤。"
D.Strings[20339]="的确，辛多雷是最伟大的种族。"
D.Strings[20340]="是啊，我们将会升华到一个新的高度，并得到萨格拉斯很久以前就承诺给我们的力量。"
D.Strings[20341]="这些愚蠢的凡人们很快就会见识到我们的力量。"
D.Strings[20342]="为了凯尔萨斯和燃烧军团！"
D.Strings[20343]="火焰将在阴影中燃烧！"
D.Strings[20344]="萨洛拉丝向$n施放暗影新星。"
D.Strings[20345]="奥蕾塞丝向$n施放燃烧。"
D.Strings[20346]="好孩子，好孩子。你在这里乖乖的吃吧。"
D.Strings[20347]="$n，你已经能够与冬鳞鱼人沟通了。"
D.Strings[20348]="我的同胞已经醒了。你的努力白费了……"
D.Strings[20349]="太迟了，小东西。迷雾已经逼近。克瓦迪尔回来了……"
D.Strings[20350]="瞧瞧波涛汹涌的大海，潮水高涨的时刻就是你的末日。"
D.Strings[20351]="克瓦迪尔从迷雾中迫近。逃跑吧，趁你还有命在，逃吧。"
D.Strings[20352]="我是阿图伊克，卡玛古的卡鲁亚克氏族酋长。"
D.Strings[20353]="那边过来个什么小东西。不是鱼人吧。"
D.Strings[20354]="上次品尝$r的美味已经是很久之前的事啦。"
D.Strings[20355]="这是什么？你不是冬鳞鱼人！"
D.Strings[20356]="是“姆嘎姆嘎国王”派你来的？我知道他的真面目！"
D.Strings[20357]="铁锭快用光了！所以一块也不能浪费，明白吗？"
D.Strings[20358]="啊！这是谁啊，居然快把锡锭用光了？你们再浪费材料试试，别以为我是女人就不敢踢你们的屁股！"
D.Strings[20359]="干得不错。我们还在不断招募新兵，他们还等着用新武器呢。继续加油！"
D.Strings[20360]="看上去不错嘛。挺好的。"
D.Strings[20361]="还不错。下次你在回火的时候可以试试我教你的窍门。"
D.Strings[20362]="这样不行；冷却之后金属就会变脆。把它们熔了吧，还能做成弹药用用。"
D.Strings[20363]="这就是技术啊！你一定要把其中的窍门告诉我。说定咯？"
D.Strings[20364]="$G爸爸:妈妈;？"
D.Strings[20365]="我能回家了吗？"
D.Strings[20366]="来玩吧！"
D.Strings[20367]="嘘……$r，就在那里！那条死鲸鱼旁边。"
D.Strings[20368]="该死的凯尔萨斯和他的走狗们！我们的一切都没有了，但他们竟然愚蠢到认为我们不会反击。女伯爵莉亚德琳已经给我们找到了一种新的能量源。我们不会坐以待毙。"
D.Strings[20369]="奥蕾塞丝！你的火焰会在我心中燃烧下去！"
D.Strings[20370]="<龙鹰似乎由于附近的骚动而变得狂乱起来。>"
D.Strings[20371]="就差一点！"
D.Strings[20372]="才不要跟陌生人走！"
D.Strings[20373]="呃……$r！"
D.Strings[20374]="你不是我的$g爸爸:妈妈;！"
D.Strings[20375]="对奥格瑞玛的攻击不仅是向兽人宣战，更是对部落的冒犯。这是对我们的侮辱！$B$B巫妖王企图散播恐惧的种子。$B$B这些……$B$B<加尔鲁什指着他周围的防御工事。>$B$B这就是阿尔萨斯一役的战果。$B$B部落决不退缩……"
D.Strings[20376]="<骑上龙鹰前往阳湾港。>"
D.Strings[20377]="你不是我们的同胞。是姆嘎姆嘎国王派你谈判投降条件的吧。走近一些，让我好好看看你。"
D.Strings[20378]="您为什么能允许这个卑鄙的女伯爵莉亚德琳前来谒见？她和她的手下扭曲了圣光，还取笑我们所坚持的一切！"
D.Strings[20379]="容忍，将军。圣光善待所有心怀虔诚的信念来到沙塔斯城的访客。"
D.Strings[20380]="欢迎来到沙塔斯城，女伯爵莉亚德琳。我们在这里等你很久了。"
D.Strings[20381]="阿达尔，感谢您能给我这么一个说话的机会。我知道您的支持者们大多都厌恶我和我的手下对待穆鲁的方式。"
D.Strings[20382]="但我认识到我们走上了一条错误的道路。那个被我们称为王子的男人背叛了我们。因为他对力量的渴望，他派出了魔血精灵攻击我们，还把穆鲁带去了太阳之井。"
D.Strings[20383]="女伯爵莉亚德琳，我们的人民都遭受着凯尔萨斯和他的手下所带来的巨大痛苦。你的人民并不应该为他们曾做过的事情负责，但是如果不做出改变的话，他们必将因此灭亡。"
D.Strings[20384]="穆鲁很久以前就理解了他的角色，他很清楚在他身上会发生些什么。你理解你自己的角色吗？"
D.Strings[20385]="我……我不明白。您——和穆鲁——很久以前就知道会发生这一切？"
D.Strings[20386]="并不是我预言了这一切，而是德莱尼人的领袖维伦："
D.Strings[20387]="“银月之城，充满鲜血与死亡。”"
D.Strings[20388]="“误入夜晚的歧途，役使破碎的圣光。”"
D.Strings[20389]="“饱经磨难，叛徒突现，遮蔽太阳的光芒。”"
D.Strings[20390]="“在最黑暗的时刻，以鲜血铭誓的女伯爵挺身而出，救赎之路重显。”"
D.Strings[20391]="我现在都明白了。从现在起，我不再效忠于逐日者家族的那个背信弃义的王子。"
D.Strings[20392]="在上前线之前，让我们再喝一杯吧？"
D.Strings[20393]="当然好，为什么不呢？"
D.Strings[20394]="我们会和您并肩战斗，阿达尔。"
D.Strings[20395]="老板！把你们最烈的麦酒拿上来。我们就要上前线了。"
D.Strings[20396]="你不会收我们的酒钱，对吧？我们可能回不来了。"
D.Strings[20397]="破碎残阳肯定会因为骑士们的加入而更加强大，女伯爵莉亚德琳。"
D.Strings[20398]="太阳之井战役是你的崭新开始，女伯爵莉亚德琳。沙塔斯城欢迎你和你的追随者们。"
D.Strings[20399]="那就这样吧。我们走了。"
D.Strings[20400]="从没喝过那么差劲的啤酒。"
D.Strings[20401]="我以血骑士的佩剑起誓，击败基尔加丹，恢复银月城昔日的辉煌。"
D.Strings[20402]="当他还是我们所敬仰的凯尔萨斯王子时，我们以为他的力量能引领我们的人民进入一个崭新的时代。"
D.Strings[20403]="我们被包围了……加尔鲁什，敌人正从四面八方涌来。"
D.Strings[20404]="天灾军团如蝗虫一般挥师北下。"
D.Strings[20405]="联盟控制着这个地区唯一一条安全的航道，即便如此，这条航道也面临着随时被致命的迷雾吞噬的危险。"
D.Strings[20406]="唯一能够正常运转的补给港口位于这片大陆的另一端，在被遗忘者手中！"
D.Strings[20407]="无法用地精飞艇运送的物资必须通过航运，横穿整个诺森德才能到我们这里。"
D.Strings[20408]="航道……补给……我快给你烦死了！萨鲁法尔，部落需要的只是勇者无畏的精神罢了！既然我们已经在这片冰原上站稳了脚跟，还有什么能阻挡我们呢！"
D.Strings[20409]="攻城器械、弹药、重型盔甲……没有这些，你打算如何轰开冰冠冰川的城墙？"
D.Strings[20410]="我的计划？你很快就会明白的！"
D.Strings[20411]="瞧……我们已经开辟出了一条航道。"
D.Strings[20412]="不仅如此……"
D.Strings[20413]="这就是你所谓的计划吗！"
D.Strings[20414]="加尔鲁什，你的脾气和你父亲简直一模一样。总是这么暴躁……既暴躁又卤莽。"
D.Strings[20415]="想学习铭文吗？"
D.Strings[20416]="你脑子里只想着战争与杀戮，完全不考虑后果。"
D.Strings[20417]="别跟我谈什么后果，老家伙。"
D.Strings[20418]="加尔鲁什，我和你的父亲都饮下了恶魔领主的鲜血。玛诺洛斯的诅咒同样在我的血脉里流淌。"
D.Strings[20419]="我也曾征战沙场，令敌人心胆俱裂。"
D.Strings[20420]="格罗姆付出了生命的代价，将我们从诅咒中解放出来，但他无法让我们忘记那段可怕的岁月。"
D.Strings[20421]="他也无法抹去我们犯下的可怕罪行。"
D.Strings[20422]="%s顿了一顿。"
D.Strings[20423]="诅咒解除后的那个严冬，数以百计的兽人士兵都在绝望中迷失了方向，我也不例外。"
D.Strings[20424]="我们终于恢复了理智，是的……终于能够反省自己在燃烧军团驱使下做出的鲁莽行径。"
D.Strings[20425]="最让他们愧疚难安的就是德莱尼小孩的哭喊声……日夜萦绕在耳畔……"
D.Strings[20426]="你去过野猪农场吧？猪长到适合屠宰的年纪时……对，那种惨烈的嘶叫。你听过猪临死前的哀嚎声么……非常刺耳。那些日子对我们这样的老兵来说真是煎熬。"
D.Strings[20427]="你总不会认为那些孩子会永远单纯吧？他们长大之后，就会拿起武器来对付我们了！"
D.Strings[20428]="%s用冷酷的目光盯着加尔鲁什。"
D.Strings[20429]="我指的不仅仅是敌人的孩子……"
D.Strings[20430]="加尔鲁什，我不能坐视不管，任由你带领族人重新踏上那条黑暗的道路。我会在局势无可挽回之前亲手杀了你……"
D.Strings[20431]="%s回到了自己的王座。"
D.Strings[20432]="萨鲁法尔，你能活那么久吗？昔日的阴影难道不会吞噬你的躯壳吗？"
D.Strings[20433]="我可不吃猪肉……"
D.Strings[20434]="%s啐了一口。"
D.Strings[20435]="嘿，士兵！准备出发！"
D.Strings[20436]="部落篝火。"
D.Strings[20437]="你发现了一堆部落篝火。亵渎这堆篝火，扑灭它吧！"
D.Strings[20438]="朋友，我这里有你需要的东西。"
D.Strings[20439]="扑灭部落篝火！"
D.Strings[20440]="联盟篝火。"
D.Strings[20441]="每个人都能享受到仲夏火焰节的乐趣！"
D.Strings[20442]="你发现了一堆联盟篝火。亵渎这堆篝火，扑灭它吧！"
D.Strings[20443]="扑灭联盟篝火！"
D.Strings[20444]="部落已经尝试来偷取我们的火焰了。我希望能以其人之道，还治其人之身。"
D.Strings[20445]="联盟的火焰在熊熊燃烧！"
D.Strings[20446]="我倒想看到联盟来试着偷我们的火焰。"
D.Strings[20447]="部落的火焰永远都不会熄灭！"
D.Strings[20448]="仲夏节是每个夏天里最重要最欢乐的时刻！"
D.Strings[20449]="我很喜欢看仲夏火焰节结束时的烟花表演。"
D.Strings[20450]="恐惧永远是我们最强大的武器。整场战争的胜负就取决于敌人的惊恐与犹疑。那么，对面不知道恐惧为何物的敌人，我们要怎么打呢？$B$B<萨鲁法尔摇了摇头。>$B$B我们不仅要在诺森德与天灾军团作战，还要在他们将我们击溃之前，努力控制住自己的情绪。"
D.Strings[20451]="我们要做好进军索拉查盆地的准备。$B$B别光站在那儿啊，$c。为部落的荣耀而战吧！"
D.Strings[20452]="我还有一堆乱七八糟的事情要处理呢，但是我不会有丝毫抱怨。$B$B如果你还为自己身处部落自豪的话，就来帮我一把！"
D.Strings[20453]="已经……太迟了……"
D.Strings[20454]="为我报仇……"
D.Strings[20455]="谢谢你，$r。我不会忘记你的帮助的。"
D.Strings[20456]="你救了我，$c。谢谢你！"
D.Strings[20457]="谢谢你，$r。要不是你出手帮忙，我已经落得和他们一样的下场了！"
D.Strings[20458]="灵魂在我们身边低语。你听见了吗，$r？"
D.Strings[20459]="这里躺着一具钢腭的车队卫兵的尸体。"
D.Strings[20460]="这里躺着一具钢腭的车队工人的尸体。"
D.Strings[20461]="暮光教派仇视一切我们珍视的东西。我们发誓要尽一切努力保卫这里，不让他们造成的灾祸将这里毁灭，$r。"
D.Strings[20462]="大人，当心！部落计划突破防线来破坏我们的仪式！"
D.Strings[20463]="你的指挥官在想什么呢？居然带领商队穿越我们神圣的墓地！"
D.Strings[20464]="钢腭的灵魂仍在这里徘徊……我能感觉到。"
D.Strings[20465]="怒拳，尽你所能地镇压那些骚动的灵魂。"
D.Strings[20466]="我们要不惜一切代价消灭死去的指挥官的灵魂。"
D.Strings[20467]="只有除掉钢腭，牛头人的灵魂才能安息。"
D.Strings[20468]="就我们和部落的关系而言，这显然不是一个良好的开端。"
D.Strings[20469]="一旦我们开始行动，速度会很快。请你做好准备，帮助我们扫清路上的障碍。"
D.Strings[20470]="博古洛克大王曾许诺会帮助我们。但他派来的重要人物在哪儿呢？"
D.Strings[20471]="$n会帮助我们展开攻击。让祖先的灵魂重归宁静吧！"
D.Strings[20472]="出击！"
D.Strings[20473]="发动伏击。让他们重新安息吧！"
D.Strings[20474]="打起精神来。钢腭就死在前面。"
D.Strings[20475]="喏，瞧见那面旗帜和他的尸体了吧。怎么回事？他朝我们冲了过来！"
D.Strings[20476]="你做得很好。返回北方的兽人要塞吧，告诉博古洛克大王我们成功了！"
D.Strings[20477]="拯救我的灵魂吧，混蛋！"
D.Strings[20478]="我自由了！谢谢你。"
D.Strings[20479]="我真是无地自容。我应该和先知一起死在犸格莫斯的。$B$B让我静一静。"
D.Strings[20480]="附近的气元素躁动不安。小心……它们不会让你安全通过的。"
D.Strings[20481]="对，对，非常好……"
D.Strings[20482]="血王子一定会对此感到满意的……"
D.Strings[20483]="看上去有点脆弱呢……不过无所谓啦……"
D.Strings[20484]="也许我们还需要一些……"
D.Strings[20485]="摧毁"
D.Strings[20486]="搞什么啊？！是谁打扰我享用美餐！"
D.Strings[20487]="我们要为主人收集更多的鲜血……"
D.Strings[20488]="啊，主人的用餐时间快到了……"
D.Strings[20489]="%s装配完毕。"
D.Strings[20490]="爆破倒计时，5……"
D.Strings[20491]="谢谢你救了我！愿好运永远伴随你。"
D.Strings[20492]="谢谢你，$c。我还以为自己再也出不来了。"
D.Strings[20493]="卡斯卡拉会铭记你的恩情。"
D.Strings[20494]="谢谢你，$c。愿微风与海洋保佑你。"
D.Strings[20495]="卡斯卡拉欠你一份情，$c。"
D.Strings[20496]="$c，谢谢你给予我们的帮助，愿先祖永远庇佑你。"
D.Strings[20497]="向我们的先祖致敬。"
D.Strings[20498]="必须恢复墓地的安宁。"
D.Strings[20499]="在完成任务前我就丢了性命。"
D.Strings[20500]="就让我与先祖们一起安息吧。"
D.Strings[20501]="谁也不能阻止我们！"
D.Strings[20502]="和我一起进入坟墓吧！"
D.Strings[20503]="这片神圣的安息之地终于恢复了宁静！"
D.Strings[20504]="傲蹄必胜！"
D.Strings[20505]="那些南方人来到这里后，才发生了这样的事。"
D.Strings[20506]="除非这片土地恢复安宁，否则我不会后退一步的。"
D.Strings[20507]="看到先祖的灵魂无法安息，我非常痛心。$B$B指挥官斯尔加·钢腭这个蠢货居然带领商队穿越这片神圣的墓地，我们必须消灭他那被诅咒的灵魂。"
D.Strings[20508]="$r，你为你的族人赢得了荣耀。再次感谢你帮助我们消灭了钢腭的灵魂。$B$B尽管我们之间有过误会，但我相信我们很快就能成为真正的朋友。"
D.Strings[20509]="英雄，我愿为你效劳！让我们一起干掉这些家伙！"
D.Strings[20510]="我必须返回战歌要塞了。英雄，好好战斗吧！"
D.Strings[20511]="英雄，我必须返回战歌要塞了。愿你浴血沙场，令敌人闻风丧胆！"
D.Strings[20512]="再见，朋友。我必须返回战歌要塞了。"
D.Strings[20513]="再见。我得奉命离开了！"
D.Strings[20514]="是谁打断了我的冥想？"
D.Strings[20515]="灵魂在护佑着你，朋友。我必须返回战歌要塞了。"
D.Strings[20516]="愿先祖与你同在。再见！"
D.Strings[20517]="得救了！谢谢你，我愿意随时为你效劳。"
D.Strings[20518]="让我们一起毁掉天灾军团的采石场！"
D.Strings[20519]="感谢太阳之井，我自由了！"
D.Strings[20520]="燃起复仇的怒火！为了奎尔萨拉斯！为了辛多雷！"
D.Strings[20521]="嗯？我在哪儿？看起来不太妙！逃命要紧！"
D.Strings[20522]="好啊！我自由了！"
D.Strings[20523]="谢了，伙计！"
D.Strings[20524]="摩尔图斯工头一定会大发雷霆的！我得赶紧回去。"
D.Strings[20525]="为什么非要我把洗涤剂放到篮子里？我讨厌洗涤剂！"
D.Strings[20526]="乌格索，瞧。你知道他们是谁吗？"
D.Strings[20527]="嗯。他们看上去像是猪啊。是猪吗？"
D.Strings[20528]="他们……"
D.Strings[20529]="他们是胆小鬼。"
D.Strings[20530]="他们是胆小的猪？"
D.Strings[20531]="不对，儿子。他们是联盟的士兵，是我们不共戴天的敌人。"
D.Strings[20532]="可是他们在怕什么呢？他们到这儿来做什么？"
D.Strings[20533]="因为他们不愿意保卫自己的家园……和家人……"
D.Strings[20534]="他们放弃了抵抗，缴械投降——完全出于自愿。"
D.Strings[20535]="乌格索，他们怕死。"
D.Strings[20536]="%s抓了抓脑袋。"
D.Strings[20537]="我……我不太明白，爸爸。"
D.Strings[20538]="%s挺起胸膛，踮起脚尖。"
D.Strings[20539]="乌格索，这就是真理啊。要么胜利，要么死亡！"
D.Strings[20540]="[不流畅的通用语] 懦夫，听见了吗？死！为自由而死！"
D.Strings[20541]="卡加尼舒！"
D.Strings[20542]="上尉……尼鲁巴尔蛛怪发动了空袭！有好几百只！他们来了……从南面扑向我们的防御线！"
D.Strings[20543]="瞧！他们来了！"
D.Strings[20544]="冷静，士兵！"
D.Strings[20545]="我们必须立即备战……你的预警非常及时。"
D.Strings[20546]="射手！天灾军团朝要塞发动了正面攻击！"
D.Strings[20547]="射手，瞄准目标！"
D.Strings[20548]="尼鲁巴尔蛛怪尝到了贸然来犯的后果！"
D.Strings[20549]="$n，只有你能从卡加尼舒的魔掌中救出我。"
D.Strings[20550]="要不惜一切代价守住内部圣殿！"
D.Strings[20551]="不留活口！让阿尔萨斯去教训他们吧……"
D.Strings[20552]="为了地狱咆哮！为了部落！"
D.Strings[20553]="啊……让怒火燃烧吧！"
D.Strings[20554]="转告因波莉安，我会考虑停战的提议。但是卓恩必须先停止对我们的攻击！"
D.Strings[20555]="你很烦诶。快滚！"
D.Strings[20556]="别……住手！"
D.Strings[20557]="我……投降。只要西米尔不再侵犯我的地盘，我愿意休战。"
D.Strings[20558]="你，立即从我的视线中消失。最好别让我再看见你。"
D.Strings[20559]="我很乐意与部落的军队交手……将他们撕得粉碎……"
D.Strings[20560]="让巫妖王的军队瞧瞧看看这具尸体吧，让他们明白部落绝不手软！"
D.Strings[20561]="士兵，集合！去敌人的尸体上掠夺战利品吧！"
D.Strings[20562]="我要把你锉骨扬灰！"
D.Strings[20563]="你死到临头了！"
D.Strings[20564]="别想逃跑！"
D.Strings[20565]="我要把你碾碎！"
D.Strings[20566]="你竟敢跨进我的地盘！"
D.Strings[20567]="我要让你在痛苦中死去！"
D.Strings[20568]="我要拿你的尸体去喂鱼。"
D.Strings[20569]="噢不……他们禁锢了他的灵魂！"
D.Strings[20570]="在西部的侦察行动中，我们损失了许多出色的双足飞龙。天灾军团对任何可疑的探子都不会手下留情。$B$B幸运的是，我想出了解决办法，虽然这样可能会威胁到骑手的性命。你要知道，在纳萨姆平原的侦察行动中，骑手的生还率已经高达百分之三十了。而我们之前使用双足飞龙的时候，简直可以说是有去无回！"
D.Strings[20571]="亚尼，送我到加尔鲁什码头吧。"
D.Strings[20572]="先知！很高兴能与你重逢！"
D.Strings[20573]="我又活过来了。"
D.Strings[20574]="我得好好休息了。感谢你给予我的帮助。"
D.Strings[20575]="不准伤害母蛾！"
D.Strings[20576]="别碰那些孢子！"
D.Strings[20577]="保护母蛾！"
D.Strings[20578]="$C，我要请你帮个忙。"
D.Strings[20579]="我太可耻了。我应该和先知一起死在犸格莫斯的。"
D.Strings[20580]="%s可以被捕获了。"
D.Strings[20581]="我感觉……有些异样。"
D.Strings[20582]="先知，你还活着！我真是太高兴了。"
D.Strings[20583]="%s笑了笑，坐下来享受这难得的安宁。"
D.Strings[20584]="先知，你还活着！"
D.Strings[20585]="如果你准备好了，我就要进行下一阶段的训练了。"
D.Strings[20586]="格尔基，没有工具我怎么干活！"
D.Strings[20587]="没有合适的工具，我可没办法修理坦克这类构造复杂的装置！"
D.Strings[20588]="有什么消息吗？我们的补给物资快到了吧？"
D.Strings[20589]="我想回家……脱下这身军装，离开部落！"
D.Strings[20590]="给我卖力工作，不然我揍死你们！"
D.Strings[20591]="前哨站的建设尚未完工！万一玛里苟斯和蓝龙军团发动袭击怎么办？"
D.Strings[20592]="快点！我们必须抢在联盟之前进入索拉查盆地！"
D.Strings[20593]="进度落后啊！你们给我卖力点，不然今天的伙食减半！"
D.Strings[20594]="从来没见过这么差劲的苦工！我的训诫靴哪儿去了？"
D.Strings[20595]="要是你再拖拖拉拉的，我就送你去喂狼！"
D.Strings[20596]="你们这帮蠢货就没有一点自尊心吗？要么在战歌要塞的援军抵达之前修好哨站，要么就等死吧！"
D.Strings[20597]="休息五分钟吧。哈哈，开个玩笑！你以为我们是谁，联盟吗？！"
D.Strings[20598]="迷雾已经蔓延到了加尔鲁什码头和帕尔依。我们却还留在这里，真是疯了！"
D.Strings[20599]="菲兹兰克死命地催我，可我手里没有任何工具，这叫我怎么做事啊？！"
D.Strings[20600]="伙计，好啦。这台超级缩小射线枪原型机可供使用啦！"
D.Strings[20601]="你在海岸上目睹的一切并不是天灾军团造成的。事实上他们也害怕这片迷雾——你也瞧见了，连天灾军团都不肯涉足此地。$B$B朋友，迷雾中危机四伏。死亡的气息就萦绕在那片雾气中……$B$B一旦你踏入禁地，就会付出生命的代价。迷雾会吞噬你！$B$B我们还没有见过谁能活着从迷雾中走出来的。"
D.Strings[20602]="燃烧吧，旱鸭子！燃烧吧！"
D.Strings[20603]="我们的征服之旅才刚刚开始……以后有的是乐子。"
D.Strings[20604]="在迷雾中化为灰烬吧！"
D.Strings[20605]="自打我来到这里，就目睹了原本只存在于噩梦中的恐怖景象，但是没有什么能比潜伏在迷雾中的可怕生物更让人毛骨悚然了。$B$B<穆图点了点头。>$B$B就在距离我们几码的雾气中，盘踞着一种名叫克瓦迪尔的噬血生物。迷雾席卷码头时，只有少数的幸运儿捡回了性命。从那之后，但凡进入迷雾的人无一生还。地狱咆哮也因此将这里划为禁区。如果你坚持要进去的话，后果自负……"
D.Strings[20606]="我……你是……$B$B<小穆图浑身颤抖。>$B$B你是来救我的吗？"
D.Strings[20607]="毒蛇之喉被烈焰吞没了！"
D.Strings[20608]="库尔达卡被烈焰吞没了！"
D.Strings[20609]="伯尔之锤被烈焰吞没了！"
D.Strings[20610]="伯尔之砧被烈焰吞没了！"
D.Strings[20611]="你想夺走我的原始精华？来吧，让我瞧瞧你是否像冻石那般坚硬！"
D.Strings[20612]="像你这样的血肉之躯，被冻僵之后就能很轻易地结果你的性命。这就是你的下场。"
D.Strings[20613]="这里不欢迎你。去死吧！"
D.Strings[20614]="你打破了这里的平衡。去死吧！"
D.Strings[20615]="我要购买火炬。"
D.Strings[20616]="退后点！我拿着真正的火焰，它真的会烧伤你！"
D.Strings[20617]="冰冷的迷雾吞噬了码头。"
D.Strings[20618]="拿走他们的衣物。"
D.Strings[20619]="舵手奥拉布斯来对付你了！"
D.Strings[20620]="可悲的蠢货！玛里苟斯的仆人宁死也不会为敌人效劳……"
D.Strings[20621]="啊啊！$c，有什么手段尽管使出来吧！我什么也不会说的！"
D.Strings[20622]="我想找人好好聊聊！"
D.Strings[20623]="你有什么要问我的吗？"
D.Strings[20624]="告诉你吧，我们已经封印了那位尊贵的大法师。就算你能找到她，可钥匙在莎尔兰德手中。你不过是在白费力气！"
D.Strings[20625]="够了！我知道的事都告诉你了。你再逼问下去也问不出什么了！"
D.Strings[20626]="对！打碎那尊恶心的纳迦雕像。"
D.Strings[20627]="让艾萨拉女王带着她的谎言去死吧！"
D.Strings[20628]="我们杀掉了那些海巫，而我们膜拜的神自然会杀死她们的女王！"
D.Strings[20629]="你们应该知道军纪吧。执行执勤任务的步兵禁止饮酒。你们是不是想让将军宰了我？"
D.Strings[20630]="好吧，不喝就是了……但是你别想抢走这些酒！"
D.Strings[20631]="谢谢你，$r。我……我知道如何才能回到父亲身边。请保护我，别让我受到伤害。"
D.Strings[20632]="我能感觉到父亲的光环。他肯定就在这个方向……跟我来，$n。"
D.Strings[20633]="前方的迷雾出现了缺口。我们就要到了！"
D.Strings[20634]="爸爸！爸爸，我得救了！"
D.Strings[20635]="%s拥抱了长者穆图。"
D.Strings[20636]="我的女儿！你终于回来了！"
D.Strings[20637]="$n，好啦。你瞧，这套战歌兽人伪装是不是很棒呢！它拥有完美的幻象效果，还散发着兽人那特有的气味！"
D.Strings[20638]="$n，穆图感谢你。"
D.Strings[20639]="我是不会失败的！这个世界注定要毁灭！"
D.Strings[20640]="不！！！这太过份了！你已经问出大法师的下落了……为什么还不放了我？"
D.Strings[20641]="我所知道的统统告诉你了，$r！你这是在浪费时间……"
D.Strings[20642]="迷雾意味着死亡……它悄无声息，残酷冷酷。"
D.Strings[20643]="怎么啦，$c？你是不是觉得自己相当优秀，不屑与我们为伍了？"
D.Strings[20644]="沃比斯波基，我弄丢了战歌兽人伪装。"
D.Strings[20645]="沃比斯波基，我需要一面战歌旗帜。"
D.Strings[20646]="嘿，伙计们！等一等！"
D.Strings[20647]="你总算露面啦！我很虚弱，怎么都扭不断这些生锈的锁链。$B$B别站在那儿呀！帮我弄断它！"
D.Strings[20648]="呃，嗨？有人吗？"
D.Strings[20649]="嘿！嘿，就是你！我听见你的声音啦！快把我救出去！"
D.Strings[20650]="我还以为他们早把我忘了呢！"
D.Strings[20651]="你瞧，小侏儒不过是想交几个朋友呀，然后“砰！”地一声……接下来发生的事你都知道啦，他被绑起来了！"
D.Strings[20652]="我在这儿呢。我知道你能听见。能帮我弄断这些链子吗？"
D.Strings[20653]="我们来做个交易吧：如果你把我从这儿救出去，我就给你一大笔钱，多到超出你的想象！"
D.Strings[20654]="嘿！这儿呢，犸格莫斯雷加的巢穴里！"
D.Strings[20655]="想什么呢？我可不要当犸格莫斯雷加的开胃菜！把我弄出这个鬼地方！"
D.Strings[20656]="我现在很忙，$c。$B$B我能为你做什么呢？"
D.Strings[20657]="好啦，别浪费时间嘛。我们快走！"
D.Strings[20658]="啊，清新的空气！我能自己返回机场啦。记得转告菲兹兰克我已经平安啦。谢谢你，$n！"
D.Strings[20659]="终于能返回机场啦！谢谢你，我自己回去就行了。记得转告菲兹兰克我已经平安啦！"
D.Strings[20660]="我觉得应该走左边这条路。走吧！"
D.Strings[20661]="恶心的家伙！"
D.Strings[20662]="我是来找你们聊天的，可你们这群没脑子的家伙竟然想杀了我！"
D.Strings[20663]="别想再把我绑起来！"
D.Strings[20664]="我可不是什么开胃小菜！"
D.Strings[20665]="好的坏蛋就是死掉的坏蛋！"
D.Strings[20666]="打够啦！快点解决这帮家伙，我们离开这里吧！"
D.Strings[20667]="嘿！我就在这儿！"
D.Strings[20668]="真不敢相信，我的同胞居然把我忘了。去死吧！"
D.Strings[20669]="哦，亲爱的机场，我再也看不到你那笔直的小跑道了。"
D.Strings[20670]="%s开始吞食无助的科多兽。"
D.Strings[20671]="将军，我向你保证，我能在一个月内招募到两个团的兵力。"
D.Strings[20672]="好吧，将军。如果你改变主意的话，我们会很乐意提供军事援助的。"
D.Strings[20673]="将军，我们的军队主要是由村民和农夫构成的。他们都是很好的人，但是还没有完全摆脱自小养成的偏见和迷信。他们还没有准备好与外来盟友并肩作战。"
D.Strings[20674]="先驱者，我会认真考虑你的建议。同时，我们也会随时向你们咨询的。"
D.Strings[20675]="我们已经被天灾军团包围了。从目前的情况看，我们还能坚持一段时间。但这将是一场你死我活的战斗。"
D.Strings[20676]="我们别无选择，只能发动进攻。我知道局势对我们不利，但是牦牛人绝不能坐以待毙。"
D.Strings[20677]="就算是死，我也要紧握沾满敌人鲜血的战斧！"
D.Strings[20678]="囚犯的鲜血都快抽干啦。马上给我抓些俘虏回来！"
D.Strings[20679]="我们得尽快塞满这些牢笼，否则玛里苟斯就会察觉！"
D.Strings[20680]="我需要更多的俘虏！将艾泽拉斯世界那些毫无节制的施法者都干掉！别停手！"
D.Strings[20681]="往这些牢笼里塞满法师！这是玛里苟斯的命令！"
D.Strings[20682]="我不会让将士们为了所谓的“荣耀”白白送命。如果没人能活下来，那么为生存而战还有什么意义呢？"
D.Strings[20683]="杜尔姆，战争看来是不可避免的。但首先，我们得找到扭转局势的法子。埃恩雷，你有什么提议吗？"
D.Strings[20684]="我们的先祖懂得如何扰乱敌人的心智。我们可以利用这种能力找出天灾军团的弱点，或是杀死他们的指挥官。没有了首领的指挥，天灾军团很快就会败下阵来。"
D.Strings[20685]="啧啧，卑鄙的阴谋。"
D.Strings[20686]="杜尔姆，你所谓的荣誉又能挽救什么？你的性命？我的性命？还是抚养你长大的盲眼老人玛罕宗父的性命？"
D.Strings[20687]="对死人而言，荣誉还有什么意义。战士可以为了荣耀投身沙场，但酋长要考虑的问题则要多得多。我们决定采取先知埃恩雷的计划，继续保卫村落。"
D.Strings[20688]="慢点说，孩子。我还不熟悉你们的语言。"
D.Strings[20689]="请你小点声，$r。哈玛特老了，她需要休息。"
D.Strings[20690]="该采取行动了。我们必须在天灾军团摧毁我们之前解决他们。"
D.Strings[20691]="这个消耗品已经没用了！不管它了！现在我已经做到了连萨格拉斯都没有做到的事情！我要彻底毁灭这个世界，真正成为燃烧军团的主宰者！末日已经到来啦！让这个世界就此支离破碎吧！"
D.Strings[20692]="凡人，你的灵魂归天灾军团了。"
D.Strings[20693]="埃恩雷，$n将你要的兽皮带回来了。请你赶快把它们拿走，我真是受不了这玩意儿。"
D.Strings[20694]="我会拿走的。怎么能让伟大的酋长被一堆兽皮吓得瑟瑟发抖呢。"
D.Strings[20695]="这是怎么回事呢？！"
D.Strings[20696]="回去做事！我已经摆平了来惹事的家伙。"
D.Strings[20697]="主人需要更多的尸体……"
D.Strings[20698]="打开"
D.Strings[20699]="钥匙已经被我摧毁了！你们那位尊贵的大法师归玛里苟斯了！"
D.Strings[20700]="卑鄙的家伙！以纳沙塔尔的名义，艾萨拉女王会为我报仇的！"
D.Strings[20701]="我就要去见先祖的灵魂了……"
D.Strings[20702]="本来嘛，我们还打算让你多活些时日的。不过我们决定现在就结束你的性命！"
D.Strings[20703]="竟敢打扰我的工作？！胆小鬼，不敢露面吗！"
D.Strings[20704]="我会将我的力量导入宝珠中！准备好！"
D.Strings[20705]="还有人吗？今天的讯问结束了？"
D.Strings[20706]="这是我所能做的一切了！力量现在掌握在你们的手中！"
D.Strings[20707]="别再抱有幻想了！你们不可能赢！"
D.Strings[20708]="有人吗……救命……"
D.Strings[20709]="别让他们把我变成那种畸形的怪物！"
D.Strings[20710]="杀了我……立刻杀了我！"
D.Strings[20711]="我还能逃出去吗……"
D.Strings[20712]="终于自由啦！我要立即返回战歌要塞！"
D.Strings[20713]="非常感谢，陌生人。"
D.Strings[20714]="我需要更多的尸体！马上给我找来！"
D.Strings[20715]="我要将他们都转变成巫妖王的仆从！把尸体都带来吧……"
D.Strings[20716]="把部落成员的尸体交给残忍的瓦雷杜斯吧！他们将被转化成巫妖王的士兵！"
D.Strings[20717]="非常好……"
D.Strings[20718]="对……我的孩子，前往纳萨姆平原吧……"
D.Strings[20719]="瞧，小孩发现了新玩具！水手们，把这个小鬼的玩具抢过来！"
D.Strings[20720]="水手们，让这只蝼蚁见识一下克瓦迪尔的强大力量！"
D.Strings[20721]="水手们，把这只旱鸭子撕成碎片！"
D.Strings[20722]="是，船长！"
D.Strings[20723]="你竟敢挑战奥拉布斯，蠢货！"
D.Strings[20724]="我要将你的灵魂卷入迷雾！"
D.Strings[20725]="让迷雾吞噬你的躯壳吧！"
D.Strings[20726]="啧啧，迷路的小羊羔……"
D.Strings[20727]="我要将你的尸体扔进大海！"
D.Strings[20728]="你还不够利维洛斯塞牙缝的。"
D.Strings[20729]="$r，擅自闯入他人的地盘就是你的不对了。"
D.Strings[20730]="巫妖王将扼杀一切生灵……"
D.Strings[20731]="死亡不过是无尽痛苦的开始。"
D.Strings[20732]="愿圣光保佑你。"
D.Strings[20733]="你的伤很严重，但性命无忧。"
D.Strings[20734]="休息吧，你今天已经全力以赴了。"
D.Strings[20735]="上针，下针。上针，下针……"
D.Strings[20736]="你将成为一只可爱的憎恶。"
D.Strings[20737]="宝贝儿，别担心啦，我们很快就要大功告成了。"
D.Strings[20738]="我需要更多的零件！"
D.Strings[20739]="这种情况叫我如何工作？！"
D.Strings[20740]="不动真格的，就治不好病人。"
D.Strings[20741]="我还需要更多的零件。"
D.Strings[20742]="好啦！"
D.Strings[20743]="快活过来呀！"
D.Strings[20744]="这样没用……你需要更多的零件。"
D.Strings[20745]="啊，很好……送上门来的零件！"
D.Strings[20746]="我建议进行摘除手术！"
D.Strings[20747]="肮脏的生物！"
D.Strings[20748]="维修进度落后了！"
D.Strings[20749]="是不是非要我大开杀戒，你们才能完成维修工事啊！"
D.Strings[20750]="如果被巫妖王发现塔尔拉玛斯出了故障，那我们就完蛋了。"
D.Strings[20751]="快一点啦！我们必须在今天之内起飞，不然巫妖王一定会要了我们的命。"
D.Strings[20752]="这是你的科多兽，托普！"
D.Strings[20753]="科多兽送货上门！"
D.Strings[20754]="哎呀！起作用啦！"
D.Strings[20755]="%s已经痊愈！"
D.Strings[20756]="法师！起飞！"
D.Strings[20757]="路障被清除了！打开牢笼！"
D.Strings[20758]="好啦，$n。交叉手指，虔诚地祈祷好运降临吧！"
D.Strings[20759]="天哪，这玩意儿不行啊！我觉得有点……轻飘飘的。"
D.Strings[20760]="为了达拉然！进攻！"
D.Strings[20761]="联盟军旗现在被放在旗座上。"
D.Strings[20762]="部落军旗现在被放在旗座上。"
D.Strings[20763]="埃霍恩，你的力量再也不会增强了！"
D.Strings[20764]="你的野心永远都不会实现！"
D.Strings[20765]="寒冰之石融化了！"
D.Strings[20766]="菲兹兰克，出了什么事。"
D.Strings[20767]="菲兹兰克，把你的故事再说一遍吧。"
D.Strings[20768]="好吧，坐吧。说来话长。$B$B当我们首次踏足这片冰封地狱时，无畏要塞的阿洛斯将军交给飞行敢死队一项特殊的任务。为了扩展联盟的势力范围，他命令我们建设一座空军基地。$B$B这个小机场就是我们的成果啦。这鬼地方到处都是肮脏的野兽，土地还冻得跟石头一样硬，你知道我们有多不容易吗！但是我们排除万难，在短期内就建成了这座机场！是不是很厉害呀！"
D.Strings[20769]="嗯……为了确保机场的正常运转，我们需要抽取大量的沙砾和石油。这附近的池塘恰好有丰富的储量。$B$B某些沙砾甚至具有魔法属性……你能想象其中的潜在利润吗！？好吧，我就不扯远了。$B$B于是我们抽走大部分池水，在池塘中央修筑了泵站。本来一切都进展得挺顺利的，直到有一天，主管道突然堵塞了。"
D.Strings[20770]="等等。你刚才说什么？"
D.Strings[20771]="不过呢，当时我并不在场，所以接下来发生的事我是后来才知道的。$B$B他们从主管道中扒拉出一些零件来，似乎是机械侏儒的部件！结果，那群“勤奋”的蠢货就擅自将这玩意儿拼接起来了！$B$B从此，我们就与泵站失去了联系。"
D.Strings[20772]="接连几天都没有泵站的消息，我就派了一支侦察队去查看情况。可是他们再也没有回来。$B$B第二天，我又派出一队，结果他们还是跟蒸发了似的。此外，我们还损失了好几架侦察机。$B$B事情到这一步，我不得不派人去了南边寻求支援，让剩余的队员留下来做最坏的打算。我们全力锻造护甲、武器以及机器人，准备全副武装地进军泵站。$B$B几天前，当我们到达那里时，顿时被眼前的情景惊呆了！"
D.Strings[20773]="确实如此，那场面真是难以形容。$B$B泵站的工作人员都不见了踪影，取而代之的是一支名副其实的机器人大军！$B$B他们和侏儒的外形相似，还说什么一直在等我们呢。诡异的是，那些机器人好像真的认识我们。我们被包围了，接着就被拖到了泵站的顶层。$B$B在那里我们见到了他们的首领，并目睹了他对幸存的侏儒所做的坏事！"
D.Strings[20774]="他自称是机甲专家麦卡佐德。我们被押上泵站顶层时，他正忙着将幸存者转换成机械生物！$B$B麦卡佐德热情地欢迎了我们，并解释说他是“大建筑师”的杰作，这位建筑师则是来自奥杜尔的泰坦守护者。$B$B我们这才明白，原来是这家伙堵塞了主管道。他显然出过什么故障，被埋在地底有数千年了吧，却因此重见天日。我们正好将泵站建在他的头顶，也真够“幸运”的。"
D.Strings[20775]="在泵站机械师的帮助下，这家伙“活”了过来。$B$B于是，他打算帮助我们“治疗”所谓的“血肉诅咒”，以此表达他的感激之情。$B$B按照麦卡佐德的说法，正是这种诅咒在逐渐侵蚀泰坦的创造物！换句话说，最初我们都是机械侏儒之类的玩意儿，在经历了数千年的演变之后，才成为有血有肉的生物的！$B$B这简直太荒谬了。"
D.Strings[20776]="这哪里是什么“治疗”啊，而且我也不打算继续听这个机械疯子的胡言乱语，尤其是他还当面屠杀我们的同胞！$B$B你瞧，我们都是心智正常的侏儒……只能选择逃跑！好吧，大多数人都纵身跃下了平台，结果你也看到了。$B$B只有少数幸运儿得以逃生。我们势单力薄，本来就疲于应付北方的猛犸人和东方的天灾军团。如今，部落又在西北方扎营，局势真是糟糕透顶！"
D.Strings[20777]="$n，我们陷入了进退维谷的窘境。$B$B我们根本没有能力应付眼前的种种状况，说实话，我真是心有余而力不足啊。我建议你去找金吉谈一谈。她或许会告诉你接下来要怎么办。$B$B只希望你能在确保我们的安全的同时，处理好这堆烂摊子。"
D.Strings[20778]="你瞧，$n。世界末日很快就会降临。而你，将成为这噩梦的终结者……"
D.Strings[20779]="我们走……"
D.Strings[20780]="就这样？这就是伟大的部落所能召集到的全部人手？"
D.Strings[20781]="我真是搞不懂你这样的人物。英雄……"
D.Strings[20782]="为什么不选择放弃？为什么要执泥于必然的结局？"
D.Strings[20783]="巫妖王是不可战胜的。认命吧。"
D.Strings[20784]="世界即将终结。就·让·它·燃·烧·吧。"
D.Strings[20785]="把$g他:她;带走，准备复活仪式。"
D.Strings[20786]="巫师，在你伤害$n之前，我就会徒手将你干枯的徽记拿过来。"
D.Strings[20787]="$n，你永远不会孤单。"
D.Strings[20788]="你想要毁灭的世界是我们的家园。"
D.Strings[20789]="怎么回事？"
D.Strings[20790]="发现入侵者！立即通报机械守卫！"
D.Strings[20791]="警报！危险！危险！"
D.Strings[20792]="我们将竭尽全力于你抗衡——直到化为尘埃。我们会战斗到最后一刻。"
D.Strings[20793]="危险迫近！开启躲避模式！"
D.Strings[20794]="你这蠢货。"
D.Strings[20795]="通灵领主，你很快就会死在蠢货手中了。我要粉碎你，即便是巫妖王，也无法再复活你！"
D.Strings[20796]="就你？区区一只兽人？也想对抗我……"
D.Strings[20797]="大地之环的进攻开始了。"
D.Strings[20798]="埃霍恩退却了。他的防御变弱了。"
D.Strings[20799]="埃霍恩很快就会重新出现。"
D.Strings[20800]="我……我真不敢相信……萨鲁法尔……我……我很荣幸……能与您并肩作战。"
D.Strings[20801]="朋友，你应该立即返回战歌要塞。地狱咆哮一定很想知道……关于萨鲁法尔的故事。"
D.Strings[20802]="不许对任何人提起我。你们俩听到了吗！"
D.Strings[20803]="你打算带我回无畏要塞吗？"
D.Strings[20804]="你说的话我一个字都听不懂。你跟我走就是了。"
D.Strings[20805]="哼哼！好吧，我出发了！"
D.Strings[20806]="什么？你要把我送回去？！"
D.Strings[20807]="我要把那些机械侏儒炸成碎片！"
D.Strings[20808]="哈，还有什么比出色地完成任务更棒的呢！"
D.Strings[20809]="该去喝上一杯金吉的熔岩巧克力啦！"
D.Strings[20810]="真是航行的好天气！"
D.Strings[20811]="现在该侃一侃?是多么卓越啦。"
D.Strings[20812]="不知道那个粉红色头发的飞行员还在不在附近……"
D.Strings[20813]="长官，我需要一架新的飞行器……"
D.Strings[20814]="墨尔杜将转换器的输出装置修好了！"
D.Strings[20815]="你知道自己在干什么吗？！"
D.Strings[20816]="这台转换器是我们生存的关键。如果修不好它，我们就死定了！"
D.Strings[20817]="要是你不能让这玩意儿正常运转，我们就完蛋了！"
D.Strings[20818]="愚蠢的元素仆从！你和你的主人会付出代价的！"
D.Strings[20819]="金吉，没看见我正在绞尽脑汁地鼓捣这玩意儿吗！"
D.Strings[20820]="我看上去像是修理转换器的专家吗？！至少这玩意儿的输入装置……还能用。"
D.Strings[20821]="你瞧，又不是我让丁奇跑掉的。这玩意儿是她的宝贝……她不费吹灰之力就能让它运转起来的。"
D.Strings[20822]="你真是……一点用都没有！"
D.Strings[20823]="嗯，我觉得似乎是修好了。只要转动仪表盘，……啊噢！"
D.Strings[20824]="我才不要使用这玩意儿呢，你想要测试的话，请便好了。"
D.Strings[20825]="我命令你服从号角持有者的意志！"
D.Strings[20826]="所有人都死了……所有的生灵……"
D.Strings[20827]="谢谢你，$r。我现在就把这个孬种带走。"
D.Strings[20828]="我又变回血肉之躯啦！谢谢你，$c！"
D.Strings[20829]="非常感谢！我以为我再也不能从噩梦中醒来了呢！"
D.Strings[20830]="不要！别动那台转换器……它很可能会出故障！"
D.Strings[20831]="啊……可是……之前的我很完美！"
D.Strings[20832]="我在哪儿？你是谁？为什么我的感觉这么奇怪？"
D.Strings[20833]="麦卡佐德发疯了！你必须立即阻止他！"
D.Strings[20834]="太可怕了！他们全变成了机械！"
D.Strings[20835]="麦卡佐德说那是“血肉诅咒”。他发疯了！"
D.Strings[20836]="逃兵的行径让我们倍感羞耻。这种耻辱感是如此强烈，你只有在亲身经历后才能有所体会。这也是乌格索来到这里的原因……他必须得到教训。"
D.Strings[20837]="诺克，我真是难以启齿……逃兵不见了。"
D.Strings[20838]="$n，别让这名逃兵再溜走了。至少我们得维护联盟的颜面。"
D.Strings[20839]="警告：发现$r入侵！"
D.Strings[20840]="启动反击模式。击退入侵者。"
D.Strings[20841]="所有单位注意，$r已进入视线范围。"
D.Strings[20842]="你的行踪已经败露。要么乖乖接受改造，要么就去死。"
D.Strings[20843]="萨索瓦尔将卡雷苟斯逼得狂暴不已！"
D.Strings[20844]="我还有命在！我恢复了血肉之躯！"
D.Strings[20845]="这简直是有史以来最糟糕的发明！"
D.Strings[20846]="我有关于菲兹兰克的重要消息。让路啊！"
D.Strings[20847]="别再跟我提什么转换器了！我已经不是机械侏儒了。"
D.Strings[20848]="我又变回血肉之躯啦。这才是最重要的！"
D.Strings[20849]="千万别进入池塘，那里到处是机器人和机械侏儒！"
D.Strings[20850]="感觉怪怪的。你在重新组装我的时候是不是出了什么差错……"
D.Strings[20851]="立即转告指挥官：麦卡佐德准备向我们发动袭击！我们完蛋了！"
D.Strings[20852]="真是厉害！你有没有觉得四肢无力？很虚弱吗？体内一阵潮热？"
D.Strings[20853]="$n，血孢花粉能削弱犸格莫斯所有猛犸人的力量。"
D.Strings[20854]="谢谢你，达拉然的朋友。"
D.Strings[20855]="我们不能在这里久留……靠近我，我们要转移到安全的地方去。"
D.Strings[20856]="状态：已完成生命物质的收集。"
D.Strings[20857]="蠢货，你真以为你那可笑的创造物能阻止我吗？"
D.Strings[20858]="$r，处处小心啊。血孢平原生活着许多残忍的生物。"
D.Strings[20859]="我们是机械侏儒……放弃抵抗吧。"
D.Strings[20860]="你被诅咒了，我们会治好你的。"
D.Strings[20861]="血肉之躯太脆弱了。我们能让你变得更加完美、强壮……敏捷。"
D.Strings[20862]="我们能移除你身上的诅咒，我们拥有强大的科技。"
D.Strings[20863]="机甲专家能改造你那虚弱的血肉之躯。"
D.Strings[20864]="今天，北风苔原是我们的。明天，全世界都是我们的！"
D.Strings[20865]="让我们移除你身上的诅咒吧！"
D.Strings[20866]="我们能让你变得完美。"
D.Strings[20867]="开始维修。"
D.Strings[20868]="长官，向您报到！"
D.Strings[20869]="以海象人的名义起誓，我要为族人复仇……这帮凶手将帕尔依烧得精光。"
D.Strings[20870]="我医治过农夫、贵族、商贩和乞丐。我要告诉你一个真理：面对死亡时，我们都一样。"
D.Strings[20871]="托奇！"
D.Strings[20872]="ED-210来啦！"
D.Strings[20873]="我是麦卡佐德的使者。我们会治好你的！"
D.Strings[20874]="闹剧该结束了。一旦我搞定你，麦卡佐德就会治愈你身上的诅咒。"
D.Strings[20875]="如果我献上你的皮，说不定奈辛瓦里会赏我点什么！"
D.Strings[20876]="我猜老赫米特肯定会用得着你的骨头的！"
D.Strings[20877]="还要50只蹄子我就能有新火枪啦！"
D.Strings[20878]="杀杀杀！！！！！"
D.Strings[20879]="今天晚上有肉吃啦！"
D.Strings[20880]="角、角茸、蹄子、尾巴、毛、皮……什么都成！"
D.Strings[20881]="让我们较量一下吧！"
D.Strings[20882]="放弃吧，小鬼！"
D.Strings[20883]="孩子，你是来找我的吗？$n，为什么要杀我呢？我只是想帮忙啊。"
D.Strings[20884]="我再次复苏啦，这样我们就能回到那个完美的时代……泰坦的时代！"
D.Strings[20885]="你的眼神和心跳骗不了我，虽然我能让你永生，但是你还是会杀了我！"
D.Strings[20886]="非常好。事情变成这样真令我难过。我把你们都当作自己的孩子。如果有必要的话，我会杀了你的！"
D.Strings[20887]="你是否心怀虔诚，崇尚正义？如果是，欢迎你与德鲁伊一起为保护动物贡献力量。只要你没有误入歧途，没有伤害过那些与我们共同分享这片天空的生灵，你就是仁德会的朋友。"
D.Strings[20888]="真是怪事！这畜生剥掉了自己的皮！"
D.Strings[20889]="愚蠢的畜生！"
D.Strings[20890]="就差一只，我就能弄齐一套奈辛瓦里牛排刀啦！"
D.Strings[20891]="我想回到大陆去。"
D.Strings[20892]="你想去哪里？"
D.Strings[20893]="%s受到重击，失去了意识。"
D.Strings[20894]="珍珠之母！"
D.Strings[20895]="贝壳礼服到手啦！"
D.Strings[20896]="贝壳吐出了珍珠！"
D.Strings[20897]="这名飞行侦察员未能在空难中生还。"
D.Strings[20898]="寻找飞行员的佩章。"
D.Strings[20899]="你疯了吗？你差点把我们炸上天！等我搞定其他事情再来处理这堆残骸吧。"
D.Strings[20900]="这帮德鲁伊是专程派些小鬼来送死的吗？蛤蜊主宰成全你！"
D.Strings[20901]="你的皮也成啊，反正客户也瞧不出什么差别！"
D.Strings[20902]="%s发出了赞许的叫声！"
D.Strings[20903]="X-51型虚空火箭坐骑"
D.Strings[20904]="宠物饼干"
D.Strings[20905]="地精天气制造机 - 原型机01-B"
D.Strings[20906]="把小鬼放出来！"
D.Strings[20907]="你把我们当傻子吗！你身上沾满了动物的鲜血！"
D.Strings[20908]="刽子手！去死吧！"
D.Strings[20909]="屠夫！凶手！你会付出代价的！"
D.Strings[20910]="实在太可悲了。辛多雷是不会和德莱尼杂种们联合起来的。"
D.Strings[20911]="我们很快就会好好收拾你。"
D.Strings[20912]="血精灵应当在一切为时太晚之前加入我们的行列。"
D.Strings[20913]="你们都在凯尔萨斯王子的掌控之中。"
D.Strings[20914]="快跑吧，败狗们。告诉你们的纳鲁主人，末日就在眼前！"
D.Strings[20915]="你们在岛上发动的可笑攻势毫无价值。很快你们全都会死！"
D.Strings[20916]="太阳之井的力量将会再次被我们掌握！"
D.Strings[20917]="你们应该就像那些恶魔一样听从我们的命令。"
D.Strings[20918]="获得新的指示。按魔导师$n的命令行事。"
D.Strings[20919]="没有找到部署目标。搜索类别：圣殿。方位：阳湾港。"
D.Strings[20920]="魔导师$n是一个伟大的战士，魔导师$n一定会让凯尔萨斯王子感到非常自豪。"
D.Strings[20921]="保护太阳之井免受阿尔萨斯和天灾军团破坏。错误：未找到太阳之井。"
D.Strings[20922]="让我们的火焰在整片大陆上熊熊燃烧吧！"
D.Strings[20923]="你在彩带杆那里跳过舞吗？"
D.Strings[20924]="我羡慕那个家伙玩火炬的技巧。"
D.Strings[20925]="你要向猛犸毁灭者卡奥挑战！？啧啧，来一较高下吧！"
D.Strings[20926]="那么，$n，你想要什么东西？"
D.Strings[20927]="来率先体验一下超级无敌的静电除污器吧！"
D.Strings[20928]="源自破碎残阳的军用高端技术，轻松去除各类顽固污渍！"
D.Strings[20929]="无论是酒渍、泥渍，还是宠物留下的污渍，静电除污器都能将它们清除干净！"
D.Strings[20930]="不要犹豫了！现在订购还能得到我免费赠送的超导聊天铁！"
D.Strings[20931]="啊——各种珍品都在这里！我们专门为有识别能力的冒险者挑选艾泽拉斯世界的宝贝。$B$B既然你来找我谈话了，我想你肯定已经想好要什么了吧。"
D.Strings[20932]="艾泽拉斯英雄传"
D.Strings[20933]="积分兑换"
D.Strings[20934]="穿越黑暗之门"
D.Strings[20935]="外域之火"
D.Strings[20936]="燃烧军团的进攻"
D.Strings[20937]="背叛者的仆从"
D.Strings[20938]="你还有什么其它的促销内容吗？"
D.Strings[20939]="嘿，先驱者，调查进行得怎么样了？如果你在订购期限前购买的话，就有机会得到一块超导聊天铁哦。"
D.Strings[20940]="一切进展顺利，瓦菲雷。你不是要去做些产品示范之类的事情吗？"
D.Strings[20941]="卡奥的三叉戟断成两截，掉在了地上！"
D.Strings[20942]="你知道炼金师可以转化特定的宝石吗？玛尔娜和我讨论过这个问题。$B$B我深信只要能给她造好炼金台，就可以让她发挥自己的才干。这样一来我和她也就可以去制造那些被认为已经失传的宝石了。"
D.Strings[20943]="我们成功了，$n。玛尔娜已经学会一些非常特殊的宝石的转化方法了。我也已经知道了该如何好好利用它们。"
D.Strings[20944]="我们已经在阳湾港取得了全面的胜利！纳鲁祝福着我们！"
D.Strings[20945]="不要害怕，$r。我们有着相同的目标。"
D.Strings[20946]="你是谁？"
D.Strings[20947]="我是蓝龙军团的卡雷苟斯。$B$B我监视太阳之井形成的能量已经有一段时间了，但是现在我意识到，它那可怕的能量也许会导致世界的毁灭！"
D.Strings[20948]="你在这里干什么？"
D.Strings[20949]="我和一个朋友一起赶来，想要从燃烧军团的首领基尔加丹手中营救一位年轻的姑娘。$B$B我们发现凯尔萨斯正在尝试从太阳之井的深处召唤出基尔加丹！$B$B为了这个世界——我们不能让他的计划成功！我的任务就是阻止他们。"
D.Strings[20950]="我们有什么可以帮你的吗？"
D.Strings[20951]="打败凯尔萨斯是一件值得你专心去做的事情。$B$B除此之外，如果你能组织一支军队的话，太阳之井里面还有许多邪恶的家伙需要你去处理。$B$B也许我们会在那里再次相遇。"
D.Strings[20952]="这里不允许你来打扰！"
D.Strings[20953]="我们的理想终将实现！"
D.Strings[20954]="欢迎，$c。你有没有向这团火焰表达你的敬意？$B$B记住：我们的节日火焰在联盟的每一片土地上燃烧，如果你有时间的话，去向它们一一表达你的敬意。$B$B当然部落也点燃了他们自己的火焰，如果你有看到的话，记得去踏灭那些毫无价值的东西。"
D.Strings[20955]="你竟敢挑战北风苔原的领主尼达尔！？"
D.Strings[20956]="你的卤莽会毁了你！"
D.Strings[20957]="看，夏日的烈焰！"
D.Strings[20958]="小心，不要被烧着了！"
D.Strings[20959]="对火焰节满意吗？"
D.Strings[20960]="欢迎！你有没有向这块大陆上的火焰表达你的敬意？"
D.Strings[20961]="这个世界遭受了许多我们肉眼看不到的破坏。甚至是时间的通路都感觉有些异常。"
D.Strings[20962]="你为我们做了很多。我来这里是为了执行一项重要的任务，不过如果你需要前往时光之穴的话，我很乐意带你去那里。"
D.Strings[20963]="送我去时光之穴。"
D.Strings[20964]="在飞行员的尸体上搜寻应急工具包。"
D.Strings[20965]="30只驯鹿蹄子换一把带瞄准镜的步枪？！成交！"
D.Strings[20966]="我不认识你们，但是用10颗珍珠换那个蚌壳头盔似乎很合算！"
D.Strings[20967]="让我直说吧：我用15根猛犸象牙和兰恩做买卖，他给了我一套匕首。我拿这玩意儿来切牛排吗？他怎么能这样？这买卖也太好做了吧？"
D.Strings[20968]="不是吧！30个犀牛头就能换一个犀牛头盔？给我来两个！"
D.Strings[20969]="如果奈辛瓦里一意孤行的话，他很快就会完蛋了！兰恩根本就不知道他在干什么！"
D.Strings[20970]="他居然自称皮草男爵——要我说，他简直是个吸血鬼！我用50张驯鹿皮换回的只是一双老鼠皮制成的冬袜？"
D.Strings[20971]="哈罗德·兰恩被犀牛撞倒了！"
D.Strings[20972]="你想打倒我？可怜虫……等等……那是什么声音？"
D.Strings[20973]="竞技场管理员就在东南面贫民窟的墙边。"
D.Strings[20974]="这些石头应该是最后一批了。我们和耐普图隆部队的合作将会无懈可击。"
D.Strings[20975]="是的，猎潮者会对这项部署非常满意。火焰领主的威力将被削弱。"
D.Strings[20976]="那么你们自己的准备做得怎么样了？冰霜之王会打开通往传送门的道路吗？"
D.Strings[20977]="卡希斯已经告诉我们了。我们已经进入了奴隶围栏，就等你们的冰术师了。"
D.Strings[20978]="盘牙水库的仪式将在埃霍恩完全准备好的时候唤醒它，炎魔之王和冰霜之王的冲突将会对这个世界的根基造成伤害。我们的最终目的终于就要实现了……"
D.Strings[20979]="旗手变得脆弱了！"
D.Strings[20980]="旗手变得更加脆弱了！"
D.Strings[20981]="奈辛瓦里不会停止杀害诺森德的野生动物的，他迟早会再下毒手。你必须保持警惕，$n！$B$B无论如何，不要屈服于任何可能出现的诱惑……这家伙一定会企图迷惑你。坚持住！"
D.Strings[20982]="菲兹克斯，我想我们已经搞定引擎的故障了。"
D.Strings[20983]="保持高温，你这蠢货！"
D.Strings[20984]="这些武器是不会自动锻造好的！再快一点！"
D.Strings[20985]="你管这叫锻造？和我共事的怎么尽是些外行人？！"
D.Strings[20986]="你就抱着那堆垃圾吧。我要在你胸前贴上“失败者”的标签，然后将你塞进箱子里寄给你的母亲。"
D.Strings[20987]="这种劣质货对我们的士兵有用吗？"
D.Strings[20988]="你这个只会捅娄子的蠢货！带上你的行李给我滚！"
D.Strings[20989]="有了这些新零件，我总算可以将这堆东西组装成飞行器了！"
D.Strings[20990]="这引擎怎么不动？莫非是电池出了问题？"
D.Strings[20991]="恐怕要从头来过了。到底要怎么样这玩意儿才能飞起来？"
D.Strings[20992]="菲兹克斯，我告诉过你很多次了，别太相信这架飞行器的稳定性，它迟早会把你搞得半死的。幸好我们还有别的替代物。"
D.Strings[20993]="这次总行了吧……对吧？"
D.Strings[20994]="吃吧，我的兄弟……你需要恢复力量。"
D.Strings[20995]="明天我们就要投身战斗了。今天我们一定要吃得饱饱的。"
D.Strings[20996]="兄弟，我为你自豪。"
D.Strings[20997]="兄弟，吃吧。好好吃一顿，我们可能再也见不到明天了……"
D.Strings[20998]="成功了，多莱安！你看！它动起来了……"
D.Strings[20999]="别想控制我，小$r！"
D.Strings[21000]="我要飞啦！"
D.Strings[21001]="我放弃了！我受够地精的这些小玩意了！"
D.Strings[21002]="冰霜之王赢了。"
D.Strings[21003]="我们要讨论什么呢？"
D.Strings[21004]="这些工具全是废物！"
D.Strings[21005]="你还指望我们能靠这些东西造出什么来？！"
D.Strings[21006]="他们都在这儿吗？"
D.Strings[21007]="除了一个，其他都在。"
D.Strings[21008]="那就行了。"
D.Strings[21009]="能专心听我说两句吗！"
D.Strings[21010]="你喋喋不休地在讲什么呢？你在谈论扳手，在抱怨硬化精金锭的熔炼标准，还在因为被别的侏儒敲诈了一笔而哭泣……"
D.Strings[21011]="让我们来谈谈要紧的事吧。"
D.Strings[21012]="把晨露酒放下！晨露酒是给技师喝的。"
D.Strings[21013]="你以为我是来找麻烦的？拜托，我才没那么闲。我从奥格瑞玛的诺格机械店出发，走了好远的路才到这里。我是来帮忙的哦。"
D.Strings[21014]="你叫利维尼？"
D.Strings[21015]="对。"
D.Strings[21016]="你还敢自称是技师，你这侏儒杂种？"
D.Strings[21017]="我没有义务来听你胡扯，先生！"
D.Strings[21018]="你们当然不是好伙伴啦，因为你们都被解雇了！这算是个好消息吧。那么，坏消息是，我会给你们一周的时间，根据表现决定是否让你们复职。就从今天晚上开始吧。"
D.Strings[21019]="哦……现在可以专心听我说话了吗？很好，这个月的制造合同里又添加了新内容。"
D.Strings[21020]="如你们所知，头等奖是一架涡轮加速飞行器。有人想知道二等奖是什么吗？"
D.Strings[21021]="二等奖是保险丝。"
D.Strings[21022]="三等奖就是炒鱿鱼！听明白了吗？"
D.Strings[21023]="笑什么？你们手里拿着工具！萨尔花大价钱买了这些工具。把图纸掏出来好好看一看！要是你们不能借助工具造出攻城器械来，你们就是一帮一无是处的蠢货。那样的话，你们就给我滚！坐上地精飞艇马上给我滚！"
D.Strings[21024]="这些工具太差劲了！"
D.Strings[21025]="工具差劲？是你们太差劲了！我干这行已经50年了！"
D.Strings[21026]="你说你叫什么名字？"
D.Strings[21027]="我名叫侏儒情人！你知道这是怎么来的吗？你瞧，你就只能骑着小破独轮车，我胯下却是一只价值5000金币，全副武装的双足飞龙。哼哼，我就叫侏儒情人！"
D.Strings[21028]="永远——在——制造。永远在制造。永远在制造！"
D.Strings[21029]="像你这样能赚大钱的英雄，跑来这里做什么呀？干嘛在失败者身上浪费时间呢？"
D.Strings[21030]="你看见这头科多兽了吗？你·看·见·这·头·科·多·兽·了·吗？！它比你那件工具“库房”值钱多了。你瞧，我是大人物。而你什么都不是。"
D.Strings[21031]="使用这颗宝珠将开启通往纳克萨纳尔的传送门。"
D.Strings[21032]="使用宝珠。"
D.Strings[21033]="这批新工具是加基森赞助的。对你来说，它们像金子一般宝贵。不过你别想得到它们。这样的东西若是给你，相当于丢进垃圾箱啦。这是为技师准备的。只有技师才配得上它！"
D.Strings[21034]="制造攻城器械需要铜球轴承。动作快点，不然就给我滚蛋！"
D.Strings[21035]="使用这颗宝珠将开启通往纳克萨纳尔上层的传送门。"
D.Strings[21036]="使用这颗宝珠将开启返回圣城恩其拉的传送门。"
D.Strings[21037]="安薇娜，你必须觉醒过来！这个世界需要你！"
D.Strings[21038]="你必须清醒过来！变回过去的你，变回你原来的样子！就是现在，安薇娜！"
D.Strings[21039]="安薇娜，我爱你！仔细聆听我的声音！回到我的身边来！只有你才能净化太阳之井！"
D.Strings[21040]="对，安薇娜！投入命运的怀抱吧！"
D.Strings[21041]="永别了，我挚爱的安薇娜。尽管只有我们少数人会记住你，但是你今天的英勇事迹改变了命运的轨迹。曾被玷污的太阳之井又重归纯净。英雄们，千万不要让安薇娜白白地牺牲。"
D.Strings[21042]="我现在只效忠于主人。"
D.Strings[21043]="但我似乎迷失了……，我找不到回去的路。"
D.Strings[21044]="卡雷……卡雷？"
D.Strings[21045]="噩梦结束了！法术被破除了！再见，亲爱的卡雷！"
D.Strings[21046]="啊啊啊！太阳之井的能量……开始……对抗我！你们都做了些什么？你们都做了些什么？？"
D.Strings[21047]="单位进入节能模式。"
D.Strings[21048]="检测到威胁。解除节能模式。"
D.Strings[21049]="发现敌人！你们上去顶住！我去启动魔像！"
D.Strings[21050]="发现敌人。"
D.Strings[21051]="现在让我们释放他们的灵魂，听一听他们要说些什么吧。"
D.Strings[21052]="谢谢你救了我们。我们偶然发现了机甲专家麦卡佐德的零件，并把他重新组装了起来。"
D.Strings[21053]="系统已启动，开始攻击目标。"
D.Strings[21054]="作为感谢，他要为我们“驱除诅咒”，将我们“变回”机械体。"
D.Strings[21055]="他声称泰坦的创造物都中了什么“血肉的诅咒”。他还说侏儒原本都是机械侏儒。"
D.Strings[21056]="他疯了！必须阻止他，否则就迟了！"
D.Strings[21057]="监测数据"
D.Strings[21058]="这消息太可怕了！"
D.Strings[21059]="我绝不容许天灾军团将我们驱逐出这里！我们放弃了一切，准备在诺森德开始新的生活。$B$B我向你保证，我们会拼死抵抗的。"
D.Strings[21060]="召唤冰霜之王埃霍恩。"
D.Strings[21061]="你身后有动静！"
D.Strings[21062]="欢迎你，$n。我是杜尔克特·狼脉，氏族的守护者。"
D.Strings[21063]="石头散发出一阵寒气，冻结住了周围的空气和放置石头的平台。在石头的深处，一道蓝色的光芒跳动着，等待着。"
D.Strings[21064]="把你的手放在石头上。"
D.Strings[21065]="到处都是天灾军团！这真是……一场噩梦！"
D.Strings[21066]="来呀，试试你们的运气吧！"
D.Strings[21067]="等等，朋友们！送这只恶魔下地狱之前，我还有些事要问它。"
D.Strings[21068]="可笑的大蜥蜴！你只有死路一条！"
D.Strings[21069]="哈哈哈！你的魔法太脆弱太可笑了！"
D.Strings[21070]="有点意思，但我还在等待真正的挑战！"
D.Strings[21071]="安薇娜在哪，恶魔？卡雷怎么了？"
D.Strings[21072]="你必须说出他们的下落！"
D.Strings[21073]="说！我可不耐烦了！"
D.Strings[21074]="玛里苟斯大人……我……尽力了……"
D.Strings[21075]="阿尔萨斯以为他手下的几名亡灵渣滓就能将我们赶回东部王国……他会尝到后果的。"
D.Strings[21076]="黑暗的力量正在这片土地上蔓延。$n，睁大眼睛，鼓起勇气吧。"
D.Strings[21077]="阿加麦斯之门被攻破了！"
D.Strings[21078]="洛希多尔之门被击碎了！勇士们，进攻！"
D.Strings[21079]="埃库尼苏之门已经不复存在了！太阳之井就在眼前！"
D.Strings[21080]="我们中的某些人打算逃避兵役。任何时候，好的渔夫总是有用的……将军也得吃饭啊。"
D.Strings[21081]="$g先生:女士;，这边走。"
D.Strings[21082]="你知道诅咒教派的情况吗？"
D.Strings[21083]="%s顺从地哀嚎起来。"
D.Strings[21084]="我有理由相信你参与了信徒的行动。"
D.Strings[21085]="每天都在厨房里做同样的事。要不了多久肯定会厌倦的。"
D.Strings[21086]="差不多到换班的时间了。我好想眯一会儿，你明白我的意思吧？"
D.Strings[21087]="你为诅咒教派效劳多长时间了？"
D.Strings[21088]="好吧……"
D.Strings[21089]="好吧，然后呢？我不会坐以待毙的！"
D.Strings[21090]="总算不用遮遮掩掩了！阿尔萨斯，赐予我力量吧！"
D.Strings[21091]="$c，你还不知道自己招惹到什么人了吧！死神在朝你招手呢！"
D.Strings[21092]="我可以把你传送到其他种族的区域。"
D.Strings[21093]="人类"
D.Strings[21094]="兽人和巨魔"
D.Strings[21095]="矮人和侏儒"
D.Strings[21096]="暗夜精灵"
D.Strings[21097]="亡灵"
D.Strings[21098]="牛头人"
D.Strings[21099]="血精灵"
D.Strings[21100]="德莱尼"
D.Strings[21101]="没钱花了？来，给你5000枚金币。"
D.Strings[21102]="5000金币"
D.Strings[21103]="你可以在我这里寄放你的宠物，而且我可以帮你提高它们的忠诚度。"
D.Strings[21104]="宠物忠诚度"
D.Strings[21105]="虽然玛蒂苟萨的命运不该如此悲惨，你们的所作所为仍然是必须和必要的，不过，这场战争远未结束！"
D.Strings[21106]="存放宠物"
D.Strings[21107]="我欠你们一份情。当我们战胜基尔加丹时，整个世界都会感激你们的。"
D.Strings[21108]="阿尔萨斯曾是万民敬仰的人类王子。他所率领的诺森德远征军遭遇了可怕的命运。$B$B我的哥哥萨萨里安就是军中的一员。"
D.Strings[21109]="我准备好动身啦，杜尔克特。"
D.Strings[21110]="勇士，我会让速度最快的座狼载你前往牦牛村。你准备好之后就告诉我吧。"
D.Strings[21111]="我愿意为部落献出生命！"
D.Strings[21112]="欢迎回来，勇士。"
D.Strings[21113]="很荣幸能和你并肩战斗。"
D.Strings[21114]="Throm-Ka，英雄！"
D.Strings[21115]="有了你的力量和决心，我们一定能获胜！"
D.Strings[21116]="瞧！英雄！"
D.Strings[21117]="瞧！$n！快鞠躬！"
D.Strings[21118]="%s向你欢呼。"
D.Strings[21119]="是，我们不过是一群手无寸铁的矿工、农夫和工匠。可是情况危急时，我们也会赤手空拳地抗争到底，像士兵那样守卫我们的家园。"
D.Strings[21120]="抱歉，但我只跟猎人打交道。"
D.Strings[21121]="抱歉，但我只跟德鲁伊打交道。"
D.Strings[21122]="训练"
D.Strings[21123]="遗忘天赋"
D.Strings[21124]="熄灭了！"
D.Strings[21125]="我可以清除你所有的天赋，这样你就可以重新选择了。$B$B不过每次的价格都会变得越来越贵。"
D.Strings[21126]="确认遗忘天赋"
D.Strings[21127]="抱歉，但我只跟法师打交道。"
D.Strings[21128]="抱歉，但我只跟圣骑士打交道。"
D.Strings[21129]="抱歉，但我只跟牧师打交道。"
D.Strings[21130]="抱歉，但我只跟潜行者打交道。"
D.Strings[21131]="抱歉，但我只跟萨满祭司打交道。"
D.Strings[21132]="抱歉，但我只跟术士打交道。"
D.Strings[21133]="抱歉，但我只跟战士打交道。"
D.Strings[21134]="%s用手掌触摸着地面。"
D.Strings[21135]="我们的命运会如何呢？"
D.Strings[21136]="真的都结束了吗？牦牛人的末日来临了吗？"
D.Strings[21137]="这就是事情的结局？真可怜……"
D.Strings[21138]="跟我们走吧。"
D.Strings[21139]="死亡才是真正的解脱……"
D.Strings[21140]="别再挣扎了……"
D.Strings[21141]="我在这片土地上长大……自幼便学习如何在冰原上狩猎。"
D.Strings[21142]="我……我觉得我不行了……"
D.Strings[21143]="让我喘口气。"
D.Strings[21144]="我好啦。继续吧。"
D.Strings[21145]="想要点什么吗？可想而知……能供你挑选的东西也不多。"
D.Strings[21146]="为国家牺牲是军人的职责。如果将这场战争称为闹剧就算是叛国的话，那我就是一名十足的叛徒了。"
D.Strings[21147]="%s指了指东北方。"
D.Strings[21148]="远处那股烟……啊，是沃图克。他想要告诉我们什么……"
D.Strings[21149]="不……这不可能……"
D.Strings[21150]="冰雾村……但愿不是冰雾村……不！！！快！英雄，跟我来！"
D.Strings[21151]="%s熟练地破译出了烽烟中包含的信息。"
D.Strings[21152]="我现在很忙，$r。让我静一静。"
D.Strings[21153]="出什么事了，$n？我要你护送那位村民撤离，结果呢？"
D.Strings[21154]="很抱歉，我没能完成护送任务，那位村民不幸丧命了。能再给我一次机会吗？我保证不会再让你失望了！"
D.Strings[21155]="快，$n！带这位村民逃离此地，与龙骨荒野的沃图克碰面！"
D.Strings[21156]="别再让我失望了，$n。你要保证带领这位村民安全撤离。"
D.Strings[21157]="巫妖，说话啊！即便你有不死的本事也难逃此劫！"
D.Strings[21158]="沉睡吧……"
D.Strings[21159]="一份完美的标本。"
D.Strings[21160]="放松点，幼龙。"
D.Strings[21161]="很好，这将使我的研究更进一步……"
D.Strings[21162]="新宠物"
D.Strings[21163]="你喜欢什么样的宠物？"
D.Strings[21164]="在我这里可以存放宠物，也可以领取新宠物。"
D.Strings[21165]="蝙蝠"
D.Strings[21166]="野猪"
D.Strings[21167]="腐食鸟"
D.Strings[21168]="豹"
D.Strings[21169]="龙鹰"
D.Strings[21170]="虚空鳐"
D.Strings[21171]="猛禽"
D.Strings[21172]="迅猛龙"
D.Strings[21173]="掠食者"
D.Strings[21174]="蝎子"
D.Strings[21175]="蛇"
D.Strings[21176]="蜘蛛"
D.Strings[21177]="迁跃兽"
D.Strings[21178]="风蛇"
D.Strings[21179]="狼"
D.Strings[21180]="主人……你要我……杀死这名小祭司？让他痛苦地死去，对吗？"
D.Strings[21181]="是的，渺小的弱者……向鲁瑞德求饶吧！"
D.Strings[21182]="你崇拜死亡？死亡就在眼前！"
D.Strings[21183]="阿尔萨斯救了我们——我们完了！"
D.Strings[21184]="死亡骑士……他疯了！"
D.Strings[21185]="祭塔失守了！向神庙撤退！"
D.Strings[21186]="别走神啊。这场战争非比寻常，前线的气氛尤其紧张。$b$b想帮忙的话就打起精神来，让我看看你有多大的本事。"
D.Strings[21187]="求你了……我们只是执行来自纳克萨纳尔的命令啊……我和我的手下都被蒙在鼓里了！"
D.Strings[21188]="求求你，死亡骑士！别让你的手下靠近我！你说什么我都照做啊！"
D.Strings[21189]="发发慈悲吧！你曾经是我们中的一员！你不记得了吗？"
D.Strings[21190]="陛下，我们的教徒已经顺利地混入联盟的地盘并取得了一定的控制权。"
D.Strings[21191]="您赐予我的力量使我能够更好地控制人类的思维。这些祭品就是证据。"
D.Strings[21192]="莉蕾萨！"
D.Strings[21193]="你这个混蛋精灵杂种，你对我的妹妹做了什么！？"
D.Strings[21194]="让我来对付这些入侵者吧。我会将他们的内脏拿去喂蛆。"
D.Strings[21195]="你在这里所取得的进展令人眼前一亮，血之王子。我很满意。"
D.Strings[21196]="这可真是个惊喜，萨萨里安。我已经数月没有听到有关莫格莱尼和其他死亡骑士的消息了。我猜，你是回来重新加入天灾军团的？"
D.Strings[21197]="别让我失望，萨莱因。把这个蠢货的首级带回冰冠冰川，否则就不用回去见我了。"
D.Strings[21198]="我宁愿自行了断。为了你对同胞犯下的罪行，阿尔萨斯，为了你对我犯下的罪行，你会付出代价的！我发誓！"
D.Strings[21199]="那是什么声音？暮光召唤者到了吗？"
D.Strings[21200]="不！现在还不是时候——埃霍恩大人还未得到全部的能量！"
D.Strings[21201]="我好像弄丢了强化奥术牢笼。在你这儿吗？"
D.Strings[21202]="$n，给。$b$b小心点，好吗？"
D.Strings[21203]="引发这次冲突的原因是什么？"
D.Strings[21204]="你无法阻止冰霜之王进入这个世界，凡人。猎潮者的力量将毁灭属于拉格纳罗斯的一切，将你们的土地变成一块冰封的乐园！"
D.Strings[21205]="当埃霍恩出现时，我们能准备好吗？"
D.Strings[21206]="你一定要在我们引导火焰的这段时间内挡住埃霍恩的手下。在我们削弱埃霍恩之前，不要靠近它。"
D.Strings[21207]="攻击！趁埃霍恩的力量被削弱的时候，攻击它的霜冻之心！"
D.Strings[21208]="$r，冰封的地狱在向你招手！跟我们走吧！"
D.Strings[21209]="$n，你别想拿走护命匣！你会为你犯下的罪行付出代价的。"
D.Strings[21210]="局势动荡！$B$B巫妖王率领萨莱因卷土重来，巨龙们纷纷投身魔枢之战，而维库人也在此时再度觉醒。$B$B你们乘坐木船来到严寒的极北之地与他们作战。各方势力互相牵制，形势大乱，使得海象人处于进退维谷的尴尬境地。$B$B眼下，新的邪恶势力又企图利用魔法力量彻底炸毁这片土地。我们必须寻找一处安全的避风港才能继续生存下去。$B$B这两位大使让我挺为难的……$r，你愿意帮助我的族人吗？"
D.Strings[21211]="伙计，我愿意用任何东西来换一碗老萨尔玛·萨丁的杂味炖肉。"
D.Strings[21212]="别指望稀饭和干面包能帮助我们渡过难关。"
D.Strings[21213]="要知道，这份食谱并不是萨丁发明的。"
D.Strings[21214]="这才不是萨尔玛·萨丁发明的食谱。它属于我的母亲。我的父母带着老马布兰契离开西部荒野时，让某个旅行者把这份食谱送给了萨尔玛。"
D.Strings[21215]="我已经准备好对付莎拉苟萨了！"
D.Strings[21216]="是吗？好吧，至少萨丁没有在局势艰难时逃离西部荒野。"
D.Strings[21217]="别拿那种眼神看着我！我知道你们在想些什么，但风暴要塞的失败早就过去了。你们真以为我会把命运交给一个又瞎又粗野又下贱的暗夜精灵杂种？"
D.Strings[21218]="噢，显然不是，我只是利用他而已，他不过是我庞大计划的一个垫脚石！我真正的目标在这里……而且，这一次不会再被你们干扰到了！"
D.Strings[21219]="复仇之炎，燃烧吧！"
D.Strings[21220]="我要让你们的世界……彻底颠覆……"
D.Strings[21221]="主人，赐予我力量。"
D.Strings[21222]="不会让你们好过的。"
D.Strings[21223]="我的死根本算不了什么！主人一定会消灭你们的！你们会溺毙在自己的鲜血中！这个世界将会熊熊燃烧！啊！"
D.Strings[21224]="很高兴能再见到你，$n。"
D.Strings[21225]="不准侮辱我的父母！收回你的话！"
D.Strings[21226]="我偏要说！你的父母都是胆小鬼，你也是，弗布隆！"
D.Strings[21227]="$n，克瓦迪尔生性残忍，可是我不能放弃神圣的卡斯卡拉。只要我们不抛弃灵魂，灵魂就不会抛弃我们。"
D.Strings[21228]="卡斯卡拉遭到攻击！我们必须拖住敌军，直到所有人安全撤离。"
D.Strings[21229]="好吧，我收回我的话！你的父母不是胆小鬼！"
D.Strings[21230]="该死的巨人！如果他们想打仗，那就打吧！"
D.Strings[21231]="很高兴你能站在我的角度考虑问题……"
D.Strings[21232]="欢迎你，$c。你祭拜过这座火堆了吗？$b$b记住：所有部落人民定居的地方，都会有我们的节日之火在那里熊熊地燃烧着。$b$b联盟也一样，在各处都点起了他们自己的火焰。当你看见这些火堆时，不妨亵渎之，对我们会有帮助的。"
D.Strings[21233]="凡人英雄们，很早以前的预言之中就昭示了你们今天的胜利。我那堕落兄弟的凄惨号叫将会响彻整个宇宙——这也会把希望带给那些仍然在反抗着燃烧军团的人们。"
D.Strings[21234]="燃烧军团彻底灭亡的日子又更近了一步，你们再一次将这个世界从火焰中拯救下来，你们应当为此而自豪！"
D.Strings[21235]="这一天标志着一个结束，这一天也宣告了一个全新的开始……"
D.Strings[21236]="你们之前消灭的那只熵魔，曾经是一位高贵的纳鲁，他名叫穆鲁。生前，他一直将代表着光明与希望的能量带给世人。不过，有一段时间，一些迷茫的孩子却囚禁了它，偷取这些能量。"
D.Strings[21237]="我们的傲慢是无法宽恕的。我们竟然加害于一位如此高贵的存在，这样的罪孽永远也无法弥补。"
D.Strings[21238]="幸运的是，我在这位高贵的纳鲁陨落的地方回收了他的火种！在火种中，希望仍然没有消逝，年轻的血精灵。"
D.Strings[21239]="可以吗？"
D.Strings[21240]="凝视它，凡人们，凝视穆鲁这颗依然纯洁无瑕的心。沐浴在这创生的光芒之中吧，就如同在沐浴晨曦一般。"
D.Strings[21241]="很快，其中蕴涵着的光明与希望——将重新构成一个不仅仅只是能量源泉的事物……或许，它们将构成一个国家的灵魂。"
D.Strings[21242]="多么神圣的灵魂！我感觉到……那么博爱……那么高贵……这……不是语言可以形容的……"
D.Strings[21243]="救赎，孩子。它在等待着我们所有人。"
D.Strings[21244]="被放开的矿车在铁轨上移动起来，发出“吱吱”声。"
D.Strings[21245]="别灰心丧气。即使是发生了这样一系列事件，银月城依然会保持强大的。"
D.Strings[21246]="遗忘宠物天赋"
D.Strings[21247]="我可以清除宠物的所有天赋，这样你可以重新教给它。$B$B不过每次的价格都会变得越来越贵。"
D.Strings[21248]="确认遗忘宠物天赋"
D.Strings[21249]="这名年轻的海象人似乎经历过一场激烈的打斗，不像是淹死的。"
D.Strings[21250]="<在尸体上寻找伊斯利鲁克的图腾。>"
D.Strings[21251]="你们只会浪费我的时间！"
D.Strings[21252]="我的渴求是无限的！"
D.Strings[21253]="对，没错，我就是神！"
D.Strings[21254]="不……更多，我还要更多！"
D.Strings[21255]="别打扰我了！"
D.Strings[21256]="我……是……无……"
D.Strings[21257]="这……这可不在计划……之内……"
D.Strings[21258]="噢，天啊，你们真可怕！"
D.Strings[21259]="天啊，你们运气怎么就这么好？"
D.Strings[21260]="现在我可真有点火了。"
D.Strings[21261]="该死的废物！看我亲自解决你们！"
D.Strings[21262]="这就是一个好的开始。"
D.Strings[21263]="我发誓你们还会有更多人躺下的……"
D.Strings[21264]="看样子你们要“灭团”了？"
D.Strings[21265]="“一”这个数字，可真令人感到孤独。"
D.Strings[21266]="一场完胜，绝对的完胜。"
D.Strings[21267]="克莉斯塔萨，我完成了自己的使命。请送我回到永生之盾。"
D.Strings[21268]="节日诗人要我来找你。"
D.Strings[21269]="很高兴你能来。我想你已经很了解我们的火焰了，这些，你需要祭拜……不过，不知道你是否了解敌人的火焰……对于那些，你必须浇灭……去吧，回来以后可以向他领取奖赏。"
D.Strings[21270]="节日博学者要我来找你。"
D.Strings[21271]="$n！我一直在担心你。有事耽搁了吗？"
D.Strings[21272]="希望你已经做好了防范措施……$b$b这里非常危险，如果你出了什么事，我是不会原谅自己的。"
D.Strings[21273]="$n，我们必须尽快阻止玛里苟斯。否则他的阴谋一旦得逞，就会产生毁灭性的后果。"
D.Strings[21274]="在动荡不安的年代，好朋友简直是无价之宝。$b$b保重，$n。尽可能地保护好自己……"
D.Strings[21275]="要不是你出手相助，我肯定已经死在监牢里了。$b$b我怎么都忘不了……"
D.Strings[21276]="别心软！杀光海象人！"
D.Strings[21277]="当我们完成使命后，会设法报答你的救命之恩的。"
D.Strings[21278]="我的力量在逐渐恢复……$b$b很快你就能见识到我真正的实力。"
D.Strings[21279]="战斗吧，克瓦迪尔！将卡斯卡拉夷为平地！"
D.Strings[21280]="海象人还没见识过我们的力量呢！让他们尝尝厉害！"
D.Strings[21281]="噢……$b$b我在哪儿？"
D.Strings[21282]="简言之，就是魔法。$b$b凡人的生命如此短暂，他们从不考虑自己的行为可能会造成怎样的长远影响。$b$b过于活跃的奥术能量严重影响了世界的稳定。如果听之任之的话，艾泽拉斯世界迟早会被毁灭。$b$b对于这一点，我们已经达成了共识。可还没等我们组织起专门的议会，玛里苟斯就擅自采取了行动。$b$b我们别无选择，只能与他作战。"
D.Strings[21283]="玛里苟斯是谁？"
D.Strings[21284]="$r，我们取得了一些进展，但还是太慢了。"
D.Strings[21285]="我们不能失败！艾泽拉斯世界的命运就维系在这脆弱的平衡上……"
D.Strings[21286]="魔法之王玛里苟斯是蓝龙军团的统帅。作为蓝龙守护者，他是艾泽拉斯世界最古老的生物之一。$b$b据说他已经从数千年来的疯狂中觉醒，可是他最近的行为表明他远没有恢复理智。$b$b对于我们的困境，他竟然决定以摧毁艾泽拉斯世界所有施法者的方式来解决。$b$b生命守护者红龙不得不采取行动。$b$b蓝龙军团和红龙军团展开了一场激战，世界的命运，就取决于那脆弱的平衡。"
D.Strings[21287]="莱洛拉斯，很高兴能再见到你。"
D.Strings[21288]="克莉斯塔萨！要不是局势恶劣，我真希望为你举行欢迎仪式。你平安地回来了，命运真是仁慈。"
D.Strings[21289]="你平安地回来了，命运真是仁慈。"
D.Strings[21290]="我们得到了命运的青睐。玛里苟斯遭受了沉重的打击。当他清楚地认识到眼前的局势之后，肯定不甘心龟缩在相对安全的魔枢。"
D.Strings[21291]="玛里苟斯——现身？天大的好机会啊。我这就去召集同胞！"
D.Strings[21292]="当然，女王。再见……"
D.Strings[21293]="莱洛拉斯，让他们做好准备吧。他们从未见识过玛里苟斯的力量。这次行动恐怕也只能暂缓他的计划。"
D.Strings[21294]="%s笑了。"
D.Strings[21295]="再见，莱洛拉斯。"
D.Strings[21296]="$n，耐心点。时机尚未成熟。火焰腾起之后我们再动手……"
D.Strings[21297]="跟紧我，$n。我不能让你受到任何伤害。"
D.Strings[21298]="玛里苟斯！！"
D.Strings[21299]="你的配偶已经完蛋了。下一个就轮到你了！"
D.Strings[21300]="来吧，魔法之王，夺回你亲爱的配偶……"
D.Strings[21301]="……夺回她的尸体吧！"
D.Strings[21302]="跟我来，$n。让我们瞧瞧目前取得的成果。"
D.Strings[21303]="莎拉苟萨？你怎么了？"
D.Strings[21304]="跟我来。这里不安全。"
D.Strings[21305]="入侵者！别让他们进入圣殿！"
D.Strings[21306]="构造体，要不惜一切代价保住我们的主城！"
D.Strings[21307]="战斗吧，孩子们！不要对敌人心软！"
D.Strings[21308]="克莉斯塔萨！你杀死了我的配偶……那就由你来代替她吧！"
D.Strings[21309]="为了领主！为了洛肯！"
D.Strings[21310]="同胞们，消灭岩石的子嗣！"
D.Strings[21311]="够了！你杀死了我的配偶……那就由你来代替她吧！"
D.Strings[21312]="钢铁的暴政到头了！"
D.Strings[21313]="快跑，$n！快！你必须活下去，完成我们未竟的事业……"
D.Strings[21314]="你的主子永远别想征服岩石！"
D.Strings[21315]="洛肯必将失败！"
D.Strings[21316]="我们才不怕你呢。来啊，钢铁的子嗣！"
D.Strings[21317]="啊！我不再是玛里苟斯的奴隶了！所有挑战我的人都要被消灭！"
D.Strings[21318]="我要净化你们！"
D.Strings[21319]="你们的痛楚才刚开始！"
D.Strings[21320]="以基尔加丹的名义！"
D.Strings[21321]="我警告过你们了！"
D.Strings[21322]="我的觉醒已经完成了！你们的死期到了！"
D.Strings[21323]="必须立刻消灭基尔加丹！"
D.Strings[21324]="这个世界危在旦夕！"
D.Strings[21325]="已经来不及了！我的工作马上就要完成了！"
D.Strings[21326]="我绝不会落到……输的……那一边。"
D.Strings[21327]="你的痛苦就是我的欢乐！"
D.Strings[21328]="我就要这么看着你流血！"
D.Strings[21329]="可悲的凡人！"
D.Strings[21330]="没听说过吗？我永远属于赢的一方！"
D.Strings[21331]="很好，我已经把你们玩够了！"
D.Strings[21332]="背叛……憎恨……混乱，这是一切的支柱。"
D.Strings[21333]="痛楚……迷惑……猜忌，这是一切的基石。"
D.Strings[21334]="阴影将在火焰下存在！"
D.Strings[21335]="火焰将你吞噬！"
D.Strings[21336]="萨洛拉丝！"
D.Strings[21337]="你们的好运到此为止了！"
D.Strings[21338]="暗影将你包围。"
D.Strings[21339]="时间，这是你永远也无法拥有的奢侈之物。"
D.Strings[21340]="我……要消失了。"
D.Strings[21341]="我真高兴能在这里看见你，$c。目前太阳之井高地一带的战略状况非常糟糕。"
D.Strings[21342]="报告全部状况，上尉。"
D.Strings[21343]="破碎残阳目前在奎尔丹纳斯岛的外围地域进展非常良好，基尔加丹的部队正被我们逼得节节败退。此外，趁着双方掌握地域的混乱，我直接派一小支侦察部队进入了太阳之井。我的部队目前已经通过了幻日广场，还曾在那附近发现了一小队血精灵，并与之交战，结果，那场战斗很快就变成了一场灾难。"
D.Strings[21344]="发生了什么事？"
D.Strings[21345]="基尔加丹派驻在太阳井之内的卫兵远远比外面这些我们遇到过的要强大。军团将那里面的魔像全部灌入了恶魔能量能，转为他们所用。仅仅只是一只炎刃保卫者就将我派去的小队打得丢盔弃甲，我只好立刻命令他们撤退。我当时推断敌人会立刻将我的部队全部赶出高地区域，可令我吃惊的是，他们没有展开任何追击行动。"
D.Strings[21346]="他们为什么停下来了？"
D.Strings[21347]="不知道，但我对这个结果表示庆幸。他们行动上的迟缓使我有机会派出学者埃尔巴顿救下了许多小队成员。我又派出了一些擅长潜行和匿踪的斥候进去侦察了一下，他们带回了一些很有意思的消息。据说，所有的炎刃保卫者都停止运作了！基尔加丹的军队大概不想浪费它们的能量，只启动了一台炎刃保卫者用于对付我们。如果你和你的朋友想突入其中的话，就请允许我先制订一个进攻计划。"
D.Strings[21348]="非常感谢你的建议。"
D.Strings[21349]="你要充分利用他们那些已经关闭了的炎刃保卫者。如果被炎刃斥候发现的话，我敢肯定那些血精灵会立刻冲向最近的炎刃保卫者旁，试图启动它。你们得立刻冲上去杀了他。消灭了那些血精灵之后，只要你不激活那些保卫者的近距传感器，应该就可以安然通过，不用费力消灭它们了。这可以为你节省无数的时间和资源。"
D.Strings[21350]="塞拉娜上尉命令我协助你们在太阳之井高地一带的行动。"
D.Strings[21351]="目前太阳之井内各道门的状况怎样？"
D.Strings[21352]="第一道门阿加麦斯已经被完全破坏了。基尔加丹手下的两位高级军官萨洛拉丝女王和高阶术士奥蕾塞丝已经暴露在我军的攻势之下。"
D.Strings[21353]="所有三道屏障都在运转中。你可以去阳湾港口找大法师奈苏尔，协助他来解除这些屏障。"
D.Strings[21354]="第一道门阿加麦斯和第二道门洛希多尔都已经被完全摧毁，只剩下第三道门埃库尼苏了。"
D.Strings[21355]="所有挡在你前往太阳之井路上的魔法屏障都已经被摧毁了。前往太阳之井吧！立刻阻止基尔加丹进入这个世界！"
D.Strings[21356]="既然卡雷苟斯已经自由了，你能将我传送到巅峰之台吗？"
D.Strings[21357]="现在萨洛拉丝女王和高阶术士奥蕾塞丝都已经被打败了，你能把我传送到巫女密室吗？"
D.Strings[21358]="我们已经可以直接面对基尔加丹了！你能把我传送到太阳之井旁边吗？"
D.Strings[21359]="你们并不是在孤军奋战！蓝龙军团会帮助你们消灭欺诈者！"
D.Strings[21360]="我又将能量灌入了另一颗宝珠！快去使用它！"
D.Strings[21361]="又有一颗宝珠准备好了！快点行动！"
D.Strings[21362]="我所有的计划都是为了这一刻的到来！"
D.Strings[21363]="集中注意力，不要浪费时间！"
D.Strings[21364]="我的等待太漫长了！"
D.Strings[21365]="要是让我失望的话，就准备接受惩罚吧！"
D.Strings[21366]="抽取她的力量！抽空她，直到她只剩下一具空空的躯壳为止！"
D.Strings[21367]="离毁灭又近了一步！"
D.Strings[21368]="你还能相信谁？"
D.Strings[21369]="敌人就在你们中间！"
D.Strings[21370]="怎么啦？你饿了吗？别担心，我来找燕麦。"
D.Strings[21371]="他们把燕麦放哪儿了呢？"
D.Strings[21372]="嗯……可能在那儿。"
D.Strings[21373]="不对……这里也没有燕麦。"
D.Strings[21374]="你为什么来到太阳之井？"
D.Strings[21375]="你不是一个人来的？"
D.Strings[21376]="玛蒂苟萨与我结伴而行，但是我们在太阳之井走散了。$B$B愿命运庇护她。"
D.Strings[21377]="基尔加丹为什么会对普通的人类女孩感兴趣？"
D.Strings[21378]="$r，安薇娜绝不是“普通”的凡人。那些家伙一旦感知到蕴藏在她体内的强大能量，就会不择手段地想要将她占为己有。$b$b安薇娜曾经救过我，现在是我报恩的时候了。"
D.Strings[21379]="$c，玩得开心吗？护火者负责照看熊熊燃烧的篝火，而我更像是守护火焰节历史的学者。当然，我还负责记录每年节日庆典的情况。到目前为止，一切都进展得很顺利，你认为呢？$b$b$n，你应该知道，火焰节期间燃起的簇簇篝火都蕴藏着与生俱来的能量。我们照看着自己的篝火，但是在敌人的主城深处，也会燃起这样神圣的火焰……"
D.Strings[21380]="$c，欢迎来到我们的营地。你可以在这里休息。"
D.Strings[21381]="这鬼地方什么都没有。"
D.Strings[21382]="我的家人都被残忍地杀害了。连孩子都不能幸免。"
D.Strings[21383]="巫妖王对这片土地所做的一切，足以让他永远在地狱之火中倍受煎熬。"
D.Strings[21384]="我们已经是无家可归的人了。"
D.Strings[21385]="天灾军团是不懂得恐惧的机器，他们只知道摧毁这个世界上所有的生命。"
D.Strings[21386]="被他们称为“地狱咆哮”的那个人恐怕是我们最后的希望了。"
D.Strings[21387]="现在只有部落能救我们了。"
D.Strings[21388]="也许是这样吧……我们的末日终于来了。"
D.Strings[21389]="在我负责警戒时，敌人杀害了我的伙伴。现在我只想着报仇。"
D.Strings[21390]="有机会的话，我们应该加入部落。只要团结起来，天灾军团就如同渣一般。"
D.Strings[21391]="阿尔萨斯……我呸！"
D.Strings[21392]="穿越横贯冰原时我们遭到了通灵师的袭击。在那种情况下，我能干什么呢？"
D.Strings[21393]="面对死亡时选择逃跑也算是胆小鬼吗？"
D.Strings[21394]="失去了牦牛村，生命也不再有意义了。"
D.Strings[21395]="我请求他们给我一个机会，让我证明自己。"
D.Strings[21396]="无论发生什么，我们必须做出统一的决定。"
D.Strings[21397]="再见，亲爱的冰原。"
D.Strings[21398]="啊……好冷啊。"
D.Strings[21399]="水桶！我要洗的衣服呢？"
D.Strings[21400]="我正在洗呢，墨尔森。你想要洗得快一点的话，就自己动手吧。"
D.Strings[21401]="部落会保护牦牛人的。冷静点，朋友。"
D.Strings[21402]="我是一名士兵，水桶。你知道的，是战士……而你是个洗衣工。"
D.Strings[21403]="还是个不合格的洗衣工！记得你把我的战袍洗成什么样了吗？"
D.Strings[21404]="我们是姐妹。牛头人和牦牛人流着相同的血液，现在没有谁能伤害你了。你安全了。"
D.Strings[21405]="加尔鲁什很快就会派出最精锐的军队。他们会代表部落朝你张开温暖的怀抱。"
D.Strings[21406]="牦牛人，你很快就会进入固若金汤的阿格玛之锤。"
D.Strings[21407]="只有那些为正义和真理而战的人才能得到救赎。只要加入我们，你就安全了。"
D.Strings[21408]="那全是你自己的错，墨尔森。现在你该学会将不同颜色的衣服分开洗了吧……"
D.Strings[21409]="水桶，我的战袍被染成了粉红色。粉红色！你说这……"
D.Strings[21410]="我被他们嘲笑了整整一周！别再犯这种错误了！"
D.Strings[21411]="好吧。随你便。"
D.Strings[21412]="%s对特使艾米萨·闪蹄欢呼。"
D.Strings[21413]="%s喜极而泣。"
D.Strings[21414]="%s咆哮着表示赞同！"
D.Strings[21415]="你有毛病吗？那是我的饭菜！"
D.Strings[21416]="现在不得不清洗衣物了。"
D.Strings[21417]="你死定了，水桶！你听见没？你死定了！"
D.Strings[21418]="%s向特使艾米萨·闪蹄致谢。"
D.Strings[21419]="嗨，来点摇滚乐吧！"
D.Strings[21420]="嗨，我是你们的歌迷！来点摇滚乐吧！"
D.Strings[21421]="瞧，伙计们！我也能摇滚起来！"
D.Strings[21422]="哇！我成功地吸引了西格·尼修斯的注意！他刚才对着我笑啦！我敢打赌明年我就能加入这支乐队！"
D.Strings[21423]="萨兰蒂亚挥舞着双手。"
D.Strings[21424]="萨兰蒂亚模仿弹吉他的动作，哼着一首颂扬部落力量的歌曲。"
D.Strings[21425]="感谢灵魂！暴风雪会减慢克瓦迪尔船只的航速！"
D.Strings[21426]="灵魂听见我们的祈祷了！$n，你能感觉到吗？"
D.Strings[21427]="骷髅马面朝着附近那座金字塔形状的建筑物。"
D.Strings[21428]="黄昏，带我去找巫妖的护命匣。"
D.Strings[21429]="%s低声嘟囔着。"
D.Strings[21430]="%s环视四周，显得有些迷惑。"
D.Strings[21431]="%s的眼睛里闪过一丝亮光，但很快又黯淡了。"
D.Strings[21432]="%s被村里发生的恐怖灾难给吓傻了。"
D.Strings[21433]="我知道了。该死！"
D.Strings[21434]="抽取……生命！"
D.Strings[21435]="解……放！"
D.Strings[21436]="无……法……控制。"
D.Strings[21437]="吞……噬。"
D.Strings[21438]="啊，又来了一群小绵羊！"
D.Strings[21439]="死吧，小虫子！"
D.Strings[21440]="你就是一块肉！"
D.Strings[21441]="来呀，挑战我吧！"
D.Strings[21442]="又一场光荣的战斗！"
D.Strings[21443]="我为杀戮而生！"
D.Strings[21444]="这根本算不上真正的挑战。你们去死吧！"
D.Strings[21445]="啊！干得好！现在……有意思了……"
D.Strings[21446]="基尔加丹万岁！所有敌人都要死！"
D.Strings[21447]="这是你的最后一口呼吸！"
D.Strings[21448]="我比以前更强大了！"
D.Strings[21449]="为了主人，杀了你！"
D.Strings[21450]="别再犹豫了！你们的命运就是如此了！"
D.Strings[21451]="基尔加丹……会胜利的！"
D.Strings[21452]="<巴德强作镇静，假装没有听你讲话。你专注地盯着他，发现一滴口水从他的面具下落下。>"
D.Strings[21453]="<巴德来回扭动，用巨魔语念叨着什么。>"
D.Strings[21454]="走开。"
D.Strings[21455]="朋友，我没功夫和你聊天。我需要休息……"
D.Strings[21456]="别担心。部落会保护牦牛人的。但是你必须发血誓效忠酋长。"
D.Strings[21457]="部落能让我参与对抗天灾军团的战争吗？"
D.Strings[21458]="当然。部落的所有成员都有复仇的权力。"
D.Strings[21459]="我愿意与你们结盟，为我死去的族人，为驱逐贪得无厌的天灾军团。我愿意用我的生命向部落起誓。"
D.Strings[21460]="那就跟我念：“Lok'tar ogar！非胜即死——为了这一信念我宣誓效忠部落。这是所有部落战士最神圣最基本的信条。\n\n我自愿将全部身心奉献给伟大的酋长。我愿意无条件服从酋长的意志和命令。\n\n从这一刻起直到永远——为了部落！”"
D.Strings[21461]="Lok'tar ogar！非胜即死——为了这一信念我宣誓效忠部落。这是所有部落战士最神圣最基本的信条。\n\n我自愿将全部身心奉献给伟大的酋长。我愿意无条件服从酋长的意志和命令。\n\n从这一刻起直到永远——为了部落！"
D.Strings[21462]="为了部落！\n\n从箱子里取些装备来武装自己吧，然后前往东边的阿格玛之锤报到。加入部落之后，你的首要任务是要活下去。\n\nLok'tar ogar！"
D.Strings[21463]="来吧，巴德。和冰巨魔较量的时刻来临了！"
D.Strings[21464]="噢，闪闪发光的宝贝！"
D.Strings[21465]="嘿，朋友！带我去看看那些巨魔兄弟呀！"
D.Strings[21466]="朋友，就让你见识一下巨魔的把戏！"
D.Strings[21467]="这些巨魔朋友今天可有乐子了！"
D.Strings[21468]="嘿嘿嘿！这肯定会非常有趣！"
D.Strings[21469]="朋友，你确信我们没走错路？"
D.Strings[21470]="<嗅，嗅>朋友，我能嗅出他们的气味。"
D.Strings[21471]="敲打脑袋就是表达爱意的完美方式。"
D.Strings[21472]="好吧，巴德。去找你的巨魔朋友……"
D.Strings[21473]="非胜即死！为了部落！"
D.Strings[21474]="兄弟，来吧！"
D.Strings[21475]="不对，不对。这里没有巨魔……"
D.Strings[21476]="好啦。什么时候才能找到那些巨魔兄弟呀？"
D.Strings[21477]="$n，太阳井之岛的三座大门已被全部摧毁。$B$B集合你的军队，阻止基尔加丹进入艾泽拉斯世界！"
D.Strings[21478]="%s翻阅着布莱恩的日记，查看最新记录的日志。"
D.Strings[21479]="天哪！日志中提到布莱恩在索尔莫丹深处发现了一块刻有神秘符文的石板！"
D.Strings[21480]="布莱恩写道，正在他尝试破译符文内容时，遭到了巨人和他们的盟友的袭击。"
D.Strings[21481]="他记录下大段已被破译的符文，却没有留下他的翻译。"
D.Strings[21482]="以麦格尼·铜须的名义，我们必须完成他未竟的工作，重铸解读石板的符文钥石！"
D.Strings[21483]="艾瑞丹，我把上古长笛弄丢了，想再要一支。"
D.Strings[21484]="朋友，别伤害我！"
D.Strings[21485]="朋友，这就是巨魔的力量！"
D.Strings[21486]="别大惊小怪的。朋友，你没见过巨魔吗？"
D.Strings[21487]="朋友，我有一种感觉，就是你根本就不知道我那些兄弟在哪儿对不对。"
D.Strings[21488]="算啦。我自己去找他们。"
D.Strings[21489]="我们好像迷路了……"
D.Strings[21490]="孩子，帕尔依的亡魂无法安息。找到纳迦女祭司的下落！"
D.Strings[21491]="裂鞭海岸昔日的荣耀不复存在，我发誓，这些混蛋会为此付出代价！"
D.Strings[21492]="“将回到钢铁与岩石的摇篮。”"
D.Strings[21493]="“以洛肯的名义，摧毁岩石的子孙。”"
D.Strings[21494]="“回到坐落在风暴峭壁的奥杜尔。”"
D.Strings[21495]="“钢铁的后裔，倾听这呼唤吧。赶快前往奥杜尔。”"
D.Strings[21496]="“造物主最伟大的子嗣们，索求你们与生俱来的权力吧。”"
D.Strings[21497]="我们必须保护这些牦牛人，并尽可能地安慰他们。"
D.Strings[21498]="大使，我弄丢了部落的血誓。你能再给我一份吗？"
D.Strings[21499]="这些孩子会活下去的。他们会在关爱中长大，成为坚强的部落勇士。时间会让他们淡忘那些悲惨的过去。"
D.Strings[21500]="亲爱的，一切都会好起来的。"
D.Strings[21501]="我的小天使，你不饿吗？听蒂布雷兹阿姨的话，吃点东西好吗？就吃一点？"
D.Strings[21502]="他会成长为一名勇敢的战士。亲爱的，是不是呀？"
D.Strings[21503]="你想不想像蒂布雷兹阿姨那样，成为一名萨满祭司？"
D.Strings[21504]="$n，再次感谢你为我带来这么好闻的熏香。"
D.Strings[21505]="格里西达，快醒醒。嘿。"
D.Strings[21506]="这里很安全，对吧？他们抓走了乔伊和米克基，我们得躲起来，不能让他们发现。"
D.Strings[21507]="我们已经摆脱那些怪物了！格里西达，他们和我们截然不同。"
D.Strings[21508]="我们是猎人。这里没有狼人。"
D.Strings[21509]="小姑娘，保持警惕！别让他们抓到我们！"
D.Strings[21510]="基尔加丹开始引导黑暗能量。"
D.Strings[21511]="站起来吧！效忠天灾军团吧！"
D.Strings[21512]="你去告诉指挥官，我一刻也呆不下去了！他到底还想不想结盟？！"
D.Strings[21513]="上次会面之后我就被晾在一边！古拉莫什什么时候才能完成仪式？"
D.Strings[21514]="无理！我是节点亲王的代表，古拉莫什居然将我晾在一旁！只有他等我的份儿！"
D.Strings[21515]="玛里苟斯亲自向我保证，指挥家会优先处理此次谈判的所有事宜。让我过去！"
D.Strings[21516]="如果再让我多等一会儿，我就要重新考虑复仇军与蓝龙军团之间的协议了！"
D.Strings[21517]="你不过是个身份卑微的小杂兵！我不能再等了！立刻带我去见古拉莫什！"
D.Strings[21518]="什么？还要等？！"
D.Strings[21519]="你来晚了！协议已经达成。只剩下一些无关紧要的细节。比如……如何处理你！"
D.Strings[21520]="%s吞噬了薰香。好胃口！"
D.Strings[21521]="真是太棒啦！香味中充斥着能量！"
D.Strings[21522]="熊熊燃烧的火炬就应该散发出这样浓烈的香味！"
D.Strings[21523]="%s放声大笑！"
D.Strings[21524]="就是现在！我们的计划生效啦！"
D.Strings[21525]="渺小的凡人，跪下！向炎魔之王拉格纳罗斯的使者致敬！"
D.Strings[21526]="你们都将在火焰中化为灰烬！"
D.Strings[21527]="%s眨了眨眼……"
D.Strings[21528]="啊。我只是在开玩笑……"
D.Strings[21529]="我是部落的成员，我要消灭天灾军团！"
D.Strings[21530]="时局动荡不安，我们却顽强地抵御了天灾军团猛烈的攻势！能成为部落的一员真是荣幸。"
D.Strings[21531]="我怀着必死的信念投身战斗！"
D.Strings[21532]="没人能阻止我复仇！"
D.Strings[21533]="我能感受到体内涌动的能量！"
D.Strings[21534]="你卖这类东西吗？"
D.Strings[21535]="%s被塞吉刀刃上反射的光芒迷惑了。"
D.Strings[21536]="%s盯着停泊的船只，发出急促的叫声。"
D.Strings[21537]="看着我的刀子，蠢货！看着它，告诉我是谁背叛了我的兄弟！"
D.Strings[21538]="能量线被扭曲了，这我知道。我不能再等下去了……去把古拉莫什叫来！"
D.Strings[21539]="湍流之针看上去运转正常嘛。古拉莫什现在一定能抽出时间来谈谈我们的协议吧？"
D.Strings[21540]="朋友，你在看什么呢？"
D.Strings[21541]="嗯……青蛙说你就是叛徒，我的“朋友”。"
D.Strings[21542]="你发现什么情况了吗？"
D.Strings[21543]="元素之魂躁动不安……"
D.Strings[21544]="我把图腾信标弄丢啦，能再要一个吗？"
D.Strings[21545]="你真的想收买欧尔嘉？"
D.Strings[21546]="真搞不懂为什么有些海盗喜欢把财宝埋起来，你看……我就喜欢将它们放在随手可及的地方。"
D.Strings[21547]="大海龟“踏浪者”将从这个港口游往龙骨荒野的莫亚基港口。"
D.Strings[21548]="我要坐大海龟前往莫亚基港口。"
D.Strings[21549]="联盟的蒸汽动力破冰船“北海之矛”将穿越东部王国的海域，开往湿地的米奈希尔港。"
D.Strings[21550]="我要坐船前往莫亚基港口。"
D.Strings[21551]="这里与西部卫戍要塞有船运往来，有时军队和商旅队会搭乘船只，但是大多数时候都是运送急需的补给品。"
D.Strings[21552]="我要坐船前往西部卫戍要塞。"
D.Strings[21553]="莫亚基港口因两只大海龟“踏浪者”和“绿背岛”而闻名。它们往返于乌努比和卡玛古。"
D.Strings[21554]="我要坐大海龟前往乌努比。"
D.Strings[21555]="我要坐大海龟前往卡玛古。"
D.Strings[21556]="想去诺森德，是吧？蒸汽动力船“海怪号”将载你前往北风苔原的无畏要塞。"
D.Strings[21557]="我要坐船前往无畏要塞。"
D.Strings[21558]="想去诺森德的话，就乘坐破冰船“北海之矛”吧。它会载你前往嚎风峡湾的瓦加德。"
D.Strings[21559]="我要坐船前往瓦加德。"
D.Strings[21560]="想去无畏要塞的话，就跳上开往北风苔原的货船吧。他们不介意偶尔捎几名旅客的。"
D.Strings[21561]="嗨！你想念东部王国了吧？如果你想回去的话，“海怪号”正要返回暴风城。那里的气候肯定比这里温暖得多！"
D.Strings[21562]="我要坐船前往暴风城港口。"
D.Strings[21563]="大海龟“绿背岛”将从这个港口游往龙骨荒野的莫亚基港口。"
D.Strings[21564]="嗨。你想回到艾泽拉斯世界吗？搭乘“吻云号”返回提瑞斯法林地吧。"
D.Strings[21565]="我要坐地精飞艇前往提瑞斯法林地。"
D.Strings[21566]="嗨。你可以乘坐“强风号”前往诺森德。她会载你飞往北风苔原的战歌要塞。"
D.Strings[21567]="我要坐地精飞艇前往战歌要塞。"
D.Strings[21568]="嗨，你想去战歌要塞？搭乘“野姑娘号”吧，眨眼工夫就能到。她是诺森德最快的地精飞艇！"
D.Strings[21569]="$r，诺森德等你去开拓。“吻云号”会载你前往嚎风峡湾的复仇港。"
D.Strings[21570]="我要坐地精飞艇前往复仇港。"
D.Strings[21571]="$c，想回家吗？如果你住在卡利姆多的话，“强风号”可以送你一程。她将直接飞往杜隆塔尔。"
D.Strings[21572]="我要坐地精飞艇前往杜隆塔尔。"
D.Strings[21573]="快！快！这些武器必须今天送抵库卡隆先锋营地！"
D.Strings[21574]="如果能用地精将你们统统替换掉，我会很高兴的！别让我失望！"
D.Strings[21575]="阿格玛大王等着我们的好消息呢！我们不能让他失望！"
D.Strings[21576]="别逼我从箱子上跳下来！我会把你痛打一顿的。"
D.Strings[21577]="嗨，你想去复仇港吗？欢迎搭乘“野姑娘号”往返航班，全天24小时服务。"
D.Strings[21578]="嘿，美人儿，塞布坦有两条毯子！为什么不过来一起暖和缓和呢，嗯？"
D.Strings[21579]="看看塞布坦要送你什么！玫瑰赠佳人！"
D.Strings[21580]="除非艾泽拉斯世界的其他巨魔都死绝了！"
D.Strings[21581]="真恶心！！！"
D.Strings[21582]="放开我！"
D.Strings[21583]="我已经心有所属了！你给我滚远点！"
D.Strings[21584]="这个巨魔以为你喜欢上他了！哈哈！"
D.Strings[21585]="别害羞啦。你难道感觉不到爱情之火在燃烧吗？"
D.Strings[21586]="上前线！库卡隆先锋营地需要空中支援！"
D.Strings[21587]="遵命！"
D.Strings[21588]="我已经出发了，长官！"
D.Strings[21589]="空袭冰雾村！让阿努巴尔见识空军的力量！"
D.Strings[21590]="立刻将这个信息告诉加尔鲁什！"
D.Strings[21591]="向天谴之门空投物资！小心驾驶！"
D.Strings[21592]="对新壁炉谷进行空中侦察！注意血色十字军的动向！"
D.Strings[21593]="据说霜之哀伤洞穴有可疑情况！立即去侦察！"
D.Strings[21594]="小毛球，准备好了吗？靠近我，小心这些狼！"
D.Strings[21595]="嗯……有头狼折回来了……"
D.Strings[21596]="他是来抓小毛球的！"
D.Strings[21597]="我们必须冲出去，否则狼群就要来了！"
D.Strings[21598]="噢，不！又来了一头狼，好大！！！"
D.Strings[21599]="不，小毛球！不！"
D.Strings[21600]="噢，小毛球，我们没救了！"
D.Strings[21601]="别朝有光的地方跑，小毛球！"
D.Strings[21602]="小毛球，你竟然没事！谢谢你救了小毛球，太感谢了！"
D.Strings[21603]="你成功释放了自己的灵魂！现在你可以充当我的眼睛了。让我们找出真相。"
D.Strings[21604]="悬赏猎杀部落叛徒！$B$B赏金由高尔特上尉提供。"
D.Strings[21605]="你已经到村子上方了。睁大你的眼睛。"
D.Strings[21606]="开始传送吧，我准备好了！"
D.Strings[21607]="湖床上发生了什么事？有奇怪的能量从那里涌出。"
D.Strings[21608]="欢迎你，$c！希望你没有恐高症！$b$b我为你准备了练习用的降落伞。它们是在紧急着陆时使用的。如果你想要缓缓落地，还不如骑着坐骑随便蹦两下呢。如果你想体验极速快感，就要从高处跳下来，在快到落地时打开降落伞！动作要快！你的反应够快吗？$b$b降落伞的效果只能持续几秒，因此你必须在适当的时机使用它。不知道你能不能掌握其中的诀窍。希望你成功。"
D.Strings[21609]="不……不！我的族人要么变成了亡魂，要么丧失了心智！"
D.Strings[21610]="那是长者玛纳洛的雕像，它注视着你。这是个好兆头！"
D.Strings[21611]="回来吧，$n。如果你的灵魂离开肉体太久的话，可能会回不去的。我们需要好好谈一谈。"
D.Strings[21612]="你好啊，伙计！坐下来喝一杯吧，怎么样？"
D.Strings[21613]="再来两杯好酒，马克。"
D.Strings[21614]="趁他虚弱时发动攻击！杀死基尔加丹！"
D.Strings[21615]="嘘……这里，邮箱旁边。快过来，你没有被跟踪吧。"
D.Strings[21616]="我为你感到骄傲，孩子。"
D.Strings[21617]="你会成为部落出色的战士的。"
D.Strings[21618]="我们要夺回冰雾村，将阿努巴尔赶出我们的家园。"
D.Strings[21619]="最艰难的时刻已经过去了。我们很快就能推翻巫妖王的暴政。"
D.Strings[21620]="放我出去，朋友！"
D.Strings[21621]="你最好祈祷我永远也出不来！"
D.Strings[21622]="我要冲破禁锢我的牢笼，将你们统统送进地狱！"
D.Strings[21623]="我不会屈服的！绝不！"
D.Strings[21624]="大家都到市政厅去！我们带来了一批武器！大家都武装起来，把天灾军团赶走！"
D.Strings[21625]="是时候了！鲁瑞德早就耐不住了！"
D.Strings[21626]="阿尔萨斯的走狗？去死吧！"
D.Strings[21627]="你不会……有好下场的！"
D.Strings[21628]="鲁瑞德和你……应该能够合作的。"
D.Strings[21629]="我一直希望能再次为国王效劳。出于人道精神，一起对抗共同的敌人。$B$B但是我发现有教徒混进了我们中间……而所有证据都表明，纳克萨纳尔就是这场灾难的源头。"
D.Strings[21630]="教徒接到的指令都来自于他们的首领。这家伙也许很快就会出现。$B$B这是个好机会。"
D.Strings[21631]="动手吧，萨萨里安。否则就再也没机会了。"
D.Strings[21632]="萨萨里安！你还活着！"
D.Strings[21633]="我还以为……还以为你已经死了。"
D.Strings[21634]="莉蕾萨……你……你没事吧？"
D.Strings[21635]="我还不能跟你回家，莉蕾萨。我和天灾军团之间的账还没有算清呢。"
D.Strings[21636]="也许你是对的，莉蕾萨。我早已经不再亏欠我的祖国和国王任何东西，可是……我还欠自己一个交代。"
D.Strings[21637]="啊……我感到头晕目眩。"
D.Strings[21638]="别再离我而去了！你想为你的祖国而战，可你的祖国根本不愿意接纳你！他们派你来送死！"
D.Strings[21639]="你的眼神说明了一切……我说服不了你。别再让我听到你的噩耗了……"
D.Strings[21640]="别担心，莉蕾萨。我完成使命后就回去找你。那时，世界上就再也没有任何东西能阻挡我回家的脚步了。"
D.Strings[21641]="我们占领了港口！敌人已经落败，阳湾港属于我们！"
D.Strings[21642]="赶紧逃命吧，朋友！"
D.Strings[21643]="朋友，这里到处都是天灾军团！"
D.Strings[21644]="$n，为什么召唤我？你和这里的巨魔在策划什么阴谋？你想要杀死我，夺取我的力量吗？"
D.Strings[21645]="朋友，各自保命吧！"
D.Strings[21646]="别挡道！"
D.Strings[21647]="达克萨隆要塞失守了！"
D.Strings[21648]="这里到处都是天灾军团！"
D.Strings[21649]="凡人，你犯了个致命的错误……别想逃跑……"
D.Strings[21650]="叛徒！审判之日已经来临，你的死期也到了！我倒要看看你效忠的巫妖王能否让你逃脱命运的审判！死吧！"
D.Strings[21651]="安薇娜的牺牲为我们带来了新的希望。"
D.Strings[21652]="你是卡鲁亚克氏族的朋友？我对此持保留意见。如果你想让我为他们占卜的话，就先证明自己的忠诚吧。"
D.Strings[21653]="我要你做的事也不算太过分。当着我的面跳入深海吧，这样你才能与我的精神融合，以此表达你的诚意。"
D.Strings[21654]="虽说我提出了要求，不过你可以选择跳或是不跳。我给你20秒做决定。"
D.Strings[21655]="$n，你拒绝了我的要求。那么我也拒绝占卜卡鲁亚克氏族的命运。在你鼓起勇气接受挑战之前，别再召唤我！"
D.Strings[21656]="很好，$n。你充分表达了自己的诚意。我会如约告诉你关于卡鲁亚克氏族的命运，请转告他们吧。"
D.Strings[21657]="请你转告卡鲁亚克海象人，逃亡是没有出路的。一旦选择逃亡，他们的灵魂将被诺森德滋生的邪灵毁灭。"
D.Strings[21658]="告诉秘法师，卡鲁亚克氏族必须与部落和联盟并肩战斗，共同抵抗玛里苟斯和巫妖王的军队。"
D.Strings[21659]="你的使命已经达成，游回去吧。尽你所能地帮助他们，$r。"
D.Strings[21660]="嗯？干什么？！走开。"
D.Strings[21661]="如果能制造出新型的空中作战机器，我肯定能在天谴之门大赚一笔。$B$B我们进行过多次尝试，但是效果并不……理想。可别小瞧我的飞行器，一旦我鼓捣出完善的轰炸系统，它就能成为彪悍的战斗机。"
D.Strings[21662]="趁这时候赶紧捞钱啊！我老爸经常说：战争是发横财的绝好机会。"
D.Strings[21663]="站在这尊远古神像前，你产生了某种异样的感觉。"
D.Strings[21664]="数千年来存放预言者之眼的位置如今已是空空如也。"
D.Strings[21665]="从神像脸上取下预言者之眼。"
D.Strings[21666]="朋友，等你的好消息。"
D.Strings[21667]="别浪费时间了，$n。等你的好消息。"
D.Strings[21668]="$n，这真是有趣的发现，不过我对此一头雾水啊。"
D.Strings[21669]="我们都看不懂上面的文字，大概只是某个士兵的日志吧。"
D.Strings[21670]="让我瞧瞧。"
D.Strings[21671]="这是矮人语啊……字迹真是潦草啊，不过我还是看出点眉目来了。"
D.Strings[21672]="布莱恩·铜须？他不是铁炉堡国王的兄弟吗？帕鲁纳，搞错了吧。"
D.Strings[21673]="你想啊，劫持矮人皇室的重要成员做人质，那赎金得多高啊。"
D.Strings[21674]="如果他在这附近的话，我们必须找到他。但是首先，我们需要破译这本日志。"
D.Strings[21675]="来吧，懦夫！尝尝部落的厉害！"
D.Strings[21676]="你竟敢挑战部落？那就来吧……"
D.Strings[21677]="我会把你们全碾碎的！为了部落！"
D.Strings[21678]="来吧！你难逃一死！"
D.Strings[21679]="滚远点，不然我就狠狠揍你一顿！"
D.Strings[21680]="滚出来！我徒手就能将你捏碎！"
D.Strings[21681]="以部落的名义，狠狠地教训他们！"
D.Strings[21682]="阿努巴尔蛛魔无所畏惧，凡人……"
D.Strings[21683]="你将成为我的腹中餐……"
D.Strings[21684]="阿努巴拉克也许用得上你的尸体……"
D.Strings[21685]="美味大餐来啦！去死吧！"
D.Strings[21686]="阿努巴尔蛛魔摧毁了%s！"
D.Strings[21687]="欢迎！想找地方休息的话，我能为你提供食宿服务哦。"
D.Strings[21688]="斥候沃塔肯的直觉是正确的。布莱恩·铜须最近确实造访过索尔莫丹，并在这本日志上记录了他的发现。"
D.Strings[21689]="他趁战争打响前探察了这片废墟，发现了三块刻有预言的符文板。"
D.Strings[21690]="布莱恩并没有记录译文，日志中只提到他在躲避战乱前背下了所有的符文。"
D.Strings[21691]="如果你能破译这些符文板，我们就能找到布莱恩。"
D.Strings[21692]="犸格莫斯碾压者正在行动！"
D.Strings[21693]="犸格莫斯碾压者已经出发！"
D.Strings[21694]="轰炸机已经坠毁！但是飞行员安全跳伞啦！"
D.Strings[21695]="我们只损失了一架飞机！"
D.Strings[21696]="发现幸存者！"
D.Strings[21697]="有位幸存者回来了！"
D.Strings[21698]="让我瞧瞧这本日志都写了些什么。"
D.Strings[21699]="不行。"
D.Strings[21700]="请你耐心点。"
D.Strings[21701]="古拉莫什正在主持仪式。"
D.Strings[21702]="我奉命请你在这里耐心等待。"
D.Strings[21703]="主人很快就会召见你的。"
D.Strings[21704]="很抱歉。上命难违，请你理解。"
D.Strings[21705]="我们要杀死阿尔萨斯！即便是天灾军团，也不能与部落抗衡！"
D.Strings[21706]="你要为此付出代价，$c！"
D.Strings[21707]="这里不欢迎你。滚远点，到别处打劫去吧！"
D.Strings[21708]="我来做示范！把练习用的降落伞包递给我！"
D.Strings[21709]="目前控制组件运转正常！"
D.Strings[21710]="找谁来测试炸弹呢？鹰身人吗？哈哈……等等……那是什么？"
D.Strings[21711]="不！我的机器……我的炸弹！好吧！那些鹰身人死定了！"
D.Strings[21712]="灵魂，屈服于我的意志吧。"
D.Strings[21713]="接受被束缚的命运吧，灵魂！你的任务是保持磨坊运转——保持风力均衡！"
D.Strings[21714]="操纵风力让磨坊保持运转，灵魂！"
D.Strings[21715]="北风！照我说的去做！"
D.Strings[21716]="狂风紧紧地贴着磨坊高速旋转，使周围的树木发出了呻吟声。"
D.Strings[21717]="寒冷的狂风环绕着牦牛人的磨坊，用古卡利姆多语低声诉说着它的怨恨。"
D.Strings[21718]="突然卷起的狂风将风力磨坊的风帆扯得紧紧的。"
D.Strings[21719]="别让他们靠近！"
D.Strings[21720]="爸爸，我让您失望了……"
D.Strings[21721]="阿努布耶坎会……杀了你。"
D.Strings[21722]="能为主人而死，我很荣幸……"
D.Strings[21723]="你的胜利毫无意义。"
D.Strings[21724]="我会再站起来的，变得……更加……强大……"
D.Strings[21725]="你在寻找竞技场管理员吗？他们在城镇之间来回行走，或是呆在主城。$B$B你可以将炉石绑在这儿。我还能将你传送到任意主城去。"
D.Strings[21726]="绑定炉石"
D.Strings[21727]="达纳苏斯"
D.Strings[21728]="埃索达"
D.Strings[21729]="铁炉堡"
D.Strings[21730]="奥格瑞玛"
D.Strings[21731]="银月城"
D.Strings[21732]="暴风城"
D.Strings[21733]="雷霆崖"
D.Strings[21734]="幽暗城"
D.Strings[21735]="将这座村落夷为平地吧！"
D.Strings[21736]="放弃吧，牦牛人！你们不是天灾军团的对手！"
D.Strings[21737]="孩子们，又是新的一天！艾卓-尼鲁布的天灾军团很快就要征服这个世界了！"
D.Strings[21738]="他们对我的族人做了什么……"
D.Strings[21739]="你将为自己的所作所为付出代价，接受先祖的惩罚吧！"
D.Strings[21740]="重生吧，我的兄弟……站起来……再次投入战斗。"
D.Strings[21741]="为了冰雾村！为了牦牛人！"
D.Strings[21742]="别以为你们从此就高枕无忧了！"
D.Strings[21743]="巨大的冰虫张开大嘴，颤抖了一会儿。"
D.Strings[21744]="来和我较量较量吧！"
D.Strings[21745]="我会击败你的！风啊，让我飞翔吧！"
D.Strings[21746]="傲慢的凡人！你死定了！"
D.Strings[21747]="啊！！这不可能！怎么会……"
D.Strings[21748]="嗨！菲兹兰克的飞行员都是王牌中的王牌呀。坚持训练是我们保持领先的秘诀。这其中就包括了跳伞训练。你永远也不知道什么时候会用到降落伞，但是迟早你会用上的。$b$b因此，我们设置了通往塔顶的传送装置。如果你是真正的士兵，就勇敢地拉开降落伞跳下来吧。塔顶有一位军官，负责提供降落伞包。$b$b$c，想要接受训练的话，我就教你如何使用传送装置。喏，你只需要踩在上面就是了。"
D.Strings[21749]="钢铁之王，请在战斗中助我一臂之力！"
D.Strings[21750]="耶！我们赢了！"
D.Strings[21751]="我怎么这么厉害啊？"
D.Strings[21752]="酋长，我们要去侦察西边的虫孔。"
D.Strings[21753]="胜利！"
D.Strings[21754]="撤退！总算不用呆在这里啦！"
D.Strings[21755]="我们很快就会返回牦牛村汇报情况的。"
D.Strings[21756]="瞧，虫孔。台玛，别再往前走啦。我们已经了解到足够多的信息，回去好吗？"
D.Strings[21757]="不行。这样是不够的。我们最好再靠近些，瞧瞧这些虫孔到底有多深。"
D.Strings[21758]="那样的话，我们就必须和蛛魔交手了。"
D.Strings[21759]="%s嘟囔着，不情愿地点了点头。"
D.Strings[21760]="发动攻击！"
D.Strings[21761]="碾碎这些小矮子！"
D.Strings[21762]="可怜虫，我们要杀死你！"
D.Strings[21763]="钢铁之子，助我一臂之力吧！"
D.Strings[21764]="敌人越战越勇！快帮帮我！"
D.Strings[21765]="没有谁能阻止我们完成使命！"
D.Strings[21766]="为洛肯的荣耀而战！"
D.Strings[21767]="蠢货，你替库伦卖命是毫无意义的！"
D.Strings[21768]="去死吧，石头的盟友！"
D.Strings[21769]="帕乌，你好。"
D.Strings[21770]="远行者从帕乌手中接过包裹，迅速将它藏了起来。"
D.Strings[21771]="嗨！我给你带干粮来啦。"
D.Strings[21772]="小心，快去快回吧。我们不能再盲目行事了。"
D.Strings[21773]="%s飞走了。"
D.Strings[21774]="朋友，你不应该朝北航行的！"
D.Strings[21775]="啊，迪诺，我的妹妹。塔辛尼要死了。"
D.Strings[21776]="警告！载具已经离开操纵区。即将关闭。"
D.Strings[21777]="别想赢我！"
D.Strings[21778]="哈鲁克，不！"
D.Strings[21779]="阿努布耶坎被打败了！随便捡一块虫壳碎片，作为你获胜的证明吧！"
D.Strings[21780]="$c，谢谢你，自从收到女儿的来信后，我就一直在关注这件事。$B$B她的牺牲总算不是徒劳的，愿她的灵魂安息。蓝龙军团会付出惨痛的代价的。$B$B我等着这一天！"
D.Strings[21781]="准备上马吧，$n。既然他们不愿意派人护送我，那我就只能指望你了。"
D.Strings[21782]="银溪镇就在西北方。镇上的居民都是猎户。他们熟知这里的地貌，如果能争取到他们的支持，对我们是非常有利的。"
D.Strings[21783]="抄近路吧。小心附近的座狼。"
D.Strings[21784]="镇子就在前面。"
D.Strings[21785]="门口悬挂着尸体……这里的情况很不对劲。"
D.Strings[21786]="嗨！尊贵的瓦里安·乌瑞恩国王委任我为特使，派我来银溪镇商谈结盟事宜。"
D.Strings[21787]="帮助联盟对你们有莫大的好处啊。我们正在招募侦察兵，同时为军队筹备给养。军饷将以金币的形式从国库直接调拨。"
D.Strings[21788]="我们还是回去吧，$n。这帮傻蛋根本就不会意识到他们犯了天大的错误。"
D.Strings[21789]="你最好滚远点，除非你也想尝尝被关进牢笼的滋味……"
D.Strings[21790]="啊？！怎么可能！跑吧！"
D.Strings[21791]="冲我们来了！"
D.Strings[21792]="天哪，又来了。"
D.Strings[21793]="我隐约觉得事情不妙。如果我有个什么闪失，请你返回琥珀松木营地向杜蒙特中尉汇报情况。"
D.Strings[21794]="现在你想要寻求帮助了？我们需要帮助的时候，你在哪儿呢？你知道我们是怎么熬过来的吗？"
D.Strings[21795]="我们完蛋了。我是你的话，就趁现在赶紧离开这里。如果你还能活着回去，那就是走运了。"
D.Strings[21796]="%s朝联盟特使的脚边啐了一口。"
D.Strings[21797]="怎么会……？"
D.Strings[21798]="$c，谢谢你，自从收到兄弟的来信后，我就一直在关注这件事。$B$B他的牺牲总算不是徒劳的，愿他的灵魂安息。蓝龙军团会付出惨痛的代价的。$B$B我等着这一天！"
D.Strings[21799]="尊贵的女士，湍流之针传送器已准备就绪。"
D.Strings[21800]="你做得很好，凯尔多努斯。玛里苟斯一定会对你赞赏有加的。"
D.Strings[21801]="为主人效忠就是我活着的意义。"
D.Strings[21802]="这座暗夜精灵神殿下的能量线正在朝碧蓝巨龙圣地涌动。我们的兄弟很快就能掌握强大的力量，利用它击溃敌人了。"
D.Strings[21803]="凯尔多努斯，解决这场骚乱。将$n的徽记带回来给我。我要用$g他:她;的徽记装饰我的房间。"
D.Strings[21804]="我们已经洞悉了这场针对蓝龙军团的侵犯行动。很快，我就会吸干你体内涌动的生命能量！"
D.Strings[21805]="好吧，孩子。退到我身后去，免得伤到你。"
D.Strings[21806]="仪式大厅，他们本打算在那里将我作为祭品的……"
D.Strings[21807]="是时候阻止这一切了！"
D.Strings[21808]="奇怪。怎么不对劲呢。"
D.Strings[21809]="士兵，阻止天灾军团的行动！随时向我汇报情况。一旦你发现可疑的人物，不管是谁，先杀了再说！"
D.Strings[21810]="记住我说过的话，这帮愚蠢的被遗忘者迟早会毁了我们！"
D.Strings[21811]="你问我的意见？我觉得我们应该趁早杀掉所有的药剂师！"
D.Strings[21812]="部落是为荣耀与战斗而生的。这帮药剂师肯定在干什么不光彩的勾当。"
D.Strings[21813]="我始终留意着这群白痴的一举一动。真是怎么提防都不为过！"
D.Strings[21814]="啊！！蛇！"
D.Strings[21815]="提前开饭了吗？"
D.Strings[21816]="%s向你致谢。"
D.Strings[21817]="离开前，%s从身上剥下一块树皮递给你。"
D.Strings[21818]="%s对你提出的要求感到非常愤怒，朝你发动了攻击！"
D.Strings[21819]="开饭啦！！！"
D.Strings[21820]="如果你要和那些医师打交道的话，千万当心。他们一定在干什么不正常的勾当。"
D.Strings[21821]="朋友，西边那片荒野上都是尸体。如果你还想活命的话，就离开这里！"
D.Strings[21822]="那条冰霜巨龙一降落，我就能杀死她。"
D.Strings[21823]="朋友，别担心。这件事就交给洛坎吧。"
D.Strings[21824]="谢谢你，小个子。"
D.Strings[21825]="我以为再也无法摆脱那个可怕法术的束缚呢！"
D.Strings[21826]="我还以为我死定了呢。谢谢你救了我。"
D.Strings[21827]="符文碎裂之石未能解放符文巨人，只是削弱了它的力量。符文巨人发动了攻击！"
D.Strings[21828]="我已经受够这个地方了。"
D.Strings[21829]="我要去药剂师营地。"
D.Strings[21830]="我要去欧尼瓦营地。"
D.Strings[21831]="你可以走了，小姐。"
D.Strings[21832]="我要去征服堡。"
D.Strings[21833]="我在阿格玛之锤的工作远不止照料兽栏里的动物这么简单。"
D.Strings[21834]="我们谈谈吧，$r。"
D.Strings[21835]="我要去怨毒镇。"
D.Strings[21836]="如果你愿意的话，我还有一项任务要交给你。"
D.Strings[21837]="听着，孩子。交给我解决吧。你站在我身后看着就好啦！"
D.Strings[21838]="再见，孩子！"
D.Strings[21839]="哈里森·琼斯？你不是死在祖阿曼了吗？"
D.Strings[21840]="死？我吗？嘿嘿，还早着呢。那次不过是点小擦伤。"
D.Strings[21841]="我要去琥珀松木营地。"
D.Strings[21842]="我要去龙眠神殿。"
D.Strings[21843]="我要去阿格玛之锤。"
D.Strings[21844]="我要去月溪旅营地。"
D.Strings[21845]="我要去暮冬要塞。"
D.Strings[21846]="我要去弗塔根要塞。"
D.Strings[21847]="我要去群星之墓。"
D.Strings[21848]="我要去无畏要塞。"
D.Strings[21849]="我要去菲兹兰克机场。"
D.Strings[21850]="和纳尔弗谈谈吧。让我们一次性解决这些傻瓜。"
D.Strings[21851]="趁现在！抬起那根木材就跑吧。部落不会打上一辈子仗，眼下正是赚钱的好机会呀！"
D.Strings[21852]="很震撼吧？这些巨人简直是完美的炮灰……呃，是盟友啦。这位就是他们的首领，但他一直拒绝和我谈话。"
D.Strings[21853]="你好，$r。你也是为了躲避巨龙才来到这条峡谷的吧，我们欢迎你啊。但是你要当心那个矮小的家伙……地精就没一个可靠的。"
D.Strings[21854]="只要有足够的钱，我就能征服全世界……"
D.Strings[21855]="这个控制台后面是一大堆碎石块。发动机的声音从地下传来。"
D.Strings[21856]="扳动控制台的操纵杆。"
D.Strings[21857]="你夺走了我的东西，我也要来拿你的！"
D.Strings[21858]="干嘛非得把我惹火呢？"
D.Strings[21859]="你弄疼我了！"
D.Strings[21860]="不许拿我的东西，$r！"
D.Strings[21861]="蠢货！你永远别想逃脱！"
D.Strings[21862]="你竟敢挑衅钢铁的子嗣？"
D.Strings[21863]="迪米特里！安东尼！你们不认识我了吗？别担心，我会让你们的灵魂安息的！"
D.Strings[21864]="我不会让你们的家人看到你们这副模样的！矿工就应该互相照顾啊！"
D.Strings[21865]="朋友们，我会将你们的事迹传播开来的！我要所有人都知道空石矿洞的矿工永远不会说放弃！"
D.Strings[21866]="旅行者，欢迎来到龙眠神殿。$B$B这里供奉着巨龙先祖的遗骸，是巨龙们商谈要事的圣地。$B$B但是最近，蓝龙军团突然对神殿发动攻击，打破了持续数千年的宁静。$B$B带着我们的祝福进入神殿吧，但是请谨记，我们绝不允许任何挑衅行为。"
D.Strings[21867]="你连祭品都没有准备就敢召唤我！"
D.Strings[21868]="$c，你想回去？$B$B我可以派一条幼龙将你安全地送达目的地。"
D.Strings[21869]="嗯，我想返回神殿底层。"
D.Strings[21870]="别来烦我，蠢货！"
D.Strings[21871]="瞧，这孩子以为自己能顺利逃脱呢……你们谁都别想活着离开。"
D.Strings[21872]="杀了我们吧……会有更多的后来者……"
D.Strings[21873]="放弃吧！他的灵魂根本不值得救赎……"
D.Strings[21874]="你犯了个严重的错误……"
D.Strings[21875]="你是不可能摆脱宿命的，明白吗？你不过是个孩子。"
D.Strings[21876]="小姑娘，你才多大？"
D.Strings[21877]="最终，我们都会成为巫妖王的仆从。孩子，这比变成一具腐烂的尸体好多了。"
D.Strings[21878]="你的父亲是个懦夫，萨莎……他没有勇气完成自己的使命。"
D.Strings[21879]="别小瞧我，我也能一箭射中野兽的眉心……而且是在两倍距离开外。"
D.Strings[21880]="我宁愿死也不要变成你们那副模样！你们还是人吗？是……畜生！"
D.Strings[21881]="你居然敢侮辱我的父亲。他比你勇敢得多。"
D.Strings[21882]="这孩子以为他自由了，但自由是要付出代价的。那些曾经受我牵制的恶魔，将为他以及所有企图逃跑的死亡骑士带去厄运……"
D.Strings[21883]="莫格莱尼的牺牲毫无意义。你会让库尔迪拉明白这一点的，对吧？"
D.Strings[21884]="记住，凡人：现在，我会给你选择的机会，我将允许你选择为谁效忠。但，殊途同归，你终将属于我。"
D.Strings[21885]="啊，部落……还是这么爱管闲事。我觉得应该好好欢迎一下你们。那么，欢迎，蝼蚁们。欢迎来到我的世界。"
D.Strings[21886]="你们来到这个属于死者的世界寻求答案。你们带着拯救盟友的希望，冒着失去生命的危险艰难地爬行到了这里。那么，请允许我帮帮你们吧。"
D.Strings[21887]="嗯？$c，你想接受我的训练？那你最好做好准备。"
D.Strings[21888]="我必须返回阴影世界，库尔迪拉。送我回去吧。"
D.Strings[21889]="愚蠢的巨魔，加入我们的行列吧。僵尸！进攻！"
D.Strings[21890]="僵尸！杀了他！"
D.Strings[21891]="就让我们瞧瞧达卡莱巨魔要如何应对强大的天灾军团吧！"
D.Strings[21892]="如果你愿意的话，就去兵营休息吧。但不要吵醒我的士兵，不然我会亲手将你扔到雪地里。"
D.Strings[21893]="启动预热程序。"
D.Strings[21894]="谢谢你救了我，$n。我永远不会忘记你的勇气和决心。"
D.Strings[21895]="大酋长，您好。请问您是否愿意接受我的邀请，以牦牛人首领的身份正式加入部落呢？"
D.Strings[21896]="$n，能以部落的兄弟的身份与你并肩作战是我的荣幸。我接受你的提议。"
D.Strings[21897]="大酋长，这是我的荣幸才对。喏，这份卷轴就是结盟的誓约，请您过目。"
D.Strings[21898]="%s让其他牦牛人都聚集在他身边，并按照卷轴上的内容诵读了誓言。"
D.Strings[21899]="$n，让我们并肩战斗吧。"
D.Strings[21900]="嗨。他们不确定这台升降梯能否正常运行，因此请了我和我的兄弟来帮忙。你想上去吗？"
D.Strings[21901]="我要到战歌要塞的顶层。"
D.Strings[21902]="嗨。他们不确定这台升降梯能否正常运行，因此请了我和我的兄弟来帮忙。你想下去吗？"
D.Strings[21903]="我要到战歌要塞的底层。"
D.Strings[21904]="同胞们，集合。"
D.Strings[21905]="Lok'tar ogar！不胜利，毋宁死——正是这条被所有的部落成员奉为真理的信条促使我加入部落！"
D.Strings[21906]="我发誓终身效忠于萨尔酋长。他的意志就是我的信条。他的指令就是我的使命！"
D.Strings[21907]="从这一刻直到我阖上双眼——为了部落！"
D.Strings[21908]="为了我们的牦牛人同胞！为了部落！"
D.Strings[21909]="欢迎加入部落，大酋长。Lok'tar ogar！"
D.Strings[21910]="除非你亲手杀死一条龙，否则我可不认你这个朋友……"
D.Strings[21911]="还有什么比猎杀巨龙更惊心动魄的呢。"
D.Strings[21912]="你好，$r。这是你首次踏上我们的圣地吧，让你目睹这样的情景真是抱歉。"
D.Strings[21913]="用手搓了搓|Hitem:36863|h|cFFFFFFFF[矮人的十面骰]|r|h ，然后抛了出去。"
D.Strings[21914]="终于自由啦。"
D.Strings[21915]="朋友，我要永远沉睡了……"
D.Strings[21916]="我的木乃伊在哪里？"
D.Strings[21917]="总算可以休息啦……"
D.Strings[21918]="随意抛出了|Hitem:36862|h|cFFFFFFFF[用旧的巨魔骰子]|r|h。"
D.Strings[21919]="开始收集能量。"
D.Strings[21920]="能量收集完毕。"
D.Strings[21921]="为什么打搅我？"
D.Strings[21922]="我要去永生之盾。"
D.Strings[21923]="我要去琥珀崖。"
D.Strings[21924]="我要去战歌要塞。"
D.Strings[21925]="不，朋友，我们可不想加入天灾军团！"
D.Strings[21926]="朋友，达卡莱帝国不会支持天灾军团的！"
D.Strings[21927]="兄弟们，坚持住！别加入天灾军团！"
D.Strings[21928]="哈！奴隶们总算带回一顿真正的美餐啦！"
D.Strings[21929]="你不过是在阻挠命中注定的结局！东方矗立起恐惧之城，而亡者大军将朝着冰冠冰川的中心挺进！"
D.Strings[21930]="嘿！需要什么东西，直接告诉我就行啦。"
D.Strings[21931]="可恨的天灾军团……他们很快就会得到报应的。"
D.Strings[21932]="辛克的伐木机已经就绪，随时摧毁林地。"
D.Strings[21933]="辛克的伐木机的安全功能已经激活。正在返回营地。"
D.Strings[21934]="如果你饿了，我这里有食物；如果你需要休息，可以钻进我的帐篷。"
D.Strings[21935]="电磁脉冲击碎了铁领主弗雷哈默尔的护盾！"
D.Strings[21936]="%s从电磁脉冲的攻击中恢复过来，再度开启了铁领主弗雷哈默尔的护盾。"
D.Strings[21937]="%s获得了燃料。"
D.Strings[21938]="谢谢你，伙计！让我瞧瞧要如何让这个笨家伙移动得快一点！"
D.Strings[21939]="我会保护你的，朋友！"
D.Strings[21940]="谢谢你，朋友。现在该让这群野兽尝尝太阳之井的愤怒了！"
D.Strings[21941]="你以为自己在做什么？离我远点！"
D.Strings[21942]="保护？为什么？那绝不是真理所在。不不不……要夺取！我现在终于明白了！"
D.Strings[21943]="外面或许没有下雪，不过这里的夜晚能把你的鼻子给冻掉。床铺就在后面——别招惹是非就是了。"
D.Strings[21944]="嗨。没有谁要故意为难你啦，不过你最好另找地方过夜。瞧你这身细皮嫩肉的，我不忍心让你吃苦。"
D.Strings[21945]="我不想死！"
D.Strings[21946]="主人会救我们的！"
D.Strings[21947]="啊！！！"
D.Strings[21948]="进来坐在火堆旁休息一下吧，$r。希望你不要介意鱼腥味儿。"
D.Strings[21949]="在险峻秀丽的海加尔山，在黄沙滚滚的希利苏斯，我们肩负着与燃烧军团抗衡的重任，血战到底。我们无名无姓，默默无闻，但我们都是联盟的英雄儿女。在圣光的指引下，我们冲锋陷阵，无坚不摧。$B$B我们就是第七军团。"
D.Strings[21950]="小家伙，你在寻找他们的首领……你竟然想要挑战雷霆使者戈洛塔尔领导的猛犸人氏族。别急着去送死吧。"
D.Strings[21951]="哈！好吧。碧蓝巨龙圣地以南有一处火炬环绕之地，在那里吹响猛犸人首领号角。向你信奉的诸神祈祷吧……戈洛塔尔就会出现。"
D.Strings[21952]="谢谢你救了我，我的同胞还被关押在上面几层！"
D.Strings[21953]="谢天谢地！我正担心他们会不会强迫我去对付石巨人呢！"
D.Strings[21954]="这帮铁矮人疯子！他们反复谈论要为“洛肯大人”效劳，但是据我所知，只有少数人接到他的指令而已。"
D.Strings[21955]="你好！需要什么吗？"
D.Strings[21956]="这全是你的错……"
D.Strings[21957]="这简直是最最最白痴的主意了……“是啦，布鲁特，这样很好呀……被遗忘者会往我们头上撒金币的！”"
D.Strings[21958]="你知道最让我厌烦的是什么吗，斯克罗提？虽然我们不得不定时报钟，供被遗忘者消遣；虽然我们必须时刻忍受他们的口水和讥笑……但是这些都比不上那些该死的超短裤……穿上这样的玩意儿真是令我抓狂！"
D.Strings[21959]="祈祷吧，斯克罗提……找回你的信仰……否则就算我们有机会逃走，你也会盼望着回来的！"
D.Strings[21960]="我希望我们中间死掉一个。我希望那个人是你，斯克罗提。"
D.Strings[21961]="别又说废话啊……"
D.Strings[21962]="真的又过了一个小时吗？"
D.Strings[21963]="如果我能离开这里，我要把看见的每一只钟都砸了……"
D.Strings[21964]="钟声敲响，午夜12点整。可笑的被遗忘者，你们的午夜降临啦！喔喔喔……"
D.Strings[21965]="钟声敲响，凌晨2点整。这正是杀死我的最佳时刻啊，来吧，让我解脱吧！"
D.Strings[21966]="钟声敲响，凌晨4点整。被遗忘者不用睡觉的吗？"
D.Strings[21967]="钟声敲响，凌晨6点整*打哈欠*。起床啦，太阳晒屁股叻。"
D.Strings[21968]="钟声敲响，早上8点整。你们都结束晨跑了吧。"
D.Strings[21969]="钟声敲响，上午10点整。今天的天气预报称，空中可能出现更多绿色的致命毒云团。"
D.Strings[21970]="钟声敲响，正午12点整。瞧你们这帮连数都不会数的家伙，现在是正午时分。说的就是你们，兽人。"
D.Strings[21971]="钟声敲响，下午2点整。请允许我借此机会做做宣传：米德尔顿正在举办买一赠一活动！购买一罐闻名于世的有毒生物制剂就能再免费获赠一罐！"
D.Strings[21972]="钟声敲响，下午4点整。现在是米德尔顿炼金房的“欢乐时光”！只需35银币，就能享受到吞食毒药或是吞服毒气的乐趣哦，两种一起来也可以哟！"
D.Strings[21973]="钟声敲响，下午6点整。杀死我的兄弟吧！"
D.Strings[21974]="啊！！发生了什么事？"
D.Strings[21975]="轮到我了吗？"
D.Strings[21976]="吃午饭的时候到了吗？"
D.Strings[21977]="这次我一定会跳的，布鲁特。我发誓！"
D.Strings[21978]="钟声敲响，凌晨1点整。如果我能逃出去的话，我会将这个镇子撕成碎片！！！"
D.Strings[21979]="钟声敲响，凌晨3点整。该睡觉了！"
D.Strings[21980]="钟声敲响，凌晨5点整。杀了我吧！"
D.Strings[21981]="钟声敲响，早上7点整。早上好，你们都起得很早啊！"
D.Strings[21982]="钟声敲响，上午9点整。龙骨荒野似乎又迎来了美好的一天！"
D.Strings[21983]="钟声敲响，上午11点整。让我借此机会欢迎你们这些心理扭曲的部落成员吧，欢迎你们来到怨毒镇！我代表我和我兄弟布鲁特向你们致意。"
D.Strings[21984]="钟声敲响，下午1点整。现在是午餐高峰时间！你们预订的货物将在60秒后送到；如果未能准时送达，就免去订单费！"
D.Strings[21985]="钟声敲响，下午3点整。我好像尿裤子了。"
D.Strings[21986]="钟声敲响，下午5点整。我知道你们还惦记着刚才的事儿呢，好吧，我确实——尿裤子了。"
D.Strings[21987]="钟声敲响，晚上7点整。夜幕降临，怨毒镇充实的一天结束了。"
D.Strings[21988]="钟声敲响，晚上9点整。我该休息啦！4小时之后我还会来报钟的，除非你们趁我睡觉时杀了我（请一定要这么做）。"
D.Strings[21989]="那个没用的巨魔再度失败了。我的容忍已经到了极限！安希斯！给我打断他的腿！"
D.Strings[21990]="我立即去办！"
D.Strings[21991]="我还没见过你如此迫切地想要给他人留下痛苦的回忆呢。这是进步呢……很好，去吧！"
D.Strings[21992]="殿下！请改派我去吧。"
D.Strings[21993]="你……自作聪明的家伙……你想什么呢？打算夺取属于她的功劳吗？你以为她会被你蒙在鼓里？"
D.Strings[21994]="监工，进展太缓慢了。"
D.Strings[21995]="命运不会为谁停留。在石巨人大军抵达奥杜尔之前，你必须监督工匠提高作战魔像的产量。"
D.Strings[21996]="告诉你手下的符文铁匠，必须加紧改造石巨人。摧毁那些不服从指令的家伙。"
D.Strings[21997]="如果石巨人胆敢阻挠我们在奥杜尔的工事，我就撤消你和你的领主的权利。绝不允许凡人帮助巨人。"
D.Strings[21998]="回到你的岗位上去吧，监工。必须让工匠们明白任务的急迫性。"
D.Strings[21999]="我设计的掷杯训练器不只是用来训练扔酒杯的，它还是非常有价值的训练设施。如果你能击中它，就可以击中任何东西！$B$B不要击中我就行了。"
D.Strings[22000]="鸣响"
D.Strings[22001]="让我们瞧瞧这管不管用。"
D.Strings[22002]="别一副懒散模样！我们必须将这些建筑物修好！"
D.Strings[22003]="最好在阿尔萨斯王子回来之前完工！"
D.Strings[22004]="伙计们，埋头工作呀！快一点！"
D.Strings[22005]="你是想滚回家吗？你以为这些建筑物能自动复原是不是！"
D.Strings[22006]="别紧张。王子很快就要回来啦，到时候我们就能返回洛丹伦了。"
D.Strings[22007]="你做得很好，士兵。阿尔萨斯王子会为你感到骄傲的！继续努力！"
D.Strings[22008]="当这一切都结束后，我会建议上头为你颁发一枚联盟荣誉奖章的。"
D.Strings[22009]="随时任何可疑的动静。我发现有些捣乱分子在蠢蠢欲动了。"
D.Strings[22010]="保持警惕，士兵。这场可怕的战争很快就要结束了。"
D.Strings[22011]="矮人，欢迎拜访欧尼瓦营地的牦牛人。"
D.Strings[22012]="如果你愿意帮助我们抵御共同的敌人，我们保证不伤害你。"
D.Strings[22013]="考虑一下吧，勘查员，希望你能尽快做出决定。我们必须立即采取行动。"
D.Strings[22014]="我听到入侵者在窃窃私语。当心。"
D.Strings[22015]="步兵，我能闻到你身上的土臭味儿。换班之前，向主教报到吧。"
D.Strings[22016]="你真臭。去洗个澡吧。"
D.Strings[22017]="高级执行官乌洛斯负责发送悬赏令的奖励。$B$B有诚意者请入内咨询。$B$B谢绝中介！"
D.Strings[22018]="我将谦卑地服从圣光的意志。"
D.Strings[22019]="摧毁那些行尸走肉……我当然是指天灾军团。"
D.Strings[22020]="乔伊，是你。真的是你！"
D.Strings[22021]="冷静。我是想问你关于铁矮人和洛肯的情况。"
D.Strings[22022]="你来这里干什么，小家伙？"
D.Strings[22023]="关于铁矮人和洛肯，你都知道些什么？"
D.Strings[22024]="乔伊怎么会问这样的问题！好吧，我确实知道洛肯的事。"
D.Strings[22025]="他也在找我的麻烦呢！如果我是你的话，我在这一带走动时会额外小心的。你永远都不知道他会躲在哪棵树后面！"
D.Strings[22026]="啊，是的。我对洛肯非常了解。"
D.Strings[22027]="他指挥钢铁的子嗣，对我们发动了战争。"
D.Strings[22028]="他藏身在不为人知的角落，监督着战争的准备工作，想要消灭石巨人！"
D.Strings[22029]="我将谦卑地服从圣光。"
D.Strings[22030]="你能来真是太好啦，我的孩子。圣光对你的眷顾正在消退。"
D.Strings[22031]="好了。好好为圣光效劳。"
D.Strings[22032]="笨手笨脚的蠢货！"
D.Strings[22033]="你把这批样本完全搞砸了！你还有什么可辩解的？"
D.Strings[22034]="<海象人怀疑地打量着你。>$b$b别在此地久留。你并不了解我们，我可希望招惹什么麻烦。"
D.Strings[22035]="但是……我是严格按照你的指令做的！我该说对不起吗？"
D.Strings[22036]="对不起？就会说对不起？！我对你太失望了！"
D.Strings[22037]="哎呀。我觉得这玩意儿起作用啦！真奇怪。"
D.Strings[22038]="天空并不安全，朋友。要小心！"
D.Strings[22039]="没有效果！"
D.Strings[22040]="又一头科多兽逃过了死亡的魔爪！"
D.Strings[22041]="天灾军团也不是我的对手，托普！"
D.Strings[22042]="托普，如期送达！"
D.Strings[22043]="返回战场！即将发射！"
D.Strings[22044]="凡人，当你在伊瑟拉的花园中走动时，请随时保持警惕。别轻易相信你所看到的一切。"
D.Strings[22045]="等我处理完收尾工作，就换个新助手！"
D.Strings[22046]="你需要什么？要不要修理一下护甲或是武器？嗯？"
D.Strings[22047]="我需要新鲜的肉……今天的血流得还不够多！"
D.Strings[22048]="你这肮脏的杂种，还有什么遗言吗？"
D.Strings[22049]="呸，我才不在乎你有没有遗言。下地狱去吧，可怜虫！"
D.Strings[22050]="哈！这种消遣真是永不过时。"
D.Strings[22051]="痛的话就告诉我。"
D.Strings[22052]="我觉得这次能够成功……"
D.Strings[22053]="让我们试试这个……"
D.Strings[22054]="感觉怎么样？"
D.Strings[22055]="你觉得我们能得出什么结论吗？"
D.Strings[22056]="这样足够吗？"
D.Strings[22057]="你想获得永生吗？"
D.Strings[22058]="再刺一下。别对敌人心软。"
D.Strings[22059]="我们施加的痛苦越多，就能越快得到想要的答案。"
D.Strings[22060]="你想要什么呢，$r？"
D.Strings[22061]="住手！求求你……"
D.Strings[22062]="你尽管来好了。"
D.Strings[22063]="你到底还想知道什么啊？"
D.Strings[22064]="$r，我能感受到你内心的阴暗面。"
D.Strings[22065]="你根本就没有问我问题啊……"
D.Strings[22066]="你是想看看我的真面目吗？"
D.Strings[22067]="$n，你简直是邪恶的化身。"
D.Strings[22068]="$c，在这个黑暗的时代，我们必须铤而走险。"
D.Strings[22069]="有什么我可以尝试的玩意儿吗？"
D.Strings[22070]="没错，可我们能坚持多久呢？这样做，又比我们的敌人好到哪儿去呢？"
D.Strings[22071]="敌人是不会对我们手软的。"
D.Strings[22072]="坐骑。我们需要更多的坐骑！"
D.Strings[22073]="坐骑。我们需要更多的坐骑！$B$B你大概是来寄放宠物的？"
D.Strings[22074]="黑暗就蛰伏在这片秀丽的山岭下。朋友，千万当心。"
D.Strings[22075]="厕所好像被占用了。"
D.Strings[22076]="小心，周围可能有那些传播着巫妖王诅咒的爪牙。"
D.Strings[22077]="愿圣光净化你，勇敢的$n。"
D.Strings[22078]="我的父亲将他的作战盔甲和斧头都送给我啦。很快我就能好好利用它们了。"
D.Strings[22079]="如果你是来这里诚心恳求我赐予你为我效劳的机会，那么我欢迎你。不然的话，你到一边凉快去吧。"
D.Strings[22080]="做个自我介绍吧。"
D.Strings[22081]="真幸运，厕所现在没人。"
D.Strings[22082]="上厕所。"
D.Strings[22083]="我们的食物和饮料储备已经出现短缺。恐怕我没什么能给你的。"
D.Strings[22084]="谢谢你的帮助，$n。这些冰莓就当作你的劳动果实吧。"
D.Strings[22085]="蠢货！你们不该踏上这片土地！"
D.Strings[22086]="我要消灭你们！"
D.Strings[22087]="你不是猛犸人！你的……力量……是……怎么来的？"
D.Strings[22088]="接下来就该轮到你的女人和孩子了。你要让可怜的猛犸人氏族失望了。"
D.Strings[22089]="你们别想抓到我，魔鬼！"
D.Strings[22090]="看在圣光的份上，把我救出去吧！"
D.Strings[22091]="我真是选了个戒酒的好日子啊！"
D.Strings[22092]="他们想杀我！救命！"
D.Strings[22093]="我宁愿死，也不愿意落在恶魔手中！"
D.Strings[22094]="这是怎么搞的！谁来救救我！"
D.Strings[22095]="谁能想到我们会遇到同样的状况呢？噢，不，大家都想到了！"
D.Strings[22096]="很好。我们已经找到了琥珀种子。你知道该怎么做了吧。"
D.Strings[22097]="我知道，我知道。在桶里……"
D.Strings[22098]="食物！！！"
D.Strings[22099]="我来了！！"
D.Strings[22100]="消灭敌人！！消灭他们！！"
D.Strings[22101]="唔唔唔！"
D.Strings[22102]="别跑！！！别再跑了！！！！"
D.Strings[22103]="谢谢你的帮助，勇士！"
D.Strings[22104]="你救了我！谢谢！"
D.Strings[22105]="你真的懂得如何驾驭狮鹫吗？我怎么觉得有点晃悠悠的？"
D.Strings[22106]="我不是忘恩负义的家伙啦，但是你能飞得再低一点吗？我恐高！"
D.Strings[22107]="当我得知北方还有宗亲时，就满心欢喜地赶来寻访。可我见到的全是侵略性极强的部族，他们身上完全没有和平的天性。$B$B$c，我很绝望。就连伟大的乌索克都没能逃过堕落的命运。$B$B我已经丧失了所有希望。"
D.Strings[22108]="你真是我的守护天使！你就像来自天堂的白衣骑士，将我从地狱的深渊中解救出来！"
D.Strings[22109]="我该怎么报答你呢，朋友？"
D.Strings[22110]="我有点头晕……呕……"
D.Strings[22111]="上来！"
D.Strings[22112]="抓住我的手！"
D.Strings[22113]="我是来救你的，朋友！"
D.Strings[22114]="骑到我的狮鹫背上来！"
D.Strings[22115]="快！上来！"
D.Strings[22116]="返回暮冬城或是腐臭平原，否则狮鹫会抛下你！"
D.Strings[22117]="站到我身后，$r。我会尽力保护你的。"
D.Strings[22118]="如果不能拯救乌索克，那我的自由也就毫无意义了。要快，$n。"
D.Strings[22119]="我会保护你和你的盟友，$r。"
D.Strings[22120]="图尔，变成熊形态吧。"
D.Strings[22121]="帮我们制伏他。"
D.Strings[22122]="我们需要一名治疗者。"
D.Strings[22123]="我们已经净化了沃达希尔的树苗。如果能制伏乌索克，我们或许能治愈他的灵魂。"
D.Strings[22124]="是的……我能感觉到沃达希尔的魔法能量……没有丝毫被污染的迹象。$B$B让我帮助你吧！命运让我来到这里，或许我能帮上忙的！"
D.Strings[22125]="终于安全了！谢谢你，陌生人！"
D.Strings[22126]="乌瑞克，这位勇士真是太善良了。谢谢你，英雄！"
D.Strings[22127]="我们成功了！我们真的成功了！"
D.Strings[22128]="我的店门将永远对你敞开，朋友。"
D.Strings[22129]="我们不会忘记你的英勇行为，$n。你永远是暮冬城的客人。$B$B你愿意将这座旅馆当作自己的家吗？"
D.Strings[22130]="我想看看你出售的货物，伊露希亚。"
D.Strings[22131]="塞巴鲁斯打心眼儿里感激你。若不是你，我早就没命啦，说不定还会变成亡灵的一员……"
D.Strings[22132]="%s呻吟着，但是似乎并没有受到感染。"
D.Strings[22133]="你的信仰很坚定，孩子。继续做事吧。"
D.Strings[22134]="你需要主教大人的祝福。快去找他吧。"
D.Strings[22135]="在纯洁的道路上继续走下去吧。圣光会保佑你的。"
D.Strings[22136]="你这个不洁者！"
D.Strings[22137]="死吧，杂种！"
D.Strings[22138]="从我眼前消失吧！"
D.Strings[22139]="异端！"
D.Strings[22140]="亵渎者！"
D.Strings[22141]="阿比迪斯大人将会净化你！"
D.Strings[22142]="你居然敢来这里，太愚蠢了！"
D.Strings[22143]="你将被净化！"
D.Strings[22144]="以圣光之名！"
D.Strings[22145]="钢铁的利刃将你净化！"
D.Strings[22146]="你竟敢干扰我们正义的事业？！"
D.Strings[22147]="%s身上的符文突然散发出明亮的光芒！"
D.Strings[22148]="我曾经以乌索克之子的身份在灰熊丘陵巡游，统治着这片领地。$B$B如今……我却只能窝在洞穴中苟延残喘，度过悲惨的余生。"
D.Strings[22149]="奥索恩，你随时可以离开，但是请先告诉我熊怪们到底出了什么事。"
D.Strings[22150]="你不能理解我的处境。我真想出去的话，早就杀出一条血路离开这个洞穴了。$B$B可我不能丢下父亲乌索克不管啊。他复活了……却不再是从前的心性。$B$B在数千年前的上古之战中，我的父亲就已经阵亡。崇拜他的熊怪部族一直想要复活他。$B$B最终他们决定重新培植那株被德鲁伊砍倒的世界之树——沃达希尔，企图利用它的力量复活我的父亲。"
D.Strings[22151]="小声点，$c。没瞧见我正穿着伪装为怨毒镇侦察吗？"
D.Strings[22152]="他们种下的树苗结出了一枚果实。最初一切都进展顺利。乌索克真的复活了，我也完全沉浸在这短暂的喜悦中。$B$B很快我就察觉到，他与生前截然不同。那些熊怪也发生了转变。$B$B当年，德鲁伊们因为不堪世界之树被邪恶力量所腐化，忍痛砍倒了沃达希尔。如今，新生的世界之树再度成为滋生邪恶的温床，令所有的熊怪变成了嗜血的野兽。$B$B出没在灰熊丘陵的怪物不再是我的父亲了，必须让他得到安息。"
D.Strings[22153]="谢谢你，乌索克之子。我会力所能及地帮助你。"
D.Strings[22154]="我是科蒂安，乌索克的女儿。我守护着这座曾经被视为圣地的祭坛。$B$B很久以来，都没有陌生人到这里来拜访了。"
D.Strings[22155]="这位陌生人是谁？"
D.Strings[22156]="他是一只名叫图尔·怒爪的熊怪。嗯，不属于我们的氏族。$B$B他来自南部的木喉部族。$B$B图尔想见见乌索克。他觉得有希望净化沃达希尔的污染，并借此拯救我的父亲。$B$B抱着这样的希望未免有些天真。等你亲眼目睹我的父亲受到的黑暗污染之后，你就能认同我的看法了。"
D.Strings[22157]="谢谢你，科蒂安。我会尽力的。"
D.Strings[22158]="天哪，我漂亮的小磨坊！你！我要你为此付出性命！"
D.Strings[22159]="愿圣光与你同行，朋友。"
D.Strings[22160]="让仁慈的圣光救赎你的灵魂吧，恶魔。"
D.Strings[22161]="他们曾经也是人类……可现在呢？不过是一群嗜血的亡灵！"
D.Strings[22162]="噢噢噢噢！一枪爆头！"
D.Strings[22163]="圣光会消灭你！"
D.Strings[22164]="%s清了清枪管。"
D.Strings[22165]="总算来了一份有价值的祭品！"
D.Strings[22166]="肮脏的畜生。你们不配活在这世上。我要杀了你们！"
D.Strings[22167]="乌索克，乌索尔的兄弟，熊怪部族的守护者……现身吧！"
D.Strings[22168]="嗨，塞莉德！你有宠物要寄放进兽栏吗？"
D.Strings[22169]="我是很忙啦，塞莉德。你有宠物要寄放进兽栏吗？"
D.Strings[22170]="塞莉德，我跟所有新来的人打赌来着，赌你肯定想要在兽栏寄放宠物。"
D.Strings[22171]="来呀，我带你去个安静的地方。"
D.Strings[22172]="走吧。"
D.Strings[22173]="这边走。后面有我们最好的兽栏。"
D.Strings[22174]="这里真是一马平川……阳光充沛……"
D.Strings[22175]="告诉我怎么制作这种胡萝卜！"
D.Strings[22176]="谢谢你们。将沃达希尔砍倒的德鲁伊做出了明智的决定，蛰伏在地底的远古邪灵已经侵淫了那棵世界之树的根须。"
D.Strings[22177]="你们将这种生物称为上古之神。它就是尤格-萨隆，拥有一千张嘴的怪物。它通过沃达希尔的根须散播着邪恶之力。"
D.Strings[22178]="你能带我离开这里吗，$C？"
D.Strings[22179]="不行，斯克尼德。你的日子到头了！"
D.Strings[22180]="啊，你是来救我的吧。快带我离开这个鬼地方！"
D.Strings[22181]="今天不行，首席抄写员！"
D.Strings[22182]="嘿！我觉得我好像在哪儿见过你。$B$B不如救我出去，怎么样？"
D.Strings[22183]="不行。你担任卫生设备工程师的日子到头了。"
D.Strings[22184]="进攻吧，我的仆从们！主人命令你们进攻！"
D.Strings[22185]="杀死这名胆敢挑衅巫妖王的凡人！"
D.Strings[22186]="他们的防线已经被攻破了！时机到了，奴仆们！进攻！"
D.Strings[22187]="我根本不知道出了什么状况。我刚到怨毒镇没多久，就突然在睡梦中被关进了牢笼！$B$B你是来救我的吗？"
D.Strings[22188]="不行，司法官。从本质上讲，我并不是来“营救”你的。"
D.Strings[22189]="什么叫我的日子到头了？！把话说清楚，不然我宰了你！"
D.Strings[22190]="你不会是想……我要把你的罪行详细记录下来，$C！"
D.Strings[22191]="你一看就是个大好人，放我出去吧！"
D.Strings[22192]="谁放我出去呀？我还要返回怨毒镇换班呢。"
D.Strings[22193]="不！我求求你！千万别杀我！"
D.Strings[22194]="集合，开往前线！"
D.Strings[22195]="增援城门！不要让天灾军团攻破城门！"
D.Strings[22196]="坚守防线！全军注意，向城门开火！"
D.Strings[22197]="这到底是什么意思？！住手！他们付你多少？？我可以给你两倍的钱！"
D.Strings[22198]="我刚刚到怨毒镇啊，怎么可能招惹到你？"
D.Strings[22199]="你好，$c。$B$B我能帮上什么忙吗？"
D.Strings[22200]="托瓦德·埃里克森领主的始祖龙被锁链拴在这儿，它是一只脾气暴躁、喜怒无常的凶兽。"
D.Strings[22201]="解开烈焰使者的锁链并控制它。"
D.Strings[22202]="战士们，站起来为你们的新主子而战吧！"
D.Strings[22203]="谢谢你，善良的灵魂。"
D.Strings[22204]="我永远不会忘记你的，朋友。"
D.Strings[22205]="终于，来了一位英雄！"
D.Strings[22206]="你来得正是时候，英雄！我差点被那畜生给吃了！"
D.Strings[22207]="要玩玩吗？"
D.Strings[22208]="让他们陪伴你吧，巫妖王向你致意！"
D.Strings[22209]="别急着逃走呀！我还有份“饯别”礼物呢……"
D.Strings[22210]="你瞧这座雕像。他就是暴风城的国王瓦利安·乌瑞恩。"
D.Strings[22211]="他的儿子安度因·乌瑞恩就是现任国王。年纪和我差不多吧。你能想象我坐上王座的模样吗？"
D.Strings[22212]="有时人们会将我误认成国王陛下。大概是我们的容貌过于相似吧……"
D.Strings[22213]="如果我当上了国王，我一定要找到一匹像你这般健壮漂亮的马儿。我会好好保护你，我相信你也会保护我的。"
D.Strings[22214]="我们会成为好朋友的。我敢打赌我和安度因也会成为好朋友的。朋友是最宝贵的财富。"
D.Strings[22215]="呸！我什么都不会告诉你，肮脏的$r，！"
D.Strings[22216]="等等……等等！你到底想知道什么啊？！我知道你是个名叫$n的$C。"
D.Strings[22217]="噢……不！我们知道是你偷了我们的盔甲、武器，还有马匹！"
D.Strings[22218]="我们知道……你们无法理解……为什么我们……对所谓的病菌免疫。海军上将巴利·韦斯温似乎向高阶修士传授了什么祷言。啊啊，求你了……住手……好吗？！"
D.Strings[22219]="啊啊啊啊啊！求求你……我们……知道……有间谍……混进了……我们中间！我……我……我就知道这么多啦。求求你……发发慈悲吧……停手呀！"
D.Strings[22220]="我带你去找其他马儿吧。你呀，肯定是想和它们呆在一起啦。它们也会成为你的新朋友呀。"
D.Strings[22221]="看上去还好吧？"
D.Strings[22222]="比看起来要难很多。"
D.Strings[22223]="这可不容易。"
D.Strings[22224]="我想我快要掌握窍门啦。"
D.Strings[22225]="我胳膊越来越疼了。"
D.Strings[22226]="我只是有些紧张。很抱歉。"
D.Strings[22227]="我只是不想再让别人失望了。"
D.Strings[22228]="我得让自己忙起来。"
D.Strings[22229]="我告诉你……我……什么……都不知道！"
D.Strings[22230]="你还想不想让我睡觉啊？"
D.Strings[22231]="求你……住手。我……我什么都愿意做……"
D.Strings[22232]="让一切……结束吧。"
D.Strings[22233]="你不能稍微安静一点吗？"
D.Strings[22234]="他们……都在……乞求……活命!"
D.Strings[22235]="你打算一直这样是吧？"
D.Strings[22236]="每两年竞争之魂就会变得特别狂躁……喏，就是现在！我们要穿上这件战袍进入战场并击败敌人，以此获得竞争之魂的青睐。"
D.Strings[22237]="我求求你……住手。"
D.Strings[22238]="这简直是非人的折磨！"
D.Strings[22239]="你别想……从我这里……得到……任何东西！"
D.Strings[22240]="啊啊啊啊啊啊啊啊啊啊！"
D.Strings[22241]="我要怎样才能获得竞争者的战袍？"
D.Strings[22242]="我要怎样才能获得竞争之魂的青睐？"
D.Strings[22243]="你只需要进入任意战场英勇作战就行了。无论胜负，只要你坚持到最后一刻，就能收到我们邮寄给你的竞争者的战袍。"
D.Strings[22244]="你必须进入任意战场并击败敌人。获胜之后，你就有可能收到我们邮寄给你的金色勋章。"
D.Strings[22245]="你知道竞争之魂吗？$B$B每两年它们就会接近我们的世界。在此期间，联盟或是部落的成员都可以穿着竞争者的战袍进入战场，以此赢得竞争之魂的青睐。$B$B我收集了一些相关的纪念品。如果你知道那段密语的话，我或许可以送你一些……"
D.Strings[22246]="我要输入神秘兑换码，领取竞争者的纪念品。"
D.Strings[22247]="$n，很快我们就明白了死亡在这片冰封之地意味着什么。诺森德弥漫着巫妖王的邪恶力量，这种力量甚至渗透每一寸土地！他唤醒了那些在战斗牺牲的将士，命令他们与我们为敌。$B$B复活的狮鹫骑士随同地面的亡灵大军对我们发动了枪林弹雨般的猛烈攻击。"
D.Strings[22248]="克雷娜对我的能力颇有质疑。她派出最精锐的将士对付联盟以及他们的猎户盟友，让他们执行针对冰霜巨魔的大规模作战计划，却让我与这帮粗俗的掠龙维库人周旋。$B$B或许我们应该联手，共同改变我们在征服者眼中的形象。"
D.Strings[22249]="欢迎来到琥珀松木营地，$C。"
D.Strings[22250]="你真贴心。喏，将这匹马牵到你的马厩去吧。"
D.Strings[22251]="我整天都忙得不可开交。来，将这匹马牵到你的马厩去吧。"
D.Strings[22252]="这是一等一的好马呀。你要好好照顾它。"
D.Strings[22253]="来，将这匹马牵到你的马厩去吧。替我向罗纳德问个好。"
D.Strings[22254]="首席抄写员巴里加被关在哪儿？"
D.Strings[22255]="他似乎被关在伐木场附近的某个牢笼。"
D.Strings[22256]="你知道他们把卫生设备工程师布尔克带到哪儿去了吗？"
D.Strings[22257]="他应该被关押在修道院的南边。"
D.Strings[22258]="知道他们把亡灵卫兵斯克尼德关在哪儿了吗？"
D.Strings[22259]="她应该被绑在绞刑架下。"
D.Strings[22260]="你能告诉我他们把司法官亚麦关在哪里了吗？"
D.Strings[22261]="我看见他被带往修道院北边了，就在箭靶附近。"
D.Strings[22262]="%s迅速窜回了自己的洞穴……"
D.Strings[22263]="增援！我们需要增援！"
D.Strings[22264]="帮帮忙啊！我抗不住了！"
D.Strings[22265]="你不知道？猎户？他们已经不是人类了……我们必须离开这里！快走！"
D.Strings[22266]="牵走杜卡尔的马吧，他已经彻底沦陷了！"
D.Strings[22267]="这里发生了什么事，长官？"
D.Strings[22268]="我不知道。为了安全起见，最好将他们统统杀掉！"
D.Strings[22269]="帮帮我！帮帮我！这家伙偷走了我的影像！"
D.Strings[22270]="我知道你为什么会来这里——平原上那些愚蠢的猛犸人多管闲事，竟然胆敢与龙族交战。当他们的走狗很有趣吗？"
D.Strings[22271]="矿洞已经失守。所有的卫兵都被杀害了，死去的矿工还被复活，成为了天灾怪物！"
D.Strings[22272]="烈焰使者试图将你掀下去。返回沃德伦！"
D.Strings[22273]="愚蠢的$g小子:小丫头;……你竟然敢打扰我的工作，受死吧！"
D.Strings[22274]="朋友，情况越来越糟糕了。根据我的计算，如果没有足够的材料维修防御墙的话，那么保护这座要塞的城墙就会在12小时内坍塌。"
D.Strings[22275]="同胞们，我要告诉你们一个坏消息。如果我们战败，亡灵大军将肆无忌惮地横扫这片冰封之地。那时，弗塔根公爵以及我们在天谴之门的军队将无力与来自纳克萨玛斯的天灾军团抗衡。"
D.Strings[22276]="李奥瑞克，我们经历过更可怕的局面，而且还活了下来。你还记得海加尔峰吗……"
D.Strings[22277]="嗯，是啊，我永远记得第七军团在海加尔峰和希利苏斯的战事，记得我们对抗燃烧军团的远征，记得第七军团曾经面临过的种种挑战。但是……我不想让别的将士听到我这番话：这次是我生命中第一次感到……"
D.Strings[22278]="别说了，李奥瑞克。我们都能感受到这刺骨的寒冷。但是，我们并不孤独！每天，都有来自各个位面的英雄加入我们的行列。"
D.Strings[22279]="我听到东方传来的低语，备受尊敬的甲虫之王已经投身战斗，沙塔斯城也派来了一支精英部队。这支军队接受过阿达尔的赐福，他们都拥有一个响亮的头衔：阿达尔之手！"
D.Strings[22280]="你说得对，我的老朋友。希望那些英雄能快点抵达这里。"
D.Strings[22281]="不……天哪！你都做了什么？！竟然杀死了这么多远古巨龙……这是什么魔法？"
D.Strings[22282]="竞争之魂又一次变得强大了。"
D.Strings[22283]="今天的战场里充满了斗志昂扬的勇士。"
D.Strings[22284]="战场军官很高兴看到这么多人来参与竞赛。"
D.Strings[22285]="我为自己能获得竞争者的战袍而感到骄傲，并且希望能获得一枚金色勋章。"
D.Strings[22286]="你已经不是黑龙了。去吧……为天灾军团战斗吧。"
D.Strings[22287]="你好，$c。$b$b你想去风险湾吗？"
D.Strings[22288]="是的，我已经准备好前往风险湾了！"
D.Strings[22289]="毁灭结界已经被摧毁了。"
D.Strings[22290]="我好困。"
D.Strings[22291]="我好冷。"
D.Strings[22292]="我最怕虫子了。"
D.Strings[22293]="呀呀，我被蜘蛛丝给缠住了。"
D.Strings[22294]="我最讨厌虫子多石头也多的地方。"
D.Strings[22295]="我不喜欢冷的地方。"
D.Strings[22296]="哈哈。"
D.Strings[22297]="太可笑了。"
D.Strings[22298]="哦。"
D.Strings[22299]="住手！"
D.Strings[22300]="好痛。"
D.Strings[22301]="什么声音？"
D.Strings[22302]="你的脑袋跟石头一样硬。"
D.Strings[22303]="工作时间！哼唧哼唧！"
D.Strings[22304]="什么？没看见我正忙着吗？$B$B难道你觉得这玩意儿能自动恢复正常？！"
D.Strings[22305]="伯瓦尔·弗塔根公爵一直都在为正义的事业奋斗。要不是他，阿尔萨斯没准已经坐上了暴风城的王座。"
D.Strings[22306]="啊，这种矿石，我差一点就能想出眉目来啦！只要灵光一闪，我就能给出答案！"
D.Strings[22307]="你们被骗了！血色先锋军都是骗子！天灾军团和被遗忘者不是我们的敌人！醒醒吧！"
D.Strings[22308]="阿比迪斯将军亲口对我说，北征诺森德是个错误，我们被诅咒了！我奉劝你们赶紧放下武器，趁早离开这里！"
D.Strings[22309]="与血色先锋军断绝关系！别再听信将军和元帅编造的谎言了！"
D.Strings[22310]="阿比迪斯就是个臭婊子！海军上将巴利·韦斯温也不过是个皮条客，他以低廉的价格出卖了阿比迪斯，就像出卖我们一样！"
D.Strings[22311]="机器人会根据你的行进速度调整自身的速度。我建议你骑上座骑，提高效率。顺便提一句，这玩意儿是我用一堆从外域送来的破铜烂铁拼凑起来的，可能会产生副作用。"
D.Strings[22312]="毁灭结界正在充能。"
D.Strings[22313]="毁灭结界充能完毕！"
D.Strings[22314]="夸特弗拉什，再给我一个导航机器人吧。"
D.Strings[22315]="嗨，$c！$b$b你打算前往风险湾对付部落吗？"
D.Strings[22316]="很好。看来不派你去好好地教训他们一下，他们是搞不清楚状况的。"
D.Strings[22317]="%s站了起来！"
D.Strings[22318]="孩子们，去看看是谁在捣鬼。"
D.Strings[22319]="遵命。去看看！"
D.Strings[22320]="喂，是谁在鸣钟？"
D.Strings[22321]="保镖嘟囔着。"
D.Strings[22322]="孩子，有事吗？"
D.Strings[22323]="我正忙着呢。有什么话待会再说好吗。"
D.Strings[22324]="请问我能不能与您单独谈一谈？"
D.Strings[22325]="<高阶修士打量了你一番，然后露出了笑容。>$B$B孩子，我知道有个地方不错的。如果你准备好了，就亲吻着我的戒指吧。"
D.Strings[22326]="我准备好了。<亲吻戒指>"
D.Strings[22327]="去修道院门口等我吧。我很快就会过去的。"
D.Strings[22328]="萨盖，蛛魔将要塞围得水泄不通啊。它们的数量简直无穷无尽。"
D.Strings[22329]="是啊。它们不断从虫孔中涌出。你见过吧？我觉得我们应该设法炸毁那些虫孔，阻断蛛魔大军的来路。"
D.Strings[22330]="没错……我昨天从采石场回收了一些军事物资，就是打算炸毁虫孔。"
D.Strings[22331]="希望能尽快埋好炸药。我们已经筋疲力尽了，只有炸毁虫孔，我们才能喘口气。"
D.Strings[22332]="你说得对。"
D.Strings[22333]="在摧毁这一文明的战事中，我已经尽到了自己的义务……我不得不屈尊亲自对付诅咒神教，一想到这点就觉得恶心。"
D.Strings[22334]="斯古莉探员，请再对我使用一次女妖的魔镜！"
D.Strings[22335]="好吧，不过这次希望你再当心一点！"
D.Strings[22336]="很显然，他们利用那些符文来储藏从别处抽取来的能量。"
D.Strings[22337]="恶鬼……真讨厌。诅咒教派已经污染了这片土地。"
D.Strings[22338]="我知道有个僻静的去处，我们可以去那里单独谈谈。跟我来吧，孩子。"
D.Strings[22339]="我真希望自己的猜测是错误的……但是他们……他们真的在复活熔岩之龙。快回到我身边，我们必须尽快将诅咒教派驱出这里。"
D.Strings[22340]="你觉着我看不出你那拙劣的伪装吗，$n？"
D.Strings[22341]="$r，世间有许多你无法了解的玄机。只有全知全能的主上才能洞悉一切。"
D.Strings[22342]="他早就预知你会来对付我。我亲眼目睹了你对我的同胞做过的事。但是，我是不会死在你手上的。"
D.Strings[22343]="别妄想了。我将以自己选择的方式离开这个世界。但是，我会遵照主上的意志卷土重来的！"
D.Strings[22344]="小声点。别被那些野兽发现啦！"
D.Strings[22345]="哎！你干什么呢？"
D.Strings[22346]="我从未见过这家伙。"
D.Strings[22347]="圣光在上！你杀死了乔伊，还抢走了肉！你是怎么找到我们的？"
D.Strings[22348]="你被咬了？"
D.Strings[22349]="回答我啊！你是不是被咬了？"
D.Strings[22350]="好吧，就算你要杀我，至少等我喂饱格里西达吧？我可怜的宝贝已经好些日子没吃过东西啦。"
D.Strings[22351]="宝贝，杀死乔伊的凶手很快就要对我们下手了，让我最后再喂你一次吧。"
D.Strings[22352]="喏，后面有灯油——你知道该怎么做吧。那帮混蛋对火焰又恨又怕！"
D.Strings[22353]="你怎么忍心对乔伊这样手无寸铁的老头下毒手？你把肉带回来又有什么企图？"
D.Strings[22354]="真是匪夷所思，我完全不明白你是怎么想的……我得说，我很难和你这样的家伙相处……"
D.Strings[22355]="你最好趁格里西达还没有胃口吃餐后甜点之前离开。"
D.Strings[22356]="既然已经找回了水晶球，那么我们就着手寻求真相吧！"
D.Strings[22357]="别拿琐碎的小事打扰我！"
D.Strings[22358]="发发慈悲吧！"
D.Strings[22359]="我只是奉命行事啊。求求你……"
D.Strings[22360]="我不想就这么死掉啊！"
D.Strings[22361]="你赢了。求求你放我走吧。"
D.Strings[22362]="可怜可怜我吧……"
D.Strings[22363]="韦斯温大人正在这一带巡视呢！如果再让我看见你在岗位上划水，我就把你撕成碎片。"
D.Strings[22364]="谢谢你，$c。"
D.Strings[22365]="我又能重新投入战斗了！"
D.Strings[22366]="哇咧！我差点死在这里。谢谢你，$r！"
D.Strings[22367]="你没看见我正忙着吗！再这样拖沓，我们是不可能在王子殿下归来之前修好这座基地啦！"
D.Strings[22368]="要不是那群混蛋烧毁了船只，我们早就到家啦。别来烦我了，我要回去工作啦！"
D.Strings[22369]="朋友，银色北伐军的部队已经抵达此地。我们不会让你独占所有荣耀的！"
D.Strings[22370]="欧瑞克，请再给我一瓶黑暗草药剂。"
D.Strings[22371]="朋友，很抱歉打扰到你了。你忙你的吧！"
D.Strings[22372]="你竟敢闯入猛犸人的领地？裂骨者要把你拍成肉酱！"
D.Strings[22373]="颤抖吧，鼠辈！"
D.Strings[22374]="好呀！我喜欢活蹦乱跳的食物。"
D.Strings[22375]="事情远没有结束……死亡……会令我……更加强大……"
D.Strings[22376]="让那群该死的农夫赶紧干活啊！我好想回到铁炉堡。实在是太想念我的老婆和孩子了。"
D.Strings[22377]="船长说，只要阿尔萨斯王子殿下回来，我们就能返回洛丹伦了。"
D.Strings[22378]="不知道王子殿下究竟是被什么事给耽搁了，但是我们真的坚持不了太久了。许多士兵都无法忍受如此严寒的气候。"
D.Strings[22379]="我相信阿尔萨斯殿下很快就会回来的。千万别气馁！"
D.Strings[22380]="看着那些被野蛮人烧毁的船只，我们的心情仿佛跌到了谷底。说实话，我从来没有觉得如此无助……"
D.Strings[22381]="愤怒。看着眼前这堆烂摊子，我实在是压抑不住心中的怒火。我们历尽艰辛，一路披荆斩棘穿越森林才来到海边，却发现还是迟了一步。返回家园的唯一希望已经破灭了。"
D.Strings[22382]="尽管这片冰霜废土给我们留下了痛苦的回忆，但我相信，年轻的王子殿下终将领导我们走向胜利。我夜夜祈祷，希望他能平安归来。"
D.Strings[22383]="我要出发了，士兵。保持警惕！"
D.Strings[22384]="<被遗忘的步兵摇了摇头。>$B$B我们快要支撑不下去了。阿尔萨斯王子殿下再不回来的话，我们都会没命的。"
D.Strings[22385]="我们不可能及时备好船只了。寒冬降临时，就是我们的末日。恐怕我们都被王子殿下遗弃了。"
D.Strings[22386]="阿尔萨斯殿下和穆拉丁殿下离开这里很长时间了。希望他们平安。"
D.Strings[22387]="一切都会好起来的。"
D.Strings[22388]="祝福你，朋友。我快……不行了……"
D.Strings[22389]="谢谢你，$r！"
D.Strings[22390]="就在我近乎绝望的时候，你为我带来了生的希望！"
D.Strings[22391]="要不是你，我肯定没命了……"
D.Strings[22392]="不！！！妈妈！！！我们会为你报仇的！"
D.Strings[22393]="啧啧，臭鼬、小白兔和小鹿结伴出游。这样的场景还真是少见啊。不过我的晚餐倒是有着落了！难得的野味啊！"
D.Strings[22394]="呀。我觉得吧，加尔鲁什倒也算得上是位勇士，可惜他很爱表现，老想着如何证明自己的实力。不过既然萨鲁法尔大王也在这里，我就安心啦。"
D.Strings[22395]="今天你想去哪儿呢？"
D.Strings[22396]="狩猎时间！"
D.Strings[22397]="加入上等的俱乐部可以为你的生活增添别样的风采。"
D.Strings[22398]="我要购买本月美酒。"
D.Strings[22399]="嘿，伙计！你手里拿的不是美酒节奖币吗？我恰好有一些美酒节物品要出售。"
D.Strings[22400]="我要立刻前往暮冬要塞！"
D.Strings[22401]="你好，$r！$b$b想找一台可以乘坐的伐木机？恐怕你得进入山岭啦。$b$b这台坏掉了。"
D.Strings[22402]="钥匙？什么钥匙？"
D.Strings[22403]="翻新过的伐木机的钥匙啊，笨！$b$b如果没有的话，你可以和我的兄弟塞尼普斯谈谈。"
D.Strings[22404]="够劲的啤酒才是好啤酒。"
D.Strings[22405]="你的兄弟在哪儿呢？"
D.Strings[22406]="事情是这样。在武装冲突爆发之前，我们利用伐木机来砍伐这里的树木。$B$B战争很快一触即发，我们不得不改装这些机器来对抗部落。要知道，翻新后的伐木机简直是超级厉害的战斗机器呢。如果你有钥匙的话，为什么不好好利用一番呢！"
D.Strings[22407]="能加入“本月美酒俱乐部”真是太棒了。"
D.Strings[22408]="当然是在河流上游啊！$b$b哈哈！在上游……嗯，你可以在蓝天伐木场找到他，这家伙大概正开着伐木机忙活呢。$b$b哦，顺便告诉他，如果他再送来半成品的伐木机，我就让他好看！"
D.Strings[22409]="我的兄弟塞尼普斯有很多伐木机。你可以前往北边的蓝天伐木场和他谈谈。"
D.Strings[22410]="抱歉，大使阁下，但王子殿下因故离开了。请问您来这片冰霜废土有什么事吗？"
D.Strings[22411]="根据皇家敕令，部队立刻返回洛丹伦。乌瑟尔大人已经说服国王陛下召回这支远征军。"
D.Strings[22412]="这么说我们要马上离开这里？"
D.Strings[22413]="没错。我的手下也报告说，从这里通向海岸的道路被亡灵占据了。你必须另找一条路回到船上。"
D.Strings[22414]="该死的亡灵！弟兄们，直接从森林中穿过去！"
D.Strings[22415]="上尉，卫兵怎么都不在自己的哨位里？"
D.Strings[22416]="呃，殿下，您的父王应乌瑟尔大人的请求召回了全军。"
D.Strings[22417]="乌瑟尔要召回我的军队？见鬼！如果战士们离我而去，我要怎么杀死玛尔加尼斯？必须要赶在他们回到海边之前烧毁船只！"
D.Strings[22418]="这是否太过分了，伙计？"
D.Strings[22419]="全都烧成灰烬！我们事业未尽，谁也不能提前回家！"
D.Strings[22420]="等等！把刀放下。你为什么……为什么要听他们的呢。你和他们截然不同啊！"
D.Strings[22421]="现在要怎么办呢？或许阿尔萨斯王子殿下今天就会回来呢！"
D.Strings[22422]="振作一点！或许我们今天就能离开这片被诅咒的土地！噢，铁炉堡！我真想家啊！"
D.Strings[22423]="不！！！！！"
D.Strings[22424]="阿尔萨斯！你这个骗子！我们都被你给害了！"
D.Strings[22425]="王子抛弃了我们！所有的希望都破灭了！"
D.Strings[22426]="叛徒，你还记得对我们许下的诺言吗！"
D.Strings[22427]="我们的性命远比你那所谓的血海深仇重要……"
D.Strings[22428]="这一切都是为什么？"
D.Strings[22429]="全是谎言……"
D.Strings[22430]="年轻的王子，愿你最憎恶的敌人撕裂你的灵魂！"
D.Strings[22431]="谢谢你。我……该离开啦。"
D.Strings[22432]="你对你的部下说谎，还背叛了为你而战的雇佣兵。你到底怎么了，阿尔萨斯？你就只有复仇这个念头了吗？"
D.Strings[22433]="别管我了，穆拉丁。你没见过玛尔加尼斯对我的家乡做了什么。"
D.Strings[22434]="只要集满足够的奖币就能加入“本月美酒俱乐部”。加入了“本月美酒俱乐部”就好象天天都过美酒节！$b$b每个月你都可以通过邮件收到一份新出的酒样。如果你喜欢的话，可以到铁炉堡的石火旅店向商人购买。"
D.Strings[22435]="本月美酒俱乐部"
D.Strings[22436]="与敌人开战吧！"
D.Strings[22437]="别让那些肮脏的兽人占领港口！"
D.Strings[22438]="不要对敌人心存怜悯！港口是我们的！"
D.Strings[22439]="不要给联盟狗喘息的机会，杀光他们！"
D.Strings[22440]="为部落的荣耀而战！"
D.Strings[22441]="只要集满足够的奖币就能加入“本月美酒俱乐部”。加入了“本月美酒俱乐部”就好象天天都过美酒节！$b$b每个月你都可以通过邮件收到一份新出的酒样。如果你喜欢的话，可以到奥格瑞玛精神谷的黑石南小屋向商人购买。"
D.Strings[22442]="%s扬起爪子，摆出威胁的架势！"
D.Strings[22443]="一切似乎都进展得很顺利。"
D.Strings[22444]="啧啧。你们真的很讨厌呢，难怪主人警告我说要小心对付。不过，你们的末日很快就会降临了。来自纳克萨玛斯的亡灵大军将席卷这里，彻底抹去你们存在过的痕迹。"
D.Strings[22445]="你以为自己能逃到哪儿去？老实点，把魔典给我吧，我或许会考虑让你死得痛快一点。"
D.Strings[22446]="冰霜废土的士兵们，聆听主人的召唤，站起来吧！夺下$n手中的魔典！"
D.Strings[22447]="它……不属于你……"
D.Strings[22448]="把……它……给我……"
D.Strings[22449]="%s注视着渐渐聚拢的村民，沉重地点了点头。"
D.Strings[22450]="死亡在等待……"
D.Strings[22451]="潮涨潮落，我来讲个故事吧。看看你们能否有所领悟。"
D.Strings[22452]="塞尔赞……会杀了你……"
D.Strings[22453]="海象人氏族自古就居住在这片冰封之地，看过数不尽的日出日落。"
D.Strings[22454]="我们生活在海陆交界处，尽情享受着大海的慷慨和恩赐。"
D.Strings[22455]="海洋与陆地赐予了我们生命。"
D.Strings[22456]="敌人打破了我们的宁静生活。他们有的想要夺取海洋的控制权。那些高大的维库人已经侵占了岸边的海象人圣地。"
D.Strings[22457]="本月美酒俱乐部？"
D.Strings[22458]="有的想要夺取陆地的控制权。那些盘踞在苔原地带的鳄鱼人大肆掠夺我们赖以为生的猎物。"
D.Strings[22459]="诅咒已经解除！"
D.Strings[22460]="塞尔赞的魔法失效了！我安全了！"
D.Strings[22461]="我们同样拥有猎手的敏捷和战士的勇气。我们愿意为了保卫家园而战。"
D.Strings[22462]="这本魔典到底隐藏着什么秘密？"
D.Strings[22463]="塞尔赞再也无法阻止我了！为了联盟！为了弗塔根公爵！"
D.Strings[22464]="但是，海象人氏族即将面临新的威胁。"
D.Strings[22465]="“本月美酒俱乐部”是什么东西？"
D.Strings[22466]="你还不知道“本月美酒俱乐部”？那是一群希望天天都是美酒节的可爱家伙！过去他们一直希望让美酒节回归，但每次持续的时间都不长。$b$b一旦你加入了这个俱乐部，每个月都能收到俱乐部邮寄来的最新酒样！如果你喜欢某种啤酒，可以到铁炉堡向商人购买。$b$b我觉得你也非常可爱，完全有资格加入这个俱乐部。只要给我一些美酒节奖币，我就会给你加入的申请表。然后我们或许就能天天一起庆祝美酒节了！"
D.Strings[22467]="%s低下头整理着思绪。"
D.Strings[22468]="万物体内都涌动着某种神秘的魔法力量。它有许多不同的称呼。"
D.Strings[22469]="海象人氏族称其为“希拉伊努亚”。"
D.Strings[22470]="所有的智慧生物都能支配这种力量，利用它来医治创伤或是荼毒生灵。它就是生命的源力，是死者与生者的灵魂之力。"
D.Strings[22471]="世间唯有一种生物能束缚“希拉伊努亚”，由此引发了诸多祸端。他们被称为蓝龙一族。"
D.Strings[22472]="强大的蓝龙拥有操纵“希拉伊努亚”的能力，他们计划将这种力量从其他生物体内夺走。"
D.Strings[22473]="这不仅是对海象人氏族的威胁，更是将世间的生灵推上了绝路。"
D.Strings[22474]="那些亡灵竟然来自我们的墓地！"
D.Strings[22475]="让我告诉你们。"
D.Strings[22476]="你做到啦！我还以为你会赔上性命呢！"
D.Strings[22477]="我们必须勇敢地战斗，否则敌人将会屠杀我们的孩子，彻底抹去海象人氏族存在过的痕迹。我们必须凭借自己的力量拯救整个氏族。"
D.Strings[22478]="与此同时，我们应该竭尽全力帮助来自南方的人们，因为他们就是“希拉伊努亚”的勇士。"
D.Strings[22479]="你还在这里干什么呢？赶紧回到镇上去！"
D.Strings[22480]="让我来治疗你吧。你很快就能重返战场啦。"
D.Strings[22481]="我的图腾能治愈你的创伤。"
D.Strings[22482]="天灾军团竟敢招惹我们！"
D.Strings[22483]="我们誓死保卫家园！"
D.Strings[22484]="皇帝陛下命令我们死也要守住这里！"
D.Strings[22485]="天灾军团想要侵占我们的土地？给他们点颜色瞧瞧！"
D.Strings[22486]="我们做好了反击的准备！"
D.Strings[22487]="阻止天灾军团！"
D.Strings[22488]="休想过去！"
D.Strings[22489]="塔里奥斯塔兹，请允许我搭乘龙兽前往神殿顶端女王陛下的王廷。"
D.Strings[22490]="这些科多兽的状况好极了。"
D.Strings[22491]="是啊，听说是位部落老兵将它们从濒死边缘救回来的。"
D.Strings[22492]="阿莱克丝塔萨女王任命我负责龙眠神殿的防务工作。$B$B但如你所知，玛里苟斯和他的军团摧毁了附近一处魔网能量线的锚点。蓝龙军团将其中的能量导向了碧蓝巨龙圣地。$B$B毫无疑问，他们是想利用这种能量强化自己，伺机向神殿发动攻击！我们已渐渐处于劣势。$B$B$r，你愿意帮助我们吗？"
D.Strings[22493]="%s为迷失的灵魂念诵了一段祷言。"
D.Strings[22494]="退后点，$n。这头野兽可能会突然暴起伤人。"
D.Strings[22495]="高弗雷！你这恶魔！你听仔细了！我要代表圣光将你从邪恶中拯救出来！"
D.Strings[22496]="很好。高弗雷，你肯听我说话了。"
D.Strings[22497]="高弗雷，这事儿吧有两种解决方式，我更喜欢开门见山的做法。你看，不如你直接告诉我秘典上的邪恶符号是什么含义。怎么样？"
D.Strings[22498]="%s发出嘶嘶声。"
D.Strings[22499]="我不会告诉你的，你这神棍。"
D.Strings[22500]="你能把我怎么样？你莫非比克尔苏加德更残忍？比巫妖王更厉害？"
D.Strings[22501]="你说得没错，这本秘典是拯救你们的唯一希望……但是你休想知道！我不会说的！绝不！"
D.Strings[22502]="好吧，那我就要用第二种解决方式了。"
D.Strings[22503]="迷失的灵魂，我会为你念上一段祷言。愿圣光拥你入怀。"
D.Strings[22504]="训诫开始。"
D.Strings[22505]="让圣光拥抱你吧，野兽！"
D.Strings[22506]="屈服在圣光的力量下吧！"
D.Strings[22507]="让圣光渗入你的灵魂，高弗雷！"
D.Strings[22508]="别抵抗了，恶魔！赎罪的时候到了！"
D.Strings[22509]="在圣火中化为灰烬吧！"
D.Strings[22510]="在辉煌的圣光面前，巫妖王的力量显得苍白无力！"
D.Strings[22511]="火焰！！！"
D.Strings[22512]="我说，什么都说！"
D.Strings[22513]="圣光！不要！求求你！"
D.Strings[22514]="我从未体验过这样的煎熬！"
D.Strings[22515]="高弗雷，你已经见识到圣光的力量了……恶魔，说吧。秘典上都写了些什么？"
D.Strings[22516]="秘典中记载了即将到来的天启。世界将在灰烬中毁灭，然后重获新生。"
D.Strings[22517]="一派胡言！高弗雷，你当我是傻子吗？别拿天灾军团那套邪说来恐吓圣光的战士！你放聪明点，不然我就叫人把你丢进装满圣水的木桶，像给狗除跳蚤那样让你冲个圣水浴！"
D.Strings[22518]="不要啊！！！我说！我什么都说！！！"
D.Strings[22519]="人类……自作孽。纳克萨玛斯为什么会攻击这里？就因为你们在暮冬城地下建起的陵墓！塞尔赞躲在你们的墓穴中，唤醒成千上万的僵尸与你们为敌！你们将被毁灭……"
D.Strings[22520]="什么！？暮冬城旧址下面有一座陵墓？我们对此事竟然毫不知情！高弗雷，我们会消灭你的主子，结束这场噩梦。"
D.Strings[22521]="高弗雷，我们自会对付塞尔赞。"
D.Strings[22522]="你们打算如何对付他？人类真是既天真又愚蠢。居然想打败黄昏使者塞尔赞！为了获得力量，他牺牲了原本的血肉之躯。巫妖王庇佑着如今的巫妖塞尔赞！"
D.Strings[22523]="你们不可能阻止塞尔赞！他拥有巫妖王陛下赐予的黑暗之能！"
D.Strings[22524]="$n，向哈尔弗汇报这位“坦诚”的市长先生招供的情报吧。剩下的事交给我解决，说不定还能从他口中榨出一些有关塞尔赞的消息呢。现在，我就让高弗雷见识一下罕见的“第三种解决方式”。"
D.Strings[22525]="来吧，我们开诚布公地谈一谈。"
D.Strings[22526]="你们在死后也别想得到安宁！"
D.Strings[22527]="站起来吧……吞噬他们的血肉！"
D.Strings[22528]="巨龙的时代即将终结……"
D.Strings[22529]="反抗是毫无意义的。你们终将被浩浩荡荡的亡灵大军践踏在脚底！"
D.Strings[22530]="你们倒下的伙伴将为亡灵大军注入新鲜的血液。你们没有希望获胜。"
D.Strings[22531]="放弃缥缈的希望吧。你们注定会失败！"
D.Strings[22532]="为了联盟，为了弗塔根公爵！"
D.Strings[22533]="啊！骑兵队到啦！"
D.Strings[22534]="技术不错啊！我们毫发无损！"
D.Strings[22535]="要不是你，我们就死定了。谢谢你带我们回来！"
D.Strings[22536]="返回腐臭平原，否则载具将被摧毁！"
D.Strings[22537]="回到船上去！"
D.Strings[22538]="逃出这里！"
D.Strings[22539]="我们会没命的！"
D.Strings[22540]="我不管啦！我要回家！"
D.Strings[22541]="我根本不想呆在这里！"
D.Strings[22542]="别让那些坏人靠近我！"
D.Strings[22543]="别让他们靠近我！我保证能在15秒内搞定这玩意儿。"
D.Strings[22544]="看着吧，我会把这台天灾战车包装得像是地精的工程制品！保护我！"
D.Strings[22545]="%s娴熟地装配出一台外形奇特的机械。"
D.Strings[22546]="过来吧。我给你们讲个故事。"
D.Strings[22547]="就快搞定啦！再给我几秒钟。"
D.Strings[22548]="敌人来啦！低头！"
D.Strings[22549]="注意头顶！敌人发动了低空袭击！"
D.Strings[22550]="攻击！肃清敌人！"
D.Strings[22551]="燃烧吧，恶魔！"
D.Strings[22552]="前进！有条巨龙来帮助我们啦！"
D.Strings[22553]="红龙来啦！"
D.Strings[22554]="觉醒吧，阿鲁高！巫妖王的力量命令你觉醒！"
D.Strings[22555]="对……他完全符合我们的要求。请你将他送去冬至村吧。如果我们不能按时完成阿尔萨斯陛下交代的任务，他会不满意的。"
D.Strings[22556]="嗨，$c。你瞧见了吗？水面上那是什么玩意儿……$b$b你到底看清楚没有啊？"
D.Strings[22557]="你是说冰山吗？"
D.Strings[22558]="冰……冰山？？$b$b呃，我是指漂在空中的不明障碍物。在我的家乡，大家都说没有见过此类物体。$B$B我是真的见过！还在近处观察过它们呢！喏，这艘船就是我近几年的创造结晶，为的就是追踪并记录这些不明物体并且在必要的时候摧毁它们！"
D.Strings[22559]="你的计划竟然成功了，我真是又惊又喜。"
D.Strings[22560]="这艘船……仅仅是为了检查浮冰？"
D.Strings[22561]="我们不能让你回到同伴身边，也不能让你和我们呆在一起……"
D.Strings[22562]="等等！你说过如果我帮你的忙，你就放我一条生路的。我可是一直遵照约定帮助你的！"
D.Strings[22563]="酋长，刀下留人。他还有利用价值。"
D.Strings[22564]="$r，别被假象蒙蔽了双眼。那些不明物狡猾着呢。前一秒你还能看见它们，转瞬之间就消失得无影无踪——简直是匪夷所思！$b$b我告诉你一个秘密，不许说出去哦。我曾经搞到过一块碎片！可惜在我进行测试实验之前，它就莫名地消失了！就像蒸发了似的……不见了……"
D.Strings[22565]="只是冰块而已吧。你也太大惊小怪了。"
D.Strings[22566]="还记得你找到的那本矮人日记吗？呃，它的主人很可能就是我们追捕布莱恩·铜须的重要线索。"
D.Strings[22567]="圣光在上，布莱恩还活着？我死也不会帮你追捕他的！"
D.Strings[22568]="我相信你会的，除非你想为难自己。"
D.Strings[22569]="托尔玛克，你对此满意吗？"
D.Strings[22570]="他还有利用价值，就留着他吧。矮人，如果我是你的话，我会更加谨慎的。"
D.Strings[22571]="你能听到许多关于不明物体的传说……$b$b有人说它们在观测冰洋，有人说它们试图改变海洋的生态系统，还有人认为它们是来接管艾泽拉斯世界的！$b$b等我用火箭推进弹头将它们打得粉碎，就能找到答案了。相信我！"
D.Strings[22572]="畜生！快说！我的妹妹在哪儿，否则我不会放过你们的。"
D.Strings[22573]="等等！别开枪！不要伤害塔特亚娜！"
D.Strings[22574]="囚犯们被关押在山脉另一侧的狼穴中。你说的姑娘很快就会被送到阿鲁高那里了。我们可以走了吗？"
D.Strings[22575]="原谅我，塔特亚娜……"
D.Strings[22576]="和阿鲁高比起来，你对我们的威慑力差得远了！我要将你撕成碎片！"
D.Strings[22577]="安娅在哪儿？"
D.Strings[22578]="只剩最后一件事了。我必须知道阿鲁高的下落。"
D.Strings[22579]="谢谢你帮我返回营地。请转告瓦尔特，就说我已经平安无事啦！"
D.Strings[22580]="他会吃掉小毛球的！你得帮帮小毛球！帮帮小毛球呀！"
D.Strings[22581]="小毛球遇到大坏蛋啦！救命啊！"
D.Strings[22582]="是营地！小毛球，我们很快就要到家啦！快点！"
D.Strings[22583]="你好，$r。$B$B我一直在盼着你。"
D.Strings[22584]="我们要投身战斗了。准备好了吗？"
D.Strings[22585]="很好，出发！"
D.Strings[22586]="机会来了，兄弟们！推进！"
D.Strings[22587]="推进！逼他们撤退到圣地！"
D.Strings[22588]="推进！逼他们撤退，消灭他们！"
D.Strings[22589]="推进！杀出一条通往圣地的血路！"
D.Strings[22590]="灰烬之龙来了！撤退！撤退！"
D.Strings[22591]="敌袭！撤回通道！"
D.Strings[22592]="撤退！灰烬之龙来了！"
D.Strings[22593]="我们会设法牵制住敌军。你，进入圣地干掉那些通灵师！"
D.Strings[22594]="我们坚持不了多久的！快进入圣地，阻止通灵师的仪式！"
D.Strings[22595]="我们会尽量拖延敌军！你一定要抓紧机会进入圣地！"
D.Strings[22596]="让我们一起加入战斗吧，$n！"
D.Strings[22597]="栖息在诺森德山峰上的狮鹫是适应性最强的物种。"
D.Strings[22598]="高级指挥官说你可以送我前往索尔森的岗哨。"
D.Strings[22599]="朋友，狮鹫骑士距离我们仅十步之遥。他们会送你前往索尔森的岗哨。准备出发吧！"
D.Strings[22600]="我已经将酬劳发给$n了！"
D.Strings[22601]="你不会吃掉我的，对吧？"
D.Strings[22602]="安娅！！你平安无事！"
D.Strings[22603]="邪月岛？是血月岛吧？"
D.Strings[22604]="别害怕……现在你安全啦。"
D.Strings[22605]="姐姐！那些卑鄙的家伙打算将我带去邪月岛，把我变成他们的一员。"
D.Strings[22606]="对，就是那个岛屿！邪月岛！萨莎……别再离开我啦！他们抓走了爸爸，然后又抓走了你……我不想和他们单独相处！"
D.Strings[22607]="不要以为过去的成就能为你带来任何权利与荣耀，$n。$B$B想要得到我的尊重，你必须证明自己。也就是说，你要遵循我的指令，并且毫无异议地完成使命。"
D.Strings[22608]="索尔森的岗哨——就在前面！"
D.Strings[22609]="坐稳啦！可能会出现颠簸。"
D.Strings[22610]="低下头，避开冰霜巨龙！呀～！"
D.Strings[22611]="我们到啦。安全着陆！"
D.Strings[22612]="放出战犬！"
D.Strings[22613]="出发！"
D.Strings[22614]="发现憎恶！第5营，让我们去教训教训他们吧！"
D.Strings[22615]="召集狮鹫！"
D.Strings[22616]="冲向前线！"
D.Strings[22617]="让他们感受到你手中的战锤之怒吧！"
D.Strings[22618]="还不够！让他们尝尝第5营的厉害！"
D.Strings[22619]="笼罩你的寒气就是厄运的先兆。"
D.Strings[22620]="协助防御！快点，废物们！"
D.Strings[22621]="你好。侍从瓦尔特和我负责照看老马布兰契和其他马匹。"
D.Strings[22622]="你好，$r。$B$B如果你愿意帮助我们保卫神殿的话，请入内与指挥官阿弗拉沙斯塔兹谈一谈。"
D.Strings[22623]="感谢你们，凡人。蓝龙军团已经察觉到你们的动向，你们要当心。眼下，玛里苟斯任命瓦尔洛斯·云击率领碧蓝魔环卫士死守魔环。请接受我们的帮助，这样才有机会击败敌人。"
D.Strings[22624]="对不起，$r，我刚刚才为你召唤了一名防御者。$B$B你得容我休息一会儿，我才能再次召唤。"
D.Strings[22625]="我一直守护着这座被阿莱克丝塔萨女王祝福过的圣地，光阴荏苒……连我都不记得度过了多长时间。在最为黑暗的年代，我未能尽到自己的职守……我倒在了死亡骑士血毒的脚下。"
D.Strings[22626]="巫妖王已经伸出魔爪……肆无忌惮地践踏着龙族最神圣的领地。他想逼迫我们采取行动。"
D.Strings[22627]="我的时日不多了……我为阿莱克丝塔萨女王奉献了一生，可死亡终将阻断我的奉献之意。红玉巨龙圣地需要一名新的守护者。"
D.Strings[22628]="谢谢你……谢谢你将我从被诅咒的枷锁中解救出来。你是个英雄……我知道你还会干出惊天动地的大事来的。"
D.Strings[22629]="达莉亚想起那个名字，往地上啐了口口水。"
D.Strings[22630]="达莉亚之魂逐渐消失了……"
D.Strings[22631]="欢迎来到欧尼瓦营地。"
D.Strings[22632]="掷杯训练器不仅仅是用来投掷啤酒杯的靶子，更是宝贵的训练设备。如果你能击中它，那你就能击中任何东西！$b$b可不要砸到我哦。"
D.Strings[22633]="我想坐在绿龙背上飞翔。"
D.Strings[22634]="贝加里斯塔兹说得没错，这里的局势非常严峻。\n\n我能赐予你召唤绿龙的能力。如果你想要召唤红龙或青铜龙，就得和贝加里斯塔兹或伊特努斯谈谈。"
D.Strings[22635]="瓦尔洛斯·云击和他率领的碧蓝魔环卫士保卫着第二环。你的幼龙足以制服那些魔环卫士，但是瓦尔洛斯利用魔环的能量撑起了一面难以渗透的魔法护盾。分布在魔枢第二环以及顶部平台的10个离心构造体负责为护盾充能。只有摧毁它们，你才有机会打破瓦尔洛斯的护盾并击败他。\n\n我能赐予你召唤红龙的能力。如果你想要召唤青铜龙或绿龙，就得和伊特努斯或沃尔蒂萨谈谈。"
D.Strings[22636]="我想坐在红龙背上飞翔。"
D.Strings[22637]="贝加里斯塔兹说得没错，时间紧迫！\n\n我能赐予你召唤青铜龙的能力。如果你想要召唤红龙或绿龙，就得和贝加里斯塔兹或沃尔蒂萨谈谈。"
D.Strings[22638]="我想坐在青铜龙背上飞翔。"
D.Strings[22639]="指挥官，我准备好出发了。"
D.Strings[22640]="阿弗拉沙斯塔兹，请让我参与保卫神殿的战斗。"
D.Strings[22641]="为女王而战！为保卫龙眠神殿而战！"
D.Strings[22642]="蓝龙军团敢向神殿发动攻击，他们活腻了吧。"
D.Strings[22643]="我会竭尽全力投身战斗！"
D.Strings[22644]="蓝龙军团从碧蓝巨龙圣地获得了强大的力量，但是我们绝不允许他们攻陷龙眠神殿！"
D.Strings[22645]="听说蓝龙军团将一条能量线的能量全部引向了碧蓝巨龙圣地。我会竭尽全力守护龙眠神殿的。"
D.Strings[22646]="猖狂的玛里苟斯居然让他的部队进攻龙眠神殿！请让我参与保卫神殿的战斗，我愿意为此付出生命的代价。"
D.Strings[22647]="我们来这里做什么？"
D.Strings[22648]="完成我们应尽的使命。"
D.Strings[22649]="不惜一切代价，守住神殿！"
D.Strings[22650]="谢谢你，朋友。出发吧。"
D.Strings[22651]="很遗憾，我们必须战斗。"
D.Strings[22652]="去吧。请你平安归来。"
D.Strings[22653]="去吧，我允许你参与战斗。"
D.Strings[22654]="我不曾料到局势会发展到今天这步田地。"
D.Strings[22655]="我看见了一辆天灾战车！"
D.Strings[22656]="萨多尔大桥是我炸毁的！我难道没有告诉你们？真的，所谓黑铁矮人破坏了大桥，那都是谣传！我才是真凶！"
D.Strings[22657]="这样毫无道理啊。为什么天灾军团不将纳克萨玛斯飞到暮冬要塞上空，然后直接炸毁它呢？我是说，如果我是克尔苏加德，肯定这么做啦。"
D.Strings[22658]="或许有一天，我们能揭开这种神秘矿石的真面目。那时我们就可以好好利用它啦。"
D.Strings[22659]="嘿，你们认识瓦加德的米克高维尔吗？他是我的叔叔哦。那你们知道他的头衔吗？“专家。”听听，多帅气啊。我也想成为一名专家。"
D.Strings[22660]="什么东西这么臭啊！肯定不是我。侏儒散发着黄油和阳光的味道，才不像那些脏兮兮的矮人。他们简直像从穴居人的腋窝里爬出来的一样！这里没有矮人，对吧？"
D.Strings[22661]="我认识一个矮人，这家伙宣称侏儒是从地下进化来的。我们的祖先是沙漠侏儒。简直是一派胡言！还沙漠侏儒呢！我呸！"
D.Strings[22662]="我从未见过如此严重的破坏程度……"
D.Strings[22663]="安静！我们要保持警惕！"
D.Strings[22664]="死亡的气息覆盖着这里的每一寸土地。"
D.Strings[22665]="听说你独自一人就将村民们空运到安全地带，使他们免受苦难的折磨。是真的吗？"
D.Strings[22666]="有谁知道塞尔赞吗？他是谁？他是如何成为统领天灾军团地面部队的统帅的？"
D.Strings[22667]="瞧瞧眼前的惨状……天灾军团会此付出代价的！"
D.Strings[22668]="尸体都到哪儿去了？他们对村民们做了什么？"
D.Strings[22669]="我希望自己能亲眼目睹阿尔萨斯接受命运的审判！"
D.Strings[22670]="天哪！快灭火！"
D.Strings[22671]="冬幕节快乐！"
D.Strings[22672]="大部分血精灵都对部落的“野蛮习气”嗤之以鼻，我当然也不例外。当我刚刚被派到这又潮湿又……芳香的地方时，我觉得自己实在是太不走运了。$B$B渐渐地，我发现这里的环境还是挺棒的。你觉得呢？$b$b我的研究工作也觉得了不小的进展。嗯，只需一个小法术，法师们就能回到这里哦。你想学习吗？"
D.Strings[22673]="大部分血精灵都对部落的“野蛮习气”嗤之以鼻，我当然也不例外。当我刚刚被派到这又潮湿又……芳香的地方时，我觉得自己实在是太不走运了。$B$B渐渐地，我发现这里的环境还是挺棒的。你觉得呢？$b$b我和你废什么话呢……你又不是法师，对我的研究肯定没兴趣。"
D.Strings[22674]="啊，我热爱斯通纳德的气息。就好像……好像……兽人的汗液。还混合着腐烂的味道。你知道，混合的气味总是很好闻的！"
D.Strings[22675]="很多人抱怨这里的潮湿气候，不过我发现它对皮肤很有好处！没有水分的皮肤可不会吹弹欲破。"
D.Strings[22676]="我的同胞们无法领略这种感觉——当你真正融入某种文化时所感受到的好处，这真是太遗憾了。"
D.Strings[22677]="你看，我现在就住在一座简陋不堪的石头哨塔里，望着外面泥泞的沼泽。大堆的苍蝇蚊虫到处乱飞，面如菜色、长满肉瘤的奇怪绿色生物四下游荡。我还能比现在更开心吗？"
D.Strings[22678]="在被指派到这里之前，我只是听说过泥巴浴的保健效果而已。当我被一条树根绊倒在地后，我才真正体会到了它的好处！大自然真是奇妙啊，不借助魔法也可以产生如此奇妙的效果！"
D.Strings[22679]="一直以来我都在思考一个问题，那就是，我为什么会被选中，来到这个地方。我只能认为是我的上级觉得只有我才能胜任这样的任务，迅速适应部落的独特文化，但是坊间还有一个听起来很伤自尊的说法，那就是因为我说话太多了。"
D.Strings[22680]="嗯？哦，请原谅我的心不在焉。我正在为北方城堡的伙计们担心，我应该派些学徒去帮他们的……你有什么事吗？"
D.Strings[22681]="嗯？哦，请原谅我的心不在焉。我正在为北方城堡的伙计们担心，我应该派些学徒去帮他们的……"
D.Strings[22682]="安静。"
D.Strings[22683]="还记得精灵们来这里之前的安静日子吗？我真怀念那时候。"
D.Strings[22684]="闭嘴。"
D.Strings[22685]="我不知道到底谁更疯狂一些。"
D.Strings[22686]="我愿意用我的捣药杵换个耳塞。"
D.Strings[22687]="我的魔法只传授给法师。很抱歉，$c。"
D.Strings[22688]="Sinu a'manore。如果你想要学习开启一道通向塞拉摩的传送门的法术，我可以帮你。"
D.Strings[22689]="你要学会尊重大自然，瑟尔希！"
D.Strings[22690]="与第一届相比，美酒节已经发生了一些变化。今年，我们发行的是美酒节奖币，而不是奖券啦。如果你手里还有旧的奖券，我可以帮你兑换。"
D.Strings[22691]="我要把背包里的奖券兑换成新的奖币。"
D.Strings[22692]="谁在不停地搞破坏？"
D.Strings[22693]="每次我修好邮箱之后，不到一天它就又坏掉了。"
D.Strings[22694]="如果让我抓住破坏影像生成器的混账……"
D.Strings[22695]="嗯。似乎邮箱又恢复正常啦……"
D.Strings[22696]="女士们，先生们……欢迎来到斗兽场！"
D.Strings[22697]="下面我向大家介绍……$n，闻名于世的$c。$g他:她;是猛兽、机械构造体以及龙……龙族的终结者！你一定不曾见过这样的人物。"
D.Strings[22698]="接下来，$n的对手。这位令人闻风丧胆的连环杀手曾被判以多种极刑！他就是……霍尔格雷·地狱之斧！女士们，先生们……下注吧！"
D.Strings[22699]="女士们，先生们，欢迎来到征服斗兽场！见证$r与巨熊的激战！下注吧！"
D.Strings[22700]="你未曾见过的激战即将在征服斗兽场中上演！$n将挑战一头来自灰熊丘陵的熊怪！快下注吧！"
D.Strings[22701]="来吧！揣上一壶热酒，挑个好位子，观看$r与机械生物之间的决战！"
D.Strings[22702]="它就是来自索尔莫丹，由百分百……纯……金属打造而成的闪电动力铁人——锈血！"
D.Strings[22703]="明年会有更多新惊喜！"
D.Strings[22704]="这是烟林牧场为你带来的惊喜！"
D.Strings[22705]="很抱歉，我已经筋疲力尽了，不能运用魔法将你送回塞拉摩岛。你是位经验丰富的探险家吧，应该知道如何返回那里。"
D.Strings[22706]="$r，想要搭乘双足飞龙吗？$B$B或者你有什么烦心事儿想向我倾诉？"
D.Strings[22707]="哟，你连宠物也带来啦。"
D.Strings[22708]="我们有必要闹得这么僵吗？"
D.Strings[22709]="面对困境，我做出了明智的判断，而你却束手无策。克雷娜，我不愿意眼睁睁地看着你将我们带上绝路！"
D.Strings[22710]="明智的判断？你的宠物呢？$n在哪儿？"
D.Strings[22711]="你背着我耍花招，无视我的命令。你会付出代价的。"
D.Strings[22712]="够了。这场战斗结束后，我与你便再无瓜葛。那时，即便是座狼，也不愿意靠近你的尸体。"
D.Strings[22713]="女士们，先生们！我说……你们一定不想错过这场战斗吧！"
D.Strings[22714]="为什么……为什么？我们非要闹到这步田地吗？"
D.Strings[22715]="我想用红玉精华换取翡翠精华。"
D.Strings[22716]="我想用琥珀精华换取翡翠精华。"
D.Strings[22717]="火箭推进弹头？是不是太夸张啦？"
D.Strings[22718]="听着。想知道不明物的真相，最好是制造一场爆炸——当然是越大越好啦！$b$b不过眼下还有很多问题没有解决，$r。$b$b这些弹头都是由机密材料制成的，而作为推进能量源的115号元素就更加机密啦！$b$b事实上，你最好假装从来没有见过我，继续过你的安稳日子去。"
D.Strings[22719]="我想用翡翠精华换取琥珀精华。"
D.Strings[22720]="我想用红玉精华换取琥珀精华。"
D.Strings[22721]="我想用琥珀精华换取红玉精华。"
D.Strings[22722]="我想用翡翠精华换取红玉精华。"
D.Strings[22723]="我想去龙眠神殿中层，与阿弗拉沙斯塔兹指挥官谈一谈。"
D.Strings[22724]="指挥官，我想去龙眠神殿顶层。"
D.Strings[22725]="欢迎你，冒险家。你来的正是时候。"
D.Strings[22726]="塞尔赞必须死，只有这样才能使怨灵停止那永无止境的哭泣！"
D.Strings[22727]="阿弗拉沙斯塔兹，能让我返回神殿底层吗？"
D.Strings[22728]="暮冬要塞的市民与官员联名发布的官方公告。"
D.Strings[22729]="能让我搭乘幼龙前往龙眠神殿中层，与阿弗拉沙斯塔兹会面吗？"
D.Strings[22730]="面对黑龙令你感到不安吗？$B$B很好。的确如此。在黑龙面前，其他龙族也会心生胆怯。这一点倒是继承了他们的祖先的美德——瞧，他们根本不敢攻击我。$B$B一帮蠢货。"
D.Strings[22731]="接下来介绍纳克萨玛斯恐怖的天灾区。天灾军团在这里进行药理研究，企图改良他们在洛丹伦传播的药剂。"
D.Strings[22732]="接下来介绍纳克萨玛斯被诅咒的蜘蛛区。天灾军团在这里培育蛛怪的变种，以便繁殖出毒性更厉害的危险生物。"
D.Strings[22733]="接下来介绍纳克萨玛斯毒气缭绕的憎恶区。天灾军团在这里制造大批强壮而丑陋的怪物，以此扩充他们的军事武装力量。"
D.Strings[22734]="接下来介绍纳克萨玛斯的死亡骑士区。在腐化力量的侵蚀下，我们最杰出的战士沦为了天灾军团的走狗。如今，战争的号角日夜在死亡骑士区的大厅中回荡。"
D.Strings[22735]="接下来介绍盘踞在纳克萨玛斯顶端的生物。他们拥有无可思议的强大力量，当之无愧地被冠以诺森德两大威胁的称号。"
D.Strings[22736]="这是药剂师诺斯。天灾军团将人们囚禁在冰冷的死灵牢笼的计划，便是他提出的创意。至今，诺斯仍然负责监督并完善这一流程。"
D.Strings[22737]="这是肮脏的希尔盖。他就是指挥天灾军团利用天灾之锅将艾泽拉斯宁静的旷野变成瘟疫之地的罪魁祸首。"
D.Strings[22738]="据说希尔盖对纳克萨玛斯的墙壁和地板进行了改造，设置了大量可以随意触发的可控陷阱。"
D.Strings[22739]="洛欧塞布。据说这个由瘟疫之地的活性诅咒与艾泽拉斯的沼泽兽缝合而成的怪物有着自我愈合的能力。"
D.Strings[22740]="这尊影像就留给你们观察吧。仔细研究对手的能力，他的优势很可能也是致命的弱点。"
D.Strings[22741]="注意。这是教官拉苏维奥斯，由克尔苏加德亲自指派的死亡骑士训练师。这位威严的教官拥有独特的教学法则，据说只有他的学徒才有可能承受得住他的威力。"
D.Strings[22742]="收割者戈提克。作为巫咒与魔法的大师，据说戈提克能瞬间召唤出亡灵军团为他作战。在他的指导下，即便是能力最弱的死亡骑士也能令亡者复生。"
D.Strings[22743]="天启四骑士是纳克萨玛斯中最强大的死亡骑士，是克尔苏加德麾下最顶尖的护卫。首先介绍库尔塔兹领主，他能操纵火焰的力量。"
D.Strings[22744]="下一位是女公爵布劳缪克丝。她能召唤暗影的力量，吞噬活人的灵魂。"
D.Strings[22745]="瑟里耶克爵士。生前他是一名信仰坚定的圣骑士，虽然他已是死灵之躯，却依然能召唤圣光的力量惩击敌人。"
D.Strings[22746]="最后一位死亡骑士是大领主莫格莱尼。他曾经是一名杰出的战士，最优秀的死亡骑士在他面前也会黯然失色。但是，当他在艾泽拉斯经历了一系列的变故后，便消失得无影无踪了。目前还不知道克尔苏加德指派了谁来取代他的位置。"
D.Strings[22747]="阿努布雷坎，艾卓-尼鲁布最杰出的蛛怪领主之一。多年前，他与蛛怪之王阿努巴拉克都惨败在巫妖王手中，此后便被天灾军团控制了。据说他曾是阿努巴拉克麾下最忠诚的领主。"
D.Strings[22748]="听着，$r。$B$B想找一台能驾驶的伐木机，你恐怕得进入北面的山岭。$b$b这台已经坏掉了。"
D.Strings[22749]="一开始我们只是利用这些机器砍伐森林，但是自从联盟踏上这片土地，战争就愈发频繁起来。我们这才发现，原来翻新过的伐木机也能充当战争机器。$b$b$c，相信我。如果你有伐木机钥匙的话，干嘛不试着驾驶一下呢。"
D.Strings[22750]="黑女巫法琳娜。生前她是一位植物学家，死后她为巫妖王效力，负责管理蜘蛛区的蛛怪培育与毒药研制工作。"
D.Strings[22751]="格利克有很多钥匙。$b$b如果你肯帮他的忙，他或许会考虑送你一把。下次你造访蓝天伐木场时，记得找他谈谈。"
D.Strings[22752]="迈克斯纳。数百年前，这只出生在诺森德冰峰深处的蜘蛛就被天灾军团虏进了纳克萨玛斯。她在这座恐怖之城中繁衍后代，那些胆敢进入纳克萨玛斯的冒险者都沦为了蜘蛛的美餐。"
D.Strings[22753]="这是帕奇维克。圣光兄弟会第一次听闻他的传言时，没有谁相信憎恶也能拥有如此迅捷的速度和可怕的力量。当帕奇维克初战告捷后，大家便不再认为那是谣言了……"
D.Strings[22754]="格罗布鲁斯，天灾军团制造的血肉巨人。格罗布鲁斯体内蠕动着纳克萨玛斯的软泥怪，能侵蚀给任何敢于靠近它的敌人。被注入软泥怪的受体通常会逃回盟友身边，顷刻之间就能击溃所有人。"
D.Strings[22755]="格拉斯，纳克萨玛斯肮脏的天灾犬。据说这只野兽极其贪婪，每天费尔根都会给它送去一批缺乏作战力的亡灵。格拉斯堪称是天灾军团废物利用系统的终端。"
D.Strings[22756]="塔迪乌斯，用女人与孩子的血肉缝合而成的巨人。据说他们的灵魂也融入塔迪乌斯体内，永远被禁锢在这肮脏的囚牢中。"
D.Strings[22757]="萨菲隆。它本是高贵的蓝龙，自由地翱翔在诺森德的冰峰间，被征战极寒之地的阿尔萨斯所杀。克尔苏加德复活了萨菲隆，如今这头冰霜巨龙守卫着主子的巢穴，等待那些胆敢挑战克尔苏加德的冒险者。"
D.Strings[22758]="巫妖克尔苏加德。显然他为巫妖王效力。克尔苏加德生前是一名强大的通灵师，死后自然而然地成为了巫术大师。据说他是巫妖王最忠诚的部下。"
D.Strings[22759]="克尔苏加德通过了最为严酷的试炼。即便是圣光兄弟会的成员，这样的试炼也会撼动他们的灵魂。克尔苏加德将自己的生命完完全全交给了阿尔萨斯，然后借助太阳之井的力量得以复生。"
D.Strings[22760]="克尔苏加德再次被驻扎在瘟疫之地的银色黎明击败。可是他的护命匣落到了圣光兄弟会某个不忠诚的成员手中。至今我们还不知道是谁偷走了护命匣以及其中的阴谋。"
D.Strings[22761]="快出来！我会掩护你的！"
D.Strings[22762]="到我身边来！我用枪掩护你！"
D.Strings[22763]="%s凝视着莫度鲁的德拉诺礼袍。"
D.Strings[22764]="诺哈因，你说莫度鲁为什么还穿着这件可笑的袍子啊。他看上去就像那些刚刚逃出埃门谷的乡巴佬似的。"
D.Strings[22765]="火枪手，营救那些士兵！速度！"
D.Strings[22766]="这是营救他的好时机！快去！"
D.Strings[22767]="火枪手，停止射击！那名士兵就在射程的安全范围之内！快去救他！"
D.Strings[22768]="旧斯坦索姆……为什么送我回到这一时间流？"
D.Strings[22769]="永恒之龙企图改变阿尔萨斯·米奈希尔王子的命运。$B$B你所熟悉的巫妖王在这一时间流里仍然是洛丹伦的王子，而且全心全意地为国效力。$B$B今天，阿尔萨斯做出了一个重大的决定，它所导致的后果，被我们时光守护者们称之为时间流的拐点。"
D.Strings[22770]="是什么决定？"
D.Strings[22771]="阿尔萨斯下令清洗斯坦索姆，杀死城内所有的居民。$B$B他发现了天灾军团在斯坦索姆传播瘟疫的证据。这种疾病不仅能致人死命。$B$B它还能让死于瘟疫的人复生成为无脑的僵尸，将他们统统改造成天灾军团的战争机器。"
D.Strings[22772]="永恒之龙打算如何破坏这一时间流呢？"
D.Strings[22773]="谢谢你掩护我！下面简直就像精神病院！"
D.Strings[22774]="哇，我还以为我死定了呢！谢谢你，朋友！"
D.Strings[22775]="我差点被食尸鬼给吃了！谢谢你救了我！"
D.Strings[22776]="谢天谢地，你来救我们啦！我们还以为这次肯定完蛋了呢！"
D.Strings[22777]="猎户，让我看看你出售的货物。"
D.Strings[22778]="什么？他想让我干嘛？"
D.Strings[22779]="好吧，如果他希望我的属下中断研究工作，为军事目的服务的话，他最好为我们提供月光酒！"
D.Strings[22780]="永恒之龙计划以某种隐秘的手段掩盖天灾军团污染斯坦索姆的证据，以此达到蒙蔽阿尔萨斯王子的目的。$B$B永恒之龙的密探已经潜入附近的农场，对感染瘟疫的谷物施加了幻术，令它们看上去和正常的粮食没有任何区别。$B$B我要你找到这些被藏起来的谷物，然后对它们使用奥术干扰器。阿尔萨斯麾下的士兵正在寻找被污染的粮食，只要你驱除了幻象，他们应该很快就能发现真相了。"
D.Strings[22781]="我们不能放弃奉承红龙军团的好机会。战争迫在眉睫，与红龙结盟对我们是大有裨益的。"
D.Strings[22782]="这些年来，耐克鲁斯滥用神器奴役阿莱克丝塔萨女王和其他红龙。虽然祖鲁希德和耐克鲁斯都死了，但是我们亏欠红龙的债远没有还清。"
D.Strings[22783]="$n，别和大部队走散了。你最好待在上尉和他手下的士兵身边……你死了的话事情就不好办了。"
D.Strings[22784]="$n，记得从南面的峡谷进出神殿。原本驻守在其他峡谷的憎恶正打得不可开交呢……你最好别自找麻烦。"
D.Strings[22785]="联盟控制这座偏远的营地有好些日子了。对我们的猎户和伐木工而言，这倒算不上是什么坏事。$B$B不过局势日益恶化，很快这里也要进驻军队了吧。"
D.Strings[22786]="交给我来处理吧。"
D.Strings[22787]="真搞不懂，你为什么要招惹她呢？"
D.Strings[22788]="你……你这蠢货！你的胆子可不小。别怪我狠心，至少我得让你看起来像是断腿的伤员。"
D.Strings[22789]="如果你还想走路的话，就别乱动。"
D.Strings[22790]="啊，不要！住手！"
D.Strings[22791]="<指挥官停止授课，转过身来打量着你。>$B$B要不要听听，$c？接纳新知识对你来说是很有好处的。"
D.Strings[22792]="$c，我能帮你什么忙吗？$B$B如果你愿意听听关于纳克萨玛斯的课程，不妨挑个位子坐下来。"
D.Strings[22793]="$c，有事吗？"
D.Strings[22794]="$n，我们又见面啦。$B$B想要复习对付天灾军团的战术吗？"
D.Strings[22795]="你的脚下裂开了一道缝隙。"
D.Strings[22796]="亲爱的，没有合适的鞋子来搭配你这身装束，总觉得不顺眼呢。你觉得呢？"
D.Strings[22797]="亲爱的，那些漂亮的鞋子简直值得你为它们而死啊！说真的啦。你从谁手中抢来的啊？肯定免不了一场血腥吧。"
D.Strings[22798]="$n，我会将她赶出藏身之地。你要做好准备，待会她一露面就动手！"
D.Strings[22799]="奖券兑换"
D.Strings[22800]="开火！！击中她！"
D.Strings[22801]="欢迎来到岩石之泉。$b$b如果你能活捉这些冰霜巨魔的话，记得来找我谈谈。我愿意出高价买他们。"
D.Strings[22802]="塞尔赞的护命匣滚落到冰雪风暴脚下。"
D.Strings[22803]="“我们都喜欢树木，芬里克。它们是很好的遮蔽物。”呸，就是不肯让我砍掉这些讨厌的植物。"
D.Strings[22804]="他们想让蝙蝠以那种危险的飞行角度降落吗？好呀，就让乘客们摔断脖子吧，他们还能喝到鲜美的蝙蝠汤。"
D.Strings[22805]="援军正陆续赶来，不知道伤亡人数要上升到什么程度，他们才肯同意我砍掉这些讨厌的树木。我们的蝙蝠损失严重。或许我应该给它们配备盔甲……"
D.Strings[22806]="侏儒们今晚又有蝙蝠胃囊吃啦……"
D.Strings[22807]="嘿，你手里拿的不是美酒节奖币吗？如果你有兴趣的话，我这里还有一些美酒节物品出售。"
D.Strings[22808]="滚开。"
D.Strings[22809]="做你的事去。"
D.Strings[22810]="你想自寻死路的话，我是不会阻拦你的。"
D.Strings[22811]="你已经无路可退了。"
D.Strings[22812]="整点啦。去吧。"
D.Strings[22813]="你最好趁我数到3之前滚远点。你懂我的意思吧？"
D.Strings[22814]="龙饵，是吧？去吧，引诱冰雪风暴！"
D.Strings[22815]="过得怎么样啊，$n？想和俱乐部的会员共度欢乐时光吗？"
D.Strings[22816]="我们又见面啦，$n。希望你能喜欢我们的俱乐部。"
D.Strings[22817]="嘿，$n！希望你喜欢我们的俱乐部！"
D.Strings[22818]="看上去像是通往地狱的大门！"
D.Strings[22819]="如果我不能重返暮冬要塞，请转告我的家人，我从未放弃过与他们团聚的梦想……"
D.Strings[22820]="一切都结束了？只要阻止塞尔赞的阴谋，天谴之门的战事就能取得胜利？"
D.Strings[22821]="我有些担心。原本应该站出来领导我们的英雄在哪儿？"
D.Strings[22822]="能与你们并肩作战是我无上的荣耀。"
D.Strings[22823]="来吧……结束这场噩梦！"
D.Strings[22824]="死亡终究会夺走我们的性命，但是有时候它比预想的来得要快。今天，我们将其称之为盲勇……明天，后人或许就将其形容为愚蠢。"
D.Strings[22825]="%s对$n施放冰霜坟墓。"
D.Strings[22826]="谢谢你从那些怪物手中救了我。"
D.Strings[22827]="$n，很高兴见到你！$B$B这是我们初次见面吗？$B$B我游历过许多地方，穿越过数条时间流，很难记住所有的事。"
D.Strings[22828]="士兵们，振作起来。$n已经帮我们揭开了最后的谜团。巫妖塞尔赞很快就会显身，让我们一举击败他吧！"
D.Strings[22829]="这就是塞尔赞的护命匣，它是我们取胜的关键！"
D.Strings[22830]="凡人，曾经……我和你一样，血肉之躯，不堪一击！"
D.Strings[22831]="士兵们，坚持住！"
D.Strings[22832]="阿尔萨斯王子从我身上看到了凡人的脆弱。"
D.Strings[22833]="“终生为我效劳吧。我承诺，我会抹除你灵魂中的弱点。彻底抹除！”我以这样的方式被巫妖王选中……接受了他的赐福。"
D.Strings[22834]="我成为了巫妖王的仆从……恐怖之城纳克萨玛斯能重返诺森德全都是我的功劳。"
D.Strings[22835]="到此为止吧……你历经万难，终于站到了黄昏使者面前。我不会令你失望的……"
D.Strings[22836]="让我拯救你吧，就像阿尔萨斯王子拯救我一样！"
D.Strings[22837]="复活吧，我的侍从！听从主人的命令！"
D.Strings[22838]="样本……样本……除了样本，就不能谈点别的吗？生活应该丰富多彩才对啊！$B$B我说，你的宠物呢？你肯定带着小宠物的吧。喏，这瓶药剂能让它们变得……呃，变得既聪明又强壮！我不骗你啦！$B$B试试吧！"
D.Strings[22839]="好吧，我试试这瓶药剂。"
D.Strings[22840]="要当心哦。它不是很稳定，药效随时可能消失。动作要快！最好……现在就用……"
D.Strings[22841]="那只猫哪儿去了？"
D.Strings[22842]="帕帕？"
D.Strings[22843]="小坏蛋，你躲在这儿呀。"
D.Strings[22844]="%s发出痛苦的哀嚎。"
D.Strings[22845]="我得再做一只帕帕。"
D.Strings[22846]="荣耀、勇气、怜悯、公正！塞尔赞，当年你也曾发誓恪守这些美德，成为一名合格的银色黎明祭司。"
D.Strings[22847]="你将全副身心都花在对抗天灾军团的大业上。你曾亲眼目睹他们在洛丹伦犯下的罪行。巫妖王夺走了你的一切！"
D.Strings[22848]="那么英尼戈·蒙托尔神父是如何堕落的呢？身为银色黎明的精神领袖，他为什么会变成自己百般唾弃的魔鬼？"
D.Strings[22849]="圣骑士，这将是你最后一次提及那个名字！受死吧！"
D.Strings[22850]="$n，很高兴看到你还活着。还记得很久之前你在暴风城帮我做的事吗？真是记忆犹新啊。"
D.Strings[22851]="公爵！"
D.Strings[22852]="弗塔根公爵！"
D.Strings[22853]="胜利属于联盟！"
D.Strings[22854]="你拯救了暮冬要塞！塞尔赞的威胁已经解除，残余的天灾士兵就交给第七军团解决吧。等你处理完这里的事务后，就去天谴之门安加萨报到吧！"
D.Strings[22855]="加入战斗吧！让我们了结这一切！"
D.Strings[22856]="哇，这匹马不错！"
D.Strings[22857]="啧啧，瞧那匹健壮的野马。"
D.Strings[22858]="我想看到更多的好马！"
D.Strings[22859]="我要亲自调教那匹马。"
D.Strings[22860]="我会给那匹马选个合适的好主子！"
D.Strings[22861]="他多半喜欢老马布兰契。"
D.Strings[22862]="当我得知西部荒野发生骚乱时，便毅然告别战友，返回家乡处理当地的事务。算算也是陈年旧事啦。感谢圣光，迪菲亚兄弟会的威胁得以解除。$B$B如今我们再次出征，来到偏远的极寒之地。如果我们嬴不了这场战争，或许就再也没有机会回家了。"
D.Strings[22863]="皮雷利先生，最近那些穿着暗色袍子的家伙有没有什么可疑的行动？"
D.Strings[22864]="皮雷利先生，你在附近见过亡灵吗？阿尔萨斯王子欢迎你提供任何线索。"
D.Strings[22865]="皮雷利先生，象你这样的旅行商人肯定见多识广。你应该对天灾军团的传言有所耳闻吧？"
D.Strings[22866]="如果我继续问下去，你是不是打算扭头就走？"
D.Strings[22867]="皮雷利先生，你一直负责监管这些货物吗？"
D.Strings[22868]="你不会还带着希尔斯布莱德丘陵的罐装海龟汤吧？"
D.Strings[22869]="霜之哀伤洞穴剧烈地摇晃起来。"
D.Strings[22870]="皮雷利先生，如果你在旅途中发现天灾军团的活动迹象或是任何可疑的行为，请立即向洛丹伦士兵汇报。"
D.Strings[22871]="没有，中士。"
D.Strings[22872]="没有，长官。"
D.Strings[22873]="是，摩利根中士。"
D.Strings[22874]="辛克的伐木机发生故障，很快停止了运转。"
D.Strings[22875]="我想检查一下你的货物，看看有没有动过什么手脚，你不介意吧？"
D.Strings[22876]="嗯？这是怎么回事？皮雷利，你竟敢欺骗我！"
D.Strings[22877]="看，穆拉丁，我们最后的希望，霜之哀伤。"
D.Strings[22878]="我不懂你在说什么，中士！"
D.Strings[22879]="等等，伙计。基座上有一行铭文，好像是警告。上面说，“持此剑者将获永恒之力。此剑喋血以展锋锐，此力噬灵以显威能”。噢，我早该知道的。这把剑被诅咒了。我们快走吧，别管它了！"
D.Strings[22880]="我要没收这批可疑的谷物，皮雷利。我们奉命寻找被动过手脚的粮食，阿尔萨斯王子会亲自介入此事，你最好合作一点，呆在原地哪儿都别去。"
D.Strings[22881]="为了拯救我的祖国，再恶毒的诅咒我也承受。"
D.Strings[22882]="别去动它，阿尔萨斯。忘了它吧，带你的弟兄们回家。"
D.Strings[22883]="你要相信我，我是无辜的！"
D.Strings[22884]="该死！无论是谁，都无法阻止我的复仇，老朋友。你，也不行。"
D.Strings[22885]="现在，我召唤镇守此地的魂灵。我愿付出任何代价，做出任何牺牲，只要你能协助我拯救祖国的人民。"
D.Strings[22886]="皮雷利，我们会继续调查此事的。走着瞧吧。"
D.Strings[22887]="啊……头疼……我……我在哪儿？"
D.Strings[22888]="我……我是谁？"
D.Strings[22889]="让我想想，昨天晚上我们吃了鸡肉。"
D.Strings[22890]="我还有好些熏肉，不过早上他吃了一些。"
D.Strings[22891]="我要为他准备一些健康的食物，上周他病得可厉害啦，至今还没有康复呢。"
D.Strings[22892]="草莓！不行，现在不是季节。"
D.Strings[22893]="啊，我烤些新鲜的面包吧！我找马尔萨要面粉去。"
D.Strings[22894]="玛尔萨，我的面粉用光啦。最近不是刚运来一批粮食吗，你能借我一些面粉吗？"
D.Strings[22895]="我们出发吧！"
D.Strings[22896]="小心！我们要去的地方非常危险，那里到处都是维库人和部落！"
D.Strings[22897]="留意周围的环境。记住这条路线，以后你可以原路返回瓦加德。"
D.Strings[22898]="我们到啦！冰锤就在那座维库人建筑物中！将他们统统送进地狱吧！"
D.Strings[22899]="马尔萨，谢谢你！我欠你一份情。"
D.Strings[22900]="啊，天哪。"
D.Strings[22901]="马尔萨，面粉有问题！王子正在寻找被动过手脚的粮食。我这就向他的士兵汇报。"
D.Strings[22902]="嗨，珍娜。没问题。想要多少都可以。"
D.Strings[22903]="我手下的战斗法师很快就会回来。$B$B等他们到了之后再来找我谈谈吧。"
D.Strings[22904]="抱歉，$r。我还有正事要办，不能耽搁。$B$B不好意思。"
D.Strings[22905]="天哪。"
D.Strings[22906]="暴风雨就要来了，脏脏……"
D.Strings[22907]="%s开始嘟囔起来……"
D.Strings[22908]="怎么啦？"
D.Strings[22909]="嗨，$n。别害怕。我……就是来自未来的……你。我是来帮你的。"
D.Strings[22910]="你发现了什么？"
D.Strings[22911]="事情不妙，脏脏。你乖乖地待在家里，我出去找士兵谈谈。"
D.Strings[22912]="永恒之龙摧毁了%s！"
D.Strings[22913]="我们要如何穿越迷雾？"
D.Strings[22914]="我还以为我会落得和他们一样的下场！"
D.Strings[22915]="那是什么！你看到了吗？"
D.Strings[22916]="你听说过牦牛人吗？他们应该和牛头人有亲缘关系吧。你怎么看？"
D.Strings[22917]="事情做得差不多啦。我要回旅店吃点东西，然后好好睡一觉。"
D.Strings[22918]="嗯，什么气味？"
D.Strings[22919]="不对呀，我3天前才洗过澡！"
D.Strings[22920]="虚惊一场……只是粮食的气味。"
D.Strings[22921]="瞧……他们来了。我会尽全力帮助你。别让他们靠近沙漏！"
D.Strings[22922]="奇怪，粮食不应该有这种气味！我最好找个卫兵来瞧瞧。"
D.Strings[22923]="在安多哈尔的时候，我就该好好地看着货车，也不至于捅这漏子了。"
D.Strings[22924]="运粮食也能惹上麻烦事！"
D.Strings[22925]="不知道会因此耽搁多少时间呢！"
D.Strings[22926]="我就不该来这里！"
D.Strings[22927]="呃，我应该把粮食重新搬上货车。"
D.Strings[22928]="不是吧，我怎么这么倒霉！货车坏了，马蹄铁丢了一只，粮食也出了问题！"
D.Strings[22929]="看来我得找卫生鉴定专家问问。如果我够“幸运”的话，他们就会告诉我说这是强效药剂……那样我们就都完蛋了！"
D.Strings[22930]="%s抓着地面。"
D.Strings[22931]="该死！你是我们唯一的希望。别死啊！"
D.Strings[22932]="不稳定的行尸鱼人要爆炸了！"
D.Strings[22933]="洛丹伦的士兵都听着！立即前往斯坦索姆入口处集合，等待阿尔萨斯王子的进一步指示。"
D.Strings[22934]="再次通告！洛丹伦的士兵立即前往斯坦索姆入口处集合，等待阿尔萨斯王子的进一步指示。"
D.Strings[22935]="很好！阿尔萨斯已经得知斯坦索姆中有被瘟疫污染的粮食，正准备展开清洗行动。$B$B但是我总觉得哪里不对劲，肯定有别的生物侵入了这条时间流，恐怕永恒之龙就在我们附近。"
D.Strings[22936]="他们想干什么？"
D.Strings[22937]="不知道，我有些担心。不过我会设法找到永恒之龙的。$B$B与此同时，我希望你能加入阿尔萨斯的部队，尽量待在他身边。"
D.Strings[22938]="什么？加入王子的军队？"
D.Strings[22939]="这么说吧，你不用去填征兵表格之类的东西，只要和王子并肩战斗就行了。$B$B你必须确保阿尔萨斯成功清洗斯坦索姆并击败玛尔加尼斯。没有了乌瑟尔和吉安娜在身边，他就需要一切可能的帮助。$B$B如果你找阿尔萨斯谈谈的话，他应该会将你编入对抗玛尔加尼斯的部队。我会继续追查永恒之龙的阴谋，一有消息就联络你。"
D.Strings[22940]="好吧，克罗米。"
D.Strings[22941]="祝你好运，千万当心。瞧，乌瑟尔和吉安娜来了。"
D.Strings[22942]="坐稳啦，$n！向无赖港出发！"
D.Strings[22943]="啊！我们到啦！你瞧，无赖港！"
D.Strings[22944]="绿皮肤的家伙……我知道你此行的目的。我们不信任你，别妄想说服我们成为你的盟友。"
D.Strings[22945]="瞧，沙漏显现出诺兹多姆的影像！"
D.Strings[22946]="%s轻蔑地挥了挥手。"
D.Strings[22947]="呸！你这蠢货！我真想把你扔去喂虫子！"
D.Strings[22948]="哇啊啊啊啊！"
D.Strings[22949]="耶喔！"
D.Strings[22950]="啊啊啊啊！！！"
D.Strings[22951]="<达库鲁将滴血的手掌伸出笼子，满怀期待地看着你。>"
D.Strings[22952]="与达库鲁握手。"
D.Strings[22953]="换成以前，我会把你打倒，瞧瞧你脸上的表情……"
D.Strings[22954]="嗨，朋友！$B$B很高兴再次见到你……$n，对吧？我怎么会忘记你的名字呢。$B$B我有一种强烈的直觉，我们一定会成为真正的好朋友！$B$B<巨魔露出一丝狡黠的笑容。>"
D.Strings[22955]="达库鲁，我还需要一瓶药剂。"
D.Strings[22956]="再见，$n。好好活着，搞些更好的装备！"
D.Strings[22957]="给。千万别大意哦。$B$B等你进入达克辛废墟后，在底座旁喝下它！"
D.Strings[22958]="我负责传达地狱咆哮的命令。他的指令都是生死攸关的决策。"
D.Strings[22959]="堕落的巨魔……"
D.Strings[22960]="……接受烈焰的惩罚……"
D.Strings[22961]="好啦！扯远了……你觉得呢？"
D.Strings[22962]="愿艾露恩保护你，$r。"
D.Strings[22963]="艾米鲁尔，是凯勒中将派我来的。请送我去西部卫戍要塞！"
D.Strings[22964]="我到啦。我们开始吧？"
D.Strings[22965]="$g先生:女士;，你觉得这个怎么样？"
D.Strings[22966]="这玩意儿要怎么用？"
D.Strings[22967]="让我看看你出售的货物。"
D.Strings[22968]="我来告诉你虚灵是怎么做生意的。我让合作伙伴去杀死生物，然后我来抽取它们的精华……只要一点点就够啦，真的。$B$B我会支付虚灵货币，以此履行合同规定的义务。$B$B你可以用货币购买我出售的货物哦。肯定有你感兴趣的东西……"
D.Strings[22969]="真不敢相信，我竟然穿过这样的装备。"
D.Strings[22970]="只有这样，哈瑞才会和我讲话！我必须一直戴着这个愚蠢的面具……"
D.Strings[22971]="哈瑞说我可以搭乘他的小船去巴尔古挖掘场。我准备好出发啦！"
D.Strings[22972]="瞧瞧你在战斗中的表现，难怪我会染上酒瘾。"
D.Strings[22973]="什么？你应该很清楚吧，我们的命运是休戚相关的！"
D.Strings[22974]="你可千万别出事啊。你若是死了，我也就不存在了，对吧？但是如果你真的死了的话，我又是如何能从未来返回呢。我被绕糊涂了！"
D.Strings[22975]="啊，我差点忘记啦，原来以前我是这么缺乏经验啊。"
D.Strings[22976]="马克大声地打嗝……"
D.Strings[22977]="朋友！$B$B事实上并不是这样的。呃……$B$B情况太复杂了。"
D.Strings[22978]="朋友！我认识你？$B$B哦，是你啊，普雷蒙有过目不忘的本事。$B$B你……跟踪我？不关我的事！我什么都没做过！"
D.Strings[22979]="不好意思，克罗米禁止我透露任何未来的事情。她警告说，如果我告诉了你，那我有可能就不会存在了。"
D.Strings[22980]="我真希望能想起来到底有多少永恒之龙想阻止你。这场战斗实在是太久远啦。"
D.Strings[22981]="听着。我本来不打算告诉你的，很快你就会接到聚会的邀请。总之，千万别喝宴会上的饮料！"
D.Strings[22982]="乌瑟尔，你总算及时赶到了。"
D.Strings[22983]="注意你讲话的态度。没错，你贵为王子，但我仍然是你的导师。"
D.Strings[22984]="我自然不会忘记这一点。听着，乌瑟尔，现在我来告诉你关于天灾的事……"
D.Strings[22985]="糟糕。我们太迟了。他们已经被感染了！虽然他们现在表面上还正常，但是迟早会变成亡灵！"
D.Strings[22986]="必须净化整座城市。"
D.Strings[22987]="你怎么会产生这种想法？肯定有别的解决方式。"
D.Strings[22988]="乌瑟尔，大胆！我是你未来的国君，我命令你清理这座城市！"
D.Strings[22989]="孩子，你还不是我的王上！况且就算你是，我也不会遵从这样的命令！"
D.Strings[22990]="那么，我只能将你的决定视为叛国了。"
D.Strings[22991]="叛国？你疯了吗，阿尔萨斯？"
D.Strings[22992]="是这样吗？我以王储的身份在此宣布，解除乌瑟尔勋爵在白银之手骑士团的所有权力与职务。"
D.Strings[22993]="阿尔萨斯！你怎么能……"
D.Strings[22994]="就这样吧！有谁希望拯救这片土地的，就跟我来！其他人……给我滚远点！"
D.Strings[22995]="阿尔萨斯，你做出了一个非常可怕的决定。"
D.Strings[22996]="吉安娜？"
D.Strings[22997]="对不起，阿尔萨斯。我不能眼睁睁地看着你走上歧途。"
D.Strings[22998]="为达克萨隆要塞而战！"
D.Strings[22999]="希姆波不能死，他还要对付叛徒呢！"
D.Strings[23000]="谁也不能阻挡希姆波！我们要解放要塞！"
D.Strings[23001]="和天灾士兵一起去死吧！"
D.Strings[23002]="被我们的族人背叛。真是莫大的耻辱……"
D.Strings[23003]="啊，我要吸取更多的精华……"
D.Strings[23004]="旅途愉快！这是单程航线！"
D.Strings[23005]="给。这次要格外当心啦。$B$B前往北边的塞布哈拉克，在底座旁边饮下它吧！$B$B哦，你要先去通灵塔顶端取下预言者之眼才行……"
D.Strings[23006]="给。这次要格外当心啦。$B$B前往北边的塞布哈拉克，在底座旁边饮下它吧！$B$B然后我会给你进一步指示的。"
D.Strings[23007]="给。这次要格外当心啦。$B$B前往西北边的达克阿塔小径，在底座旁饮下药剂吧。$B$B然后我会给你进一步指示的。"
D.Strings[23008]="这是你的那份。"
D.Strings[23009]="调转方向！重新投入战斗！否则我就将你甩下去！"
D.Strings[23010]="欢迎来到我的营地，$r。$B$B好吧，她或许算不上一座营地，但至少我把她看作自己的家园。"
D.Strings[23011]="乌尔芬，我想再次透过巨鹰之眼洞悉真相。"
D.Strings[23012]="好吧。我允许你再次借用巨鹰之眼那敏锐的视力。"
D.Strings[23013]="请将我传送到琥珀崖。"
D.Strings[23014]="本来呢我是带小毛球出来散步的走着走着就迷了路，你也知道这附近有狼群出没呀没想到真被我们给撞上啦，我抱起小毛球撒开脚丫没命地逃就在我近乎绝望的时候眼前出现了一座哨塔！我们迅速躲进塔内惊魂未定地熬了许久直到外面的狼群悻悻地离开才松了一口气……这段经历真是太可怕啦而且我们还不知道回家的路。"
D.Strings[23015]="你最好马上离开。你吓到小毛球啦！"
D.Strings[23016]="我能飞去其他地方吗？"
D.Strings[23017]="有什么能帮忙的吗？"
D.Strings[23018]="这是毅力还是愚蠢？无所谓了。铭记这个教训吧，凡人！"
D.Strings[23019]="欢迎来到龙眠神殿，$r。希望神殿外的骚乱没有为你带来任何困扰；最近玛里苟斯展开了一系列的行动，龙眠神殿已经被包围了。不过你还是可以安心地待在这儿，我们会确保你的安全。"
D.Strings[23020]="肃清敌军！"
D.Strings[23021]="阿比迪斯，杀光他们！别让我失望！"
D.Strings[23022]="海军上将眯起眼睛，仔细地打量着你。"
D.Strings[23023]="你已经体现了自己的价值。"
D.Strings[23024]="到冰冠冰川来找我吧，懦夫……如果你们还能活着到那里的话！"
D.Strings[23025]="天灾军团如潮水般向我们涌来。战斗吧！"
D.Strings[23026]="不要放弃希望。只要我们心怀坚定的信仰，就能走出这片黑暗，迎接黎明的曙光。"
D.Strings[23027]="坚持！做好准备！一旦发现污秽，立即烧毁它！"
D.Strings[23028]="%s打开了一道混乱裂隙！"
D.Strings[23029]="%s撑起护盾，将自己的能量转移到裂隙中！"
D.Strings[23030]="伊利丹之路"
D.Strings[23031]="跳舞球"
D.Strings[23032]="灵魂商人"
D.Strings[23033]="猎杀伊利丹"
D.Strings[23034]="你以为冥想能帮助你洗涤内心的杂念吗？"
D.Strings[23035]="蠢货！我要彻底摧毁你，成为你内心世界真正的主宰！"
D.Strings[23036]="别想打败我。我是你身体不可分割的一部分！"
D.Strings[23037]="干得不错。"
D.Strings[23038]="又一只蓝龙倒下啦。我们的配合真是天衣无缝！"
D.Strings[23039]="只要我们通力合作，这场战争很快就能分出胜负。"
D.Strings[23040]="我从来没有想过自己会载着一名$r投身战斗。"
D.Strings[23041]="还好你留意到那只蓝龙啦！"
D.Strings[23042]="抓紧。让我们勇敢地迎接挑战吧。"
D.Strings[23043]="我从未见过这样的场面。有你陪同真是太好了。"
D.Strings[23044]="玛里苟斯显然是疯了。"
D.Strings[23045]="%s指挥着前方遮天蔽日的虫群大军。"
D.Strings[23046]="你好，$c！$b$b希望你能胜任艰苦的工作。我们的人手紧张，非常需要帮助。"
D.Strings[23047]="凛风与森林低声诉说着隐忧。这片看似生机勃勃的土地其实隐藏着莫大的危机。"
D.Strings[23048]="<塞瑞恩的眼神异常空洞。为了净化沃达希尔，她似乎耗尽了全部精力。>"
D.Strings[23049]="朋友，我们会为部落提供最优质的皮革！"
D.Strings[23050]="买点干粮在路上吃？或者观战的时候也可以喝上一杯？"
D.Strings[23051]="敌人从四面八方向我们逼近，长老们都认为应该放弃这座岗哨。但是我认为我们应该留下来，勇敢地与敌人抗衡。"
D.Strings[23052]="你只能在冰雾村上空飞翔。"
D.Strings[23053]="$r，你不应该来这里的。"
D.Strings[23054]="$r，你不应该来这里的。想活命的话，赶紧离开吧。"
D.Strings[23055]="返回战场，否则巨龙会将你甩下去！"
D.Strings[23056]="这片广袤的土地便是巨龙先祖的埋骨地。他们的灵魂已经升华，在龙神之厅中享受着永恒的宁静。"
D.Strings[23057]="天灾军团的行径将会世界造成不可挽回的恶劣影响。必须阻止他们！"
D.Strings[23058]="迦拉克隆是龙族的祖先。泰坦以它为雏形，甄选了五条巨龙来守护艾泽拉斯世界。"
D.Strings[23059]="我还没有完全成熟，必须依赖进食来强化自身的力量。"
D.Strings[23060]="朋友，今天真是个美好的日子。我一直待在龙眠神殿，已经很久没有在龙骨荒野上空自由飞翔了。"
D.Strings[23061]="最近，女王陛下召集议会谈论了奥杜尔遭遇的一场灾难。风暴峭壁似乎出了什么大事！"
D.Strings[23062]="蓝龙军团竟然选择了如此残酷而冷血的道路，整个龙族都因此蒙羞。我却不得不与玛里苟斯的子嗣交战，做出这样的决定真令我痛心。"
D.Strings[23063]="达库鲁将目光投向达克萨隆要塞……"
D.Strings[23064]="你做得很好。"
D.Strings[23065]="朋友，我必须返回龙眠神殿了。再见！"
D.Strings[23066]="奴仆们，快！绝不能给敌人任何喘息的机会！"
D.Strings[23067]="迦拉克隆的骸骨很快就要从永恒的长眠中觉醒，为世界带来一场残酷的浩劫！"
D.Strings[23068]="奴仆们！听从我的号令吧！通灵主宰命令你们：肃清敌人，否则你们要为失败付出惨痛的代价！"
D.Strings[23069]="巫妖王下令继续向天谴之门安加萨调派冰霜巨龙！服从指令，否则就尝尝我的厉害！"
D.Strings[23070]="敌人发动了攻击！禁止任何人穿越这座古老的陵墓！"
D.Strings[23071]="安提沃克的镰刀跌落在地！"
D.Strings[23072]="看看是谁来了？一群公然蔑视并挑战织法者的狂徒？一群完全缺乏理解与远见的蠢货。我怎样才能让你们看清这真相呢？玛里苟斯是在拯救这个世界！咳，我为什么要跟你们废话？"
D.Strings[23073]="可怜而无知的蠢货！"
D.Strings[23074]="显然，我的宠物们失败了。看来还得另外安排一次示范。"
D.Strings[23075]="你们还要打下去吗？你们仍然遵守着被扭曲的教条吗？如果你们能活下来，就到中央的圆环中找我吧。"
D.Strings[23076]="你以为自己嬴了，是吗？尝尝安提沃克的怒火吧！"
D.Strings[23077]="瞧！安提沃克的镰刀！"
D.Strings[23078]="我将她称作诺莫瑞根之魂。她很漂亮，不是吗？要不是你帮忙，她也不可能恢复原貌。"
D.Strings[23079]="好！让我们来尝尝这个所谓的烈酒……"
D.Strings[23080]="天啊！真是好酒！"
D.Strings[23081]="真可惜，科林的烈酒不能在广大啤酒爱好者中推广开来！我知道这么说可能不合适，但我真的很嫉妒那些黑铁矮人！"
D.Strings[23082]="$n，这啤酒……好吧，它可能是美酒节上最好的酒了！"
D.Strings[23083]="欢迎来到银色前沿，$c。$b$b你可以将这里当作自己的家，不过别太放松啦。我们仍处于危险的丛林深处。$b$b要想所有人都安全地走出这片森林，就必须同心协力……你也一样。"
D.Strings[23084]="恐怖船长德梅萨已经进驻藏宝海湾并宣布这一天为海盗日！$B$B她邀请所有敢于前往的人与船员们一起开怀畅饮。"
D.Strings[23085]="我们的处境非常狼狈。"
D.Strings[23086]="天灾军团的邪恶气息与达卡莱巨魔的黑暗仪式亵渎了这片土地。$B$B我们必须将他们彻底铲除。"
D.Strings[23087]="感谢圣光！"
D.Strings[23088]="嗨，$C。我们正忙着打仗呢。"
D.Strings[23089]="你是$n？我听说你已经死了啊。"
D.Strings[23090]="麻烦你快一点……局势每况愈下，我必须做好战斗准备。"
D.Strings[23091]="你是新兵？瞧你这身行头，不像是正规的军装啊。"
D.Strings[23092]="哎呀，是援军啊！"
D.Strings[23093]="有口信要捎给我吗？"
D.Strings[23094]="士兵，听令！立即撤退，向中士报到！"
D.Strings[23095]="好吧，时间就是金钱，光阴飞逝！我们来喝一杯吧……"
D.Strings[23096]="哇！它真的可以润滑蒸汽阀门！"
D.Strings[23097]="如果我是一个诚实的地精，我要说这是节日上最好的啤酒……"
D.Strings[23098]="科林已经死了，这可真糟糕。如果我能从他手中买下这些酒再转卖出去的话——当然要兑上水，重新装瓶，再贴上自己的商标——那我肯定发财了！"
D.Strings[23099]="$r，是不是觉得这里比想象中更加毛骨悚然啊？$b$b如果你真有这种感觉，我一点也不吃惊。几乎所有来过这里的人都这么说，我已经习惯了。"
D.Strings[23100]="朋友，我这就送你去琥珀松木营地！不过我们需要稍作停留……"
D.Strings[23101]="我是赞达拉部族的乌布戈。$B$B$r，眼前的情形非常糟糕。达卡莱巨魔将自己送上了绝路。$B$B为什么要重蹈覆辙呢？"
D.Strings[23102]="我们很快就会对征服堡展开空中侦察，看看那些肮脏的部落到底有什么阴谋。留神那些双足飞龙，倒不是说它们能追上我！"
D.Strings[23103]="以铜须之名，这里到底发生了什么事？瞧瞧这堆烂摊子！我说……"
D.Strings[23104]="哎呀，我们被盯上啦！抓紧啦！我打算甩掉它们！"
D.Strings[23105]="好吧。我还是返回中士身边吧。"
D.Strings[23106]="保持警惕。达卡莱巨魔生性卑鄙。"
D.Strings[23107]="千万小心，$c。那些巨魔连他们崇拜的蛇神都敢杀！"
D.Strings[23108]="别在野外逗留太久。"
D.Strings[23109]="我想知道我们这是去哪儿，以及谁会来对付这些家伙？"
D.Strings[23110]="达卡莱巨魔真是麻烦。我们必须继续前进！"
D.Strings[23111]="喂，伙计！$B$B今天是我们的节日，你知道啦……是海盗日！$B$B我和查姆巴克想出了这个主意，而恐怖船长立即同意了……所以，我们就来啦！"
D.Strings[23112]="明天我们就把海湾还给大财主里维加兹……可在今天——海盗日——这地方归恐怖船长德梅萨和她的船员了。耶！$B$B记住：可不能光做做样子哦。在海盗日上，你还要讲些道上的黑话才行！"
D.Strings[23113]="哈帕纳咕哝着，挥挥手让你去找恐怖船长德梅萨。$B$B你发现他那条毛发浓密的粗壮胳膊上刺着一箭穿心的纹身，上面写着“玛加萨”。"
D.Strings[23114]="呱呱！龙骨拖！龙骨拖！"
D.Strings[23115]="呱呱！让他走跳板！走跳板！"
D.Strings[23116]="呱呱！见鬼！真见鬼！"
D.Strings[23117]="呱呱！住手，你这条下贱的狗！住手！"
D.Strings[23118]="你要到这里来是需要一些勇气的，$g小伙子:小姑娘;。今天是海盗日，你知道啦……直到明天的太阳升起之前，藏宝海湾是属于我的。$B$B那么！你觉得怎样？为我和我的船员举杯，一起来参加庆祝吗？"
D.Strings[23119]="噢……我有点头晕……"
D.Strings[23120]="别来烦我，$c！我要照看整整两大锅起泡酒呢，不能让它们变味儿！$B$B要是这些酒出了一点差子，科林·烈酒大人会把我剥来煮了！"
D.Strings[23121]="祝你健康，恐怖船长！今天让我也尝尝当海盗的滋味吧！"
D.Strings[23122]="要我帮你尝一尝吗？"
D.Strings[23123]="部队在这里待命，我会亲自率领一支小分队进入斯坦索姆，开始清理行动。为了洛丹伦，我们必须除掉所有被感染的城民！"
D.Strings[23124]="欢迎来到藏宝海湾，伙计。别担心德梅萨和她的船员……每年我们允许他们来这里发泄一次，就在海盗日这一天，然后她就会回到南海去，让我们继续平静地生活。$B$B那么……作为热砂集团谦卑的仆人，我能为你做点什么呢？或者我更愿意说——你能为我做点什么呢，嗯？"
D.Strings[23125]="感觉太棒啦！真是暖胃的美酒呀！$n，你真是个时髦的$g家伙:姑娘;！"
D.Strings[23126]="好酒！可惜不够劲。我觉得可以在里面多加一点大蒜……"
D.Strings[23127]="嘿！今天是海盗日，你知道的……在明天的太阳升起之前，藏宝海湾是我的。"
D.Strings[23128]="我们已经摆脱它们啦！真险呀！好啦，我这就送你去琥珀松木营地！朋友，坐稳！"
D.Strings[23129]="入侵者！杀了他们！"
D.Strings[23130]="联盟狗！死！死吧！"
D.Strings[23131]="消灭他们！为了部落！"
D.Strings[23132]="我们的处境远比在东西瘟疫之地时狼狈得多。$b$b天灾军团变得更加强大了。"
D.Strings[23133]="我受不了啦……$b$b他们会杀了你，然后吃掉你的尸体！据说这样还算幸运的！你能想象比这更倒霉的遭遇吗！"
D.Strings[23134]="你一定要救我出去，$r！$b$b我可不想落得他们那样悲惨的下场！"
D.Strings[23135]="自打我来到这里，就一直吃不下睡不着。$b$b我根本不该加入银色北伐军……"
D.Strings[23136]="<呜咽>我叔叔是银色黎明的成员。$b$b他怎么有勇气面对这些肮脏的怪物啊？"
D.Strings[23137]="一闭上眼睛，就浮现出我被天灾士兵包围的景象！$b$b我要离开这个鬼地方……"
D.Strings[23138]="我一定会死在这里的……我心里很清楚。"
D.Strings[23139]="我们死定了！！！"
D.Strings[23140]="趁早逃命去吧，$c！$b$b我们不可能获胜……"
D.Strings[23141]="这下麻烦大了。"
D.Strings[23142]="去吧，让天灾军团尝尝厉害！"
D.Strings[23143]="好酒！但我觉着还不够刺激。要不我们用滑腻的蜥蜴眼来提提味道……"
D.Strings[23144]="呃，还不错吧……总觉得少了点什么！不如加点蝎毒？对呀！那样就很完美啦！"
D.Strings[23145]="差不多啦！不过还需要加点料。嘿嘿，你猜对啦……把昨天的袜子丢进锅里吧……哎哟，那种味道……真是美呀！"
D.Strings[23146]="$g先生:女士;，这可真是好酒呀！不骗你！"
D.Strings[23147]="我们来唱歌吧！$B$B啤酒，吵闹，$B啤酒，吵闹！$B黑铁矮人的生活！$B$B哈哈！$n，我喜欢你！"
D.Strings[23148]="我说到哪儿啦？对啦……于是我对她说：“可是我需要你！我需要你啊！”……她却哈哈大笑，扭着尾巴爬走了！我说的都是真心话啊，$n。纳迦真是残酷的种族！"
D.Strings[23149]="让我们再尝尝看！"
D.Strings[23150]="还要一杯！"
D.Strings[23151]="你说得对！我在想什么呢！天灾军团，放马过来吧！"
D.Strings[23152]="你说得对！我们能做到！"
D.Strings[23153]="我们会取得这场战争的胜利！"
D.Strings[23154]="为银色北伐军而战！天灾军团注定会失败！"
D.Strings[23155]="我们会净化这片土地！阿尔萨斯，等着瞧吧！"
D.Strings[23156]="淹死你！"
D.Strings[23157]="被深渊吞噬吧！"
D.Strings[23158]="我要把你血淋淋的内脏安在自己身上。"
D.Strings[23159]="%s在附近寻找可以食用的尸体。"
D.Strings[23160]="%s咀嚼着附近的植物。"
D.Strings[23161]="兄弟，干杯！"
D.Strings[23162]="西莱图斯的魔精属于我们啦。世间万物都将臣服于达卡莱的力量！"
D.Strings[23163]="他们竟敢发动攻击？这帮蠢货！他们难道不清楚我们有多强大吗？！"
D.Strings[23164]="杀死入侵者！看看谁敢来亵渎我们神圣的祭坛！"
D.Strings[23165]="杀死他们，然后我们去南边对付他们的同胞！"
D.Strings[23166]="狂野诸神的力量在我们的血脉中燃烧，即便是巫妖王，也无法阻挡我们前进的道路！"
D.Strings[23167]="我看见你了，蝼蚁！过来吧。"
D.Strings[23168]="我要消灭银色北伐军！我要消灭天灾军团！"
D.Strings[23169]="若是在别的日子，我才不会这么做。不过……我很口渴，而且我讨厌独自饮酒。$B$B干杯！"
D.Strings[23170]="全军列队待命，各指挥官报到！听我的号令，准备进入斯坦索姆。"
D.Strings[23171]="你愿意不惜一切代价保卫洛丹伦吗？"
D.Strings[23172]="砰！$b$b我只记得听见一声巨响……"
D.Strings[23173]="<叹气>……这次大劫难逃了。"
D.Strings[23174]="谢谢你，朋友。要不是你帮忙，我肯定没命了。"
D.Strings[23175]="<叹气>……$b$b你能帮我个小忙吗？"
D.Strings[23176]="<叹气>……呃，我还以为事情会更糟糕呢。"
D.Strings[23177]="遵命，王子殿下。我们准备好了。"
D.Strings[23178]="不用管我。我只是个糟老头，让我静静地等待那位老……朋友。"
D.Strings[23179]="啊，难以忍受的……痛苦……"
D.Strings[23180]="啊，我……快撑不住了……"
D.Strings[23181]="朋友，我欠你一份情。谢谢你救了我。"
D.Strings[23182]="快，$r。$b$b我的时间不多了。"
D.Strings[23183]="快点。我在流血呢……"
D.Strings[23184]="嗯，再来点魔精。"
D.Strings[23185]="<叹气>……你觉着我们能逃出去吗，$C？$b$b我的血快流干了！"
D.Strings[23186]="开火！又是那群该死的龙！来吧！"
D.Strings[23187]="大家都做好准备了吧。记住，斯坦索姆的城民已经受到感染，很快就会丧命。我们必须清洗斯坦索姆，确保洛丹伦的其它地区免受天灾军团的侵蚀。出发吧。"
D.Strings[23188]="到井边去！快！"
D.Strings[23189]="前进！这片土地属于巫妖王陛下！"
D.Strings[23190]="没有人能阻止天灾军团！没有人！"
D.Strings[23191]="毁灭所有阻挡你们前进的生物！为巫妖王而战！"
D.Strings[23192]="不……可能……"
D.Strings[23193]="悲惨地死去吧！"
D.Strings[23194]="哈！感觉怎么样？！"
D.Strings[23195]="你想挑战卡洛斯？古雷罗！上吧！"
D.Strings[23196]="我想返回第一座哨站。"
D.Strings[23197]="赞美圣光！是阿尔萨斯王子！殿下，我们都被感染了，现在该怎么办？"
D.Strings[23198]="你已经感染得太深了，我能做的只有让你毫无痛苦地安息。"
D.Strings[23199]="%s开始施放魔法牵引！"
D.Strings[23200]="这只是个开始。"
D.Strings[23201]="龙来了！开火！"
D.Strings[23202]="她正在攻击要塞！击落她!"
D.Strings[23203]="见鬼……"
D.Strings[23204]="打起精神来！继续开炮！"
D.Strings[23205]="要塞着火了！炮兵呢！都死哪儿去了！"
D.Strings[23206]="快去南边的通道！"
D.Strings[23207]="敌人开始撤退了……快去支援南边的通道！快！"
D.Strings[23208]="敌人对南边的通道发动了猛攻！"
D.Strings[23209]="南边！立即支援！"
D.Strings[23210]="敌人聚集到南边去了！"
D.Strings[23211]="南边！快！"
D.Strings[23212]="立即支援东边的通道！"
D.Strings[23213]="敌人开始撤退了……快去支援东边的通道！快！"
D.Strings[23214]="支援东边的通道！敌人企图层层推进，突破我们的防线！"
D.Strings[23215]="支援东边的通道！快！"
D.Strings[23216]="敌人聚集到东边去了！"
D.Strings[23217]="东边！快！"
D.Strings[23218]="有个教徒不小心撞上了我的剑刃，然后就死了……我能再要一套伪装吗？我发誓这次会更加谨慎的。"
D.Strings[23219]="啊，我的熔岩之龙……事情并非无可挽回……或许我还能让它们复生。"
D.Strings[23220]="对，这只是个开始。年轻的王子，我等你很久了。我就是玛尔加尼斯。"
D.Strings[23221]="如你所见，你的子民现在已经属于我了。我已经将城中的居民统统变成了我的奴仆，让斯坦索姆的生命之火……永远熄灭了。"
D.Strings[23222]="奥法徽章"
D.Strings[23223]="我不会让你得逞的，玛尔加尼斯！我绝对不会眼睁睁地看着他们成为你的奴仆！"
D.Strings[23224]="辉煌徽章"
D.Strings[23225]="防御者徽章"
D.Strings[23226]="愤怒徽章"
D.Strings[23227]="自然徽章"
D.Strings[23228]="虚空徽章"
D.Strings[23229]="什么事？没看见我正忙着吗？"
D.Strings[23230]="玛尔加尼斯肯定会派出天灾部队阻挠我们。我希望能有些精通剑术或魔法的勇士对抗天灾士兵。而我，会率领剩余的军队清理斯坦索姆中的亡灵，将全城拯救出来。"
D.Strings[23231]="你是来接受训练的吗？"
D.Strings[23232]="你不是死亡骑士。离我远点。"
D.Strings[23233]="我想学习死亡骑士的技能。"
D.Strings[23234]="嗯……它的确比之前碰见过的所有机器都诡秘复杂……啊，见鬼……敌人来了！"
D.Strings[23235]="玛多兰在上，这玩意到底干了些什么？哦！等等，我马上就搞定它了……"
D.Strings[23236]="哈，终于搞定了！援军来了！接招吧，你们这群白痴铁疙瘩！"
D.Strings[23237]="你摆出这种鄙视的面孔算什么意思？$B$B说到匹斯波特家族，名气可是响当当的！我的祖辈世代以炼金师为业，享有很高的声誉。$B$B不骗你！$B$B我敢说，无论是艾泽拉斯世界还是别的异位面，你找不出比匹斯波特家族更有才的炼金师啦！$B$B虽说我目前还挂着学徒的头衔，但我的技术是顶呱呱的！你要明白，在学术界，只有保持低调才能博得上位。$B$B我说，你是来帮我的吧？$B$B<小侏儒傲慢地笑了笑。>"
D.Strings[23238]="我会让你们见识见识先锋军的真正实力！"
D.Strings[23239]="听着，你去告诉舒维瑟尔和洛伊塔，就说我们已经控制住了这里的局势。他们不需要……什么？$B$B他们没派你来？那你干嘛还来浪费我的时间？$B$B我还有工作要做呢！"
D.Strings[23240]="嗨，没看见我正忙着吗？！$B$B你想看演出？乐队每晚8点开演。"
D.Strings[23241]="想见识见识先锋军的实力吗？"
D.Strings[23242]="快点干掉闯入者！我可没时间亲自动手。"
D.Strings[23243]="你们应该在动手之前就考虑到后果，蠢货。"
D.Strings[23244]="难道要我亲自解决这些入侵者？"
D.Strings[23245]="你瞧，我都把挖掘机器开到这里来了……"
D.Strings[23246]="呃……好吧，好吧。我们需要测试一下设备。$B$B稍等。我来安排一场“排练”。$B$B你准备好了吗？"
D.Strings[23247]="米兹利，我们最好快点弄好。他们很快就要到了。"
D.Strings[23248]="<受伤的雨声神谕者痛苦地呻吟着。>"
D.Strings[23249]="啊！你竟然抢走属于我的猎物！基克吉克要干掉你！"
D.Strings[23250]="你好，$r。$b$b非常抱歉，你得体谅我一下，我现在实在是太忙了。"
D.Strings[23251]="%s愤怒地尖啸着，冲过来帮助她的孩子。"
D.Strings[23252]="$n，时间很紧迫。你准备好了吗？"
D.Strings[23253]="我准备好啦。你要的第一种材料是什么？"
D.Strings[23254]="在这里，东南方。啊，你也落到他们手里了……"
D.Strings[23255]="又有入侵者？我倒要看看谁敢和风险投资公司过不去！"
D.Strings[23256]="这次一定要干掉你！"
D.Strings[23257]="呃，居然能在这种地方遇到别的冒险者，这还真让我吃惊！$B$B既然你们在这里，就帮助我进入前面的大厅吧！如果我的研究理论没错的话，我们一定能在这里找到矮人一族起源的秘密！"
D.Strings[23258]="布莱恩，能帮助你是我们的荣幸！"
D.Strings[23259]="布莱恩，别再卖弄你的历史知识啦！我们行动吧。"
D.Strings[23260]="要是我的兄弟现在也在这里就好了。他们肯定不会相信这项发现有多么惊人！$B$B这座大厅是储存泰坦圆盘的档案馆；而这里，就是存储圆盘的地方。$B$B瞧！地板下就散落着泰坦圆盘！我们必须赶快行动，矮人一族有史以来最伟大的发现在等着我们呢。"
D.Strings[23261]="首先我们需要加入一棵结根草。别拖拖拉拉的，现在就去搞……"
D.Strings[23262]="可惜……真是可惜。"
D.Strings[23263]="我会让你搭乘我的飞行器的。睁大你的眼睛，给我调查清楚赫米特的情况！"
D.Strings[23264]="警报：飞行器已被导弹锁定。启动闪避机动功能。"
D.Strings[23265]="复生吧，为我效劳！"
D.Strings[23266]="除非你能击落科尔拉玛斯，否则不可能阻挡天灾军团的攻势。"
D.Strings[23267]="别想逃出死神的魔爪。"
D.Strings[23268]="以巫妖王的名义。"
D.Strings[23269]="接受巫妖王的拥抱吧。"
D.Strings[23270]="我们将攫取你们崇拜的神灵的力量！"
D.Strings[23271]="每杀死一名敌人，我们就多一员炮灰。"
D.Strings[23272]="接受命运的审判吧。"
D.Strings[23273]="似乎还要加点料……"
D.Strings[23274]="可以考虑加点……"
D.Strings[23275]="在它变浓之前，得加点……"
D.Strings[23276]="快，给我来点……"
D.Strings[23277]="啊，没错。我就知道……"
D.Strings[23278]="没错，没错。我们需要更多……"
D.Strings[23279]="我觉得还要加点……"
D.Strings[23280]="给我找些……"
D.Strings[23281]="诺森德的大部分区域比女妖的心还要寒冷。不过，这里却……嗯，一定有什么特殊的原因！很有可能跟这些水晶柱有关！"
D.Strings[23282]="这里竟然有泰坦的建筑物，真是……有趣。"
D.Strings[23283]="这里的地貌与安戈洛环形山极其相似。或者两者有些关联吧。"
D.Strings[23284]="我们什么时候能再盼来一名飞行员啊？研究工作毫无进展，必须进行空中侦测才行。"
D.Strings[23285]="国王广场的喷泉附近发现天灾军团踪迹！"
D.Strings[23286]="市场小径城门附近发现天灾军团踪迹！"
D.Strings[23287]="节庆小巷城门附近发现天灾军团踪迹！"
D.Strings[23288]="长者广场城门附近发现天灾军团踪迹！"
D.Strings[23289]="市政厅附近发现天灾军团踪迹！"
D.Strings[23290]="结根草！"
D.Strings[23291]="腌鹰蛋！"
D.Strings[23292]="斑点杂色鸟粪！"
D.Strings[23293]="干瘪的蝙蝠翼！"
D.Strings[23294]="陈年苹果冰酒！"
D.Strings[23295]="石像鬼牙齿粉末！"
D.Strings[23296]="泥潭蛆虫！"
D.Strings[23297]="尖刺蜘蛛卵！"
D.Strings[23298]="毛茸茸的鲱鱼头！"
D.Strings[23299]="恶臭的海盗汗液！"
D.Strings[23300]="冰冠冰川的水！"
D.Strings[23301]="蜂翼！"
D.Strings[23302]="原始魔精！"
D.Strings[23303]="迅猛龙爪！"
D.Strings[23304]="琥珀种子！"
D.Strings[23305]="燃冰！"
D.Strings[23306]="皱巴巴的龙爪！"
D.Strings[23307]="冰冷的毒蛇粘液！"
D.Strings[23308]="结晶的野猪鼻涕！"
D.Strings[23309]="碎裂的石化蜥蜴水晶！"
D.Strings[23310]="巨魔杀除剂！"
D.Strings[23311]="结冰的蜘蛛毒液！"
D.Strings[23312]="消灭达卡莱巨魔！消灭银色北伐军！将他们统统变成天灾军团的爪牙！"
D.Strings[23313]="我美丽的科尔拉玛斯！你们要为此付出惨痛的代价！"
D.Strings[23314]="蠢货，死神的脚步已经临近！我等你很久了。"
D.Strings[23315]="达卡莱巨魔，别以为这样就能阻挠我们攫取狂野之神的力量。除非你们早已杀掉了这些所谓的神灵，否则他们的力量终将归我们所有。"
D.Strings[23316]="我的双手沾满了银色黎明成员的鲜血。银色北伐军也会落得同样的下场。"
D.Strings[23317]="无论你砍翻多少天灾士兵，我都能令他们重新站起来。如果你不幸丧命的话，我也能让你复生，成为我的仆从。"
D.Strings[23318]="凡人，你们无法与巫妖王的力量抗衡！"
D.Strings[23319]="你们注定会沦为天灾军团的爪牙！"
D.Strings[23320]="我们需要一些……"
D.Strings[23321]="我们得添加一些……"
D.Strings[23322]="接下来，我们需要……"
D.Strings[23323]="很好，再给我拿些……"
D.Strings[23324]="就快大功告成啦！只需要……"
D.Strings[23325]="趁它沸腾之前，我还需要……"
D.Strings[23326]="变浓稠啦！快，拿些……"
D.Strings[23327]="进展顺利，但是还需要一些……"
D.Strings[23328]="就快成功啦。给我找些……"
D.Strings[23329]="该死！你太令我失望了！"
D.Strings[23330]="天哪！药水全毁啦！"
D.Strings[23331]="太晚了。我不得不重新开始……"
D.Strings[23332]="嗯，是时候啦……"
D.Strings[23333]="一堆没用的骨头……"
D.Strings[23334]="没想到就算变身亡灵，你也这么没用。"
D.Strings[23335]="享受永恒的折磨吧。"
D.Strings[23336]="所谓自由，意味着更多的痛苦。"
D.Strings[23337]="够了。"
D.Strings[23338]="这么说，神谕者决定帮助你了。好吧，我会把我所知的一切都告诉你。"
D.Strings[23339]="碎角犀牛的族长法鲁恩就是你的同伴寻找的目标。他很少和族群的其他成员待在一起。"
D.Strings[23340]="法鲁恩喜欢独自在苦潮瀑布以北的林地游荡。你可以在那里找到他；不过你很快就会明白，他并不需要族群其他成员的保护。"
D.Strings[23341]="告诉你的同伴，让他去那里猎杀法鲁恩，然后领取奖赏吧。"
D.Strings[23342]="事情办完之后，就让他趁早离开。他并不属于这里。"
D.Strings[23343]="我真搞不懂这个水果贩子和那些食人魔佣兵。我们之间似乎要爆发战争……但什么都没有发生。"
D.Strings[23344]="水果贩子拒绝接受我的挑战，还不肯把他的马车挪开。而那些食人魔佣兵只是在一旁干坐着……他到底想干什么？"
D.Strings[23345]="我们要买掉这些苹果，但是不能让人们吃下它们。啊，不！我们要把苹果卖给我们的朋友，这样他们就会替我教训那个水果贩子了！"
D.Strings[23346]="我请来的雇佣兵还没有到。我就知道他们不可靠。我们要招募新的人手。卖掉这些苹果，然后让新的部队去踩烂它们！"
D.Strings[23347]="现在就来解决水果的问题。我们对水果贩子实在是太过迁就啦。现在我们要开始卖水果。但这些水果不是给人吃的。我不允许！谁也不准吃我们的水果！"
D.Strings[23348]="水果贩子！！！你的马车还挡着我们的路！我叫你猖狂！现在你要面对新的竞争对手了！"
D.Strings[23349]="你的好日子到头了，水果贩子！！现在我要开始卖你的烂水果了！"
D.Strings[23350]="哈！我踩烂了一只苹果，水果贩子！现在开始，你卖给其他人的苹果也会被他们踩烂的！"
D.Strings[23351]="如果你想要战争，那我就给你战争，水果贩子！我们来看看谁卖掉的苹果多！"
D.Strings[23352]="喝吧！尝尝我的鲜血！尝尝死亡的滋味！"
D.Strings[23353]="我真是受不了你。滚吧，别在我身上白费力气了。"
D.Strings[23354]="那些疯狂的达卡莱巨魔竟然击落了一座浮空城！$B$B他们是如何做到的？！"
D.Strings[23355]="啊，当初真不该抢着要专家的名头。他们老是让我做一些根本就不可能的事！"
D.Strings[23356]="来玩玩吧！"
D.Strings[23357]="你们来的太迟了，洛丹伦的勇士们，现在已经是亡灵的时代了。"
D.Strings[23358]="快，$c！$b$b把材料都扔进去。时间紧迫！"
D.Strings[23359]="<当你靠近时，被俘虏的鳄鱼发出一声低吼。>"
D.Strings[23360]="看来不会有什么危险……来吧。"
D.Strings[23361]="今天特别适合出门劫掠一番，不是吗？"
D.Strings[23362]="嗯，我们必须竭尽所能地帮助他们。"
D.Strings[23363]="远行者，那些炮火……呃，我是说那些人……他们是对抗维库人的重要资源。啊，我说的是“资源”？好吧，我的意思是“盟友”。"
D.Strings[23364]="天哪！别让它靠近我的飞艇！"
D.Strings[23365]="%s从空气中嗅出某种异样的味道。"
D.Strings[23366]="<俯下身去扶起受伤的雨声神谕者。>"
D.Strings[23367]="北伐军！点燃这截木头，为军队提供照明。"
D.Strings[23368]="哎呀，好粘啊！它们是怎么结网的啊？"
D.Strings[23369]="啊！见鬼，我把自己给网住了！粘死啦。哎呀，我的发型！"
D.Strings[23370]="好吧！让我看看能不能将这堆破铜烂铁改造成有用的装置。"
D.Strings[23371]="萨满祭司维克伊克从旁边的灌木丛中走了出来。"
D.Strings[23372]="你竟然帮助雨声鳄鱼人！我都看见了！你这个叛徒！"
D.Strings[23373]="如果你要和大舌头怪交朋友，那你就不是狂心狼獾人的朋友啦！我要告诉全村人！我们再也不会相信你了！"
D.Strings[23374]="萨满祭司维克伊克朝狂心岭的方向奔去。"
D.Strings[23375]="勇敢的士兵，你从未放弃过对抗玛尔加尼斯统帅的天灾军团。继续努力吧。"
D.Strings[23376]="没错。玛尔加尼斯就在十字军广场指挥天灾军团，但是从斯坦索姆入口通往广场的大门都被关闭了。$B$B如果我率领一支小分队穿过市政厅的话，也能抵达十字军广场。所幸的是，玛尔加尼斯并不知道这一点。你愿意加入我们的突袭行动吗？"
D.Strings[23377]="殿下，我们的所作所为都是为了洛丹伦的利益。"
D.Strings[23378]="带路吧，阿尔萨斯王子。"
D.Strings[23379]="我们得搞清楚，为什么天灾军团如此看重这种矿石。"
D.Strings[23380]="科尔法克斯，你知道萨隆邪铁吗？"
D.Strings[23381]="没听说过。它似乎散发着邪恶的气息。"
D.Strings[23382]="我倒要看看它能不能挡住我的斧子！"
D.Strings[23383]="见鬼！连一丝裂痕都没留下！这是我见过的最硬的矿石！"
D.Strings[23384]="终于可以回家啦！"
D.Strings[23385]="谢谢！"
D.Strings[23386]="就快到家啦。走吧！"
D.Strings[23387]="啊啊！它直冲着我们来了！"
D.Strings[23388]="我的胡子！两边不对称了！"
D.Strings[23389]="耳朵！你弄伤了我的耳朵！"
D.Strings[23390]="痛！我不干了，我不要当靶子！"
D.Strings[23391]="天哪！这边的胡须本来是完好的！"
D.Strings[23392]="莱茵，雷布拉特，试试自然与元素的力量？"
D.Strings[23393]="梅兹哼了一声，摆出心不在焉的模样。"
D.Strings[23394]="冷静点，伙计。这只是小号铅弹啊！"
D.Strings[23395]="呸，还是有进步的。"
D.Strings[23396]="女神在上。自然的力量也无法撼动它！"
D.Strings[23397]="别抱怨了。你的运气还不错啊。"
D.Strings[23398]="只是有点伤自尊嘛，伙计。振作一点啦！"
D.Strings[23399]="梅兹？"
D.Strings[23400]="你会什么力量啊。"
D.Strings[23401]="有什么值得大惊小怪的。"
D.Strings[23402]="好吧。不过你记住，圣光的力量是不能随便运用的。"
D.Strings[23403]="怎么回事？！"
D.Strings[23404]="好吧，事情毫无进展。我们还是将这块萨隆邪铁交给大领主弗丁研究吧。"
D.Strings[23405]="朋友们，谢谢你们的尝试。我们一定会揭开其中秘密，只希望一切不会太迟。"
D.Strings[23406]="很快你们就会发现一切都是徒劳无功。"
D.Strings[23407]="萨隆邪铁？"
D.Strings[23408]="我闻到了……$r的气味。好鲜美！"
D.Strings[23409]="我要吃了你！"
D.Strings[23410]="战争之鼓"
D.Strings[23411]="我倒要看看它是否真的坚不可摧。"
D.Strings[23412]="受伤的雨声神谕者笨拙地站了起来。"
D.Strings[23413]="%s掸去身上的灰尘。"
D.Strings[23414]="击落它！"
D.Strings[23415]="圣光！救救我吧！"
D.Strings[23416]="放了我吧！"
D.Strings[23417]="你竟然和大舌头怪搅和在一起！你不再是狂心氏族的朋友了。狂心狼獾人要让你尝尝厉害！"
D.Strings[23418]="不妙！我们被狗狗人跟踪了！"
D.Strings[23419]="跟我来，我知道路。"
D.Strings[23420]="先生，有客户投诉说我们出售的致命药膏中，魔女之毒的含量不足。"
D.Strings[23421]="先生，有客户投诉说我们出售的麻醉药膏中，丧命草的含量过高。"
D.Strings[23422]="先生，我认为上一张配方中死亡根须的用量已经很接近合适剂量了。"
D.Strings[23423]="乌雷特，你调配出新的混合药剂了吗？店里堆满了该死的孢子，我快被烦死了！"
D.Strings[23424]="下次放双倍的剂量好了！"
D.Strings[23425]="下次就放一半的剂量吧。"
D.Strings[23426]="记住：你犯下的错误永远比你想象的要严重得多。给我加双倍的剂量！"
D.Strings[23427]="我还在调制啊，我可不想随便出售连我自己都不满意的半成品。用不了多久啦。"
D.Strings[23428]="残忍的斯卡迪已经进入鱼枪的射程！"
D.Strings[23429]="你每次都这么说。有时候，我甚至怀疑你永远也配制不出那玩意儿。"
D.Strings[23430]="啊，是阿尔萨斯王子。您来的正是时候。"
D.Strings[23431]="是的，我很高兴能在灾难大爆发之前找到你。"
D.Strings[23432]="这是什么巫术？"
D.Strings[23433]="阿尔萨斯，你不需要弄明白这是什么。你唯一要做的，就是等死。"
D.Strings[23434]="部落占领了冬拥堡垒！"
D.Strings[23435]="联盟占领了冬拥堡垒！"
D.Strings[23436]="你要去哪儿吗？我可以送你一程。"
D.Strings[23437]="我能不能搭乘飞行器呀？"
D.Strings[23438]="卡拉，我想飞往亡者之穴寻找比希。"
D.Strings[23439]="嘲讽旗"
D.Strings[23440]="熊坐骑"
D.Strings[23441]="我准备好前往你的村子了。"
D.Strings[23442]="我们等你做好准备再出发。"
D.Strings[23443]="你准备好了的话就告诉我们。"
D.Strings[23444]="等你做好准备，我们就启程回家吧。"
D.Strings[23445]="带我离开这个鬼地方，$r！"
D.Strings[23446]="你们这帮蠢货！终于还是让我逃出来啦！"
D.Strings[23447]="成功了！我终于重获自由！"
D.Strings[23448]="你听到附近传来一声低沉的咆哮。"
D.Strings[23449]="自动跳舞信号发射器"
D.Strings[23450]="别打扰维克伊克。"
D.Strings[23451]="维克伊克，我诚恳地和大舌头怪们谈过了，他们渴望和平。这是他们赠送的求和礼物。"
D.Strings[23452]="你居然和大舌头怪交朋友，真恶心！你不属于这里。赶紧滚出狂心氏族的土地，不然我就召唤魔法生物干掉你！"
D.Strings[23453]="狂心氏族永远不会和大舌头怪做朋友。你这个叛徒，竟然还有脸回来！"
D.Strings[23454]="你要是敢回来，狂心狼獾人就要你的命。从现在开始，你是我们的敌人！"
D.Strings[23455]="没有……我没有背叛狂心氏族的意思。我当时只是……正当防卫啊。完全是个误会。"
D.Strings[23456]="$r飞行员来啦！击落$g他:她;！"
D.Strings[23457]="看来玛尔加尼斯除了天灾军团的亡灵大军外，还另有秘密武器。我们得抓紧时间了。"
D.Strings[23458]="大功告成！霍杜姆，让巨魔饮下这贴药剂。他会老老实实地回答所有问题的……"
D.Strings[23459]="是时候啦，菲肯斯坦。我们来做个试验吧！"
D.Strings[23460]="来吧，巨魔。喝下它！"
D.Strings[23461]="别逼我对你动粗啊，放乖点。"
D.Strings[23462]="嗯，听我说。它不会比这里出售的掺水烈酒更难喝……"
D.Strings[23463]="嘿！一口气喝光吧！"
D.Strings[23464]="作为银色北伐军的成员，我曾以……嗯……那什么……的名义起誓，绝不计较他人的言行过失……"
D.Strings[23465]="我打心眼儿里不想看见这些绿皮肤的野蛮人！"
D.Strings[23466]="他们相貌丑陋，还有难闻的体臭！吃东西的时候狼吞虎咽的……哎哟，想起来就恶心！"
D.Strings[23467]="你可能为我带来救赎的希望。$B$B你也可能将我送入死亡的深渊。"
D.Strings[23468]="朋友，开什么玩笑！这是什么鬼东西啊，我可不要喝……"
D.Strings[23469]="朋友，你是不是先喝上一口，证明这不是毒药？那样我才会喝的。"
D.Strings[23470]="好吧。我同意。但首先，我有个问题……"
D.Strings[23471]="你整天和这帮兽人混在一起，感觉怎么样啊？"
D.Strings[23472]="接受十字军之力的审判吧！"
D.Strings[23473]="我要代表圣光消灭你们！"
D.Strings[23474]="十字军的审判已经降临了，死亡骑士！"
D.Strings[23475]="卑鄙的死亡骑士，你们的末日就要到了！"
D.Strings[23476]="霍杜姆，你这蠢货！现在好了，我必须重新配制药剂！"
D.Strings[23477]="又失败了……"
D.Strings[23478]="你竟然混进了黑锋要塞，十字军！"
D.Strings[23479]="说的好，但这毫无意义……"
D.Strings[23480]="这些十字军伪装成新兵潜入了黑锋要塞。"
D.Strings[23481]="消灭入侵者！"
D.Strings[23482]="令人钦佩的坚韧与魄力！一位新的勇士诞生啦！"
D.Strings[23483]="巫妖王一定会对这位死亡骑士新兵感到满意的。"
D.Strings[23484]="在这样一群可怜虫里，总算有位勇士脱颖而出。"
D.Strings[23485]="混乱！厄运！毁灭！它将拥有一切破坏性的力量！"
D.Strings[23486]="死亡的预言者已经重生……"
D.Strings[23487]="让它穿上阿尔萨斯传令官的服饰。"
D.Strings[23488]="是，教官。"
D.Strings[23489]="仆从们，站起来吧。消灭这些家伙！"
D.Strings[23490]="这一个……"
D.Strings[23491]="黑暗的能量在我体内涌动……强大的力量！我渴求更多的力量！"
D.Strings[23492]="我重获新生，将成为散播厄运的武器……"
D.Strings[23493]="这声音……多么高贵……阿尔萨斯陛下……我的王……"
D.Strings[23494]="为了执行主人的命令，我从坟墓中醒来。"
D.Strings[23495]="遵命，教官。"
D.Strings[23496]="又是这种邪恶的巫术！提高警惕！"
D.Strings[23497]="站起来吧！主人在等待着你们。去吧！"
D.Strings[23498]="听，死亡骑士……是主人的声音。他在召唤你。"
D.Strings[23499]="遵命，教官！"
D.Strings[23500]="我的生命只属于巫妖王陛下！"
D.Strings[23501]="天灾军团必胜！"
D.Strings[23502]="胆敢反抗的都要死！"
D.Strings[23503]="我们走吧。"
D.Strings[23504]="为我报仇！"
D.Strings[23505]="我的生命……结束了。"
D.Strings[23506]="我的宝藏！可耻的叛徒，不许偷塔尔特克的东西。"
D.Strings[23507]="太迟了，我撑不下去了。"
D.Strings[23508]="塔尔特克要和凶暴的龙一起杀了你！蠢货。"
D.Strings[23509]="我得救了！"
D.Strings[23510]="朋友，我欠你一份情。"
D.Strings[23511]="你没见过始祖龙吗？喏，这周围到处都是啊。祝你狩猎愉快。"
D.Strings[23512]="小心背后，我们被包围了。"
D.Strings[23513]="玛尔加尼斯不会让我们好过的。"
D.Strings[23514]="%s开始施放强化魔爆术！"
D.Strings[23515]="它们还真是够顽强的。"
D.Strings[23516]="他还会派些什么东西来阻挡我们？"
D.Strings[23517]="通向玛尔加尼斯的最短路线就在前面那个书架之后。"
D.Strings[23518]="不要给他喘息的机会！"
D.Strings[23519]="如果伦诺克恢复力量，那我们就死定了！"
D.Strings[23520]="必须让巨熊之神处于虚弱状态，这样先知才能完成仪式。"
D.Strings[23521]="入侵者！杀死他们，不然他们会毁了一切！"
D.Strings[23522]="阿尔萨斯·米奈希尔王子殿下，今天，你的灵魂已经被某种强大的黑暗力量侵蚀。你想要以死亡净化这座城市，现在你也要面对毁灭的命运了。"
D.Strings[23523]="我就知道会这样……"
D.Strings[23524]="那艘船肯定会撞上我……"
D.Strings[23525]="我不敢睁眼……"
D.Strings[23526]="他们就不能放慢速度吗？"
D.Strings[23527]="为了洛丹伦，我会竭尽所能，无论是你的言论还是行为，都无法阻止我。"
D.Strings[23528]="居然还不减速！"
D.Strings[23529]="那就来吧，年轻的王子。"
D.Strings[23530]="完蛋了……"
D.Strings[23531]="我还没有告诉儿子，他是我的骄傲……再也没有机会了……"
D.Strings[23532]="我还不想死……"
D.Strings[23533]="我还有很多梦想没有实现……"
D.Strings[23534]="莫格莱尼，让那把该死的剑闭嘴。它发出的哀鸣令我难以忍受。"
D.Strings[23535]="让它闭嘴！什么破玩意儿！吵个不停，我简直没法思考！"
D.Strings[23536]="很抱歉，我们的啤酒只对“本月美酒俱乐部”的会员出售。"
D.Strings[23537]="这座岗哨目前是安全的，$r。$b$b敌人暂时不敢再次来犯。"
D.Strings[23538]="天灾军团扩张如此迅速，我有时都忍不住会想，他们怎么还没赢得这场战争呢。"
D.Strings[23539]="啊，终于回到了达克萨隆要塞！"
D.Strings[23540]="达库鲁凝视着达克萨隆要塞。"
D.Strings[23541]="朋友，干得好……"
D.Strings[23542]="哈！瑟匹克没说错，猎杀大舌头怪是挺好玩的！"
D.Strings[23543]="狩猎大舌头怪真有趣啊！格利基克以后要常带奴隶来玩！"
D.Strings[23544]="没准卡塔克待会就出现，然后吞下整个村子！哈！"
D.Strings[23545]="猎杀钢刺野猪的难度大得多！愚蠢的大舌头怪。"
D.Strings[23546]="格利基克是最棒的猎人，是不是啊？"
D.Strings[23547]="尝尝长矛的滋味！哈哈！格利基克挺爱开玩笑的。"
D.Strings[23548]="你远远超出了我的期望。"
D.Strings[23549]="那些嗡嗡叫的蓝蜂都躲在格利基克打不到的地方。"
D.Strings[23550]="交给达伊克来办吧。奴隶，我们走。"
D.Strings[23551]="这里没有钢刺野猪，我们去别的地方吧。"
D.Strings[23552]="听着，奴隶……格利基克被那只坏心肠的蜂后蜇过。所以啊，格利基克才不要招惹它们。"
D.Strings[23553]="格利基克喜欢猎杀大舌头怪，但他们的数量似乎太多了点。"
D.Strings[23554]="奴隶，这里很不安全。这里是大舌头怪的老窝。"
D.Strings[23555]="狂心狼獾人不会独自闯入这里。奴隶也不该。"
D.Strings[23556]="你去将他们引出来。我待在这里监视情况。去吧，好戏即将上演。"
D.Strings[23557]="我可不管长者怎么说，反正你永远都是格利基克的奴隶。"
D.Strings[23558]="别想偷懒。奴隶，赶紧做事！"
D.Strings[23559]="你永远无法达到格利基克的境界。"
D.Strings[23560]="格利基克是最最优秀的钢刺野猪猎手！"
D.Strings[23561]="匹奇根本构不成威胁嘛……要不然格利基克肯定不会放过他。"
D.Strings[23562]="你真没用。格利基克干嘛要为你心烦啊。"
D.Strings[23563]="死在格利基克手里的钢刺野猪可以填满河流之心！"
D.Strings[23564]="不知道山那边有没有钢刺野猪。格利基克要找时间去瞧瞧。"
D.Strings[23565]="破柱子附近根本没有钢刺野猪，只看见一堆死尸。奴隶，跟格利基克走吧。"
D.Strings[23566]="蠢奴隶，你要是想死，就径直朝那根破柱子走过去吧。格利基克还想活命呢，我先撤了。"
D.Strings[23567]="为什么要去破柱子那里啊？你这个蠢奴隶。格利基克要走了。"
D.Strings[23568]="这里只有一堆死尸。格利基克要走了。"
D.Strings[23569]="格利基克没有见过卡塔克。格利基克猜想，他或许没有别人说的那么坏吧。"
D.Strings[23570]="拉克亚克说卡塔克曾经一口吞下整座村子的大舌头怪。他们的味道想必美极了。"
D.Strings[23571]="奴隶，离卡塔克远点。他可能会一口吃掉你。"
D.Strings[23572]="很久很久以前，卡塔克翻越群山来到狂心氏族的领地。那时候，拉克亚克用大舌头怪奴隶来喂他，所以现在卡塔克不会找狂心狼獾人的麻烦。"
D.Strings[23573]="狂心狼獾人用大舌头怪喂养卡塔克，保证自己不会沦为他的食物。奴隶，这就是我们比你聪明的证据。"
D.Strings[23574]="或许狂心氏族该把你送去喂卡塔克，奴隶。"
D.Strings[23575]="狂心狼獾人最厉害！"
D.Strings[23576]="到家啦！奴隶，你最好为格利基克带回了足够的肉。"
D.Strings[23577]="格利基克去搞点酒喝。你乖乖地待在角落里等我。"
D.Strings[23578]="格利基克饿死了。奴隶，快趴到火堆上去。等你烤熟之后告诉格利基克一声。"
D.Strings[23579]="你最好耐心地等着格利基克。"
D.Strings[23580]="格利基克要去睡一会儿。奴隶，你去给我搞点吃的回来。"
D.Strings[23581]="格利基克的主要工作之一就是猎捕硬皮猩猩。"
D.Strings[23582]="猎杀硬皮猩猩对格利基克来说容易极了……它们很愚蠢的。"
D.Strings[23583]="奴隶，你待在一旁看着就是了。让格利基克来对付这些硬皮猩猩！"
D.Strings[23584]="别挡格利基克的道！"
D.Strings[23585]="吃到苦头了吧！哈哈！你这蠢奴隶。"
D.Strings[23586]="当心点，坏心肠的软皮猩猩能一口吃掉你！哈哈！"
D.Strings[23587]="恶心的大舌头怪！它在这里干什么？！"
D.Strings[23588]="奴隶，杀死大舌头怪！"
D.Strings[23589]="奴隶，看好格利基克身后！我要好好地惩罚一下大舌头怪！要帮格利基克留神背后！"
D.Strings[23590]="空气中散发着大舌头怪的臭味！"
D.Strings[23591]="啊！快看！格利基克可以将大舌头怪串起来做项链！"
D.Strings[23592]="嘿，奴隶……不知道烧烤大舌头怪吃起来怎么样。"
D.Strings[23593]="%s把一面强者的旗帜插在了$n的尸体上。"
D.Strings[23594]="哈！是格利基克杀的！"
D.Strings[23595]="下次你也要帮忙啊，奴隶。不能把所有的活儿都丢给格利基克。"
D.Strings[23596]="格利基克是最好的猎人……永远是。"
D.Strings[23597]="一击必中！格利基克真厉害。"
D.Strings[23598]="它甚至没有发现格利基克。"
D.Strings[23599]="你是要帮我一把呢，还是就坐在一旁偷懒？"
D.Strings[23600]="格利基克为什么要带上你啊。你这废物。"
D.Strings[23601]="下次格利基克让你试试。"
D.Strings[23602]="联盟哨塔被摧毁了！"
D.Strings[23603]="部落哨塔被摧毁了！"
D.Strings[23604]="凭借邪恶的力量，我们才能统御亡者！"
D.Strings[23605]="奥莉丝塔夫人，我想接受训练。"
D.Strings[23606]="鲜血就是生命……如果能随意掌控鲜血的奔涌，那么敌人的性命也就如同掌中玩物了。"
D.Strings[23607]="索瓦尔勋爵，我想接受训练。"
D.Strings[23608]="凛冽的北风承载着我们散发出的不祥气息。我们就像绝望的寒冬……接受死亡的冰封之拥吧……"
D.Strings[23609]="阿曼萨加德，我想接受训练。"
D.Strings[23610]="将你的肉体抛诸脑后吧！"
D.Strings[23611]="多里安，你错过了一场惊心动魄的战斗！真是难忘的经历啊！"
D.Strings[23612]="我们骑在斯塔比背上，全速开战……"
D.Strings[23613]="我感觉周围的景象在颤抖，差点抓不住手中的枪。"
D.Strings[23614]="接着，那只恐怖的野兽进入了我们的视线！"
D.Strings[23615]="$n全神贯注地控制斯塔比战斗。"
D.Strings[23616]="达卡莱帝国走上了自我毁灭的道路，我们为此感到悲哀。$B$B他们通过弑神夺来的力量只能维持一段很短的时间。$B$B这短暂的收益将葬送达卡莱帝国的未来。"
D.Strings[23617]="这场战斗真是腥风血雨啊。母龙的攻击速度越来越快了！"
D.Strings[23618]="但是，我，还有$n凭借卓越的智慧和完美的合作，最终取得了胜利。喏，这就是我们的战利品。"
D.Strings[23619]="这就是反抗巫妖王的下场！"
D.Strings[23620]="多里安，怎么你看上去有点嫉妒啊？"
D.Strings[23621]="呃，才没有。我是来照料篝火堆的，顺便找苏特菲兹谈谈机械零件的缺陷问题。我承认，这件战利品看上去是挺不错的。"
D.Strings[23622]="集中精神，我们必须继续前进。"
D.Strings[23623]="这只需要一小会儿。"
D.Strings[23624]="我确信这条秘道还通着。"
D.Strings[23625]="局势严峻。斯坦索姆正在燃烧。我们必须穿越着火带，击杀沿途的天灾军团，设法抵达玛尔加尼斯所在的十字军广场。做好准备吧。"
D.Strings[23626]="为洛丹伦而战！"
D.Strings[23627]="休息一会，你们抓紧时间喘口气，我们马上就得重新上路。"
D.Strings[23628]="希姆托加倒是能为我们提供一定的保护，但是天灾军团的势力不断扩张，再加上达卡莱帝国的弑神举动，她的力量已经被严重削弱了。$B$B因此防御的重任就落在我和埃霍奈的肩上了。"
D.Strings[23629]="就这样吧，我们必须继续上路了。玛尔加尼斯在等着我们呢。"
D.Strings[23630]="圣光在上。市场小径还没有着火。玛尔加尼斯应该就躲藏在前面的十字军广场。你们准备好继续前进的话，就告诉我。"
D.Strings[23631]="走吧，朋友。谢谢你。"
D.Strings[23632]="必须保护希姆托加，不能让那些愚蠢的达卡莱巨魔偷走她的力量。"
D.Strings[23633]="你从大地中来，就该回到大地中去。"
D.Strings[23634]="你甘愿奉献生命，我们以你为荣。"
D.Strings[23635]="诱使它踩进陷阱！"
D.Strings[23636]="绝不能让达卡莱巨魔突破防御线。"
D.Strings[23637]="这是我能赋予你的全部力量了。全力战斗吧，我的地灵朋友。"
D.Strings[23638]="愚蠢的奴隶，别挡道！这是格利基克的猎物！"
D.Strings[23639]="哈哈！格利基克是最最厉害的猎手！格利基克杀死了个头最大的硬皮猩猩！"
D.Strings[23640]="奴隶，看清楚了吧。或许有一天你也能领悟这一招。"
D.Strings[23641]="来找格利基克报仇啊！让那些愚蠢的硬皮猩猩从背后攻击我啊。"
D.Strings[23642]="吃饭时?！"
D.Strings[23643]="格利基克饿了。"
D.Strings[23644]="你一边呆着去，奴隶。格利基克正在吃饭呢。"
D.Strings[23645]="趁格利基克吃饭的时候，你去多杀些猎物吧。"
D.Strings[23646]="鸡！好吃！"
D.Strings[23647]="格利基克要去抓鸡！"
D.Strings[23648]="奴隶！快来帮格利基克抓鸡啊！"
D.Strings[23649]="别害怕呀。格利基克不会把你丢进火里烤的。格利基克是个好心肠的狼獾人。"
D.Strings[23650]="它们可真灵活！"
D.Strings[23651]="快跑呀，软皮猩猩！格利基克来抓你们啦！"
D.Strings[23652]="啊！吓坏了吧！"
D.Strings[23653]="软皮猩猩是我们重要的生活来源。"
D.Strings[23654]="埃霍奈的斧头就是达卡莱巨魔的末日。$B$B即便有一些漏网之鱼从我的斧下逃脱，你也会干掉他们！"
D.Strings[23655]="这个位置似乎不错。锁定目标，当你发现母龙后，迅速做好准备，然后向我发出信号。"
D.Strings[23656]="来吧，野兽！来跟赫米特玩玩！"
D.Strings[23657]="尝尝厉害吧，野兽！"
D.Strings[23658]="这招怎么样啊，嗯？"
D.Strings[23659]="看枪！"
D.Strings[23660]="它们的体型越大，摔得就越惨。"
D.Strings[23661]="狡猾的法师领主伊洛姆守护着第三道环。表面上他显得孤立无援，但那不过是欺骗敌人的假象！伊洛姆是位强大的咒术师，能召唤各种幽灵生物为他作战。去上面找他吧。\n\n我能赋予你召唤红玉幼龙协同作战的能力。当然，如果你希望借助青铜龙或是绿龙的力量，就去找伊特努斯或是沃尔蒂萨谈谈。"
D.Strings[23662]="你即将面临迄今为止最大的挑战。魔网守护者埃雷苟斯，这只蓝龙拥有超乎想象的可怕力量。埃雷苟斯在魔枢的最高环飞翔。\n\n现在，幼龙的终极力量已经解封。利用它们的力量击败埃雷苟斯吧！"
D.Strings[23663]="你从玛里苟斯的部队手中夺得了魔环的控制权。红龙军团欠你一个人情。"
D.Strings[23664]="青铜龙军团欠你一个人情。"
D.Strings[23665]="绿龙军团欠你一个人情。"
D.Strings[23666]="红玉幼龙有什么能力？"
D.Strings[23667]="琥珀幼龙有什么能力？"
D.Strings[23668]="翡翠幼龙有什么能力？"
D.Strings[23669]="红玉幼龙的终极技能是什么？"
D.Strings[23670]="琥珀幼龙的终极技能是什么？"
D.Strings[23671]="翡翠幼龙的终极技能是什么？"
D.Strings[23672]="红玉幼龙擅长降低伤害以及保护盟友。\n\n它们使用灼热之怒喷出液体火焰，在敌对目标之间跳跃，每次跳跃都能增加对目标的伤害。\n\n当红玉幼龙受到攻击时，它将获得可叠加的闪避能量，由此触发的闪避机动可使幼龙暂时躲过接下来的攻击与法术伤害。"
D.Strings[23673]="琥珀幼龙擅长操控时间来制造伤害。\n\n它们使用震击之枪扰乱敌对目标附近的时间流，立即对目标造成伤害。震击能量将在目标身上叠加，叠加次数越多，目标受到的伤害就越高。\n\n危急时，琥珀幼龙还能停止敌对目标的时间流。在这种情况下，目标身上将储存大量的震击能量。"
D.Strings[23674]="翡翠幼龙擅长在毒伤敌人的同时治疗自己。\n\n它们使用吸血之毒从敌对目标身上偷取生命。毒药可以叠加，每次叠加都能增加生命偷取的效果。\n\n翡翠幼龙还能使用噩梦之触进入梦境，将一部分自身的生命能量转化成高伤害的攻击，令敌对目标虚弱并在短时间内降低目标造成的伤害。"
D.Strings[23675]="拥有终极力量的红玉幼龙可以使用殉难，撑起护盾保护友方目标，短时间内对友方目标的所有魔法伤害将由红玉幼龙承担。使用该技能的同时仍可触发闪避机动。"
D.Strings[23676]="全盛状态的琥珀幼龙可以使用时间裂隙，制造出压缩时间结界包围敌对目标。穿过结界的法术将对该目标造成双倍的伤害，还能在目标身上叠加震击能量。"
D.Strings[23677]="全盛状态的翡翠幼龙可以使用梦境通道，将自身的生命能量转移到友方目标身上，以此进行治疗。使用该技能的同时仍可利用吸血之毒恢复生命值。"
D.Strings[23678]="小……小姐，您的盔甲需要抛……抛光吗？"
D.Strings[23679]="小……小姐，您的战马需要梳……梳洗吗？"
D.Strings[23680]="小……小姐，您的战斧需要打……打磨吗？"
D.Strings[23681]="小……小姐，您需……需要更多的尸尘吗？"
D.Strings[23682]="遵命，尊贵的小……小姐……"
D.Strings[23683]="离我远点，爱德华。否则我要你好看。"
D.Strings[23684]="不需要。可怜虫，给我滚开。"
D.Strings[23685]="别出现在我面前，不然我杀了你。我再说一次。"
D.Strings[23686]="不要。滚远点。"
D.Strings[23687]="异端！清算之日即将来临！"
D.Strings[23688]="圣光会将你从这个世界上抹除！"
D.Strings[23689]="你无法阻止血色十字军前进的脚步！"
D.Strings[23690]="你们是十字军不共戴天的仇敌！"
D.Strings[23691]="所有人都将屈服于血色十字军的力量！"
D.Strings[23692]="他们会来救我的……别以为这些可笑的牢笼能永远禁锢我！"
D.Strings[23693]="愿圣光原谅你犯下的一切过错。"
D.Strings[23694]="你还不明白我们为什么要反抗十字军吗？"
D.Strings[23695]="银色黎明将战斗到底！"
D.Strings[23696]="兄弟姐妹们，一切还来得及。忏悔吧！你们会得到救赎的。"
D.Strings[23697]="我的死只会令同胞们坚定必胜的决心。有胆你就动手吧！"
D.Strings[23698]="对于你付出的努力，我一定要给你丰厚的报酬……"
D.Strings[23699]="真相！"
D.Strings[23700]="朋友，现在来安静地领悟真相吧！"
D.Strings[23701]="我……我就要挂了……要坚持……不住了……"
D.Strings[23702]="你在考验我的耐心，现在就让你见识一下蓝龙的真正力量。"
D.Strings[23703]="哈！别想夺走我的财宝！"
D.Strings[23704]="杀光他们！杀光他们，夺回希姆托加！"
D.Strings[23705]="主人，我的任务完成了。"
D.Strings[23706]="杀死赞达拉巨魔和他们的傀儡！谁也别想阻止我们！"
D.Strings[23707]="在这些凡人的帮助下，所有胆敢反抗我们的家伙都已经被清除了。"
D.Strings[23708]="波利安小姐……你愿意……"
D.Strings[23709]="你愿意收下这枚戒指吗？"
D.Strings[23710]="你做得很好，达库鲁。"
D.Strings[23711]="你对达卡莱帝国的背叛为我制造出了一支新的军团。"
D.Strings[23712]="噢，查德……我当然愿意！"
D.Strings[23713]="你的军团……"
D.Strings[23714]="平身，接受我的赏赐吧。"
D.Strings[23715]="幼龙的终极力量已经解封。利用它们的力量击败埃雷苟斯吧！"
D.Strings[23716]="朋友，欢迎你。在这里记得随时保持警惕！"
D.Strings[23717]="硬皮猩猩很烦呀。我们为什么还来这里？"
D.Strings[23718]="要是你不停地杀硬皮猩猩，就会成为格利基克那样的家伙。你想变成他那样吗？"
D.Strings[23719]="如果你是来戳软皮猩猩的话，达伊克就要戳你了。别学格利基克的坏习惯。"
D.Strings[23720]="哈……我们在哪儿？不对呀。我们不是来找硬皮猩猩的吧？"
D.Strings[23721]="不久前，狂心氏族在这里安了新家……大舌头怪的屋子看上去很漂亮啊，我们其实可以抢来自己住。它们那么丑，才不配住这么好看的地方。"
D.Strings[23722]="等等，听我说。"
D.Strings[23723]="看看你有没有忘记什么东西啊。我以前就老忘事儿。"
D.Strings[23724]="我在栅栏上安了许多尖刺。它们看上去挺锋利的。你觉得呢？"
D.Strings[23725]="这里有许多优秀的猎手，大部分都是达伊克调教出来的。不过教你这样的家伙还是头一次。要知道，你并不是狂心氏族的成员。"
D.Strings[23726]="当心那些幼崽。狂心狼獾人从小就很阴险。"
D.Strings[23727]="我知道你还在不断地学习，但是大舌头怪很坏。狂心狼獾人是好人，大舌头怪是坏人，明白吗？"
D.Strings[23728]="戳它的眼睛，大舌头怪最讨厌这一招了。"
D.Strings[23729]="嗯，玩够啦。杀死它算了。"
D.Strings[23730]="我知道它们长得很滑稽，但是你也别老盯着看啊，多杀些吧。"
D.Strings[23731]="啧啧，你们俩要做朋友吗？要不要在沼泽里安个窝再生一堆不大不小的中舌头怪啊？真浪漫啊……省省吧，别犯傻了。"
D.Strings[23732]="我觉着它挺喜欢你的。要不我们把它带回去，然后温柔地说：“大舌头乖乖，跳进锅里去吧。”你觉得怎么样？"
D.Strings[23733]="听听达伊克的小建议吧！别想骑上卡塔克。"
D.Strings[23734]="卡塔克喜欢吃大舌头怪。但是它饿极了的话，也会吃狂心狼獾人。所以，千万别饿着卡塔克。"
D.Strings[23735]="这场战斗似乎持续好一阵子了，怎么没瞧见别的狼獾人？"
D.Strings[23736]="这里不是狂心岭！我们又迷路了？"
D.Strings[23737]="你学得可真够慢的。我只是说说而已。"
D.Strings[23738]="你肯定特想知道我们烧烤的肉是打哪儿来的吧。就不告诉你，哈哈，这是秘密。"
D.Strings[23739]="哈！或许你能学到点什么！"
D.Strings[23740]="蜂后是杀不绝的。很快就会产生新的蜂后。"
D.Strings[23741]="什么！你杀死了蜂后！怎么可能……呃，没什么。好吧，没什么。"
D.Strings[23742]="对！多捅几下，以防万一！捅得好！捅得好！"
D.Strings[23743]="真不明白它怎么能捕杀那些多生物。不过反正它已经死了，威胁解除啦。"
D.Strings[23744]="达伊克的上一个学徒就是被躲在沙里的怪物给吃掉的。我们最好别落得同样的下场！"
D.Strings[23745]="危急时候，它通常会钻进沙里逃走的。看来这次它逃得不够快啊。"
D.Strings[23746]="我都没怎么见过。虽然不够漂亮，但是还将就吧。"
D.Strings[23747]="再来听听达伊克的小建议！好多亡灵啊，这意味着我们有很大的几率被变成亡灵。达伊克要逃命去了。"
D.Strings[23748]="好吧！你什么都学会啦！没错！达伊克不管你了，你去研究那根邪恶的红柱子吧。"
D.Strings[23749]="这根倒塌的柱子看上去很不安全。达伊克要走了，你也赶紧跟上吧。"
D.Strings[23750]="你看那堆死尸，这就是靠近破柱子的下场。它们已经得到教训了。我们回家吧。"
D.Strings[23751]="再来听听达伊克的小建议！如果格利基克又把鸡给放跑了，就让他把鸡们都捉回去。"
D.Strings[23752]="你可能没注意到，鸡……跑得有点快。"
D.Strings[23753]="狂心狼獾人不去追鸡是有原因的。因为如果追不上的话，就太丢脸了。"
D.Strings[23754]="噢！达伊克想到个办法！我们来学鸡叫，它们或许会循声而来！"
D.Strings[23755]="跑来跑去的……弄得达伊克再也不想吃鸡肉了。"
D.Strings[23756]="我们改吃钢刺野猪怎么样？我不要再跑来跑去的。"
D.Strings[23757]="再来听听达伊克的小建议！在你搜刮战利品之前，要确保敌人已经死翘翘了。"
D.Strings[23758]="这次干得还算不错。仅仅是不错而已。"
D.Strings[23759]="把尸体清理干净！达伊克最讨厌剥皮的时候被什么东西给挡着了。很烦人的。"
D.Strings[23760]="达伊克训练出来的幼崽杀得都比你快。你要学的东西还很多啊。"
D.Strings[23761]="你瞧见它的脸了吗？一副惶恐的表情，“啊，我要被那个大家伙砸扁啦！”哈哈哈。"
D.Strings[23762]="看上去很痛苦的样子。"
D.Strings[23763]="达伊克从来没有见你吃过东西。你也要吃东西的，对吧？"
D.Strings[23764]="我们是来干什么？达伊克又忘记啦。"
D.Strings[23765]="再来听听达伊克的小建议！尽量别用脸去挡刺。没什么用的。"
D.Strings[23766]="我本来想写一份详细的攻击计划的……但是你拿走了我的笔。"
D.Strings[23767]="雄蜂只是外表凶悍而已，其实很容易对付的。巨蜂就比较麻烦一点。"
D.Strings[23768]="我们来这里是有目的，对吧？我想不起来了。"
D.Strings[23769]="每次来虫巢，达伊克都觉得这里的巨蜂又变多了。它们的数量怎么就不见少呢？"
D.Strings[23770]="我告诉你，被蜇的滋味可不好受。你最好别去尝试。"
D.Strings[23771]="再来听听达伊克的小建议！水晶不适合用来挠背。你最好别去尝试。"
D.Strings[23772]="有时候大舌头怪会来这里采集水晶。当然，它们现在敢来的话，就是找死。"
D.Strings[23773]="巨峰喜欢蓝色水晶。不过达伊克不明白这是为什么。"
D.Strings[23774]="某个强大的存在制造了柱子、水晶以及别的东西。不过它已经不在这里了，所以我们不用害怕。"
D.Strings[23775]="再来听听达伊克的小建议！去大舌头怪的祭坛搅乱虽然很好玩，但是你最好别贸然冲进舌头堆。"
D.Strings[23776]="瑟匹克是狩猎大舌头怪的高手。达伊克本来打算将他训练成蓝蜂猎手的，但他却选择了别的道路。"
D.Strings[23777]="大舌头怪非常宝贝那些用来供奉祭坛的水晶。我们砸碎水晶的话，它们就会发火。"
D.Strings[23778]="达伊克见过很多象你这样不长毛的家伙。狂心氏族不会放弃自己的领地，你还是小心点比较好。"
D.Strings[23779]="有些没毛的家伙和大舌头怪成了好朋友……达伊克觉着这太傻了。"
D.Strings[23780]="这些家伙很容易对付！先杀它们！"
D.Strings[23781]="达伊克一直想教我狩猎的技巧，事实上，我按自己的方式来做，效果反而更好。"
D.Strings[23782]="只要你能带回上等的肉，我们就把你当作高阶萨满祭司那样伺候一天。很不错的交易吧。"
D.Strings[23783]="你应该把鸡们都放出来，然后说是格利基克干的。这招屡试不爽。"
D.Strings[23784]="我又不急着办什么事。我们甚至可以在这里休息一阵子。"
D.Strings[23785]="我很少呆在营地……不久前，我还独自游历了不少地方呢。嗯，我喜欢那些关于野兽、巨龙和神灵的传说。"
D.Strings[23786]="长者哈尔卡克是个大好人。在我年幼的时候，他帮过我很多忙，一点也不像达伊克。"
D.Strings[23787]="如你所知，鳄鱼人都是大坏蛋。"
D.Strings[23788]="希望你正在计划消灭大舌头怪的秘密方案。"
D.Strings[23789]="如果我踩到它的尾巴，那绝对是个意外。"
D.Strings[23790]="通常我都是直接杀掉这些家伙的。你知道的，对吧？"
D.Strings[23791]="我讨厌和大舌头怪同行。"
D.Strings[23792]="我知道你想干什么……如果我们好好待它，说不定它会带我们去找更多的大舌头怪。"
D.Strings[23793]="最好离卡塔克远点。他只会在吃饱喝足的时候将狂心狼獾人视为朋友……你要明白，他的胃口简直像个无底洞。"
D.Strings[23794]="我在这里掌握了许多狩猎大舌头怪的技巧。它们的数量很多，完全可以用来练习。"
D.Strings[23795]="听着激烈的厮杀搏斗声，远比待在营地舒畅啊。"
D.Strings[23796]="在卡塔克成为我们的“朋友”之前，他吃掉了很多狂心狼獾人。这件事很少有人提及。"
D.Strings[23797]="你见过塔尔特克吗？他是氏族最优秀的战士之一……他统领着西北部的土地。我听说他还捕获过龙。说实话，我有点嫉妒他。"
D.Strings[23798]="就狂心狼獾人来说，萨满祭司亚克耶克显得安静了些，但是他拥有强大的力量。这或许是卡塔克不敢肆意妄为的唯一禁忌。"
D.Strings[23799]="破柱子不欢迎狼獾人。我要回去了，你把事情办完之后再来找我吧。"
D.Strings[23800]="许多狂心狼獾人都在破柱子附近失踪了。今天不会轮到瑟匹克吧。"
D.Strings[23801]="我想过设局把大舌头怪骗来这里，但对我来说这太危险了。那么，祝你好运，我们营地见。"
D.Strings[23802]="真不该来这里……我还有很多冒险计划呢，干嘛要来这个鬼地方玩命。小心点……我们待会见。"
D.Strings[23803]="哈哈哈！你看见没有？闪电直接击中了他！"
D.Strings[23804]="砰！真棒！再来！再来！"
D.Strings[23805]="我们以后还要来玩这个！太有趣啦……闪电把大舌头怪打得抱头鼠窜！"
D.Strings[23806]="附近的湖里全是海洋生物。不知道是怎么来的……莫非是洪水？"
D.Strings[23807]="我喜欢狩猎大舌头怪的原因之一……就是它们不像其他猎物那样愚蠢。懂得耍花招的猎物才是真正的挑战。"
D.Strings[23808]="雾语大舌头怪很会利用那些祭坛捣鬼……它们能让迷雾覆盖整片区域，令我们难以发现它们的行踪。"
D.Strings[23809]="小心那只大个子的唤雾者……瑟匹克曾和他打过一次，根本不是他的对手，只能狼狈地逃掉了。他远比其他的大舌头怪厉害。"
D.Strings[23810]="这算不上什么伟大的狩猎，但是玩过很多次之后我仍然觉得非常有趣。"
D.Strings[23811]="你觉得他们会吸取教训，不许格利基克靠近鸡舍？"
D.Strings[23812]="格利基克才不会错过抓鸡活动呢……格利基克得填饱他的肚子。每次抓完鸡，我们都会发现有一只鸡不见了。"
D.Strings[23813]="这些鸡比我想象中难对付！我不该掉以轻心的！"
D.Strings[23814]="技术不错嘛！狩猎手法和我一样纯熟自然。"
D.Strings[23815]="格利基克总是摆出一副高高在上的模样，但这家伙每天吃那么多，打回来的猎物却少得可怜。"
D.Strings[23816]="达伊克经常会忘记他在做什么，忘记他在哪儿……甚至会忘记自己的名字。有时候，他还真算不上是个好老师。"
D.Strings[23817]="你有没有跟巨龙、神灵或者别的什么打过架啊？瑟匹克最喜欢听故事啦。"
D.Strings[23818]="干得好！它一点也没有察觉。"
D.Strings[23819]="哈哈！给瑟匹克留点猎物吧。"
D.Strings[23820]="烈焰！死亡！毁灭！黑色的火焰在我心中燃烧！我必须……释放它！哈哈哈！"
D.Strings[23821]="你有没有发现，洞穴中有时会传来隆隆声。一定有什么生物潜伏在里面。"
D.Strings[23822]="大舌头怪通常不敢来这里……我曾在这里和它们交过手，杀死了很多大舌头怪。"
D.Strings[23823]="我很想知道水都流到哪儿去了……真搞不明白。"
D.Strings[23824]="维克伊克最喜欢找那些在盆地里迷路的大舌头怪的麻烦。他帮我用陷阱抓过好几只愚蠢的家伙。你可以去瞧瞧他是怎么做的……很有趣。"
D.Strings[23825]="冲突已经持续好一阵子了……这里的大舌头怪似乎很有斗志。"
D.Strings[23826]="这里的大舌头怪也供奉祭坛，但这座祭坛有一个守护者。如果它出现的话，你就要当心。"
D.Strings[23827]="跟一个聪明的猎手一起狩猎，感觉真是不错。你很擅长狩猎嘛。"
D.Strings[23828]="或许我不再是大舌头怪唯一害怕的强者了。你打斗的样子也很吓人。"
D.Strings[23829]="欢迎来到营地，$c。"
D.Strings[23830]="科弗斯能为你提供什么服务？"
D.Strings[23831]="我需要修理装备和购买物资，科弗斯。"
D.Strings[23832]="使用灼热之怒对敌人造成伤害；如果我开始承受伤害，就使用闪避机动。记住，我必须以承受伤害的方式积攒闪避能量，才能使用闪避机动！"
D.Strings[23833]="使用吸血之毒对敌人造成伤害，同时保持对我的治疗。噩梦之触非常强大，但会对我造成伤害，所以只能在我的生命值较高的情况下使用！"
D.Strings[23834]="使用震击之枪对敌人造成伤害。如果我们遇到麻烦，就使用停止时间将敌人冻结，然后使用震击之枪对他们造成大量伤害！"
D.Strings[23835]="我伤得很重！我无法承受更多的伤害了！"
D.Strings[23836]="我已经具备全部力量，可以使用时间裂隙了。你能利用它对敌人造成额外的伤害并获得震击能量。积攒足够的能量后，再使用震击之枪造成大量伤害！"
D.Strings[23837]="我已经具备全部力量，可以使用梦境通道了。你能利用它治疗其他幼龙，但这个技能会消耗我的生命值，因此必须与吸血之毒配合使用！"
D.Strings[23838]="我已经具备全部力量，可以使用殉难了。你能利用它保护其他幼龙，但这会让我承受大量伤害，因此必须与闪避机动配合使用！"
D.Strings[23839]="拉弗乌的宝藏！祭坛的宝藏！"
D.Strings[23840]="我挖，我挖，我挖……"
D.Strings[23841]="没准还有更多闪闪发亮的虫虫！我们爱虫虫！"
D.Strings[23842]="当心那只大怪兽！它会吃掉我们！"
D.Strings[23843]="这里好多狗狗人啊。或许他们想和我们交朋友？"
D.Strings[23844]="我们离开这里好不好啊？我有点害怕。"
D.Strings[23845]="这里没有虫虫……虫虫都到哪里去了呢？"
D.Strings[23846]="不好玩。这里不好玩。"
D.Strings[23847]="声音……到处都能听见，是幽灵！快跑呀！"
D.Strings[23848]="虫虫都不见了。这里是个坏地方……我们不要呆在这里。"
D.Strings[23849]="我们不喜欢这里。要不你办完事之后再来找我们。"
D.Strings[23850]="大坏蛇，你再也别想吃掉幼体了！"
D.Strings[23851]="它再也不能来捣乱啦！"
D.Strings[23852]="你很强！呀……你能保护我们！"
D.Strings[23853]="嘶嘶……嘶嘶……死了。都死了。"
D.Strings[23854]="有东西喂虫虫吃啦！"
D.Strings[23855]="它好像受了重伤。别像那样对待我们，好不好？"
D.Strings[23856]="我想……它大概是死了。"
D.Strings[23857]="啊啊！看来安全了？"
D.Strings[23858]="嗨。你是谁？我们来做好朋友吧？"
D.Strings[23859]="这里不下雪真是太好啦。我讨厌下雪！"
D.Strings[23860]="你的眼珠看起来好有趣。"
D.Strings[23861]="这些死了的家伙似乎……不太高兴。"
D.Strings[23862]="啊啊啊！我讨厌狗狗人！太坏了！"
D.Strings[23863]="我没有见过造物主。真的，只见过他们留下的祭坛。"
D.Strings[23864]="大树。温暖的家。"
D.Strings[23865]="这些虫虫又脆又美味。要不要来点？"
D.Strings[23866]="索乌塞对我们很和善。我们都很喜欢他。"
D.Strings[23867]="没准你能成为索干皮。你喜欢吗？"
D.Strings[23868]="漂浮的火花！他们会给我一个吗？"
D.Strings[23869]="狗狗人经常攻击这里。他们吓跑了虫虫……因此我们不常来这里了。"
D.Strings[23870]="造物主在祭坛留下了守护者。虽然不是为我们留下的，但它是我们的好朋友……帮助我们抵御过好几次狗狗人的袭击。"
D.Strings[23871]="你有好多闪闪发亮的东西。运气真好。"
D.Strings[23872]="睡觉时间到了？"
D.Strings[23873]="谢谢你，你是个好人。"
D.Strings[23874]="这里好臭啊。为什么这么臭呢？"
D.Strings[23875]="别乱来，狗狗人。我们不会乱来的，你也不要乱来啊。"
D.Strings[23876]="太古怪了。有人把虫虫都抢走了。不会是你干的吧？"
D.Strings[23877]="狗狗人浑身都是毛！真可怕。"
D.Strings[23878]="噢！他是谁？你的朋友？我和他也能做好朋友吗？"
D.Strings[23879]="有馅饼吗？以前有人给过我一块馅饼。好吃极了！"
D.Strings[23880]="更多的宝藏！各种各样的宝藏！宝藏！"
D.Strings[23881]="亮闪闪！亮闪闪！虽然不如我的水晶闪亮，但依然很闪亮！"
D.Strings[23882]="我们挖地的速度可快啦！真的哦！你瞧……完成啦！是不是很快呀？"
D.Strings[23883]="亮闪闪的水晶怎么都不嫌多啊！不嫌多！"
D.Strings[23884]="让我们击败这群笨蛋狗狗人吧！来吧！"
D.Strings[23885]="大雪怪抓不到我们！我们跑得快如飞！"
D.Strings[23886]="砰！啪！击中那只狗狗人！"
D.Strings[23887]="索乌霍鲁来抓你们啦！愚蠢的狗狗人。哈哈哈！"
D.Strings[23888]="塔尔特克比不上你！你真够厉害的。呀！"
D.Strings[23889]="你以为我们会害怕龙吗？不会！"
D.Strings[23890]="让你偷我们的财宝！财宝属于……我们，明白吗？！"
D.Strings[23891]="我打赌你没有见过狗狗人骑在龙背上的情景吧？哈哈！你以后也不会见到。"
D.Strings[23892]="哇！你来这里干什么啊？傻，傻瓜！不要来这里！"
D.Strings[23893]="不！别来找我的麻烦！这地方归你们啦。再见！"
D.Strings[23894]="嗯……别来找我的麻烦。"
D.Strings[23895]="哦！哈哈……滋味不好受吧。"
D.Strings[23896]="哇噻！到处都是闪电！我们应该学了这招去对付狗狗人！"
D.Strings[23897]="狗狗人把祭坛搞得一团糟！讨厌！快阻止他们！"
D.Strings[23898]="啊！差一点！快，快站到金属柱子下！它能保证我们的安全，对吧？"
D.Strings[23899]="雾气。好重的雾气啊。对你来说，这或许算不上浓雾吧？"
D.Strings[23900]="雾语鳄鱼人有时候也会讨厌我们。他们认为我们“毁了他们的宁静”。"
D.Strings[23901]="雾语鳄鱼人都很无聊。对，真的有点……无聊。"
D.Strings[23902]="唤雾者擅长利用祭坛来控制气候。他们知道各种水晶的用途！对，他们知道得一清二楚！"
D.Strings[23903]="啪！哈哈！击中啦！"
D.Strings[23904]="你喜欢吗？我打赌你不会喜欢的！因为你已经死啦！哈哈哈！"
D.Strings[23905]="影舞步！"
D.Strings[23906]="你输了！输得真难看呀！"
D.Strings[23907]="我们打败你啦！我们真了不起！"
D.Strings[23908]="你肯定不想死吧！太迟啦，死人是不能许愿的！哈哈哈！"
D.Strings[23909]="胜……利……啦！啾啾啾！"
D.Strings[23910]="家！家！家……闪闪发亮的地方！"
D.Strings[23911]="家里真好，可惜呆不长！我们要更多的冒险！"
D.Strings[23912]="来来，一起从树上跳下去吧！超级好玩！"
D.Strings[23913]="追赶幼体！追赶幼体！快跑！"
D.Strings[23914]="美好的家。住了很长时间，依然不会厌倦。"
D.Strings[23915]="造物主能够保证家的安全，因为他们喜欢先知！他们知道鳄鱼人都是好人。"
D.Strings[23916]="这是我真正的家！你相信我们以前也是鳄鱼人幼体吗？真的是这样哦！"
D.Strings[23917]="灵鳍鳄鱼人最厉害！嚓！嚓！拯救世界！"
D.Strings[23918]="不欢迎狗狗人！我们要好好地揍他们一顿！"
D.Strings[23919]="索乌霍鲁是最聪明的灵鳍神谕者。不骗你！"
D.Strings[23920]="上次狗狗人打过来，结果索乌霍鲁将他们统统赶回了狗狗人的营地！真是氏族的荣耀啊！"
D.Strings[23921]="你很强大！我打赌你能干掉那只大雪怪！肯定没问题！"
D.Strings[23922]="愚蠢的狗狗人！我们不想打架的！你们却偏偏跑来送死！"
D.Strings[23923]="我们知道你们有龙！但我们不怕！我们要将你们统统打扁！"
D.Strings[23924]="逃命去吧，狗狗人！我们来抓你们啦……最好滚回自己的山上去！"
D.Strings[23925]="大石柱不能随便摸的！讨厌！不许摸！"
D.Strings[23926]="塔尔特克是个笨蛋！狗狗人都听这个笨蛋的话。狗狗人都很愚蠢！"
D.Strings[23927]="我们会拧断你们的长矛！别为它们哭泣啊……别为断裂的长矛哭泣！"
D.Strings[23928]="嗨，狗狗人，你这辈子洗过澡吗？肯定没有！哈哈哈。"
D.Strings[23929]="我的干皮人肯定比你厉害。别不信。"
D.Strings[23930]="你看上去不是很强壮啊。没用的狗狗人。"
D.Strings[23931]="知道我们不喜欢什么吗？狗狗人！比如那边的狗狗人！看见了吗？我们不喜欢它。"
D.Strings[23932]="这里为什么会有狗狗人？滚开！去拣骨头玩吧。"
D.Strings[23933]="嗨……我说……狗狗人。你的亲人都还好吧？我的干皮人将他们统统杀掉了。哈哈哈！很爽吧！"
D.Strings[23934]="唉……又是泥土。"
D.Strings[23935]="索乌塞应该会喜欢这些玩意儿吧。"
D.Strings[23936]="嗨……或许我们会找到更多没用的虫虫。"
D.Strings[23937]="这里怎么会有亮闪闪的兔子啊？"
D.Strings[23938]="挖够了没有啊？"
D.Strings[23939]="你瞧，我刚刚认识那家伙，他就派我来这里挖掘没用的小玩意儿……你觉得这件事正常吗？"
D.Strings[23940]="来吧，狼獾人！你的末日到了！"
D.Strings[23941]="索乌霍鲁会终止这场战斗……"
D.Strings[23942]="卡塔克，我不怕你！"
D.Strings[23943]="狗狗人杀害了我们的同胞，我们却要向他们示好……你觉得这件事正常吗？"
D.Strings[23944]="你想去破柱子送死啊？那你自己去吧。"
D.Strings[23945]="如果能集合起一支军队，我或许会考虑与你同去。去破柱子可不是闹着玩儿的。"
D.Strings[23946]="干皮人，你很勇敢。如果你坚持要去破柱子的话，那么再见。"
D.Strings[23947]="干皮人，我不会再跟着你了。很多鳄鱼人都死在破柱子了，我不想去陪他们。"
D.Strings[23948]="我不敢相信……他们全都……死了。"
D.Strings[23949]="我以为我们的家园不会遭受亡灵的侵袭。"
D.Strings[23950]="阿尔萨斯的军队已经侵入诺森德的最后一片净土……"
D.Strings[23951]="我们应该保卫家园……应该阻止这一切的发生。"
D.Strings[23952]="我们不能任凭天灾军团胡来。他们必须付出代价！"
D.Strings[23953]="整个苔行村都在谈论异常的气候时，索乌塞没有采取任何措施，现在他们都死了……你觉得这件事正常吗？"
D.Strings[23954]="又倒下一个。"
D.Strings[23955]="来阻挡我们啊！"
D.Strings[23956]="对干皮人来说很不错了。"
D.Strings[23957]="或许你就是值得我陪伴左右的冒险家……或许你能拯救我的同胞。"
D.Strings[23958]="你怎么能忍受亚鲁乌特？他一开口，我就想把他踹到狂心岭去。"
D.Strings[23959]="拉弗乌是索乌塞的小宠物。他大概是我见过的最无能的鳄鱼人……这多少能说明点问题。"
D.Strings[23960]="我经历过的战斗比其他鳄鱼人加起来的还要多，就这样，我还能找出时间来学习你的语言……你觉得这件事正常吗？"
D.Strings[23961]="呀，我们出发吧。"
D.Strings[23962]="事情办好啦。"
D.Strings[23963]="为什么我们还留在这里？给我个说得过去的理由啊。"
D.Strings[23964]="你是打算继续无所事事地坐着，还是和我一起做些有用的事？"
D.Strings[23965]="你要打个盹？那我先给你倒个歉吧，待会你睡着之后，我可能会不小心踩到你的脸。"
D.Strings[23966]="我是最聪明、最强壮、最有修养的鳄鱼人，但是索乌塞却拥有氏族的统治权……你觉得这件事正常吗？"
D.Strings[23967]="可能还有更多的幸存者！我们必须继续前进。"
D.Strings[23968]="他们把尸体都拖到哪儿去了？他们会对尸体做什么？"
D.Strings[23969]="很难相信在这样一场劫难后，还会有幸存者。"
D.Strings[23970]="唯一值得欣慰的是，他们没有变成亡灵。"
D.Strings[23971]="我知道我的态度有些傲慢，但是我不希望我的同胞受到牵连。"
D.Strings[23972]="有的苔行鳄鱼人比我想象的更有活力，真是令人宽慰啊。"
D.Strings[23973]="灵鳍鳄鱼人是最强大的战士……他们参与了大多数对抗狼獾人的战斗。"
D.Strings[23974]="灵鳍神谕者是我最敬重的神谕者……他们勇敢地守护了自己的家园，令人钦佩啊。"
D.Strings[23975]="造物主将索乌霍鲁留在这里……我们口中的造物主，就是你熟知的泰坦。"
D.Strings[23976]="我相信，造物主将索乌霍鲁留在这里保护祭坛。但是和祭坛一样，没有合适的水晶，他就没法发挥能力。"
D.Strings[23977]="让我们向狼獾人宣战吧……他们逍遥得太久了，应该付出代价。"
D.Strings[23978]="灵鳍鳄鱼人和狼獾人交战已经有段日子了，但至今没有其他神谕者前来帮忙……你觉得这件事正常吗？"
D.Strings[23979]="卑鄙的狼獾人。我不管干皮人是不是会为你担保，但今天就是你的死期。"
D.Strings[23980]="你最好给我个说得过去的理由，不然我不会让这只狼獾人活命的。"
D.Strings[23981]="你对狼獾人还是很友好嘛？如果有一天你背叛我们，重新站在狼獾人那一边，我一点都不会吃惊！"
D.Strings[23982]="你和狼獾人是一伙的吧？你大概本来就心怀不轨。"
D.Strings[23983]="我咆哮起来是很可怕。"
D.Strings[23984]="敌人就站在我身旁，我却没有动手杀它……你觉得这件事正常吗？"
D.Strings[23985]="现在，我命令你去净化祖达克，达库鲁。"
D.Strings[23986]="令我失望，你就将迎来末日……"
D.Strings[23987]="获得成功，更加强大的力量就唾手可得！"
D.Strings[23988]="遵命，我的主人。"
D.Strings[23989]="朋友，请原谅，我欺骗了你。这样是为了你好。"
D.Strings[23990]="那时，你要证明自己的价值……"
D.Strings[23991]="而我，则急需优秀的下属，能支配强大力量的下属，在祖达克为我效劳。"
D.Strings[23992]="自己权衡一番吧。要知道，巫妖王陛下对于所有忠诚的仆从都非常慷慨。"
D.Strings[23993]="朋友，只要踏上这条路，很快你也能成为不朽的存在！"
D.Strings[23994]="仔细回想今天你目睹的一切，$n。$B$B未来已经注定，你唯一需要考虑的只是你想在其中扮演怎样的角色。"
D.Strings[23995]="玛里苟斯最强大的仆从守卫着上层的环。单凭你的力量，根本不可能战胜他们。我们将赋予你召唤幼龙的能力。你可以骑着幼龙在魔环飞翔并使用强大的龙族魔法。"
D.Strings[23996]="接下来，我们要去哪儿？"
D.Strings[23997]="贝加里斯塔兹说得没错，时间不多了！\n\n幼龙的终极力量已经解封。使用它们的力量击败埃雷苟斯吧！"
D.Strings[23998]="贝加里斯塔兹说得没错，情况非常危急。\n\n幼龙的终极力量已经解封。使用它们的力量击败埃雷苟斯吧！"
D.Strings[23999]="上古之神，我们乞求你的帮助。我们应该怎么做，才能拯救这片土地的神灵？"
D.Strings[24000]="必须找到雪豹女神。他们的命运与此休戚相关。"
D.Strings[24001]="不过她被锁住了。必须设法搭救她。"
D.Strings[24002]="这名凡人必须前往她的祭坛。他们必将肩负起艰难的使命，甚至可能面临失败的惨境。"
D.Strings[24003]="但是他们必须尝试，否则一切都完了。达卡莱巨魔很可能将自己和他们崇拜的神灵送上绝路！"
D.Strings[24004]="神灵做出了指示，$n。你必须承担起这项艰难的使命。"
D.Strings[24005]="没有谁比死亡骑士更了解天灾军团。$B$B相信我，$r。全力火拼，以牙还牙才是最奏效的战争策略。"
D.Strings[24006]="对老纳斯宽容点。他年纪大了，体力早已不如从前。"
D.Strings[24007]="我找不到纳斯了……"
D.Strings[24008]="老纳斯每次都能找到回来的路，真是奇怪。肯定是靠闻的吧……"
D.Strings[24009]="我说！我必须另找一份谋生的活儿。"
D.Strings[24010]="或许换个方式也能奏效啊。比如，只是拍拍肩膀？"
D.Strings[24011]="真的，期望令人心烦意乱……"
D.Strings[24012]="希望他们不是因为这点才记得我……"
D.Strings[24013]="能不能将你的注意力转移到别人的臀部去？"
D.Strings[24014]="如果有机会治好我的毛病，我一定要让斯特凡尝尝这靴子的滋味。"
D.Strings[24015]="噢！我开始觉得，你在享受这一切……"
D.Strings[24016]="哎哟！你这一脚踢得真重……"
D.Strings[24017]="啊！这一脚恐怕是白挨了。"
D.Strings[24018]="呃！这附近好像没有巨魔，我闻不出他们的气味……"
D.Strings[24019]="听着！你根本没理由踹我这一脚！"
D.Strings[24020]="啊！你很享受是吧？"
D.Strings[24021]="哎哟！好吧，至少你的用意是好的。对你来说已经很难得了……"
D.Strings[24022]="啊！每次你踹我的时候，我就怀疑自己离开天灾军团的决定是不是做错了。"
D.Strings[24023]="事情到底有完没完啊？"
D.Strings[24024]="每收集一束毛发，就损失一份尊严……"
D.Strings[24025]="如果让妈妈看见我现在的模样……"
D.Strings[24026]="我希望那是最后一个！"
D.Strings[24027]="我们好像把什么东西给撞松了。"
D.Strings[24028]="如果你决定就此结束的话，我一点都不会失望……"
D.Strings[24029]="他说，我们去祖达克。他说，这样我们才能查明真相……"
D.Strings[24030]="还早着呢，你居然这么早就吵醒我！到底有什么紧要事啊？"
D.Strings[24031]="你控制了阿彻鲁斯之眼。"
D.Strings[24032]="我受够了！我要走了。"
D.Strings[24033]="啊！好痛。我只能一瘸一拐地挪动了。"
D.Strings[24034]="等我们的处境安全之后我再回来。"
D.Strings[24035]="情况很糟糕啊。我待会再回来找你。"
D.Strings[24036]="愚蠢的奴隶应该消灭敌人，确保格利基克的生命安全！"
D.Strings[24037]="再来听听达伊克的小建议！别让敌人伤害到你的老师。我得回家去了。"
D.Strings[24038]="哎哟……我们现在回去没问题吧？痛死我了……我们真惨啊。"
D.Strings[24039]="好痛啊！我们要赶紧撤离这里！很快就会回来！"
D.Strings[24040]="要我为你搭上性命，没门。"
D.Strings[24041]="哈！真有趣！"
D.Strings[24042]="我早就盼着再来祭坛捣蛋了！"
D.Strings[24043]="相信我——你会喜欢的！"
D.Strings[24044]="尝尝厉害吧，大舌头怪！"
D.Strings[24045]="我的同胞或许会让你探索祖达克的秘密，但是赞达拉氏族始终肩负着见证历史的使命，并将如实地记载巨魔帝国毁灭的篇章。"
D.Strings[24046]="牛头人酋长乐队来到了沙塔斯城！就在天涯旅店，整点开始演出！"
D.Strings[24047]="你还有很多东西要学……最重要的一点，就是保护达伊克！"
D.Strings[24048]="达伊克要休息一会儿……全身都是伤。"
D.Strings[24049]="如果你受了重伤，一定要好好休息，恢复精力。达伊克现在就教你该怎么做……"
D.Strings[24050]="奴隶，你太令我失望了。"
D.Strings[24051]="哎哟。没用的奴隶……哎哟！"
D.Strings[24052]="愚蠢的奴隶，继续战斗……格利基克不想再挨打了。"
D.Strings[24053]="我们被天灾盯上了！消灭它！"
D.Strings[24054]="滚开，肮脏的恶魔！"
D.Strings[24055]="这就是天灾军团干的好事！"
D.Strings[24056]="天灾！别让它逃走！"
D.Strings[24057]="笨蛋！停止射击！格利基克想要完整的战利品！"
D.Strings[24058]="别让它逃走！这次一定要抓住它。"
D.Strings[24059]="格利基克总算抓到你啦！你是格利基克的！"
D.Strings[24060]="当心！别像上次那样被它抓伤了。"
D.Strings[24061]="你准备好进行一场狂欢了吗？那么就去天涯旅店吧！牛头人酋长乐队将在整点之后的十分钟开始演出！"
D.Strings[24062]="勇士，今天不应该是你的死期。复活吧！站起来，再次投身战斗！"
D.Strings[24063]="糟糕……不是吧。"
D.Strings[24064]="格利基克好像又闯进鸡舍了……"
D.Strings[24065]="格利基克不是故意把鸡放走的！来帮帮忙啊！"
D.Strings[24066]="格利基克饿……哎呀，没有啦。格利基克错了。"
D.Strings[24067]="谁？牛头人酋长乐队！什么？现场演出？哪里？天涯旅店！时间？整点之后的十分钟！快去啊！"
D.Strings[24068]="点火"
D.Strings[24069]="牛头人酋长乐队！在天涯旅店现场演出！整点之后十分钟就开始啦！千万不要错过！你被沙塔斯城放逐了？还不快潜回去！"
D.Strings[24070]="嗨，巨魔……这是给你的礼物！"
D.Strings[24071]="你准备好和我一起挑战玛尔加尼斯了吗？"
D.Strings[24072]="阿彻鲁斯之眼朝目标发射能量。"
D.Strings[24073]="殿下，我已经准备好与恐惧魔王作战了。"
D.Strings[24074]="唷……真恶心！"
D.Strings[24075]="我想要打扮成海盗。"
D.Strings[24076]="给我的？真的吗？"
D.Strings[24077]="太……太漂亮了！"
D.Strings[24078]="一切都准备就绪啦。"
D.Strings[24079]="5秒后开始蒸馏。"
D.Strings[24080]="再加一颗橙子！快点！"
D.Strings[24081]="更多的香蕉！"
D.Strings[24082]="往蒸馏器里扔颗木瓜！"
D.Strings[24083]="蒸馏器温度过低！点燃火盆！"
D.Strings[24084]="压力过高！打开施压阀！"
D.Strings[24085]="让我们来做个了断吧，玛尔加尼斯。"
D.Strings[24086]="成功啦！去拿桶来。"
D.Strings[24087]="不好！我要关掉蒸馏器……"
D.Strings[24088]="很好！时刻做好准备！"
D.Strings[24089]="走开。这里没什么好看的。"
D.Strings[24090]="<血玫瑰好奇地打量着你。>$B$B你这样的家伙也能吸引大家的目光，真是奇怪。$b$b我没有侮辱你的意思……"
D.Strings[24091]="斯特凡说你可以示范要如何使用这东西。"
D.Strings[24092]="你的旅程才刚开始，年轻的王子。集合你的部队，到诺森德再次挑战我。在那里，我们将了结彼此之间的恩怨，你将了解到你真正的命运。"
D.Strings[24093]="就算你跑到天涯海角，我也一定要抓到你！听到了吗？天涯海角！"
D.Strings[24094]="你们表现得很出色。玛尔加尼斯留下的一切都是你们的了，把它们收下作为奖励吧。现在我要马上开始计划远征诺森德了。"
D.Strings[24095]="达卡莱巨魔将我囚禁在祭坛，令我的肉身处于濒死状况。但是他们无法看见我的灵魂。$B$B我们必须协同作战，阻止他们夺取我的力量。"
D.Strings[24096]="醉鬼，我准备好啦，可以开始蒸馏了。"
D.Strings[24097]="很好！不要大意！"
D.Strings[24098]="干得好！集中精神。"
D.Strings[24099]="也行吧。不知道接下来应该加点什么……"
D.Strings[24100]="能量在水晶柱中涌动，发出低沉的嗡嗡声。"
D.Strings[24101]="伦诺克，我需要再次吸取你的精魄。"
D.Strings[24102]="请你快一点，$n。我承受着莫大的痛苦，时间已经不多了。"
D.Strings[24103]="肮脏的入侵者。死吧！"
D.Strings[24104]="天灾！快跑！快跑！"
D.Strings[24105]="圣光，救救我们！"
D.Strings[24106]="是食尸鬼！！！！食尸鬼！！！！"
D.Strings[24107]="我不会躺在这里等死的！凡人，想杀我的话，也得看看你有没有那个本事！"
D.Strings[24108]="哈哈哈，我在装死。朋友，你的死期到了！"
D.Strings[24109]="我好像在喝……引擎清洁剂！"
D.Strings[24110]="好吧，我会尝尝的。"
D.Strings[24111]="这正是我梦寐以求的美酒啊！"
D.Strings[24112]="酿造得很成功啊！这酒的后劲还挺大的。"
D.Strings[24113]="天灾伪装失效了！快找个安全的地方！"
D.Strings[24114]="联盟的桥梁遭到攻击！"
D.Strings[24115]="我对葛瑞姆酿造的酒总是充满兴趣的。"
D.Strings[24116]="呃，我的妻子应该会喜欢这种果味酒……"
D.Strings[24117]="哇，仔细品味后才发现口感一流啊！葛瑞姆总是能为我带来惊喜！我喜欢！"
D.Strings[24118]="想尝尝葛瑞姆·雷酒新酿的丛林果酒吗？"
D.Strings[24119]="我们尽快离开这里。否则，就算不被亡灵杀死，也要被火烧死。"
D.Strings[24120]="正义必将得到伸张。"
D.Strings[24121]="嗷嗷……瞧那只食尸鬼。$b$b跳一下呀！跳一下！$b$b哈哈哈……真是一只可爱的食尸鬼。"
D.Strings[24122]="我们打算将这面墙炸掉，让维克的人可以修建新的港口和道路，但是这个蠢货居然嫌我用了太多的炸药！$B$B哼。我玩爆破的时候，他小子还裹着尿布呢。大不了我一脚把他踹进运河，然后自己把这该死的活儿干完！"
D.Strings[24123]="我们计划等拆了这面墙之后开始修建另一条通往暴风城港口的路……但是这个疯狂的矮人带来的炸药足以把这整个区域都给炸上天！$B$B我不知道阿历克斯顿大人是怎么想的，居然会雇佣她……这个满嘴脏话、刁钻刻薄、像头牛一样固执的矮人！"
D.Strings[24124]="还能做些什么？我们已经失去了一切！"
D.Strings[24125]="勇敢地战斗！和以前一样，将天灾军团赶出我们的家园！"
D.Strings[24126]="天灾军团玷污了这片古朴的土地。以伟大的造物主之名，我会将他们污朽的躯壳踩得粉碎。"
D.Strings[24127]="阿比迪斯，圣光给了什么新的指示！"
D.Strings[24128]="圣光没能拯救我的妻子和孩子！"
D.Strings[24129]="也没能拯救我的丈夫和兄弟！"
D.Strings[24130]="圣光抛弃了我们！"
D.Strings[24131]="肃静！圣光没有抛弃我们！只要你们保持内心的纯洁，它就能展现出比过去更加强大的力量！"
D.Strings[24132]="海文郡沦陷了！"
D.Strings[24133]="马厩和伐木场被遗弃了！我们的马匹怎么办？"
D.Strings[24134]="我们已经派出十字军部队，他们会夺回本属于我们的领地！天灾军团如果胆敢阻挠，定要将他们挫骨扬灰。"
D.Strings[24135]="你觉得我们能去哪儿？新阿瓦隆容不下这么多人！"
D.Strings[24136]="所有人都必须接受审讯官的调查。内心纯洁的平民可以留在新阿瓦隆，被圣光摒弃的人则必须离开。"
D.Strings[24137]="人群骚动起来。"
D.Strings[24138]="但是你们并没有什么值得担心的啊，对吧？"
D.Strings[24139]="我和你一样，希望能阻止天灾军团的入侵。我能帮上什么忙吗？"
D.Strings[24140]="泰坦并非在一夜之间就创造出了所有生命。整个过程相当漫长，其中涉及大量的试验与叠代。$B$B因此，造物主看中了索拉查盆地，并将它改造成戒备森严的实验场所。$B$B为了确保安全，泰坦还制造出一台机械防御装置，它拥有无可匹敌的破坏力。除非你发誓对我效忠，否则我拒绝透露更多的机密。"
D.Strings[24141]="将造物主的秘密告知你这样的凡人，简直是对神灵的亵渎，但是我别无选择。$B$B泰坦的女儿弗蕾亚要我不惜一切代价保卫索拉查盆地的安全，这就是我留守此地的唯一目的。$B$B盆地内有一座大门，连接着另一块与这里的环境极其相似的土地。穿越那座大门，就能找到我们所说的秘密武器。"
D.Strings[24142]="相信我。我不是巫妖王的朋友。"
D.Strings[24143]="我不会令你失望的。"
D.Strings[24144]="你手里藏着什么？"
D.Strings[24145]="哨站属于无齿轮区域。如果有谁在制造机械装置时使用齿轮，就会遭到无情的嘲笑。"
D.Strings[24146]="看来你和我的想法一样啊。你想找些水果，对吧？"
D.Strings[24147]="洛肯？！这下我们碰到大麻烦了……虽然铁矮人已经被全部摆平了，但我敢打赌不知道什么鬼地方还有台机器，正不停向外吐着铁维库人！"
D.Strings[24148]="哎哟！你拉哪儿呢！"
D.Strings[24149]="很高兴我能帮上忙！"
D.Strings[24150]="能给我一颗橙子吗？"
D.Strings[24151]="还有香蕉吗？"
D.Strings[24152]="我可能需要一颗木瓜。"
D.Strings[24153]="这里不欢迎你，怪物！"
D.Strings[24154]="接受净化吧！"
D.Strings[24155]="圣光保佑你，我的孩子。"
D.Strings[24156]="%s召唤出一支冰冻僵尸大军。"
D.Strings[24157]="裂骨者开始施放裂骨！"
D.Strings[24158]="奥格瑞玛城外有两座飞艇塔。东侧的飞艇塔开通了前往提瑞斯法林地和荆棘谷的航线，西侧的飞艇塔则用于飞往诺森德和雷霆崖。"
D.Strings[24159]="东侧飞艇塔"
D.Strings[24160]="西侧飞艇塔"
D.Strings[24161]="兄弟们，快！天灾军团的攻势强劲，我不知道我们还能支撑多久！"
D.Strings[24162]="加把劲儿！将木材堆放入舱，准备运往新阿瓦隆！"
D.Strings[24163]="我已经够快的了，上尉！"
D.Strings[24164]="长官，我快吃不消了！就算我没死在天灾兵手里，也会活活累死啊！"
D.Strings[24165]="木材装载完毕！别挡道！"
D.Strings[24166]="战争的号角已经吹响！时间紧迫！加快速度！"
D.Strings[24167]="天灾军团即将攻陷海文郡。我们必须加快速度！"
D.Strings[24168]="杀光他们！"
D.Strings[24169]="渺小的赞达拉巨魔将被碾得粉碎！"
D.Strings[24170]="骑兵连，出发！夺回希姆托加！"
D.Strings[24171]="如果你上缴10颗敌人的徽记，我就赏你满袋子的金币和宝石。"
D.Strings[24172]="你瞎了吗？他们就在那儿。杀光他们！"
D.Strings[24173]="我看到你了。过来啊，让我们干掉这只达卡莱巨魔。"
D.Strings[24174]="如果他们不肯离开希姆托加，就将那里夷为平地！"
D.Strings[24175]="我管你是赞达拉，银色北伐军，还是天灾兵……在我眼里，你就像只小虫子。我要捏碎你！"
D.Strings[24176]="光明使者……"
D.Strings[24177]="乌瑟尔大人……"
D.Strings[24178]="谁在敲我的鼓？"
D.Strings[24179]="我要杀了你，$r！"
D.Strings[24180]="请收下……我亮闪闪的财宝。结束了……"
D.Strings[24181]="我们得救啦。你真好，干皮人。"
D.Strings[24182]="苔行鳄鱼人似乎受了重伤。"
D.Strings[24183]="<检测脉搏……>"
D.Strings[24184]="这些足迹一定是杉苟留下的。"
D.Strings[24185]="这些不是杉苟的足迹。"
D.Strings[24186]="勇敢的旅者经由这座港口在暴风城和鲁瑟兰村之间往返。"
D.Strings[24187]="破冰者开始施放跃动碎片。"
D.Strings[24188]="苔行村受害者发出痛苦的呻吟。"
D.Strings[24189]="%s的油量只剩下一半了。"
D.Strings[24190]="%s的油快耗光了。"
D.Strings[24191]="我可怜的飞行器。她在坠机事故中遭到严重损坏，我偏偏没有备用零件。看样子她是没法恢复原貌了！"
D.Strings[24192]="食血者召唤出血蛆帮忙！"
D.Strings[24193]="嗨，朋友。$B$B别站在那儿发呆。这里有很多事要做呢。"
D.Strings[24194]="很快，$n！$B$B很快，你就能拥有真正的力量。很快，你的付出就能得到回报。"
D.Strings[24195]="来吧，凡人……$B$B忍耐！你将拥有真正的力量！"
D.Strings[24196]="啊，英雄。我听你的小伙伴说，你会来的。这样挺好的，省去了我亲自搜寻你的麻烦。"
D.Strings[24197]="我经历了一百年的战争与痛苦。你真的觉得，凭着血肉之躯与不死生物作对是明智的选择吗？我敢说，你很可能会失败。"
D.Strings[24198]="即便是碎裂成粉末，这些水晶依然在削弱我的力量……或许我不该低估泰坦的强大……"
D.Strings[24199]="这两个有勇无谋的蠢货彼此厌恶，却异口同声地称你为英雄。你或许还不愿意做出选择……那么，就让我多给你一点时间吧。"
D.Strings[24200]="阿尔萨斯也曾拥有……同样的力量……或许你应该沿着他的足迹追寻力量。"
D.Strings[24201]="伟大的哈克娅，请召唤一名子嗣，让它将我悄悄地带进奎丝鲁恩祭坛。"
D.Strings[24202]="谢谢你救了我，$n。这是我唯一能为你做的。握紧了，我们出发吧。"
D.Strings[24203]="握紧了，我们出发吧！"
D.Strings[24204]="事情似乎不太顺利。千万别跌下去。那里满是肮脏的东西！"
D.Strings[24205]="天哪……奎丝鲁恩死了！别动。我们偷偷绕过先知。"
D.Strings[24206]="呃，能带我在祖达克逛一圈吗？"
D.Strings[24207]="我们被发现了！别慌张。我们得离开这里！"
D.Strings[24208]="成功啦！保重，$n。再次对你表示感谢！"
D.Strings[24209]="他死了……我们自由啦！很高兴你能站在我们这一边，而不是与狗狗人为伍。我们很高兴！真的！非常高兴！"
D.Strings[24210]="那是什么？我能感受到入侵者的气息。将他们揪出来杀掉！"
D.Strings[24211]="启航！当心那些藤蔓植物！"
D.Strings[24212]="看来前面的区域已经被天灾军团清扫过了……"
D.Strings[24213]="看见了吗？她……真大啊！"
D.Strings[24214]="来吧！坐稳啦——前面有强气流！"
D.Strings[24215]="他们发动攻击了！当心那些火箭！"
D.Strings[24216]="啊啊啊！被击中了！你得帮帮忙！快，趁飞行器还没有爆炸！"
D.Strings[24217]="憎恶，我需要你的帮助！"
D.Strings[24218]="我想我们现在安全了。回去吧！"
D.Strings[24219]="将这些试验结果报告带去幽暗城，交给我们的药剂师。还有，别再把信吃了行不行？"
D.Strings[24220]="欢迎光临。请问你想休息还是进餐？"
D.Strings[24221]="保证……完成……任务……<嗝>"
D.Strings[24222]="肮脏的偷马贼！"
D.Strings[24223]="没人能偷走基特里克的马！"
D.Strings[24224]="你很快就会被绞死……"
D.Strings[24225]="我到底还要将多少具尸体送到巫妖王面前，他才肯罢休？"
D.Strings[24226]="这份血样不错。是从哪儿弄来的？"
D.Strings[24227]="这份血样取自一位男性人类农民。他杀死家人后闯入了暴风城。"
D.Strings[24228]="这份血样取自一位女性侏儒。她的神情举止流露出难以抗拒的萌属性，人们在她面前总是会失去戒心。因此，她受感染轻易地又害了数十人。"
D.Strings[24229]="你喜欢我为那些所谓的崇拜者创造的新家吗？$B$B临死前，我强忍着莫大的痛楚诅咒了他们，并将他们一同拖进了我所创造的异界。$B$B我可以随心所欲，这固然不错；但我真正希望的，是向先知寻仇！"
D.Strings[24230]="%s召唤出天灾军团的大军！"
D.Strings[24231]="天灾军团，听我的号令！血色十字军的末日已经降临！攻占这片土地吧！"
D.Strings[24232]="男性兽人的血样。为了避免传染，他选择了自焚。"
D.Strings[24233]="女性牛头人的血样。僵尸入侵时，她正在照看村里的孩子。她成功地击退了敌人，却在混乱中被咬伤。很不幸，没等治愈她就一命呜呼了。"
D.Strings[24234]="奇怪，这份血样的记录并不完整。标签上潦草地用血写着“我杀了它！”。"
D.Strings[24235]="它取自我们的同胞。被遗忘者。对他尊重些。"
D.Strings[24236]="男性牛头人的血样。这位萨满祭司被感染后，还没来得及治愈自己就被杀掉了。"
D.Strings[24237]="女性矮人的血样。这位圣骑士在临死前，用她仅剩的法力治疗了自己的同伴。"
D.Strings[24238]="朋友，我已经占领了这里的部分土地，但这仅仅是个开始！"
D.Strings[24239]="这份血样完全坏死了。它是从哪儿来的？"
D.Strings[24240]="这份血样非常奇特。从哪儿弄来的？"
D.Strings[24241]="我们能从这份血样中学到很多东西……"
D.Strings[24242]="这份血样被严重污染了！怎么会这样？"
D.Strings[24243]="我需要更多类似的样本。它取自何种生物？"
D.Strings[24244]="这份新鲜的血样很独特。有什么来历吗？"
D.Strings[24245]="我们可以从试验中学到很多知识……"
D.Strings[24246]="冰川正在逐渐扩展……到处都是亡灵！先等教授控制这里的局势吧！"
D.Strings[24247]="自以为是的北伐军挡住了我们前进的道路。他们注定会失败！"
D.Strings[24248]="很快，一切都将属于巫妖王！"
D.Strings[24249]="卑鄙的家伙，你这是自作自受！"
D.Strings[24250]="下次偷基特里克的马之前，你最好考虑清楚，嗯？"
D.Strings[24251]="你就这点能耐？"
D.Strings[24252]="这简直是浪费时间。"
D.Strings[24253]="下次至少让我多花点力气吧。"
D.Strings[24254]="达卡莱巨魔在破坏他们的土地！他们很快就会失去这一切……很快。"
D.Strings[24255]="啊，这就是我们的命运之城……古达克！"
D.Strings[24256]="凡人将接受考验！"
D.Strings[24257]="我的剑刃渴望鲜血！"
D.Strings[24258]="复仇！"
D.Strings[24259]="消灭活人！"
D.Strings[24260]="血色十字军的鲜血将染红大地！"
D.Strings[24261]="主人，我听到了你的召唤。"
D.Strings[24262]="就算是死，也要找人垫背！"
D.Strings[24263]="接受痛苦的试炼吧，死亡骑士……"
D.Strings[24264]="以天灾军团的名义，消灭他们！"
D.Strings[24265]="让他们从痛苦中解脱吧，死亡骑士！"
D.Strings[24266]="不要让牧师复活他们！"
D.Strings[24267]="把尸体带过来……"
D.Strings[24268]="不要对活人心存怜悯！"
D.Strings[24269]="不必怜悯弱者！"
D.Strings[24270]="收割者，我愿意听从你的吩咐！"
D.Strings[24271]="我的剑刃渴望更多的亡魂！"
D.Strings[24272]="为弱者带去痛苦！"
D.Strings[24273]="鲜血与恐怖，收割者！"
D.Strings[24274]="赞美莫格莱尼！"
D.Strings[24275]="死亡是他们唯一的解脱！"
D.Strings[24276]="消灭你所见到的凡人！"
D.Strings[24277]="接受痛苦的试炼吧，死亡骑士！"
D.Strings[24278]="他们将被遗忘……"
D.Strings[24279]="将他们从这个世界上抹去！"
D.Strings[24280]="天灾军团终将拥有至高无上的统治权！"
D.Strings[24281]="鲜血与恐怖！"
D.Strings[24282]="天启骑士，我愿意听从你的号令！"
D.Strings[24283]="许多人会遭殃！"
D.Strings[24284]="让他们跑！这里无处可逃！"
D.Strings[24285]="让他们尝尝恐惧的滋味，死亡骑士！"
D.Strings[24286]="吞噬他们的灵魂！"
D.Strings[24287]="更多的痛苦！"
D.Strings[24288]="撕裂这片大地！"
D.Strings[24289]="主人，你能从这里听见他们的哭声！"
D.Strings[24290]="我做好战斗准备了！"
D.Strings[24291]="十字军注定会被毁灭！"
D.Strings[24292]="萨拉纳尔，我将成为你引以为傲的骑士！"
D.Strings[24293]="引擎爆炸了！快将维克的飞行器开回湖边着陆场！"
D.Strings[24294]="天灾伪装失效了！快找掩护！"
D.Strings[24295]="天灾伪装失效了！赶紧躲起来！"
D.Strings[24296]="当然。$r，看仔细了。"
D.Strings[24297]="你是来找哈古斯买东西的吗？"
D.Strings[24298]="是啊。我想购买一些补给品。"
D.Strings[24299]="求……求你……"
D.Strings[24300]="不！求你！我……我有孩子！我……我……"
D.Strings[24301]="饶命！我会离开的！永远不会回来！求你！"
D.Strings[24302]="愿圣光怜悯你的灵魂，死亡骑士。"
D.Strings[24303]="放过我吧！"
D.Strings[24304]="我差点……就成功了……"
D.Strings[24305]="恶魔，你让我的孩子沦为孤儿！"
D.Strings[24306]="为什么？"
D.Strings[24307]="不要心存怜悯。"
D.Strings[24308]="弱者才会有仁慈之心。"
D.Strings[24309]="给它个了断。"
D.Strings[24310]="不接受投降。"
D.Strings[24311]="生还是死，由你选择。"
D.Strings[24312]="不要犹豫。"
D.Strings[24313]="控制你的怒火，集中注意力！"
D.Strings[24314]="打倒它！"
D.Strings[24315]="享受失败的痛苦滋味吧！"
D.Strings[24316]="让它了解恐惧的真正含义。"
D.Strings[24317]="终结它可悲的生命。"
D.Strings[24318]="拥抱黑暗吧，死亡骑士。"
D.Strings[24319]="你觉得它会对你心慈手软吗？对怪物一样的你？"
D.Strings[24320]="无论生死，你都将侍奉我。"
D.Strings[24321]="我不会束手就擒的！"
D.Strings[24322]="我不会轻易倒下的！"
D.Strings[24323]="天灾的走狗！死吧！"
D.Strings[24324]="来啊，死亡骑士！"
D.Strings[24325]="这就是你全部的能耐吗？"
D.Strings[24326]="你能夺走我的性命，却无法束缚我的灵魂！"
D.Strings[24327]="黑暗在等待……"
D.Strings[24328]="死亡骑士，除非你能打败我并夺走死亡战马，否则你永远无法返回生者的世界。你准备好了吗？"
D.Strings[24329]="我准备好了，骑士。"
D.Strings[24330]="不…………！"
D.Strings[24331]="%s转个不停！"
D.Strings[24332]="高阶祭司变成了焦炭。"
D.Strings[24333]="火！啊！！！！"
D.Strings[24334]="想要赢得巫妖王的宠爱？$B$B有充分价值的人才能获得黑暗的礼物……"
D.Strings[24335]="%s爆炸了！"
D.Strings[24336]="欢迎来到达拉然公会注册办事处。请问你需要什么帮助？"
D.Strings[24337]="知道了。立即返回战争区域。我们的战略目标是尽可能多地搭救那些感染的受害者。"
D.Strings[24338]="目标很简单：杀死我，夺走死亡战马。"
D.Strings[24339]="等你成功地完成这项创举后，就带着我的死亡战马返回死亡裂口，用骑手的召唤将萨拉纳尔从生者的世界召唤出来。"
D.Strings[24340]="大药剂师普特雷斯！我有来自前线的报告……"
D.Strings[24341]="你准备好了吗？听我的指令！"
D.Strings[24342]="被遗忘者的力量！"
D.Strings[24343]="为女妖之王而战！"
D.Strings[24344]="炸药束将在5秒后引爆……"
D.Strings[24345]="炸药束将在4秒后引爆……"
D.Strings[24346]="炸药束将在3秒后引爆……"
D.Strings[24347]="炸药束将在2秒后引爆……"
D.Strings[24348]="炸药束将在1秒后引爆……"
D.Strings[24349]="我身边的人似乎都染上了重病。"
D.Strings[24350]="自从上次尝过龙息红椒后，我还从来没有这么难受过。"
D.Strings[24351]="我的床看上去很漂亮啊。"
D.Strings[24352]="本月我要是再多请一天病假的话，老板就会杀了我。"
D.Strings[24353]="镇长有没有提到疫情扩展的消息？"
D.Strings[24354]="你和那些尚未染病的人交谈过吗？"
D.Strings[24355]="我敢打赌，是饮用水的问题。"
D.Strings[24356]="天哪。不好意思，稍等一会儿。"
D.Strings[24357]="你看见了吗？"
D.Strings[24358]="%s显得非常虚弱。"
D.Strings[24359]="死吧，蠢货！"
D.Strings[24360]="什么？怎么可能？"
D.Strings[24361]="我费了很多功夫，才迫使赫米特遵守协议。只希望大法师能赏识我的才能。"
D.Strings[24362]="很不错啊，死亡骑士。返回生者的世界，领取你应得的奖励吧。"
D.Strings[24363]="你应该紧跟着阿尔萨斯！"
D.Strings[24364]="你来做什么，可悲的家伙？送死吗？"
D.Strings[24365]="我很熟悉你身上的臭味。捕杀雪豹时，你一路潜行尾随在我身后！"
D.Strings[24366]="情况不妙……要不你待会再来找我们？"
D.Strings[24367]="我们是很想帮忙啊。但我们不想搭上性命！你待会再来找我们吧！"
D.Strings[24368]="抱歉……我们要回家去，我们不想死。很抱歉！"
D.Strings[24369]="我邀请你去地底世界参加我的乔迁庆宴！"
D.Strings[24370]="我也想静静地陪伴你，但我们都知道，这是不可能的。就让我的小伙伴送你去地狱吧。"
D.Strings[24371]="远古海滩的战斗开始了！"
D.Strings[24372]="远古海滩的战斗将在1分钟后开始。"
D.Strings[24373]="远古海滩的战斗将在30秒后开始。做好准备！"
D.Strings[24374]="我们中只有一人能离开这个世界！"
D.Strings[24375]="就这点能耐？这就是萨拉纳尔所能派出的最强大的骑士？"
D.Strings[24376]="过来，懦夫！来打败我啊！"
D.Strings[24377]="你没有机会重返生者的世界！"
D.Strings[24378]="可悲的家伙！你也觉得自己能打败阿彻鲁斯黑暗骑士？"
D.Strings[24379]="放弃吧，你没有希望获胜！"
D.Strings[24380]="我们赶紧离开这里吧。"
D.Strings[24381]="听着，风险投资公司的蠢货！准则第一条：永远不要把囚犯关押在爆炸物附近。"
D.Strings[24382]="你的伪装骗不了我！我要杀了你，达库鲁一定会很满意的！"
D.Strings[24383]="否则，这就是后果。"
D.Strings[24384]="这里越来越热了。我们继续前进吧？"
D.Strings[24385]="我们将夺走他们的一切，死亡骑士。"
D.Strings[24386]="瞧，又是一车炸弹！让我们引爆它吧。"
D.Strings[24387]="萨拉纳尔，我必须返回暗影界。"
D.Strings[24388]="你不该随意摆弄这些东西。会弄伤人的。"
D.Strings[24389]="成功啦！谢谢你带我逃离那个地狱般的洞穴。告诉赫米特，让他等着我！"
D.Strings[24390]="我不明白……"
D.Strings[24391]="我做错了什么吗？"
D.Strings[24392]="为什么会落得……这样的结局……"
D.Strings[24393]="哎哟。嗯……哎哟！"
D.Strings[24394]="太慢啦！你追不上我们！"
D.Strings[24395]="嗨！亚鲁乌特到哪儿去了？噗！"
D.Strings[24396]="这次就靠你自己了！"
D.Strings[24397]="我受够了。"
D.Strings[24398]="如果你还想让我来送死的话，就去营地找我吧。"
D.Strings[24399]="很好。我会让先知永远待在我身边的。"
D.Strings[24400]="等等……住手！你不能夺走力量！！"
D.Strings[24401]="我需要治疗！"
D.Strings[24402]="我们应该离开这里。我需要恢复！"
D.Strings[24403]="我觉得应该施放恢复了！"
D.Strings[24404]="旅途愉快！等你抵达目的地后再召唤我吧。"
D.Strings[24405]="我不知道自己还能撑多久！"
D.Strings[24406]="狂心氏族将夺得这块土地的控制权。大舌头怪最好滚得远远的，不然我们就将他们统统杀掉。"
D.Strings[24407]="达穆克必须死！"
D.Strings[24408]="狂心狼獾人很看起来凶猛，但其实我们是好人呀。时间长了，你就会发现，我们和聪明强壮的朋友相处得很好。$B$B我们只是不善于和笨蛋打交道而已。"
D.Strings[24409]="这就是雨水巨石。我们保护它，向它供奉闪闪发亮的宝贝；它就会庇护我们。$B$B你有亮闪闪的宝贝吗？"
D.Strings[24410]="我的个子不高，但是我会很厉害的魔法。我负责保护迷雾巨石……嗯，大多数时候我还是相当称职的。$B$B愚蠢的狗狗人。"
D.Strings[24411]="狗狗人的攻击已经持续好几天了。但是闪电巨石还很安全。$B$B跟往常一样，索乌霍鲁向我们伸出了援手……狗狗人不会有获胜的机会。"
D.Strings[24412]="卡塔克是来吃大舌头怪的。我们要为他准备一顿大餐。"
D.Strings[24413]="立即与我在市政厅会合，勇士。我们必须直接挑战玛尔加尼斯。"
D.Strings[24414]="伪装失效了！避开天灾兵！"
D.Strings[24415]="苏特菲兹，今天是你的幸运日。$n为你带回了更多的龙崽。"
D.Strings[24416]="我凭什么要替你照顾龙崽啊，多里安。我还要搞研究工作呢。"
D.Strings[24417]="好吧，你随时可以返回营地，帮助维斯雷摆弄那堆齿轮……"
D.Strings[24418]="不要，我讨厌齿轮！别让我碰那玩意儿！"
D.Strings[24419]="朋友，他们比我想象的更强壮。进攻！"
D.Strings[24420]="听我指挥，这个交给我来处理！"
D.Strings[24421]="这东西是从哪儿来的？趁工头还没发现，我最好赶紧把它拖到船上去！"
D.Strings[24422]="管它做什么呢。放在这里就是了，不会有人发现的！"
D.Strings[24423]="我们把闪闪发光的宝贝都供奉给了神殿……我们一点也不贪心啊……为什么会这样？"
D.Strings[24424]="把我的宝藏拿去吧……这样天气就会好转……亡灵也会离开。"
D.Strings[24425]="谢谢……你。"
D.Strings[24426]="我们……什么都没做啊……我搞不明白。"
D.Strings[24427]="我做错事了？对不起……"
D.Strings[24428]="谢谢你！你是个好人！"
D.Strings[24429]="或许你也能让天气好转？"
D.Strings[24430]="我会为神殿供奉更多闪闪发光的宝贝！我发誓！对不起！"
D.Strings[24431]="继续搭救苔行鳄鱼人，好吗？"
D.Strings[24432]="你救了我们！谢谢你！"
D.Strings[24433]="干皮人，你好。"
D.Strings[24434]="一切顺利吗？"
D.Strings[24435]="有你这样优秀的猎手陪同，感觉真好。"
D.Strings[24436]="嗨！你还好吧？我们很好……嗯，很好很好。嗨！"
D.Strings[24437]="你被自己绊倒过吗？我们有过这样的经历诶。有点痛。不好玩，我们不要再绊倒了。"
D.Strings[24438]="你好！你看上去又强壮又和善。我喜欢你。我们做朋友好不好啊？"
D.Strings[24439]="要帮忙吗？要帮忙吗？我们是很乐于助人的。"
D.Strings[24440]="为什么我们还待在这里？"
D.Strings[24441]="你想要什么东西吗？"
D.Strings[24442]="我永远欠你一份情，$n。"
D.Strings[24443]="$n，犸托斯的鲜血让我变得强壮起来。"
D.Strings[24444]="我自由了！快，为奎丝鲁恩复仇。我稍后会和你在希姆托加碰面。"
D.Strings[24445]="喘……喘不过气来……"
D.Strings[24446]="皮肤……滚烫……好痛……"
D.Strings[24447]="视线……越来越模糊……看……看不见了……"
D.Strings[24448]="救……救命……来人……"
D.Strings[24449]="我快死了……"
D.Strings[24450]="进攻方未能在规定时间内击败防守方！不能获得奖励！"
D.Strings[24451]="我们躲在你身后，这次你休想抓到我们！现在要好好教训你！哼！"
D.Strings[24452]="坏东西，你很快就要死了！你再也不能打扰瑟匹克睡觉啦！"
D.Strings[24453]="没用的废物，滚到坑里去！"
D.Strings[24454]="要么滚到坑里去，要么就吃鞭子！"
D.Strings[24455]="食尸鬼！进坑！快点！"
D.Strings[24456]="滚进坑里去，否则我就将你轰成渣！"
D.Strings[24457]="没脑子的蠢货！滚到坑里去！"
D.Strings[24458]="我命令你们，立刻进坑！就是现在！"
D.Strings[24459]="联盟占领了泰坦的传送门！"
D.Strings[24460]="部落占领了泰坦的传送门！"
D.Strings[24461]="远古海滩之战结束了！"
D.Strings[24462]="$n，到我这里来。我就在希姆托加。"
D.Strings[24463]="先知陷入了沉思，盘算着如何才能巧妙地偷取女神的力量。"
D.Strings[24464]="%s打算祈祷一番，希望哈克娅能给出建议，但最终决定不这么做。"
D.Strings[24465]="%s暗自嘀咕，一边抱怨自己的计划进展缓慢，一边继续进行仪式。"
D.Strings[24466]="先知扭了扭脖子，似乎察觉到出了什么差错。"
D.Strings[24467]="我要找格利基克，你有他的镣铐吗？"
D.Strings[24468]="我要找达伊克，你有他的粉笔吗？"
D.Strings[24469]="我要找瑟匹克，你有他的狩猎号角吗？"
D.Strings[24470]="$g爸爸:妈妈;！"
D.Strings[24471]="我要找拉弗乌，你有他的虫袋吗？"
D.Strings[24472]="我要找亚鲁乌特，你有他的宝贝水晶吗？"
D.Strings[24473]="我要找莫乌德，你有他的皮球吗？"
D.Strings[24474]="我要让你陪葬！"
D.Strings[24475]="恶魔，没那么容易！"
D.Strings[24476]="墓穴在呼唤我们！"
D.Strings[24477]="是你杀了我！"
D.Strings[24478]="死吧，天灾！"
D.Strings[24479]="天气不错啊，很适合飞行，不是吗？"
D.Strings[24480]="我一眼就能认出谁是王牌飞行员。谢谢你救了我！"
D.Strings[24481]="天灾军团冲破了防线！"
D.Strings[24482]="他们就在后面！已经占领了船只！"
D.Strings[24483]="这群怪物！"
D.Strings[24484]="怎么会这样！？"
D.Strings[24485]="将他们从船上赶下去！杀光他们！"
D.Strings[24486]="躲起来！避开火力！"
D.Strings[24487]="难以置信！"
D.Strings[24488]="消灭天灾军团！"
D.Strings[24489]="双方都守住了要塞！平局！"
D.Strings[24490]="你得加快速度啊！我已经杀死11个了！"
D.Strings[24491]="第10个！你呢？"
D.Strings[24492]="9个！我闭着眼睛都能命中猎物！"
D.Strings[24493]="11！比起揍老德洛斯坦来，这稍微难一点！"
D.Strings[24494]="返回灵鳍湾或是卡塔克要塞。"
D.Strings[24495]="返回卡塔克要塞或是灵鳍湾。"
D.Strings[24496]="第一回合 - 结束！"
D.Strings[24497]="返回犸托斯祭坛！"
D.Strings[24498]="部落防御胜利计算。"
D.Strings[24499]="联盟防御胜利计算。"
D.Strings[24500]="你死定了，朋友！"
D.Strings[24501]="我是来为兄弟们报仇的！"
D.Strings[24502]="死吧，肮脏的天灾兵！"
D.Strings[24503]="我们要把天灾军团赶出祖达克——就从你开始吧！"
D.Strings[24504]="什么？！……"
D.Strings[24505]="哎哟！"
D.Strings[24506]="噢！"
D.Strings[24507]="当你的身体和索乌霍鲁融合时，你感到一阵剧烈的能量波动。"
D.Strings[24508]="看看你所取得的成就，死亡骑士！你真是天灾军团的荣耀！"
D.Strings[24509]="当你的身体和卡塔克融合时，一股怒气从你心中腾起。"
D.Strings[24510]="滚远点！"
D.Strings[24511]="等等！我要坚持下去！"
D.Strings[24512]="别杀我！我只是想赚点钱！"
D.Strings[24513]="别杀我！你让我干什么都行！"
D.Strings[24514]="我不会屈服！我要战斗下去！"
D.Strings[24515]="求你住手！停止杀戮！"
D.Strings[24516]="我挑错了戒酒的日子！"
D.Strings[24517]="啊……我……我好象拉屎了……"
D.Strings[24518]="我... 我要继续战斗下去... 我... 我不会屈服。"
D.Strings[24519]="收获的时节……到了！"
D.Strings[24520]="祖达克不欢迎天灾军团！"
D.Strings[24521]="朋友，祖达克属于达卡莱氏族。永远都是！"
D.Strings[24522]="天灾军团注定会失败。"
D.Strings[24523]="我们会杀光天灾兵！"
D.Strings[24524]="滚开，恶心的天灾兵！"
D.Strings[24525]="你不是天灾军团的成员。朋友，你来这儿做什么？"
D.Strings[24526]="天灾军团怎么会允许你四处闲逛？"
D.Strings[24527]="你迷路了吧……"
D.Strings[24528]="我的族人随时会来救我……我相信。"
D.Strings[24529]="你想把我们怎么样？"
D.Strings[24530]="杀了我吧！我不想加入天灾军团！"
D.Strings[24531]="我绝不向巫妖王效忠！绝不！"
D.Strings[24532]="达卡莱帝国必胜！天灾军团将再次……全军覆没。"
D.Strings[24533]="嗯？让我们瞧瞧这具尸体能冒出什么来。"
D.Strings[24534]="该死的恶鬼！他们几乎吞掉了这具尸体……"
D.Strings[24535]="肮脏的家伙！别碰那些尸体！"
D.Strings[24536]="这具尸体真丑。很合适做食尸鬼……"
D.Strings[24537]="我估计这具尸体的脊椎已经断了！正好做食尸鬼！"
D.Strings[24538]="难道要收割者戈提克动手掐死一个恶鬼吗？"
D.Strings[24539]="啧啧！又一个食尸鬼！"
D.Strings[24540]="你有一个魔化蒂基面具？是你杀了我的家人！"
D.Strings[24541]="我要杀了你，$n！"
D.Strings[24542]="很快，$n。$b$b我们已经做好准备，可以启程前往古达克了！"
D.Strings[24543]="你很快就能再次飞翔了……"
D.Strings[24544]="骷髅翅膀将扇起死亡的气息……"
D.Strings[24545]="起来吧。为天灾军团而飞翔！"
D.Strings[24546]="开饭的时间到了。醒来吧！"
D.Strings[24547]="兄弟姐妹们，睁开双眼！凝视命运的启示吧！"
D.Strings[24548]="天空吞噬着被征服者的痛苦！"
D.Strings[24549]="血色十字军休想阻止我们！"
D.Strings[24550]="那些尸体只会令我们的军队日益壮大！"
D.Strings[24551]="停泊在破碎海岸的十字军舰队已成残骸！"
D.Strings[24552]="天灾军团的战士一定会击败敌人！"
D.Strings[24553]="巫妖王和你们都谈过！让他的教诲再次引起你们的共鸣吧！"
D.Strings[24554]="是伟大的巫妖王将你们重新唤醒。"
D.Strings[24555]="是伟大的天灾军团让你们重获生机。"
D.Strings[24556]="死亡骑士不需要怜悯，"
D.Strings[24557]="血色十字军的末日即将来临。我的骑士们，用你们手中的长剑，让他们瞧瞧究竟什么是真正的血色！"
D.Strings[24558]="一旦放置天灾锅，这块看似普通的南瓜田就会成为诅咒的源头！"
D.Strings[24559]="诺斯，希尔盖呢？"
D.Strings[24560]="你竟敢提起他！滚出我的视线！"
D.Strings[24561]="那个马屁精大概正在房间里练习芭蕾舞吧。"
D.Strings[24562]="别在我面前提他的名字！我只警告你这一次！"
D.Strings[24563]="我可以告诉你他不在哪儿……"
D.Strings[24564]="希尔盖可能在清理他那间肮脏的舞蹈室。"
D.Strings[24565]="%s高高跃起，示意你骑上马背。"
D.Strings[24566]="新阿瓦隆被攻陷只是时间问题。"
D.Strings[24567]="天灾军团冲破了防线！快跑！跑啊！"
D.Strings[24568]="天灾军团！！！快跑！！"
D.Strings[24569]="饶了我吧，$n！求你了！"
D.Strings[24570]="难道我们已经无处可逃了吗？"
D.Strings[24571]="谁来救救我！"
D.Strings[24572]="我们都要完蛋了！！！"
D.Strings[24573]="我杀了15个。看看你能不能超过我！"
D.Strings[24574]="第16个。我可是一直让着你的！"
D.Strings[24575]="你要加把劲赶上来才行啊，否则这算什么比赛呢。"
D.Strings[24576]="哈！16！你呢？10个，还是11个啊？"
D.Strings[24577]="我杀了25个了。你落后多少呀？"
D.Strings[24578]="人生…人生真是无常啊..."
D.Strings[24579]="生命不息，战斗不止！"
D.Strings[24580]="我绝不会在敌人面前屈服的！"
D.Strings[24581]="懦夫！结束这一切吧……"
D.Strings[24582]="天灾兵……愿圣光将你们彻底消灭！"
D.Strings[24583]="26！你到底要不要开始猎杀啊？"
D.Strings[24584]="我妈妈狩猎起来都比你快，$n。"
D.Strings[24585]="我已经杀了26个，这还只是热身而已。"
D.Strings[24586]="芬努斯这里有你需要的东西，朋友。"
D.Strings[24587]="我要买东西，芬努斯。"
D.Strings[24588]="唔，我已经占据领先优势啦，可以小睡一会儿。"
D.Strings[24589]="啊，睡得真舒服。狩猎比赛的情况如何啦？"
D.Strings[24590]="他们说过会确保我们的安全！安全！"
D.Strings[24591]="天灾军团在街道上横冲直撞！"
D.Strings[24592]="我的家人都被杀害了！在我们最需要军队帮助的时候，他们在哪儿？"
D.Strings[24593]="哎呀，我领先很多了嘛。我去钓会儿鱼好了。"
D.Strings[24594]="奎比，别再隐瞒了！我们要知道实情！"
D.Strings[24595]="奎比，那些船要开到哪儿去？！说实话！"
D.Strings[24596]="我们完蛋了！救救我们，奎比！"
D.Strings[24597]="如果你再不露面，我们就踏平这里！"
D.Strings[24598]="大家都会没命的！救救我们！"
D.Strings[24599]="“血色的黎明”是什么！奎比，我们有权知道真相！"
D.Strings[24600]="纳克萨玛斯飞走了？我们才不关心呢！来自阿彻鲁斯的死亡骑士正在大肆屠杀我们的同胞！"
D.Strings[24601]="奎比，下届选举时我一定不会投你的票！"
D.Strings[24602]="你这没用的废物，奎比！"
D.Strings[24603]="这是对我们的蔑视！快回答我们的问题！"
D.Strings[24604]="呃，原来我们还在比赛啊。"
D.Strings[24605]="我想搭最后一班船！别扔下我们！"
D.Strings[24606]="别再扯什么血色“乐园”了！"
D.Strings[24607]="奎比！！！！！！"
D.Strings[24608]="第41个！我的技术不错吧？"
D.Strings[24609]="41！已经完成2/3啦。再加把劲儿！"
D.Strings[24610]="嘿！我分明已经瞄准了那只猎物。你偷了我的猎物！"
D.Strings[24611]="啊，才到48。越来越困难了。"
D.Strings[24612]="有人将那些从我手中逃掉的猎物都杀了。能有48个的成绩已经很不容易了。"
D.Strings[24613]="48。速度逐渐慢下来了。"
D.Strings[24614]="我要去别的地方找些猎物了。按照原定计划，应该不止48个啊。"
D.Strings[24615]="哈，54！进入最后冲刺阶段！"
D.Strings[24616]="54！我不会输给你的！"
D.Strings[24617]="54！压倒性的优势啊！"
D.Strings[24618]="54了！准备祝贺我吧！"
D.Strings[24619]="啊……你来了。主人说过，你很快就会到的。"
D.Strings[24620]="请跟我来，$n。有很多东西要给你看……"
D.Strings[24621]="嗨！"
D.Strings[24622]="带我去黑锋要塞吧。"
D.Strings[24623]="带我去东瘟疫之地！"
D.Strings[24624]="“血色的黎明”是什么？"
D.Strings[24625]="关于“血色的黎明”，你都知道些什么？快说，不然就等着吃鞭子吧！"
D.Strings[24626]="我对你已经够客气的了！“血色的黎明”到底是什么？"
D.Strings[24627]="“血色的黎明”究竟是什么！说！"
D.Strings[24628]="我有的是精力对付你！说吧，“血色的黎明”是什么！"
D.Strings[24629]="我迟早会掏出埋在你心里的所有秘密！只要你肯开口，我就饶你一命！"
D.Strings[24630]="你的性命就这么不值钱吗？只要你告诉我关于“血色的黎明”的资料，我就立即结束你的痛苦。"
D.Strings[24631]="我不想再费唇舌了。把“血色的黎明”的秘密告诉我，否则我就要你好看！"
D.Strings[24632]="呸，我不会告诉你的！"
D.Strings[24633]="你杀了我吧，怪物。我什么都不会说！"
D.Strings[24634]="啊……痛……差点就赶上我小时候在学校里受过的鞭刑了。"
D.Strings[24635]="你……你什么都别想……别想知道……"
D.Strings[24636]="你以为自己下手很重？我难以忍受这痛苦？哈哈！摧毁这凡人的躯壳，我就能升入天堂！"
D.Strings[24637]="我说，你挥舞鞭子的力道像个小姑娘。你就这点能耐？"
D.Strings[24638]="什么血色啊？我从来没有听说过……"
D.Strings[24639]="这样的痛苦只是暂时的。如果我泄漏了机密，阿比迪斯将军肯定会令我生不如死……"
D.Strings[24640]="我说！住手！求你了！"
D.Strings[24641]="我们……我们只知道“血色的黎明”象征着觉醒。你……你瞧，圣光给了阿比迪斯将军新的启示。是圣光……"
D.Strings[24642]="是圣光在指引我们。天灾军团抵达之前，这次行动就已经开始了……我们……只是简单地奉命行事。我们必须服从军令。"
D.Strings[24643]="其他的我就不清楚了……阿比迪斯将军决定谁走谁留。我只知道这些……你要相信我啊！"
D.Strings[24644]="啊！住手！还有一件事我忘记说了……很快就会有信差……从壁炉谷赶来。嗯……"
D.Strings[24645]="%s终于屈服了。"
D.Strings[24646]="怪物，你根本不了解什么才是真正的痛苦！"
D.Strings[24647]="哈！我经历过三次严酷的拷问！这根本不算什么！"
D.Strings[24648]="当心！有只蜜蜂飞出去啦，它气得想到处蛰人呐！"
D.Strings[24649]="这一鞭就跟挠痒似的……"
D.Strings[24650]="我要把你切得粉碎，送还给巫妖王！"
D.Strings[24651]="你很快就要被押上绞刑架了，魔鬼！"
D.Strings[24652]="我曾是大检察官伊森利恩的部下！你的鞭刑就像午后茶点一般！"
D.Strings[24653]="啊！你烧坏了我的战袍！那是我唯一保存完好的战袍！"
D.Strings[24654]="撒谎！接下来你要承受的痛苦足够你谈论好几年！"
D.Strings[24655]="颤抖吧，异教徒！一名十字军领主加入了战斗！"
D.Strings[24656]="净化新阿瓦隆！铲除天灾军团！"
D.Strings[24657]="十字军……$B$B<瑞文戴尔男爵摇了摇头。>$B$B他们是一群特殊的人类。在我看来，十字军似乎不具备高等智慧，他们无法理智地评估局势并计算得失。只要提到圣光，就能让他们群情激昂——接着，这帮家伙会完全无视自己的利益，盲目地投身战斗。"
D.Strings[24658]="时间的旅者，过来。我有话和你说！"
D.Strings[24659]="我们又见面了，时间的旅者！"
D.Strings[24660]="快过来吧！"
D.Strings[24661]="你应该感到荣幸。主人要我们向你展示沃尔塔鲁斯的工事，这还是头一遭。"
D.Strings[24662]="主人从达克萨隆来到这里时，就预言了你到此造访的时间。"
D.Strings[24663]="我向你展示的东西绝对不能在沃尔塔鲁斯以外提起。我们的秘密很快就能揭晓了！"
D.Strings[24664]="这些是我们储藏的荒芜水晶。没有水晶，我们的计划就不可能成功。"
D.Strings[24665]="我知道，你会为我们做好了充足的储备而感到庆幸。"
D.Strings[24666]="这些是你在战场上俘虏的巨魔。你的身手确实不错……"
D.Strings[24667]="我自由了，达卡莱巨魔。为你们的罪行付出代价吧！"
D.Strings[24668]="我在这儿，$n。你没被跟踪吧？"
D.Strings[24669]="阿卡里，我的主人需要你的鲜血，我也要夺取你的一部分力量！"
D.Strings[24670]="$n！我一直在等你。你怎么去了那么久？$b$b我们可以对荒芜之血进行转换了。$b$b让我们共同见证军队的诞生吧！"
D.Strings[24671]="我准备好了，达库鲁。"
D.Strings[24672]="好了。滚回你的主人身边吧。告诉哈克娅，我来了！"
D.Strings[24673]="我好像弄丢了你的伐木机控制器……还有吗？"
D.Strings[24674]="萨萨里安，你为什么这么在意？"
D.Strings[24675]="他过于孱弱，所以被俘虏了。"
D.Strings[24676]="唯有强者才能生存。更别说是……"
D.Strings[24677]="更别说什么，奥尔巴兹？就因为他是血精灵？"
D.Strings[24678]="活着的时候，我们是不共戴天的仇敌……"
D.Strings[24679]="但在死后……诅咒的种子在我们心中扎根，我们都沦为了天灾军团的孤儿。"
D.Strings[24680]="死后我们成为了兄弟。"
D.Strings[24681]="见鬼去吧，萨萨里安。"
D.Strings[24682]="该死的十字军！我的肋骨折断了，似乎有内出血的症状。"
D.Strings[24683]="你在找什么？"
D.Strings[24684]="我只想好好地喝一杯。"
D.Strings[24685]="我要找回符文剑和盔甲……很快就好。"
D.Strings[24686]="侍僧，将他们锁起来！准备审讯！"
D.Strings[24687]="我很虚弱，但是我应该能撑起一个反魔法屏障。你最好别走出屏障，否则就会被他们的法术杀死。"
D.Strings[24688]="我伤得很重，但是我会尽量帮忙的。你最好待在我撑起的反魔法屏障中，否则侍僧的魔法会将你撕成碎片。"
D.Strings[24689]="我必须集中精神维持这个屏障。去消灭他们！"
D.Strings[24690]="你瞎转悠什么呢，快回去工作！"
D.Strings[24691]="敌人再次发动了攻击。注意安全！别离开反魔法区域！没有屏障的保护，他们轻易就能将你撕成碎片！"
D.Strings[24692]="屏障支撑不了多久了……那个胆小鬼在哪儿呢？"
D.Strings[24693]="我能帮你什么忙吗，$r？"
D.Strings[24694]="大检察官来了！准备迎战，死亡骑士！别离开反魔法屏障的安全区域！击败他，拿到他的徽记！"
D.Strings[24695]="知道了！别打我！"
D.Strings[24696]="我需要水下呼吸效果，盖伦。"
D.Strings[24697]="嘿嘿，食人魔笨蛋。你以为我会乖乖地回去工作吗？"
D.Strings[24698]="肮脏的天灾兵！接受圣光的净化吧！"
D.Strings[24699]="十字军会从这个世界上抹去你们的存在！"
D.Strings[24700]="看样子我得亲自对付你了。尝尝大检查官的厉害吧，天灾军团！"
D.Strings[24701]="宝珠中散发出一道微弱的光芒，表面笼罩着一层蓝色的雾气。"
D.Strings[24702]="别以为天灾军团的黑暗魔法能让你们免受圣光的惩罚！"
D.Strings[24703]="懦夫！"
D.Strings[24704]="出来玩玩吧。"
D.Strings[24705]="接受圣光的净化吧！"
D.Strings[24706]="你想要寻求救赎？我就是你的救星！"
D.Strings[24707]="%s的尸体跌落在地。"
D.Strings[24708]="坚守阵地！利用反魔法屏障抵挡他们的法术！"
D.Strings[24709]="别离开反魔法屏障！将他们引过来！"
D.Strings[24710]="死亡骑士，快用死亡之握！将他们拖进来！"
D.Strings[24711]="别和他们打持久战！集中注意力！"
D.Strings[24712]="我不可能一直维持反魔法屏障。动作快点，消灭他们！"
D.Strings[24713]="一旦战败，圣光将因此蒙羞。"
D.Strings[24714]="%s瘫倒在地。"
D.Strings[24715]="你完蛋了，死亡骑士！"
D.Strings[24716]="拉弗乌从土堆里挖出几只虫子。"
D.Strings[24717]="库弗，我们再次听到你的召唤。请允许我们给你和$n几句忠告。你们即将面临巨大的威胁，如果不赶紧行动的话，你们和哈克娅都会丧命。"
D.Strings[24718]="唯有完美的守卫者徽记能传达挑衅的意图。拥有这颗徽记的守卫者就在戒备森严的希姆鲁克。"
D.Strings[24719]="只有杀死奎丝鲁恩祭坛典狱官，获得充满活力的典狱官精华，才能引出阿卡里先知。你必须将这两件稀罕物交给哈克娅。"
D.Strings[24720]="未来仍然笼罩着阴霾。$n，这是你的命运。虽然你和你的伙伴或许不是先知的对手，但是，你必须尝试。"
D.Strings[24721]="不，也不是哈克娅！"
D.Strings[24722]="若有所思地向巫医所在的方向看去。"
D.Strings[24723]="新阿瓦隆大检查官的死亡必然会引起敌人的注意。你最好立刻离开！快跑吧，趁敌人还没有涌上来。我会照顾好自己的。"
D.Strings[24724]="我来吸引火力，掩护你逃走。"
D.Strings[24725]="十字军，你们的大检查官已经死了！没有人能逃出天灾军团的控制！"
D.Strings[24726]="<库尔迪拉呻吟着。>"
D.Strings[24727]="库尔迪拉，我们快离开这儿！"
D.Strings[24728]="旅店的设施并不符合我的要求，不过……这里至少还算暖和。"
D.Strings[24729]="血色十字军将迎来一名新主子——我是说，在他们死后……"
D.Strings[24730]="剑刃残留着鲜血的余温，雷耶克很喜欢。"
D.Strings[24731]="雷耶克感觉自己变强壮了！雷耶克能徒手击败大舌头怪！"
D.Strings[24732]="雷耶克和$n要让狂心氏族的敌人吓得簌簌发抖！"
D.Strings[24733]="这是什么？我杀死阿卡里时就认出你了。你是$n，他们都很惧怕你。"
D.Strings[24734]="你根本不足为患，$g小子:小丫头;。相反，我正想杀了你。谁也别想阻止我进入希姆托加！"
D.Strings[24735]="蠢货！谁都无法阻止我们！"
D.Strings[24736]="直到现在你才明白——我拥有神灵的力量，这真是遗憾。你不过是个凡人，怎可能击败我！"
D.Strings[24737]="你这是挑衅吗？"
D.Strings[24738]="我要挑战你，死亡骑士！"
D.Strings[24739]="多管闲事。你只是闯入巨魔帝国的外来者。去死吧！"
D.Strings[24740]="先知开始施放歼灭仪式。"
D.Strings[24741]="决斗即将开始……"
D.Strings[24742]="你这是在挑战死神！"
D.Strings[24743]="看我怎么把你揍趴下，菜鸟！"
D.Strings[24744]="别逗我笑了。"
D.Strings[24745]="啧啧，哭鼻子啦……"
D.Strings[24746]="不准喝药！"
D.Strings[24747]="你赢不了的，$n。"
D.Strings[24748]="看看谁才是巫妖王麾下真正的勇士！"
D.Strings[24749]="先知！"
D.Strings[24750]="什么？哈克娅？！"
D.Strings[24751]="把你的脏手拿开！"
D.Strings[24752]="很好，小东西。看来我也不必对你手下留情了。等我解决掉这个蠢货，再来对付你！"
D.Strings[24753]="是吗？我命令你立即终止仪式，放了他们！"
D.Strings[24754]="不！我是不会被打败的！"
D.Strings[24755]="谢谢你。你再次拯救了我们。我会在希姆托加等你。"
D.Strings[24756]="呃，似乎没用。"
D.Strings[24757]="记住，别把蓝色的和绿色的混起来。"
D.Strings[24758]="啊，应该试试红色的！"
D.Strings[24759]="这不是我想要的结果。"
D.Strings[24760]="朋友，好好瞧瞧这里。你要帮我征服它！"
D.Strings[24761]="%s低声地抽泣。"
D.Strings[24762]="你是来执行任务的吧？"
D.Strings[24763]="看着我的眼睛……"
D.Strings[24764]="$n，我认得你的犄角……他们……他们对你做了些什么，$n？"
D.Strings[24765]="你不记得我了？该死的天灾军团……他们挫败了你的正义之气、泯灭了你最后一丝良知……还有你身为牛头人的天性！"
D.Strings[24766]="朋友！瞧瞧，这片土地承载了多少荣耀！"
D.Strings[24767]="巫妖王愿意与忠于他的仆从分享力量。"
D.Strings[24768]="来见我吧，$n。我必须和你谈谈。"
D.Strings[24769]="$n，仔细回忆。想想莫高雷起伏的草原，那是你的家乡。想想生命的壮丽画卷。你，曾是牛头人氏族的勇士！眼前的你，不是真正的你。"
D.Strings[24770]="蓝玉之门遭到攻击！"
D.Strings[24771]="翡翠之门遭到攻击！"
D.Strings[24772]="红日之门遭到攻击！"
D.Strings[24773]="紫晶之门遭到攻击！"
D.Strings[24774]="金月之门遭到攻击！"
D.Strings[24775]="我……我支撑不住了。这是注定的命运。杀了我吧，$n，否则我们俩都难逃一死。$n……想想莫高雷。这个世界值得你去拯救。"
D.Strings[24776]="金月之门被摧毁了！"
D.Strings[24777]="紫晶之门被摧毁了！"
D.Strings[24778]="红日之门被摧毁了！"
D.Strings[24779]="翡翠之门被摧毁了！"
D.Strings[24780]="蓝玉之门被摧毁了！"
D.Strings[24781]="我是来……"
D.Strings[24782]="你不记得我了？该死的天灾军团……他们挫败了你的正义之气、泯灭了你最后一丝良知……还有你身为人类的天性！"
D.Strings[24783]="$n，仔细回忆。想想艾尔文森林静谧的山谷，那是你的家乡。想想生命的壮丽画卷。你，曾是联盟的勇士！眼前的你，不是真正的你。"
D.Strings[24784]="我……我支撑不住了。这是注定的命运。杀了我吧，$n，否则我们俩都难逃一死。$n……想想艾尔文森林。这个世界值得你去拯救。"
D.Strings[24785]="%s因为伤势过重而死掉了。"
D.Strings[24786]="到处都是狼人！不要轻言放弃，我就在你身后！"
D.Strings[24787]="你不记得我了？那时候，你还是襁褓中的婴儿。你的母亲每次去月神殿当值时，就会把你托付给我。我抱着你，喂你蜂蜜和羊奶。我耐心地哄你睡觉，直到你的母亲回家。你就像我的小天使。该死的天灾军团……他们对你做了什么，$n？"
D.Strings[24788]="恐怕我们还没有见识到阿鲁高的恐怖……"
D.Strings[24789]="想想生命的壮丽画卷。你，曾是卡多雷的勇士！眼前的你，不是真正的你。"
D.Strings[24790]="我……我支撑不住了。这是注定的命运。杀了我吧，$n，否则我们俩都难逃一死。$n……想想泰达希尔，我们挚爱的家园。这个世界值得你去拯救。"
D.Strings[24791]="啊，来自铁炉堡的孩子，你想做什么……"
D.Strings[24792]="$n，我认得你的脸庞……他们……他们对你做了些什么，$g小伙子:小姑娘;？"
D.Strings[24793]="你不记得我了？该死的天灾军团……他们挫败了你的正义之气、泯灭了你最后一丝良知……还有你身为铁炉堡的孩子的天性！"
D.Strings[24794]="$n，仔细回忆。想想丹莫罗被白雪覆盖的山脊，那是你的家乡。想想生命的壮丽画卷。你，曾是矮人氏族的勇士！眼前的你，不是真正的你。"
D.Strings[24795]="听我说，$n。你必须摆脱巫妖王的控制。他一心盘算着毁掉这个世界，毁掉我们的家园。你不该沦为任由他摆布的棋子！过去，你曾是一名伟大的英雄；现在，我相信你能为新的英雄。反抗吧！摆脱巫妖王的控制！"
D.Strings[24796]="我……我支撑不住了。这是注定的命运。杀了我吧，$n，否则我们俩都难逃一死。$n……为了卡兹莫丹！！！"
D.Strings[24797]="抓住他们！"
D.Strings[24798]="能不能让我……"
D.Strings[24799]="你不记得我了？该死的天灾军团……他们挫败了你的正义之气、泯灭了你最后一丝良知……还有你身为侏儒的天性！"
D.Strings[24800]="$n，仔细回忆。想想穴居人入侵前的诺莫瑞根！想想手握弧光扳手的感觉。你，曾是侏儒氏族的勇士！眼前的你，不是真正的你。"
D.Strings[24801]="我……我支撑不住了。这是注定的命运。杀了我吧，$n，否则我们俩都难逃一死。$n……想想诺莫瑞根。这个世界值得你去拯救。"
D.Strings[24802]="$n，我认得你的面须……他们……他们对你做了些什么，$n？"
D.Strings[24803]="你不记得我了？该死的天灾军团……他们挫败了你的正义之气、泯灭了你最后一丝良知……还有你身为德莱尼人的天性！"
D.Strings[24804]="$n，仔细回忆。想想阿古斯高耸的山脊，那是你的家乡。想想生命的壮丽画卷。你，曾是德莱尼氏族的勇士！眼前的你，不是真正的你。"
D.Strings[24805]="我……我支撑不住了。这是注定的命运。杀了我吧，$n，否则我们俩都难逃一死。$n……想想阿古斯。这个世界值得你去拯救。"
D.Strings[24806]="你不记得我了？该死的天灾军团……他们挫败了你的正义之气、泯灭了你最后一丝良知……还有你身为血精灵的天性！"
D.Strings[24807]="$n，仔细回忆。想想银月城宏伟的殿堂，那是你的家乡。想想生命的壮丽画卷。你，曾是辛多雷氏族的勇士！眼前的你，不是真正的你。"
D.Strings[24808]="我……我支撑不住了。这是注定的命运。杀了我吧，$n，否则我们俩都难逃一死。$n……想想银月城。这个世界值得你去拯救。"
D.Strings[24809]="我要像兽人那样死去……"
D.Strings[24810]="你不记得我了？该死的天灾军团……他们挫败了你的正义之气、泯灭了你最后一丝良知……还有你身为兽人的天性！"
D.Strings[24811]="$n，仔细回忆。想想杜隆塔尔！氏族的勇士不惜牺牲自己，解除了嗜血的诅咒。想想我们的诞生之地——试炼谷。那时，我们的世界一片祥和，不曾翻涌着恶魔的气息。我们共同书写了壮丽的生命画卷，$n。你，曾是部落的勇士！眼前的你，不是真正的你。"
D.Strings[24812]="我……我支撑不住了。这是注定的命运。杀了我吧，$n，否则我们俩都难逃一死。$n……为了部落！这个世界值得你去拯救。"
D.Strings[24813]="很讽刺吧？身为被遗忘者，还能再死一次……"
D.Strings[24814]="$n，我认得你的骨头……他们……他们对你做了些什么，$n？"
D.Strings[24815]="你不记得我了吗？很久很久以前，我们曾经是人类。天灾军团攻陷洛丹伦后，我们相继沦为僵尸。但是不久之后，黑暗女王解放了我们。"
D.Strings[24816]="我们曾经起誓！要向巫妖王复仇！他摧毁了我们的王国，我们发誓要让他付出代价！我们组建起被遗忘者大军，和天灾军团作战，将他们赶回了瘟疫之地，解放了提瑞斯法林地！你和我都曾是被遗忘者氏族的勇士！"
D.Strings[24817]="我……我支撑不住了。这是注定的命运。杀了我吧，$n，否则我们俩都难逃一死。$n……想想提瑞斯法林地。这个世界值得你去拯救。"
D.Strings[24818]="$n？伙计？"
D.Strings[24819]="$n，我认得你的獠牙……他们……他们对你做了些什么，伙计？"
D.Strings[24820]="你不记得我了？该死的天灾军团！他们榨干了你的魔精，泯灭了你最后一丝良知……还有你身为巨魔的天性！"
D.Strings[24821]="$n，仔细回忆。我们是暗矛巨魔啊，朋友！我们情同手足！还记得我们击败扎拉赞恩的英雄事迹吗？我们打败了他，解放了回音群岛！朋友！好好想想！你曾经是暗矛巨魔氏族的勇士！"
D.Strings[24822]="我……我支撑不住了。这是注定的命运。杀了我吧，$n，否则我们俩都难逃一死。$n……想想森金村，朋友！这个世界值得你去拯救。"
D.Strings[24823]="动手吧，$n！让我解脱吧！"
D.Strings[24824]="呃，这棵树真奇怪。我必须研究一下。"
D.Strings[24825]="总有一天，雷耶克会成为强大的战士。"
D.Strings[24826]="这是什么！？这根本不是树！守卫！来人啊！"
D.Strings[24827]="暴风城港口"
D.Strings[24828]="要去奥伯丁或者无畏要塞吗？只要穿过运河，就能抵达位于教堂广场和花园之间的暴风城港口。"
D.Strings[24829]="暴风城港口是前往奥伯丁和无畏要塞的捷径。它就在教堂广场和花园之间。"
D.Strings[24830]="你好，$c。我相信你带来了一些关于全球邀请赛的好消息？如果是的话，那么你肯定已经获得了一段神秘兑换码。只要你把那段神秘兑换码告诉我，我就可以送给你一件礼物，泰瑞尔的剑柄。$B$B准备好了之后就告诉我吧。"
D.Strings[24831]="我要告诉你那段神秘兑换码，获得泰瑞尔的剑柄。"
D.Strings[24832]="信使到了！"
D.Strings[24833]="到了！信使总算到了！"
D.Strings[24834]="快给信使让路！快，去觐见将军！"
D.Strings[24835]="就凭这点能耐，也想打败我？"
D.Strings[24836]="尽情告饶吧。我是不会心软的！"
D.Strings[24837]="永恒的诅咒就是你的下场！"
D.Strings[24838]="你杀了我，现在轮到我杀你了……反反复复地杀！"
D.Strings[24839]="休想逃走。尝尝我的怒火吧！"
D.Strings[24840]="在怒火中煎熬吧！"
D.Strings[24841]="如你所愿，达库鲁。"
D.Strings[24842]="我们觉得最好将他们安置在这里，让他们乖乖地接受注定的命运。"
D.Strings[24843]="这就是他们的命运……"
D.Strings[24844]="诅咒会逐渐侵入他们的肉体，使他们的体质发生变化。"
D.Strings[24845]="这种特殊的转变将赋予他们难以想象的力量。"
D.Strings[24846]="很快，主人会赐予他们黑暗的礼物，让他们能够永远为巫妖王效劳！"
D.Strings[24847]="$n，你想在这里呆多久都行。好好享受你的努力所换来的成果吧！"
D.Strings[24848]="你帮助主人实现了他伟大的计划。愿你的力量越来越强……"
D.Strings[24849]="看！我们正在创建一支最强大的天灾部队！"
D.Strings[24850]="这只是第一批！最终，我们将横扫整个祖达克……"
D.Strings[24851]="快，$n。快使用传送门！"
D.Strings[24852]="我们是被巫妖王选中的死亡骑士，$n。身为天灾军团的一员，我们要坚定执行巫妖王的意志。"
D.Strings[24853]="我错过了通往阿彻鲁斯的传送门，奥尔巴兹。能再次开启传送门吗？"
D.Strings[24854]="%s指了指脚下的冰水。"
D.Strings[24855]="这些怪物杀死了我的父亲，绑架了我的妹妹。我要让他们付出代价！"
D.Strings[24856]="远古海滩的第2轮比赛将在1分钟后开始。"
D.Strings[24857]="第2轮比赛将在30秒后开始。备战！"
D.Strings[24858]="憎恶之物！"
D.Strings[24859]="食尸鬼的口水！"
D.Strings[24860]="荒芜水晶！"
D.Strings[24861]="死亡骑士，好好欣赏他们的痛苦吧！这样的场景足以让你们振奋起来！"
D.Strings[24862]="集中攻击弱者！"
D.Strings[24863]="一群待宰的羔羊……"
D.Strings[24864]="你注定要死在天灾军团手中！"
D.Strings[24865]="为什么还要垂死挣扎？投降吧！"
D.Strings[24866]="谁要看雷耶克的新头盔？"
D.Strings[24867]="我要看！"
D.Strings[24868]="我也想看！"
D.Strings[24869]="好吧，雷耶克让你们瞧瞧！"
D.Strings[24870]="啊，钢盔把雷耶克吃掉了！快跑啊！"
D.Strings[24871]="哦耶！连狗崽子们都害怕这头盔，肯定能把那些胆小的大舌头怪吓得屁滚尿流啊！"
D.Strings[24872]="在痛苦中煎熬吧！"
D.Strings[24873]="$n，感谢你给予我们的帮助。但是你拒绝参与我们的实验项目，着实令我感到遗憾。"
D.Strings[24874]="普特雷斯大人，是蝙蝠骑士！"
D.Strings[24875]="他一定带来了前线的消息。"
D.Strings[24876]="感觉到自己的变化了吧！"
D.Strings[24877]="没有时间了！所有残余部队立刻向入侵者发动攻击！"
D.Strings[24878]="大门已经被攻破了！快，派兵去挡住那些入侵者！"
D.Strings[24879]="欢迎你，旅行者。"
D.Strings[24880]="我要去圣光据点。"
D.Strings[24881]="$n，感谢你在危急关头伸出援手。当你面对黑暗时，愿圣光赐予你速度与力量。"
D.Strings[24882]="尊贵的圣骑士，请你过来……"
D.Strings[24883]="是，主教大人。"
D.Strings[24884]="防御者们很快就能获得另一件古器，我要你将这个消息传播开来。"
D.Strings[24885]="当心天灾军团的袭击。"
D.Strings[24886]="欢迎来到我的厨房！我们在这里为达拉然的居民烹制最美味的食物。"
D.Strings[24887]="我是来学习烹饪的。"
D.Strings[24888]="你好啊，朋友。"
D.Strings[24889]="希望你好好地教训一下大舌头怪。他们该滚蛋了！"
D.Strings[24890]="灵鳍湾的战斗仍在继续。$B$B你能抽空去那里帮帮忙吗？"
D.Strings[24891]="你好，$c！暴风城港口的景色别具风格。从空中俯瞰的效果更佳。你要鸟瞰一下整座港口吗？"
D.Strings[24892]="我要绕暴风城港口游览一圈。"
D.Strings[24893]="凭你的智慧，恐怕无法掌握传送魔法的奥秘。$B$B但是你可以使用我身后的水晶，它能将你传送到达拉然下方，位于晶歌森林的废墟。"
D.Strings[24894]="身为一名法师，你拥有开启传送门，将自己传送回这里的能力。如果你愿意的话，我可以将传送法术传送给你。$B$B你也可以使用我身后的水晶，传送到达拉然下方的晶歌森林。"
D.Strings[24895]="你有空吗？索乌尼可以教你好听的曲子！"
D.Strings[24896]="我要传送到达拉然。"
D.Strings[24897]="朋友，欢迎来到我的理发店！你是想理发？还是染发啊？要不试试别的项目？$B$B我们提供各种修面、打洞、绘制暗夜精灵纹身等服务，甚至能为德莱尼人修整犄角和卷须！$B$B请坐吧，我们这就为你服务！只要花上几个子儿，你就能变得魅力四射……"
D.Strings[24898]="朋友，欢迎来到我的理发店！你是想理发？还是染发啊？要不试试别的项目？$B$B我们提供各种修面、打洞、獠牙和犄角整形等服务，甚至能为亡灵整容！$B$B请坐吧，我们这就为你服务！只要花上几个子儿，你就能变得魅力四射……"
D.Strings[24899]="来喝一杯！"
D.Strings[24900]="我是来买那种有名的烈酒的。还有存货吗？"
D.Strings[24901]="不管是谁告诉你我这里还有存货，请你务必替我保密。我可没法满足整座营地的需求。"
D.Strings[24902]="一切都结束了！"
D.Strings[24903]="血色领地的沦陷将成为一个血淋淋的教训！"
D.Strings[24904]="你们无路可逃……"
D.Strings[24905]="彻底摧毁这里，给那些胆敢反抗天灾军团的人留下一个教训！"
D.Strings[24906]="就凭你们，也想将亡灵逐出这片土地？见识天灾军团真正的力量，绝望吧！"
D.Strings[24907]="很快，你就会成为天灾军团的一员。"
D.Strings[24908]="十字军，你们所信仰的圣光在哪儿呢？"
D.Strings[24909]="圣光根本就不存在。只有黑暗长存！"
D.Strings[24910]="来呀，十字军。接受改造吧！"
D.Strings[24911]="我的孩子，尽情地享受吧！"
D.Strings[24912]="只剩1个离心构造体了。我们必须摧毁它们，才能破除瓦尔洛斯·云击的护盾。你可以在位于魔环中层的加速之环找到那些构造体。"
D.Strings[24913]="破除护盾，削弱瓦尔洛斯的防御力量！击败他，碧蓝魔环卫士就会消失，这样我们就能继续往上层前进了。前往位于魔环中层的加速之环，在浮动平台上找到瓦尔洛斯。"
D.Strings[24914]="下一个目标是法师领主伊洛姆。前往靠近魔环顶层的转化之环，在浮动平台上找到伊洛姆。他正在引导蓝色的魔枢能量旋。当心，这位强大的咒术师能召唤仆从帮他作战。"
D.Strings[24915]="只要除掉魔网守护者埃雷苟斯，我们就能控制魔环。他就在位于魔环顶层的校准之环上方盘旋。埃雷苟斯拥有难以想象的力量。开战之后你待在我背上吧，让我来对付他。"
D.Strings[24916]="我们终于从玛里苟斯手中夺得了魔环的控制权。小家伙，你还不能松懈。我渴望在广阔的天空舒展双翼。"
D.Strings[24917]="你或许也可以为我效劳。"
D.Strings[24918]="行了，别再估计什么形势不形势的了，蠢货！赶紧给我加入战斗！"
D.Strings[24919]="斯卡瓦尔德，你这无能的废物！滚回来，让我把你变得更有用一点！"
D.Strings[24920]="再……见……"
D.Strings[24921]="真是……无上的……荣耀。"
D.Strings[24922]="达尔隆！你有没有勇气和我一起上啊！"
D.Strings[24923]="呸！通灵师岂有死了就放弃的道理？你这没用的东西！"
D.Strings[24924]="没……完……呢。"
D.Strings[24925]="一个战士的……死。"
D.Strings[24926]="瓦尔洛斯·云击和魔环卫士守护着第二环。你召唤的幼龙足以对付魔环卫士，但是瓦尔洛斯利用魔环自身的能量，撑起了一面难以穿透的护盾。10个离心构造体不断地为护盾提供能量，它们就分布在我们头顶的环面和平台上。只有摧毁它们，才有可能伤害到瓦尔洛斯。"
D.Strings[24927]="接下来我们该怎么办？"
D.Strings[24928]="前往复仇港的飞艇已经抵达！要去嚎风峡湾的旅客请登机！"
D.Strings[24929]="位于风暴峭壁的岩石大厅已开放测试，该地下城适合77至79级的玩家。请组满队伍后再传送至岩石大厅。该地下城的集合石尚未开放。\n\n穿过地下城内的常规出口，即可离开岩石大厅并返回这里。如果角色死亡并选择释放灵魂，请从该NPC处传送回去。"
D.Strings[24930]="我已经组满队伍，准备前往岩石大厅！"
D.Strings[24931]="将我送回岩石大厅！"
D.Strings[24932]="我……我不知道。"
D.Strings[24933]="我说，莫度鲁，你从哪儿弄到这件……呃……“漂亮”的长袍的啊？"
D.Strings[24934]="噢。噢……原来如此。不错呀！"
D.Strings[24935]="%s强忍着笑。"
D.Strings[24936]="前往战歌要塞的飞艇已经抵达！要去北风苔原的旅客请登机！"
D.Strings[24937]="%s完全没有意识到她在嘲笑自己，竟然露出了笑容，用带有重口音的通用语回答了她的问题。"
D.Strings[24938]="哈！这是我的祖母送给我的礼物呀。这件长袍是她用德拉诺最上等的丝绸亲手缝制的！穿上它令我倍感自豪呢！"
D.Strings[24939]="%s窃笑着，用鼻子摩挲着哨兵琪珊·清泉的脚踝。"
D.Strings[24940]="%s朝哨兵琪珊·清泉发出呼噜声。"
D.Strings[24941]="%s冲营地那头的哨兵蓝塔娜·琥珀咧嘴一笑，意味深长地挑动着她长长的眉毛。"
D.Strings[24942]="压……扁……你……"
D.Strings[24943]="%s嗤了一声，狠狠地瞪了瞪哨兵琪珊·清泉，然后将头扭向一旁。"
D.Strings[24944]="哈……哈……哈……"
D.Strings[24945]="打……碎……你……"
D.Strings[24946]="警告：生命体形态模式无法辨识。文档处理程序中断。继续干涉程序将导致安全对策启动。"
D.Strings[24947]="你回来做什么？立即返回斯坦索姆！$B$B要我把你传送过去吗？"
D.Strings[24948]="你不该来这里……现在你就要死了！"
D.Strings[24949]="为什么会这样呢？"
D.Strings[24950]="是你逼我这么做的！"
D.Strings[24951]="我心中的负担更加沉重了……"
D.Strings[24952]="都是你的错！"
D.Strings[24953]="失去了这么多时间……你们永远也无法挽回！"
D.Strings[24954]="正在重新评估威胁指数。"
D.Strings[24955]="生命体已被净化。"
D.Strings[24956]="我诅咒你们烂在这里！我……不想要这个结局……"
D.Strings[24957]="安全系统发现不明入侵。历史文档的分析工作优先级转为低。对策程序立即启动。"
D.Strings[24958]="已超出威胁指数标准。天界文档中断。提高安全级别。"
D.Strings[24959]="威胁指数过高。虚空分析程序关闭。启动清理协议。"
D.Strings[24960]="找出那些携带了病毒的谷物箱，对它们使用奥术干扰器！$B$B这样阿尔萨斯就有充分的证据对斯坦索姆动手了。"
D.Strings[24961]="警告：安全系统自动修复装置已被关闭。立刻消除全部存储器内容并……"
D.Strings[24962]="系统已上线。生命形态模式已确认。您好，铜须先生。是否需要问询？"
D.Strings[24963]="你还待在这里做什么？$B$B阿尔萨斯就在斯坦索姆的入口处，你应该跟紧他！快去！"
D.Strings[24964]="看看你们那软弱的躯壳和短暂的生命。你们永远也无法逃避血肉的诅咒！"
D.Strings[24965]="血肉永远无法胜过钢铁！"
D.Strings[24966]="钢铁的大军将令整个世界窒息！"
D.Strings[24967]="洛肯是不会放弃的……他一定会夺回熔炉！你们……什么也无法改变！"
D.Strings[24968]="主人要我告诉你……"
D.Strings[24969]="%s寻求帮助！"
D.Strings[24970]="欢迎你。"
D.Strings[24971]="欢迎踏入冰冷的死亡之域。"
D.Strings[24972]="黑暗在等着你呢。"
D.Strings[24973]="我将……融入这黑夜。"
D.Strings[24974]="你们知道好奇心过剩的下场吧……"
D.Strings[24975]="我要让你们尝尝无所适从的滋味！"
D.Strings[24976]="这里有我千万个分身。"
D.Strings[24977]="现在，最后一步！"
D.Strings[24978]="这该死的……运气。"
D.Strings[24979]="混沌已降临。"
D.Strings[24980]="%s的灵魂与宿主分离时，发出了痛苦的嚎叫声。"
D.Strings[24981]="谜底将揭示。"
D.Strings[24982]="不灭而不朽。"
D.Strings[24983]="必然的终结。"
D.Strings[24984]="不……！"
D.Strings[24985]="萨隆亚已经预见了一切！凡人的徒劳努力根本无法毁灭永恒的王朝！"
D.Strings[24986]="正如萨隆亚所料！"
D.Strings[24987]="正如预言所说！"
D.Strings[24988]="你的血肉现在要为萨隆亚效劳了！"
D.Strings[24989]="你的躯壳对萨隆亚还有些用处！"
D.Strings[24990]="不，这感觉……太短暂了！"
D.Strings[24991]="啊啊啊！我还要这种感觉！"
D.Strings[24992]="不……不可能！萨隆亚是不朽的！萨隆亚是……"
D.Strings[24993]="留下。好好享受你们的最后时光吧。"
D.Strings[24994]="了断吧！来个了断吧！杀了我，否则我以女王陛下之名发誓，你们绝对看不见明天的太阳！"
D.Strings[24995]="现在我们终于接近真理了！"
D.Strings[24996]="女王陛下……生命的缚誓者……请保护……我。"
D.Strings[24997]="这是怎么回事？Mok-thorin ka！杀了他们！"
D.Strings[24998]="我们的工作还没完成呢！"
D.Strings[24999]="我要如何训练宠物？"
D.Strings[25000]="与猎人一样，宠物也可选择天赋专精。狂野宠物，例如猫科动物。它们拥有可观的输出伤害，承受伤害的能力却偏弱。坚韧宠物，例如海龟。它们拥有多种防御技能，能吸引敌人的火力，便于你进行远程输出。狡诈宠物，例如蜘蛛。它们同时拥有攻击和防御技能，在战场和竞技场的作用显得尤为突出。$B$B每种宠物都自带一种默认天赋，但你可以根据自己的喜好加以更改。"
D.Strings[25001]="什么？我这是在哪？别傻站着了，杀了他们！"
D.Strings[25002]="这才像话！"
D.Strings[25003]="你们……不过如……此……"
D.Strings[25004]="你确定要这样做吗？$B$B一旦我抹去你已经学会的天赋，就不能反悔啦。"
D.Strings[25005]="嗯。请让我遗忘天赋。"
D.Strings[25006]="好吧。遗忘完毕。"
D.Strings[25007]="我们需要更多的尸体！"
D.Strings[25008]="大领主需要更多的憎恶！"
D.Strings[25009]="蠢货，加快速度！"
D.Strings[25010]="天灾军团的阴影将吞噬整个银色黎明！"
D.Strings[25011]="站起来吧！到天灾军团的前线去战斗吧！"
D.Strings[25012]="再加把劲儿！总攻就要开始了！"
D.Strings[25013]="对！就是这样！更多的灵魂！"
D.Strings[25014]="会……会痛吗？"
D.Strings[25015]="有点刺痛……"
D.Strings[25016]="我现在改变注意的话，还来得及吗？要不你直接杀了我吧？"
D.Strings[25017]="你这怪物！"
D.Strings[25018]="求你饶命！我……"
D.Strings[25019]="天哪！天哪！！"
D.Strings[25020]="嗯。强烈的痛感可能会令你昏迷，因此你最好待在这只装满软泥怪的大桶里！"
D.Strings[25021]="生效了，等着瞧吧。"
D.Strings[25022]="我本来就会杀死你啊。着什么急呢？"
D.Strings[25023]="谄媚对你没有好处。"
D.Strings[25024]="别可笑啦。就算我饶了你，你又能去哪里呢？我们已经灭绝了你们的文明。你忘了吗？"
D.Strings[25025]="后退！"
D.Strings[25026]="别打了！听我说！"
D.Strings[25027]="尖叫吧，人类。我喜欢这美妙的乐曲。"
D.Strings[25028]="安静！听扎特森说，我可是狂心氏族最厉害的拳击手！"
D.Strings[25029]="拉卡特，你这蠢货。如果你再用鼻子嗅猎物的行踪，那你的鼻子就废了。你没有了鼻子，还怎么闻气味呢。闻不到气味，我看你还怎么打猎，你就成废物了！"
D.Strings[25030]="阿亚克，别像块石头似的矗在那儿啊。拉卡特就比你活跃。跑动起来啊，不然你就会被巨蜂蛰到，要不就是被钢刺野猪的獠牙戳伤。跑动起来！"
D.Strings[25031]="快。加快攻击速度啊！你们俩慢得跟大舌头怪似的。我应该将你们丢进河里，让你们全身裹满泥巴，这样大舌头怪就能收留你们了。"
D.Strings[25032]="保护好腹部啊，不然会被开膛破肚的！你要将注意力放在对方的上半身，别老盯着下面啊。"
D.Strings[25033]="很好。再打一次。别再犯傻了。"
D.Strings[25034]="来吧，让我瞧瞧你都学了些什么。"
D.Strings[25035]="如果你使用冰冷触摸降低它的施法速度，那么咒语的威胁性就会降低很多……"
D.Strings[25036]="别让它轻易地放出下一个法术……冻结它的思维。"
D.Strings[25037]="让我瞧瞧你都学到了什么。来吧。"
D.Strings[25038]="不要因为血液被冻结就放慢了攻击速度。来吧，鼓起勇气。"
D.Strings[25039]="别老站着不动。上前一步吧。"
D.Strings[25040]="让我瞧瞧你有没有掌握我交给你的诀窍。"
D.Strings[25041]="准备接受挑战吧。好好利用我教给你的诀窍。"
D.Strings[25042]="我要征服你们的灵魂！"
D.Strings[25043]="你还没有落败……利用饥饿之寒阻止这次攻击！"
D.Strings[25044]="它们被冻僵了，正是下手的好机会。利用凛风冲击将它们撕成碎片吧！"
D.Strings[25045]="妄图挑战巫妖王的力量？你太愚蠢了！"
D.Strings[25046]="陛下，我已执行了您的意志！"
D.Strings[25047]="让我再为主人奉上一个灵魂吧！"
D.Strings[25048]="你的死亡临近了……"
D.Strings[25049]="你的灵魂可以去主人那里了！"
D.Strings[25050]="你的末日已经不可避免。"
D.Strings[25051]="还有什么遗言吗？"
D.Strings[25052]="不！我历尽千辛万苦，不是为了……"
D.Strings[25053]="尊敬的陛下！我已经完成您的全部要求，希望您能不吝赐下伟大的祝福！"
D.Strings[25054]="我不会忘记你为萨萨里安所做的一切。不胜感激。"
D.Strings[25055]="这感觉……真是超乎想象。我将永远听命于您，陛下。"
D.Strings[25056]="能以您的名义杀死这些蝼蚁令我十分荣幸，来吧，天灾军团的敌人们！我让你们看看巫妖王的真正力量！"
D.Strings[25057]="这次献祭只是对你恭顺与服从的考验。现在你已证明自己确实可以胜任我的嘱托。平身吧，席瓦拉·索格蕾！"
D.Strings[25058]="你的第一个试炼正在等待着你。消灭那些不速之客。"
D.Strings[25059]="就在这里，我放弃了一切，只为换取父亲的自由。如今，我要亲手摧毁它……"
D.Strings[25060]="大领主，我准备好了。向圣光之愿礼拜堂发起进攻吧！"
D.Strings[25061]="我的父亲曾经说过，生命本身毫无意义……只有死亡，才能让你了解人性的真谛。圣光之愿礼拜堂的沦陷将完美地诠释他这番话的含义。$n，我们很快就要进攻了。做好准备吧。"
D.Strings[25062]="阿彻鲁斯的死亡骑士，聆听主人的召唤吧！向圣光之愿礼拜堂发动攻击！我们在布洛米尔汇合！"
D.Strings[25063]="天灾军团的士兵们，做好准备！你们马上就可以向银色黎明倾泻怒火了！"
D.Strings[25064]="让我们瞧瞧来自暗影界的残暴怪物……"
D.Strings[25065]="大地即将崩裂，天空也要为之哭泣！很快，艾泽拉斯那悲戚的血泪就会降下！"
D.Strings[25066]="阿彻鲁斯的死亡骑士们，死亡的远征现在开始！"
D.Strings[25067]="天灾军团的士兵们，阿彻鲁斯的死亡骑士们，黑暗的仆从们：听从大领主的召唤！"
D.Strings[25068]="德鲁伊！真奇怪……阴影世界中怎么会有德鲁伊的精神投影呢？"
D.Strings[25069]="食尸鬼？这里的食尸鬼已经够多的了。"
D.Strings[25070]="谁打扰了我的梦境？"
D.Strings[25071]="比格沃斯先生。这只猫是纳克萨玛斯中唯一有生命的物体，据说它是克尔苏加德与生者世界的最后一丝联系。谣传胆敢碰它一根毛发的人都难逃……等等，它在做什么？！"
D.Strings[25072]="%s敲了敲显示屏。"
D.Strings[25073]="呃，别理它。我相信没有人敢伤害克尔苏加德最宝贝的宠物。"
D.Strings[25074]="快！对乌索克的尸体使用灰烬。我们必须净化它！"
D.Strings[25075]="Shur'nab……shur'nab……尤格-萨隆！"
D.Strings[25076]="天空变得血红！巫妖王在注视着我们。前进！苏醒的你们将带来毁灭，身后只留下灰烬和痛苦。"
D.Strings[25077]="兄弟姐妹们，坚持住！圣光必胜！"
D.Strings[25078]="天灾军团来了！"
D.Strings[25079]="奴仆们，站起来吧！摧毁他们！"
D.Strings[25080]="臣服于大领主的力量吧！"
D.Strings[25081]="你没有任何机会！"
D.Strings[25082]="天灾军团将要毁灭这里！"
D.Strings[25083]="没有痛苦，生命就毫无意义！"
D.Strings[25084]="你们的部队还能坚持多久呢？"
D.Strings[25085]="银色黎明完蛋了！"
D.Strings[25086]="不留活口！"
D.Strings[25087]="这是什么？！我的……我不能攻击了……"
D.Strings[25088]="服从我，灰烬使者！"
D.Strings[25089]="遵照我的意愿！我是你的主人！"
D.Strings[25090]="我……我竟不能……这把剑背叛了我……"
D.Strings[25091]="力量……消失了……"
D.Strings[25092]="灰烬使者正在抗拒我……"
D.Strings[25093]="仆从们，快来帮我！"
D.Strings[25094]="你赢不了的，达里安！"
D.Strings[25095]="你难道还不明白吗，孩子？你已经沦为了你父亲毕生都在对抗的存在！你已经和阿尔萨斯那个懦夫一样，甘心堕入黑暗……堕入仇恨……以害人为生！"
D.Strings[25096]="你的主子知道礼拜堂下面埋藏着什么。所以他才不敢露面！你和你的死亡骑士就是他派来送死的，达里安。"
D.Strings[25097]="你现在感受到的，是上千个迷失灵魂的痛苦！他们都是牺牲在你和你的主人剑下的英灵！圣光会把你撕碎的，达里安！"
D.Strings[25098]="我的力量正在减弱，大领主！"
D.Strings[25099]="怎么回事？这是什么？"
D.Strings[25100]="圣光正在吞噬我们！"
D.Strings[25101]="兵力骤减，部队即将崩溃！"
D.Strings[25102]="大领主，我们该怎么办？"
D.Strings[25103]="没法……集中精神……"
D.Strings[25104]="势不可挡……难以抵抗……"
D.Strings[25105]="快……快死了……"
D.Strings[25106]="带到礼拜堂前！"
D.Strings[25107]="蠢货！你让我们落入了圈套！我可不想死在这里，莫格莱尼！"
D.Strings[25108]="%s逃跑了。"
D.Strings[25109]="%s被提里奥·弗丁击败，跪倒在地。"
D.Strings[25110]="死亡骑士们，撤退。我们战败了……这里的……圣光之力…………我们输定了……"
D.Strings[25111]="省点力气吧，老家伙。这将是你的最后一口气息了。"
D.Strings[25112]="我的儿子！最让我自豪的孩子！"
D.Strings[25113]="灰烬使者！"
D.Strings[25114]="不……不可能……"
D.Strings[25115]="低下你们的头！"
D.Strings[25116]="父亲！"
D.Strings[25117]="啊……这……这是……"
D.Strings[25118]="父亲，您回来了！"
D.Strings[25119]="您去了好久啊，父亲。我还以为……"
D.Strings[25120]="%s拥抱了他的父亲。"
D.Strings[25121]="没有什么能够阻止我回家，达里安。我绝不会离开自己的家乡和亲人。"
D.Strings[25122]="父亲，我也想加入部队，和您一起抵抗亡灵。我也要战斗，不能再袖手旁观了！"
D.Strings[25123]="达里安·莫格莱尼，你还没有到可以握剑的年龄呢，更不用说去跟肆虐洛丹伦的亡灵作战了！我不能失去你，想都不敢想……"
D.Strings[25124]="父亲，就算死，我也要在和亡灵军团的战斗中光荣地战死！就算死，我也要和您死在一起！"
D.Strings[25125]="我的儿子啊，你总有一天会举起灰烬使者，凭借它的力量在这片土地上匡扶正义。我坚信，当那一天终于到来的时候，你会为我们的人民带来荣光，洛丹伦将因你而变得更加美好。但，我的孩子，不是今天。"
D.Strings[25126]="不要忘记……"
D.Strings[25127]="真感人……"
D.Strings[25128]="他现在归我了……"
D.Strings[25129]="你……背叛了我。你背叛了我们所有人，怪物！感受莫格莱尼的力量吧。"
D.Strings[25130]="阿尔萨斯，你这该死的怪物！"
D.Strings[25131]="你说对了，弗丁。我就是派他们去送死的。他们的生命毫无意义，但你的不同……"
D.Strings[25132]="把伟大的提里奥·弗丁揪出来还真是容易啊。你已经暴露了，圣骑士。谁也救不了你了……"
D.Strings[25133]="永远……记住……"
D.Strings[25134]="来自暗影界的居民，请在我们面前现身吧。"
D.Strings[25135]="欢迎来自暗影界的另一位居民……"
D.Strings[25136]="让我们瞧瞧接下来是什么野兽……"
D.Strings[25137]="你们对阴影世界的了解还远远不够……"
D.Strings[25138]="骷髅。即便是骨头架子这样的玩物，我们也能从中学到新的知识。"
D.Strings[25139]="骷髅法师。这是展示某些技能的绝好机会。"
D.Strings[25140]="奇怪，我还以为它们在阴影世界已经绝迹了呢。当心点，它不容易对付的。"
D.Strings[25141]="不过正好……看清楚，这就是我们的敌人，这就是死亡骑士的敌人。我们是孤独的死亡骑士，我们必须战斗。"
D.Strings[25142]="我们能够使用暗影的能量封印住这些治疗者的能力。"
D.Strings[25143]="暗影的能量会反噬他们的能力，就这样将这个投影赶回翡翠梦境里去。"
D.Strings[25144]="提里奥！"
D.Strings[25145]="阿尔萨斯！！！"
D.Strings[25146]="锻造手艺也太差劲了吧。连食尸鬼都不屑使用这件武器。"
D.Strings[25147]="你管这玩意儿叫武器？再让我看见这样的货色，我就把你扔进锅炉和金属锭一块儿熔了。或许那时你才会明白该如何努力。"
D.Strings[25148]="如果银色黎明的武器都是这种品质的话，那他们迟早会完蛋。"
D.Strings[25149]="餐叉都比这玩意儿坚硬。重新铸造！"
D.Strings[25150]="你是不是没搞清楚？这把武器是用来捅人的，不是挠痒痒的！重新打磨！"
D.Strings[25151]="你就算变成亡灵，也没那个能耐为巫妖王效力。手脚再勤快点，我或许会考虑让你彻底摆脱这个世界。否则，你就等着进熔炉吧。"
D.Strings[25152]="终于……回家了……"
D.Strings[25153]="我……回来了……主人……"
D.Strings[25154]="我回来了……主人。我是您……忠实的仆从。"
D.Strings[25155]="对不起……主人……我离开了……这么久。"
D.Strings[25156]="食尸鬼的问题在于，他们很快就会丧失利用价值。让我们用死亡和腐烂解决他们吧。"
D.Strings[25157]="有时候，食尸鬼的尸体比他们本身更有用。"
D.Strings[25158]="真是不幸。"
D.Strings[25159]="痛……"
D.Strings[25160]="我……不好？"
D.Strings[25161]="主人？"
D.Strings[25162]="%s击碎了脆弱的魔像！"
D.Strings[25163]="但，不是今天……"
D.Strings[25164]="还……没有完呢！"
D.Strings[25165]="下一次，我们就不会在这片圣地上决战了，圣骑士。"
D.Strings[25166]="和我相比，你们施放的法术还不够强大，但是在密集的魔法攻击下，反魔法护罩依然能起到完美的保护作用。"
D.Strings[25167]="你们可以利用护罩吸收的法术能量展开反击。"
D.Strings[25168]="法师害怕我们……这是有原因的。你们要学会利用这种恐惧。"
D.Strings[25169]="我的迷惑项圈不见了！"
D.Strings[25170]="%s切换到战斗姿态！"
D.Strings[25171]="%s切换到狂暴姿态！"
D.Strings[25172]="%s切换到防御姿态！"
D.Strings[25173]="站起来，达里安，你听着……"
D.Strings[25174]="别害怕……接受死亡的冰冷拥抱吧……"
D.Strings[25175]="这就是失败的代价。"
D.Strings[25176]="懦弱的后果就是死亡。"
D.Strings[25177]="你的记性太差劲了。"
D.Strings[25178]="要学习的知识还有很多。继续努力吧。"
D.Strings[25179]="你掌握得不错。继续努力吧。"
D.Strings[25180]="我们见证了一场可怕的悲剧。善良人的鲜血早已将这整片土地染红！无数高贵而英勇的骑士，为了保卫我们而牺牲在这里！"
D.Strings[25181]="这是一个好的开始。继续努力吧。"
D.Strings[25182]="我们永远不会忘记这一幕，我们仍然需要保持警惕！"
D.Strings[25183]="巫妖王必须为他的所作所为付出代价，我们绝不能再让他继续破坏这个世界。"
D.Strings[25184]="兄弟们，姐妹们，我向你们发誓：巫妖王一定会被消灭！今天，我们大家要重新团结起来。"
D.Strings[25185]="银色黎明和白银之手骑士团将在此合二为一！我们一定可以完成前人未尽的事业！"
D.Strings[25186]="我们要继续抗争阿尔萨斯，我们终将推倒冰冠冰川的城墙！"
D.Strings[25187]="阿尔萨斯，银色北伐军向你宣战！"
D.Strings[25188]="这也是黑锋骑士们的心愿……尽管在你们的世界中已没有立足之地，但我们仍要为打倒巫妖王而战斗。我在此立誓！"
D.Strings[25189]="%s沿着隧道爬了过来！"
D.Strings[25190]="给，$n。$b$b麻烦你集中精神，完成任务……"
D.Strings[25191]="食尸鬼！过来！"
D.Strings[25192]="吃吧，我们的敌人会很高兴的。"
D.Strings[25193]="%s将一根雷管放在地上。"
D.Strings[25194]="你这个狡猾的家伙！我该怎么对付你呢？"
D.Strings[25195]="哎呀，谢谢你。有时候，小恩小惠远胜于数小时的巫术研究。"
D.Strings[25196]="%s连忙走过来。"
D.Strings[25197]="%s将雷管吞了下去。"
D.Strings[25198]="我们的库房已经空了。在补给物资送来之前，我没东西可卖。"
D.Strings[25199]="谢谢你送来了一些补给物资，这样我又能拿起厨具啦。我能为你做什么呢？"
D.Strings[25200]="$n好像晕过去了。我们该怎么办呢，提里奥？"
D.Strings[25201]="%s开始施放闪电新星！"
D.Strings[25202]="保持警惕，$r。$b$b生命在这里显得尤其脆弱！"
D.Strings[25203]="作为鲜血学徒，你们必须懂得如何掌控敌人的生命。"
D.Strings[25204]="借助武器或咒术，鲜血能提高我们的攻击力，同时削弱敌人的力量。"
D.Strings[25205]="真正的大师能利用鲜血在战斗中爆发出超越自身的强大力量。"
D.Strings[25206]="无论对手是一息尚存还是已然毙命，我们都能汲取他们的能量，以此获得远胜于低等生物的生存力。"
D.Strings[25207]="敌人倒下后，我们能窃取并利用他们残余的所有能量继续展开攻击。"
D.Strings[25208]="对鲜血大师来说，战斗是永无止境的……"
D.Strings[25209]="我们渴望着鲜血的洗礼……"
D.Strings[25210]="我们拥有敌人永远无法战胜的力量……"
D.Strings[25211]="鲜血大师掌控着生命与死亡。胆敢与我们为敌的家伙，会被抽干所有的能量，沦为毫无生气的死尸。"
D.Strings[25212]="返回战场，否则我就将你摔下去！"
D.Strings[25213]="飞船又不是因为我才坠毁的，为什么大家都朝我瞪眼？"
D.Strings[25214]="我们总算找到零件，可以修理诺莫瑞根之魂了。"
D.Strings[25215]="让我瞧瞧，拧一拧，再调整一下……"
D.Strings[25216]="你看，诺莫瑞根之魂！修好啦！"
D.Strings[25217]="你可以开着她去兜风，不过万一你在座椅上发现了刀片，可别来跟我抱怨。你要知道，我好不容易才凑齐了零件修理她，就别那么讲究啦。"
D.Strings[25218]="你好，朋友！我在车间里设立了店面。我很乐意为你组装一辆亮闪闪的载具啊——我甚至可以在攻击结束后再将帐单寄给你的头儿。这可是相当划算的买卖呀！"
D.Strings[25219]="我要一辆攻城车。"
D.Strings[25220]="你好，朋友！我倒是很乐意为你组装一辆攻城车，但是我手头的零件用光啦。"
D.Strings[25221]="这是背叛！你将为这场骗局付出生命的代价！"
D.Strings[25222]="支配节杖散发着明亮的光芒！快使用它！"
D.Strings[25223]="一名地穴卫士加入了战斗！"
D.Strings[25224]="避开与血色十字军的正面火力冲突，不要被他们的箭和标枪伤到！"
D.Strings[25225]="吞噬血色十字军，补充你的能量！"
D.Strings[25226]="但愿琼斯没事。"
D.Strings[25227]="如果琼斯肯听我的，他或许会活得久一点。"
D.Strings[25228]="这个琼斯……"
D.Strings[25229]="他不是蠢蛋，是疯子！整天就想着追求财富与荣耀……"
D.Strings[25230]="以前，我和琼斯总是一起外出探险……"
D.Strings[25231]="他上哪儿，我就上哪儿。我一直跟着他，可这次他却叫我留下来。"
D.Strings[25232]="但愿琼斯能平安回来。"
D.Strings[25233]="上次玩牌，琼斯还欠我一笔赌债呢。这家伙居然想抽我老千！他这骗子，胃口比我个子还大！"
D.Strings[25234]="天哪……我居然还记得这些往事，真不敢相信……"
D.Strings[25235]="……于是他将土豆都扔掉了，我分明让他留下来的。"
D.Strings[25236]="%s深深地吸了一口气，挺起胸膛。"
D.Strings[25237]="%s朝远处眺望，显得十分烦躁。"
D.Strings[25238]="%s忍不住笑了起来。他的笑声一次次地打断了自己的话语。"
D.Strings[25239]="嗯……你有点面熟……让我想想……$B$B哈哈！西部荒野！我在西部荒野见过你。你是$n！咱们又见面啦，希望你能再次伸出援手。$B$B这里离西部荒野非常遥远，但是如果我们打不赢这一战，恐怕就要无家可归了。"
D.Strings[25240]="$n！你换了新衣服，差点认不出你啦。你还留着那件外套吗……或者你选了马裤……还是法杖？我不记得了，那已经是很久之前的事情了吧……$B$B嗯，很高兴你能来这里帮忙。我们需要一切可以动用的力量。$n，如果你的表现能像在西部荒野帮助人民军时一样好，那我们就有希望了。$B$B眼前的局势非常严峻，赢不了这一战，我们就休想回到西部荒野了。"
D.Strings[25241]="$n，有了圣光的祝福和你的帮助，迪菲亚已经不再构成威胁。$B$B但是我们距离西部荒野非常遥远，而且如果我们打不赢这一战，恐怕就要无家可归了。"
D.Strings[25242]="祝你狩猎愉快，$c！"
D.Strings[25243]="祝你好运，$r！"
D.Strings[25244]="保持警惕，$r！"
D.Strings[25245]="$c顺利抵达啦！"
D.Strings[25246]="$c已经安然着陆！"
D.Strings[25247]="蠢货！你本来可以获得强大的力量！"
D.Strings[25248]="怎么可能？巫妖王陛下说过，他已经为你规划好了未来……"
D.Strings[25249]="我就知道任何人都不能相信！"
D.Strings[25250]="你拒绝了远大的前程。现在，去死吧！"
D.Strings[25251]="而且，即使是你的背叛，也已经阻止不了我了。"
D.Strings[25252]="我用不着再依靠你了。没有你，我一样可以毁灭祖达克！"
D.Strings[25253]="你会为这场愚蠢的背叛而丢掉性命的！"
D.Strings[25254]="记住，$n，这不是短期的考验。对猎人而言，真正的考验是在长途跋涉中锻炼自己的耐性。"
D.Strings[25255]="联盟夺取了东部墓地！"
D.Strings[25256]="联盟夺取了西部墓地！"
D.Strings[25257]="联盟夺取了南部墓地！"
D.Strings[25258]="部落夺取了东部墓地！"
D.Strings[25259]="部落夺取了西部墓地！"
D.Strings[25260]="部落夺取了南部墓地！"
D.Strings[25261]="空气中有潜藏着的能量在涌动……丰收的时候到啦！"
D.Strings[25262]="乌格雷斯开始施放强大的黑暗力量！"
D.Strings[25263]="你把全家人都带来了吗！那么，你来这里做什么？"
D.Strings[25264]="找事儿做？这里是战场，你明白吗？你是干什么的？"
D.Strings[25265]="好吧。继续。"
D.Strings[25266]="女王陛下派来了黑暗游侠！退后！"
D.Strings[25267]="你们是我今天见到的最差劲的一批新兵！列队，向高级执行官安希尔姆报到！"
D.Strings[25268]="瞧瞧你们这蓬头垢面的模样！我还以为你们会比昨天那批新兵好一点呢。列队！去报到！"
D.Strings[25269]="把你们脸上的谷粒抹掉！要是让高级执行官看见你们这副模样，他会亲手宰了你们！"
D.Strings[25270]="一点都不好玩……"
D.Strings[25271]="新的玩具！"
D.Strings[25272]="真没意思……"
D.Strings[25273]="你怎么不动了呢？"
D.Strings[25274]="起来起来！我还没玩够呢！"
D.Strings[25275]="你们……只是让主人的计划更进一步……"
D.Strings[25276]="啊，娱乐节目要开始了！"
D.Strings[25277]="好玩的事才刚开始呢！"
D.Strings[25278]="啊！上等的材料！"
D.Strings[25279]="别担心，我会好好利用你的！"
D.Strings[25280]="去跟我的几位朋友打个招呼吧。"
D.Strings[25281]="来呀，斯坦索姆的市民们！来见见你们的“救世主”。"
D.Strings[25282]="砰！哈哈哈哈哈……"
D.Strings[25283]="鲜血……毁灭……真令人愉悦！"
D.Strings[25284]="我需要一份样本……"
D.Strings[25285]="如此强壮……我要了！"
D.Strings[25286]="你的血肉背叛了你。"
D.Strings[25287]="库尔格能为你做些什么呢？"
D.Strings[25288]="我准备好了。让我们保卫神庙吧！"
D.Strings[25289]="真不敢相信，蓝龙军团居然会攻击我们。我们要发动反击！"
D.Strings[25290]="从哪里着手呢？"
D.Strings[25291]="$n，久仰大名啊。这场战斗一定会非常有趣。"
D.Strings[25292]="我们是先攻打圣地呢，还是先对付敌军？"
D.Strings[25293]="我们一直在盼望着你，$n。现在我们总算占据了优势。"
D.Strings[25294]="你准备好作战了吗，$c？"
D.Strings[25295]="蠢货！你想唤醒那个可怕的造物，让它与我们的军队为敌吗？别想把源生石像带回诺森德！"
D.Strings[25296]="主人，就是这个无耻的凡人出卖了我们。我们一定要好好教训他！"
D.Strings[25297]="冲锋，否则就面对我的怒火！"
D.Strings[25298]="杀了他们！别找借口！没有怜悯！不留俘虏！"
D.Strings[25299]="烧毁每一座建筑物！杀光每一个人！"
D.Strings[25300]="我要把你们的血涂在脸上！"
D.Strings[25301]="我是天生的战士！"
D.Strings[25302]="我的生命……献给死神！"
D.Strings[25303]="我又回来了！又得到一次把你们脑壳敲碎的机会！"
D.Strings[25304]="不！不！我还可以……做得更好。"
D.Strings[25305]="因格瓦尔！你这可耻的失败将警示所有巫妖王的仆从！你被诅咒了！站起来，重新执行主人的意志！"
D.Strings[25306]="真有意思……这附近储存着高纯度的奥术能量。我要去探察一番……"
D.Strings[25307]="这是你应受的惩罚。值得庆幸的是，你会死得很痛快。"
D.Strings[25308]="至于你……"
D.Strings[25309]="出演了一次如此令人愉悦的背叛，你那卑微的生命，我就留给你作为奖赏吧。或许你身上还大有潜力呢。"
D.Strings[25310]="下次见面时，你的性命可就没法如此轻易地保住了！"
D.Strings[25311]="你令我失望了，达库鲁。"
D.Strings[25312]="太棒了！$n领悟了将永恒生命转化为永恒暗影的配方。"
D.Strings[25313]="太棒了！$n领悟了将永恒生命转化为永恒火焰的配方。"
D.Strings[25314]="但你记住……"
D.Strings[25315]="太棒了！$n领悟了将永恒火焰转化为永恒之水的配方。"
D.Strings[25316]="太棒了！$n领悟了将永恒火焰转化为永恒生命的配方。"
D.Strings[25317]="太棒了！$n领悟了将永恒空气转化为永恒之水的配方。"
D.Strings[25318]="太棒了！$n领悟了将永恒空气转化为永恒之土的配方。"
D.Strings[25319]="太棒了！$n领悟了将永恒暗影转化为永恒之土的配方。"
D.Strings[25320]="太棒了！$n领悟了将永恒暗影转化为永恒生命的配方。"
D.Strings[25321]="太棒了！$n领悟了将永恒之土转化为永恒空气的配方。"
D.Strings[25322]="太棒了！$n领悟了将永恒之土转化为永恒暗影的配方。"
D.Strings[25323]="太棒了！$n领悟了将永恒之水转化为永恒空气的配方。"
D.Strings[25324]="太棒了！$n领悟了将永恒之水转化为永恒火焰的配方。"
D.Strings[25325]="你拿的是什么玩意儿？"
D.Strings[25326]="这样的小玩具是救不了你的！"
D.Strings[25327]="圣光的力量也难以战胜巫妖王的强大！"
D.Strings[25328]="和你心爱的人说再见吧，$c……"
D.Strings[25329]="你的王国终将沦陷，$r！"
D.Strings[25330]="你们的城堡必将倒塌，而你挚爱的人也会沦为巫妖王的奴仆！"
D.Strings[25331]="你佩戴的圣物散发着臭味，真恶心……"
D.Strings[25332]="你干嘛不扔掉它……"
D.Strings[25333]="加入我们吧，$n。起誓效忠巫妖王。全心全意地侍奉他，就能享受永恒的宁静……享受你降生以来从未体验过的宁静。"
D.Strings[25334]="结局早已注定，何必再做徒劳的抗衡。艾泽拉斯世界……必将消亡。"
D.Strings[25335]="如果你打算反抗，那么在死之前，你会体验到无尽的痛苦与恐惧，并眼睁睁地看着你挚爱的人撒手而去。"
D.Strings[25336]="欢迎……"
D.Strings[25337]="啊，你在那儿……"
D.Strings[25338]="瞧。我发现你了……"
D.Strings[25339]="竞技场战斗将在60秒后结束。"
D.Strings[25340]="坚守你的信仰。元帅会带领我们战胜巫妖王的。"
D.Strings[25341]="接受圣光的祝福吧。"
D.Strings[25342]="不要动摇。我们很快就会沐浴在圣光中。"
D.Strings[25343]="我们中间混进了一些反叛份子，最好保持警惕。黑锋骑士团企图阻止我们消灭他们真正的主子——巫妖王。"
D.Strings[25344]="不要怀疑圣光所给予的指示。只有甘愿奉献一切的人才能感受到它的存在。"
D.Strings[25345]="巴利·韦斯温元帅有一项计划……这也是他多年的愿望。为了拯救世界，我们在执行这项计划的过程中必须保持坚定和虔诚的态度。"
D.Strings[25346]="虽然这里天寒地冻，但是沐浴在圣光中，我却倍感温暖。不要气馁。"
D.Strings[25347]="元帅有令，禁止进入岛屿南端，违者处死。把这个命令传下去。"
D.Strings[25348]="暴风城的危机尚未解除——有报告称城外飘来了一座浮空城，天灾兵进攻的事件也时有发生。"
D.Strings[25349]="尽管敌人的数量在不断减少，但是天灾军团的绞肉车源源不断地送来了新鲜的僵尸。"
D.Strings[25350]="最近一次在东瘟疫之地爆发的冲突中，双方都伤亡惨重。"
D.Strings[25351]="银色黎明在塔纳利斯的荒漠中赢得了决定性的胜利。"
D.Strings[25352]="圣光之愿礼拜堂是瘟疫之地仅存的据点。银色黎明必须在那里站稳脚跟，才能确保整个地区的安全。"
D.Strings[25353]="打起精神来！"
D.Strings[25354]="我相信，巫妖王会败在我们手下。我们的复仇大业一定会取得成功。$B$B但首先，我们必须将血色先锋军这个祸端彻底解决掉！"
D.Strings[25355]="高级指挥官，我要听你的故事。"
D.Strings[25356]="好吧，但如果我是你的话，我会集中精神仔细聆听，而不是盲目地点点头表示回应。$B$B和所有精彩的故事一样，这个故事也是以背叛开场的。不过，并非是别人背叛了我们……事情并非如此。在巫妖王的众多仆从中，他最看重的就是我们——死亡骑士。$B$B但是，在大领主达里安·莫格莱尼的帮助下，我们背叛了他。$B$B瘟疫之地圣光之愿礼拜堂的那场决战中，就在我们几乎全军覆没的紧要关头，提里奥·弗丁帮助莫格莱尼以及幸存的死亡骑士摆脱了巫妖王的束缚。"
D.Strings[25357]="<你微微地点了点头，高级指挥官顿时眯起了眼睛。于是你赶紧停止动作，他这才开口继续说起了故事。>"
D.Strings[25358]="放弃吧，老老实实地受死吧。"
D.Strings[25359]="弗丁举起了灰烬使者，巫妖王见势不妙，便迅速逃走了。于是，我们轻而易举地从残余的天灾兵手中夺取了黑锋要塞的控制权。$B$B但是我们与血色十字军的隔阂并没有消除。$B$B就像被遗忘者当初的境遇一样，血色十字军总是将我们与天灾军团混为一谈。$B$B我们拥有独立的思想和目标，我们拥有生者的一切特质。但是对他们来说，我们和巫妖王麾下那些没脑子的奴隶没什么两样。$B$B他们居然误认为我们会再次臣服于巫妖王的淫威。"
D.Strings[25360]="他们现在自称血色先锋军了吧？"
D.Strings[25361]="高级指挥官，能再讲一遍刚才的故事吗？"
D.Strings[25362]="<高级指挥官瞪了你一眼，继续说道。>$B$B我马上就会讲到了。没错，阿比迪斯将军率领部队抵达诺森德后，就将血色十字军更名为血色先锋军了。$B$B先锋军驻扎龙骨荒野的新壁炉谷后不久，海军上将巴利·韦斯温前来拜访。据说，阿比迪斯将军完全没有料到他会来。她更没有料到韦斯温上将动摇了她在军中的地位，并最终夺得了兵权。$B$B你一定要问，她怎么能心甘情愿地让位呢，但这已经不重要了。阿比迪斯将军死后，韦斯温也神秘失踪了，我们一直没有找到他。"
D.Strings[25363]="我要内脏！要鲜血！要食物！"
D.Strings[25364]="把你剁碎，再吃掉！"
D.Strings[25365]="好饿啊！必须吃饭！"
D.Strings[25366]="要爆炸啦！"
D.Strings[25367]="韦斯温元帅去哪儿了？"
D.Strings[25368]="我说过，我们失去了他的行踪，但我相信你能帮我们找到他。我怀疑他就躲在岛上，可是我派出的探子始终搜不到他的藏身之所。$B$B虽然怨毒镇的被遗忘者对新壁炉谷展开了一系列的攻击行动，但如今残余在那里的先锋军都是身经百战的强者。不幸的是，他们设法获得了更精良的装备，还从某些白痴手里弄到了狮鹫。$B$B我想说，$n，不管你有多厉害，这项任务绝非是去乡间散步那么简单。"
D.Strings[25369]="没问题。什么时候可以开始行动？"
D.Strings[25370]="我们很快就要展开行动了。$B$B但是我必须说明——我们不是来削弱他们的士气的，也不是来吸引敌人的火力的。我们的目标是，彻底消灭血色先锋军。$B$B如果你对此不感兴趣，就趁早滚远点。我需要的是每天都能来帮忙，直到使命达成的伙伴。$B$B你觉得自己能胜任吗，$n？"
D.Strings[25371]="来吧，消灭先锋军！"
D.Strings[25372]="<高级指挥官咧嘴一笑，从头到脚地打量了你一番。>$B$B这正是我想听的。"
D.Strings[25373]="王！我听不见你的声音！别扔下我！"
D.Strings[25374]="别走！"
D.Strings[25375]="我要吃……"
D.Strings[25376]="我在哪儿？好黑啊……"
D.Strings[25377]="抱定最后的希望吧，凡人！"
D.Strings[25378]="希望让灵魂变得甜蜜起来，巫妖王会喜欢你这道甜品的！"
D.Strings[25379]="求你！$n！杀了我吧！"
D.Strings[25380]="我的罪孽深重……"
D.Strings[25381]="……我杀死了挚爱的人……还吃掉了他们……"
D.Strings[25382]="结束这痛苦的折磨！"
D.Strings[25383]="发发慈悲吧，$n！让我安息！"
D.Strings[25384]="你……我在沙塔斯城见过你……"
D.Strings[25385]="王知道你。他想见你……"
D.Strings[25386]="献给王的鲜血与灵魂！"
D.Strings[25387]="我的眼中燃着烈火！头痛欲裂！"
D.Strings[25388]="活生生的血肉可以减轻痛苦……"
D.Strings[25389]="吃一点点就够了。一根手指或是一只耳朵就行……"
D.Strings[25390]="保持镇静，$n！"
D.Strings[25391]="%s的防御气泡破裂了！"
D.Strings[25392]="%s开始召唤！"
D.Strings[25393]="听说巫妖王在北方的冰冻废土兴风作浪。他建起了一座名叫冰冠堡垒的城堡，想要消灭我们。"
D.Strings[25394]="传说诺森德生活着可怕的巨人。他们的胡须像匕首一样锋利，冰冷的目光甚至能熄灭熊熊烈火。"
D.Strings[25395]="来自北方的寒风呼啸而过，冰冷刺骨。"
D.Strings[25396]="暴风城港口一片繁忙的景象。不知道那些新造的船只会开往哪儿去……"
D.Strings[25397]="听说牛头人的远亲住在诺森德。希望他们都是优秀的猎手……专门猎杀亡灵。"
D.Strings[25398]="要是血精灵也远征诺森德的话，那么我们一定能实现复仇大业！巫妖王肯定会为当初进攻银月城而后悔！"
D.Strings[25399]="多年来，血色十字军酿造的惨剧简直不尽其数。他们沦为了痛苦、狂热与谋杀的代名词。$B$B我不能再让这样的悲剧继续重演。你觉得呢？"
D.Strings[25400]="如果我们信仰圣光，就应该挥师北上，直面诺森德的黑暗势力。"
D.Strings[25401]="诺森德大陆遍布历史遗迹！我们要凿开坚硬的冰层，寻找祖先的足迹。"
D.Strings[25402]="极地独特的磁场区拥有难以估量的研究价值！"
D.Strings[25403]="听说他们找到了国王！他就要返回暴风城了！"
D.Strings[25404]="北方大陆商机暗藏啊……赶紧打点货物，穿上厚厚的外套，我们出发吧！"
D.Strings[25405]="哈！我有点想念老祝玛伽了。他很强壮，但是铁皮轻而易举就将他干掉了。"
D.Strings[25406]="小道消息传得跟风中的落叶一样快。他们说北方大陆生活着高等精灵！"
D.Strings[25407]="瞧，笼子空了。一只可怜的巨魔倒在斗兽场的血泊中。你们还是坚持不肯屈服是吧？"
D.Strings[25408]="轮到你了。你愿意被铁皮一口吞掉呢？还是打算开口说点什么？我让你考虑一会儿吧。"
D.Strings[25409]="你很思念你的邻居吧。让我看看能不能快点让你去陪他。"
D.Strings[25410]="你没有多少时间啦。如果你愿意谈谈达克萨隆的情况，尽管开口吧。"
D.Strings[25411]="达卡莱战士，嗯？让我们瞧瞧你在面对铁皮时，能展现出怎样的英勇气概。"
D.Strings[25412]="我有个主意。不如你告诉我达克萨隆的情况，然后我就给老铁皮送些点心？"
D.Strings[25413]="那么，我的建议你考虑得怎么样了？不论你做什么决定，我想铁皮都会很高兴的。"
D.Strings[25414]="加尔鲁什急于远征北方，但萨尔主张谨慎行事……"
D.Strings[25415]="我很想知道诺森德有什么猎物。我敢打赌，一定有凶猛的野兽。"
D.Strings[25416]="亡灵的灵魂饱受诅咒和痛苦的折磨。如果我被感染了，你一定要在我彻底堕落前结束我的性命……"
D.Strings[25417]="药剂师们夜以继日地工作，研究治疗巫妖王诅咒的方法。没有他们，联盟和部落将丧失获胜的机会。"
D.Strings[25418]="返回冰冠冰川，不然先锋军狮鹫会将你抛下去的！"
D.Strings[25419]="返回先锋军港口，不然白骨狮鹫会将你抛下去的！"
D.Strings[25420]="给，朋友。这是你的白骨狮鹫。不如骑上它和先锋军作战！"
D.Strings[25421]="高级指挥官，这真是个精彩的故事。"
D.Strings[25422]="我们是来找活儿干的，长官。"
D.Strings[25423]="呃……我们受理殡仪事务，长官。"
D.Strings[25424]="%s朝米克高维尔扑闪着大眼睛。"
D.Strings[25425]="%s哀怨地对米克高维尔叹了口气……又或者是对飞行器叹气？"
D.Strings[25426]="%s满怀希望地盯着飞行器……又或者她是在看米克高维尔？"
D.Strings[25427]="可恶的……哇哇！杀！对，杀了你！"
D.Strings[25428]="海德比武会是神圣的。获胜者将赢得终身陪伴托里姆的殊荣。"
D.Strings[25429]="来吧，宝贝儿！"
D.Strings[25430]="动手吧……"
D.Strings[25431]="轰轰！"
D.Strings[25432]="哈哈，真是精彩！"
D.Strings[25433]="我喜欢把东西炸上天！"
D.Strings[25434]="炸弹真是伟大的发明！"
D.Strings[25435]="你不该招惹地精的。"
D.Strings[25436]="尝尝炸弹的厉害吧！"
D.Strings[25437]="矮人……奇怪的生物……"
D.Strings[25438]="它们会觉得痛吗？？"
D.Strings[25439]="你很快就会和我们一样了……"
D.Strings[25440]="颤抖吧，矮人！！"
D.Strings[25441]="瓦古会吃掉你！"
D.Strings[25442]="我自由了？我自由了！"
D.Strings[25443]="真不敢相信！我可以走了！"
D.Strings[25444]="我该离开啦！谢谢你，朋友！"
D.Strings[25445]="朋友，愿圣光与你同在。"
D.Strings[25446]="我必须集中精神，许多无辜的生命要靠我们去挽救。"
D.Strings[25447]="能为圣光奉献力量是我的荣耀。天灾军团妄图摧毁我们的家园，对我们的同胞进行有计划的屠杀，我们绝不会让他们得逞。"
D.Strings[25448]="我不知道元帅的下落。你去死吧！"
D.Strings[25449]="我要用你的内脏当早餐！"
D.Strings[25450]="瑞拉克，我把迷你鹦鹉弄丢了！求你帮帮我！"
D.Strings[25451]="我要让你输得心服口服！"
D.Strings[25452]="你可以杀了我，但是我绝对不会告诉你！"
D.Strings[25453]="我是血色先锋军的一员！绝不会出卖自己的领袖！"
D.Strings[25454]="你不过是黑锋骑士团的走狗。去死吧！"
D.Strings[25455]="我不知道他的下落。就算我知道，也不会告诉你——哪怕你杀了我！"
D.Strings[25456]="欢迎你，疲惫的旅行者。历经长途跋涉后，希望你能在欧尼瓦营地好好休息。"
D.Strings[25457]="我要用你的尸体装饰桅杆！"
D.Strings[25458]="欢迎来到欧尼瓦营地。休息一会儿，科多兽交给我们来照料吧。"
D.Strings[25459]="被遗忘者在努力地研制治愈瘟疫的方法，希望以此拯救倍受侵害的联盟和部落成员；而我们则起誓消灭那些包围着各大主城的天灾军团浮空城。$B$B利用圣光的力量，我们能对巫妖王的造物造成重创，运气好的话，还能直接摧毁它们。"
D.Strings[25460]="你好啊，旅行者。但愿从冬蹄营地到这座破落岗哨的路不是太难走。"
D.Strings[25461]="我要告诉大主教兰德雷！啊……"
D.Strings[25462]="欢迎你，旅行者。你从冬蹄营地来的吧，很高兴你能平安抵达这里。"
D.Strings[25463]="卫兵！快来帮帮我！"
D.Strings[25464]="等等……住手！我不知道元帅的下落，但是我或许能帮忙找到他。"
D.Strings[25465]="我给你钱，还有珠宝！别杀我！"
D.Strings[25466]="我真的不知道他在哪儿。抵达这里之后，我就再也没有见过他了！"
D.Strings[25467]="来人啊！我被袭击了！"
D.Strings[25468]="住手！我愿意加入你们！"
D.Strings[25469]="别打脸！别打脸啊！"
D.Strings[25470]="你竟敢招惹我！你知道我是谁吗？"
D.Strings[25471]="你好，$C。你弄丢了宠物吗？"
D.Strings[25472]="主人，我会为你献上成千上万的生命。"
D.Strings[25473]="陛下，我会服从你的一切指令！"
D.Strings[25474]="陛下，整个世界将因你而颤抖……"
D.Strings[25475]="我愿意成为毁灭一切的工具！陛下，请下令吧！"
D.Strings[25476]="胆敢与天灾军团抗衡的家伙，必将落得悲惨的下场！"
D.Strings[25477]="我们的敌人只有死路一条！"
D.Strings[25478]="你好，$c。我可以帮你看管宠物，或者帮你找回走失的伙伴。"
D.Strings[25479]="陛下，我已重获新生，从此终身臣服于你。"
D.Strings[25480]="我不会心慈手软的。"
D.Strings[25481]="我想寄养宠物。"
D.Strings[25482]="我的迷你鹦鹉不见了。"
D.Strings[25483]="我的加布林不见了。"
D.Strings[25484]="莫格莱尼先是伸手要军队，接着又要带走我的仆从？什么玩意儿！"
D.Strings[25485]="别再跟我扯什么圣光了！我还要铸造武器和护甲呢！"
D.Strings[25486]="他先是将那些宝贵的萨隆邪铁随意派送出去，然后又命令我锻造更强大的符文剑。我呸！"
D.Strings[25487]="我没有傻头傻脑的奴仆，但是我至少能亲眼目睹利刃的诞生。"
D.Strings[25488]="如果能从诺森德搞到原料，我或许能锻造出可以冻结亡灵心脏的武器。"
D.Strings[25489]="这些死亡骑士真是不知羞耻啊。他们拿走了我精心锻造的武器和盔甲，那些都是接受过巫妖王赐福的好东西呀。接着他们不知道去哪儿逛了一圈，回来的时候一个个都穿得跟地精似的，嗫嚅着说他们为了几个铜板不得不卖掉了盔甲！真是可耻！"
D.Strings[25490]="我忙得不可开交，可是有谁来帮过我呢？一个都没有！这帮混蛋！"
D.Strings[25491]="帮我修理一下盔甲，科弗斯！我的剑生锈了，科弗斯！……这些该死的家伙什么时候才能学会照顾自己？"
D.Strings[25492]="我的精龙宝宝不见了。"
D.Strings[25493]="我们应该再发一枚信号弹。这样或许能从黑锋哨站请求到更多的支援。"
D.Strings[25494]="我打算再发一枚信号弹。但愿黑锋哨站能看见。"
D.Strings[25495]="黑锋哨站或许还能再派一些援军来。再发一枚信号弹吧。"
D.Strings[25496]="我的座狼幼崽不见了。"
D.Strings[25497]="我的烟网小蜘蛛不见了。"
D.Strings[25498]="我不是在做梦吧？！真的有人来救我了？"
D.Strings[25499]="什么……不……不是吧？那个没心肝的蠢货让你先帮他找工具，然后再来找我？"
D.Strings[25500]="呃……我会留意那些炮塔的……"
D.Strings[25501]="只有一个人能活下来！"
D.Strings[25502]="第2轮将在1分钟后开始！"
D.Strings[25503]="我要争取自由，离开这个该死的地方！"
D.Strings[25504]="你犯了一个严重的错误，魔鬼！"
D.Strings[25505]="他们说我是废物？我要让他们瞧瞧什么才叫废物！"
D.Strings[25506]="我曾经为圣光而战……可你看看我现在的样子……"
D.Strings[25507]="你会让我挑一把武器和一套盔甲吧？"
D.Strings[25508]="你没有获胜的希望，$r。"
D.Strings[25509]="我要拆除这座腐烂的地狱！"
D.Strings[25510]="尝尝冰冷钢铁的厉害吧，$r！"
D.Strings[25511]="死亡是唯一的出路！"
D.Strings[25512]="我们的未来看不到希望……"
D.Strings[25513]="我的农场小鸡不见了。"
D.Strings[25514]="怪物！你会先毙命的！"
D.Strings[25515]="该结束了！"
D.Strings[25516]="让恐惧将你淹没吧！"
D.Strings[25517]="哈！你连剑都拿不稳！你的末日即将来临。"
D.Strings[25518]="很好。来个了断吧。"
D.Strings[25519]="我的鹿角小飞兔不见了。"
D.Strings[25520]="越来越多的攻击者从加姆涌来。迅速埋设地雷！"
D.Strings[25521]="猛犸人越来越近了……"
D.Strings[25522]="已经能看见他们啦——停止埋设地雷！"
D.Strings[25523]="他们来了！炸死他们！"
D.Strings[25524]="利斯巴克的载具商店开始营业啦！"
D.Strings[25525]="斯巴克莱特的战车商店开始营业啦！"
D.Strings[25526]="过来，兰德雷。我有很重要的事情要问你，你最好老实交代。"
D.Strings[25527]="还不错吧，但是多掌握点技巧总是没错的！你瞧，看我摆臀的动作……像这样！"
D.Strings[25528]="机械松鼠都比你挖得快！"
D.Strings[25529]="挖快点！我可不管你的传动装置是不是生锈了！"
D.Strings[25530]="你一定是用锡锭造出来的，懒骨头！"
D.Strings[25531]="没有完成当日额定工作量的工人将被扔进熔炉！"
D.Strings[25532]="你连一堆破铜烂铁都比不上！"
D.Strings[25533]="你的母亲是一只扳手，你的父亲则散发着爆盐炸弹的气味！"
D.Strings[25534]="你！我看你连冲制扳手这种简单的活儿都做不了。给我滚！"
D.Strings[25535]="假人都比你干得快！加快速度！"
D.Strings[25536]="告诉我韦斯温的下落，不然我就摧毁你的灵魂！"
D.Strings[25537]="你休想从我嘴里问出元帅的下落。我还不至于受你摆布。"
D.Strings[25538]="看来我别无选择了。好吧，其实我很乐意这样对付你的。"
D.Strings[25539]="住手！用不着这样。我告诉你他的下落。"
D.Strings[25540]="很好。快说！"
D.Strings[25541]="这座岛屿的南端有一处极端隐蔽的洞穴。元帅就躲在那儿，策划着对巫妖王的最后决战。"
D.Strings[25542]="隐蔽的洞穴？真有意思。兰德雷，你没有利用价值了。恐怕这次你就没有复活的机会了！"
D.Strings[25543]="事情总算有了眉目，那么就让我们谈谈要如何对付巴利·韦斯温元帅吧。"
D.Strings[25544]="士兵们，行动！我们负责掩护！"
D.Strings[25545]="我们掩护你们！撤退！"
D.Strings[25546]="快撤退！"
D.Strings[25547]="我们负责掩护，立刻撤退！"
D.Strings[25548]="等你们解决掉元帅之后，再来死亡高地见我吧。"
D.Strings[25549]="冰牙已经陪伴我经历过无数次战役。$b$b不要被她不穿护甲的表象迷惑了。她是我见过的最聪明的熊。"
D.Strings[25550]="别再耽搁时间了！$b$b激烈的战斗在等待！"
D.Strings[25551]="为布伦希尔达村的荣耀而战！"
D.Strings[25552]="黑暗编织者变成了恐怖的恶魔生物。"
D.Strings[25553]="%s发出狂笑，身体产生了可怕的变化。"
D.Strings[25554]="%s发出恐怖的嚎叫声，变成了可怕的恶魔。"
D.Strings[25555]="黑暗编织者冲你露出邪恶的笑容，他的身体紧接着变成了完全不同的形态。"
D.Strings[25556]="既然你已经知道了，那就必须死了！"
D.Strings[25557]="即便在死后，你也无路可逃！"
D.Strings[25558]="你休想活着离开这里！"
D.Strings[25559]="什么？！没关系。就算没有魔法屏障，我仍然可以轻易消灭你们！在绝望中感受我真正的力量吧！"
D.Strings[25560]="啊！我在那具虚弱的躯壳中待得太久了！"
D.Strings[25561]="Kirel narak！我是玛尔加尼斯！我是不朽的！"
D.Strings[25562]="够了！我在这里浪费了不少时间，必须回到家乡去回复体力。"
D.Strings[25563]="没有我的部队，你们永远也别想击败巫妖王。我会向他复仇的……还有你们！"
D.Strings[25564]="你们觉得我会甘心等死吗？"
D.Strings[25565]="天灾军团攻破了南面的城墙！"
D.Strings[25566]="你怎么找到我的？难道兰德雷全招了？"
D.Strings[25567]="啊哈哈哈哈！这就是你们最后的手段了？"
D.Strings[25568]="天灾军团攻破了西面的城墙！"
D.Strings[25569]="天灾军团攻破了北面的城墙！"
D.Strings[25570]="冰牙非常勇敢，不穿盔甲也敢上战场。$b$b$n，或许她能让你鼓起勇气，面对即将到来的挑战。"
D.Strings[25571]="我说，情况似乎不妙啊。"
D.Strings[25572]="我觉得，拜雷……似乎没有那么糟糕吧。你瞧，从我们现在的位置扔石头，是能砸到工具的。"
D.Strings[25573]="真奇怪……等等，刚才我分明听见你说我矮。"
D.Strings[25574]="是吗？既然如此，你为什么不自己跳过去取回工具呢？"
D.Strings[25575]="把我扔过去？！你能不能别出这种馊主意？"
D.Strings[25576]="我不想听。"
D.Strings[25577]="你最好祈祷他们直接被炸死。"
D.Strings[25578]="如果他们还活着的话，肯定会将你扔进雷区。到时候我只会在一旁偷笑。"
D.Strings[25579]="一定有办法过去的。"
D.Strings[25580]="不然地精怎么能将他的工具留在那里呢？"
D.Strings[25581]="对啦！看上去绝对安全啊。你走前面，我会跟着你的！"
D.Strings[25582]="呃……我刚才在想……你的个子比较矮，所以不可能让你来引爆地雷。"
D.Strings[25583]="没有！没有！我不是说你矮啦……呃……这么说吧……或许我可以将你扔过去，直接穿越这片雷区？"
D.Strings[25584]="拜雷，我想到一个办法……"
D.Strings[25585]="听我说——这个法子说不定管用！"
D.Strings[25586]="你瞧，沿着这条道走，我们和工具之间……其实只有几枚地雷。"
D.Strings[25587]="我们就在这里等待下一拨冒险者，然后告诉他们该往哪儿走……等他们引爆地雷后，我们就可以直接走过去拿工具了！"
D.Strings[25588]="拜雷，我实在想不出有什么办法可以过去。"
D.Strings[25589]="噢……有道理。是那里吗？那条道似乎……没有障碍。"
D.Strings[25590]="嗯……好吧。上次的伤还在隐隐作痛呢。"
D.Strings[25591]="天哪……不！"
D.Strings[25592]="就差一点！你吓死我了！"
D.Strings[25593]="胆小鬼。"
D.Strings[25594]="嘿，$c。如果你弄丢了钥匙，我或许能帮上忙。"
D.Strings[25595]="我把通灵学院的钥匙弄丢了。"
D.Strings[25596]="我把禁魔监狱的钥匙弄丢了。"
D.Strings[25597]="我把灼热峡谷的钥匙弄丢了。"
D.Strings[25598]="我把暗炉钥匙弄丢了。"
D.Strings[25599]="我把哈拉迈德之眼弄丢了。"
D.Strings[25600]="我把卡拉赞的钥匙弄丢了。"
D.Strings[25601]="又是那些该死的铁矮人！他们居然抢在我们前面找到了他。"
D.Strings[25602]="他们不找到他是不会放弃的。我们不能让这种事发生，$n，布莱恩也明白这一点。"
D.Strings[25603]="日记中记载着一些晦涩难懂的信息。布莱恩一定有后备计划，但他不可能永远不被抓到……"
D.Strings[25604]="现在就指望你了，一定要抢在铁矮人前面找到他！"
D.Strings[25605]="站在你面前的是一位奥术魔法的大师。只有蠢货才会不自量力地向我宣战。他们无一例外地变成了烧焦的尸体。"
D.Strings[25606]="我的生命与灵魂中充斥着部落留给我的痛苦回忆。悲伤、绝望和牺牲已经成为历史。战争的怒火永远在我内心深处燃烧！"
D.Strings[25607]="%s一边做事，一边吹着口哨。"
D.Strings[25608]="%s幻想着王子与遥远的国度。"
D.Strings[25609]="该传送门通往阿拉希盆地战场。"
D.Strings[25610]="该传送门通往奥特兰克山谷战场。"
D.Strings[25611]="该传送门通往风暴之眼战场。"
D.Strings[25612]="该传送门通往战歌峡谷战场。"
D.Strings[25613]="获取"
D.Strings[25614]="坏巨魔，滚开！"
D.Strings[25615]="你为什么要伤害怒爪？你疯了吗？"
D.Strings[25616]="怒爪和巨魔不再是朋友了！"
D.Strings[25617]="你们杀了我们的孩子！我们要报仇！"
D.Strings[25618]="是你选择了与我们为敌！"
D.Strings[25619]="你伤害了首领的海狮！你为什么要伤害海狮？？！"
D.Strings[25620]="你的味道怎么这么难闻了？你以前没这么难闻的！"
D.Strings[25621]="巨魔太无耻了！巨魔都是刽子手！"
D.Strings[25622]="%s扔出一枚炸弹。"
D.Strings[25623]="有什么事吗？$B$B你是来吃东西，还是来学习厨艺的？我可是最棒的大厨噢。"
D.Strings[25624]="执行达库鲁的意志！"
D.Strings[25625]="这片土地将属于天灾军团！"
D.Strings[25626]="小畜生的家园都被点燃了！"
D.Strings[25627]="谁也救不了你们！这片土地现在归天灾军团了！"
D.Strings[25628]="谁都不能阻止我们！"
D.Strings[25629]="我们是不可阻挡的！"
D.Strings[25630]="想要购买战袍？"
D.Strings[25631]="我把阿拉索战袍弄丢了。"
D.Strings[25632]="我把污染者战袍弄丢了。"
D.Strings[25633]="我把血骑士战袍弄丢了。"
D.Strings[25634]="我把银色黎明战袍弄丢了。"
D.Strings[25635]="我把阿古斯之手战袍弄丢了。"
D.Strings[25636]="我把绿色伊利达雷战袍弄丢了。"
D.Strings[25637]="我把紫色伊利达雷战袍弄丢了。"
D.Strings[25638]="你好，$c。我可以帮你找回失散的伙伴。"
D.Strings[25639]="我把成就战袍弄丢了。"
D.Strings[25640]="我把保卫者的战袍弄丢了。"
D.Strings[25641]="你被发现了！快使用投网和地面速冻，别让那些矮人靠近你！"
D.Strings[25642]="%s嗅着地面，寻找气味的踪迹。"
D.Strings[25643]="%s循着气味找到了源头。"
D.Strings[25644]="冰霜猎犬发现了小偷的藏身之所。快去对付他！"
D.Strings[25645]="蛇鳞的仆从，响应我的召唤！"
D.Strings[25646]="你的血肉将被千万颗利齿撕咬！"
D.Strings[25647]="巨魔把我惹火了！"
D.Strings[25648]="你好啊！你想要购买渔具，还是学习垂钓的艺术？"
D.Strings[25649]="评估数据库的完整性……"
D.Strings[25650]="运行三级诊断……"
D.Strings[25651]="整理交换文件……"
D.Strings[25652]="校验密钥……"
D.Strings[25653]="尝试修复丢失的数据……"
D.Strings[25654]="执行新的安全协议……"
D.Strings[25655]="我踏遍了艾泽拉斯的每一寸土地，想要寻找失落的荣耀并收复属于我的王国。在我离开暴风城的这段日子里，联盟经历了种种考验。有你这样的英雄保卫我们脆弱的盟国，我真是倍感欣慰。"
D.Strings[25656]="拿起武器！我们必须守住港口，否则联盟远征诺森德的计划就会提前流产！"
D.Strings[25657]="我们必须对巫妖王的挑衅做出回应。暴风城的子民将尽力而为，但是想要克服眼前的危机，我希望你们所有人都能贡献出自己的力量。只有首先解除家园的威胁，我们才有可能粉碎天灾军团在诺森德的阴谋。$B$B叛离的王子阿尔萨斯从远在诺森德的王座上向我们发起了挑战。联盟不能束手待毙。战争……一触即发。$B$B击败巫妖王和他的部队将是一个漫长而艰难的过程。我们必须征服死亡本身。许多人可能会因此牺牲，但艾泽拉斯的未来就看我们能否取胜了。$B$B我希望你能参与诺森德的战斗，为这一崇高的事业奉献自己的价值。"
D.Strings[25658]="乌瑞恩国王很快就会回归。五年来，天灾军团按兵不动地驻守在原有的领地上，并未向外扩展他们的势力范围。世界各地偶尔出现的危机，也被勇敢的英雄们逐一化解。这样和平的日子已经结束了。"
D.Strings[25659]="现在不是聊天的时候！天灾军团正在攻击我们的战舰。拿起武器，保护那些船只！如果它们被毁了，那我们数月的心血就会付诸流水！"
D.Strings[25660]="我们在洛丹伦的努力已化为泡影。军队遭到重创，而天灾军团的势力并未损减。我们必须从源头上消灭他们。$B$B我们要去诺森德。我并不知道前方隐藏着怎样的危机，只知道那里有无数急于杀死我们的敌人。$B$B但是我们别无选择，艾泽拉斯的未来已经落在了我们的肩膀上。"
D.Strings[25661]="%s开始变形！"
D.Strings[25662]="自从第三次战争中我最后一次和盟友并肩作战以来，联盟发生了翻天覆地的变化。某些变化固然是好的，但是另一些……$B$B<布罗尔绝望地看着瓦莉拉。>$B$B……本来是可以避免的。$B$B在我们集中精神抵御燃烧军团对艾泽拉斯的攻击时，天灾军团逐渐发展壮大，形成了一股可怕的势力。燃烧军团的堕落力量和天灾军团的污染力量在本质上是相同的：它们都是违反自然法则的存在。我们必须扼杀它们。"
D.Strings[25663]="别说废话！如果天灾军团攻陷了我们的城市，那么联盟击败巫妖王的希望就破灭了！"
D.Strings[25664]="%s变成了一头猛犸象！"
D.Strings[25665]="自从第三次战争后，我再也没有见过如此整齐的部队了！瓦里安已经决心直面天灾军团的威胁。这才像他……$B$B你要去诺森德吗？我没有去过那里，不过我听说诺森德是一片美丽丰饶的土地。遗憾的是，我必须留下来处理各种紧急事件，因此无法随弗塔根公爵的部队一同出发。"
D.Strings[25666]="别用那种眼神打量我。我理解你们的感受。但是卫兵还有平民始终向我投来怀疑的目光，这点令我难以忍受。$B$B为了履行对瓦里安的承诺，我却打算继续留在这里。他能以平等的态度看待我……联盟也应该用这种态度对待我的族人。$B$B天灾军团正在破坏暴风城的宁静，如果你看够了的话，不如去帮帮忙？"
D.Strings[25667]="没时间闲聊了！如果船只被摧毁，联盟就只能在自己的家园与天灾军团作战，还怎么攻陷巫妖王的老巢！快去帮忙吧，杀掉那些亡灵！"
D.Strings[25668]="我听说部落也在招募征战诺森德的军队。希望联盟和部落可以将矛头一致指向真正的威胁。你懂我的意思吧，我是说不要窝里斗。$B$B虽然以我的经验来看，实现真正的同盟不太可能。你们对我真是太“热情”了。$B$B<瓦莉拉生气地咕哝着。>"
D.Strings[25669]="暴风城的蠢货们！无知的联盟臣民们！聆听我的审判吧！在恐惧中颤抖吧。巫妖王的双眼已经在凝视着你们。"
D.Strings[25670]="啊！这个渺小的胜利不会改变你们的境地！来吧！到诺森德来吧！我的仆从们在等着你们，他们已经饥不可耐了……"
D.Strings[25671]="怒爪自由了！巨魔去死吧！"
D.Strings[25672]="再也不会有狼獾人好好先生了！"
D.Strings[25673]="去死吧，巨魔！"
D.Strings[25674]="为怒爪复仇！"
D.Strings[25675]="我要宣战！"
D.Strings[25676]="检测到创世者的圆盘的用途。激活紧急协议。"
D.Strings[25677]="检验诺甘农之壳的状态。"
D.Strings[25678]="诺甘农之壳处于安全状态。核实用户身份后即可进行数据传输。"
D.Strings[25679]="准备核实守护者米米尔的身份。"
D.Strings[25680]="身份核实失败。用户非守护者米米尔。"
D.Strings[25681]="创世者的圆盘已落入非法用户手中。激活防御协议。"
D.Strings[25682]="消灭冒名顶替者。夺回创世者的圆盘。"
D.Strings[25683]="你们屈服得也太快了！"
D.Strings[25684]="你们是否很失望呢？"
D.Strings[25685]="真不幸。好戏还没开始呢。"
D.Strings[25686]="我的先锋军，将会荡平巫妖王的部队！"
D.Strings[25687]="你的牺牲是徒劳的，渺小的凡人。"
D.Strings[25688]="你的生命结束了。"
D.Strings[25689]="别再浪费时间了。$c，消灭巫妖王的爪牙！"
D.Strings[25690]="对抗巫妖王的战事有何进展，$c？"
D.Strings[25691]="先锋军将彻底消灭巫妖王的部队！"
D.Strings[25692]="你还好吧？如果你能站起来的话，我会送你返回冰霜堡。"
D.Strings[25693]="所有系统已上线，可以使用！"
D.Strings[25694]="指令：修复原型机控制台。"
D.Strings[25695]="执行指令！"
D.Strings[25696]="原型机控制台已修复，恢复可用状态。"
D.Strings[25697]="等待守护者米米尔的下一步指令。"
D.Strings[25698]="充电！"
D.Strings[25699]="<当你靠近时，霜脉斥候试图站起来；但是他很快就跌倒在地，紧紧地捂住身体上那条明显的伤口。>"
D.Strings[25700]="来不及了。我失血过多……坚持不了多久了。"
D.Strings[25701]="很抱歉，我来晚了。发生了什么事？"
D.Strings[25702]="一群鹰身人突然冲出山谷。带领她们的是一只名叫希尔拉娜的鹰身人……我无路可逃。我不明白……她们为何变得如此具有攻击性……我放松了警惕……是我的失误。"
D.Strings[25703]="我去求援。你待在原地别动。"
D.Strings[25704]="没……没有用……太晚了。$B$B<霜脉斥候往雪地上咳出几口鲜血。>$B$B替我……报仇……$B$B<霜脉斥候咽下最后一口气，摊倒在地。>"
D.Strings[25705]="$c，环顾四周，将这破败的景象印在你的脑海中吧。居住在这里的巨魔不是死了就是逃到上层去了。$B$B局势越来越严峻了。$B$B陷入绝望的达卡莱巨魔杀害了氏族崇拜的动物之神，并饮下它们的鲜血来攫取难以言喻的力量。虽然他们凭借新的力量成功地牵制了天灾军团的攻势，却由此引发了灾难性的后果。沦为废墟的远古帝国祖达克就是最好的例证。"
D.Strings[25706]="你千万不能败露自己的行踪。我要继续装出臣服于巫妖王的模样！"
D.Strings[25707]="你好了吗？"
D.Strings[25708]="我们要回去找兰迪加，把这里的情况告诉他。快！"
D.Strings[25709]="如果让我来开坦克，事情就不会搞成现在这样了！"
D.Strings[25710]="我们经不起再一轮的攻击了。快带我们离开这里！"
D.Strings[25711]="快，里德！"
D.Strings[25712]="你能数清楚这里有多少怪物想杀我们吗？我敢打赌，统计数字会让你大吃一惊。"
D.Strings[25713]="我的速度已经达到极限了。别干扰我！"
D.Strings[25714]="是啊，我相信如果让你来开坦克的话情况会好得多。比如我们直接就死在来这里的路上。我甚至能想象我们因此获得的头衔：“死于严重蒸汽坦克事故的银色北伐军英雄”。"
D.Strings[25715]="很多时候我都在想，为什么我们会成为好朋友呢。你总是在我的身边积极地鼓励我。"
D.Strings[25716]="我就是打算尽可能地拖延时间，让那些不怀好意的天灾军团杀掉我们，然后对我们的尸体做一些可怕的事。我这样说你满意了吧？"
D.Strings[25717]="不如你用扳手来试试？这样你就会明白敲打这玩意儿是什么感觉！我告诉你，这件事不是那么容易的！"
D.Strings[25718]="如果你再罗嗦一句，我就……"
D.Strings[25719]="为什么死的是达加斯而不是你？这是为什么！为什么！！"
D.Strings[25720]="你快把我避疯了！闭嘴！"
D.Strings[25721]="戈尔克、布尔和达加斯都死了……只有我和马克拉尔活了下来。希望你为我们带来了好消息。"
D.Strings[25722]="你能修好我的设备吗？"
D.Strings[25723]="嘀嗒嘀，嘀嗒嘀……"
D.Strings[25724]="还不够快！"
D.Strings[25725]="我们快点了结这一切吧。"
D.Strings[25726]="你已经没有未来了。"
D.Strings[25727]="这是我们获得伟大胜利的一刻！"
D.Strings[25728]="你命该就此陨落。"
D.Strings[25729]="历史的篇章已成定局……"
D.Strings[25730]="你敢？！斯利文男爵呢？我要和他说话！"
D.Strings[25731]="维尔自由了？维尔爱$n！"
D.Strings[25732]="碾碎你……毁灭！"
D.Strings[25733]="是谁干扰了我的仪式？"
D.Strings[25734]="够了！我受够了！"
D.Strings[25735]="你就是那个捣乱的家伙？要对付你，真是易如反掌。"
D.Strings[25736]="巫妖王，我要铲除你所有的走狗！"
D.Strings[25737]="带上你的飞行堡垒滚回诺德森去，否则我就徒手碾碎它们！"
D.Strings[25738]="等等。如果你身上带着核心的话，请把它放在地上，避免在战斗过程中造成损伤。"
D.Strings[25739]="战斗开始。谢谢合作。"
D.Strings[25740]="亲爱的将军，你的末日来临了！"
D.Strings[25741]="我不会让你这么做的！"
D.Strings[25742]="国王要我顺便帮你一把——看来我干得还不错。祝你好运。"
D.Strings[25743]="够了。别打了！"
D.Strings[25744]="蠢货！暗影拱顶支持不了多久了！"
D.Strings[25745]="快！如果有人看见我和你在一起就糟了……"
D.Strings[25746]="快点！不能让人发现我们在一起。"
D.Strings[25747]="有什么消息吗，朋友？"
D.Strings[25748]="你能帮我下去吗，斯特凡？"
D.Strings[25749]="这能帮你安全回到地面，$n。"
D.Strings[25750]="安静！孩子们在睡觉！"
D.Strings[25751]="他们是来杀你的。"
D.Strings[25752]="放纵你内心的恐惧吧。"
D.Strings[25753]="杀光他们……别让他们先杀了你。"
D.Strings[25754]="他们已经背叛了你。现在……复仇吧。"
D.Strings[25755]="告诉你自己，这些人并不是你真正的朋友。"
D.Strings[25756]="没有退路了。这一生不会有。下一世亦不会有。"
D.Strings[25757]="你正被某种隐形的力量操控着。"
D.Strings[25758]="这是你的错。"
D.Strings[25759]="你们这些丑陋的小怪物，最好祈祷我出不去！"
D.Strings[25760]="我要把你们碾碎！"
D.Strings[25761]="我的兄弟会来救我的，然后你们就会见识到真正强大的力量！"
D.Strings[25762]="你们的酷刑只会激怒我！"
D.Strings[25763]="我要把你打垮！"
D.Strings[25764]="你们以为这个笼子能关我多久，魔鬼！"
D.Strings[25765]="我要能把你打败的话会很高兴！"
D.Strings[25766]="我要拿你去领赏！"
D.Strings[25767]="你的武器将成为我的收藏品。"
D.Strings[25768]="别想打赢我！"
D.Strings[25769]="你来送死吗？"
D.Strings[25770]="面对我的愤怒吧！"
D.Strings[25771]="我要消灭你！"
D.Strings[25772]="干得漂亮！到斯坦索姆的大门去，我会交给你下一项任务！"
D.Strings[25773]="再见。希望下次见面时，局势能好一些。我永远不会忘记你为我们所做的一切！"
D.Strings[25774]="天选者奥贾尔就在东北方的痛苦之匣。\n\n纳瓦留斯王子在东边死亡旷野的远端。"
D.Strings[25775]="滚开，豺狼人！"
D.Strings[25776]="别想从迪姆这里偷走零件！"
D.Strings[25777]="这是我的零件，豺狼人！"
D.Strings[25778]="这些都是地精的零件……不许偷！"
D.Strings[25779]="天哪！我的零件！"
D.Strings[25780]="不……别再偷了。"
D.Strings[25781]="为什么就不能让迪姆安静一会儿呢？"
D.Strings[25782]="迪姆想回家……别再捣乱了，让迪姆做完手里的活。"
D.Strings[25783]="%s从果荚中长了出来。"
D.Strings[25784]="我……还没……还没……"
D.Strings[25785]="休息一会，然后和我一起来启动这个东西。一切……马上就要真相大白了。好了，我们开始吧！"
D.Strings[25786]="是该收获答案了！让我们一路杀过去吧！"
D.Strings[25787]="干得好，你们的晚饭算是有着落了。"
D.Strings[25788]="抓紧，这边走这边走！"
D.Strings[25789]="你们想要挑战主人？先平息我的风暴吧！"
D.Strings[25790]="这点轻微的花火，将带来你们的灭亡！"
D.Strings[25791]="没有人是安全的！"
D.Strings[25792]="很震惊？我可以理解。"
D.Strings[25793]="你在尝试不可能做到的事！"
D.Strings[25794]="你的生命之火……就此熄灭了。"
D.Strings[25795]="主人……您有客人了。"
D.Strings[25796]="你们还有什么希望可言？完全没有！"
D.Strings[25797]="我曾见证过无数帝国的崛起与衰落……也见证过无数物种的诞生与灭绝……千百年来，凡人种族的愚蠢都不曾改变过。你们出现在这里，更是印证了这一点。"
D.Strings[25798]="在主人为我展示的未来图景中，没有你们的位置。艾泽拉斯将在黑暗中获得新生。尤格-萨隆将获得自由，而万神殿，必将毁灭！"
D.Strings[25799]="你们无法逃避命运！"
D.Strings[25800]="靠近点。我立刻送你们归天。"
D.Strings[25801]="你们的血肉之躯无法长存于世。"
D.Strings[25802]="区区凡人……"
D.Strings[25803]="我……就是永恒！"
D.Strings[25804]="你们把短暂的生命全部浪费掉了！"
D.Strings[25805]="我的死亡……预示着世界的终结。"
D.Strings[25806]="你们还不知道自己正在注视着无尽的深渊吗！"
D.Strings[25807]="你们太无知了。竟然看不清这条路通向何方吗？"
D.Strings[25808]="这条道路的尽头就是湮灭！"
D.Strings[25809]="铁矮人在追你！快使用结网和地面速冻逃跑！"
D.Strings[25810]="霜齿已经追踪到了气味的源头。进入洞穴仔细搜查！"
D.Strings[25811]="%s嗅着气味，寻找踪迹。"
D.Strings[25812]="%s循着气味找到了洞穴中的气味源头。"
D.Strings[25813]="嗯，你们帮我看着点外面。我这样的强者只要锤两下就能搞定这破烂……"
D.Strings[25814]="噢，见鬼，好像有点不太妙，看来我们遇到点小麻烦啦……"
D.Strings[25815]="嘿，破机器，怎么样？你想跟我来硬的？太可惜了，这是属于我的游戏！"
D.Strings[25816]="再给我几分钟，马上就能……啊噢……"
D.Strings[25817]="提高？这算是好消息吗？"
D.Strings[25818]="哈！终于找到问题出在哪儿了！我马上就能搞定了……"
D.Strings[25819]="等等！你想清理谁啊！有我在，没门！"
D.Strings[25820]="哈！看来还是我这把老骨头厉害呀！然后再看看这里……"
D.Strings[25821]="消除？不不不不……呀，我刚才搞到哪来着？啊哈！应该是这样！"
D.Strings[25822]="我已经竭尽全力了！"
D.Strings[25823]="圣光会保佑你的！"
D.Strings[25824]="希望这牺牲是值得的！"
D.Strings[25825]="问询？要不你以为我来这干嘛？喝下午茶吗？少废话！"
D.Strings[25826]="告诉我矮人是怎样演化出来的！从最初开始！"
D.Strings[25827]="对，对。我已经知道土灵是用石头创造出来，用以改造地下世界的。但变异是怎么发生的？我听说过什么母体扰动？"
D.Strings[25828]="寄生性噬主……什么来着？讲通用语会死吗？"
D.Strings[25829]="你管这叫做战斗？我还是把你的布娃娃拿来吧。或许她能教会你怎么挥剑。"
D.Strings[25830]="就连我去世的祖母……都能打倒你！噢，愿她的灵魂安息吧。"
D.Strings[25831]="我的左边脑袋劝我把你们俩就地解决了！我的右边脑袋对此毫无异议！"
D.Strings[25832]="嗨，女士们。你们觉得……斯克恩代表着什么？"
D.Strings[25833]="我要你们一直练到腰酸背疼为止，然后才开始真正的训练！"
D.Strings[25834]="只有精英中的精英才能进入瓦哈拉斯，前往伊米海姆。剩下的人都得死……甚至落得更加悲惨的结局！"
D.Strings[25835]="别光摆架势啊，上去给他一拳！"
D.Strings[25836]="你想让我丢脸是吗？这就是你唯一的能耐！"
D.Strings[25837]="上古之神是吧，也就是说他们给土灵施加了什么血肉的诅咒，然后怎么样了？"
D.Strings[25838]="如果他们真的杀光上古之神，那艾泽拉斯也就毁灭了……"
D.Strings[25839]="什么守护者？"
D.Strings[25840]="艾塞尔与瓦尼尔……好吧，这么说意志熔炉又从头开始创造了新的土灵……那老的怎么样了？"
D.Strings[25841]="等等！等等！你是说艾塞尔与瓦尼尔之间爆发了战争？为什么？"
D.Strings[25842]="这个“洛肯”听起来真是阴险狡诈。还好不用再理会他了。那么……如果我的理解没有错，最初的原始土灵是否因为某种原因从休眠仓里苏醒了过来，还受了这个什么母体扰动的影响，最终演化成现代的矮人？至少……是现代矮人的祖先。"
D.Strings[25843]="啊，现在我得花上很长时间来好好消化这些知识。我要在这里再待一会儿。谢谢你们。"
D.Strings[25844]="我会用熔炉来制造一些土灵，让他们保卫这里……但现在最大的挑战是：找到并阻止洛肯！"
D.Strings[25845]="暴风将赐予我力量！"
D.Strings[25846]="愿闪电指引我的怒火！"
D.Strings[25847]="让暴风吞噬你！"
D.Strings[25848]="邪恶必将受到惩罚！"
D.Strings[25849]="啊啊啊！！！强大的力量！"
D.Strings[25850]="闪电的力量在我体内流淌！"
D.Strings[25851]="尝尝暴风之王的怒火！"
D.Strings[25852]="美味的点心自己送上门来了呀！我能用炸弹把你烤熟吗？"
D.Strings[25853]="欢迎你，$c。"
D.Strings[25854]="我要把你踩在脚下！"
D.Strings[25855]="我要用你来擦靴子！"
D.Strings[25856]="小家伙，我一脚就能踩扁你！"
D.Strings[25857]="尝尝盖米尔的厉害！"
D.Strings[25858]="我自由了！！！你很快就会感受到暴风之王的怒火！"
D.Strings[25859]="哇！我……我从来没见过这样的家伙！让他们去死吧，$n！"
D.Strings[25860]="天灾军团没有机会获胜！"
D.Strings[25861]="燃烧"
D.Strings[25862]="正在检索……造物主曾经亲自回来清除噬主共体生物所造成的感染。根据当时的评估，上古之神滋生所造成的危害非常严重。强行分离被感染部分将导致宿主损毁——"
D.Strings[25863]="正确。造物主决定中和寄生体的威胁，并将其封锁在宿主内部。之后，包括意志熔炉在内的各系统受命开始创造新的土灵。植入了新的安全机制，并任命了守护者。"
D.Strings[25864]="名称：艾塞尔与瓦尼尔。如果用通用语命名，则是风暴巨人与岩石巨人，最高领袖为哨兵洛肯。守护巨龙受命监管艾泽拉斯世界的进化过程。"
D.Strings[25865]="另有后台信息与你的问询关联：在艾塞尔和瓦尼尔的全面战争之后——"
D.Strings[25866]="不详。数据显示，全面战争是由首席管理官洛肯发起的，他在此之后中和了所有残余的艾塞尔与瓦尼尔，结束了冲突。接着，他停止了包括土灵、巨人和维库人在内的数个源种生物的演化进程，并将他们全部封存在指定的封存仓内。"
D.Strings[25867]="本质上的确如此。"
D.Strings[25868]="我自由了，暴风的复仇将随之而来！"
D.Strings[25869]="开战之前，我会向你介绍敌人的情况。听仔细了，要对付天灾军团，必须做好充分的准备。"
D.Strings[25870]="正在检索史前数据……文档定位完毕。创世之初，土灵的使命是——"
D.Strings[25871]="正在检索……在其发展周期的初始阶段，艾泽拉斯世界遭受到了寄生性噬主共体生物的感染。"
D.Strings[25872]="名称：上古之神。上古之神感染了包括土灵在内的整个毫无防备的系统，意图将所有事物向他们自身同化。这种扰动母体结构的行为与现象被定义为“血肉诅咒”。扰动的效果与日俱增。"
D.Strings[25873]="收到，布莱恩布隆赞。进程终止。"
D.Strings[25874]="盖米尔，奥贾尔、纳瓦留斯和塞穆在哪儿？"
D.Strings[25875]="盖米尔，我要注意些什么？我从来没有骑过巨人。"
D.Strings[25876]="我准备好了，盖米尔。我们走吧！"
D.Strings[25877]="<布莱恩满怀期待地看着你。>"
D.Strings[25878]="你能想象吗？奥杜尔中埋藏着所有的智慧与知识，甚至还有生命本身的秘密！"
D.Strings[25879]="你能听懂我的话吗？现在，我们应该能沟通了吧。"
D.Strings[25880]="探险者协会真的派出了其他探员？我一个也没见着。我在一座被铁矮人攻占的营地里发现了你的日记。"
D.Strings[25881]="有个斥候在索尔莫丹发现了这本日记的剩余部分。从那时起，我们就开始寻找你的下落了。"
D.Strings[25882]="我……我能听懂！呃，既然我们能够对话，那么我想听听你的解释！"
D.Strings[25883]="你是怎么从探险者协会那里拿到我的联络器的？"
D.Strings[25884]="你解决了铁矮人，我很感谢你。但是部落为什么会对我感兴趣？"
D.Strings[25885]="该不会是斥候沃塔肯吧？连我都听说过他冷酷无情的名头。所以他是打算绑架我的吧？"
D.Strings[25886]="如果你看过日记，就该知道我发现了什么。泰坦的造物正在自相残杀！"
D.Strings[25887]="洛肯和他的铁矮人已经将土灵逐出了奥杜尔，并占领了这座城市。"
D.Strings[25888]="如果我们继续厮杀，洛肯就会利用奥杜尔的资源将联盟和部落一起摧毁。"
D.Strings[25889]="去和指挥官谈谈，劝他放弃沃塔肯的愚蠢计划吧。"
D.Strings[25890]="伯克塔认为坠机事故只是一次倒霉的经历，但是我相信我们可以从中学到点什么。"
D.Strings[25891]="伊米亚的战争领主，天选者奥贾尔就在东北方的痛苦之匣，准备唤醒他的瓦古大军。$B$B跨越东边的死亡旷野，你可以在通往祖达克第二层的阶梯附近找到纳瓦留斯王子。$B$B塞穆不知所踪，从体型来看，他是很难藏匿的。$B$B必须将他们统统解决！"
D.Strings[25892]="我还有几个问题，盖米尔。"
D.Strings[25893]="你像老太婆一样虚弱！"
D.Strings[25894]="见鬼去吧！"
D.Strings[25895]="今晚我要出席伊米海姆的宴会，而你只配为我倒酒。"
D.Strings[25896]="符文预示了我今日的胜利！"
D.Strings[25897]="累了吧？哈哈哈哈！"
D.Strings[25898]="今晚你就要在地狱里长眠了！"
D.Strings[25899]="你会希望自己从未觉醒。"
D.Strings[25900]="你就知道抱怨，像女人似的！"
D.Strings[25901]="毒药……胃部在剧烈翻腾……"
D.Strings[25902]="我准备好了——我们离开这里吧。"
D.Strings[25903]="你准备好了就告诉我一声。我希望越快越好……因为毒药正在慢慢发作。"
D.Strings[25904]="我本来想把毒囊交给莉吉特的……接着……你也知道了……我倒下了。谢谢你帮我！"
D.Strings[25905]="我们必须继续攻打尤顿海姆。不能给他们丝毫喘息的机会！让他们不眠不休地疲劳作战！拒绝纳降！$B$B即便是灰烬使者的持有者提里奥·弗丁和他麾下的银色北伐军，都不可能取得你如今的成就！$B$B$n，开战吧！就在我们闲聊的时候，说不定局势已经发生了巨大的逆转。"
D.Strings[25906]="等你准备好，我就将你放在我的头顶，然后我们一起消灭祖达克的天灾军团。你要指挥我对付敌人！"
D.Strings[25907]="你达到了1级军衔：新兵"
D.Strings[25908]="你达到了1级军衔：下士"
D.Strings[25909]="你达到了2级军衔：中尉"
D.Strings[25910]="盖米尔急需雷云！"
D.Strings[25911]="盖米尔快要死了！赶快去找雷云！"
D.Strings[25912]="保存在奥杜尔的文献中可能记载着阻止洛肯滥用城市资源来对付我们的办法。但是解封档案的钥匙被泰坦分成了两截，并分别藏了起来。$B$B我已经发现了其中一半的下落，它就藏在创世者的图书馆里。图书馆位于东北方群山的北麓。首先，你必须从图书馆守卫者那里取得圆盘的碎片。"
D.Strings[25913]="我们遇到麻烦了，$r！当心身后！"
D.Strings[25914]="主人！不！"
D.Strings[25915]="塞穆来了！"
D.Strings[25916]="塞穆……为……为我报仇……"
D.Strings[25917]="哦，是你放了他？无所谓，不过是将他的死期和重生稍微往后推了一点而已。"
D.Strings[25918]="感谢你帮助黑锋骑士团夺取了暗影拱顶。能得到你的支持真是我们的荣幸。$B$B联盟和部落仍在互相厮杀，殊不知这只会让巫妖王获益。我们必须集中精力，处理好眼前的要事。$B$B对银色北伐军来说，他们总是在制定作战计划时犹豫不决，一心想着如何完美地击败敌人，我们就没有这些乱七八糟的担忧。$B$B$n，你就是我们执行复仇大业的工具。"
D.Strings[25919]="我要把你撕成碎片。"
D.Strings[25920]="你想挑战？"
D.Strings[25921]="你看上去并不强壮。"
D.Strings[25922]="你觉得自己够格吗？"
D.Strings[25923]="动手吧，我的姐妹。"
D.Strings[25924]="欢迎你，我的姐妹。我能帮你找回失散的伙伴。"
D.Strings[25925]="欢迎你，我的姐妹。我能帮你看管宠物或是找回失散的伙伴。"
D.Strings[25926]="死亡骑士们……到这儿来！"
D.Strings[25927]="进来吧，我的姐妹。$B$B好好地吃上一顿，再睡个安稳觉，这样才能养足精力，全力备战！"
D.Strings[25928]="誓死保卫神殿！"
D.Strings[25929]="击退敌人！"
D.Strings[25930]="他们在地下！他们在地下！"
D.Strings[25931]="这里是我们的家园！"
D.Strings[25932]="挑战者被打败了！"
D.Strings[25933]="他们还真是不堪一击啊！"
D.Strings[25934]="挑战者只留下了一滩血迹！"
D.Strings[25935]="不如叫些小丑来！神圣的斗兽场已经沦为马戏团了！"
D.Strings[25936]="哇！那家伙需要好好地“刮一刮”！"
D.Strings[25937]="我还没回过神来——就听见“砰”的一声！挑战者就死了！"
D.Strings[25938]="女士们先生们，请闭上双眼！这简直是大屠杀！"
D.Strings[25939]="进入痛苦斗兽场吧，$n。战斗开始后，你就必须留在竞技场里。要么获胜，要么死亡！"
D.Strings[25940]="女士们先生们，我们又见面啦。痛苦斗兽场的生死大战即将拉开帷幕！这一轮，将由$n对阵庞大的冰虫伊戈……伊戈达？伊戈杜斯？这名字是谁起的？！好吧，由$n对阵大虫子！"
D.Strings[25941]="$n击败了伊戈……伊戈这只大虫子！"
D.Strings[25942]="做好准备，$n！进入斗兽场，准备战斗！记住，你和你的对手都不能离开竞技场，否则你会被取消资格！"
D.Strings[25943]="战斗即将开始！我没念错吧？这……这是邪恶的猛犸人领主，恶臭之须！是的，各位，是恶臭之须！$n毫无取胜的希望！"
D.Strings[25944]="$n以绝对优势战胜了猛犸人领主！龙骨荒野的猛犸人氏族会怀念恶臭之须的！"
D.Strings[25945]="一群小不点，恶臭之须来了！"
D.Strings[25946]="我要熔化你们的血肉！"
D.Strings[25947]="$r，你觉得有把握战胜我吗？"
D.Strings[25948]="你的种族毫无荣耀可言。尽管放马过来吧……反正你会像其他人一样死去！"
D.Strings[25949]="以托里姆胡须的名义，这将是一场精彩的比赛！"
D.Strings[25950]="动手吧，$r$c，我没时间跟你干耗！"
D.Strings[25951]="就算杀了你，也不能证明我在瓦哈拉斯的地位，就当是消遣好了！"
D.Strings[25952]="如果你想死，我就成全你！"
D.Strings[25953]="我送你一条通往地狱的捷径，而你让我消遣一番。听上去挺公平的！"
D.Strings[25954]="达卡莱巨魔，然后是所谓的血色先锋军，接着是侏儒和海德尼尔持盾女武士，现在轮到你了？这是在跟我开玩笑吧？"
D.Strings[25955]="你们感觉到了吗？能量在空气中沸腾！这只能说明……"
D.Strings[25956]="站起来吧，大地的兄弟们。伊拉修斯要消灭这群凡人！"
D.Strings[25957]="为猎潮者而战！海洋与风暴的力量，摧毁我的敌人吧！"
D.Strings[25958]="风之领主，让我的敌人迅速死去吧！"
D.Strings[25959]="除非亲眼目睹，否则接下来的战斗将令人难以置信！这位即将出场的战士原本是个脾气温和的海象人渔夫，但是他的全家被恶毒的海狮和暴躁的企鹅杀死了，从此他就变成了一个行尸走肉般的雇佣兵。现在，他只为金币而战！女士们先生们，他就是奥里努克·碎牙！！"
D.Strings[25960]="来吧，旱鸭子。面对我的怒火吧！"
D.Strings[25961]="科尔拉克来了！雪落墓地属于冰斧的勇士！呃，科尔拉克是想要说，斗兽场属于冰斧的勇士！"
D.Strings[25962]="别想对科尔拉克耍花招，斗兽场可没有墓地！去死吧！"
D.Strings[25963]="来自冰冠冰川野蛮之台的屠夫乌拉多弗以及他的猛犸象恩诺姆斯！各位，这次我们的挑战者恐怕会被轰得连渣都不剩！让我们共同期待一场腥风血雨的大战吧！"
D.Strings[25964]="嗨，宝贝儿，将他们统统撕碎！我们才是真正的王者！"
D.Strings[25965]="没用的家伙！看来我得亲自动手了！"
D.Strings[25966]="乌拉多弗跃下了猛犸象！"
D.Strings[25967]="这是什么？！"
D.Strings[25968]="黑锋骑士团指挥官、天灾军团征服者以及暗影拱顶征服者——兰克拉尔公爵命令你束手就擒。你接不接受这份裁决？"
D.Strings[25969]="接不接受？这就是我的回答，小信差！"
D.Strings[25970]="冰斧巨魔的勇士向你发起了挑战，$n！希望你已经做好了准备！"
D.Strings[25971]="奥特兰克山谷的访客，斗兽场中迄今为止最为凶猛的斗士：血怒者科尔拉克！！！"
D.Strings[25972]="难以置信！新的痛苦斗兽场勇士诞生了！！！一群无名小卒击败了屠夫乌拉多弗！真是个奇迹！"
D.Strings[25973]="%s聚集了魔精，向前冲去！"
D.Strings[25974]="$n被逼到了绝路！"
D.Strings[25975]="如果你没别的事可做，就去杀掉这些家伙吧！"
D.Strings[25976]="谢谢你。我还以为自己死定了呢。"
D.Strings[25977]="我还以为这里将成为我的坟墓呢。"
D.Strings[25978]="让我和你一起战斗吧。"
D.Strings[25979]="我们一起对抗铁矮人吧！"
D.Strings[25980]="我能照顾自己的，$n。"
D.Strings[25981]="一旦比赛开始，就是不死不休的局面！逃跑是不可能的！"
D.Strings[25982]="%s越来越疯狂了！"
D.Strings[25983]="萨尔……酋长……部队在等待你的命令。请允许我带领他们前往诺森德，彻底铲除亡灵的威胁！"
D.Strings[25984]="啊！我受不了了！在你们反复权衡利弊的时候，我们的敌人正在逐渐壮大！如果让我来决定，我会召集一切力量登上那座冰山，为部落征服它！"
D.Strings[25985]="他犯下了这么多罪孽，你还在犹豫？MAK'GORA！"
D.Strings[25986]="这么说你打算拒绝我的请求？杜隆坦之子原来是个懦夫！"
D.Strings[25987]="萨鲁法尔，你的看法是什么？"
D.Strings[25988]="复仇的烈焰煎熬着我的灵魂，但眼前的局势迫使我们必须仔细权衡。巫妖王是个残忍的对手……我们要小心应付。"
D.Strings[25989]="我们要派斥候去查探敌情。我还要和普罗德摩尔女士会晤，看看联盟有什么打算。"
D.Strings[25990]="如果这是个陷阱，我是不会盲目踩进去的！不要犯和你父亲同样的错误，加尔鲁什！"
D.Strings[25991]="酋长，诺森德已经成为我们最大的威胁了，我们必须反击。但是巫妖王的实力不容小觑，我们绝对不能掉以轻心。"
D.Strings[25992]="酋长！天灾军团正在攻打奥格瑞玛！"
D.Strings[25993]="酋长，有何吩咐？"
D.Strings[25994]="魔精池里似乎有什么生物在骚动……"
D.Strings[25995]="你在这儿干什么？$B$B别挡我的路。我不会让你这种人干扰血色先锋军的！"
D.Strings[25996]="我要和你决斗，先锋军的混蛋！"
D.Strings[25997]="等等，等等……我投降！求求你，别打了！我这就走！"
D.Strings[25998]="哈！虔诚者埃弗雷姆又胜利了。毫无悬念！"
D.Strings[25999]="来啊，维库人的走狗。我要把你们统统打趴下！"
D.Strings[26000]="你竟敢挑战我？！别以为这样就能阻止我向巫妖王效忠！"
D.Strings[26001]="你为什么不敢面对我？你害怕虔诚者埃弗雷姆吗？"
D.Strings[26002]="我的耐心是有限的！我是来证明自己的，这就是我的目的！"
D.Strings[26003]="战斗吧，维库人，莫非你是个胆小鬼！"
D.Strings[26004]="尝尝我的铁拳吧，小鬼！"
D.Strings[26005]="显然你输了。你还指望能怎么样呢？"
D.Strings[26006]="别来打扰我。我正在研究那些“格斗者”的笨拙动作。$B$B我要将他们统统击败，然后我就会被提拔为巫妖王的部属了。"
D.Strings[26007]="我听说女性维库人根本不擅长战斗。如果你想证明我是错的，可以自己试试。"
D.Strings[26008]="你似乎能帮我赚点钱。来痛苦斗兽场转转怎么样，伙计？"
D.Strings[26009]="奥格瑞玛的狗崽子们！部落的蠢材们！聆听我的审判吧！在恐惧中颤抖吧。巫妖王的双眼已经在凝视着你们。"
D.Strings[26010]="现在你是斗兽场的勇士啦！你觉得自己能保住这个头衔吗？"
D.Strings[26011]="%s开始施放毒性新星！"
D.Strings[26012]="本单元正在忙碌。请稍后查询。"
D.Strings[26013]="在监工看见我们之前，快回去工作吧。"
D.Strings[26014]="我不是工人。我是来解救你的，你不用再在矿井里干苦力了。"
D.Strings[26015]="%s炸出了一个天灾池。"
D.Strings[26016]="又自由了？守护者米米尔的工作还没有做完。"
D.Strings[26017]="谢谢你，$r。我要和你一起反抗雷铸铁矮人。"
D.Strings[26018]="新指令：离开矿井并返回创世者的图书馆。"
D.Strings[26019]="新指令：帮忙击败铁矮人。"
D.Strings[26020]="无法计算。单元发生故障。指令：关闭。"
D.Strings[26021]="我是至高无上的土灵之王！仆从们，现身吧——快来帮助你们的君王！"
D.Strings[26022]="你无法用火焰烧毁我的王国！来吧，仆从们，我还不打算退位呢！"
D.Strings[26023]="我带起一阵足以吹倒大树的狂风！仆从们，快来帮我，他们不会得逞的！"
D.Strings[26024]="我是万恶之恶，冷血之王！过来吧，元素仆从们，让我们冰封一切，统治世界！"
D.Strings[26025]="返回风暴峭壁。"
D.Strings[26026]="孩子，你想挑战我？我可没时间陪你玩……"
D.Strings[26027]="进来！"
D.Strings[26028]="让我们尽快结束这一切吧。"
D.Strings[26029]="格罗姆之子……我们还是另找时间吧。"
D.Strings[26030]="萨鲁法尔……"
D.Strings[26031]="别在我面前摆酋长的架子。现在……来战吧！"
D.Strings[26032]="哈！杜隆坦之子，你——"
D.Strings[26033]="酋长？怎么说？能派我去诺森德吗？"
D.Strings[26034]="冻须！你在哪儿？！快来帮我！"
D.Strings[26035]="召集军队，联络地精造船商！部落要开战了！"
D.Strings[26036]="是的，萨尔。时机已经成熟，我们要杀死阿尔萨斯。带上我的大药剂师同行吧。他的知识能帮助你解决天灾军团的麻烦。"
D.Strings[26037]="太好了……真是太好了。"
D.Strings[26038]="这是我的荣幸，黑暗女王。"
D.Strings[26039]="这里是神圣的献祭之厅！你们这些入侵者的结局只有死亡！"
D.Strings[26040]="%s开始旋转，一个魔法护盾包围了他！"
D.Strings[26041]="这件霍迪尔号角的仿制品是为了纪念安格里姆国王以及所有在落雷谷之战中牺牲的巨人而造的。"
D.Strings[26042]="该死的！你不能把我当牲口一样对待！"
D.Strings[26043]="够了！我要教你学会懂礼貌！"
D.Strings[26044]="我宁愿战死，也不会为了苟活而去做奴隶！"
D.Strings[26045]="回去……工作……"
D.Strings[26046]="在你眼里，我们连牲口都不如！"
D.Strings[26047]="总有一天……我们要复仇。"
D.Strings[26048]="我不想惹麻烦，但是如果这里的情况还得不到改善，很快就会发生暴动的。"
D.Strings[26049]="海德尼尔，你们最好小心一点。只要能打扁你们那漂亮的蓝色脸蛋儿，搭上几条性命也无所谓。"
D.Strings[26050]="我警告你，如果你继续殴打我们，我们会趁你睡觉的时候杀死你。"
D.Strings[26051]="谢谢，谢谢你！总算能摆脱这些蓝皮肤的疯女人了！"
D.Strings[26052]="这个绿皮肤的小鬼根本派不上用处。不过没关系，他可以在作战前充当热身的对象。"
D.Strings[26053]="你还需要热身吗……莫非你害怕面对与你同等体型的对手？"
D.Strings[26054]="我什么都不怕——来吧！"
D.Strings[26055]="强者将获得胜利！"
D.Strings[26056]="祝你好运……你需要的就是运气了！"
D.Strings[26057]="你不配与托里姆并肩作战！"
D.Strings[26058]="打得不错啊，小家伙。我输了。我们还会再见面的。下次我一定会做好充分的准备。"
D.Strings[26059]="啊！！！！我要宰了你！"
D.Strings[26060]="你也想向巫妖王证明自己的实力吗？$B$B你不觉得这样的方式有点过时吗？非要争个你死我活吗？"
D.Strings[26061]="嘿，我认识你！我要感谢你把我送到这里。那次传送事故是我最美好的体验。$B$B如果你有机会回到北风苔原的话，告诉那个自以为是的复制品，我已经取得了相当大的成就！"
D.Strings[26062]="抱歉，丁奇。我有事要办，不能陪你。"
D.Strings[26063]="真没意思！"
D.Strings[26064]="该谁说了算啊，嗯？"
D.Strings[26065]="哟！！！"
D.Strings[26066]="出售小吃！"
D.Strings[26067]="小吃！"
D.Strings[26068]="来买点小吃吧！"
D.Strings[26069]="小吃！来买点小吃吧！"
D.Strings[26070]="爆米花！来买点爆米花吧！"
D.Strings[26071]="花生！来买点花生吧！"
D.Strings[26072]="痛苦啤酒！来买点冰镇的痛苦啤酒吧！"
D.Strings[26073]="爆米花！花生！啤酒！"
D.Strings[26074]="弗约恩的铁砧被摆放在丹尼芬雷最显然的位置，象征着他们击败弗约恩以及冰霜巨人大军的战绩。$b$b你忍不住笑了起来，你的举动竟然对世界产生了如此深远的影响。"
D.Strings[26075]="能与您并肩作战是我的荣幸，国王陛下。"
D.Strings[26076]="向雷心国王致敬！"
D.Strings[26077]="自从冰霜巨人一战后，很久没有经历过这样激烈的战事了！"
D.Strings[26078]="我们不会让敌人轻易得手的，陛下！"
D.Strings[26079]="就在今天，风暴骑士会让他们尝到恐惧的滋味！"
D.Strings[26080]="你对我们的训练是卓有成效的，陛下！"
D.Strings[26081]="再次投身激烈的战斗，这种感觉真好。"
D.Strings[26082]="国王陛下，您拥有最强大的力量——让他们见识一下吧！"
D.Strings[26083]="我不再训练死亡骑士了，我受够了那些愚蠢的新兵和他们无穷无尽的提问。$B$B现在，请你走开。"
D.Strings[26084]="检测到不明金属样本。"
D.Strings[26085]="开始分析……"
D.Strings[26086]="确认样本为萨隆邪铁与铁的合金。"
D.Strings[26087]="该样品中的矿石成分来自艾泽拉斯的地壳深处，这种矿石是最近才被挖掘出来的。"
D.Strings[26088]="该样品中萨隆邪铁的纯度非常高。在自然状态下，这种矿石是不会出现在艾泽拉斯表面的。"
D.Strings[26089]="奥努森被迄今为止最丑陋的人打败了！"
D.Strings[26090]="奥努森该离开了。你会想念我的。"
D.Strings[26091]="只有强大而邪恶的力量才能创造出这种矿石。尝试访问数据库，搜索更多信息……"
D.Strings[26092]="奥努森第一！你第二！"
D.Strings[26093]="奥努森要宰了你！"
D.Strings[26094]="奥努森来这里挑战维库人，以此提升自己的地位。$B$B然后，奥努森要在瓦哈拉斯战斗并赢得胜利，奥努森要为巫妖王效力！"
D.Strings[26095]="奥努森，我要告诉你一个坏消息。那就是，我将粉碎你的梦想！"
D.Strings[26096]="拒绝访问？！"
D.Strings[26097]="要了解更多信息，必须获取守护者洛肯的指令，然后访问奥杜尔的档案。"
D.Strings[26098]="指令完成。返回待机模式。"
D.Strings[26099]="你们当中有谁愿意献身？"
D.Strings[26100]="我将自己献给主人！"
D.Strings[26101]="你好，$n。这里是守护者米米尔的工作室。"
D.Strings[26102]="我发现了这块奇怪的护甲板。你知道这玩意儿的来历吗？"
D.Strings[26103]="我敢肯定的是：从护甲板的尺寸、厚度以及螺丝孔的位置来看，它肯定是某个巨型装置的护甲。"
D.Strings[26104]="我不能再卖啤酒给你了，$n。"
D.Strings[26105]="你已经喝得够多了，$n。我不能再卖啤酒给你了。"
D.Strings[26106]="我觉得你已经喝得够多了，$n。"
D.Strings[26107]="对不起，$n，你已经喝得够多了。"
D.Strings[26108]="对不起，$n，我们不能再卖啤酒给你了。"
D.Strings[26109]="我把塞雷布拉斯节杖弄丢了。"
D.Strings[26110]="谢谢你。我准备返回暗影拱顶了。"
D.Strings[26111]="我耽搁了太多的时间，必须返回暗影拱顶了。再见。"
D.Strings[26112]="我们还会在暗影拱顶见面的。"
D.Strings[26113]="我受够了。我要回去了。"
D.Strings[26114]="我很想留下来和你一起对抗维库人，但是我不能让男爵大人担心啊。"
D.Strings[26115]="我必须离开了。你就留在这里多杀几个丑陋的杂种吧。"
D.Strings[26116]="我该走了。别被他们抓住了，不然他们会把你煮了的！"
D.Strings[26117]="我要回去了。我会告诉男爵大人，是你救了我的性命。"
D.Strings[26118]="嘿！维库人身上有钥匙。杀了他们，拿到钥匙，把我从笼子里放出去！"
D.Strings[26119]="拿到钥匙，来到笼子面前，打开锁。"
D.Strings[26120]="你能打开笼子，放我出去吗？"
D.Strings[26121]="幸运的是，冰冷的死亡还没有真正降临。"
D.Strings[26122]="我被关在这里啊。你不会看不见的！"
D.Strings[26123]="放我出去，我们可以并肩作战啊。那将是一场光荣的杀戮！"
D.Strings[26124]="是斯利文男爵派你来救我的吗？总算盼来了救兵。快！"
D.Strings[26125]="等我离开这个牢笼，我们就要让这帮维库人尝尝厉害，让他们后悔苏醒过来！"
D.Strings[26126]="别为我担心，孩子。我一直以为岁月会侵蚀我……很高兴我想错了。别让铁矮人找到那件东西。"
D.Strings[26127]="雷铸铁矮人的暴政终于走到头了！"
D.Strings[26128]="雷铸铁矮人从残破的尸体中涌了出来！"
D.Strings[26129]="你的奴仆将再也不能攻击岩石的子嗣和他们的盟友了。"
D.Strings[26130]="我要终结你的性命，瓦杜兰！"
D.Strings[26131]="自以为是的预言家！不过谁能想到，一块岩石也能思考？"
D.Strings[26132]="如果你急于开战，我可以满足你。但是，无论你做什么，都无法阻止铁巨人的完成！"
D.Strings[26133]="我曾经拥有一切。名望、财富、一整套最棒的角斗士套装……我却亲手毁了这一切。$B$B他们发现我有舞弊行为……进行胜负交易……一切全完蛋了。$B$B如今我一无所有，只剩下这身破烂的衣衫，还有一只坏掉的肝脏。"
D.Strings[26134]="谢谢。我能帮什么忙吗？"
D.Strings[26135]="在返回暗影拱顶之前，我可以协助你作战。"
D.Strings[26136]="谢谢你，$c。我欠你一份情。"
D.Strings[26137]="好极了。我们来杀几个维库人吧！"
D.Strings[26138]="复仇的时刻到了！"
D.Strings[26139]="我的头盔呢？呃，至少他们没带走我的剑。这帮蠢货。"
D.Strings[26140]="霍迪尔之子！在此，我谦卑地奉上……"
D.Strings[26141]="霍迪尔之盔！"
D.Strings[26142]="你是谁？$B$B走开……港口的建设工作非常繁重，我已经累得筋疲力尽了。现在我要喝上两口矮人啤酒，痛痛快快地哭一场再美美地打个盹儿。"
D.Strings[26143]="座狼一路飞奔，搜索着敌人的踪迹。"
D.Strings[26144]="灵体座狼毫不犹豫地冲进了山谷。"
D.Strings[26145]="座狼在原地转悠了一会儿，然后改变了方向。"
D.Strings[26146]="在短暂的停留后，座狼继续往前追踪目标。"
D.Strings[26147]="座狼显然有所发现。它露出獠牙，循着气味前进。"
D.Strings[26148]="接近猎物时，座狼咆哮起来。"
D.Strings[26149]="冰霜座狼嗥叫着，它发现了猎物！"
D.Strings[26150]="好吧，你找到我了。那么，你去死吧！"
D.Strings[26151]="死吧，冰霜巨人的朋友！"
D.Strings[26152]="你没有机会开口说话了！"
D.Strings[26153]="我曾经拥有一个温暖的家，它就坐落在奎尔萨拉斯苍翠的森林中。我还记得我的丈夫……还有孩子们的笑容。我曾经生活在这个美好的世界。眨眼之间，巫妖王夺走了这一切。$B$B虽然单凭我的力量根本不足以与他抗衡，但是总有一天，我要让他付出三倍的代价！"
D.Strings[26154]="部落需要你！击退巫妖王的军队！"
D.Strings[26155]="我们迟早要面对巫妖王的大军。他已经威胁到了整个艾泽拉斯的安全。$B$B但是，远征诺森德的事千万不能草率。贸然闯入极寒之地是愚蠢的行径。巫妖王想必早已做好了战争的准备。$B$B我们必须谨慎行事。没错，我们的军队实力雄厚；但是如果缺乏成熟的战略计划，那么我们终将落败。$B$B要是加尔鲁什明白这一点就好了……"
D.Strings[26156]="奥格瑞玛建立以来，部落历经磨难，我们一次次地奋起抵抗，击退了那些妄图消灭我们的敌人！$B$B但是，面对眼前的危机……我却无能为力。部落的子民饱受折磨，这惨不忍睹的场景令我痛苦难安。我们必须寻求被遗忘者的帮助。$B$B总有一天，巫妖王会听见震天的战鼓声，不过现在还不是时候。在向天灾军团复仇前，我们要搭救部落的子民。"
D.Strings[26157]="真正的战士不会停止杀戮！我没功夫和你闲聊！将这些怪物送回坟墓去吧！"
D.Strings[26158]="我难以平息心中的怒火，迫不及待地想用手中的利斧劈开巫妖王的脑袋。萨尔只会说什么时机尚未成熟，让我们眼睁睁地看着天灾军团日益壮大。我不会让这种事发生的！$B$B想要解除巫妖王的威胁，就必须集结部落的全部军力，远征诺森德彻底击败他！我们的军队已经整装待发，期盼着为死于侵略的同胞复仇。$B$B反击的时刻已经到了！"
D.Strings[26159]="我原本是不信任萨尔的，直到我目睹了真相。兽人……从恶魔的堕落血液中解放出来了！他们在这片土地上站稳了脚跟，重铸氏族的荣耀。$B$B我渴望向萨尔和部落证明自己的实力。虽然我的父亲不曾与巫妖王交手，但是他已经对部落构成了致命的威胁，那就让我来面对他吧！$B$B我会请求萨尔，让我率领最优秀的战士前往诺森德，消灭巫妖王！不过眼前最重要的事情，就是根除亡灵天灾。"
D.Strings[26160]="你！为什么不参与战斗？杀死那些天灾士兵，否则他们会给奥格瑞玛带来更大的损失！"
D.Strings[26161]="我能理解加尔鲁什的心情。面对这不共戴天的仇敌，所有兽人的心中都燃起了战斗的怒火。但是，酋长反复地强调，战略计划和军队实力都是胜负的决定性因素。$B$B时机成熟时，我们一定会远征诺森德。我们不再是头脑简单，任由恶魔驱使的奴隶。这就是新生的部落。"
D.Strings[26162]="面对亡灵大军，我们无法用传统的手段“杀死”他们。我们也无法治愈巫妖王的诅咒，只能阻止其传播。被遗忘者和他们的炼金师是我们唯一的希望，尽管我很讨厌他们。$B$B如果我们能熬过这一关，我向你保证，部落一定会挥师诺森德，歼灭巫妖王和他的部队！"
D.Strings[26163]="还想活命的话，你最好小心说话。$B$B沉默？你真明智。去消灭天灾军团吧！"
D.Strings[26164]="萨尔想必对阿尔萨斯的行径倍感愤怒，但是比起我心中的怨恨来就微不足道了。如果他能体会被遗忘者的心情，我相信部落的大军会把怒火倾泻到诺森德，歼灭那片冰封荒野上的天灾军团。$B$B可惜我不是部落的领导者，不能下令开战。局势紧迫，萨尔却还在权衡利弊得失。不过，战争……已经到了一触即发的关头。"
D.Strings[26165]="我的遭遇全拜阿尔萨斯所赐。我要让他尝到被折磨的痛苦滋味。$B$B一直以来，我都盼望着被遗忘者能在诺森德与天灾军团决一死战，但是我们需要部落的支持。我们的军队数量严重不足，必须得到盟友的援助。$B$B阿尔萨斯对部落的这次进攻或许能让萨尔认清局势，最终决定对冰冠冰川宣战。那时，我会毫不犹豫地支持他。"
D.Strings[26166]="你知道我是谁吗？！我是个大人物！你应该保护我免遭天灾军团的袭击，而不是扯一些无意义的鬼话！$B$B我不是战士，而你是。出去迎敌吧！"
D.Strings[26167]="<普特雷斯用令人不安的眼神打量着你。>$B$B你不是英雄的楷模吗……$B$B你是否愿意为伟大的正义事业而献身？"
D.Strings[26168]="这简直是里程碑式的胜利！皇家炼金师协会花费了数年时间来破解巫妖王诅咒的秘密，现在总算取得了突破！$B$B虽然实验的成功堪称历史的转折点，但是还有很多东西有待研究。我要做更多的实验……挑选更多的样本……$B$B至少我不用担心浮空城。联盟会解决那个玩意儿的。这样我就有足够的时间来研究，揭示其中的奥妙。"
D.Strings[26169]="有霜脉矮人的地方就有雄鹰。在我降生之前，它们就是氏族的盟友了……如今我已不再年轻了。"
D.Strings[26170]="联盟占领了沉降之环攻城车间！"
D.Strings[26171]="联盟占领了破碎神殿攻城车间！"
D.Strings[26172]="部落占领了沉降之环攻城车间！"
D.Strings[26173]="部落占领了破碎神殿攻城车间！"
D.Strings[26174]="国王派你来接受试炼？他一定在你身上发现了某种潜质，不然也不会让你参加如此神圣的仪式。"
D.Strings[26175]="我知道你对霜脉矮人还缺乏了解，因此我会在路上为你做一些简单的介绍。"
D.Strings[26176]="很多年前，我的父亲和一些霜脉矮人行走在穿越龙骨荒野的艰难归程中。他们遇到了暴风雪……比我们见过的任何一场暴风雪都厉害。"
D.Strings[26177]="沿着雪地上的血迹，他们遇见了一位流浪的矮人。他操着一口难以理解的方言……嗯，因为他不是一般的矮人啊。这个神秘的流浪者自称是高山矮人——我们从未听说过这个氏族。"
D.Strings[26178]="高山矮人似乎迷了路，不记得自己是从哪儿来的，甚至不记得自己的名字。他们不忍心将这位表亲丢在冰天雪地里，于是收留了他，然后踏上了返回冰霜堡的旅途。"
D.Strings[26179]="走着走着，他们面前的雪地突然裂开了，一只像维拉努斯那么大的冰虫袭击了他们……其中一位伙伴还来不及反应，就被整个吞了下去。"
D.Strings[26180]="我的父亲以为大家都难逃此劫……但听背后的雪地里传来一声怒吼，他扭头看见高山矮人的体型正在增大，他的皮肤上浮现出岩石般的纹理，他的手上冒出嘶嘶作响的闪电。"
D.Strings[26181]="高山矮人带着闷雷般的吼声向前冲去，将一把闪亮的金属锤直接掷进了冰虫的喉咙，我的父亲还看见金属锤的表面环绕着闪电。"
D.Strings[26182]="那只冰虫立即倒下了，它的脑袋勉强挂在不断抽搐的躯体上。我的父亲敬畏地注视着高山矮人，举起拳头表示赞美……"
D.Strings[26183]="这位神秘的高山矮人没有名字，于是我的父亲尊称他为“约尔格”，这是传说中的勇士才能享受的称呼。很多年以后，他成为了霜脉矮人熟知的国王——约尔格·雷心。"
D.Strings[26184]="国王对我们进行了严格的训练……让我们成长为可怕的战士。如今的我们，远比当年与冰霜巨人交战时吹嘘的还要厉害。"
D.Strings[26185]="朋友，你最近还好吗？"
D.Strings[26186]="作为霜脉战士最严厉的试炼之一，就是战胜比自己高大许多的敌人，比如巨人、龙或是冰虫——由此证明体型并不是我们的弱点。"
D.Strings[26187]="接受今天的试炼吧。杀死钢铁观察者，再回来见我们，然后你就能成为倍受尊敬的霜脉战士了。"
D.Strings[26188]="重新教我切割完美宝石"
D.Strings[26189]="冬拥湖之战即将开始！"
D.Strings[26190]="钢铁观察者苏醒时，附近的建筑物嘎吱作响。"
D.Strings[26191]="钢铁观察者一锤砸下，身上的铁锈纷纷散落，它的步伐也越来越快了。"
D.Strings[26192]="铁巨人略微有些颤抖。"
D.Strings[26193]="钢铁观察者咆哮起来，更多的铁锈从古老的躯干上滑落下来。"
D.Strings[26194]="钢铁观察者捂着受伤的双眼，盲目地横冲直撞。"
D.Strings[26195]="钢铁观察者发出一声怒吼，摔倒在地。"
D.Strings[26196]="你以为我会放你进来，让你拿走风暴之心吗？"
D.Strings[26197]="哪怕你杀死了瓦杜兰，也无法阻止我铸造巨人。"
D.Strings[26198]="欢迎你，土灵的朋友和盟友。"
D.Strings[26199]="瞧，这里有一些我能用得着的东西。"
D.Strings[26200]="愿力量与你同在，$c。让天灾军团感受到百万灵魂的愤怒吧！"
D.Strings[26201]="愿荣耀与力量与你同在，$c。我以仅存的力量祝福你，愿这场噩梦早日结束！"
D.Strings[26202]="愿古老的智慧与你同在，高贵的$c。"
D.Strings[26203]="朋友，谢谢你。再见，我必须回到银色前线基地。"
D.Strings[26204]="$r，我允许你进入我们的城堡。$b$b但是，别让我们蒙羞！"
D.Strings[26205]="约库姆国王，如果您不介意的话，能不能告诉我科洛米尔的消息？"
D.Strings[26206]="我对你的信任还不够，抱歉不能将如此重要的信息透露给你。$b$b你必须尊重我们接受的考验以及我们背负的重担……$b$b如果你能为丹尼芬雷带来荣耀的话，我或许会考虑与你分享我们的知识。"
D.Strings[26207]="很好，$c。$b$b虽然你还需要付出更多努力，才能缓解我们与托里姆的关系，但是我决定将这个秘密告诉你。$b$b等你做好了解真相的准备后，再来与我谈话吧。"
D.Strings[26208]="我想知道科洛米尔的命运。"
D.Strings[26209]="这块熊腰肉都冻得发硬了……再试试吧。"
D.Strings[26210]="嗨！我不想催你的，但是铁矮人已经察觉了你和克莱特乌斯的行动……我们赶紧离开这儿吧。"
D.Strings[26211]="雷心国王听说铁矮人正朝这里挺进，于是他将眼下能召集到的最好的战士都带来了。"
D.Strings[26212]="快，克莱特乌斯在西边。雷心国王会尽量阻止铁矮人大军，但是他们在数量上占据了绝对优势。"
D.Strings[26213]="天啊，看看他战斗时的英姿。我从未见过比他更凶狠的战士……能有这样一位国王真是我的荣幸。"
D.Strings[26214]="我们会尽量阻止铁矮人大军。趁现在执行你的使命吧！"
D.Strings[26215]="嗨！$C！这些人快死啦！我需要你的帮助！"
D.Strings[26216]="别傻站着啊！北伐军需要你的帮助！"
D.Strings[26217]="你到底在干什么？没看见你周围的人危在旦夕吗！"
D.Strings[26218]="朋友，快把你下巴上的口水擦一擦，来帮我个忙！"
D.Strings[26219]="圣光啊！他们快死了！"
D.Strings[26220]="我对你卖的货物完全不感兴趣，朋友！"
D.Strings[26221]="你觉得自己能避开血腥与恐怖的场景吗？！"
D.Strings[26222]="别发呆了，拿出行动来！赶紧打起精神，帮我一把啊！"
D.Strings[26223]="等等，$r。"
D.Strings[26224]="约库姆国王，是你在召唤我吗？"
D.Strings[26225]="风暴之王，这位$r$c做出了超乎寻常的高尚行为。通过努力，$g他:她;已经成功地软化了我的子民的心。"
D.Strings[26226]="约库姆国王，安格里姆之子，我一直对自己的行为感到后悔。我压抑不住内心的伤痛，深深地伤害了身边的亲人。"
D.Strings[26227]="巫妖王对此次反击迅速做出了反应，竟然比我预想中的还要快。"
D.Strings[26228]="你要对付的有史以来最狡猾、最聪明、最凶狠的生物。"
D.Strings[26229]="巫妖王不同于已往的任何敌人，大领主。虽然你曾在圣光之愿礼拜堂打败过他，但如今，你却身处巫妖王统御下的邪恶王国中。"
D.Strings[26230]="你不可能获胜。照目前的情形，是毫无希望的……"
D.Strings[26231]="达里安，你觉得我应该怎么做？"
D.Strings[26232]="什么也不能。你的能力受到圣光的局限，在这种情况下你什么都做不了。圣光完全控制了你，将你牢牢地束缚在它所能触及的范围之内。"
D.Strings[26233]="说话小心点，死亡骑士。你身边的人都是圣光虔诚的信徒。"
D.Strings[26234]="大领主，认清眼前的局势吧。巫妖王已经彻底封锁了你的前路，占据了上风。"
D.Strings[26235]="蛛魔的巨网将迅速封印你打开的突破口。"
D.Strings[26236]="在回音谷，你的士兵成为了阻挡炮火的肉盾，帮助巫妖王的军队顺利地攻陷了你的营地。"
D.Strings[26237]="巫妖王清楚你心中的底线，大领主。他知道你是不会对自己人开火的。你还不明白吗？对他来说，不谈底线，不讲原则。"
D.Strings[26238]="我们要光明正大地战斗，达里安。不能为了胜利，做出和天灾军团一样的行径。如果我们那么做了，和怪物又有什么差别！"
D.Strings[26239]="那你就输定了，大领主。"
D.Strings[26240]="托里姆！快出来吧！"
D.Strings[26241]="%s受到了黑女巫的拥抱的影响！"
D.Strings[26242]="很久很久以前，北风独自统治着这片险峻的群山。这里还生活着一支强大的牦牛人氏族，酋长的兄弟企图争夺北风的控制权。"
D.Strings[26243]="他的名字叫做雷蹄。雷蹄纠集了一支军队，踏上了征服风暴峭壁，推翻其合法统治者——北风的征程。"
D.Strings[26244]="雷蹄在北风的王国中心策划了一场伏击战，他的阴谋差一点就得逞了。但是北风侥幸逃生，最终处死了这个牦牛人，以此惩罚他的背叛。"
D.Strings[26245]="你修复了钥匙，我对此感激不尽。我保证，你的努力将成就伟大的事业。"
D.Strings[26246]="铁矮人……到处都是……他们冲我们来了。这帮固执的家伙看来是不会放过我们的。"
D.Strings[26247]="他们想要击落飞机！我没法往上攀升……别让他们靠近我们！"
D.Strings[26248]="前面还有更多的铁矮人——坚持！"
D.Strings[26249]="我们就快脱险啦……还差一点。"
D.Strings[26250]="只要别被巨人扔下的石块砸到，我们就很安全……虽然下面已经被砸得一团糟了。"
D.Strings[26251]="他们的数量多得难以置信……好在雷心国王伸出了援手。我听说过他的许多事迹——是时候见见他了。"
D.Strings[26252]="可怜的克莱特乌斯。他是个优秀的守护者……至少他完成了自己的使命。我相信，这件事的重要性对他来说是不言而喻的。"
D.Strings[26253]="我们就快抵达冰霜堡了。如果你能在离开前把我介绍给雷心国王，我会非常感激你的。我们俩都欠他一份情。"
D.Strings[26254]="天啊……这不是……穆拉丁吗？！"
D.Strings[26255]="哥们儿，我怎么会搞错啊——肯定是你。你不认识自己的弟弟了吗？！"
D.Strings[26256]="我真不敢相信自己的眼睛！你不是死了吗？大家都这么认为……到底发生了什么事，穆拉丁。你怎么会在这里？"
D.Strings[26257]="天哪！如果麦格尼见到你，不知道他会高兴成什么样子呢！他已经很久没有听到过好消息了，这次一定能令他欣喜若狂！"
D.Strings[26258]="眼下麦格尼就在诺森德，他是来寻找你的下落的。暮冬城的先知传来消息，说你还活着。于是麦格尼立即离开铁炉堡，来这里找你了。"
D.Strings[26259]="什么？你是在和我说话吗？"
D.Strings[26260]="我的弟弟？呃……我倒是有几个兄弟……"
D.Strings[26261]="穆拉丁抓着脑袋，使劲地晃了晃，一幕幕的往事渐渐涌入他的脑海。"
D.Strings[26262]="……布莱恩？"
D.Strings[26263]="完全不对，$n。在驯风者巴兰告诉我的传说里，雷蹄是个英雄，不是暴徒。"
D.Strings[26264]="我……我不知道，布莱恩。我在这里待了很长时间……但是在此之前的记忆，只剩下支离破碎的噩梦。"
D.Strings[26265]="见到你我还是很高兴的。我真是激动得不知道说什么好了。"
D.Strings[26266]="北风是牦牛人的夙敌。它统治着元素生物，肆意践踏着牦牛人的性命。"
D.Strings[26267]="麦格尼！很抱歉啊，我的记忆恢复得很慢。"
D.Strings[26268]="他们宁愿死，也不愿意臣服于北风。这里出了差错。"
D.Strings[26269]="霜脉矮人对我很好。他们非常强壮。"
D.Strings[26270]="知识之锤……"
D.Strings[26271]="这证实了我们的怀疑。时间流的进程被切断了，历史也被篡改了。这是怎么做到的呢？"
D.Strings[26272]="风暴之王，您的$r仆人做出了超乎寻常的高尚行为。通过努力，$g他:她;已经成功地软化了我的子民的心。"
D.Strings[26273]="托里姆竟然说出过如此谦卑的言辞。我会将你的这番话转达给丹尼芬雷的。"
D.Strings[26274]="我们决定宽恕你在黑暗时代的所作所为。不会再有谁提起那些往事了。"
D.Strings[26275]="作为我们重铸友谊的见证，我就把这东西物归原主吧……"
D.Strings[26276]="我要造一辆攻城车。"
D.Strings[26277]="你好，$r。我能帮你什么忙吗？"
D.Strings[26278]="大爆炸来临时，我的父亲对锤子施放了符文，绝不能让它落入敌人之手。这是他做的最后一件事……"
D.Strings[26279]="我要造一辆投石车。"
D.Strings[26280]="托里姆，希望今后还能与你并肩作战。"
D.Strings[26281]="我必须返回丹尼芬雷了。风暴之王，我相信我们还会见面的。"
D.Strings[26282]="我要造一辆攻城坦克。"
D.Strings[26283]="请求您宽恕我为您和您的子民带来的痛苦和伤害。"
D.Strings[26284]="科洛米尔……谢谢你，约库姆。我都不敢奢望它还完好无损。很快，它将再次见证光辉的战役！"
D.Strings[26285]="我要造一架战斗机。"
D.Strings[26286]="你在想什么，孩子？"
D.Strings[26287]="对不起，朋友。只有部落的正式军官才有权购买载具。"
D.Strings[26288]="我要造一架轰炸机。"
D.Strings[26289]="我要造一架伐木机。"
D.Strings[26290]="今天，我们失去了一批优秀的战士。巫妖王要为这场血腥的杀戮付出代价！"
D.Strings[26291]="永歌森林，达尔弗斯。我至今仍然记得，在阿尔萨斯将死亡的气息散播到那片森林之前，她是多么的美丽……"
D.Strings[26292]="末日，达尔弗斯。我们还要多久才能看到天灾军团的末日呢。"
D.Strings[26293]="他们的反应为何如此之快，达尔弗斯？我们的计划几乎是天衣无缝啊。我真是想不通。"
D.Strings[26294]="伤口会愈合的，孩子。"
D.Strings[26295]="他会的，达尔弗斯……"
D.Strings[26296]="我毫不怀疑这一点，但是我们真的能活着见到那一天吗？"
D.Strings[26297]="他夺走了多少鲜活的生命……给无辜的民众带来了多少痛苦。为了什么？"
D.Strings[26298]="高贵的矮人，有的伤口是难以愈合的。破碎的灵魂要如何复原。"
D.Strings[26299]="是时候阻止洛肯的愚蠢行径了。"
D.Strings[26300]="洛肯！！！"
D.Strings[26301]="来吧，和我交战！你这没用的叛徒！"
D.Strings[26302]="很高兴再次见到你！$B$B雷心国王告诉我，说他会离开一段日子……他回忆起一些可怕的往事，决定算清这笔旧账。他坚持不让我们随行，按照惯例，我们也尊重他的决定。$B$B同时，我负责接管整个氏族。当然，你仍然是我们的贵客。"
D.Strings[26303]="托里姆，急着和你心爱的西芙做伴吗？"
D.Strings[26304]="你竟敢……"
D.Strings[26305]="拉格努斯，我一直觉得你是个人材，不过我的耐心正在逐渐消失。我知道穆拉丁在这里，但是你到底能不能带我找到他？！"
D.Strings[26306]="我的兄弟！真的是你！我几乎不敢相信自己的眼睛……你还活着！"
D.Strings[26307]="能再见到你真是太好了，穆拉丁。我听说你现在登上了王座，真的吗？铜须家族的人注定是要成为大人物的！"
D.Strings[26308]="说起来……"
D.Strings[26309]="似乎的确如此！你看上去还是那么强壮。你还记得发生了什么事吗，穆拉丁？在你离开的日子里，命运愈发糟糕了。"
D.Strings[26310]="我不太记得了，麦格尼。我经常做噩梦，梦见一个人类……很高……浅色的头发……死黑色的盔甲。他的名字……话在嘴边却说不出口……"
D.Strings[26311]="博士委托我执行关于尼尔盖德的计划，那可是完全由瓦古制成的血肉巨人！它将成为最强大的血肉巨人，只要有一整支这样的巨人组成的部队，你们就全都玩完了！"
D.Strings[26312]="……阿尔萨斯。"
D.Strings[26313]="麦格尼点了点头。"
D.Strings[26314]="他不再是你记忆中的男孩了，穆拉丁。他已经完全变了。"
D.Strings[26315]="嗯，我知道。我亲眼目睹了他的转变……我看着他抛弃正义，而我却没有伸出援手……等我意识到事情的严重性时，一切都晚了。"
D.Strings[26316]="我不会告诉你的！"
D.Strings[26317]="那已经是陈年旧事了，穆拉丁。后悔是没有用的。"
D.Strings[26318]="是的……后悔是没用的。但是我能纠正这一切……我必须这么做。我要找到那个孩子，让他为自己的所作所为负责。"
D.Strings[26319]="别浪费时间了。我什么都不会说的！"
D.Strings[26320]="你是认真的吗，穆拉丁？这些年来，我一直以为你已经死了，现在好不容易才找到你，我不想再失去你。"
D.Strings[26321]="我是认真的，麦格尼。我会小心处理的，别担心。"
D.Strings[26322]="那就这样吧。我要回去了。祝你平安。"
D.Strings[26323]="穆拉丁，保重。我很想与你同行，但是我正在发掘一个足以震惊世界的秘密。我不能半途而废。"
D.Strings[26324]="去吧，布莱恩。下次见面时，你再告诉我这个惊天动地的故事吧。再见，兄弟们。"
D.Strings[26325]="我要杀了你，再把你跺碎了加入我们正在制造的巨人里！"
D.Strings[26326]="我不会让你毁了我们的劳动成果的！尼尔盖德会把你们都干掉的！"
D.Strings[26327]="等博士回来，暗影拱顶就会变成一片废墟。"
D.Strings[26328]="尼尔盖德不过是第一个瓦古血肉巨人，我们会造出一支大军来的。到那时，你就会明白什么是真正的恐怖！"
D.Strings[26329]="别浪费我的时间！"
D.Strings[26330]="太晚了，小鬼。"
D.Strings[26331]="在公平对决的情况下，你似乎有机会战胜我。"
D.Strings[26332]="不幸的是……这场战斗并不公平！"
D.Strings[26333]="这就要感谢你的小朋友了。你离开了风暴神殿，在那里你才能发挥出全部的力量。而现在，我们战斗的地方更靠近主人的力量。"
D.Strings[26334]="救我出去，朋友！"
D.Strings[26335]="谢谢你，朋友。但是我们还没有彻底摆脱危险！"
D.Strings[26336]="我们快离开这儿吧！赶快！"
D.Strings[26337]="直呼……"
D.Strings[26338]="她的名讳！！"
D.Strings[26339]="在这儿！我在被摧毁的天灾车上面！救命！"
D.Strings[26340]="你是冲着博士的计划来的！你只有死路一条！"
D.Strings[26341]="当你跳上尼尔盖德时，构造体上腐烂的血肉突然活了起来。"
D.Strings[26342]="他们正在策划一场大袭击！我们必须去警告大领主弗丁！"
D.Strings[26343]="快一点，勇士！我们必须赶回银色前线基地，把进攻的事告诉他们！"
D.Strings[26344]="他们有几百人！甚至可能有几千人！他们随时可能发动进攻！我敢肯定！"
D.Strings[26345]="如果你不来的话，我就死定了！"
D.Strings[26346]="我……我看见巫妖王了。他很快就消失了，但是他确实来过这里……接着温度骤降，变得非常……非常寒冷。"
D.Strings[26347]="凡人，我会考虑饶恕你的性命的。毕竟……我为什么要杀掉最得力的仆从啊？我在海德尼尔矿洞里等了你好几周呢。"
D.Strings[26348]="奴隶们！把我的兄弟和他的飞龙送去他们的新家吧。别伤了那头畜生的性命。我还有个针对她的特别计划呢。"
D.Strings[26349]="……再见，我的兄弟。"
D.Strings[26350]="你只能在银色前线基地、回音谷和天灾城飞翔。"
D.Strings[26351]="%s碎裂开来。"
D.Strings[26352]="这当然不是我的真实相貌。如果你不是那么卤莽的话，你早就看见我过去的幻影了。但是你毕竟帮助我渡过了难关……我必须谢谢你！"
D.Strings[26353]="谁敢？！就算要牺牲尼尔盖德，我也会抓到你，将你的肉一片片地割下来！"
D.Strings[26354]="救命！我被网裹住了，动弹不得！"
D.Strings[26355]="我在这儿！躺在地上！救命！"
D.Strings[26356]="别丢下我们！"
D.Strings[26357]="救救我们！"
D.Strings[26358]="小心！巫妖王就在附近！"
D.Strings[26359]="他们会杀了我们的！"
D.Strings[26360]="我们完了！"
D.Strings[26361]="为了银色北伐军！"
D.Strings[26362]="嗯，那是什么？"
D.Strings[26363]="雪花落到我的眼睛里了……"
D.Strings[26364]="你说什么？"
D.Strings[26365]="嗯嗯……我们说到哪儿了？"
D.Strings[26366]="啊……总算可以休息一下啦。"
D.Strings[26367]="哦，你好，小$r。"
D.Strings[26368]="你不是牦牛人。你为什么闯入我族战士的埋骨圣地？"
D.Strings[26369]="很抱歉打扰到你，酋长。但是，你的兄弟的灵魂可能遇到了危险。你能把关于他的回忆告诉我吗？"
D.Strings[26370]="我的兄弟雷蹄，是一位比我更出色的战士。在我接受继任氏族酋长的训练时，他正在为一项重要的任务做准备。"
D.Strings[26371]="他怎么会有危险呢？他只是想让我们获得力量，控制那些令我们难以安生的元素生物。"
D.Strings[26372]="他要去找一件神器……一只号角。他离开了村子，踏上了寻找它的漫漫长途。"
D.Strings[26373]="在他夺得号角之后，有个可怕的敌人追上了他……但是，我不记得……后来发生了什么。"
D.Strings[26374]="我的记忆似乎被一层迷雾笼罩了。我甚至不记得我的兄弟后来出了什么事。这就是你所说的危险吗？"
D.Strings[26375]="坟墓在骚动，他们一定被卷进来了。看看你的四周，$n。你看见他们了吗？"
D.Strings[26376]="是的，情况不妙，但是我无力阻止他们。你能向唐卡洛营地发出警告吗，陌生人？告诉他们，历史和他们的祖先正在危险之中。"
D.Strings[26377]="%s落到巢中，发出一声怒吼。"
D.Strings[26378]="小心下面！"
D.Strings[26379]="放松点！不认识你的旧主子了吗？"
D.Strings[26380]="我会在风暴神殿等你。看来我得再降服她一次了。"
D.Strings[26381]="引擎发动了！扎克的飞行器即将返回K3！"
D.Strings[26382]="看看他们……他们一心只想超过别人。"
D.Strings[26383]="让我听听你的提议。"
D.Strings[26384]="你看，托里姆和这些鹰身人不同。他是近乎神的存在。$B$B他为泰坦们守护着奥杜尔和造物者圣台。$B$B直到他的妻子西芙被他的兄弟可鄙地杀害了。"
D.Strings[26385]="托里姆失去了理智。他将矛头指向了他的亲密战友，冰霜巨人。$B$B这导致了海德尼尔和霍迪尔之子至今仍在这片土地上互相攻伐……托里姆也因此离开了风暴神殿。"
D.Strings[26386]="你想让我参加海德比武会并结束战争吗？"
D.Strings[26387]="就算这些母狼和冰霜巨人天天对砍，那也不关我的事。$B$B不，不……我是想让托里姆振作起来，召集起所有的盟友夺回奥杜尔。$B$B如果他失败了，这个世界就会破碎的！$B$B当然了，我会支付给你足够的报酬的。"
D.Strings[26388]="很好。我愿意参加这个比赛。"
D.Strings[26389]="知识之锤有反应。这件古器肯定来自雷蹄的时代。"
D.Strings[26390]="知识之锤没有反应。这件古器不属于雷蹄的时代。"
D.Strings[26391]="我会东山再起的，到时候我会报仇的！"
D.Strings[26392]="让我独自反省吧，$r。"
D.Strings[26393]="男人——很难与他们相处，但是又离不开他们。好吧，也不是离不了……不过那样真的很无聊。"
D.Strings[26394]="这些矿洞真是太可怕了。幸好我不打算在这里待很长时间。"
D.Strings[26395]="熊是美丽的生物。野性、强壮、凶猛……就像我们一样。"
D.Strings[26396]="对不起，朋友。我们手头的零件好象都用完了。"
D.Strings[26397]="蠢货！你赢不了我的！"
D.Strings[26398]="我不会让你用元素愤怒号角来对付我们的！去死吧，懦夫！"
D.Strings[26399]="大人，教官霍加尔禀告说战士们都准备好了。他们正在外面的平台上等候您的命令。"
D.Strings[26400]="号角！趁它进入虚弱状态吹响号角！"
D.Strings[26401]="强大的乌弗朗领主，有个坏消息要告诉你。东边的暗影拱顶沦陷了。"
D.Strings[26402]="乌弗朗领主，平台上来了一些陌生人，要求与您的战士进行公平决斗。他们都不是维库人。"
D.Strings[26403]="大人，这个德莱尼人是和一整队来自暗影拱顶的死亡骑士一起被抓的。他们来自黑锋骑士团！"
D.Strings[26404]="大人，有消息说，其他领主准备发兵进攻我们。我们必须赶快行动了。"
D.Strings[26405]="领主大人，我带来了最终的消息。您的勇士贝索德，已经在瓦哈拉斯阵亡了。作为一名瓦古，他已经被放逐到地下大厅去了。"
D.Strings[26406]="告诉霍加尔，当我发出进攻的命令时，他要充当我的先锋。"
D.Strings[26407]="谁在叫我……？"
D.Strings[26408]="那你必须派人给巫妖王送个消息。就说我的军队已经整装待发，就等他一声令下了。"
D.Strings[26409]="让他们打吧。如果他们败给低等种族，那也是注定的，说明他们毫无价值。"
D.Strings[26410]="把他锁在那里。等我有空的时候自然会去处理他的。至于其他人……别让他们跑了！"
D.Strings[26411]="那就把我们的人都召集起来。一定要保证我们能在他们行动前得到消息。我倒要看看到底是谁先发动进攻！"
D.Strings[26412]="不！那个号角是我的！"
D.Strings[26413]="贝索德是个伟大的战士，但显然他还不够强大。为我找一个新勇士吧。我们不能忍受这种耻辱！"
D.Strings[26414]="这将是你最后一次和天灾军团作对了！"
D.Strings[26415]="当%s倒下时，平台上的祭坛开始发出微弱的光芒。"
D.Strings[26416]="喂，喂！"
D.Strings[26417]="你好，伙计——很高兴有你陪在我身边！"
D.Strings[26418]="这片山脉的历史非常悠久……你要随时停下脚步来倾听，$c。"
D.Strings[26419]="你获得了7500点荣誉和150点竞技场点数。"
D.Strings[26420]="<霜脉斥候咽下了最后一口气。>"
D.Strings[26421]="我们在龙骨荒野的青铜巨龙圣地发现了这些始祖幼龙。我们立即意识到这是我们的同胞——他们是我们的远古血亲。$B$B很抱歉，$c。我把你说糊涂了吧。我是青铜巨龙圣地的本诺比奥斯。为了方便行事，我变化成了现在的形态。用凡人的形态可以更好地和凡人进行交流，共同生活。$B$B我能帮你什么忙吗？"
D.Strings[26422]="贝索德的剑？！！太好了，$r，我接受你的挑战。但首先，你必须打败我的勇士们。沃尔格！给我碾碎这只爬虫！"
D.Strings[26423]="当第一个勇士倒下时，领主吐了口唾沫。"
D.Strings[26424]="布莉塔，去把这个卑微的$c打成筛子！"
D.Strings[26425]="你或许可以打败我的勇士们，$c。但我和他们是完全不同的。"
D.Strings[26426]="赶快向你们的诸神祈祷，企求速死吧。"
D.Strings[26427]="你好，$n！今天你想要点什么？"
D.Strings[26428]="伊尔斯卡领主，你接受了公平决斗的挑战，并且输了。"
D.Strings[26429]="你显然还有所欠缺，并将受到制裁。站起来吧，被诅咒的伊尔斯卡领主！"
D.Strings[26430]="说吧，$c。"
D.Strings[26431]="长久以来，我一直不明白自己的命运。我的使命从未像现在这样清晰过。$B$B我必须亲手解决洛肯。"
D.Strings[26432]="你能把西芙的事告诉我吗？"
D.Strings[26433]="刚才那一瞬间，我把你当成了我亲爱的西芙……那一缕头发……不！那不可能……西芙已经死了……$B$B我……我的兄弟……杀了她！"
D.Strings[26434]="他罪行还不止于此，托里姆。他现在控制了奥杜尔。"
D.Strings[26435]="奥杜尔……我曾经发誓要守护奥杜尔。$B$B发誓要守护造物者圣台。$B$B发誓要守护与冰霜巨人之间的盟誓。$B$B可是我都没有做到！我被我的兄弟欺骗了。他诱使我将矛头指向我的朋友。他骗我说是我亲密的朋友，冰霜巨人之王安格里姆害死了西芙。$B$B当我意识到自己做了什么时……我……陷入了绝望。"
D.Strings[26436]="事情或许还有挽回的余地啊。"
D.Strings[26437]="你是谁，小家伙！竟然对强大的托里姆说这些话……$B$B我应该……撕碎你！$B$B但是你将我从昏迷中唤醒了。你的来到是一个预兆！$B$B我把你错当成西芙，这并不是巧合。她会怎么看我呢？我必须准备战斗了。$B$B我一定要为她报仇，把泰坦的圣地从我那个疯狂的兄弟手中解放出来！"
D.Strings[26438]="我会帮助你的，托里姆。"
D.Strings[26439]="随着%s最后的残骸渗入地下，附近的祭坛开始散发出微弱的光芒。"
D.Strings[26440]="不！！！！"
D.Strings[26441]="欢迎来到风暴峭壁，$r。"
D.Strings[26442]="……zzz……过来……马龙……zzz……"
D.Strings[26443]="……呃……谁敢……捣蛋……zzzz……教训……他们……"
D.Strings[26444]="西北方的塔楼遭到破坏！"
D.Strings[26445]="西南方的塔楼遭到破坏！"
D.Strings[26446]="东南方的塔楼遭到破坏！"
D.Strings[26447]="东北方的塔楼遭到破坏！"
D.Strings[26448]="东北方的塔楼被摧毁了！"
D.Strings[26449]="东南方的塔楼被摧毁了！"
D.Strings[26450]="西南方的塔楼被摧毁了！"
D.Strings[26451]="西北方的塔楼被摧毁了！"
D.Strings[26452]="西边的桥梁遭到破坏！"
D.Strings[26453]="南边的桥梁遭到破坏！"
D.Strings[26454]="东边的桥梁遭到破坏！"
D.Strings[26455]="东边的桥梁被摧毁了！"
D.Strings[26456]="南边的桥梁被摧毁了！"
D.Strings[26457]="西边的桥梁被摧毁了！"
D.Strings[26458]="东边的哨塔遭到破坏！"
D.Strings[26459]="南边的哨塔遭到破坏！"
D.Strings[26460]="西边的哨塔遭到破坏！"
D.Strings[26461]="西边的哨塔被摧毁了！"
D.Strings[26462]="南边的哨塔被摧毁了！"
D.Strings[26463]="东边的哨塔被摧毁了！"
D.Strings[26464]="雷吼长者在哪里？"
D.Strings[26465]="雷吼长者在北风苔原的仁德会营地。"
D.Strings[26466]="长者帕姆亚就在战歌要塞外面。"
D.Strings[26467]="长者帕姆亚在哪里？"
D.Strings[26468]="毫无疑问，有东西在干扰雷蹄和唐卡洛战士的真实历史。这究竟是怎么回事呢？"
D.Strings[26469]="别自找麻烦了。无论是雷蹄，还是你和你的盟友，谁都不能阻止我。"
D.Strings[26470]="我的力量在不断增长。我期待已久的复仇之日总算来临了。"
D.Strings[26471]="雷蹄和他的同胞的历史将被抹去，这片土地将回到真正的主人手中！"
D.Strings[26472]="不！真实的历史不容亵渎。我们将恢复被你摧毁的一切！"
D.Strings[26473]="$n，我们必须尽快确定北风是从什么时候开始篡改时间流的。然后我们才有可能打败他并纠正历史。"
D.Strings[26474]="长者伊加苏在哪里？"
D.Strings[26475]="人们最后一次看见长者伊加苏时，他正在探索魔枢。"
D.Strings[26476]="长者诺塔尔在哪里？"
D.Strings[26477]="你可以到考达拉的永生之盾去找长者诺塔尔。"
D.Strings[26478]="长者萨迪斯在哪里？"
D.Strings[26479]="我最后一次听到长者萨迪斯的消息时，他正要前往无畏要塞。"
D.Strings[26480]="蓝狼长者在哪里？"
D.Strings[26481]="蓝狼长者正在参加冬拥湖的战斗。"
D.Strings[26482]="长者瓦尼卡在哪里？"
D.Strings[26483]="长者瓦尼卡在索拉查盆地的雨声河。"
D.Strings[26484]="长者杉德雷在哪里？"
D.Strings[26485]="长者杉德雷到索拉查盆地的湖边着陆场去了。"
D.Strings[26486]="长者墨尔希在哪里？"
D.Strings[26487]="你可以到龙骨荒野的群星之墓去找长者墨尔希。"
D.Strings[26488]="长者索伊姆在哪里？"
D.Strings[26489]="长者索伊姆已经在龙骨荒野的莫亚基港口住了很多年了。"
D.Strings[26490]="天守长者在哪里？"
D.Strings[26491]="天守长者就在龙骨荒野的阿格玛之锤附近。"
D.Strings[26492]="长者努尔根在哪里？"
D.Strings[26493]="根据我最后得到的消息，长者努尔根在艾卓-尼鲁布。"
D.Strings[26494]="长者伍雷恩在哪里？"
D.Strings[26495]="长者伍雷恩在灰熊丘陵的欧尼瓦营地。"
D.Strings[26496]="长者库甘达加在哪里？"
D.Strings[26497]="长者库甘达加在乌特加德之巅。"
D.Strings[26498]="长者卢纳罗在哪里？"
D.Strings[26499]="长者卢纳罗在灰熊丘陵的特塞斯废墟。"
D.Strings[26500]="长者贝尔达在哪里？"
D.Strings[26501]="长者贝尔达在灰熊丘陵的月溪旅营地。"
D.Strings[26502]="长者亚尔特恩在哪里？"
D.Strings[26503]="你能在乌特加德城堡找到长者亚尔特恩。"
D.Strings[26504]="长者基里亚斯在达克萨隆要塞里。"
D.Strings[26505]="长者陶鲁斯在哪里？"
D.Strings[26506]="长者陶鲁斯到祖达克的希姆托加去了。"
D.Strings[26507]="长者奥哈齐在哪里？"
D.Strings[26508]="长者奥哈齐在古达克。"
D.Strings[26509]="灰鬃长者在哪里？"
D.Strings[26510]="最后一次有人看见灰鬃长者时，他在风暴峭壁的K3。"
D.Strings[26511]="长者穆拉克在哪里？"
D.Strings[26512]="长者穆拉克就在风暴峭壁的唐卡洛营地外面。"
D.Strings[26513]="长者法迦尔在哪里？"
D.Strings[26514]="长者法迦尔在风暴峭壁的冰霜堡。"
D.Strings[26515]="石须长者在哪里？"
D.Strings[26516]="石须长者住在风暴峭壁的布德克拉格庇护所。"
D.Strings[26517]="长者尤拉克在哪里？"
D.Strings[26518]="长者尤拉克在岩石大厅里。"
D.Strings[26519]="Mrfrrmrfrmrrr！$B$B<恶鬼清了清喉咙。>$B$B嗯？"
D.Strings[26520]="你还不够强壮，不足以参加远古海滩的战斗。等你经验更丰富一些的时候再来找我吧。"
D.Strings[26521]="我们不能让部落利用远古海滩的秘密来对付我们。你愿意帮助我们在那里战斗的勇士吗？"
D.Strings[26522]="我们不能让联盟利用远古海滩的秘密来对付我们。你愿意帮助我们在那里战斗的勇士吗？"
D.Strings[26523]="你即将离开尤顿海姆区域。立即返回，否则始祖幼龙会将你掀下背。"
D.Strings[26524]="沙德隆，帮帮我！一切都危在旦夕！"
D.Strings[26525]="塔尼布隆！你也有保护龙卵的责任！"
D.Strings[26526]="维斯匹隆，情况危急！快来帮助我！"
D.Strings[26527]="%s在注视你！"
D.Strings[26528]="嘿！别在我的酒窖里捣乱！走开！"
D.Strings[26529]="你在我的酒窖里干了什么？之前发生了食物中毒事件，我最讨厌陌生人乱翻我的货物！滚开！"
D.Strings[26530]="这件事太可疑了，你觉得呢？"
D.Strings[26531]="命令就是命令。如果王子要我跳……"
D.Strings[26532]="奇怪的命令，你无法否认这一点。可疑食物？凭这一点，你就应该逮捕贝法斯！"
D.Strings[26533]="我听见了！我不卖啤酒给你了！一滴也不卖！"
D.Strings[26534]="自由啦……呱呱。呱呱……没有找到……我们！逃跑！"
D.Strings[26535]="欢迎醒来，孩子。"
D.Strings[26536]="我……就是……无尽的愤怒！"
D.Strings[26537]="不要丧失信仰。"
D.Strings[26538]="天灾军团的末日即将降临。"
D.Strings[26539]="银色北伐军的时代已经来临！"
D.Strings[26540]="胜利属于我们！"
D.Strings[26541]="信仰圣光吧，一切都可能实现！"
D.Strings[26542]="快去干活！现在是时候实施我们的越狱计划了。"
D.Strings[26543]="魔鬼，接招！你休想逃过灰烬使者的怒火！"
D.Strings[26544]="我获得了……新生。"
D.Strings[26545]="理发师"
D.Strings[26546]="这……就是失败的……代价……"
D.Strings[26547]="缝合场是天灾军团制造食尸鬼、憎恶和血肉巨人的中心。如果我们能摧毁这座工厂，巫妖王的力量就会被大大削弱。"
D.Strings[26548]="岁月的侵蚀令他变得行动迟缓……你只要保持身手敏捷，他是不可能战胜你的。雷心国王在默默地支持你——别让他失望。"
D.Strings[26549]="这真是最好的试炼，阿尔萨斯王子殿下。"
D.Strings[26550]="时间到。"
D.Strings[26551]="你似乎很累了。"
D.Strings[26552]="黑暗之王对你的介入很不高兴。"
D.Strings[26553]="我要的是阿尔萨斯王子，不是你！"
D.Strings[26554]="快把塔楼和城墙修好！别让敌人冲进来了！"
D.Strings[26555]="啊！诅咒你，玛尔加尼斯！父王……吉安娜……我令洛丹伦失望了……"
D.Strings[26556]="保护你们的王子，洛丹伦的士兵们，我需要帮助！"
D.Strings[26557]="我要顶不住了！帮帮我！"
D.Strings[26558]="玛尔加尼斯必将为此付出代价。"
D.Strings[26559]="我不能放过你。"
D.Strings[26560]="又少了一个障碍。"
D.Strings[26561]="我在做饭呢！"
D.Strings[26562]="又一个饥饿的新兵？"
D.Strings[26563]="你给我带什么来了？"
D.Strings[26564]="我要温习诺森德炖肉的做法。"
D.Strings[26565]="%s周围的岩浆沸腾了起来！"
D.Strings[26566]="这些小虫太容易燃烧起来了……"
D.Strings[26567]="立刻返回尤顿海姆。你感到白骨女巫的法术正在减弱！"
D.Strings[26568]="我们是托里姆的仆人。"
D.Strings[26569]="银色火炮准备就绪！净化这片土地上的罪恶吧！"
D.Strings[26570]="你们这可笑的骚扰到此为止了！"
D.Strings[26571]="能在这片被遗弃的土地上见到你这样的英雄，真是令人愉快。我能帮你什么忙吗？"
D.Strings[26572]="你好，法师。你愿意领略高深莫测的魔法世界吗？"
D.Strings[26573]="很高兴见到你，大德鲁伊。我奉提里奥之命执行一项重要的使命，时间紧迫。你能送我去月光林地吗？"
D.Strings[26574]="当然可以！愿艾露恩祝福你。"
D.Strings[26575]="单炮连射！"
D.Strings[26576]="偶数号的大炮开火！"
D.Strings[26577]="奇数号的大炮开火！"
D.Strings[26578]="全体开火！"
D.Strings[26579]="弹幕齐射！"
D.Strings[26580]="嗨。我无意中听到了你们的谈话。请让我出一份力吧。"
D.Strings[26581]="我正打算从达拉然返回银色前线基地。英雄，你愿意与我同行吗？"
D.Strings[26582]="朋友，今天是巨魔历史上黑暗的一天。"
D.Strings[26583]="太可怕了。我连看都不敢看。"
D.Strings[26584]="没有你的帮助，我们很难取得胜利。"
D.Strings[26585]="瞧，前线基地的英雄！"
D.Strings[26586]="有了你的坚定与果断，我们一定能取得胜利！"
D.Strings[26587]="谢谢，$n。衷心地感谢你。"
D.Strings[26588]="随时为你效劳，$n。"
D.Strings[26589]="我愿与你并肩作战，直到最后一刻！"
D.Strings[26590]="尊贵的英雄。"
D.Strings[26591]="为了后世的幸福，我有责任记录下这些悲剧。"
D.Strings[26592]="我们不能放松警惕。在这种时候，一次小小的失利就可能令我们置身于危险中。唉，这种高度紧张的气氛下，士兵们真的需要喘口气了。$B$B享受胜利吧，$n。如果没有你，我们可能已经失去前线基地了。"
D.Strings[26593]="朋友，如果你迷了路，我或许能帮上忙。你要去哪儿？"
D.Strings[26594]="这座城市的确有些古怪。我能帮你什么忙吗？"
D.Strings[26595]="警告：禁止将载具开出冬拥湖。请立即返回。"
D.Strings[26596]="龙群卫士报告！"
D.Strings[26597]="圣殿卫士报告！"
D.Strings[26598]="总算盼来了援军！面对如此大规模的入侵，监狱守卫是坚持不了多久的！请你前去增援我的士兵，尽量为我们争取时间吧。防御系统的能量尚未用尽。如果情况危急的话，务必要激活监狱周围的水晶发射能量波。"
D.Strings[26599]="我的职责是保护这些龙卵。在伤害到它们之前，你们就会被我的龙息烧成灰烬！"
D.Strings[26600]="遇到麻烦时就激活水晶。"
D.Strings[26601]="%s开始召唤暮光传送门！"
D.Strings[26602]="联盟守住了冬拥堡垒！"
D.Strings[26603]="你是不是衰老得连基本的算术都不会了。你难道没看出来，建筑物的设计思路根本就有问题吗？照你的方案，它肯定会倒塌！"
D.Strings[26604]="部落守住了冬拥堡垒！"
D.Strings[26605]="你说什么！我是这里的总设计师，设计图由我来最终拍板！如果你对此有所置疑的话，尽管向弗丁大领主投诉好了。我要去工作了，恕不奉陪！"
